-- §0.4 THE SHARED HELPERS ──────────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* sha256 hex over a jsonb value's canonical text. */
CREATE OR REPLACE FUNCTION governance.digest(p jsonb) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $$ SELECT encode(sha256(convert_to(coalesce(p, 'null'::jsonb)::text, 'UTF8')), 'hex') $$;
GRANT EXECUTE ON FUNCTION governance.digest(jsonb) TO eye_app, eye_commit;

/* A vendor-side (PLATFORM) governance write: the route's action, PLATFORM scope, the act recorded under the acting principal. */
CREATE OR REPLACE FUNCTION governance.assert_platform(p_action text, p_actor uuid, p_noun text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
BEGIN
  PERFORM observation.assert_authority(ARRAY[p_action]);
  IF public.eye_scope() IS DISTINCT FROM 'PLATFORM' THEN
    RAISE EXCEPTION '% rejected (authority): product-governance registries are the vendor''s (PLATFORM scope)', p_noun USING ERRCODE = '42501';
  END IF;
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN
    RAISE EXCEPTION '% rejected (actor): the act is recorded under the acting principal', p_noun USING ERRCODE = '42501';
  END IF;
END $$;
REVOKE ALL ON FUNCTION governance.assert_platform(text, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.assert_platform(text, uuid, text) TO eye_commit;

/* Does the principal hold (live) one of the roles at a scope that covers the subject: a PLATFORM binding covers everything; a TENANT binding
   its tenant; a DOMAIN binding its domain. */
CREATE OR REPLACE FUNCTION governance.holds_role(p_principal uuid, p_tenant uuid, p_domain uuid, p_roles text[]) RETURNS boolean
STABLE SECURITY DEFINER SET search_path = identity, pg_catalog, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM identity.role_bindings b JOIN identity.principals p ON p.id = b.principal_id
                  WHERE b.principal_id = p_principal AND p.status = 'active' AND b.revoked_at IS NULL AND b.role_code = ANY (p_roles)
                    AND (b.scope = 'PLATFORM'
                         OR (b.scope = 'TENANT' AND p_tenant IS NOT NULL AND b.tenant_id = p_tenant)
                         OR (b.scope = 'DOMAIN' AND p_domain IS NOT NULL AND b.domain_id = p_domain)))
$$ LANGUAGE sql;
REVOKE ALL ON FUNCTION governance.holds_role(uuid, uuid, uuid, text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.holds_role(uuid, uuid, uuid, text[]) TO eye_commit;

/* THE APPROVER TEST (B94's, generalised — re-checked in every approving, accepting, attesting and signing port): a named ACTIVE HUMAN holding
   one of p_roles at a covering scope; never the PROPOSER; never the BUILDER of the subject (the principal(s) declared as having produced
   it); never an AGENT. Refusals in the class form: (actor) · (authority) · (separation_of_duties). */
CREATE OR REPLACE FUNCTION governance.assert_approver(p_noun text, p_actor uuid, p_tenant uuid, p_domain uuid, p_roles text[], p_proposer uuid, p_builders uuid[], p_what text) RETURNS void
LANGUAGE plpgsql STABLE SET search_path = governance, onboarding, pg_catalog, pg_temp AS $$
BEGIN
  IF onboarding.principal_kind(p_actor) IS DISTINCT FROM 'human' THEN
    RAISE EXCEPTION '% rejected (actor): % is a named human''s act; an agent or a system never approves, accepts or attests (it may draft evidence and proposals only)', p_noun, p_what USING ERRCODE = '42501';
  END IF;
  IF NOT governance.holds_role(p_actor, p_tenant, p_domain, p_roles) THEN
    RAISE EXCEPTION '% rejected (authority): % is the act of a %', p_noun, p_what, array_to_string(p_roles, ' or ') USING ERRCODE = '42501';
  END IF;
  IF p_proposer IS NOT NULL AND p_actor = p_proposer THEN
    RAISE EXCEPTION '% rejected (separation_of_duties): % is never done by its proposer (no self-acceptance)', p_noun, p_what USING ERRCODE = '42501';
  END IF;
  IF p_builders IS NOT NULL AND p_actor = ANY (p_builders) THEN
    RAISE EXCEPTION '% rejected (separation_of_duties): % is never done by a builder of the subject (independence)', p_noun, p_what USING ERRCODE = '42501';
  END IF;
END $$;
GRANT EXECUTE ON FUNCTION governance.assert_approver(text, uuid, uuid, uuid, text[], uuid, uuid[], text) TO eye_commit;

-- §0.5 THE LEDGER (append-only; every part's ports write it) ───────────────────────────────────────────────────────────────────────────────
CREATE TABLE governance.events (
  event_id           uuid PRIMARY KEY,
  scope              text NOT NULL CHECK (scope IN ('PLATFORM', 'TENANT', 'DOMAIN')),
  tenant_id          uuid,
  domain_id          uuid,
  subject_kind       text NOT NULL CHECK (subject_kind ~ '^[a-z][a-z_]{2,40}$'),
  subject_id         uuid NOT NULL,
  version            int,
  event              text NOT NULL CHECK (event ~ '^[a-z_]+\.[a-z_.]+$'),
  actor_principal_id uuid NOT NULL,
  details            jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(details) = 'object'),
  occurred_at        timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id     uuid NOT NULL,
  CONSTRAINT gev_scope CHECK ((scope = 'PLATFORM' AND tenant_id IS NULL AND domain_id IS NULL) OR (scope = 'TENANT' AND tenant_id IS NOT NULL AND domain_id IS NULL)
                              OR (scope = 'DOMAIN' AND tenant_id IS NOT NULL AND domain_id IS NOT NULL))
);
CREATE INDEX gev_subject ON governance.events (subject_id, occurred_at);
CREATE TRIGGER gev_append_only BEFORE UPDATE OR DELETE ON governance.events FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

CREATE OR REPLACE FUNCTION governance.ledger(p_tenant uuid, p_domain uuid, p_subject_kind text, p_subject_id uuid, p_version int, p_event text, p_actor uuid, p_details jsonb, p_correlation uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v uuid := gen_random_uuid();
BEGIN
  INSERT INTO governance.events (event_id, scope, tenant_id, domain_id, subject_kind, subject_id, version, event, actor_principal_id, details, correlation_id)
  VALUES (v, CASE WHEN p_domain IS NOT NULL THEN 'DOMAIN' WHEN p_tenant IS NOT NULL THEN 'TENANT' ELSE 'PLATFORM' END, p_tenant, p_domain, p_subject_kind, p_subject_id, p_version, p_event, p_actor,
          coalesce(p_details, '{}'::jsonb), p_correlation);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.ledger(uuid, uuid, text, uuid, int, text, uuid, jsonb, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ledger(uuid, uuid, text, uuid, int, text, uuid, jsonb, uuid) TO eye_commit;

-- §0.6 THE SHARED CORE (its ports are the parts') ─────────────────────────────────────────────────────────────────────────────────────────
/* THE ARTIFACT KINDS and THE LINK RELATIONS (closed lists; a part that needs another kind asks the integrator). */
CREATE OR REPLACE FUNCTION governance.artifact_kinds() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'requirement', 'capability', 'journey', 'component', 'deployable_unit', 'interface', 'schema', 'policy_bundle', 'test', 'fixture', 'evidence',
  'release_candidate', 'decision_record', 'standard', 'design_asset', 'design_component', 'pattern', 'principle', 'exception', 'acceptance_record',
  'data_product', 'data_authority', 'domain', 'change_proposal', 'conflict', 'baseline', 'stewardship_case', 'manifest', 'feature', 'role'] $$;
CREATE OR REPLACE FUNCTION governance.link_relations() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'implements', 'verifies', 'depends_on', 'derives_from', 'cites', 'owned_by', 'supersedes', 'covers', 'accepted_in', 'excepts', 'deploys',
  'consumes', 'maps_to', 'evidences', 'conflicts_with', 'contributes_to', 'governs', 'part_of'] $$;
GRANT EXECUTE ON FUNCTION governance.artifact_kinds(), governance.link_relations() TO eye_app, eye_commit;

/* THE ARTIFACTS: one identity per governed thing. PLATFORM rows are the vendor's product registries (requirements, capabilities, components,
   manifests, the design system, exceptions …); TENANT/DOMAIN rows are a customer's (an acceptance record of a domain, a stewardship case …).
   One CURRENT version per (kind, external_key, scope owner); a change is a new version (superseded_at stamped). Each part registers its
   primary objects here (artifact_id = the object's id) so the others read them by kind and through the links — never by each other's tables. */
CREATE TABLE governance.artifacts (
  artifact_id        uuid NOT NULL,
  version            int  NOT NULL CHECK (version >= 1),
  scope              text NOT NULL CHECK (scope IN ('PLATFORM', 'TENANT', 'DOMAIN')),
  tenant_id          uuid,
  domain_id          uuid,
  kind               text NOT NULL CHECK (kind = ANY (governance.artifact_kinds())),
  external_key       text NOT NULL CHECK (length(btrim(external_key)) BETWEEN 1 AND 200),
  title              text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 500),
  owner_principal_id uuid,
  owner_role         text REFERENCES identity.roles (code),
  authority_class    text,
  controlling_volume text,
  lifecycle          text NOT NULL DEFAULT 'active' CHECK (lifecycle IN ('proposed', 'active', 'deprecated', 'retired', 'superseded', 'quarantined')),
  attributes         jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(attributes) = 'object'),
  source             jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(source) = 'object'),
  digest             text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  effective_from     timestamptz NOT NULL DEFAULT clock_timestamp(),
  superseded_at      timestamptz,
  recorded_by        uuid NOT NULL,
  correlation_id     uuid NOT NULL,
  PRIMARY KEY (artifact_id, version),
  CONSTRAINT gar_scope CHECK ((scope = 'PLATFORM' AND tenant_id IS NULL AND domain_id IS NULL) OR (scope = 'TENANT' AND tenant_id IS NOT NULL AND domain_id IS NULL)
                              OR (scope = 'DOMAIN' AND tenant_id IS NOT NULL AND domain_id IS NOT NULL))
);
CREATE UNIQUE INDEX gar_one_current ON governance.artifacts (artifact_id) WHERE superseded_at IS NULL;
CREATE UNIQUE INDEX gar_key_current ON governance.artifacts (kind, external_key, coalesce(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(domain_id, '00000000-0000-0000-0000-000000000000'::uuid)) WHERE superseded_at IS NULL;
CREATE INDEX gar_kind ON governance.artifacts (kind, lifecycle) WHERE superseded_at IS NULL;

/* THE LINKS (append-only): from → to with a relation; a link is RETIRED by a later row (retired = true), never updated or deleted. */
CREATE TABLE governance.links (
  link_id         uuid PRIMARY KEY,
  scope           text NOT NULL CHECK (scope IN ('PLATFORM', 'TENANT', 'DOMAIN')),
  tenant_id       uuid,
  domain_id       uuid,
  from_artifact   uuid NOT NULL,
  to_artifact     uuid NOT NULL,
  relation        text NOT NULL CHECK (relation = ANY (governance.link_relations())),
  retired         boolean NOT NULL DEFAULT false,
  retires_link    uuid REFERENCES governance.links (link_id),
  attributes      jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(attributes) = 'object'),
  recorded_by     uuid NOT NULL,
  recorded_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  CONSTRAINT gln_not_self CHECK (from_artifact <> to_artifact),
  CONSTRAINT gln_retire CHECK (retired = (retires_link IS NOT NULL)),
  CONSTRAINT gln_scope CHECK ((scope = 'PLATFORM' AND tenant_id IS NULL AND domain_id IS NULL) OR (scope = 'TENANT' AND tenant_id IS NOT NULL AND domain_id IS NULL)
                              OR (scope = 'DOMAIN' AND tenant_id IS NOT NULL AND domain_id IS NOT NULL))
);
CREATE INDEX gln_from ON governance.links (from_artifact, relation);
CREATE INDEX gln_to ON governance.links (to_artifact, relation);
CREATE TRIGGER gln_append_only BEFORE UPDATE OR DELETE ON governance.links FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

/* The LIVE links (a link not retired by a later row). */
CREATE OR REPLACE VIEW governance.links_live WITH (security_invoker = true) AS
  SELECT l.* FROM governance.links l WHERE NOT l.retired AND NOT EXISTS (SELECT 1 FROM governance.links r WHERE r.retires_link = l.link_id);

/* THE PLATFORM SIGNATURES (a sibling of executive.signatures, which is DOMAIN-scoped — B36's table untouched): a named human's Ed25519
   signature, by key reference, over a vendor-side subject's digest (the baseline decision, an exception approval, a release acceptance, a
   design acceptance, a manifest attestation). One per signer per subject version. Written by the parts' signing ports. */
CREATE OR REPLACE FUNCTION governance.signature_kinds() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'baseline_decision', 'decision_rights', 'exception_approval', 'release_acceptance', 'design_acceptance', 'design_contribution', 'manifest_attestation',
  'change_approval', 'conflict_resolution', 'ownership_transfer', 'acceptance_attestation'] $$;
GRANT EXECUTE ON FUNCTION governance.signature_kinds() TO eye_app, eye_commit;
CREATE TABLE governance.signatures (
  signature_id    uuid PRIMARY KEY,
  scope           text NOT NULL CHECK (scope IN ('PLATFORM', 'TENANT', 'DOMAIN')),
  tenant_id       uuid,
  domain_id       uuid,
  subject_kind    text NOT NULL CONSTRAINT gsg_subject_kind CHECK (subject_kind = ANY (governance.signature_kinds())),
  subject_id      uuid NOT NULL,
  subject_version int NOT NULL,
  subject_digest  text NOT NULL CHECK (subject_digest ~ '^[0-9a-f]{64}$'),
  signer          uuid NOT NULL,
  signer_role     text NOT NULL,
  key_id          text NOT NULL,
  algorithm       text NOT NULL CHECK (algorithm = 'ed25519'),
  signature       text NOT NULL,
  bound_action    text NOT NULL,
  signed_at       timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  CONSTRAINT gsg_one_per_signer UNIQUE (subject_kind, subject_id, subject_version, signer)
);
CREATE TRIGGER gsg_append_only BEFORE UPDATE OR DELETE ON governance.signatures FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

/* THE HOLDS: a subject (a release candidate, a capability's expansion, an acceptance record) held, by whom and why — an expired exception
   (§PG), a conformance conflict (§PG), stale or missing evidence (§CM), a constrained acceptance (§AR). A hold is LIFTED by a later act
   (lifted_at), never deleted. §CM's release-candidate check and §AR's expansion check read the open holds. */
CREATE TABLE governance.holds (
  hold_id         uuid PRIMARY KEY,
  scope           text NOT NULL CHECK (scope IN ('PLATFORM', 'TENANT', 'DOMAIN')),
  tenant_id       uuid,
  domain_id       uuid,
  subject_artifact uuid NOT NULL,
  reason_kind     text NOT NULL CHECK (reason_kind IN ('exception_expired', 'conflict', 'evidence_stale', 'evidence_missing', 'acceptance_constrained', 'conformance_drift', 'ownership_gap')),
  source_artifact uuid,
  reason          text NOT NULL CHECK (length(btrim(reason)) >= 8),
  opened_by       uuid NOT NULL,
  opened_at       timestamptz NOT NULL DEFAULT clock_timestamp(),
  lifted_at       timestamptz,
  lifted_by       uuid,
  lift_reason     text,
  correlation_id  uuid NOT NULL,
  CONSTRAINT ghd_lifted CHECK ((lifted_at IS NULL) = (lifted_by IS NULL) AND (lifted_at IS NULL) = (lift_reason IS NULL))
);
CREATE INDEX ghd_open ON governance.holds (subject_artifact) WHERE lifted_at IS NULL;

-- RLS and grants. PLATFORM rows (the vendor's registries) are readable by every authenticated context (they are not tenant data); TENANT /
-- DOMAIN rows under the tenant / domain isolation idioms; SELECT to eye_app and eye_commit; no write grant — the definer ports write.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['governance.events', 'governance.artifacts', 'governance.links', 'governance.signatures', 'governance.holds'] LOOP
    EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', t);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($f$CREATE POLICY governance_visibility ON %s USING (
      (scope = 'PLATFORM' AND public.eye_scope() <> 'NONE')
      OR (scope = 'TENANT' AND tenant_id = public.eye_tenant())
      OR (scope = 'DOMAIN' AND tenant_id = public.eye_tenant() AND (public.eye_scope() = 'TENANT' OR domain_id = public.eye_domain()))
      OR public.eye_scope() = 'PLATFORM')$f$, t);
    EXECUTE format('GRANT SELECT ON %s TO eye_app, eye_commit', t);
  END LOOP;
  GRANT SELECT ON governance.links_live TO eye_app, eye_commit;
END $$;


-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §RG — registries, bidirectional traceability, orphan detection, deterministic change impact, the verification record, the fixture registry (F-P7D-25, F-P7-F-12)
-- (folded at integration from the part-local file 0115_b107_x_rg.sql, unchanged but for the marked `B107 integration` edits; apply order §0, §RG, §CM, §DR, §PG, §AR, §DG)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 0115 §RG — CP-6 B107: THE REGISTRIES, BIDIRECTIONAL TRACEABILITY, ORPHAN DETECTION, DETERMINISTIC CHANGE IMPACT, THE VERIFICATION RECORD
-- AND THE FIXTURE REGISTRY (F-P7D-25 V03-T-474, ES-01-002, ES-02-001/-005, ES-03-001..004, ES-06-001..005, ES-67-001, V04-T-012, V04-T-017,
-- IA-02-001/-002/-003/-006, IA-06-001/-002/-003/-005/-006, V06-T-008, DP-02-001/-002/-003/-006, DP-07-001/-002/-003/-005/-006,
-- DP-67-002/-005; F-P7-F-12 PR-08-001/-002/-003/-005/-006, CAP-AU-09, AT-08, ADR-004). Applies alone on 0001–0114 + the prelude (§0).
--
-- WHAT IS BUILT
--   * THE IMPORTERS (read-only): a TS reader (src/governance/registries/importers.ts) parses the repository's registers —
--     audit/requirements/*.csv (requirements, their chapters, the V8 App A capabilities and App D journeys), audit/delivery/feature-rowmap.csv
--     (+ FEATURE_TRACKER.csv titles), DECISIONS.md (decision records), EXCEPTIONS.md (the ENGINEERING exception class — §PG governs the
--     in-product registry) — and objects.interface_register / objects.schema_registry, and feeds ONE governed PLATFORM port per source
--     (governance.rg_import) run by the conformance steward. Each run records the source's sha256 and is IDEMPOTENT (an unchanged source writes
--     nothing; an unchanged row writes nothing). A changed row is a NEW VERSION (the old one stays resolvable — ES-03-004); a row gone from
--     the source is a RETIRED version (never deleted). THE SOURCES ARE NEVER WRITTEN: the product never writes the CSVs, never marks a unit
--     verified:all, and an in-product record is never a leg pointer; the in-product status of a requirement is the register's, imported.
--   * THE NORMATIVE-ARTIFACT REGISTRY (ES-02-001, IA-02-001..003, DP-02-001..003, PR-08-003): identity, authority class, owner, lifecycle,
--     version, effective time, supersession, dependents (the incoming live links); THE CONTROL ORDER (governance.rg_authority_rank): a lower
--     authority never supersedes, governs or is inherited by a higher one, and a derived requirement never weakens its parent (ES-03-003).
--   * TRACE LINKS (the prelude's governance.links, written here with the versions and digests of both ends — machine-readable, versioned,
--     append-only, audited: ES-06-001/-005) and BIDIRECTIONAL queries, as of any instant (governance.rg_trace).
--   * ORPHANS (governance.rg_orphans): every artifact lacking a required link, by a closed rule list — listed, never hidden.
--   * DETERMINISTIC CHANGE IMPACT (governance.rg_impact / rg_record_impact — ES-02-005, ES-06-004): a changed (or proposed) artifact → its
--     dependents through the live links, breadth-first, ordered (depth, kind, key, id), digested: the same input over the same links gives the
--     same digest. Recorded impacts mark the dependent verifications STALE and HOLD the dependent release candidates (evidence_stale).
--   * INHERITANCE (governance.rg_inheritance / rg_reconcile_inheritance — IA-06-005, DP-07-005, PR-08-005): incomplete, circular, stale,
--     unverifiable, conflicting or out-of-order inheritance makes the artifact NON-CONFORMANT and HOLDS it and the capabilities depending on it
--     (capability acceptance held), names the affected journeys and release candidates and the highest controlling authority; a closed chain
--     LIFTS the holds. Nothing is inferred healthy: an artifact never checked reads `unchecked`.
--   * THE ADMISSION CHECK (governance.rg_admission_check — IA-02-006, IA-06-006, DP-02-006, DP-07-006): bidirectional closure, orphans, holds,
--     stale and missing verification for a subject; PRODUCTION ADMISSION IS R1 and is never claimed here.
--   * THE VERIFICATION RECORD (V04-T-012, ES-67-001): vitest / playwright JSON reports and gate receipts ingested as `evidence` (the record)
--     and `test` artifacts with IDENTITY / EXECUTION / VALIDITY dimensions; tests VERIFY the requirements their titles cite by EXACT id
--     (never by prose similarity); an accountable REVIEW by independent assurance (never the ingester or runner, never an agent).
--   * THE FIXTURE REGISTRY (DP-67-002/-005): identity, purpose, generator/source, schema, seed, classification, expected results, environment
--     scope, expiry; APPROVED by independent assurance (never a builder of the fixture); QUARANTINED when stale, non-representative,
--     contaminated, privacy-unsafe, irreproducible or indistinguishable — its dependent evidence INVALIDATED; REBUILT as a new version from an
--     approved generator; dependent verification re-run.
--   * THE BUILD IDENTITY read (ES-06-003; the migration head here, the head SHA / policy bundle / manifest digest in TS) stamped on the
--     declared set of §RG's own outputs: every import, impact and verification record.
--
-- THREE CLAIMS, never mixed: CONSTRUCTION (this code and phase6-registries-b107); DEMONSTRATED OPERATION (the act on eye_demo with SYNTHETIC
-- personas); REAL ACCEPTANCE / PRODUCTION ADMISSION (R1/R2/H3 — named authorities; never claimed: the admission check says so, a verification
-- record's claim is construction or demonstration only).
-- Re-declared here: nothing of 0001–0114 or the prelude. Added to the prelude's tables: three indexes (gln_source, gln_retires, gar_req_id).
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- §RG.1 INDEXES on the shared core (lookups the importer, the as-of reads and the citation resolution need) ──────────────────────────────────
CREATE INDEX IF NOT EXISTS gln_source ON governance.links ((attributes->>'source')) WHERE NOT retired;
CREATE INDEX IF NOT EXISTS gln_retires ON governance.links (retires_link);  -- every "not retired by a later row" test (links_live included) probes it
CREATE INDEX IF NOT EXISTS gar_req_id ON governance.artifacts ((split_part(external_key, ':', 2))) WHERE kind = 'requirement' AND superseded_at IS NULL;

-- §RG.2 THE VOCABULARY ───────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* THE CONTROL ORDER. Volume 0 (the product constitution) and Volume 2 (the controlled technical baseline) override every other document; the
   executive narrative (V1), the architecture (V3), engineering (V4), AI (V5), infrastructure and data (V6, V7 — peers), product and experience
   (V8, V9 — peers: "Volume 8 … may not redefine … future visual-system authority", PR-08-003), the commercial thesis (V10); then the project's
   decisions and engineering exceptions ("refine, and may never contradict, Volume 0 and Volume 3" — DECISIONS.md), manifests, implementation,
   verification and operational evidence (IA-02-001: "from Volume 0 through infrastructure manifests, implementation, verification, and
   operational evidence"). A lower number controls. Two classes of the SAME rank are peers: neither controls the other. */
CREATE OR REPLACE FUNCTION governance.rg_authority_rank(p_class text) RETURNS int
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$ SELECT CASE p_class
  WHEN 'constitutional' THEN 0 WHEN 'technical_baseline' THEN 1 WHEN 'doctrine' THEN 2 WHEN 'architecture' THEN 3 WHEN 'engineering' THEN 4
  WHEN 'ai' THEN 5 WHEN 'infrastructure' THEN 6 WHEN 'data' THEN 6 WHEN 'product' THEN 7 WHEN 'experience' THEN 7 WHEN 'commercial' THEN 8
  WHEN 'project_decision' THEN 9 WHEN 'project_exception' THEN 9 WHEN 'manifest' THEN 10 WHEN 'implementation' THEN 11 WHEN 'verification' THEN 12
  WHEN 'operational_evidence' THEN 13 END $$;
CREATE OR REPLACE FUNCTION governance.rg_volume_class(p_volume text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$ SELECT CASE p_volume
  WHEN 'V0' THEN 'constitutional' WHEN 'V1' THEN 'doctrine' WHEN 'V2' THEN 'technical_baseline' WHEN 'V3' THEN 'architecture' WHEN 'V4' THEN 'engineering'
  WHEN 'V5' THEN 'ai' WHEN 'V6' THEN 'infrastructure' WHEN 'V7' THEN 'data' WHEN 'V8' THEN 'product' WHEN 'V9' THEN 'experience' WHEN 'V10' THEN 'commercial' END $$;
/* May `p_lower` inherit from / be governed by / be superseded by `p_upper`? (the upper controls: a strictly lower rank, or the SAME class) */
CREATE OR REPLACE FUNCTION governance.rg_controls(p_upper text, p_lower text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT p_upper IS NOT NULL AND p_lower IS NOT NULL AND governance.rg_authority_rank(p_upper) IS NOT NULL AND governance.rg_authority_rank(p_lower) IS NOT NULL
     AND (p_upper = p_lower OR governance.rg_authority_rank(p_upper) < governance.rg_authority_rank(p_lower)) $$;

/* THE DEPENDENCY DIRECTION of each relation: the side that is IMPACTED when the other side changes ('from' = "from depends on to");
   NULL = the relation does not propagate a change (ownership, supersession, a declared conflict). */
CREATE OR REPLACE FUNCTION governance.rg_dependent_side(p_relation text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$ SELECT CASE
  WHEN p_relation IN ('implements', 'verifies', 'depends_on', 'derives_from', 'cites', 'covers', 'accepted_in', 'excepts', 'deploys', 'consumes',
                      'maps_to', 'evidences', 'contributes_to', 'part_of') THEN 'from'
  WHEN p_relation = 'governs' THEN 'to'
  ELSE NULL END $$;

/* The relation's kind constraints (NULL = admitted, else the reason). The links §RG records: a test or a record VERIFIES; a record EVIDENCES;
   supersession stays within a kind; a release DEPLOYS. Other parts' links are theirs. */
CREATE OR REPLACE FUNCTION governance.rg_relation_problem(p_relation text, p_from_kind text, p_to_kind text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$ SELECT CASE
  WHEN p_relation = 'verifies' AND p_from_kind NOT IN ('test', 'evidence') THEN 'only a test or a verification record verifies'
  WHEN p_relation = 'evidences' AND p_from_kind <> 'evidence' THEN 'only evidence evidences'
  WHEN p_relation = 'supersedes' AND p_from_kind <> p_to_kind THEN 'an artifact supersedes only an artifact of its own kind'
  WHEN p_relation = 'deploys' AND p_from_kind NOT IN ('release_candidate', 'deployable_unit', 'manifest') THEN 'only a release candidate, a deployable unit or a manifest deploys'
  WHEN p_relation = 'derives_from' AND p_from_kind <> p_to_kind AND NOT (p_from_kind = 'standard' AND p_to_kind = 'requirement') AND NOT (p_from_kind = 'requirement' AND p_to_kind = 'standard')
    THEN 'derivation is between requirements or standards'
  ELSE NULL END $$;

/* THE REQUIRED LINKS (the orphan rules, a closed list): an artifact of `kind` (narrowed by `only_role`, never a `exempt_class` one) with no
   LIVE link of `relation` on `side` (out: it is the from; in: it is the to) to a current artifact of `other_kinds`, is an ORPHAN. */
CREATE OR REPLACE FUNCTION governance.rg_link_rules() RETURNS TABLE (rule_id text, kind text, relation text, side text, other_kinds text[], only_role text, exempt_class text, description text, basis text)
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$ VALUES
  ('RG-O01', 'requirement', 'implements', 'in', ARRAY['feature', 'component', 'deployable_unit', 'capability', 'interface', 'schema'], NULL, NULL, 'a requirement no feature or component implements', 'ES-01-002, ES-67-001 (the rowmap maps every row to a feature)'),
  ('RG-O02', 'requirement', 'part_of', 'out', ARRAY['standard'], NULL, NULL, 'a requirement not placed in its controlling chapter', 'V06-T-008: a requirement inherits every anchor of its chapter'),
  ('RG-O03', 'standard', 'derives_from', 'out', NULL, 'chapter', 'constitutional', 'a chapter with no upward anchor (constitutional invariant or controlling requirement)', 'V04-T-017, V06-T-008, V03-T-474'),
  ('RG-O04', 'capability', 'maps_to', 'out', ARRAY['requirement'], NULL, NULL, 'a capability with no requirement row', 'PR-08-001, CAP-AU-09'),
  ('RG-O05', 'journey', 'maps_to', 'out', ARRAY['requirement'], NULL, NULL, 'a journey with no requirement row', 'PR-08-002'),
  ('RG-O06', 'test', 'verifies', 'out', ARRAY['requirement', 'capability', 'journey', 'component', 'interface', 'schema', 'deployable_unit'], NULL, NULL, 'a test that verifies nothing named', 'ES-67-001, V04-T-012'),
  ('RG-O07', 'evidence', 'evidences', 'out', NULL, NULL, NULL, 'evidence that evidences nothing', 'V04-T-012'),
  ('RG-O08', 'fixture', 'consumes', 'in', ARRAY['test'], NULL, NULL, 'a fixture no test consumes', 'DP-67-002'),
  ('RG-O09', 'component', 'implements', 'out', ARRAY['requirement', 'capability', 'interface'], NULL, NULL, 'a component that implements no requirement', 'IA-06-001, ES-01-002'),
  ('RG-O10', 'deployable_unit', 'implements', 'out', ARRAY['requirement', 'capability', 'component', 'interface'], NULL, NULL, 'a deployable unit that implements nothing named', 'ES-06-002'),
  ('RG-O11', 'release_candidate', 'deploys', 'out', NULL, NULL, NULL, 'a release candidate that deploys nothing', 'ES-06-002, IA-06-006'),
  ('RG-O12', 'feature', 'implements', 'out', ARRAY['requirement'], NULL, NULL, 'a feature with no requirement row', 'PR-08-002'),
  ('RG-O13', 'exception', 'excepts', 'out', NULL, NULL, NULL, 'an exception that names no requirement it excepts', 'IA-02-002'),
  ('RG-O14', 'decision_record', 'cites', 'out', NULL, NULL, NULL, 'a decision record with no resolvable anchor', 'ES-02-001'),
  ('RG-O15', 'interface', 'maps_to', 'out', ARRAY['requirement'], NULL, NULL, 'an interface with no requirement row', 'V04-T-005, IA-06-001') $$;
GRANT EXECUTE ON FUNCTION governance.rg_authority_rank(text), governance.rg_volume_class(text), governance.rg_controls(text, text), governance.rg_dependent_side(text),
  governance.rg_relation_problem(text, text, text), governance.rg_link_rules() TO eye_app, eye_commit;

/* The deterministic identity of a registry artifact (ADR-004: stable identities): the same kind and key give the same id in every
   database — the act, the rehearsal and the harness agree; an identity is never re-keyed (a new key IS a new artifact). */
CREATE OR REPLACE FUNCTION governance.rg_artifact_id(p_kind text, p_key text) RETURNS uuid
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$ SELECT md5('governance.rg:' || p_kind || ':' || p_key)::uuid $$;
/* The NORMATIVE digest (what a change means): the register's status (`attributes.register`) and a fixture's governance state (`approved_by`,
   `quarantine`) are carried — and versioned — but never change the digest (a link to it stays current). */
CREATE OR REPLACE FUNCTION governance.rg_content_digest(p_kind text, p_key text, p_title text, p_class text, p_volume text, p_attributes jsonb) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT governance.digest(jsonb_build_object('kind', p_kind, 'key', p_key, 'title', p_title, 'authority_class', p_class, 'controlling_volume', p_volume,
                                              'attributes', coalesce(p_attributes, '{}'::jsonb) - 'register' - 'approved_by' - 'quarantine')) $$;
GRANT EXECUTE ON FUNCTION governance.rg_artifact_id(text, text), governance.rg_content_digest(text, text, text, text, text, jsonb) TO eye_app, eye_commit;

-- §RG.3 THE TABLES ──────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* One row per import RUN that changed something (an unchanged source writes nothing): the source and its sha256, what changed. */
CREATE TABLE governance.rg_imports (
  import_id       uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id       uuid CHECK (tenant_id IS NULL),
  domain_id       uuid CHECK (domain_id IS NULL),
  source_kind     text NOT NULL CHECK (source_kind IN ('requirements', 'rowmap', 'decisions', 'exceptions', 'interfaces', 'schemas')),
  source_path     text NOT NULL CHECK (source_path ~ '^[A-Za-z0-9_][A-Za-z0-9_./-]{0,199}$' AND source_path !~ '\.\.'),
  source_digest   text NOT NULL CHECK (source_digest ~ '^[0-9a-f]{64}$'),
  parser_version  text NOT NULL,
  detail          jsonb NOT NULL DEFAULT '{}'::jsonb,
  row_count       int NOT NULL CHECK (row_count >= 0),
  counts          jsonb NOT NULL,
  changed         uuid[] NOT NULL DEFAULT '{}',
  unresolved      jsonb NOT NULL DEFAULT '[]'::jsonb,
  build_identity  jsonb NOT NULL DEFAULT '{}'::jsonb,
  imported_by     uuid NOT NULL,
  imported_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL
);
CREATE INDEX rgi_source ON governance.rg_imports (source_path, imported_at DESC);

/* A recorded CHANGE IMPACT (ES-02-005, ES-06-004): the ordered dependents and their digest; the stale verifications; the holds opened. */
CREATE TABLE governance.rg_impacts (
  impact_id       uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id       uuid CHECK (tenant_id IS NULL),
  domain_id       uuid CHECK (domain_id IS NULL),
  trigger         text NOT NULL CHECK (trigger IN ('import', 'register', 'change', 'proposal')),
  trigger_ref     uuid,
  input           jsonb NOT NULL,
  dependents      jsonb NOT NULL,
  counts          jsonb NOT NULL,
  stale_verifications jsonb NOT NULL DEFAULT '[]'::jsonb,
  held            jsonb NOT NULL DEFAULT '[]'::jsonb,
  depth_limit     int NOT NULL CHECK (depth_limit BETWEEN 1 AND 12),
  truncated       boolean NOT NULL DEFAULT false,
  digest          text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  build_identity  jsonb NOT NULL DEFAULT '{}'::jsonb,
  recorded_by     uuid NOT NULL,
  recorded_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL
);

/* THE VERIFICATION RECORD (V04-T-012): identity, execution and validity of one report; its cases below. claim: construction (a harness or CI
   run) or demonstration (the act) — never acceptance. */
CREATE TABLE governance.rg_verification_records (
  record_id       uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id       uuid CHECK (tenant_id IS NULL),
  domain_id       uuid CHECK (domain_id IS NULL),
  source_kind     text NOT NULL CHECK (source_kind IN ('vitest', 'playwright', 'gate_receipt')),
  source_name     text NOT NULL CHECK (length(btrim(source_name)) BETWEEN 1 AND 200),
  source_digest   text NOT NULL UNIQUE CHECK (source_digest ~ '^[0-9a-f]{64}$'),
  identity        jsonb NOT NULL,
  execution       jsonb NOT NULL,
  validity        jsonb NOT NULL,
  totals          jsonb NOT NULL,
  result          text NOT NULL CHECK (result IN ('passed', 'failed', 'mixed', 'unstated')),
  valid_until     timestamptz NOT NULL,
  claim           text NOT NULL CHECK (claim IN ('construction', 'demonstration')),
  build_identity  jsonb NOT NULL DEFAULT '{}'::jsonb,
  ingested_by     uuid NOT NULL,
  ingested_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL
);
CREATE TABLE governance.rg_verification_cases (
  record_id       uuid NOT NULL REFERENCES governance.rg_verification_records (record_id),
  case_no         int NOT NULL CHECK (case_no >= 1),
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id       uuid CHECK (tenant_id IS NULL),
  domain_id       uuid CHECK (domain_id IS NULL),
  test_artifact   uuid NOT NULL,
  test_version    int NOT NULL,
  status          text NOT NULL CHECK (status IN ('passed', 'failed', 'skipped', 'todo', 'flaky', 'unstated')),
  duration_ms     numeric,
  cited           text[] NOT NULL DEFAULT '{}',
  resolved        uuid[] NOT NULL DEFAULT '{}',
  fixtures        uuid[] NOT NULL DEFAULT '{}',
  PRIMARY KEY (record_id, case_no)
);
CREATE INDEX rgc_test ON governance.rg_verification_cases (test_artifact);
/* The accountable REVIEW of a record (ES-03-001: "independently reviewable"): independent assurance, never the ingester or the runner. */
CREATE TABLE governance.rg_verification_reviews (
  review_id       uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id       uuid CHECK (tenant_id IS NULL),
  domain_id       uuid CHECK (domain_id IS NULL),
  record_id       uuid NOT NULL REFERENCES governance.rg_verification_records (record_id),
  decision        text NOT NULL CHECK (decision IN ('accepted', 'rejected')),
  record_digest   text NOT NULL CHECK (record_digest ~ '^[0-9a-f]{64}$'),
  reason          text NOT NULL CHECK (length(btrim(reason)) >= 8),
  reviewer        uuid NOT NULL,
  reviewed_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  CONSTRAINT rgr_one_per_reviewer UNIQUE (record_id, reviewer)
);
/* EVIDENCE INVALIDATED (DP-67-005): a record whose fixture was quarantined (or lapsed) is not evidence any more — recorded, never deleted. */
CREATE TABLE governance.rg_invalidations (
  invalidation_id uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id       uuid CHECK (tenant_id IS NULL),
  domain_id       uuid CHECK (domain_id IS NULL),
  record_id       uuid NOT NULL REFERENCES governance.rg_verification_records (record_id),
  cause_kind      text NOT NULL CHECK (cause_kind IN ('fixture_quarantined')),
  cause_artifact  uuid NOT NULL,
  cause_version   int NOT NULL,
  reason          text NOT NULL,
  recorded_by     uuid NOT NULL,
  recorded_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  CONSTRAINT rgv_once UNIQUE (record_id, cause_artifact, cause_version)
);
/* The FIXTURE decisions (approve / quarantine / rebuild): the trail beside the fixture's versions. */
CREATE TABLE governance.rg_fixture_decisions (
  decision_id     uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id       uuid CHECK (tenant_id IS NULL),
  domain_id       uuid CHECK (domain_id IS NULL),
  fixture_artifact uuid NOT NULL,
  fixture_version int NOT NULL,
  decision        text NOT NULL CHECK (decision IN ('registered', 'approved', 'quarantined', 'rebuilt')),
  reason_class    text CHECK (reason_class IS NULL OR reason_class IN ('stale', 'non_representative', 'contaminated', 'privacy_unsafe', 'irreproducible', 'indistinguishable')),
  reason          text NOT NULL,
  digest          text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  actor           uuid NOT NULL,
  decided_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL
);
/* Which holds §RG opened and why (the prelude's holds carry no origin): an inheritance finding on an artifact, or a recorded impact. */
CREATE TABLE governance.rg_hold_origins (
  hold_id         uuid PRIMARY KEY REFERENCES governance.holds (hold_id),
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id       uuid CHECK (tenant_id IS NULL),
  domain_id       uuid CHECK (domain_id IS NULL),
  origin          text NOT NULL CHECK (origin IN ('inheritance', 'impact')),
  origin_artifact uuid,
  impact_id       uuid REFERENCES governance.rg_impacts (impact_id),
  findings        jsonb NOT NULL DEFAULT '[]'::jsonb,
  recorded_at     timestamptz NOT NULL DEFAULT clock_timestamp()
);

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['governance.rg_imports', 'governance.rg_impacts', 'governance.rg_verification_records', 'governance.rg_verification_cases',
                           'governance.rg_verification_reviews', 'governance.rg_invalidations', 'governance.rg_fixture_decisions', 'governance.rg_hold_origins'] LOOP
    EXECUTE format('CREATE TRIGGER %s BEFORE UPDATE OR DELETE ON %s FOR EACH ROW EXECUTE FUNCTION public.raise_append_only()', replace(t, 'governance.', '') || '_append_only', t);
    EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', t);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($f$CREATE POLICY governance_visibility ON %s USING (
      (scope = 'PLATFORM' AND public.eye_scope() <> 'NONE')
      OR (scope = 'TENANT' AND tenant_id = public.eye_tenant())
      OR (scope = 'DOMAIN' AND tenant_id = public.eye_tenant() AND (public.eye_scope() = 'TENANT' OR domain_id = public.eye_domain()))
      OR public.eye_scope() = 'PLATFORM')$f$, t);
    EXECUTE format('GRANT SELECT ON %s TO eye_app, eye_commit', t);
  END LOOP;
END $$;

-- §RG.4 THE INTERNAL WRITERS (not granted: only the ports below call them) ───────────────────────────────────────────────────────────────────
/* PUT an artifact: unchanged → nothing written; changed (content, lifecycle, owner or the register's status) → the current version superseded
   and version n+1 inserted at the same instant (ES-03-004: the old version stays resolvable as of its time). */
CREATE OR REPLACE FUNCTION governance.rg_put_artifact(p_kind text, p_key text, p_title text, p_class text, p_volume text, p_lifecycle text, p_attributes jsonb,
  p_owner uuid, p_owner_role text, p_source jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v_id uuid := governance.rg_artifact_id(p_kind, p_key); cur governance.artifacts%ROWTYPE; v_digest text; v_now timestamptz := clock_timestamp(); v_version int;
BEGIN
  v_digest := governance.rg_content_digest(p_kind, p_key, p_title, p_class, p_volume, p_attributes);
  SELECT * INTO cur FROM governance.artifacts a WHERE a.artifact_id = v_id AND a.superseded_at IS NULL FOR UPDATE;
  IF cur.artifact_id IS NOT NULL AND cur.digest = v_digest AND cur.lifecycle = p_lifecycle AND cur.attributes = coalesce(p_attributes, '{}'::jsonb) AND cur.title = p_title
     AND cur.owner_principal_id IS NOT DISTINCT FROM p_owner AND cur.owner_role IS NOT DISTINCT FROM p_owner_role THEN
    RETURN jsonb_build_object('artifact_id', v_id, 'version', cur.version, 'digest', cur.digest, 'changed', false, 'normative_change', false, 'created', false);
  END IF;
  IF cur.artifact_id IS NULL AND EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.kind = p_kind AND a.external_key = p_key AND a.scope = 'PLATFORM' AND a.superseded_at IS NULL) THEN
    RAISE EXCEPTION 'requirement registry rejected (duplicate): % % is registered under another identity', p_kind, p_key USING ERRCODE = '23505';
  END IF;
  v_version := coalesce(cur.version, 0) + 1;
  IF cur.artifact_id IS NOT NULL THEN
    UPDATE governance.artifacts SET superseded_at = v_now WHERE artifact_id = v_id AND version = cur.version;
  END IF;
  INSERT INTO governance.artifacts (artifact_id, version, scope, kind, external_key, title, owner_principal_id, owner_role, authority_class, controlling_volume, lifecycle,
                                    attributes, source, digest, effective_from, recorded_by, correlation_id)
  VALUES (v_id, v_version, 'PLATFORM', p_kind, p_key, p_title, p_owner, p_owner_role, p_class, p_volume, p_lifecycle, coalesce(p_attributes, '{}'::jsonb),
          coalesce(p_source, '{}'::jsonb), v_digest, v_now, p_actor, p_correlation);
  RETURN jsonb_build_object('artifact_id', v_id, 'version', v_version, 'digest', v_digest, 'changed', true, 'created', cur.artifact_id IS NULL,
                            'normative_change', cur.artifact_id IS NOT NULL AND cur.digest <> v_digest, 'previous_version', cur.version, 'previous_lifecycle', cur.lifecycle);
END $$;
REVOKE ALL ON FUNCTION governance.rg_put_artifact(text, text, text, text, text, text, jsonb, uuid, text, jsonb, uuid, uuid) FROM PUBLIC;

/* PUT a link (versioned: the versions and normative digests of both ends recorded): an identical LIVE link (same ends, relation and end
   digests) is kept; a link to an older version of an end is RE-ASSERTED (the old one retired by a later row, never updated). */
CREATE OR REPLACE FUNCTION governance.rg_put_link(p_from uuid, p_to uuid, p_relation text, p_attributes jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE f governance.artifacts%ROWTYPE; t governance.artifacts%ROWTYPE; v_old uuid; v_id uuid := gen_random_uuid(); v_attrs jsonb;
BEGIN
  SELECT * INTO f FROM governance.artifacts WHERE artifact_id = p_from AND superseded_at IS NULL;
  SELECT * INTO t FROM governance.artifacts WHERE artifact_id = p_to AND superseded_at IS NULL;
  SELECT l.link_id INTO v_old FROM governance.links_live l WHERE l.from_artifact = p_from AND l.to_artifact = p_to AND l.relation = p_relation
     AND l.attributes->>'from_digest' IS NOT DISTINCT FROM f.digest AND l.attributes->>'to_digest' IS NOT DISTINCT FROM t.digest ORDER BY l.recorded_at LIMIT 1;
  IF v_old IS NOT NULL THEN RETURN jsonb_build_object('link_id', v_old, 'created', false); END IF;
  -- an older assertion of the same link (an end moved): retired by a later row, then re-asserted
  INSERT INTO governance.links (link_id, scope, from_artifact, to_artifact, relation, retired, retires_link, attributes, recorded_by, correlation_id)
  SELECT gen_random_uuid(), 'PLATFORM', l.from_artifact, l.to_artifact, l.relation, true, l.link_id,
         jsonb_build_object('source', l.attributes->>'source', 'reason', 're-asserted over the current versions of its ends'), p_actor, p_correlation
    FROM governance.links_live l WHERE l.from_artifact = p_from AND l.to_artifact = p_to AND l.relation = p_relation;
  v_attrs := coalesce(p_attributes, '{}'::jsonb) || jsonb_build_object('from_version', f.version, 'to_version', t.version, 'from_digest', f.digest, 'to_digest', t.digest);
  INSERT INTO governance.links (link_id, scope, from_artifact, to_artifact, relation, attributes, recorded_by, correlation_id)
  VALUES (v_id, 'PLATFORM', p_from, p_to, p_relation, v_attrs, p_actor, p_correlation);
  RETURN jsonb_build_object('link_id', v_id, 'created', true);
END $$;
REVOKE ALL ON FUNCTION governance.rg_put_link(uuid, uuid, text, jsonb, uuid, uuid) FROM PUBLIC;

-- §RG.5 THE READS (INVOKER: the caller's RLS — PLATFORM rows are readable by every authenticated context; another tenant's rows are not) ─────
/* The migration head (ES-06-003's schema version) — the build identity's database half; the head SHA, policy bundle and manifest digest are
   read by the API (build-identity.ts). Never inferred: an absent value reads null. */
CREATE OR REPLACE FUNCTION governance.rg_build_identity() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $$
  SELECT jsonb_build_object('migration_head', (SELECT max(filename) FROM public.schema_migrations), 'migrations', (SELECT count(*) FROM public.schema_migrations)) $$;
REVOKE ALL ON FUNCTION governance.rg_build_identity() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_build_identity() TO eye_app, eye_commit;

/* A principal's display name for the registry pages: a PLATFORM-homed principal to a PLATFORM reader, or a principal of the reader's own
   tenant (products.catalog_principal_name answers only the latter — a vendor's steward would read blank). Nothing else is revealed. */
CREATE OR REPLACE FUNCTION governance.rg_principal_name(p_principal uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = identity, public, pg_catalog, pg_temp AS $$
  SELECT p.display_name FROM identity.principals p
   WHERE p.id = p_principal AND ((p.scope = 'PLATFORM' AND public.eye_scope() = 'PLATFORM') OR (p.tenant_id IS NOT NULL AND p.tenant_id = public.eye_tenant())) $$;
REVOKE ALL ON FUNCTION governance.rg_principal_name(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_principal_name(uuid) TO eye_app, eye_commit;

/* An artifact as of an instant (the version in force then), or NULL. */
CREATE OR REPLACE FUNCTION governance.rg_at(p_artifact uuid, p_as_of timestamptz) RETURNS governance.artifacts
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT a.* FROM governance.artifacts a WHERE a.artifact_id = p_artifact AND a.effective_from <= p_as_of AND (a.superseded_at IS NULL OR a.superseded_at > p_as_of)
   ORDER BY a.version DESC LIMIT 1 $$;
GRANT EXECUTE ON FUNCTION governance.rg_at(uuid, timestamptz) TO eye_app, eye_commit;

/* THE WALK (breadth-first, deterministic): from the roots, `up` toward what they depend on (their authorities), `down` toward their
   dependents, over the links LIVE AS OF p_as_of (recorded by then and not retired by then), to the artifacts in force then. A node is
   reported once, at its least depth, through its first parent in (key, relation, link) order. `p_cap` bounds the answer; a truncated
   walk SAYS so. A link is STALE when an end's normative digest moved since it was asserted. */
CREATE OR REPLACE FUNCTION governance.rg_walk(p_roots uuid[], p_direction text, p_depth int, p_as_of timestamptz, p_cap int) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v_seen jsonb := '{}'::jsonb; v_frontier uuid[]; v_level int := 0; v_rows jsonb := '[]'::jsonb; v_level_rows jsonb; v_lb jsonb; v_t timestamptz := coalesce(p_as_of, clock_timestamp());
        v_count int := 0; v_trunc boolean := false; v_back jsonb := '[]'::jsonb; v_cap int := greatest(coalesce(p_cap, 2000), 1); v_max int := least(greatest(coalesce(p_depth, 4), 1), 12); r uuid;
BEGIN
  IF p_direction IS NULL OR p_direction NOT IN ('up', 'down') THEN RAISE EXCEPTION 'trace link rejected (direction): a walk goes up or down' USING ERRCODE = '22023'; END IF;
  FOREACH r IN ARRAY coalesce(p_roots, '{}') LOOP v_seen := v_seen || jsonb_build_object(r::text, 0); END LOOP;
  v_frontier := coalesce(p_roots, '{}');
  WHILE v_level < v_max AND cardinality(v_frontier) > 0 LOOP
    v_level := v_level + 1;
    WITH live AS (
      SELECT l.link_id, l.relation, l.from_artifact, l.to_artifact, l.attributes AS lattrs FROM governance.links l
       WHERE NOT l.retired AND l.recorded_at <= v_t AND (l.from_artifact = ANY (v_frontier) OR l.to_artifact = ANY (v_frontier))
         AND NOT EXISTS (SELECT 1 FROM governance.links x WHERE x.retires_link = l.link_id AND x.recorded_at <= v_t)
    ), steps AS (
      SELECT e.*,
             CASE WHEN (coalesce(governance.rg_dependent_side(e.relation), 'from') = 'from') = (p_direction = 'up') THEN e.from_artifact ELSE e.to_artifact END AS here,
             CASE WHEN (coalesce(governance.rg_dependent_side(e.relation), 'from') = 'from') = (p_direction = 'up') THEN e.to_artifact ELSE e.from_artifact END AS there
        FROM live e
    ), hits AS (
      SELECT s.link_id, s.relation, s.here, s.there, s.lattrs, (governance.rg_at(s.here, v_t)).external_key AS here_key,
             n.kind AS n_kind, n.external_key AS n_key, n.title AS n_title, n.version AS n_version, n.lifecycle AS n_lifecycle, n.authority_class AS n_class,
             n.controlling_volume AS n_volume, n.digest AS n_digest, n.attributes->>'evidence_kind' AS n_evidence_kind, n.scope AS n_scope, n.tenant_id AS n_tenant, n.domain_id AS n_domain,
             (governance.rg_at(s.from_artifact, v_t)).digest AS fd, (governance.rg_at(s.to_artifact, v_t)).digest AS td
        FROM steps s CROSS JOIN LATERAL governance.rg_at(s.there, v_t) n
       WHERE s.here = ANY (v_frontier) AND n.artifact_id IS NOT NULL
         -- a recorded change impact is an analysis OF its subjects, never a dependent of them
         AND NOT (p_direction = 'down' AND n.kind = 'evidence' AND coalesce(n.attributes->>'evidence_kind', '') = 'change_impact')
    ), firsts AS (
      SELECT DISTINCT ON (h.there) h.* FROM hits h WHERE NOT (v_seen ? h.there::text) ORDER BY h.there, h.here_key, h.relation, h.link_id
    )
    SELECT (SELECT coalesce(jsonb_agg(jsonb_build_object(
               'depth', v_level, 'artifact_id', f.there, 'kind', f.n_kind, 'key', f.n_key, 'title', f.n_title, 'version', f.n_version, 'lifecycle', f.n_lifecycle,
               'authority_class', f.n_class, 'controlling_volume', f.n_volume, 'digest', f.n_digest, 'relation', f.relation, 'via', f.here, 'link_id', f.link_id,
               'scope', f.n_scope, 'tenant_id', f.n_tenant, 'domain_id', f.n_domain,
               'stale', (f.lattrs ? 'to_digest') AND (f.lattrs->>'to_digest' IS DISTINCT FROM f.td OR f.lattrs->>'from_digest' IS DISTINCT FROM f.fd))
             ORDER BY f.n_kind, f.n_key, f.there), '[]'::jsonb) FROM firsts f),
           (SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('root', h.there, 'from', h.here, 'relation', h.relation)), '[]'::jsonb)
              FROM hits h WHERE h.there = ANY (p_roots) AND governance.rg_dependent_side(h.relation) IS NOT NULL)
      INTO v_level_rows, v_lb;
    v_back := v_back || v_lb;
    IF jsonb_array_length(v_level_rows) = 0 THEN EXIT; END IF;
    IF v_count + jsonb_array_length(v_level_rows) > v_cap THEN
      v_level_rows := (SELECT coalesce(jsonb_agg(x ORDER BY o), '[]'::jsonb) FROM jsonb_array_elements(v_level_rows) WITH ORDINALITY AS e(x, o) WHERE o <= v_cap - v_count);
      v_trunc := true;
    END IF;
    v_rows := v_rows || v_level_rows; v_count := v_count + jsonb_array_length(v_level_rows);
    IF v_trunc THEN EXIT; END IF;
    v_seen := v_seen || (SELECT jsonb_object_agg(x->>'artifact_id', v_level) FROM jsonb_array_elements(v_level_rows) x);
    v_frontier := ARRAY(SELECT (x->>'artifact_id')::uuid FROM jsonb_array_elements(v_level_rows) x);
  END LOOP;
  RETURN jsonb_build_object('direction', p_direction, 'as_of', v_t, 'depth', v_level, 'count', v_count, 'truncated', v_trunc, 'nodes', v_rows, 'back_to_root', v_back);
END $$;
GRANT EXECUTE ON FUNCTION governance.rg_walk(uuid[], text, int, timestamptz, int) TO eye_app, eye_commit;

/* BIDIRECTIONAL TRACE (ES-06-001, PR-08-001, CAP-AU-09): the artifact as of the instant, its upward chain (authorities) and its downward
   dependents (tests, evidence, components, releases …). */
CREATE OR REPLACE FUNCTION governance.rg_trace(p_artifact uuid, p_depth int, p_as_of timestamptz) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v_t timestamptz := coalesce(p_as_of, clock_timestamp()); a governance.artifacts;
BEGIN
  a := governance.rg_at(p_artifact, v_t);
  IF a.artifact_id IS NULL THEN RAISE EXCEPTION 'trace link rejected (unknown_artifact): no artifact % is in force as of %', p_artifact, v_t USING ERRCODE = '22023'; END IF;
  RETURN jsonb_build_object('artifact', to_jsonb(a), 'as_of', v_t,
    'up', governance.rg_walk(ARRAY[p_artifact], 'up', coalesce(p_depth, 4), v_t, 2000),
    'down', governance.rg_walk(ARRAY[p_artifact], 'down', coalesce(p_depth, 4), v_t, 2000),
    'versions', (SELECT coalesce(jsonb_agg(jsonb_build_object('version', v.version, 'lifecycle', v.lifecycle, 'digest', v.digest, 'effective_from', v.effective_from, 'superseded_at', v.superseded_at)
                                           ORDER BY v.version), '[]'::jsonb) FROM governance.artifacts v WHERE v.artifact_id = p_artifact));
END $$;
GRANT EXECUTE ON FUNCTION governance.rg_trace(uuid, int, timestamptz) TO eye_app, eye_commit;

/* DETERMINISTIC CHANGE IMPACT (ES-02-005, ES-06-004): the input normalised (sorted, each with its current version and digest and the proposed
   digest if any), the dependents (the downward walk over the live links, ordered depth, kind, key, id), the classes the clause names
   (requirements, tests and evidence — the verifications now STALE —, components, capabilities, journeys, releases, decision-active products),
   and ONE digest over input + dependents. The same input over the same links and versions gives the same digest. */
CREATE OR REPLACE FUNCTION governance.rg_impact(p_changes jsonb, p_depth int) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v_input jsonb; v_roots uuid[]; v_walk jsonb; v_deps jsonb; v_reqs jsonb; v_depth int := least(greatest(coalesce(p_depth, 8), 1), 12);
BEGIN
  IF p_changes IS NULL OR jsonb_typeof(p_changes) <> 'array' OR jsonb_array_length(p_changes) = 0 OR jsonb_array_length(p_changes) > 500 THEN
    RAISE EXCEPTION 'change impact rejected (changes): name 1–500 changed artifacts' USING ERRCODE = '22023';
  END IF;
  SELECT jsonb_agg(jsonb_build_object('artifact_id', a.artifact_id, 'kind', a.kind, 'key', a.external_key, 'version', a.version, 'digest', a.digest,
                                      'proposed_digest', c.proposed) ORDER BY a.kind, a.external_key, a.artifact_id),
         array_agg(a.artifact_id ORDER BY a.artifact_id)
    INTO v_input, v_roots
    FROM (SELECT DISTINCT ON ((x->>'artifact_id')) (x->>'artifact_id')::uuid AS id, nullif(x->>'proposed_digest', '') AS proposed FROM jsonb_array_elements(p_changes) x
           WHERE coalesce(x->>'artifact_id', '') ~ '^[0-9a-f-]{36}$' ORDER BY (x->>'artifact_id'), x->>'proposed_digest') c
    JOIN governance.artifacts a ON a.artifact_id = c.id AND a.superseded_at IS NULL;
  IF v_roots IS NULL OR cardinality(v_roots) <> (SELECT count(DISTINCT x->>'artifact_id') FROM jsonb_array_elements(p_changes) x) THEN
    RAISE EXCEPTION 'change impact rejected (unknown_artifact): every changed artifact is a current registry artifact' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_input) x WHERE x->>'proposed_digest' IS NOT NULL AND x->>'proposed_digest' !~ '^[0-9a-f]{64}$') THEN
    RAISE EXCEPTION 'change impact rejected (digest): a proposed digest is 64 hex' USING ERRCODE = '22023';
  END IF;
  v_walk := governance.rg_walk(v_roots, 'down', v_depth, NULL, 20000);
  -- the REQUIREMENTS whose conformance is re-evaluated: those the changed artifacts and their dependent components, units, interfaces,
  -- schemas and capabilities realise (upward, 3 steps)
  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('artifact_id', n->>'artifact_id', 'key', n->>'key', 'version', (n->>'version')::int, 'digest', n->>'digest')), '[]'::jsonb)
    INTO v_reqs FROM jsonb_array_elements((governance.rg_walk(v_roots || ARRAY(SELECT (x->>'artifact_id')::uuid FROM jsonb_array_elements(v_walk->'nodes') x
                                                                              WHERE x->>'kind' IN ('component', 'deployable_unit', 'interface', 'schema', 'capability') ORDER BY 1),
                                                             'up', 3, NULL, 5000))->'nodes') n WHERE n->>'kind' = 'requirement';
  SELECT coalesce(jsonb_agg(x ORDER BY x->>'key', x->>'artifact_id'), '[]'::jsonb) INTO v_reqs FROM jsonb_array_elements(v_reqs) x;
  SELECT coalesce(jsonb_agg(jsonb_build_object('artifact_id', n->>'artifact_id', 'kind', n->>'kind', 'key', n->>'key', 'title', n->>'title', 'version', (n->>'version')::int,
                                               'digest', n->>'digest', 'depth', (n->>'depth')::int, 'relation', n->>'relation', 'via', n->>'via', 'lifecycle', n->>'lifecycle',
                                               'scope', n->>'scope', 'tenant_id', n->>'tenant_id', 'domain_id', n->>'domain_id')
                            ORDER BY (n->>'depth')::int, n->>'kind', n->>'key', n->>'artifact_id'), '[]'::jsonb)
    INTO v_deps FROM jsonb_array_elements(v_walk->'nodes') n;
  RETURN jsonb_build_object(
    'input', v_input, 'depth_limit', v_depth, 'truncated', (v_walk->>'truncated')::boolean, 'dependents', v_deps,
    'counts', (SELECT coalesce(jsonb_object_agg(k, n), '{}'::jsonb) FROM (SELECT d->>'kind' AS k, count(*) AS n FROM jsonb_array_elements(v_deps) d GROUP BY 1) s),
    'stale_verifications', (SELECT coalesce(jsonb_agg(d ORDER BY d->>'kind', d->>'key'), '[]'::jsonb) FROM jsonb_array_elements(v_deps) d WHERE d->>'kind' IN ('test', 'evidence')),
    'release_candidates', (SELECT coalesce(jsonb_agg(d ORDER BY d->>'key'), '[]'::jsonb) FROM jsonb_array_elements(v_deps) d WHERE d->>'kind' = 'release_candidate'),
    'decision_active', (SELECT coalesce(jsonb_agg(d ORDER BY d->>'key'), '[]'::jsonb) FROM jsonb_array_elements(v_deps) d WHERE d->>'kind' IN ('data_product', 'decision_record', 'acceptance_record', 'baseline')),
    'requirements_to_reverify', v_reqs,
    'digest', governance.digest(jsonb_build_object('input', v_input, 'depth_limit', v_depth, 'requirements', v_reqs,
              'dependents', (SELECT coalesce(jsonb_agg(jsonb_build_array(d->>'artifact_id', d->'version', d->>'digest', d->'depth', d->>'relation', d->>'via')
                                                       ORDER BY (d->>'depth')::int, d->>'kind', d->>'key', d->>'artifact_id'), '[]'::jsonb) FROM jsonb_array_elements(v_deps) d))));
END $$;
GRANT EXECUTE ON FUNCTION governance.rg_impact(jsonb, int) TO eye_app, eye_commit;

/* ORPHANS (ES-06-001, IA-06-006, PR-08-006, CAP-AU-09 "orphan-free"): per rule, the current artifacts lacking the required live link (and the
   mandatory requirements with neither a verification method nor a verifying test — ES-03-001, ES-67-001: rule RG-V01). Counted and listed;
   never hidden. p_ids narrows to a set (the admission check); p_rule to one rule. */
CREATE OR REPLACE FUNCTION governance.rg_orphan_rows(p_ids uuid[], p_rule text) RETURNS TABLE (rule_id text, artifact_id uuid, kind text, external_key text, title text)
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT r.rule_id, a.artifact_id, a.kind, a.external_key, a.title
    FROM governance.rg_link_rules() r
    JOIN governance.artifacts a ON a.kind = r.kind AND a.superseded_at IS NULL AND a.lifecycle IN ('active', 'proposed', 'deprecated')
                               AND (r.only_role IS NULL OR a.attributes->>'role' = r.only_role) AND (r.exempt_class IS NULL OR a.authority_class IS DISTINCT FROM r.exempt_class)
   WHERE (p_rule IS NULL OR r.rule_id = p_rule) AND (p_ids IS NULL OR a.artifact_id = ANY (p_ids)) AND r.side = 'out'
     AND NOT EXISTS (SELECT 1 FROM governance.links l JOIN governance.artifacts o ON o.artifact_id = l.to_artifact AND o.superseded_at IS NULL AND o.lifecycle NOT IN ('retired', 'superseded')
                      WHERE l.from_artifact = a.artifact_id AND l.relation = r.relation AND NOT l.retired AND (r.other_kinds IS NULL OR o.kind = ANY (r.other_kinds))
                        AND NOT EXISTS (SELECT 1 FROM governance.links x WHERE x.retires_link = l.link_id))
  UNION ALL
  SELECT r.rule_id, a.artifact_id, a.kind, a.external_key, a.title
    FROM governance.rg_link_rules() r
    JOIN governance.artifacts a ON a.kind = r.kind AND a.superseded_at IS NULL AND a.lifecycle IN ('active', 'proposed', 'deprecated')
                               AND (r.only_role IS NULL OR a.attributes->>'role' = r.only_role) AND (r.exempt_class IS NULL OR a.authority_class IS DISTINCT FROM r.exempt_class)
   WHERE (p_rule IS NULL OR r.rule_id = p_rule) AND (p_ids IS NULL OR a.artifact_id = ANY (p_ids)) AND r.side = 'in'
     AND NOT EXISTS (SELECT 1 FROM governance.links l JOIN governance.artifacts o ON o.artifact_id = l.from_artifact AND o.superseded_at IS NULL AND o.lifecycle NOT IN ('retired', 'superseded')
                      WHERE l.to_artifact = a.artifact_id AND l.relation = r.relation AND NOT l.retired AND (r.other_kinds IS NULL OR o.kind = ANY (r.other_kinds))
                        AND NOT EXISTS (SELECT 1 FROM governance.links x WHERE x.retires_link = l.link_id))
  UNION ALL
  SELECT 'RG-V01', a.artifact_id, a.kind, a.external_key, a.title
    FROM governance.artifacts a
   WHERE (p_rule IS NULL OR p_rule = 'RG-V01') AND (p_ids IS NULL OR a.artifact_id = ANY (p_ids))
     AND a.kind = 'requirement' AND a.superseded_at IS NULL AND a.lifecycle IN ('active', 'proposed') AND coalesce(a.attributes->>'mandatory', 'false') = 'true'
     AND coalesce(a.attributes->>'verification_method', '') = ''
     AND NOT EXISTS (SELECT 1 FROM governance.links l WHERE l.to_artifact = a.artifact_id AND l.relation = 'verifies' AND NOT l.retired
                        AND NOT EXISTS (SELECT 1 FROM governance.links x WHERE x.retires_link = l.link_id)) $$;
GRANT EXECUTE ON FUNCTION governance.rg_orphan_rows(uuid[], text) TO eye_app, eye_commit;
CREATE OR REPLACE FUNCTION governance.rg_orphans(p_rule text, p_limit int, p_offset int) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  WITH o AS (SELECT * FROM governance.rg_orphan_rows(NULL, p_rule)),
  rules AS (SELECT r.rule_id, r.kind, r.relation, r.side, r.description, r.basis FROM governance.rg_link_rules() r
            UNION ALL SELECT 'RG-V01', 'requirement', 'verifies', 'in', 'a mandatory requirement with neither a verification method nor a verifying test', 'ES-03-001, ES-67-001')
  SELECT jsonb_build_object('evaluated_at', clock_timestamp(), 'total', (SELECT count(*) FROM o),
    'rules', (SELECT jsonb_agg(jsonb_build_object('rule_id', r.rule_id, 'kind', r.kind, 'relation', r.relation, 'side', r.side, 'description', r.description, 'basis', r.basis,
                 'count', (SELECT count(*) FROM o WHERE o.rule_id = r.rule_id),
                 'orphans', (SELECT coalesce(jsonb_agg(jsonb_build_object('artifact_id', x.artifact_id, 'kind', x.kind, 'key', x.external_key, 'title', x.title) ORDER BY x.external_key), '[]'::jsonb)
                               FROM (SELECT * FROM o WHERE o.rule_id = r.rule_id ORDER BY o.external_key, o.artifact_id LIMIT least(greatest(coalesce(p_limit, 25), 0), 500) OFFSET greatest(coalesce(p_offset, 0), 0)) x))
               ORDER BY r.rule_id) FROM rules r WHERE p_rule IS NULL OR r.rule_id = p_rule)) $$;
GRANT EXECUTE ON FUNCTION governance.rg_orphans(text, int, int) TO eye_app, eye_commit;

/* The OBLIGATION strength of a requirement (SHALL / MUST > SHOULD > MAY) and the threshold's strictness, for the "never weaken" rule. */
CREATE OR REPLACE FUNCTION governance.rg_strength(p_attributes jsonb) RETURNS int
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$ SELECT CASE upper(coalesce(p_attributes->>'obligation', ''))
  WHEN 'SHALL' THEN 3 WHEN 'MUST' THEN 3 WHEN 'SHALL NOT' THEN 3 WHEN 'MUST NOT' THEN 3 WHEN 'SHOULD' THEN 2 WHEN 'SHOULD NOT' THEN 2 WHEN 'MAY' THEN 1 ELSE NULL END $$;
/* Does the child's declared threshold weaken the parent's? ({value, direction: min|max}: a `min` threshold weakens when lower, a `max` when higher.) */
CREATE OR REPLACE FUNCTION governance.rg_weakens(p_child jsonb, p_parent jsonb) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE c jsonb := p_child->'threshold'; p jsonb := p_parent->'threshold';
BEGIN
  IF governance.rg_strength(p_parent) IS NOT NULL AND (governance.rg_strength(p_child) IS NULL OR governance.rg_strength(p_child) < governance.rg_strength(p_parent)) THEN
    RETURN format('the obligation %s is weaker than the parent''s %s', coalesce(p_child->>'obligation', '<none>'), p_parent->>'obligation');
  END IF;
  IF p IS NOT NULL AND jsonb_typeof(p) = 'object' THEN
    IF c IS NULL OR jsonb_typeof(c) <> 'object' OR c->>'direction' IS DISTINCT FROM p->>'direction' OR jsonb_typeof(c->'value') <> 'number' THEN
      RETURN 'the parent declares an acceptance threshold the derived requirement does not carry in the same direction';
    END IF;
    IF (p->>'direction' = 'min' AND (c->>'value')::numeric < (p->>'value')::numeric) OR (p->>'direction' = 'max' AND (c->>'value')::numeric > (p->>'value')::numeric) THEN
      RETURN format('the threshold %s (%s) is weaker than the parent''s %s', c->>'value', c->>'direction', p->>'value');
    END IF;
  END IF;
  RETURN NULL;
END $$;
GRANT EXECUTE ON FUNCTION governance.rg_strength(jsonb), governance.rg_weakens(jsonb, jsonb) TO eye_app, eye_commit;

/* THE LINT (ES-02-001, ES-03-002/-003, IA-02-003, DP-02-003, PR-08-003): every live link that breaks the control order (supersedes, governs,
   derives_from, part_of: the controlling end must control); every derived requirement that weakens its parent; every requirement whose text
   carries more than one controlling obligation (compound — ES-03-002, as the importer counted it); every normative artifact without a
   declared owner; every circular derivation. Listed, counted — never fixed by inference. */
CREATE OR REPLACE FUNCTION governance.rg_lint(p_limit int) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  WITH live AS (SELECT l.* FROM governance.links l WHERE NOT l.retired AND NOT EXISTS (SELECT 1 FROM governance.links x WHERE x.retires_link = l.link_id)
                  AND l.relation IN ('supersedes', 'governs', 'derives_from', 'part_of')),
  pairs AS (SELECT l.link_id, l.relation, f.artifact_id AS from_id, f.external_key AS from_key, f.authority_class AS from_class, f.attributes AS from_attrs, f.kind AS from_kind,
                   t.artifact_id AS to_id, t.external_key AS to_key, t.authority_class AS to_class, t.attributes AS to_attrs, t.kind AS to_kind
              FROM live l JOIN governance.artifacts f ON f.artifact_id = l.from_artifact AND f.superseded_at IS NULL
                          JOIN governance.artifacts t ON t.artifact_id = l.to_artifact AND t.superseded_at IS NULL),
  order_v AS (SELECT p.*, CASE p.relation WHEN 'governs' THEN NOT governance.rg_controls(p.from_class, p.to_class)
                                         WHEN 'supersedes' THEN NOT governance.rg_controls(p.from_class, p.to_class)
                                         ELSE NOT governance.rg_controls(p.to_class, p.from_class) END AS bad FROM pairs p),
  weak AS (SELECT p.*, governance.rg_weakens(p.from_attrs, p.to_attrs) AS why FROM pairs p WHERE p.relation = 'derives_from' AND p.from_kind = 'requirement' AND p.to_kind = 'requirement'),
  compound AS (SELECT a.artifact_id, a.external_key FROM governance.artifacts a WHERE a.kind = 'requirement' AND a.superseded_at IS NULL AND coalesce((a.attributes->>'obligations')::int, 0) > 1),
  ownerless AS (SELECT a.artifact_id, a.kind, a.external_key FROM governance.artifacts a WHERE a.superseded_at IS NULL AND a.scope = 'PLATFORM' AND a.lifecycle IN ('active', 'proposed')
                  AND a.kind IN ('requirement', 'standard', 'capability', 'journey', 'policy_bundle', 'decision_record', 'component', 'interface', 'schema')
                  AND a.owner_principal_id IS NULL AND a.owner_role IS NULL AND coalesce(a.attributes->>'owner_declared', '') = ''),
  cyc AS (
    WITH RECURSIVE w(start, node, path, cyc) AS (
      SELECT l.from_artifact, l.to_artifact, ARRAY[l.from_artifact, l.to_artifact], l.from_artifact = l.to_artifact
        FROM live l WHERE l.relation IN ('derives_from', 'supersedes', 'part_of')
      UNION ALL
      SELECT w.start, l.to_artifact, w.path || l.to_artifact, l.to_artifact = ANY (w.path)
        FROM w JOIN live l ON l.from_artifact = w.node AND l.relation IN ('derives_from', 'supersedes', 'part_of')
       WHERE NOT w.cyc AND cardinality(w.path) < 24)
    SELECT DISTINCT start FROM w WHERE cyc AND node = start)
  SELECT jsonb_build_object('evaluated_at', clock_timestamp(),
    'control_order', jsonb_build_object('count', (SELECT count(*) FROM order_v WHERE bad), 'findings', (SELECT coalesce(jsonb_agg(jsonb_build_object('link_id', o.link_id, 'relation', o.relation,
         'from', o.from_key, 'from_class', o.from_class, 'to', o.to_key, 'to_class', o.to_class) ORDER BY o.from_key, o.to_key), '[]'::jsonb)
         FROM (SELECT * FROM order_v WHERE bad ORDER BY from_key, to_key LIMIT coalesce(p_limit, 50)) o)),
    'weakening', jsonb_build_object('count', (SELECT count(*) FROM weak WHERE why IS NOT NULL), 'findings', (SELECT coalesce(jsonb_agg(jsonb_build_object('link_id', w.link_id, 'from', w.from_key, 'to', w.to_key, 'why', w.why) ORDER BY w.from_key), '[]'::jsonb)
         FROM (SELECT * FROM weak WHERE why IS NOT NULL ORDER BY from_key LIMIT coalesce(p_limit, 50)) w)),
    'compound', jsonb_build_object('count', (SELECT count(*) FROM compound), 'sample', (SELECT coalesce(jsonb_agg(c.external_key ORDER BY c.external_key), '[]'::jsonb)
         FROM (SELECT * FROM compound ORDER BY external_key LIMIT coalesce(p_limit, 50)) c)),
    'ownerless', jsonb_build_object('count', (SELECT count(*) FROM ownerless), 'sample', (SELECT coalesce(jsonb_agg(jsonb_build_object('kind', o.kind, 'key', o.external_key) ORDER BY o.kind, o.external_key), '[]'::jsonb)
         FROM (SELECT * FROM ownerless ORDER BY kind, external_key LIMIT coalesce(p_limit, 50)) o)),
    'circular', jsonb_build_object('count', (SELECT count(*) FROM cyc), 'artifacts', (SELECT coalesce(jsonb_agg(c.start ORDER BY c.start), '[]'::jsonb) FROM cyc c))) $$;
GRANT EXECUTE ON FUNCTION governance.rg_lint(int) TO eye_app, eye_commit;

/* Is a test's verification CURRENT? The newest record evidencing the test's CURRENT version, passed, unexpired, not invalidated. */
CREATE OR REPLACE FUNCTION governance.rg_test_evidence(p_test uuid) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce((SELECT jsonb_build_object('record_id', r.record_id, 'status', c.status, 'ingested_at', r.ingested_at, 'valid_until', r.valid_until,
            'current', c.test_version = t.version AND c.status = 'passed' AND r.valid_until > clock_timestamp()
                       AND NOT EXISTS (SELECT 1 FROM governance.rg_invalidations i WHERE i.record_id = r.record_id),
            'expired', r.valid_until <= clock_timestamp(), 'invalidated', EXISTS (SELECT 1 FROM governance.rg_invalidations i WHERE i.record_id = r.record_id),
            'version_moved', c.test_version <> t.version)
         FROM governance.rg_verification_cases c JOIN governance.rg_verification_records r ON r.record_id = c.record_id
         JOIN governance.artifacts t ON t.artifact_id = c.test_artifact AND t.superseded_at IS NULL
        WHERE c.test_artifact = p_test ORDER BY r.ingested_at DESC, r.record_id LIMIT 1),
    jsonb_build_object('record_id', NULL, 'current', false, 'status', 'never_verified')) $$;
GRANT EXECUTE ON FUNCTION governance.rg_test_evidence(uuid) TO eye_app, eye_commit;

/* INHERITANCE (IA-06-005, DP-07-005, PR-08-005, V04-T-017, V06-T-008): the artifact's upward chain must reach a CONSTITUTIONAL authority,
   without a cycle, with every link current (no end moved since it was asserted, no end retired, superseded or quarantined), verifiable
   (a requirement: a method or a verifying test; a test: current passing evidence), free of a declared conflict and of a control-order
   break. The highest controlling authority among the chain is named; the affected capabilities, journeys and release candidates (the
   downward walk) are exposed. A finding never makes a guess: an unreachable anchor reads `incomplete`. */
CREATE OR REPLACE FUNCTION governance.rg_inheritance(p_artifact uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE a governance.artifacts; v_up jsonb; v_down jsonb; v_findings jsonb := '[]'::jsonb; v_ids uuid[]; v_ctrl jsonb; v_ev jsonb;
BEGIN
  SELECT * INTO a FROM governance.artifacts WHERE artifact_id = p_artifact AND superseded_at IS NULL;
  IF a.artifact_id IS NULL THEN RAISE EXCEPTION 'trace link rejected (unknown_artifact): no current artifact %', p_artifact USING ERRCODE = '22023'; END IF;
  v_up := governance.rg_walk(ARRAY[p_artifact], 'up', 10, NULL, 2000);
  v_down := governance.rg_walk(ARRAY[p_artifact], 'down', 6, NULL, 2000);
  v_ids := ARRAY(SELECT (n->>'artifact_id')::uuid FROM jsonb_array_elements(v_up->'nodes') n) || p_artifact;
  -- incomplete: no constitutional authority up the chain (a constitutional artifact anchors itself)
  IF a.authority_class IS DISTINCT FROM 'constitutional' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_up->'nodes') n WHERE n->>'authority_class' = 'constitutional') THEN
    v_findings := v_findings || jsonb_build_array(jsonb_build_object('class', 'incomplete', 'detail', 'the upward chain reaches no constitutional authority (Volume 0)',
      'artifacts', (SELECT coalesce(jsonb_agg(n->>'key' ORDER BY (n->>'depth')::int, n->>'key'), '[]'::jsonb) FROM jsonb_array_elements(v_up->'nodes') n)));
  END IF;
  IF jsonb_array_length(v_up->'back_to_root') > 0 THEN
    v_findings := v_findings || jsonb_build_array(jsonb_build_object('class', 'circular', 'detail', 'the chain returns to the artifact itself', 'artifacts', v_up->'back_to_root'));
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_up->'nodes') n WHERE (n->>'stale')::boolean OR n->>'lifecycle' IN ('retired', 'superseded', 'quarantined')) THEN
    v_findings := v_findings || jsonb_build_array(jsonb_build_object('class', 'stale', 'detail', 'an authority up the chain moved since the link was asserted, or is retired, superseded or quarantined',
      'artifacts', (SELECT jsonb_agg(n->>'key' ORDER BY n->>'key') FROM jsonb_array_elements(v_up->'nodes') n WHERE (n->>'stale')::boolean OR n->>'lifecycle' IN ('retired', 'superseded', 'quarantined'))));
  END IF;
  IF a.kind = 'requirement' AND coalesce(a.attributes->>'verification_method', '') = ''
     AND NOT EXISTS (SELECT 1 FROM governance.links_live l WHERE l.to_artifact = p_artifact AND l.relation = 'verifies') THEN
    v_findings := v_findings || jsonb_build_array(jsonb_build_object('class', 'unverifiable', 'detail', 'neither a verification method nor a verifying test (ES-03-001)', 'artifacts', jsonb_build_array(a.external_key)));
  ELSIF a.kind = 'test' THEN
    v_ev := governance.rg_test_evidence(p_artifact);
    IF NOT coalesce((v_ev->>'current')::boolean, false) THEN
      v_findings := v_findings || jsonb_build_array(jsonb_build_object('class', 'unverifiable', 'detail', 'no current passing evidence for this test version', 'evidence', v_ev));
    END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM governance.links_live l WHERE l.relation = 'conflicts_with' AND l.from_artifact = ANY (v_ids) AND l.to_artifact = ANY (v_ids)) THEN
    v_findings := v_findings || jsonb_build_array(jsonb_build_object('class', 'conflicting', 'detail', 'a declared conflict inside the chain; the highest controlling authority decides',
      'links', (SELECT jsonb_agg(l.link_id) FROM governance.links_live l WHERE l.relation = 'conflicts_with' AND l.from_artifact = ANY (v_ids) AND l.to_artifact = ANY (v_ids))));
  END IF;
  IF EXISTS (SELECT 1 FROM governance.links_live l JOIN governance.artifacts f ON f.artifact_id = l.from_artifact AND f.superseded_at IS NULL
                     JOIN governance.artifacts t ON t.artifact_id = l.to_artifact AND t.superseded_at IS NULL
              WHERE l.from_artifact = ANY (v_ids) AND l.relation IN ('derives_from', 'part_of') AND NOT governance.rg_controls(t.authority_class, f.authority_class)) THEN
    v_findings := v_findings || jsonb_build_array(jsonb_build_object('class', 'control_order', 'detail', 'a lower authority is placed above a higher one in the chain'));
  END IF;
  SELECT jsonb_build_object('artifact_id', x.artifact_id, 'key', x.external_key, 'authority_class', x.authority_class, 'rank', governance.rg_authority_rank(x.authority_class)) INTO v_ctrl
    FROM governance.artifacts x WHERE x.artifact_id = ANY (v_ids) AND x.superseded_at IS NULL AND governance.rg_authority_rank(x.authority_class) IS NOT NULL
   ORDER BY governance.rg_authority_rank(x.authority_class), x.external_key LIMIT 1;
  RETURN jsonb_build_object('artifact', jsonb_build_object('artifact_id', a.artifact_id, 'kind', a.kind, 'key', a.external_key, 'version', a.version, 'authority_class', a.authority_class),
    'conformant', jsonb_array_length(v_findings) = 0, 'findings', v_findings, 'controlling_authority', v_ctrl, 'upward', v_up->'count',
    'affected', jsonb_build_object(
      'capabilities', (SELECT coalesce(jsonb_agg(jsonb_build_object('artifact_id', n->>'artifact_id', 'key', n->>'key') ORDER BY n->>'key'), '[]'::jsonb) FROM jsonb_array_elements(v_down->'nodes') n WHERE n->>'kind' = 'capability'),
      'journeys', (SELECT coalesce(jsonb_agg(jsonb_build_object('artifact_id', n->>'artifact_id', 'key', n->>'key') ORDER BY n->>'key'), '[]'::jsonb) FROM jsonb_array_elements(v_down->'nodes') n WHERE n->>'kind' = 'journey'),
      'release_candidates', (SELECT coalesce(jsonb_agg(jsonb_build_object('artifact_id', n->>'artifact_id', 'key', n->>'key') ORDER BY n->>'key'), '[]'::jsonb) FROM jsonb_array_elements(v_down->'nodes') n WHERE n->>'kind' = 'release_candidate'),
      'decision_active', (SELECT coalesce(jsonb_agg(jsonb_build_object('artifact_id', n->>'artifact_id', 'key', n->>'key') ORDER BY n->>'key'), '[]'::jsonb) FROM jsonb_array_elements(v_down->'nodes') n WHERE n->>'kind' IN ('data_product', 'decision_record', 'acceptance_record')),
      'services', (SELECT coalesce(jsonb_agg(jsonb_build_object('artifact_id', n->>'artifact_id', 'key', n->>'key') ORDER BY n->>'key'), '[]'::jsonb) FROM jsonb_array_elements(v_down->'nodes') n WHERE n->>'kind' IN ('component', 'deployable_unit', 'interface'))),
    'open_holds', (SELECT coalesce(jsonb_agg(jsonb_build_object('hold_id', h.hold_id, 'reason_kind', h.reason_kind, 'reason', h.reason, 'opened_at', h.opened_at) ORDER BY h.opened_at), '[]'::jsonb)
                     FROM governance.holds h WHERE h.subject_artifact = p_artifact AND h.lifted_at IS NULL));
END $$;
GRANT EXECUTE ON FUNCTION governance.rg_inheritance(uuid) TO eye_app, eye_commit;

/* Has a recorded impact been CLEARED? Every stale test it named has, since the impact, current passing evidence for its current version. */
CREATE OR REPLACE FUNCTION governance.rg_impact_open(p_impact uuid) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce(jsonb_agg(s->>'key' ORDER BY s->>'key'), '[]'::jsonb)
    FROM governance.rg_impacts i, jsonb_array_elements(i.stale_verifications) s
   WHERE i.impact_id = p_impact AND s->>'kind' = 'test'
     AND NOT EXISTS (SELECT 1 FROM governance.rg_verification_cases c JOIN governance.rg_verification_records r ON r.record_id = c.record_id
                       JOIN governance.artifacts t ON t.artifact_id = c.test_artifact AND t.superseded_at IS NULL
                      WHERE c.test_artifact = (s->>'artifact_id')::uuid AND r.ingested_at > i.recorded_at AND c.status = 'passed' AND c.test_version = t.version
                        AND r.valid_until > clock_timestamp() AND NOT EXISTS (SELECT 1 FROM governance.rg_invalidations v WHERE v.record_id = r.record_id)) $$;
GRANT EXECUTE ON FUNCTION governance.rg_impact_open(uuid) TO eye_app, eye_commit;

/* THE ADMISSION CHECK (IA-02-006, IA-06-006, DP-02-006, DP-07-006 — the construction half; production admission is R1): the subject and its
   upward closure — orphans among them, open holds on any, stale links, requirements with no verification, tests with no current evidence. */
CREATE OR REPLACE FUNCTION governance.rg_admission_check(p_subject uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE a governance.artifacts; v_up jsonb; v_ids uuid[]; v_blocking jsonb := '[]'::jsonb; v_x jsonb;
BEGIN
  SELECT * INTO a FROM governance.artifacts WHERE artifact_id = p_subject AND superseded_at IS NULL;
  IF a.artifact_id IS NULL THEN RAISE EXCEPTION 'trace link rejected (unknown_artifact): no current artifact %', p_subject USING ERRCODE = '22023'; END IF;
  v_up := governance.rg_walk(ARRAY[p_subject], 'up', 10, NULL, 5000);
  v_ids := ARRAY(SELECT (n->>'artifact_id')::uuid FROM jsonb_array_elements(v_up->'nodes') n) || p_subject;
  IF (v_up->>'truncated')::boolean THEN v_blocking := v_blocking || jsonb_build_array(jsonb_build_object('class', 'truncated', 'detail', 'the closure exceeded 5000 artifacts; nothing is inferred beyond it')); END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('rule_id', o.rule_id, 'key', o.external_key) ORDER BY o.rule_id, o.external_key), '[]'::jsonb) INTO v_x FROM governance.rg_orphan_rows(v_ids, NULL) o;
  IF jsonb_array_length(v_x) > 0 THEN v_blocking := v_blocking || jsonb_build_array(jsonb_build_object('class', 'orphans', 'items', v_x)); END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('hold_id', h.hold_id, 'subject', h.subject_artifact, 'reason_kind', h.reason_kind, 'reason', h.reason) ORDER BY h.opened_at), '[]'::jsonb) INTO v_x
    FROM governance.holds h WHERE h.subject_artifact = ANY (v_ids) AND h.lifted_at IS NULL;
  IF jsonb_array_length(v_x) > 0 THEN v_blocking := v_blocking || jsonb_build_array(jsonb_build_object('class', 'held', 'items', v_x)); END IF;
  SELECT coalesce(jsonb_agg(n->>'key' ORDER BY n->>'key'), '[]'::jsonb) INTO v_x FROM jsonb_array_elements(v_up->'nodes') n WHERE (n->>'stale')::boolean OR n->>'lifecycle' IN ('retired', 'superseded', 'quarantined');
  IF jsonb_array_length(v_x) > 0 THEN v_blocking := v_blocking || jsonb_build_array(jsonb_build_object('class', 'stale', 'items', v_x)); END IF;
  -- the tests in the closure AND every test verifying an artifact of it: each needs current passing evidence for its current version
  SELECT coalesce(jsonb_agg(t.external_key ORDER BY t.external_key), '[]'::jsonb) INTO v_x FROM governance.artifacts t
   WHERE t.superseded_at IS NULL AND t.kind = 'test' AND t.lifecycle = 'active'
     AND (t.artifact_id = ANY (v_ids) OR t.artifact_id IN (SELECT l.from_artifact FROM governance.links_live l WHERE l.relation = 'verifies' AND l.to_artifact = ANY (v_ids)))
     AND NOT coalesce((governance.rg_test_evidence(t.artifact_id)->>'current')::boolean, false);
  IF jsonb_array_length(v_x) > 0 THEN v_blocking := v_blocking || jsonb_build_array(jsonb_build_object('class', 'unverified_tests', 'items', v_x)); END IF;
  RETURN jsonb_build_object('subject', jsonb_build_object('artifact_id', a.artifact_id, 'kind', a.kind, 'key', a.external_key, 'version', a.version, 'digest', a.digest),
    'closure', cardinality(v_ids), 'admissible', jsonb_array_length(v_blocking) = 0, 'blocking', v_blocking, 'claim', 'construction',
    'production_admission', 'R1 — production admission and continued operation are external; this check is the construction half and admits nothing to production',
    'evaluated_at', clock_timestamp());
END $$;
GRANT EXECUTE ON FUNCTION governance.rg_admission_check(uuid) TO eye_app, eye_commit;

/* THE REGISTRY SNAPSHOT (ES-06-002): the current versions of the named kinds and their digest — a release candidate records the requirement set
   it was built from by this digest (§CM). */
CREATE OR REPLACE FUNCTION governance.rg_snapshot(p_kinds text[]) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT jsonb_build_object('kinds', to_jsonb(p_kinds), 'as_of', clock_timestamp(), 'count', count(*),
    'digest', governance.digest(coalesce(jsonb_agg(jsonb_build_array(a.artifact_id, a.version, a.digest, a.lifecycle) ORDER BY a.artifact_id), '[]'::jsonb)))
    FROM governance.artifacts a WHERE a.superseded_at IS NULL AND a.scope = 'PLATFORM' AND a.kind = ANY (coalesce(p_kinds, ARRAY['requirement'])) $$;
GRANT EXECUTE ON FUNCTION governance.rg_snapshot(text[]) TO eye_app, eye_commit;

-- §RG.6 THE PORTS (SECURITY DEFINER; PLATFORM; the action asserted first, then the scope and the acting principal) ────────────────────────────
/* IMPORT one source (ES-03-001..004, ES-67-001, PR-08-002, ADR-004): the steward's governed write of what the TS reader parsed. The source's
   sha256 decides the fast path (the same digest and parser → nothing written: idempotent); otherwise every row is diffed (set-based):
   new → version 1, changed → n+1 (the old one superseded, resolvable), gone → a RETIRED version; the source's links re-asserted over the
   current versions of their ends, the ones it no longer declares retired by a later row; unresolved link ends are listed, never guessed. */
CREATE OR REPLACE FUNCTION governance.rg_import(p_source_kind text, p_source_path text, p_source_digest text, p_parser text, p_detail jsonb, p_items jsonb, p_links jsonb,
  p_build jsonb, p_actor uuid, p_import_id uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE prev governance.rg_imports%ROWTYPE; v_now timestamptz := clock_timestamp(); v_bad text; v_new int := 0; v_versioned int := 0; v_retired int := 0; v_unchanged int := 0;
        v_links_added int := 0; v_links_retired int := 0; v_unres jsonb; v_unres_n int; v_changed uuid[]; v_normative uuid[]; v_row governance.rg_imports%ROWTYPE; v_n int;
        c_kinds CONSTANT text[] := ARRAY['requirement', 'standard', 'capability', 'journey', 'feature', 'decision_record', 'exception', 'interface', 'schema'];
BEGIN
  PERFORM governance.assert_platform('governance.registry.import', p_actor, 'requirement registry');
  IF p_source_kind IS NULL OR p_source_kind NOT IN ('requirements', 'rowmap', 'decisions', 'exceptions', 'interfaces', 'schemas') THEN
    RAISE EXCEPTION 'requirement registry rejected (source): % is not a registered source kind', coalesce(p_source_kind, '<null>') USING ERRCODE = '22023';
  END IF;
  IF p_source_path IS NULL OR p_source_path !~ '^[A-Za-z0-9_][A-Za-z0-9_./-]{0,199}$' OR p_source_path ~ '\.\.' THEN
    RAISE EXCEPTION 'requirement registry rejected (source): the source is a repository-relative path' USING ERRCODE = '22023';
  END IF;
  IF p_source_digest IS NULL OR p_source_digest !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'requirement registry rejected (digest): the source''s sha256 is 64 hex' USING ERRCODE = '22023'; END IF;
  IF p_parser IS NULL OR length(p_parser) NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'requirement registry rejected (parser): the parser version is named' USING ERRCODE = '22023'; END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) > 20000 THEN RAISE EXCEPTION 'requirement registry rejected (items): at most 20000 rows per source' USING ERRCODE = '22023'; END IF;
  IF p_links IS NULL OR jsonb_typeof(p_links) <> 'array' OR jsonb_array_length(p_links) > 60000 THEN RAISE EXCEPTION 'requirement registry rejected (links): at most 60000 links per source' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.rg_import:' || p_source_path, 0));
  SELECT * INTO prev FROM governance.rg_imports i WHERE i.source_path = p_source_path ORDER BY i.imported_at DESC, i.import_id DESC LIMIT 1;
  -- the fast path: the same bytes and parser, and nothing the last import left unresolved (a link end that a LATER source registers is
  -- resolved by re-diffing — which writes nothing when nothing resolves)
  IF prev.import_id IS NOT NULL AND prev.source_digest = p_source_digest AND prev.parser_version = p_parser AND jsonb_array_length(prev.unresolved) = 0 THEN
    RETURN jsonb_build_object('unchanged', true, 'source_path', p_source_path, 'source_digest', p_source_digest, 'import', to_jsonb(prev) - 'changed');
  END IF;

  -- the rows: well-formed, one per (kind, key), never another part's kind, the class the volume carries (PR-08-003)
  SELECT CASE
      WHEN i.k IS NULL OR length(btrim(i.k)) NOT BETWEEN 1 AND 200 THEN 'a row has no key (1–200 characters)'
      WHEN i.kind IS NULL OR NOT (i.kind = ANY (c_kinds)) THEN format('%s: the kind %s is not imported by this registry', i.k, coalesce(i.kind, '<null>'))
      WHEN i.title IS NULL OR length(btrim(i.title)) NOT BETWEEN 1 AND 500 THEN format('%s: the title is 1–500 characters', i.k)
      WHEN governance.rg_authority_rank(i.authority_class) IS NULL THEN format('%s: the authority class %s is not in the control order', i.k, coalesce(i.authority_class, '<null>'))
      WHEN i.controlling_volume IS NOT NULL AND governance.rg_volume_class(i.controlling_volume) IS NOT NULL AND i.kind IN ('requirement', 'standard')
           AND governance.rg_volume_class(i.controlling_volume) <> i.authority_class THEN format('%s: a %s row carries %s authority, never %s (PR-08-003)', i.k, i.controlling_volume, governance.rg_volume_class(i.controlling_volume), i.authority_class)
      WHEN coalesce(i.lifecycle, 'active') NOT IN ('proposed', 'active', 'deprecated', 'retired') THEN format('%s: an imported row is proposed, active, deprecated or retired', i.k)
      WHEN i.attributes IS NOT NULL AND jsonb_typeof(i.attributes) <> 'object' THEN format('%s: attributes are an object', i.k)
      WHEN i.owner_role IS NOT NULL AND NOT EXISTS (SELECT 1 FROM identity.roles r WHERE r.code = i.owner_role) THEN format('%s: the owner role %s is unknown', i.k, i.owner_role)
    END INTO v_bad
    FROM jsonb_to_recordset(p_items) AS i(kind text, k text, title text, authority_class text, controlling_volume text, lifecycle text, attributes jsonb, owner_role text)
   WHERE i.k IS NULL OR i.kind IS NULL OR NOT (i.kind = ANY (c_kinds)) OR i.title IS NULL OR length(btrim(i.title)) NOT BETWEEN 1 AND 500 OR length(btrim(i.k)) NOT BETWEEN 1 AND 200
      OR governance.rg_authority_rank(i.authority_class) IS NULL OR coalesce(i.lifecycle, 'active') NOT IN ('proposed', 'active', 'deprecated', 'retired')
      OR (i.controlling_volume IS NOT NULL AND governance.rg_volume_class(i.controlling_volume) IS NOT NULL AND i.kind IN ('requirement', 'standard') AND governance.rg_volume_class(i.controlling_volume) <> i.authority_class)
      OR (i.attributes IS NOT NULL AND jsonb_typeof(i.attributes) <> 'object')
      OR (i.owner_role IS NOT NULL AND NOT EXISTS (SELECT 1 FROM identity.roles r WHERE r.code = i.owner_role))
   LIMIT 1;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'requirement registry rejected (items): %', v_bad USING ERRCODE = '22023'; END IF;
  SELECT format('%s %s', x.kind, x.k) INTO v_bad FROM jsonb_to_recordset(p_items) AS x(kind text, k text) GROUP BY x.kind, x.k HAVING count(*) > 1 LIMIT 1;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'requirement registry rejected (items): % appears twice in one source', v_bad USING ERRCODE = '22023'; END IF;
  SELECT format('%s %s', a.kind, a.external_key) INTO v_bad FROM jsonb_to_recordset(p_items) AS x(kind text, k text)
    JOIN governance.artifacts a ON a.kind = x.kind AND a.external_key = x.k AND a.scope = 'PLATFORM' AND a.superseded_at IS NULL AND a.artifact_id <> governance.rg_artifact_id(x.kind, x.k) LIMIT 1;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'requirement registry rejected (duplicate): % is registered under another identity', v_bad USING ERRCODE = '23505'; END IF;

  -- the diff (set-based): what is new, what changed, what is unchanged
  CREATE TEMP TABLE IF NOT EXISTS pg_temp.rg_inc (id uuid PRIMARY KEY, kind text, k text, title text, authority_class text, controlling_volume text, lifecycle text, attributes jsonb,
                                          owner_role text, digest text, cur_version int, cur_digest text, state text) ON COMMIT DROP;
  TRUNCATE pg_temp.rg_inc;
  INSERT INTO pg_temp.rg_inc (id, kind, k, title, authority_class, controlling_volume, lifecycle, attributes, owner_role, digest, cur_version, cur_digest, state)
  SELECT governance.rg_artifact_id(i.kind, i.k), i.kind, i.k, btrim(i.title), i.authority_class, i.controlling_volume, coalesce(i.lifecycle, 'active'), coalesce(i.attributes, '{}'::jsonb), i.owner_role,
         governance.rg_content_digest(i.kind, i.k, btrim(i.title), i.authority_class, i.controlling_volume, coalesce(i.attributes, '{}'::jsonb)), a.version, a.digest,
         CASE WHEN a.artifact_id IS NULL THEN 'new'
              WHEN a.digest = governance.rg_content_digest(i.kind, i.k, btrim(i.title), i.authority_class, i.controlling_volume, coalesce(i.attributes, '{}'::jsonb))
                   AND a.lifecycle = coalesce(i.lifecycle, 'active') AND a.attributes = coalesce(i.attributes, '{}'::jsonb) AND a.title = btrim(i.title)
                   AND a.owner_role IS NOT DISTINCT FROM i.owner_role AND a.source->>'path' IS NOT DISTINCT FROM p_source_path THEN 'unchanged'
              ELSE 'changed' END
    FROM jsonb_to_recordset(p_items) AS i(kind text, k text, title text, authority_class text, controlling_volume text, lifecycle text, attributes jsonb, owner_role text)
    LEFT JOIN governance.artifacts a ON a.artifact_id = governance.rg_artifact_id(i.kind, i.k) AND a.superseded_at IS NULL;
  SELECT count(*) FILTER (WHERE state = 'new'), count(*) FILTER (WHERE state = 'changed'), count(*) FILTER (WHERE state = 'unchanged') INTO v_new, v_versioned, v_unchanged FROM pg_temp.rg_inc;
  v_normative := ARRAY(SELECT id FROM pg_temp.rg_inc WHERE state = 'changed' AND cur_digest IS DISTINCT FROM digest ORDER BY id);
  UPDATE governance.artifacts a SET superseded_at = v_now FROM pg_temp.rg_inc i WHERE i.state = 'changed' AND a.artifact_id = i.id AND a.superseded_at IS NULL;
  INSERT INTO governance.artifacts (artifact_id, version, scope, kind, external_key, title, owner_role, authority_class, controlling_volume, lifecycle, attributes, source, digest,
                                    effective_from, recorded_by, correlation_id)
  SELECT i.id, coalesce(i.cur_version, 0) + 1, 'PLATFORM', i.kind, i.k, i.title, i.owner_role, i.authority_class, i.controlling_volume, i.lifecycle, i.attributes,
         jsonb_build_object('path', p_source_path, 'source_digest', p_source_digest, 'import_id', p_import_id), i.digest, v_now, p_actor, p_correlation
    FROM pg_temp.rg_inc i WHERE i.state IN ('new', 'changed');
  -- what the source no longer declares: a RETIRED version (never deleted; resolvable as of its time)
  CREATE TEMP TABLE IF NOT EXISTS pg_temp.rg_gone (id uuid PRIMARY KEY) ON COMMIT DROP;
  TRUNCATE pg_temp.rg_gone;
  INSERT INTO pg_temp.rg_gone SELECT a.artifact_id FROM governance.artifacts a
   WHERE a.superseded_at IS NULL AND a.scope = 'PLATFORM' AND a.source->>'path' = p_source_path AND a.lifecycle <> 'retired' AND a.kind = ANY (c_kinds)
     AND NOT EXISTS (SELECT 1 FROM pg_temp.rg_inc i WHERE i.id = a.artifact_id);
  GET DIAGNOSTICS v_retired = ROW_COUNT;
  IF v_retired > 0 THEN
    CREATE TEMP TABLE IF NOT EXISTS pg_temp.rg_gone_rows ON COMMIT DROP AS SELECT * FROM governance.artifacts WITH NO DATA;
    TRUNCATE pg_temp.rg_gone_rows;
    INSERT INTO pg_temp.rg_gone_rows SELECT a.* FROM governance.artifacts a JOIN pg_temp.rg_gone g ON g.id = a.artifact_id WHERE a.superseded_at IS NULL;
    UPDATE governance.artifacts a SET superseded_at = v_now FROM pg_temp.rg_gone g WHERE a.artifact_id = g.id AND a.superseded_at IS NULL;
    INSERT INTO governance.artifacts (artifact_id, version, scope, kind, external_key, title, owner_principal_id, owner_role, authority_class, controlling_volume, lifecycle, attributes,
                                      source, digest, effective_from, recorded_by, correlation_id)
    SELECT r.artifact_id, r.version + 1, 'PLATFORM', r.kind, r.external_key, r.title, r.owner_principal_id, r.owner_role, r.authority_class, r.controlling_volume, 'retired', r.attributes,
           r.source || jsonb_build_object('retired_by_import', p_import_id), r.digest, v_now, p_actor, p_correlation FROM pg_temp.rg_gone_rows r;
  END IF;
  v_changed := v_normative || ARRAY(SELECT id FROM pg_temp.rg_gone ORDER BY id);

  -- the links the source declares: resolved by (kind, key) to CURRENT artifacts (any source); unresolved ends listed
  CREATE TEMP TABLE IF NOT EXISTS pg_temp.rg_lnk (from_id uuid, to_id uuid, relation text, attributes jsonb, from_ok boolean, to_ok boolean, from_kind text, from_key text, to_kind text, to_key text) ON COMMIT DROP;
  TRUNCATE pg_temp.rg_lnk;
  INSERT INTO pg_temp.rg_lnk
  SELECT governance.rg_artifact_id(l.from_kind, l.from_key), governance.rg_artifact_id(l.to_kind, l.to_key), l.relation, coalesce(l.attributes, '{}'::jsonb),
         EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.artifact_id = governance.rg_artifact_id(l.from_kind, l.from_key) AND a.superseded_at IS NULL AND a.lifecycle <> 'retired'),
         EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.artifact_id = governance.rg_artifact_id(l.to_kind, l.to_key) AND a.superseded_at IS NULL AND a.lifecycle <> 'retired'),
         l.from_kind, l.from_key, l.to_kind, l.to_key
    FROM jsonb_to_recordset(p_links) AS l(from_kind text, from_key text, to_kind text, to_key text, relation text, attributes jsonb);
  SELECT format('%s → %s (%s)', from_key, to_key, coalesce(relation, '<null>')) INTO v_bad FROM pg_temp.rg_lnk
   WHERE relation IS NULL OR NOT (relation = ANY (governance.link_relations())) OR from_id = to_id OR governance.rg_relation_problem(relation, from_kind, to_kind) IS NOT NULL LIMIT 1;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'requirement registry rejected (links): % is not an admissible link', v_bad USING ERRCODE = '22023'; END IF;
  SELECT count(*), coalesce(jsonb_agg(jsonb_build_object('from', from_kind || ' ' || from_key, 'to', to_kind || ' ' || to_key, 'relation', relation) ORDER BY from_key, to_key) FILTER (WHERE rn <= 200), '[]'::jsonb)
    INTO v_unres_n, v_unres
    FROM (SELECT x.*, row_number() OVER (ORDER BY x.from_key, x.to_key, x.relation) AS rn FROM pg_temp.rg_lnk x WHERE NOT (x.from_ok AND x.to_ok)) u;
  DELETE FROM pg_temp.rg_lnk WHERE NOT (from_ok AND to_ok);
  -- keep an identical live link of this source; retire the ones it no longer declares (or whose ends moved), insert the new assertions
  CREATE TEMP TABLE IF NOT EXISTS pg_temp.rg_want (from_id uuid, to_id uuid, relation text, attributes jsonb, from_digest text, to_digest text, from_version int, to_version int, keep uuid) ON COMMIT DROP;
  TRUNCATE pg_temp.rg_want;
  INSERT INTO pg_temp.rg_want
  SELECT DISTINCT ON (w.from_id, w.to_id, w.relation) w.from_id, w.to_id, w.relation, w.attributes, f.digest, t.digest, f.version, t.version, NULL::uuid
    FROM pg_temp.rg_lnk w JOIN governance.artifacts f ON f.artifact_id = w.from_id AND f.superseded_at IS NULL JOIN governance.artifacts t ON t.artifact_id = w.to_id AND t.superseded_at IS NULL
   ORDER BY w.from_id, w.to_id, w.relation;
  UPDATE pg_temp.rg_want w SET keep = l.link_id FROM governance.links l
   WHERE l.attributes->>'source' = p_source_path AND NOT l.retired AND l.from_artifact = w.from_id AND l.to_artifact = w.to_id AND l.relation = w.relation
     AND l.attributes->>'from_digest' = w.from_digest AND l.attributes->>'to_digest' = w.to_digest AND l.attributes - 'source' - 'import_id' - 'from_version' - 'to_version' - 'from_digest' - 'to_digest' = w.attributes
     AND NOT EXISTS (SELECT 1 FROM governance.links x WHERE x.retires_link = l.link_id);
  INSERT INTO governance.links (link_id, scope, from_artifact, to_artifact, relation, retired, retires_link, attributes, recorded_by, correlation_id)
  SELECT gen_random_uuid(), 'PLATFORM', l.from_artifact, l.to_artifact, l.relation, true, l.link_id, jsonb_build_object('source', p_source_path, 'import_id', p_import_id, 'reason', 'no longer declared by the source over the current versions of its ends'),
         p_actor, p_correlation
    FROM governance.links l
   WHERE l.attributes->>'source' = p_source_path AND NOT l.retired AND NOT EXISTS (SELECT 1 FROM governance.links x WHERE x.retires_link = l.link_id)
     AND NOT EXISTS (SELECT 1 FROM pg_temp.rg_want w WHERE w.keep = l.link_id);
  GET DIAGNOSTICS v_links_retired = ROW_COUNT;
  INSERT INTO governance.links (link_id, scope, from_artifact, to_artifact, relation, attributes, recorded_by, correlation_id)
  SELECT gen_random_uuid(), 'PLATFORM', w.from_id, w.to_id, w.relation,
         w.attributes || jsonb_build_object('source', p_source_path, 'import_id', p_import_id, 'from_version', w.from_version, 'to_version', w.to_version, 'from_digest', w.from_digest, 'to_digest', w.to_digest),
         p_actor, p_correlation
    FROM pg_temp.rg_want w WHERE w.keep IS NULL;
  GET DIAGNOSTICS v_links_added = ROW_COUNT;

  -- the same bytes and parser, nothing new resolved: nothing is recorded (idempotent). A source whose bytes changed while nothing it declares
  -- did (a column this registry does not read) is still recorded, so its digest is current.
  IF prev.import_id IS NOT NULL AND prev.source_digest = p_source_digest AND prev.parser_version = p_parser
     AND v_new + v_versioned + v_retired + v_links_added + v_links_retired = 0 THEN
    RETURN jsonb_build_object('unchanged', true, 'source_path', p_source_path, 'source_digest', p_source_digest, 'import', to_jsonb(prev) - 'changed', 'unresolved_remaining', v_unres_n);
  END IF;
  INSERT INTO governance.rg_imports (import_id, source_kind, source_path, source_digest, parser_version, detail, row_count, counts, changed, unresolved, build_identity, imported_by, correlation_id)
  VALUES (p_import_id, p_source_kind, p_source_path, p_source_digest, p_parser, coalesce(p_detail, '{}'::jsonb), jsonb_array_length(p_items),
          jsonb_build_object('registered', v_new, 'versioned', v_versioned, 'retired', v_retired, 'unchanged', v_unchanged, 'normative_changes', cardinality(v_normative),
                             'links_declared', jsonb_array_length(p_links), 'links_added', v_links_added, 'links_retired', v_links_retired, 'unresolved', v_unres_n),
          v_changed, v_unres, coalesce(p_build, '{}'::jsonb) || governance.rg_build_identity(), p_actor, p_correlation)
  RETURNING * INTO v_row;
  PERFORM governance.ledger(NULL, NULL, 'registry_import', p_import_id, NULL, 'registry.imported', p_actor,
    jsonb_build_object('source_path', p_source_path, 'source_digest', p_source_digest, 'counts', v_row.counts), p_correlation);
  RETURN jsonb_build_object('unchanged', false, 'source_path', p_source_path, 'source_digest', p_source_digest, 'import', to_jsonb(v_row));
END $$;
REVOKE ALL ON FUNCTION governance.rg_import(text, text, text, text, jsonb, jsonb, jsonb, jsonb, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_import(text, text, text, text, jsonb, jsonb, jsonb, jsonb, uuid, uuid, uuid) TO eye_commit;

/* REGISTER one normative artifact (ES-02-001, ES-03-001..004, IA-02-001..003, DP-02-001..003, PR-08-003, ADR-004): identity (kind + key,
   never re-keyed, a retired identity never reused), authority class (a requirement or a standard carries its VOLUME's class — a Volume 8
   row never claims a higher authority), owner, lifecycle, version (expected — stale refused), effective time; a SUPERSESSION (the target
   of the same kind, controlled by the new artifact's class) and a PARENT (a derived requirement: the parent exists, controls it and is not
   weakened); a mandatory requirement names its verification method and states one controlling obligation. Unchanged → nothing written. */
CREATE OR REPLACE FUNCTION governance.rg_register(p_kind text, p_key text, p_expected_version int, p_title text, p_class text, p_volume text, p_lifecycle text, p_attributes jsonb,
  p_supersedes uuid, p_parent uuid, p_owner uuid, p_owner_role text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE cur governance.artifacts%ROWTYPE; sup governance.artifacts%ROWTYPE; par governance.artifacts%ROWTYPE; v_put jsonb; v_attrs jsonb := coalesce(p_attributes, '{}'::jsonb);
        v_why text; v_links jsonb := '[]'::jsonb; v_id uuid;
BEGIN
  PERFORM governance.assert_platform('governance.registry.register', p_actor, 'requirement registry');
  IF p_kind IS NULL OR p_kind NOT IN ('requirement', 'standard', 'capability', 'journey', 'feature', 'component', 'deployable_unit', 'interface', 'schema', 'policy_bundle', 'decision_record') THEN
    RAISE EXCEPTION 'requirement registry rejected (kind): % is registered by its own part, not by the registry', coalesce(p_kind, '<null>') USING ERRCODE = '22023';
  END IF;
  IF p_key IS NULL OR length(btrim(p_key)) NOT BETWEEN 1 AND 200 OR p_key <> btrim(p_key) THEN RAISE EXCEPTION 'requirement registry rejected (key): a stable key of 1–200 characters' USING ERRCODE = '22023'; END IF;
  IF p_title IS NULL OR length(btrim(p_title)) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'requirement registry rejected (title): a title of 1–500 characters' USING ERRCODE = '22023'; END IF;
  IF governance.rg_authority_rank(p_class) IS NULL THEN RAISE EXCEPTION 'requirement registry rejected (authority_class): % is not in the control order', coalesce(p_class, '<null>') USING ERRCODE = '22023'; END IF;
  IF p_kind IN ('requirement', 'standard') AND (p_volume IS NULL OR governance.rg_volume_class(p_volume) IS NULL) THEN
    RAISE EXCEPTION 'requirement registry rejected (volume): a % names its controlling volume (V0–V10)', p_kind USING ERRCODE = '22023';
  END IF;
  IF p_volume IS NOT NULL AND governance.rg_volume_class(p_volume) IS NOT NULL AND p_kind IN ('requirement', 'standard') AND governance.rg_volume_class(p_volume) <> p_class THEN
    RAISE EXCEPTION 'requirement registry rejected (control_order): a % row carries % authority — it never claims % (PR-08-003: a volume never redefines a higher authority)', p_volume, governance.rg_volume_class(p_volume), p_class USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_lifecycle, 'active') NOT IN ('proposed', 'active', 'deprecated') THEN RAISE EXCEPTION 'requirement registry rejected (lifecycle): a registration is proposed, active or deprecated (retirement is a supersession or the source''s)' USING ERRCODE = '22023'; END IF;
  IF jsonb_typeof(v_attrs) <> 'object' THEN RAISE EXCEPTION 'requirement registry rejected (attributes): attributes are an object' USING ERRCODE = '22023'; END IF;
  IF p_owner_role IS NOT NULL AND NOT EXISTS (SELECT 1 FROM identity.roles r WHERE r.code = p_owner_role) THEN RAISE EXCEPTION 'requirement registry rejected (owner): % is not a role', p_owner_role USING ERRCODE = '22023'; END IF;
  IF p_owner IS NULL AND p_owner_role IS NULL AND coalesce(v_attrs->>'owner_declared', '') = '' THEN
    RAISE EXCEPTION 'requirement registry rejected (owner): a normative artifact declares its owner (a principal, a role or the register''s declared owner — ES-02-001)' USING ERRCODE = '22023';
  END IF;
  IF p_kind = 'requirement' THEN
    IF coalesce(v_attrs->>'mandatory', 'false') = 'true' AND coalesce(v_attrs->>'verification_method', '') = '' THEN
      RAISE EXCEPTION 'requirement registry rejected (verification_method): a mandatory requirement names an executable or independently reviewable verification method (ES-03-001)' USING ERRCODE = '22023';
    END IF;
    IF coalesce((v_attrs->>'obligations')::int, 1) > 1 THEN
      RAISE EXCEPTION 'requirement registry rejected (compound): the text states % controlling obligations; one requirement states one (ES-03-002)', v_attrs->>'obligations' USING ERRCODE = '22023';
    END IF;
  END IF;
  v_id := governance.rg_artifact_id(p_kind, p_key);
  SELECT * INTO cur FROM governance.artifacts WHERE artifact_id = v_id AND superseded_at IS NULL FOR UPDATE;
  IF cur.artifact_id IS NOT NULL AND cur.lifecycle IN ('retired', 'superseded') THEN
    RAISE EXCEPTION 'requirement registry rejected (state): % % was %; a retired identity is never reused (ADR-004) — register a new key', p_kind, p_key, cur.lifecycle USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_expected_version, -1) <> coalesce(cur.version, 0) THEN
    RAISE EXCEPTION 'requirement registry rejected (stale): % % is at version %, not %', p_kind, p_key, coalesce(cur.version, 0), coalesce(p_expected_version::text, '<none>') USING ERRCODE = '22023';
  END IF;
  IF p_supersedes IS NOT NULL THEN
    SELECT * INTO sup FROM governance.artifacts WHERE artifact_id = p_supersedes AND superseded_at IS NULL FOR UPDATE;
    IF sup.artifact_id IS NULL OR sup.scope <> 'PLATFORM' THEN RAISE EXCEPTION 'requirement registry rejected (unknown_artifact): the superseded artifact is not a current registry artifact' USING ERRCODE = '22023'; END IF;
    IF sup.artifact_id = v_id THEN RAISE EXCEPTION 'requirement registry rejected (supersedes): an artifact never supersedes itself (a change is a new version)' USING ERRCODE = '22023'; END IF;
    IF sup.kind <> p_kind THEN RAISE EXCEPTION 'requirement registry rejected (supersedes): an artifact supersedes only an artifact of its own kind' USING ERRCODE = '22023'; END IF;
    IF sup.lifecycle IN ('retired', 'superseded') THEN RAISE EXCEPTION 'requirement registry rejected (state): % is already %', sup.external_key, sup.lifecycle USING ERRCODE = '22023'; END IF;
    IF NOT governance.rg_controls(p_class, sup.authority_class) THEN
      RAISE EXCEPTION 'requirement registry rejected (control_order): % authority never supersedes % authority (a lower artifact may add precision, never replace a higher one — IA-02-003)', p_class, sup.authority_class USING ERRCODE = '22023';
    END IF;
  END IF;
  IF p_parent IS NOT NULL THEN
    SELECT * INTO par FROM governance.artifacts WHERE artifact_id = p_parent AND superseded_at IS NULL;
    IF par.artifact_id IS NULL OR par.scope <> 'PLATFORM' OR par.lifecycle IN ('retired', 'superseded') THEN
      RAISE EXCEPTION 'requirement registry rejected (unknown_parent): a derived requirement references a current parent (ES-03-003)' USING ERRCODE = '22023';
    END IF;
    IF par.artifact_id = v_id THEN RAISE EXCEPTION 'requirement registry rejected (circular): an artifact never derives from itself' USING ERRCODE = '22023'; END IF;
    IF par.kind <> p_kind THEN RAISE EXCEPTION 'requirement registry rejected (unknown_parent): a derived % derives from a % (its parent is %)', p_kind, p_kind, par.kind USING ERRCODE = '22023'; END IF;
    IF NOT governance.rg_controls(par.authority_class, p_class) THEN
      RAISE EXCEPTION 'requirement registry rejected (control_order): % authority never derives from % authority (inheritance goes upward)', p_class, par.authority_class USING ERRCODE = '22023';
    END IF;
    v_why := governance.rg_weakens(v_attrs, par.attributes);
    IF v_why IS NOT NULL THEN RAISE EXCEPTION 'requirement registry rejected (weakens): % — a derived requirement never weakens its parent (ES-03-003)', v_why USING ERRCODE = '22023'; END IF;
    v_attrs := v_attrs || jsonb_build_object('parent', par.external_key);
  END IF;
  v_put := governance.rg_put_artifact(p_kind, p_key, btrim(p_title), p_class, p_volume, coalesce(p_lifecycle, 'active'), v_attrs, p_owner, p_owner_role,
                                      jsonb_build_object('path', 'registered', 'by', p_actor), p_actor, p_correlation);
  IF p_parent IS NOT NULL THEN
    IF EXISTS (WITH RECURSIVE w(n, d) AS (SELECT p_parent, 0 UNION SELECT l.to_artifact, w.d + 1 FROM w JOIN governance.links_live l ON l.from_artifact = w.n AND l.relation = 'derives_from' WHERE w.d < 32)
               SELECT 1 FROM w WHERE n = v_id) THEN
      RAISE EXCEPTION 'requirement registry rejected (circular): deriving % from % closes a cycle', p_key, par.external_key USING ERRCODE = '22023';
    END IF;
    v_links := v_links || jsonb_build_array(governance.rg_put_link(v_id, p_parent, 'derives_from', jsonb_build_object('source', 'registered'), p_actor, p_correlation));
  END IF;
  IF p_supersedes IS NOT NULL THEN
    PERFORM governance.rg_put_artifact(sup.kind, sup.external_key, sup.title, sup.authority_class, sup.controlling_volume, 'superseded', sup.attributes || jsonb_build_object('superseded_by', p_key),
                                       sup.owner_principal_id, sup.owner_role, sup.source || jsonb_build_object('superseded_by', v_id), p_actor, p_correlation);
    v_links := v_links || jsonb_build_array(governance.rg_put_link(v_id, p_supersedes, 'supersedes', jsonb_build_object('source', 'registered'), p_actor, p_correlation));
  END IF;
  IF (v_put->>'changed')::boolean OR jsonb_array_length(v_links) > 0 THEN
    PERFORM governance.ledger(NULL, NULL, 'artifact', v_id, (v_put->>'version')::int, 'registry.registered', p_actor,
      jsonb_build_object('kind', p_kind, 'key', p_key, 'authority_class', p_class, 'supersedes', p_supersedes, 'parent', p_parent, 'digest', v_put->>'digest'), p_correlation);
  END IF;
  RETURN v_put || jsonb_build_object('kind', p_kind, 'key', p_key, 'links', v_links,
    'changed_artifacts', to_jsonb(ARRAY(SELECT x FROM unnest(ARRAY[CASE WHEN (v_put->>'normative_change')::boolean THEN v_id END, p_supersedes]) x WHERE x IS NOT NULL)));
END $$;
REVOKE ALL ON FUNCTION governance.rg_register(text, text, int, text, text, text, text, jsonb, uuid, uuid, uuid, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_register(text, text, int, text, text, text, text, jsonb, uuid, uuid, uuid, text, uuid, uuid) TO eye_commit;

/* RECORD a trace link (ES-06-001, IA-06-001..003, DP-07-001..003): both ends current PLATFORM registry artifacts (a tenant's artifact is
   never linked from the vendor's registry), the relation admissible for the kinds, the CONTROL ORDER kept (derives_from / part_of upward,
   governs / supersedes downward), no cycle closed through a derivation, no duplicate live link. The versions and digests of both ends are
   recorded; the link is append-only. */
CREATE OR REPLACE FUNCTION governance.rg_link(p_from uuid, p_to uuid, p_relation text, p_attributes jsonb, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE f governance.artifacts%ROWTYPE; t governance.artifacts%ROWTYPE; v_why text; v jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.trace.link', p_actor, 'trace link');
  IF p_relation IS NULL OR NOT (p_relation = ANY (governance.link_relations())) THEN RAISE EXCEPTION 'trace link rejected (relation): % is not a link relation', coalesce(p_relation, '<null>') USING ERRCODE = '22023'; END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 THEN RAISE EXCEPTION 'trace link rejected (reason): a link states its basis (8 characters or more)' USING ERRCODE = '22023'; END IF;
  IF p_attributes IS NOT NULL AND jsonb_typeof(p_attributes) <> 'object' THEN RAISE EXCEPTION 'trace link rejected (attributes): attributes are an object' USING ERRCODE = '22023'; END IF;
  SELECT * INTO f FROM governance.artifacts WHERE artifact_id = p_from AND superseded_at IS NULL;
  SELECT * INTO t FROM governance.artifacts WHERE artifact_id = p_to AND superseded_at IS NULL;
  IF f.artifact_id IS NULL OR t.artifact_id IS NULL THEN RAISE EXCEPTION 'trace link rejected (unknown_artifact): both ends are current registry artifacts' USING ERRCODE = '22023'; END IF;
  IF f.scope <> 'PLATFORM' OR t.scope <> 'PLATFORM' THEN RAISE EXCEPTION 'trace link rejected (scope): the vendor''s registry links only its own (PLATFORM) artifacts — a tenant''s record is never linked from here' USING ERRCODE = '22023'; END IF;
  IF p_from = p_to THEN RAISE EXCEPTION 'trace link rejected (circular): an artifact is never linked to itself' USING ERRCODE = '22023'; END IF;
  IF f.lifecycle IN ('retired', 'superseded') OR t.lifecycle IN ('retired', 'superseded') THEN RAISE EXCEPTION 'trace link rejected (state): a retired or superseded artifact takes no new link (it stays resolvable)' USING ERRCODE = '22023'; END IF;
  v_why := governance.rg_relation_problem(p_relation, f.kind, t.kind);
  IF v_why IS NOT NULL THEN RAISE EXCEPTION 'trace link rejected (relation): %', v_why USING ERRCODE = '22023'; END IF;
  IF (p_relation IN ('derives_from', 'part_of') AND NOT governance.rg_controls(t.authority_class, f.authority_class))
     OR (p_relation IN ('governs', 'supersedes') AND NOT governance.rg_controls(f.authority_class, t.authority_class)) THEN
    RAISE EXCEPTION 'trace link rejected (control_order): % (%) % % (%) breaks the control order — a lower authority may add precision, never weaken or replace a higher one',
      f.external_key, f.authority_class, p_relation, t.external_key, t.authority_class USING ERRCODE = '22023';
  END IF;
  IF p_relation = 'derives_from' AND f.kind = 'requirement' AND t.kind = 'requirement' THEN
    v_why := governance.rg_weakens(f.attributes, t.attributes);
    IF v_why IS NOT NULL THEN RAISE EXCEPTION 'trace link rejected (weakens): %', v_why USING ERRCODE = '22023'; END IF;
  END IF;
  IF p_relation IN ('derives_from', 'part_of', 'supersedes', 'depends_on') AND EXISTS (
       WITH RECURSIVE w(n, d) AS (SELECT p_to, 0 UNION SELECT l.to_artifact, w.d + 1 FROM w JOIN governance.links_live l ON l.from_artifact = w.n AND l.relation = p_relation WHERE w.d < 32)
       SELECT 1 FROM w WHERE n = p_from) THEN
    RAISE EXCEPTION 'trace link rejected (circular): % % % closes a cycle', f.external_key, p_relation, t.external_key USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM governance.links_live l WHERE l.from_artifact = p_from AND l.to_artifact = p_to AND l.relation = p_relation
               AND l.attributes->>'from_digest' IS NOT DISTINCT FROM f.digest AND l.attributes->>'to_digest' IS NOT DISTINCT FROM t.digest) THEN
    RAISE EXCEPTION 'trace link rejected (duplicate): % % % is already a live link over these versions', f.external_key, p_relation, t.external_key USING ERRCODE = '22023';
  END IF;
  v := governance.rg_put_link(p_from, p_to, p_relation, coalesce(p_attributes, '{}'::jsonb) || jsonb_build_object('source', 'recorded', 'reason', btrim(p_reason)), p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'trace_link', (v->>'link_id')::uuid, NULL, 'trace.linked', p_actor,
    jsonb_build_object('from', f.external_key, 'to', t.external_key, 'relation', p_relation, 'reason', btrim(p_reason)), p_correlation);
  RETURN v || jsonb_build_object('from', f.external_key, 'to', t.external_key, 'relation', p_relation);
END $$;
REVOKE ALL ON FUNCTION governance.rg_link(uuid, uuid, text, jsonb, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_link(uuid, uuid, text, jsonb, text, uuid, uuid) TO eye_commit;

/* RETIRE a recorded link (a later row; never an update or a delete). An imported link is the source's — re-import to change it. */
CREATE OR REPLACE FUNCTION governance.rg_retire_link(p_link uuid, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE l governance.links%ROWTYPE; v_id uuid := gen_random_uuid();
BEGIN
  PERFORM governance.assert_platform('governance.trace.link', p_actor, 'trace link');
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 THEN RAISE EXCEPTION 'trace link rejected (reason): a retirement states its reason (8 characters or more)' USING ERRCODE = '22023'; END IF;
  SELECT * INTO l FROM governance.links WHERE link_id = p_link FOR UPDATE;
  IF l.link_id IS NULL OR l.retired OR l.scope <> 'PLATFORM' THEN RAISE EXCEPTION 'trace link rejected (unknown_link): no live registry link %', p_link USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM governance.links x WHERE x.retires_link = p_link) THEN RAISE EXCEPTION 'trace link rejected (state): the link is already retired' USING ERRCODE = '22023'; END IF;
  IF l.attributes->>'source' IS DISTINCT FROM 'recorded' THEN
    RAISE EXCEPTION 'trace link rejected (state): this link is declared by % — the source is authoritative; change it there and re-import', coalesce(l.attributes->>'source', 'another part') USING ERRCODE = '22023';
  END IF;
  INSERT INTO governance.links (link_id, scope, from_artifact, to_artifact, relation, retired, retires_link, attributes, recorded_by, correlation_id)
  VALUES (v_id, 'PLATFORM', l.from_artifact, l.to_artifact, l.relation, true, p_link, jsonb_build_object('source', 'recorded', 'reason', btrim(p_reason)), p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'trace_link', p_link, NULL, 'trace.link_retired', p_actor, jsonb_build_object('reason', btrim(p_reason), 'retired_by', v_id), p_correlation);
  RETURN jsonb_build_object('link_id', p_link, 'retired_by', v_id);
END $$;
REVOKE ALL ON FUNCTION governance.rg_retire_link(uuid, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_retire_link(uuid, text, uuid, uuid) TO eye_commit;

/* RECORD a change impact (ES-02-005, ES-06-004): recomputed in the port over the links as they stand; when the caller names the digest it was
   shown, a different answer is STALE (the links moved since). The impact is registered as `evidence` evidencing the changed artifacts; an
   actual change (not a proposal) HOLDS each dependent release candidate (evidence_stale) until its stale verifications are current again. */
CREATE OR REPLACE FUNCTION governance.rg_record_impact(p_impact uuid, p_changes jsonb, p_depth int, p_expected_digest text, p_trigger text, p_trigger_ref uuid, p_build jsonb,
  p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE v jsonb; v_held jsonb := '[]'::jsonb; rc jsonb; v_hold uuid; v_key text; r jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.impact.record', p_actor, 'change impact');
  IF p_trigger IS NULL OR p_trigger NOT IN ('import', 'register', 'change', 'proposal') THEN RAISE EXCEPTION 'change impact rejected (trigger): an impact is recorded for an import, a registration, a change or a proposal' USING ERRCODE = '22023'; END IF;
  v := governance.rg_impact(p_changes, p_depth);
  IF p_expected_digest IS NOT NULL AND p_expected_digest <> v->>'digest' THEN
    RAISE EXCEPTION 'change impact rejected (stale): the links or versions moved since the impact % was shown (now %)', left(p_expected_digest, 12), left(v->>'digest', 12) USING ERRCODE = '22023';
  END IF;
  INSERT INTO governance.rg_impacts (impact_id, trigger, trigger_ref, input, dependents, counts, stale_verifications, held, depth_limit, truncated, digest, build_identity, recorded_by, correlation_id)
  VALUES (p_impact, p_trigger, p_trigger_ref, v->'input', v->'dependents', v->'counts', v->'stale_verifications', '[]'::jsonb, (v->>'depth_limit')::int, (v->>'truncated')::boolean, v->>'digest',
          coalesce(p_build, '{}'::jsonb) || governance.rg_build_identity(), p_actor, p_correlation);
  v_key := 'impact:' || p_impact::text;
  PERFORM governance.rg_put_artifact('evidence', v_key, format('Change impact %s (%s): %s dependents', left(v->>'digest', 12), p_trigger, jsonb_array_length(v->'dependents')),
            'verification', NULL, 'active', jsonb_build_object('evidence_kind', 'change_impact', 'impact_id', p_impact, 'digest', v->>'digest', 'trigger', p_trigger, 'counts', v->'counts'),
            NULL, 'conformance_steward', jsonb_build_object('path', 'impact', 'impact_id', p_impact), p_actor, p_correlation);
  FOR r IN SELECT x FROM jsonb_array_elements(v->'input') x LOOP
    PERFORM governance.rg_put_link(governance.rg_artifact_id('evidence', v_key), (r->>'artifact_id')::uuid, 'evidences', jsonb_build_object('source', 'impact'), p_actor, p_correlation);
  END LOOP;
  IF p_trigger <> 'proposal' THEN
    FOR rc IN SELECT x FROM jsonb_array_elements(v->'release_candidates') x LOOP
      v_hold := gen_random_uuid();
      INSERT INTO governance.holds (hold_id, scope, subject_artifact, reason_kind, source_artifact, reason, opened_by, correlation_id)
      VALUES (v_hold, 'PLATFORM', (rc->>'artifact_id')::uuid, 'evidence_stale', governance.rg_artifact_id('evidence', v_key),
              format('change impact %s: a controlling artifact changed under %s; its dependent verifications are stale until re-run', left(v->>'digest', 12), rc->>'key'), p_actor, p_correlation);
      INSERT INTO governance.rg_hold_origins (hold_id, origin, origin_artifact, impact_id, findings) VALUES (v_hold, 'impact', (rc->>'artifact_id')::uuid, p_impact, v->'stale_verifications');
      v_held := v_held || jsonb_build_array(jsonb_build_object('hold_id', v_hold, 'subject', rc->>'artifact_id', 'key', rc->>'key'));
    END LOOP;
  END IF;
  PERFORM governance.ledger(NULL, NULL, 'change_impact', p_impact, NULL, 'impact.recorded', p_actor,
    jsonb_build_object('digest', v->>'digest', 'trigger', p_trigger, 'counts', v->'counts', 'held', v_held), p_correlation);
  RETURN v || jsonb_build_object('impact_id', p_impact, 'trigger', p_trigger, 'held', v_held, 'evidence_artifact', governance.rg_artifact_id('evidence', v_key));
END $$;
REVOKE ALL ON FUNCTION governance.rg_record_impact(uuid, jsonb, int, text, text, uuid, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_record_impact(uuid, jsonb, int, text, text, uuid, jsonb, uuid, uuid) TO eye_commit;

/* RECONCILE INHERITANCE (IA-06-005, DP-07-005, PR-08-005): for each artifact (≤ 200), its inheritance re-evaluated. NON-CONFORMANT → a hold
   on the artifact (its acceptance/promotion denied: evidence_missing for incomplete/unverifiable, evidence_stale for stale, conflict for
   circular/conflicting/control_order) and on every CAPABILITY depending on it (capability acceptance held), the affected journeys and
   release candidates named; CONFORMANT (a closed chain) → §RG's open inheritance holds on it LIFTED, and an impact hold on it lifted once
   every stale verification that impact named is current again. */
CREATE OR REPLACE FUNCTION governance.rg_reconcile_inheritance(p_artifacts uuid[], p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE v_id uuid; v_inh jsonb; v_out jsonb := '[]'::jsonb; v_kinds text[]; v_kind text; v_subjects uuid[]; s uuid; v_hold uuid; v_held jsonb; v_lifted jsonb; h record; v_open jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.trace.check', p_actor, 'trace link');
  IF p_artifacts IS NULL OR cardinality(p_artifacts) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'trace link rejected (artifacts): name 1–200 artifacts' USING ERRCODE = '22023'; END IF;
  FOREACH v_id IN ARRAY (SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(p_artifacts) x) LOOP
    IF NOT EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.artifact_id = v_id AND a.superseded_at IS NULL AND a.scope = 'PLATFORM') THEN
      RAISE EXCEPTION 'trace link rejected (unknown_artifact): % is not a current registry artifact', v_id USING ERRCODE = '22023';
    END IF;
    v_inh := governance.rg_inheritance(v_id); v_held := '[]'::jsonb; v_lifted := '[]'::jsonb;
    IF NOT (v_inh->>'conformant')::boolean THEN
      v_kinds := ARRAY(SELECT DISTINCT CASE f->>'class' WHEN 'stale' THEN 'evidence_stale' WHEN 'incomplete' THEN 'evidence_missing' WHEN 'unverifiable' THEN 'evidence_missing' ELSE 'conflict' END
                         FROM jsonb_array_elements(v_inh->'findings') f ORDER BY 1);
      v_subjects := ARRAY[v_id] || ARRAY(SELECT (c->>'artifact_id')::uuid FROM jsonb_array_elements(v_inh->'affected'->'capabilities') c);
      FOREACH s IN ARRAY v_subjects LOOP
        FOREACH v_kind IN ARRAY v_kinds LOOP
          IF NOT EXISTS (SELECT 1 FROM governance.holds hh JOIN governance.rg_hold_origins o ON o.hold_id = hh.hold_id
                          WHERE hh.subject_artifact = s AND hh.lifted_at IS NULL AND hh.reason_kind = v_kind AND o.origin = 'inheritance' AND o.origin_artifact = v_id) THEN
            v_hold := gen_random_uuid();
            INSERT INTO governance.holds (hold_id, scope, subject_artifact, reason_kind, source_artifact, reason, opened_by, correlation_id)
            VALUES (v_hold, 'PLATFORM', s, v_kind, v_id, format('the inheritance of %s is not closed (%s): acceptance and promotion held until the chain is restored',
                    v_inh->'artifact'->>'key', (SELECT string_agg(DISTINCT f->>'class', ', ') FROM jsonb_array_elements(v_inh->'findings') f)), p_actor, p_correlation);
            INSERT INTO governance.rg_hold_origins (hold_id, origin, origin_artifact, findings) VALUES (v_hold, 'inheritance', v_id, v_inh->'findings');
            v_held := v_held || jsonb_build_array(jsonb_build_object('hold_id', v_hold, 'subject', s, 'reason_kind', v_kind));
          END IF;
        END LOOP;
      END LOOP;
      IF jsonb_array_length(v_held) > 0 THEN
        PERFORM governance.ledger(NULL, NULL, 'artifact', v_id, (v_inh->'artifact'->>'version')::int, 'inheritance.held', p_actor,
          jsonb_build_object('findings', v_inh->'findings', 'held', v_held, 'controlling_authority', v_inh->'controlling_authority', 'affected', v_inh->'affected'), p_correlation);
      END IF;
    ELSE
      FOR h IN SELECT hh.hold_id FROM governance.holds hh JOIN governance.rg_hold_origins o ON o.hold_id = hh.hold_id
                WHERE hh.lifted_at IS NULL AND o.origin = 'inheritance' AND o.origin_artifact = v_id ORDER BY hh.opened_at LOOP
        UPDATE governance.holds SET lifted_at = clock_timestamp(), lifted_by = p_actor, lift_reason = 'the evidence chain is closed (inheritance reconciled)' WHERE hold_id = h.hold_id;
        v_lifted := v_lifted || jsonb_build_array(h.hold_id);
      END LOOP;
    END IF;
    -- an impact hold on this artifact: lifted once every stale verification the impact named is current again
    FOR h IN SELECT hh.hold_id, o.impact_id FROM governance.holds hh JOIN governance.rg_hold_origins o ON o.hold_id = hh.hold_id
              WHERE hh.subject_artifact = v_id AND hh.lifted_at IS NULL AND o.origin = 'impact' ORDER BY hh.opened_at LOOP
      v_open := governance.rg_impact_open(h.impact_id);
      IF jsonb_array_length(v_open) = 0 THEN
        UPDATE governance.holds SET lifted_at = clock_timestamp(), lifted_by = p_actor, lift_reason = 'every verification the change impact made stale is current again' WHERE hold_id = h.hold_id;
        v_lifted := v_lifted || jsonb_build_array(h.hold_id);
      END IF;
    END LOOP;
    IF jsonb_array_length(v_lifted) > 0 THEN
      PERFORM governance.ledger(NULL, NULL, 'artifact', v_id, (v_inh->'artifact'->>'version')::int, 'inheritance.restored', p_actor, jsonb_build_object('lifted', v_lifted), p_correlation);
    END IF;
    v_out := v_out || jsonb_build_array(v_inh || jsonb_build_object('held', v_held, 'lifted', v_lifted,
      'still_open', (SELECT coalesce(jsonb_agg(hh.hold_id), '[]'::jsonb) FROM governance.holds hh WHERE hh.subject_artifact = v_id AND hh.lifted_at IS NULL)));
  END LOOP;
  RETURN jsonb_build_object('results', v_out);
END $$;
REVOKE ALL ON FUNCTION governance.rg_reconcile_inheritance(uuid[], uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_reconcile_inheritance(uuid[], uuid, uuid) TO eye_commit;

/* INGEST a verification record (V04-T-012, ES-67-001, ES-03-001): a report the API normalised (reports.ts), with its sha256 — the same
   digest again is the SAME record (idempotent). Each case registers its `test` (by file and full name), VERIFIES the requirements its title
   cites by EXACT id (resolved against the registry; unresolved tokens counted, never guessed) and CONSUMES the fixtures named (a quarantined
   or unapproved fixture is refused — evidence on it is never admitted); the record is `evidence` EVIDENCING each test with its status. */
CREATE OR REPLACE FUNCTION governance.rg_ingest_verification(p_record uuid, p jsonb, p_build jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE prev governance.rg_verification_records%ROWTYPE; c jsonb; i int := 0; v_test jsonb; v_key text; v_title text; v_req uuid; v_fx uuid; v_fixtures uuid[]; v_resolved uuid[];
        v_passed int := 0; v_failed int := 0; v_other int := 0; v_result text; v_until timestamptz; v_ev text; v_unres int := 0; f text; fx governance.artifacts%ROWTYPE; v_row governance.rg_verification_records%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.verification.ingest', p_actor, 'verification record');
  IF p IS NULL OR jsonb_typeof(p) <> 'object' THEN RAISE EXCEPTION 'verification record rejected (report): the report is an object' USING ERRCODE = '22023'; END IF;
  IF coalesce(p->>'source_digest', '') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'verification record rejected (digest): the report''s sha256 is 64 hex' USING ERRCODE = '22023'; END IF;
  SELECT * INTO prev FROM governance.rg_verification_records r WHERE r.source_digest = p->>'source_digest';
  IF prev.record_id IS NOT NULL THEN RETURN jsonb_build_object('duplicate', true, 'record', to_jsonb(prev)); END IF;
  IF coalesce(p->>'source_kind', '') NOT IN ('vitest', 'playwright', 'gate_receipt') THEN RAISE EXCEPTION 'verification record rejected (source): vitest, playwright or gate_receipt' USING ERRCODE = '22023'; END IF;
  IF coalesce(length(btrim(p->>'source_name')), 0) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'verification record rejected (name): the report is named (1–200 characters)' USING ERRCODE = '22023'; END IF;
  IF coalesce(p->>'claim', '') NOT IN ('construction', 'demonstration') THEN
    RAISE EXCEPTION 'verification record rejected (claim): a record is construction or demonstration evidence — never acceptance (R2/H3)' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p->'cases') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'cases') = 0 OR jsonb_array_length(p->'cases') > 5000 THEN
    RAISE EXCEPTION 'verification record rejected (cases): a record carries 1–5000 cases (an empty report verifies nothing)' USING ERRCODE = '22023';
  END IF;
  FOREACH f IN ARRAY ARRAY['identity', 'execution', 'validity'] LOOP
    IF jsonb_typeof(p->f) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'verification record rejected (%): the % dimension is stated (V04-T-012)', f, f USING ERRCODE = '22023'; END IF;
  END LOOP;
  BEGIN v_until := (p->>'valid_until')::timestamptz; EXCEPTION WHEN others THEN v_until := NULL; END;
  IF v_until IS NULL OR v_until <= clock_timestamp() OR v_until > clock_timestamp() + interval '400 days' THEN
    RAISE EXCEPTION 'verification record rejected (validity): a record is valid until a future instant within 400 days — evidence expires' USING ERRCODE = '22023';
  END IF;
  v_ev := 'verification:' || (p->>'source_digest');
  FOR c IN SELECT x FROM jsonb_array_elements(p->'cases') x LOOP
    i := i + 1;
    IF coalesce(c->>'status', '') NOT IN ('passed', 'failed', 'skipped', 'todo', 'flaky', 'unstated') THEN
      RAISE EXCEPTION 'verification record rejected (cases): case % has status %', i, coalesce(c->>'status', '<null>') USING ERRCODE = '22023';
    END IF;
    IF coalesce(length(btrim(c->>'key')), 0) NOT BETWEEN 1 AND 200 OR coalesce(length(btrim(c->>'title')), 0) NOT BETWEEN 1 AND 500 THEN
      RAISE EXCEPTION 'verification record rejected (cases): case % has no test identity (key 1–200, title 1–500)', i USING ERRCODE = '22023';
    END IF;
    v_fixtures := '{}';
    FOR f IN SELECT jsonb_array_elements_text(coalesce(c->'fixtures', '[]'::jsonb)) LOOP
      SELECT * INTO fx FROM governance.artifacts WHERE artifact_id = governance.rg_artifact_id('fixture', f) AND superseded_at IS NULL;
      IF fx.artifact_id IS NULL THEN RAISE EXCEPTION 'verification record rejected (unknown_fixture): % is not a registered fixture', f USING ERRCODE = '22023'; END IF;
      IF fx.lifecycle <> 'active' THEN
        RAISE EXCEPTION 'verification record rejected (state): fixture % is % — evidence on an unapproved or quarantined fixture is never admitted (DP-67-005)', f, fx.lifecycle USING ERRCODE = '22023';
      END IF;
      IF (fx.attributes->>'valid_until')::timestamptz <= clock_timestamp() THEN
        RAISE EXCEPTION 'verification record rejected (expired): fixture % expired on % — quarantine and rebuild it first', f, fx.attributes->>'valid_until' USING ERRCODE = '22023';
      END IF;
      v_fixtures := v_fixtures || fx.artifact_id;
    END LOOP;
    v_test := governance.rg_put_artifact('test', btrim(c->>'key'), left(btrim(c->>'title'), 500), 'verification', NULL, 'active',
                jsonb_build_object('file', c->>'file', 'full_name', c->>'full_name', 'runner', p->>'source_kind'), NULL, 'conformance_steward',
                jsonb_build_object('path', 'verification', 'record_id', p_record), p_actor, p_correlation);
    v_resolved := ARRAY(SELECT DISTINCT a.artifact_id FROM governance.artifacts a
                         WHERE a.kind = 'requirement' AND a.superseded_at IS NULL AND a.lifecycle IN ('active', 'proposed', 'deprecated')
                           AND split_part(a.external_key, ':', 2) = ANY (ARRAY(SELECT jsonb_array_elements_text(coalesce(c->'cited', '[]'::jsonb)))) ORDER BY 1);
    v_unres := v_unres + (SELECT count(*) FROM jsonb_array_elements_text(coalesce(c->'cited', '[]'::jsonb)) t(x)
                           WHERE NOT EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.kind = 'requirement' AND a.superseded_at IS NULL AND split_part(a.external_key, ':', 2) = t.x))::int;
    FOREACH v_req IN ARRAY v_resolved LOOP
      PERFORM governance.rg_put_link((v_test->>'artifact_id')::uuid, v_req, 'verifies', jsonb_build_object('source', 'verification', 'record_id', p_record), p_actor, p_correlation);
    END LOOP;
    FOREACH v_fx IN ARRAY v_fixtures LOOP
      PERFORM governance.rg_put_link((v_test->>'artifact_id')::uuid, v_fx, 'consumes', jsonb_build_object('source', 'verification', 'record_id', p_record), p_actor, p_correlation);
    END LOOP;
    IF c->>'status' = 'passed' THEN v_passed := v_passed + 1; ELSIF c->>'status' IN ('failed', 'flaky') THEN v_failed := v_failed + 1; ELSE v_other := v_other + 1; END IF;
    c := c || jsonb_build_object('_test', v_test, '_resolved', to_jsonb(v_resolved), '_fixtures', to_jsonb(v_fixtures), '_no', i);
    p := jsonb_set(p, ARRAY['cases', (i - 1)::text], c);
  END LOOP;
  -- the result is computed here from the cases — never taken from the report's own summary
  v_result := CASE WHEN p->>'source_kind' = 'gate_receipt' AND coalesce(p->>'declared_result', '') NOT IN ('passed', 'failed') THEN 'unstated'
                   WHEN v_failed = 0 AND v_passed > 0 THEN 'passed' WHEN v_passed = 0 AND v_failed > 0 THEN 'failed' WHEN v_passed = 0 AND v_failed = 0 THEN 'unstated' ELSE 'mixed' END;
  INSERT INTO governance.rg_verification_records (record_id, source_kind, source_name, source_digest, identity, execution, validity, totals, result, valid_until, claim, build_identity, ingested_by, correlation_id)
  VALUES (p_record, p->>'source_kind', btrim(p->>'source_name'), p->>'source_digest', p->'identity', p->'execution', p->'validity',
          jsonb_build_object('cases', i, 'passed', v_passed, 'failed', v_failed, 'other', v_other, 'unresolved_citations', v_unres), v_result, v_until, p->>'claim',
          coalesce(p_build, '{}'::jsonb) || governance.rg_build_identity(), p_actor, p_correlation)
  RETURNING * INTO v_row;
  INSERT INTO governance.rg_verification_cases (record_id, case_no, test_artifact, test_version, status, duration_ms, cited, resolved, fixtures)
  SELECT p_record, (x->>'_no')::int, (x->'_test'->>'artifact_id')::uuid, (x->'_test'->>'version')::int, x->>'status', nullif(x->>'duration_ms', '')::numeric,
         ARRAY(SELECT jsonb_array_elements_text(coalesce(x->'cited', '[]'::jsonb))), ARRAY(SELECT (jsonb_array_elements_text(x->'_resolved'))::uuid),
         ARRAY(SELECT (jsonb_array_elements_text(x->'_fixtures'))::uuid)
    FROM jsonb_array_elements(p->'cases') x;
  PERFORM governance.rg_put_artifact('evidence', v_ev, format('%s %s — %s (%s cases)', p->>'source_kind', btrim(p->>'source_name'), v_result, i), 'verification', NULL, 'active',
            jsonb_build_object('evidence_kind', 'verification_record', 'record_id', p_record, 'source_kind', p->>'source_kind', 'result', v_result, 'valid_until', v_until, 'claim', p->>'claim'),
            NULL, 'conformance_steward', jsonb_build_object('path', 'verification', 'record_id', p_record), p_actor, p_correlation);
  PERFORM governance.rg_put_link(governance.rg_artifact_id('evidence', v_ev), (x->'_test'->>'artifact_id')::uuid, 'evidences',
            jsonb_build_object('source', 'verification', 'record_id', p_record, 'status', x->>'status'), p_actor, p_correlation)
     FROM jsonb_array_elements(p->'cases') x;
  PERFORM governance.ledger(NULL, NULL, 'verification_record', p_record, NULL, 'verification.ingested', p_actor,
    jsonb_build_object('source_kind', p->>'source_kind', 'source_digest', p->>'source_digest', 'result', v_result, 'totals', v_row.totals), p_correlation);
  RETURN jsonb_build_object('duplicate', false, 'record', to_jsonb(v_row), 'evidence_artifact', governance.rg_artifact_id('evidence', v_ev));
END $$;
REVOKE ALL ON FUNCTION governance.rg_ingest_verification(uuid, jsonb, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_ingest_verification(uuid, jsonb, jsonb, uuid, uuid) TO eye_commit;

/* REVIEW a verification record (ES-03-001 "independently reviewable"): independent assurance — a named human, never the ingester, never the
   runner the record names, never an agent — on the record's exact digest. */
CREATE OR REPLACE FUNCTION governance.rg_review_verification(p_record uuid, p_decision text, p_digest text, p_reason text, p_review uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE r governance.rg_verification_records%ROWTYPE; v_builders uuid[]; v_row governance.rg_verification_reviews%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.verification.review', p_actor, 'verification record');
  SELECT * INTO r FROM governance.rg_verification_records WHERE record_id = p_record;
  IF r.record_id IS NULL THEN RAISE EXCEPTION 'verification record rejected (unknown_record): no record %', p_record USING ERRCODE = '22023'; END IF;
  v_builders := ARRAY[r.ingested_by] || CASE WHEN coalesce(r.execution->>'runner_principal', '') ~ '^[0-9a-f-]{36}$' THEN ARRAY[(r.execution->>'runner_principal')::uuid] ELSE '{}'::uuid[] END;
  PERFORM governance.assert_approver('verification record', p_actor, NULL, NULL, ARRAY['independent_assurance'], r.ingested_by, v_builders, 'the accountable review of a verification record');
  IF p_decision IS NULL OR p_decision NOT IN ('accepted', 'rejected') THEN RAISE EXCEPTION 'verification record rejected (decision): accepted or rejected' USING ERRCODE = '22023'; END IF;
  IF p_digest IS DISTINCT FROM r.source_digest THEN RAISE EXCEPTION 'verification record rejected (stale): the review names the record''s exact digest' USING ERRCODE = '22023'; END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 THEN RAISE EXCEPTION 'verification record rejected (reason): a review states its reason (8 characters or more)' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM governance.rg_verification_reviews v WHERE v.record_id = p_record AND v.reviewer = p_actor) THEN
    RAISE EXCEPTION 'verification record rejected (duplicate): this reviewer already reviewed the record' USING ERRCODE = '22023';
  END IF;
  INSERT INTO governance.rg_verification_reviews (review_id, record_id, decision, record_digest, reason, reviewer, correlation_id)
  VALUES (p_review, p_record, p_decision, p_digest, btrim(p_reason), p_actor, p_correlation) RETURNING * INTO v_row;
  PERFORM governance.ledger(NULL, NULL, 'verification_record', p_record, NULL, 'verification.reviewed', p_actor, jsonb_build_object('decision', p_decision, 'review_id', p_review), p_correlation);
  RETURN to_jsonb(v_row);
END $$;
REVOKE ALL ON FUNCTION governance.rg_review_verification(uuid, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_review_verification(uuid, text, text, text, uuid, uuid, uuid) TO eye_commit;

/* REGISTER (or REBUILD) a fixture (DP-67-002): identity, purpose, generator or approved source, schema, seed, classification (synthetic,
   anonymised or public only — a privacy-unsafe fixture is never registered), expected results, environment scope, expiry; builders declared.
   A new version is PROPOSED (unapproved: no evidence may use it). Over a QUARANTINED fixture this is the REBUILD: from a named generator, with
   a different content (the contaminated one is never re-registered as is). */
CREATE OR REPLACE FUNCTION governance.rg_register_fixture(p_key text, p_expected_version int, p_title text, p_attributes jsonb, p_reason text, p_decision uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE cur governance.artifacts%ROWTYPE; a jsonb := coalesce(p_attributes, '{}'::jsonb); v_until timestamptz; v_put jsonb; f text; v_rebuild boolean;
BEGIN
  PERFORM governance.assert_platform('governance.fixture.register', p_actor, 'governance fixture');
  IF p_key IS NULL OR p_key !~ '^[a-z0-9][a-z0-9._:/-]{1,150}$' THEN RAISE EXCEPTION 'governance fixture rejected (key): a fixture key is lower-case (2–151 characters)' USING ERRCODE = '22023'; END IF;
  IF p_title IS NULL OR length(btrim(p_title)) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'governance fixture rejected (title): a title of 1–500 characters' USING ERRCODE = '22023'; END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 THEN RAISE EXCEPTION 'governance fixture rejected (reason): a registration states its reason (8 characters or more)' USING ERRCODE = '22023'; END IF;
  IF jsonb_typeof(a) <> 'object' THEN RAISE EXCEPTION 'governance fixture rejected (attributes): attributes are an object' USING ERRCODE = '22023'; END IF;
  FOREACH f IN ARRAY ARRAY['purpose', 'schema', 'seed', 'classification', 'expected_results'] LOOP
    IF coalesce(btrim(a->>f), '') = '' THEN RAISE EXCEPTION 'governance fixture rejected (%): a fixture declares its % (DP-67-002)', f, replace(f, '_', ' ') USING ERRCODE = '22023'; END IF;
  END LOOP;
  IF coalesce(btrim(a->>'generator'), '') = '' AND coalesce(btrim(a->>'source'), '') = '' THEN
    RAISE EXCEPTION 'governance fixture rejected (generator): a fixture names its generator or its approved source' USING ERRCODE = '22023';
  END IF;
  IF a->>'classification' NOT IN ('synthetic', 'anonymised', 'public') THEN
    RAISE EXCEPTION 'governance fixture rejected (classification): % — a fixture is synthetic, anonymised or public; a privacy-unsafe fixture is never registered', a->>'classification' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(a->'environment_scope') IS DISTINCT FROM 'array' OR jsonb_array_length(a->'environment_scope') = 0 THEN
    RAISE EXCEPTION 'governance fixture rejected (environment_scope): a fixture names the environments it may be used in' USING ERRCODE = '22023';
  END IF;
  IF a ? 'builders' AND (jsonb_typeof(a->'builders') <> 'array' OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(a->'builders') b WHERE b !~ '^[0-9a-f-]{36}$')) THEN
    RAISE EXCEPTION 'governance fixture rejected (builders): the builders are principal ids' USING ERRCODE = '22023';
  END IF;
  BEGIN v_until := (a->>'valid_until')::timestamptz; EXCEPTION WHEN others THEN v_until := NULL; END;
  IF v_until IS NULL OR v_until <= clock_timestamp() THEN RAISE EXCEPTION 'governance fixture rejected (validity): a fixture expires at a future instant' USING ERRCODE = '22023'; END IF;
  SELECT * INTO cur FROM governance.artifacts WHERE artifact_id = governance.rg_artifact_id('fixture', p_key) AND superseded_at IS NULL FOR UPDATE;
  IF coalesce(p_expected_version, -1) <> coalesce(cur.version, 0) THEN
    RAISE EXCEPTION 'governance fixture rejected (stale): % is at version %, not %', p_key, coalesce(cur.version, 0), coalesce(p_expected_version::text, '<none>') USING ERRCODE = '22023';
  END IF;
  IF cur.lifecycle = 'retired' THEN RAISE EXCEPTION 'governance fixture rejected (state): % is retired; a retired identity is never reused' , p_key USING ERRCODE = '22023'; END IF;
  v_rebuild := cur.lifecycle = 'quarantined';
  IF v_rebuild AND governance.rg_content_digest('fixture', p_key, btrim(p_title), 'verification', NULL, a || jsonb_build_object('builders', coalesce(a->'builders', '[]'::jsonb))) = cur.digest THEN
    -- (the digest leaves out the governance state — approval, quarantine — so the same seed and source give the same digest)
    RAISE EXCEPTION 'governance fixture rejected (rebuild): a quarantined fixture is rebuilt from its generator with a new content (seed or source) — never re-registered as is' USING ERRCODE = '22023';
  END IF;
  v_put := governance.rg_put_artifact('fixture', p_key, btrim(p_title), 'verification', NULL, 'proposed', a || jsonb_build_object('builders', coalesce(a->'builders', '[]'::jsonb)), NULL, 'conformance_steward',
                                      jsonb_build_object('path', 'fixture'), p_actor, p_correlation);
  IF NOT (v_put->>'changed')::boolean THEN RETURN v_put || jsonb_build_object('unchanged', true); END IF;
  INSERT INTO governance.rg_fixture_decisions (decision_id, fixture_artifact, fixture_version, decision, reason, digest, actor, correlation_id)
  VALUES (p_decision, (v_put->>'artifact_id')::uuid, (v_put->>'version')::int, CASE WHEN v_rebuild THEN 'rebuilt' ELSE 'registered' END, btrim(p_reason), v_put->>'digest', p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'fixture', (v_put->>'artifact_id')::uuid, (v_put->>'version')::int, CASE WHEN v_rebuild THEN 'fixture.rebuilt' ELSE 'fixture.registered' END, p_actor,
    jsonb_build_object('key', p_key, 'digest', v_put->>'digest'), p_correlation);
  RETURN v_put || jsonb_build_object('key', p_key, 'lifecycle', 'proposed', 'rebuilt', v_rebuild);
END $$;
REVOKE ALL ON FUNCTION governance.rg_register_fixture(text, int, text, jsonb, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_register_fixture(text, int, text, jsonb, text, uuid, uuid, uuid) TO eye_commit;

/* APPROVE a fixture version for use (DP-67-005 "rebuild from approved sources or generators"): independent assurance — a named human, never
   the steward who registered any version of it, never a declared builder, never an agent — on the version's exact digest. */
CREATE OR REPLACE FUNCTION governance.rg_approve_fixture(p_fixture uuid, p_version int, p_digest text, p_reason text, p_decision uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE cur governance.artifacts%ROWTYPE; v_builders uuid[]; v_proposer uuid; v_put jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.fixture.approve', p_actor, 'governance fixture');
  SELECT * INTO cur FROM governance.artifacts WHERE artifact_id = p_fixture AND superseded_at IS NULL AND kind = 'fixture' FOR UPDATE;
  IF cur.artifact_id IS NULL THEN RAISE EXCEPTION 'governance fixture rejected (unknown_fixture): no fixture %', p_fixture USING ERRCODE = '22023'; END IF;
  -- the builders: whoever registered or rebuilt any version (an approver or a quarantining steward did not build it), and the declared ones
  SELECT array_agg(DISTINCT x) INTO v_builders FROM (SELECT d.actor AS x FROM governance.rg_fixture_decisions d WHERE d.fixture_artifact = p_fixture AND d.decision IN ('registered', 'rebuilt')
                                                      UNION SELECT b::uuid FROM jsonb_array_elements_text(coalesce(cur.attributes->'builders', '[]'::jsonb)) b) s;
  SELECT d.actor INTO v_proposer FROM governance.rg_fixture_decisions d WHERE d.fixture_artifact = p_fixture AND d.fixture_version = cur.version AND d.decision IN ('registered', 'rebuilt') LIMIT 1;
  PERFORM governance.assert_approver('governance fixture', p_actor, NULL, NULL, ARRAY['independent_assurance'], v_proposer, v_builders, 'approving a fixture for use');
  IF cur.lifecycle <> 'proposed' THEN RAISE EXCEPTION 'governance fixture rejected (state): % is %; only a proposed version is approved', cur.external_key, cur.lifecycle USING ERRCODE = '22023'; END IF;
  IF p_version IS DISTINCT FROM cur.version OR p_digest IS DISTINCT FROM cur.digest THEN
    RAISE EXCEPTION 'governance fixture rejected (stale): the approval names version % and its exact digest', cur.version USING ERRCODE = '22023';
  END IF;
  IF (cur.attributes->>'valid_until')::timestamptz <= clock_timestamp() THEN RAISE EXCEPTION 'governance fixture rejected (expired): % expired before its approval', cur.external_key USING ERRCODE = '22023'; END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 THEN RAISE EXCEPTION 'governance fixture rejected (reason): an approval states its reason (8 characters or more)' USING ERRCODE = '22023'; END IF;
  v_put := governance.rg_put_artifact('fixture', cur.external_key, cur.title, cur.authority_class, cur.controlling_volume, 'active', cur.attributes || jsonb_build_object('approved_by', p_actor),
                                      cur.owner_principal_id, cur.owner_role, cur.source, p_actor, p_correlation);
  INSERT INTO governance.rg_fixture_decisions (decision_id, fixture_artifact, fixture_version, decision, reason, digest, actor, correlation_id)
  VALUES (p_decision, p_fixture, (v_put->>'version')::int, 'approved', btrim(p_reason), cur.digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'fixture', p_fixture, (v_put->>'version')::int, 'fixture.approved', p_actor, jsonb_build_object('approved_version', cur.version, 'digest', cur.digest), p_correlation);
  RETURN v_put || jsonb_build_object('key', cur.external_key, 'lifecycle', 'active');
END $$;
REVOKE ALL ON FUNCTION governance.rg_approve_fixture(uuid, int, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_approve_fixture(uuid, int, text, text, uuid, uuid, uuid) TO eye_commit;

/* QUARANTINE a fixture (DP-67-005): stale, non-representative, contaminated, privacy-unsafe, irreproducible or indistinguishable → a new
   version `quarantined`; EVERY record that evidences a test consuming it is INVALIDATED (recorded); the tests to re-run are named. */
CREATE OR REPLACE FUNCTION governance.rg_quarantine_fixture(p_fixture uuid, p_reason_class text, p_reason text, p_decision uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE cur governance.artifacts%ROWTYPE; v_put jsonb; v_inv jsonb; v_tests jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.fixture.quarantine', p_actor, 'governance fixture');
  IF p_reason_class IS NULL OR p_reason_class NOT IN ('stale', 'non_representative', 'contaminated', 'privacy_unsafe', 'irreproducible', 'indistinguishable') THEN
    RAISE EXCEPTION 'governance fixture rejected (reason_class): stale, non_representative, contaminated, privacy_unsafe, irreproducible or indistinguishable' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 THEN RAISE EXCEPTION 'governance fixture rejected (reason): a quarantine states its reason (8 characters or more)' USING ERRCODE = '22023'; END IF;
  SELECT * INTO cur FROM governance.artifacts WHERE artifact_id = p_fixture AND superseded_at IS NULL AND kind = 'fixture' FOR UPDATE;
  IF cur.artifact_id IS NULL THEN RAISE EXCEPTION 'governance fixture rejected (unknown_fixture): no fixture %', p_fixture USING ERRCODE = '22023'; END IF;
  IF cur.lifecycle IN ('quarantined', 'retired') THEN RAISE EXCEPTION 'governance fixture rejected (state): % is already %', cur.external_key, cur.lifecycle USING ERRCODE = '22023'; END IF;
  v_put := governance.rg_put_artifact('fixture', cur.external_key, cur.title, cur.authority_class, cur.controlling_volume, 'quarantined',
                                      cur.attributes || jsonb_build_object('quarantine', jsonb_build_object('class', p_reason_class, 'reason', btrim(p_reason))),
                                      cur.owner_principal_id, cur.owner_role, cur.source, p_actor, p_correlation);
  WITH ev AS (
    SELECT DISTINCT c.record_id FROM governance.rg_verification_cases c WHERE p_fixture = ANY (c.fixtures)
  ), ins AS (
    INSERT INTO governance.rg_invalidations (invalidation_id, record_id, cause_kind, cause_artifact, cause_version, reason, recorded_by, correlation_id)
    SELECT gen_random_uuid(), ev.record_id, 'fixture_quarantined', p_fixture, cur.version, format('%s: %s', p_reason_class, btrim(p_reason)), p_actor, p_correlation FROM ev
    ON CONFLICT ON CONSTRAINT rgv_once DO NOTHING RETURNING record_id)
  SELECT coalesce(jsonb_agg(record_id ORDER BY record_id), '[]'::jsonb) INTO v_inv FROM ins;
  SELECT coalesce(jsonb_agg(DISTINCT t.external_key), '[]'::jsonb) INTO v_tests FROM governance.rg_verification_cases c JOIN governance.artifacts t ON t.artifact_id = c.test_artifact AND t.superseded_at IS NULL
   WHERE p_fixture = ANY (c.fixtures);
  INSERT INTO governance.rg_fixture_decisions (decision_id, fixture_artifact, fixture_version, decision, reason_class, reason, digest, actor, correlation_id)
  VALUES (p_decision, p_fixture, (v_put->>'version')::int, 'quarantined', p_reason_class, btrim(p_reason), cur.digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'fixture', p_fixture, (v_put->>'version')::int, 'fixture.quarantined', p_actor,
    jsonb_build_object('class', p_reason_class, 'invalidated', v_inv, 'rerun', v_tests), p_correlation);
  RETURN v_put || jsonb_build_object('key', cur.external_key, 'lifecycle', 'quarantined', 'invalidated', v_inv, 'rerun', v_tests);
END $$;
REVOKE ALL ON FUNCTION governance.rg_quarantine_fixture(uuid, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_quarantine_fixture(uuid, text, text, uuid, uuid, uuid) TO eye_commit;

/* DECLARE A DECISION-ACTIVE PRODUCT (ES-06-004 "decision-active products", DP-07-003): a domain's own briefing, decision package or forecast
   CITES the vendor's contracts (a schema, an interface, a component, a requirement or a capability) — declared by the domain's
   administrator or executive, in the DOMAIN (tenant/domain isolation: another tenant never sees it; the vendor's PLATFORM impact reads it), the
   object verified to exist IN THAT DOMAIN, recorded as a DOMAIN `data_product` artifact with its `cites` links (append-only; re-declaring the
   same citations writes nothing). A change to a cited contract then lists the product among its impact's decision-active dependents. */
CREATE OR REPLACE FUNCTION governance.rg_declare_domain_product(p_tenant uuid, p_domain uuid, p_product_kind text, p_object uuid, p_title text, p_cites uuid[], p_reason text,
  p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE v_key text; v_id uuid; cur governance.artifacts%ROWTYPE; v_digest text; v_attrs jsonb; v_version int; v_now timestamptz := clock_timestamp(); c uuid; t governance.artifacts%ROWTYPE;
        v_links jsonb := '[]'::jsonb; v_exists boolean; v_lid uuid; f governance.artifacts%ROWTYPE;
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.trace.domain_cite']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'trace link rejected (actor): the act is recorded under the acting principal' USING ERRCODE = '42501'; END IF;
  IF p_product_kind IS NULL OR p_product_kind NOT IN ('briefing', 'decision_package', 'forecast') THEN
    RAISE EXCEPTION 'trace link rejected (product_kind): a decision-active product is a briefing, a decision package or a forecast' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 THEN RAISE EXCEPTION 'trace link rejected (reason): a declaration states its basis (8 characters or more)' USING ERRCODE = '22023'; END IF;
  IF p_title IS NULL OR length(btrim(p_title)) NOT BETWEEN 1 AND 300 THEN RAISE EXCEPTION 'trace link rejected (title): a title of 1–300 characters' USING ERRCODE = '22023'; END IF;
  IF p_cites IS NULL OR cardinality(p_cites) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'trace link rejected (cites): a product cites 1–50 registry artifacts' USING ERRCODE = '22023'; END IF;
  v_exists := CASE p_product_kind
    WHEN 'briefing' THEN EXISTS (SELECT 1 FROM executive.briefings b WHERE b.briefing_id = p_object AND b.tenant_id = p_tenant AND b.domain_id = p_domain)
    WHEN 'decision_package' THEN EXISTS (SELECT 1 FROM decision.packages_current x WHERE x.package_id = p_object AND x.tenant_id = p_tenant AND x.domain_id = p_domain)
    ELSE EXISTS (SELECT 1 FROM prediction.forecasts_current x WHERE x.forecast_id = p_object AND x.tenant_id = p_tenant AND x.domain_id = p_domain) END;
  IF NOT v_exists THEN RAISE EXCEPTION 'trace link rejected (unknown_object): no % % in this domain', p_product_kind, p_object USING ERRCODE = '22023'; END IF;
  FOREACH c IN ARRAY p_cites LOOP
    SELECT * INTO t FROM governance.artifacts WHERE artifact_id = c AND superseded_at IS NULL;
    IF t.artifact_id IS NULL OR t.scope <> 'PLATFORM' OR t.lifecycle IN ('retired', 'superseded') THEN
      RAISE EXCEPTION 'trace link rejected (unknown_artifact): % is not a current registry artifact of the vendor', c USING ERRCODE = '22023';
    END IF;
    IF t.kind NOT IN ('schema', 'interface', 'component', 'requirement', 'capability', 'policy_bundle') THEN
      RAISE EXCEPTION 'trace link rejected (relation): a product cites a schema, an interface, a component, a requirement, a capability or a policy bundle — not a %', t.kind USING ERRCODE = '22023';
    END IF;
  END LOOP;
  v_key := p_product_kind || ':' || p_object::text;
  v_id := governance.rg_artifact_id('data_product', p_tenant::text || ':' || p_domain::text || ':' || v_key);
  v_attrs := jsonb_build_object('product_kind', p_product_kind, 'object_id', p_object, 'declared_reason', btrim(p_reason), 'owner_declared', 'the domain');
  v_digest := governance.rg_content_digest('data_product', v_key, btrim(p_title), 'operational_evidence', NULL, v_attrs);
  SELECT * INTO cur FROM governance.artifacts WHERE artifact_id = v_id AND superseded_at IS NULL FOR UPDATE;
  IF cur.artifact_id IS NULL OR cur.digest <> v_digest THEN
    v_version := coalesce(cur.version, 0) + 1;
    IF cur.artifact_id IS NOT NULL THEN UPDATE governance.artifacts SET superseded_at = v_now WHERE artifact_id = v_id AND version = cur.version; END IF;
    INSERT INTO governance.artifacts (artifact_id, version, scope, tenant_id, domain_id, kind, external_key, title, owner_principal_id, authority_class, lifecycle, attributes, source, digest,
                                      effective_from, recorded_by, correlation_id)
    VALUES (v_id, v_version, 'DOMAIN', p_tenant, p_domain, 'data_product', v_key, btrim(p_title), p_actor, 'operational_evidence', 'active', v_attrs,
            jsonb_build_object('path', 'domain_declaration'), v_digest, v_now, p_actor, p_correlation);
  END IF;
  SELECT * INTO f FROM governance.artifacts WHERE artifact_id = v_id AND superseded_at IS NULL;
  FOREACH c IN ARRAY (SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(p_cites) x) LOOP
    SELECT * INTO t FROM governance.artifacts WHERE artifact_id = c AND superseded_at IS NULL;
    IF NOT EXISTS (SELECT 1 FROM governance.links_live l WHERE l.from_artifact = v_id AND l.to_artifact = c AND l.relation = 'cites'
                     AND l.attributes->>'to_digest' = t.digest AND l.attributes->>'from_digest' = f.digest) THEN
      INSERT INTO governance.links (link_id, scope, tenant_id, domain_id, from_artifact, to_artifact, relation, retired, retires_link, attributes, recorded_by, correlation_id)
      SELECT gen_random_uuid(), 'DOMAIN', p_tenant, p_domain, l.from_artifact, l.to_artifact, l.relation, true, l.link_id, jsonb_build_object('source', 'domain_declaration', 'reason', 're-declared'), p_actor, p_correlation
        FROM governance.links_live l WHERE l.from_artifact = v_id AND l.to_artifact = c AND l.relation = 'cites';
      v_lid := gen_random_uuid();
      INSERT INTO governance.links (link_id, scope, tenant_id, domain_id, from_artifact, to_artifact, relation, attributes, recorded_by, correlation_id)
      VALUES (v_lid, 'DOMAIN', p_tenant, p_domain, v_id, c, 'cites', jsonb_build_object('source', 'domain_declaration', 'reason', btrim(p_reason), 'from_version', f.version, 'to_version', t.version,
              'from_digest', f.digest, 'to_digest', t.digest), p_actor, p_correlation);
      v_links := v_links || jsonb_build_array(jsonb_build_object('link_id', v_lid, 'cites', t.external_key));
    END IF;
  END LOOP;
  IF jsonb_array_length(v_links) > 0 OR cur.artifact_id IS NULL OR cur.digest <> v_digest THEN
    PERFORM governance.ledger(p_tenant, p_domain, 'artifact', v_id, f.version, 'trace.product_declared', p_actor,
      jsonb_build_object('product_kind', p_product_kind, 'object_id', p_object, 'links', v_links), p_correlation);
  END IF;
  RETURN jsonb_build_object('artifact_id', v_id, 'version', f.version, 'key', v_key, 'links', v_links, 'unchanged', jsonb_array_length(v_links) = 0 AND cur.artifact_id IS NOT NULL AND cur.digest = v_digest);
END $$;
REVOKE ALL ON FUNCTION governance.rg_declare_domain_product(uuid, uuid, text, uuid, text, uuid[], text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.rg_declare_domain_product(uuid, uuid, text, uuid, text, uuid[], text, uuid, uuid) TO eye_commit;


-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §CM — the generated component conformance manifest, release candidates (B65 substituted: not a release), the conformance monitor (F-P7D-25)
-- (folded at integration from the part-local file 0115_b107_x_cm.sql, unchanged but for the marked `B107 integration` edits; apply order §0, §RG, §CM, §DR, §PG, §AR, §DG)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 0115 §CM — CP-6 B107: CONFORMANCE MANIFESTS, THE RELEASE-CANDIDATE RECORD AND ITS EVIDENCE CHECK, THE LOCAL CONFORMANCE MONITOR
-- (F-P7D-25: V03-T-029, V03-T-433, V03-T-452, V03-T-479, ES-01-001/-004/-005, ES-02-002, ES-31..40-002, ES-65-001/-002/-004, ADR-0001,
-- V04-T-001/-004/-018, AI-08-001/-005, IA-01-001/-002/-003/-005/-006, IA-72-003, V06-T-002, DP-65-002/-005, DP-67-006, DAT-GV-09,
-- V07-T-005). Applies alone on top of 0001–0114 and the §0 prelude; nothing of 0001–0114 or §0 is re-declared.
--
--   THE MANIFEST: `conformance/components.manifest.json` is GENERATED from source (apps/api/src/governance/conformance/
--     generate-components-manifest.mjs; the unit tests "regenerated equals committed" and "no unmapped unit" run inside build-test). The
--     conformance steward REGISTERS the committed file (governance.cm_register_manifest): its digest, its index, and every deployable unit and
--     component as an ARTIFACT of the shared core with its LINKS (manifest covers unit/component; unit deploys component; unit depends_on unit;
--     component maps_to its requirement and consumes its interfaces and schemas — §RG's artifacts, linked when §RG has registered them; what is
--     unresolved is COUNTED and returned, never hidden). A manifest carrying an UNMAPPED unit is REFUSED and the non-conformant record is
--     PRESERVED as a finding (IA-01-005, DP-65-005).
--   THE RELEASE CANDIDATE (B65 SUBSTITUTED — explicitly NOT a release, NOT a signed release, NOT production admission): head SHA, migration head
--     (read by the port from public.schema_migrations), policy bundle (version + digest), the registered manifest version and digest, the
--     configuration digest, the deployment profile, the customer scope, the topology (the manifest's units), the period, and the EVIDENCE items
--     (family, kind, ref, digest, bound head SHA, captured_at, valid_until — a registered §RG evidence artifact by id, or a reference). THE CHECK
--     (governance.cm_check_candidate) refuses ABSENT (a required family without an item), STALE (valid_until passed on the database clock),
--     UNVERIFIABLE (no digest, an unknown or superseded artifact, a digest other than the artifact's, a capture in the future, an unknown head)
--     and FOREIGN-VERSION evidence (bound to another head SHA; a manifest or migration head that is no longer what runs), and HOLDS on any open
--     hold of the candidate (an expired exception — §PG's, a conflict — §PG's, a conformance drift — the monitor's). Its evidence holds are
--     opened and lifted by the check itself. ATTESTATION (governance.cm_attest_candidate): independent assurance — a named human, never the
--     proposer, never a builder, never an agent (governance.assert_approver) — signs `manifest_attestation` over the candidate's digest, re-
--     checked at that instant (no open hold, no evidence expired since the check, the manifest still current).
--   THE MONITOR (governance.cm_record_monitor): the after-tick hook `governance-conformance` (the attention agent, its own action
--     governance.conformance.monitor, READ FIRST then this write — B33-H) or the steward; findings by fingerprint (opened / resolved when no
--     longer observed), a `conformance_drift` hold per drift finding on the candidates it concerns, a run recorded on change.
--   PLATFORM rows only (the vendor's registries): readable by every authenticated context, written only by these definer ports. A PLATFORM
--   finding raises no attention item (attention is DOMAIN-scoped): it is shown in the workspace and the ledger.
--
-- THREE CLAIMS: CONSTRUCTION (this file + phase6-conformance-b107); DEMONSTRATED OPERATION (the act — every candidate `claim = 'demonstration'`,
-- `release = 'not_a_release'`); REAL ACCEPTANCE / PRODUCTION ADMISSION / PRODUCTION MONITORING (R1/R2/H2) — never claimed, and no row here can.
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- §CM.1 THE VOCABULARIES ───────────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* The conformance evidence families (V03-T-452). REQUIRED by the check: contract, trust, human authority (evidenced by this repository's
   harnesses). Quality, deployment and operations are CARRIED (B64 SLO computation, B106 parity, B63 runbooks): listed, never required, never
   inferred present. */
CREATE OR REPLACE FUNCTION governance.cm_evidence_families() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY['contract', 'trust', 'human_authority', 'quality', 'deployment', 'operations'] $$;
CREATE OR REPLACE FUNCTION governance.cm_required_families() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY['contract', 'trust', 'human_authority'] $$;
CREATE OR REPLACE FUNCTION governance.cm_finding_kinds() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  -- the registration's
  'unmapped_unit',
  -- the monitor's
  'manifest_unregistered', 'manifest_drift', 'manifest_unreadable', 'policy_drift', 'migration_drift', 'head_drift', 'evidence_expired', 'exception_expired', 'exception_expiry_reported'] $$;
CREATE OR REPLACE FUNCTION governance.cm_monitor_kinds() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'manifest_unregistered', 'manifest_drift', 'manifest_unreadable', 'policy_drift', 'migration_drift', 'head_drift', 'evidence_expired', 'exception_expired', 'exception_expiry_reported'] $$;
GRANT EXECUTE ON FUNCTION governance.cm_evidence_families(), governance.cm_required_families(), governance.cm_finding_kinds(), governance.cm_monitor_kinds() TO eye_app, eye_commit;

/* The migration head this database runs (the last applied migration, by name). Read by the candidate's port itself — never a caller's word. */
CREATE OR REPLACE FUNCTION governance.cm_migration_head() RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $$ SELECT max(filename) FROM public.schema_migrations $$;
REVOKE ALL ON FUNCTION governance.cm_migration_head() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.cm_migration_head() TO eye_app, eye_commit;

/* A principal's display name for the conformance reads: a PLATFORM-homed principal (the vendor's steward, assurance, product authority) or one
   of the caller's own tenant; NULL otherwise (products.catalog_principal_name answers this tenant's only). */
CREATE OR REPLACE FUNCTION governance.cm_principal_name(p_principal uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = identity, public, pg_catalog, pg_temp AS $$
  SELECT p.display_name FROM identity.principals p WHERE p.id = p_principal AND (p.scope = 'PLATFORM' OR p.tenant_id = public.eye_tenant())
$$;
REVOKE ALL ON FUNCTION governance.cm_principal_name(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.cm_principal_name(uuid) TO eye_app, eye_commit;

-- §CM.2 THE TABLES ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* THE REGISTERED MANIFESTS: one identity (the committed file's path), a version per registered digest; the INDEX is what the ports and the
   conformance service read (units with their components, layers, dependencies; components with their kind, layer, contracts, requirement). */
CREATE TABLE governance.cm_manifests (
  manifest_id     uuid NOT NULL,
  version         int  NOT NULL CHECK (version >= 1),
  path            text NOT NULL CHECK (path ~ '^[A-Za-z0-9_./-]{3,200}$'),
  schema          text NOT NULL CHECK (schema ~ '^eye\.components-manifest/v[0-9]+$'),
  generator       text NOT NULL,
  file_digest     text NOT NULL CHECK (file_digest ~ '^[0-9a-f]{64}$'),
  index_digest    text NOT NULL CHECK (index_digest ~ '^[0-9a-f]{64}$'),
  summary         jsonb NOT NULL CHECK (jsonb_typeof(summary) = 'object'),
  index           jsonb NOT NULL CHECK (jsonb_typeof(index) = 'object' AND jsonb_typeof(index -> 'units') = 'array' AND jsonb_typeof(index -> 'components') = 'array'),
  link_report     jsonb NOT NULL DEFAULT '{}'::jsonb,
  state           text NOT NULL CHECK (state IN ('current', 'superseded')),
  registered_by   uuid NOT NULL,
  registered_at   timestamptz NOT NULL DEFAULT clock_timestamp(),
  superseded_at   timestamptz,
  correlation_id  uuid NOT NULL,
  PRIMARY KEY (manifest_id, version),
  CONSTRAINT cmm_superseded CHECK ((state = 'superseded') = (superseded_at IS NOT NULL))
);
CREATE UNIQUE INDEX cmm_one_current ON governance.cm_manifests ((true)) WHERE state = 'current';

/* THE RELEASE CANDIDATES (B65 SUBSTITUTED: not a release). Versioned: an amendment (renewed evidence) is a new version; the prior one is
   `superseded`. The check's result and the attestation are recorded on the version they concern. */
CREATE TABLE governance.cm_release_candidates (
  candidate_id        uuid NOT NULL,
  version             int  NOT NULL CHECK (version >= 1),
  label               text NOT NULL CHECK (length(btrim(label)) BETWEEN 3 AND 200),
  head_sha            text NOT NULL CHECK (head_sha ~ '^[0-9a-f]{40}$' OR head_sha = 'unknown'),
  migration_head      text NOT NULL,
  policy_bundle       jsonb NOT NULL CHECK (jsonb_typeof(policy_bundle) = 'object' AND (policy_bundle ->> 'digest') ~ '^[0-9a-f]{64}$' AND length(coalesce(policy_bundle ->> 'version', '')) > 0),
  manifest_id         uuid NOT NULL,
  manifest_version    int  NOT NULL,
  manifest_digest     text NOT NULL CHECK (manifest_digest ~ '^[0-9a-f]{64}$'),
  config_digest       text NOT NULL CHECK (config_digest ~ '^[0-9a-f]{64}$'),
  deployment_profile  text NOT NULL CHECK (deployment_profile IN ('local-dev')),
  customer_scope      jsonb NOT NULL CHECK (jsonb_typeof(customer_scope) = 'object' AND customer_scope ->> 'kind' IN ('platform', 'tenants')),
  topology            jsonb NOT NULL CHECK (jsonb_typeof(topology) = 'object'),
  period_from         date NOT NULL,
  period_to           date NOT NULL,
  evidence            jsonb NOT NULL CHECK (jsonb_typeof(evidence) = 'array'),
  evidence_digest     text NOT NULL CHECK (evidence_digest ~ '^[0-9a-f]{64}$'),
  builders            uuid[] NOT NULL DEFAULT '{}',
  digest              text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  state               text NOT NULL CHECK (state IN ('assembled', 'conformant', 'refused', 'held', 'attested', 'withdrawn', 'superseded')),
  check_result        jsonb,
  checked_by          uuid,
  checked_at          timestamptz,
  attested_by         uuid,
  attested_at         timestamptz,
  attestation_reason  text,
  signature_id        uuid,
  withdrawn_by        uuid,
  withdrawn_at        timestamptz,
  withdraw_reason     text,
  proposed_by         uuid NOT NULL,
  proposed_at         timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id      uuid NOT NULL,
  claim               text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  release             text NOT NULL DEFAULT 'not_a_release' CHECK (release = 'not_a_release'),
  production_admission text NOT NULL DEFAULT 'R1: production admission and continued operation are external — this candidate is a local conformance record, never an admission',
  PRIMARY KEY (candidate_id, version),
  CONSTRAINT crc_period CHECK (period_to >= period_from),
  CONSTRAINT crc_attested CHECK ((state = 'attested') = (attested_by IS NOT NULL AND signature_id IS NOT NULL) OR state = 'superseded' OR state = 'withdrawn')
);
CREATE UNIQUE INDEX crc_one_open ON governance.cm_release_candidates (candidate_id) WHERE state <> 'superseded';

/* THE FINDINGS (non-conformance items): one OPEN finding per fingerprint; resolved, never deleted. */
CREATE TABLE governance.cm_findings (
  finding_id       uuid PRIMARY KEY,
  kind             text NOT NULL CHECK (kind = ANY (governance.cm_finding_kinds())),
  fingerprint      text NOT NULL CHECK (length(fingerprint) BETWEEN 3 AND 300),
  subject_artifact uuid,
  summary          text NOT NULL CHECK (length(btrim(summary)) >= 8),
  observed         jsonb NOT NULL DEFAULT '{}'::jsonb,
  expected         jsonb NOT NULL DEFAULT '{}'::jsonb,
  state            text NOT NULL CHECK (state IN ('open', 'resolved')),
  opened_by        uuid NOT NULL,
  opened_at        timestamptz NOT NULL DEFAULT clock_timestamp(),
  resolved_by      uuid,
  resolved_at      timestamptz,
  resolution       text,
  correlation_id   uuid NOT NULL,
  CONSTRAINT cmf_resolved CHECK ((state = 'resolved') = (resolved_at IS NOT NULL AND resolved_by IS NOT NULL AND resolution IS NOT NULL))
);
CREATE UNIQUE INDEX cmf_one_open ON governance.cm_findings (fingerprint) WHERE state = 'open';

/* THE MONITOR RUNS (recorded on change: a finding opened or resolved, a hold opened or lifted, or the observation moved). */
CREATE TABLE governance.cm_monitor_runs (
  run_id             uuid PRIMARY KEY,
  via                text NOT NULL CHECK (via IN ('tick', 'steward')),
  ticked_tenant      uuid,
  ticked_domain      uuid,
  observed           jsonb NOT NULL,
  observation_digest text NOT NULL CHECK (observation_digest ~ '^[0-9a-f]{64}$'),
  opened             int NOT NULL DEFAULT 0,
  resolved           int NOT NULL DEFAULT 0,
  holds_opened       int NOT NULL DEFAULT 0,
  holds_lifted       int NOT NULL DEFAULT 0,
  open_after         int NOT NULL DEFAULT 0,
  actor_principal_id uuid NOT NULL,
  recorded_at        timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id     uuid NOT NULL
);
CREATE TRIGGER cmr_append_only BEFORE UPDATE OR DELETE ON governance.cm_monitor_runs FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['governance.cm_manifests', 'governance.cm_release_candidates', 'governance.cm_findings', 'governance.cm_monitor_runs'] LOOP
    EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', t);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', t);
    -- the vendor's registries: readable by every authenticated context (they are not tenant data); written only by the definer ports
    EXECUTE format('CREATE POLICY cm_platform_read ON %s USING (public.eye_scope() <> ''NONE'')', t);
    EXECUTE format('GRANT SELECT ON %s TO eye_app, eye_commit', t);
  END LOOP;
END $$;

-- §CM.3 THE INTERNAL HELPERS (no grant: called inside the definer ports) ─────────────────────────────────────────────────────────────────────
/* An artifact of the shared core, by (kind, external key) at PLATFORM scope: the current version when its digest is unchanged; a NEW VERSION
   (the prior one superseded) when it changed; a new identity when absent. An artifact another part registered is REUSED as it stands (never
   superseded by §CM). Returns the artifact id. */
CREATE OR REPLACE FUNCTION governance._cm_artifact(p_kind text, p_key text, p_title text, p_attrs jsonb, p_volume text, p_lifecycle text, p_actor uuid, p_correlation uuid, p_id uuid DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE a governance.artifacts%ROWTYPE; v_digest text := governance.digest(jsonb_build_object('title', p_title, 'attributes', p_attrs, 'lifecycle', p_lifecycle));
BEGIN
  SELECT * INTO a FROM governance.artifacts x WHERE x.kind = p_kind AND x.external_key = p_key AND x.scope = 'PLATFORM' AND x.superseded_at IS NULL FOR UPDATE;
  IF FOUND THEN
    IF coalesce(a.source ->> 'part', '') <> 'cm' OR a.digest = v_digest THEN RETURN a.artifact_id; END IF;
    UPDATE governance.artifacts SET superseded_at = clock_timestamp() WHERE artifact_id = a.artifact_id AND version = a.version;
    INSERT INTO governance.artifacts (artifact_id, version, scope, kind, external_key, title, authority_class, controlling_volume, lifecycle, attributes, source, digest, recorded_by, correlation_id)
    VALUES (a.artifact_id, a.version + 1, 'PLATFORM', p_kind, p_key, left(p_title, 500), 'engineering', p_volume, p_lifecycle, p_attrs, jsonb_build_object('part', 'cm', 'via', 'governance.cm'), v_digest, p_actor, p_correlation);
    RETURN a.artifact_id;
  END IF;
  INSERT INTO governance.artifacts (artifact_id, version, scope, kind, external_key, title, authority_class, controlling_volume, lifecycle, attributes, source, digest, recorded_by, correlation_id)
  VALUES (coalesce(p_id, gen_random_uuid()), 1, 'PLATFORM', p_kind, p_key, left(p_title, 500), 'engineering', p_volume, p_lifecycle, p_attrs, jsonb_build_object('part', 'cm', 'via', 'governance.cm'), v_digest, p_actor, p_correlation)
  RETURNING artifact_id INTO p_id;
  RETURN p_id;
END $$;
REVOKE ALL ON FUNCTION governance._cm_artifact(text, text, text, jsonb, text, text, uuid, uuid, uuid) FROM PUBLIC;

/* A live link, once: inserted only when no live link (from, to, relation) exists. Returns 1 when inserted. */
CREATE OR REPLACE FUNCTION governance._cm_link(p_from uuid, p_to uuid, p_relation text, p_actor uuid, p_correlation uuid) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from = p_to THEN RETURN 0; END IF;
  IF EXISTS (SELECT 1 FROM governance.links_live l WHERE l.from_artifact = p_from AND l.to_artifact = p_to AND l.relation = p_relation) THEN RETURN 0; END IF;
  INSERT INTO governance.links (link_id, scope, from_artifact, to_artifact, relation, attributes, recorded_by, correlation_id)
  VALUES (gen_random_uuid(), 'PLATFORM', p_from, p_to, p_relation, jsonb_build_object('part', 'cm'), p_actor, p_correlation);
  RETURN 1;
END $$;
REVOKE ALL ON FUNCTION governance._cm_link(uuid, uuid, text, uuid, uuid) FROM PUBLIC;

/* The current PLATFORM artifact of a kind and key, or NULL. */
CREATE OR REPLACE FUNCTION governance._cm_find(p_kind text, p_key text) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT a.artifact_id FROM governance.artifacts a WHERE a.kind = p_kind AND a.external_key = p_key AND a.scope = 'PLATFORM' AND a.superseded_at IS NULL LIMIT 1
$$;
REVOKE ALL ON FUNCTION governance._cm_find(text, text) FROM PUBLIC;

/* THE LINK PASS of a registered manifest version: the desired links (manifest covers unit and component; unit deploys component; unit
   depends_on unit; component maps_to its requirement; component consumes its layer's interfaces and the current version of each schema type
   it owns) inserted once; the links §CM recorded earlier that are no longer desired RETIRED by a later row; the references §RG has not
   registered yet COUNTED (stated, never hidden). Re-running it after §RG's import links what has become resolvable. */
CREATE OR REPLACE FUNCTION governance._cm_link_pass(p_manifest uuid, p_version int, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE
  m governance.cm_manifests%ROWTYPE; u jsonb; c jsonb; x text; v_from uuid; v_to uuid; v_added int := 0; v_retired int := 0;
  v_unres_req int := 0; v_unres_if int := 0; v_unres_schema int := 0; v_desired jsonb := '[]'::jsonb; l record; v_key text;
BEGIN
  SELECT * INTO m FROM governance.cm_manifests WHERE manifest_id = p_manifest AND version = p_version;
  FOR u IN SELECT * FROM jsonb_array_elements(m.index -> 'units') LOOP
    v_from := governance._cm_find('deployable_unit', u ->> 'unit_id');
    v_desired := v_desired || jsonb_build_array(jsonb_build_array(p_manifest, v_from, 'covers'));
    FOR x IN SELECT jsonb_array_elements_text(u -> 'component_ids') LOOP
      v_desired := v_desired || jsonb_build_array(jsonb_build_array(v_from, governance._cm_find('component', x), 'deploys'));
    END LOOP;
    FOR x IN SELECT jsonb_array_elements_text(coalesce(u -> 'dependencies', '[]'::jsonb)) LOOP
      v_desired := v_desired || jsonb_build_array(jsonb_build_array(v_from, governance._cm_find('deployable_unit', x), 'depends_on'));
    END LOOP;
  END LOOP;
  FOR c IN SELECT * FROM jsonb_array_elements(m.index -> 'components') LOOP
    v_from := governance._cm_find('component', c ->> 'component_id');
    v_desired := v_desired || jsonb_build_array(jsonb_build_array(p_manifest, v_from, 'covers'));
    IF c ->> 'requirement' IS NOT NULL THEN
      v_to := governance._cm_find('requirement', c ->> 'requirement');
      IF v_to IS NULL THEN v_unres_req := v_unres_req + 1; ELSE v_desired := v_desired || jsonb_build_array(jsonb_build_array(v_from, v_to, 'maps_to')); END IF;
    END IF;
    FOR x IN SELECT jsonb_array_elements_text(coalesce(c -> 'interfaces', '[]'::jsonb)) LOOP
      v_to := governance._cm_find('interface', x);
      IF v_to IS NULL THEN v_unres_if := v_unres_if + 1; ELSE v_desired := v_desired || jsonb_build_array(jsonb_build_array(v_from, v_to, 'consumes')); END IF;
    END LOOP;
    FOR x IN SELECT jsonb_array_elements_text(coalesce(c -> 'schema_types', '[]'::jsonb)) LOOP
      -- the CURRENT schema version of the type (objects.schema_registry is authoritative; §RG registers each version as `TYPE@vN`)
      SELECT a.artifact_id INTO v_to FROM governance.artifacts a
       WHERE a.kind = 'schema' AND a.scope = 'PLATFORM' AND a.superseded_at IS NULL AND a.external_key ~ ('^' || x || '@v[0-9]+$')
       ORDER BY (substring(a.external_key FROM '@v([0-9]+)$'))::int DESC LIMIT 1;
      IF v_to IS NULL THEN v_unres_schema := v_unres_schema + 1; ELSE v_desired := v_desired || jsonb_build_array(jsonb_build_array(v_from, v_to, 'consumes')); END IF;
    END LOOP;
  END LOOP;
  -- insert the desired links once
  SELECT coalesce(sum(governance._cm_link((d ->> 0)::uuid, (d ->> 1)::uuid, d ->> 2, p_actor, p_correlation)), 0) INTO v_added
    FROM jsonb_array_elements(v_desired) d WHERE d ->> 0 IS NOT NULL AND d ->> 1 IS NOT NULL;
  -- retire §CM's live links that are no longer desired (from this manifest's units / components / the manifest itself)
  FOR l IN SELECT * FROM governance.links_live ll WHERE ll.attributes ->> 'part' = 'cm' AND ll.relation IN ('covers', 'deploys', 'depends_on', 'maps_to', 'consumes')
              AND (ll.from_artifact = p_manifest OR EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.artifact_id = ll.from_artifact AND a.kind IN ('deployable_unit', 'component') AND a.source ->> 'part' = 'cm'))
              AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_desired) d WHERE (d ->> 0)::uuid = ll.from_artifact AND (d ->> 1)::uuid = ll.to_artifact AND d ->> 2 = ll.relation) LOOP
    INSERT INTO governance.links (link_id, scope, from_artifact, to_artifact, relation, retired, retires_link, attributes, recorded_by, correlation_id)
    VALUES (gen_random_uuid(), 'PLATFORM', l.from_artifact, l.to_artifact, l.relation, true, l.link_id, jsonb_build_object('part', 'cm', 'why', 'no longer in the registered manifest'), p_actor, p_correlation);
    v_retired := v_retired + 1;
  END LOOP;
  RETURN jsonb_build_object('links_added', v_added, 'links_retired', v_retired, 'unresolved', jsonb_build_object('requirements', v_unres_req, 'interfaces', v_unres_if, 'schemas', v_unres_schema),
                            'note', 'a reference §RG has not registered (requirement V3:/V6:/V7:<id>, interface L<n>-I0<k>, schema <TYPE>@v<n>) is counted here and linked by a later registration');
END $$;
REVOKE ALL ON FUNCTION governance._cm_link_pass(uuid, int, uuid, uuid) FROM PUBLIC;

/* The OPEN holds on a subject (any part's), but the reason kinds excluded. */
CREATE OR REPLACE FUNCTION governance._cm_open_holds(p_subject uuid, p_exclude text[]) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('hold_id', h.hold_id, 'reason_kind', h.reason_kind, 'reason', h.reason, 'opened_at', h.opened_at, 'source_artifact', h.source_artifact) ORDER BY h.opened_at), '[]'::jsonb)
    FROM governance.holds h WHERE h.subject_artifact = p_subject AND h.lifted_at IS NULL AND NOT (h.reason_kind = ANY (p_exclude))
$$;
REVOKE ALL ON FUNCTION governance._cm_open_holds(uuid, text[]) FROM PUBLIC;

-- §CM.4 THE MANIFEST REGISTRATION ─────────────────────────────────────────────────────────────────────────────────────────────────────────
/* REGISTER the committed component manifest (the conformance steward; the service reads the committed file, its digest and its index — the
   caller supplies no content). An UNMAPPED unit (mapped=false, no component, or a component id the index does not declare) REFUSES the
   registration and PRESERVES the non-conformant record as an open finding (the route answers 422 after the commit). The same digest again is
   UNCHANGED (the link pass still runs: what §RG registered since is linked). A new digest is a new version: every unit and component an
   artifact (a changed entry a new artifact version; a unit or component gone RETIRED), the links re-derived. */
CREATE OR REPLACE FUNCTION governance.cm_register_manifest(p_path text, p_schema text, p_generator text, p_file_digest text, p_index jsonb, p_summary jsonb,
                                                           p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE
  cur governance.cm_manifests%ROWTYPE; v_id uuid; v_version int; v_unmapped jsonb; v_known text[]; u jsonb; c jsonb; v_findings jsonb := '[]'::jsonb; v_f uuid;
  v_links jsonb; v_resolved int; v_retired int := 0; a record;
BEGIN
  PERFORM governance.assert_platform('governance.conformance.manifest.register', p_actor, 'conformance manifest');
  IF p_file_digest IS NULL OR p_file_digest !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'conformance manifest rejected (digest): the committed file''s digest is 64 hex' USING ERRCODE = '22023'; END IF;
  IF p_schema IS NULL OR p_schema !~ '^eye\.components-manifest/v[0-9]+$' THEN RAISE EXCEPTION 'conformance manifest rejected (schema): % is not a component manifest schema', coalesce(p_schema, '<none>') USING ERRCODE = '22023'; END IF;
  IF p_index IS NULL OR jsonb_typeof(p_index -> 'units') <> 'array' OR jsonb_typeof(p_index -> 'components') <> 'array' OR jsonb_array_length(p_index -> 'units') = 0 THEN
    RAISE EXCEPTION 'conformance manifest rejected (index): the manifest names its units and components' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.cm.manifest', 0));
  v_known := ARRAY(SELECT x ->> 'component_id' FROM jsonb_array_elements(p_index -> 'components') x);
  -- IA-01-005 / DP-65-005: a unit that cannot resolve to an approved component identity is REFUSED; the non-conformant record PRESERVED
  SELECT coalesce(jsonb_agg(jsonb_build_object('path', x ->> 'path', 'unit_id', x ->> 'unit_id',
           'why', CASE WHEN (x ->> 'mapped') = 'false' THEN coalesce(x ->> 'reason', 'not mapped') WHEN jsonb_array_length(coalesce(x -> 'component_ids', '[]'::jsonb)) = 0 THEN 'it deploys no component'
                       ELSE 'it names a component the manifest does not declare: ' || (SELECT string_agg(y, ', ') FROM jsonb_array_elements_text(x -> 'component_ids') y WHERE NOT (y = ANY (v_known))) END)), '[]'::jsonb)
    INTO v_unmapped
    FROM jsonb_array_elements(p_index -> 'units') x
   WHERE (x ->> 'mapped') = 'false' OR jsonb_array_length(coalesce(x -> 'component_ids', '[]'::jsonb)) = 0
      OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(coalesce(x -> 'component_ids', '[]'::jsonb)) y WHERE NOT (y = ANY (v_known)));
  IF jsonb_array_length(v_unmapped) > 0 THEN
    FOR u IN SELECT * FROM jsonb_array_elements(v_unmapped) LOOP
      SELECT finding_id INTO v_f FROM governance.cm_findings WHERE fingerprint = 'unmapped_unit:' || (u ->> 'path') AND state = 'open';
      IF v_f IS NULL THEN
        v_f := gen_random_uuid();
        INSERT INTO governance.cm_findings (finding_id, kind, fingerprint, summary, observed, expected, state, opened_by, correlation_id)
        VALUES (v_f, 'unmapped_unit', 'unmapped_unit:' || (u ->> 'path'), format('the deployable unit %s cannot resolve to an approved component identity: %s', u ->> 'path', u ->> 'why'),
                jsonb_build_object('path', u ->> 'path', 'file_digest', p_file_digest), jsonb_build_object('rule', 'every deployable unit deploys at least one declared component (UNIT_MAP)'), 'open', p_actor, p_correlation);
      END IF;
      v_findings := v_findings || jsonb_build_array(v_f);
    END LOOP;
    PERFORM governance.ledger(NULL, NULL, 'conformance_manifest', coalesce((SELECT manifest_id FROM governance.cm_manifests WHERE state = 'current'), '00000000-0000-0000-0000-000000000000'::uuid), NULL,
                              'manifest.refused', p_actor, jsonb_build_object('file_digest', p_file_digest, 'unmapped', v_unmapped, 'findings', v_findings), p_correlation);
    RETURN jsonb_build_object('refused', true, 'class', 'unmapped_unit', 'unmapped', v_unmapped, 'findings', v_findings, 'file_digest', p_file_digest,
                              'preserved', 'the non-conformant record is kept as an open finding; the registration and any promotion of this manifest are refused');
  END IF;

  SELECT * INTO cur FROM governance.cm_manifests WHERE state = 'current' FOR UPDATE;
  IF FOUND AND cur.file_digest = p_file_digest THEN
    v_links := governance._cm_link_pass(cur.manifest_id, cur.version, p_actor, p_correlation);
    UPDATE governance.cm_manifests SET link_report = v_links WHERE manifest_id = cur.manifest_id AND version = cur.version;
    IF (v_links ->> 'links_added')::int > 0 OR (v_links ->> 'links_retired')::int > 0 THEN
      PERFORM governance.ledger(NULL, NULL, 'conformance_manifest', cur.manifest_id, cur.version, 'manifest.relinked', p_actor, v_links, p_correlation);
    END IF;
    RETURN jsonb_build_object('unchanged', true, 'manifest_id', cur.manifest_id, 'version', cur.version, 'file_digest', cur.file_digest, 'links', v_links);
  END IF;

  v_id := coalesce(cur.manifest_id, governance._cm_find('manifest', p_path), gen_random_uuid());
  v_version := coalesce(cur.version, 0) + 1;
  IF cur.manifest_id IS NOT NULL THEN
    UPDATE governance.cm_manifests SET state = 'superseded', superseded_at = clock_timestamp() WHERE manifest_id = cur.manifest_id AND version = cur.version;
  END IF;
  INSERT INTO governance.cm_manifests (manifest_id, version, path, schema, generator, file_digest, index_digest, summary, index, state, registered_by, correlation_id)
  VALUES (v_id, v_version, p_path, p_schema, coalesce(p_generator, ''), p_file_digest, governance.digest(p_index), coalesce(p_summary, '{}'::jsonb), p_index, 'current', p_actor, p_correlation);
  PERFORM governance._cm_artifact('manifest', p_path, 'The component conformance manifest (generated)', jsonb_build_object('file_digest', p_file_digest, 'version', v_version, 'schema', p_schema, 'summary', p_summary),
                                  'V4', 'active', p_actor, p_correlation, v_id);
  FOR u IN SELECT * FROM jsonb_array_elements(p_index -> 'units') LOOP
    PERFORM governance._cm_artifact('deployable_unit', u ->> 'unit_id', format('%s (%s)', u ->> 'unit_id', u ->> 'path'), u - 'mapped', 'V4', 'active', p_actor, p_correlation);
  END LOOP;
  FOR c IN SELECT * FROM jsonb_array_elements(p_index -> 'components') LOOP
    PERFORM governance._cm_artifact('component', c ->> 'component_id', coalesce(nullif(c ->> 'name', ''), c ->> 'component_id'), c,
                                    CASE c ->> 'kind' WHEN 'logical' THEN 'V3' WHEN 'infrastructure' THEN 'V6' WHEN 'data' THEN 'V7' ELSE 'V4' END, 'active', p_actor, p_correlation);
  END LOOP;
  -- a unit or a component §CM registered that this manifest no longer declares is RETIRED (a new version), never deleted
  FOR a IN SELECT x.* FROM governance.artifacts x WHERE x.scope = 'PLATFORM' AND x.superseded_at IS NULL AND x.source ->> 'part' = 'cm' AND x.lifecycle <> 'retired'
             AND ((x.kind = 'deployable_unit' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_index -> 'units') y WHERE y ->> 'unit_id' = x.external_key))
               OR (x.kind = 'component' AND NOT (x.external_key = ANY (v_known)))) LOOP
    PERFORM governance._cm_artifact(a.kind, a.external_key, a.title, a.attributes, a.controlling_volume, 'retired', p_actor, p_correlation);
    v_retired := v_retired + 1;
  END LOOP;
  v_links := governance._cm_link_pass(v_id, v_version, p_actor, p_correlation);
  UPDATE governance.cm_manifests SET link_report = v_links WHERE manifest_id = v_id AND version = v_version;
  -- the unmapped-unit findings close: this manifest maps every unit
  UPDATE governance.cm_findings SET state = 'resolved', resolved_by = p_actor, resolved_at = clock_timestamp(), resolution = format('manifest v%s maps every unit', v_version)
   WHERE kind = 'unmapped_unit' AND state = 'open';
  GET DIAGNOSTICS v_resolved = ROW_COUNT;
  PERFORM governance.ledger(NULL, NULL, 'conformance_manifest', v_id, v_version, 'manifest.registered', p_actor,
                            jsonb_build_object('file_digest', p_file_digest, 'summary', p_summary, 'links', v_links, 'retired', v_retired, 'findings_resolved', v_resolved), p_correlation);
  RETURN jsonb_build_object('manifest_id', v_id, 'version', v_version, 'file_digest', p_file_digest, 'units', jsonb_array_length(p_index -> 'units'), 'components', jsonb_array_length(p_index -> 'components'),
                            'retired', v_retired, 'links', v_links, 'findings_resolved', v_resolved, 'superseded_version', cur.version);
END $$;
REVOKE ALL ON FUNCTION governance.cm_register_manifest(text, text, text, text, jsonb, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.cm_register_manifest(text, text, text, text, jsonb, jsonb, uuid, uuid) TO eye_commit;

-- §CM.5 THE RELEASE CANDIDATE ─────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* ASSEMBLE (or AMEND: a new version over renewed evidence) a release candidate — the conformance steward. The port binds what it can read
   itself: the migration head (public.schema_migrations), the CURRENT registered manifest (its version, file digest and units = the topology).
   The runtime's head SHA and policy bundle come from the service (the server's own build identity, never the client's). The evidence items
   are validated for shape here; their truth is the CHECK's. */
CREATE OR REPLACE FUNCTION governance.cm_assemble_candidate(p_candidate uuid, p_expected_version int, p_label text, p_head_sha text, p_policy jsonb, p_config_digest text, p_profile text,
                                                            p_scope jsonb, p_period_from date, p_period_to date, p_evidence jsonb, p_builders uuid[], p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, tenancy, public, pg_catalog, pg_temp AS $$
DECLARE
  prev governance.cm_release_candidates%ROWTYPE; m governance.cm_manifests%ROWTYPE; v_id uuid := coalesce(p_candidate, gen_random_uuid()); v_version int; v_items jsonb := '[]'::jsonb;
  e jsonb; v_n int := 0; v_topology jsonb; v_identity jsonb; v_digest text; v_scope jsonb; v_art uuid; v_ev uuid;
BEGIN
  PERFORM governance.assert_platform('governance.conformance.candidate.assemble', p_actor, 'release candidate');
  IF length(btrim(coalesce(p_label, ''))) < 3 THEN RAISE EXCEPTION 'release candidate rejected (label): a candidate is labelled (3+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_head_sha IS NULL OR NOT (p_head_sha ~ '^[0-9a-f]{40}$' OR p_head_sha = 'unknown') THEN RAISE EXCEPTION 'release candidate rejected (head): the head SHA is 40 hex (or unknown — then the check refuses it)' USING ERRCODE = '22023'; END IF;
  IF p_policy IS NULL OR (p_policy ->> 'digest') !~ '^[0-9a-f]{64}$' OR length(coalesce(p_policy ->> 'version', '')) = 0 THEN RAISE EXCEPTION 'release candidate rejected (policy): the policy bundle names its version and digest' USING ERRCODE = '22023'; END IF;
  IF p_config_digest IS NULL OR p_config_digest !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'release candidate rejected (config): the configuration digest is 64 hex' USING ERRCODE = '22023'; END IF;
  IF p_profile IS DISTINCT FROM 'local-dev' THEN RAISE EXCEPTION 'release candidate rejected (profile): only local-dev is a real profile here (the profile catalogue is B106/B111)' USING ERRCODE = '22023'; END IF;
  IF p_period_from IS NULL OR p_period_to IS NULL OR p_period_to < p_period_from THEN RAISE EXCEPTION 'release candidate rejected (period): the period under review runs from a day to a later or the same day' USING ERRCODE = '22023'; END IF;
  -- the customer scope: the platform, or named tenants (and domains of them) that exist
  IF p_scope IS NULL OR p_scope ->> 'kind' NOT IN ('platform', 'tenants') THEN RAISE EXCEPTION 'release candidate rejected (scope): the customer scope is platform or named tenants' USING ERRCODE = '22023'; END IF;
  IF p_scope ->> 'kind' = 'tenants' THEN
    IF jsonb_typeof(p_scope -> 'tenants') <> 'array' OR jsonb_array_length(p_scope -> 'tenants') = 0
       OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_scope -> 'tenants') t WHERE t !~ '^[0-9a-f-]{36}$' OR NOT EXISTS (SELECT 1 FROM tenancy.tenants x WHERE x.id = t::uuid))
       OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(coalesce(p_scope -> 'domains', '[]'::jsonb)) dd WHERE dd !~ '^[0-9a-f-]{36}$'
                   OR NOT EXISTS (SELECT 1 FROM tenancy.domains y WHERE y.id = dd::uuid AND y.tenant_id::text IN (SELECT jsonb_array_elements_text(p_scope -> 'tenants')))) THEN
      RAISE EXCEPTION 'release candidate rejected (scope): every named tenant exists, and every named domain is one of theirs' USING ERRCODE = '22023';
    END IF;
  END IF;
  v_scope := jsonb_build_object('kind', p_scope ->> 'kind', 'tenants', coalesce(p_scope -> 'tenants', '[]'::jsonb), 'domains', coalesce(p_scope -> 'domains', '[]'::jsonb));
  -- the evidence items (shape only; the check judges them)
  IF p_evidence IS NULL OR jsonb_typeof(p_evidence) <> 'array' OR jsonb_array_length(p_evidence) > 200 THEN RAISE EXCEPTION 'release candidate rejected (evidence): the evidence is a list of at most 200 items' USING ERRCODE = '22023'; END IF;
  FOR e IN SELECT * FROM jsonb_array_elements(p_evidence) LOOP
    v_n := v_n + 1;
    IF jsonb_typeof(e) <> 'object' OR NOT ((e ->> 'family') = ANY (governance.cm_evidence_families())) OR e ->> 'kind' NOT IN ('test_report', 'gate_receipt', 'artifact', 'review_record')
       OR length(btrim(coalesce(e ->> 'ref', ''))) < 3 OR e ->> 'captured_at' IS NULL OR e ->> 'valid_until' IS NULL
       OR (e ->> 'artifact_id' IS NOT NULL AND (e ->> 'artifact_id') !~ '^[0-9a-f-]{36}$') THEN
      RAISE EXCEPTION 'release candidate rejected (evidence): item % names a family (%), a kind (test_report | gate_receipt | artifact | review_record), a ref, captured_at and valid_until',
        v_n, array_to_string(governance.cm_evidence_families(), ' | ') USING ERRCODE = '22023';
    END IF;
    IF (e ->> 'valid_until')::timestamptz <= (e ->> 'captured_at')::timestamptz THEN
      RAISE EXCEPTION 'release candidate rejected (evidence): item % is valid until after it was captured', v_n USING ERRCODE = '22023';
    END IF;
    v_items := v_items || jsonb_build_array(jsonb_build_object('item', v_n, 'family', e ->> 'family', 'kind', e ->> 'kind', 'ref', btrim(e ->> 'ref'), 'artifact_id', e ->> 'artifact_id',
      'digest', e ->> 'digest', 'bound_head_sha', e ->> 'bound_head_sha', 'captured_at', (e ->> 'captured_at')::timestamptz, 'valid_until', (e ->> 'valid_until')::timestamptz,
      'note', e ->> 'note'));
  END LOOP;
  IF p_builders IS NOT NULL AND EXISTS (SELECT 1 FROM unnest(p_builders) b WHERE NOT EXISTS (SELECT 1 FROM identity.principals x WHERE x.id = b)) THEN
    RAISE EXCEPTION 'release candidate rejected (builders): every declared builder is a principal' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO m FROM governance.cm_manifests WHERE state = 'current';
  IF NOT FOUND THEN RAISE EXCEPTION 'release candidate rejected (state): no component manifest is registered — the steward registers the committed manifest first' USING ERRCODE = '23505'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.cm.candidate:' || v_id::text, 0));
  IF p_candidate IS NULL THEN
    IF coalesce(p_expected_version, 0) <> 0 THEN RAISE EXCEPTION 'release candidate rejected (stale): a new candidate expects version 0' USING ERRCODE = '23505'; END IF;
    v_version := 1;
  ELSE
    SELECT * INTO prev FROM governance.cm_release_candidates WHERE candidate_id = p_candidate AND state <> 'superseded' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'release candidate rejected (unknown_candidate): no candidate %', p_candidate USING ERRCODE = '23503'; END IF;
    IF prev.version <> p_expected_version THEN RAISE EXCEPTION 'release candidate rejected (stale): the candidate is at version %, not %', prev.version, p_expected_version USING ERRCODE = '23505'; END IF;
    IF prev.state IN ('attested', 'withdrawn') THEN RAISE EXCEPTION 'release candidate rejected (state): version % is %; assemble a new candidate', prev.version, prev.state USING ERRCODE = '23505'; END IF;
    UPDATE governance.cm_release_candidates SET state = 'superseded' WHERE candidate_id = p_candidate AND version = prev.version;
    v_version := prev.version + 1;
  END IF;
  v_topology := jsonb_build_object('units', (SELECT coalesce(jsonb_agg(u ->> 'unit_id' ORDER BY u ->> 'unit_id'), '[]'::jsonb) FROM jsonb_array_elements(m.index -> 'units') u), 'manifest_index_digest', m.index_digest);
  v_identity := jsonb_build_object('candidate_id', v_id, 'version', v_version, 'label', btrim(p_label), 'head_sha', p_head_sha, 'migration_head', governance.cm_migration_head(),
    'policy_bundle', jsonb_build_object('version', p_policy ->> 'version', 'digest', p_policy ->> 'digest'), 'manifest', jsonb_build_object('id', m.manifest_id, 'version', m.version, 'digest', m.file_digest),
    'config_digest', p_config_digest, 'profile', p_profile, 'scope', v_scope, 'topology', v_topology, 'period', jsonb_build_array(p_period_from, p_period_to),
    'evidence_digest', governance.digest(v_items), 'builders', to_jsonb(coalesce(p_builders, '{}'::uuid[])), 'claim', 'demonstration', 'release', 'not_a_release');
  v_digest := governance.digest(v_identity);
  INSERT INTO governance.cm_release_candidates (candidate_id, version, label, head_sha, migration_head, policy_bundle, manifest_id, manifest_version, manifest_digest, config_digest, deployment_profile,
    customer_scope, topology, period_from, period_to, evidence, evidence_digest, builders, digest, state, proposed_by, correlation_id)
  VALUES (v_id, v_version, btrim(p_label), p_head_sha, governance.cm_migration_head(), v_identity -> 'policy_bundle', m.manifest_id, m.version, m.file_digest, p_config_digest, p_profile,
    v_scope, v_topology, p_period_from, p_period_to, v_items, governance.digest(v_items), coalesce(p_builders, '{}'::uuid[]), v_digest, 'assembled', p_actor, p_correlation);
  v_art := governance._cm_artifact('release_candidate', 'RC:' || v_id::text, format('%s (release candidate — not a release)', btrim(p_label)),
                                   jsonb_build_object('version', v_version, 'digest', v_digest, 'state', 'assembled', 'head_sha', p_head_sha, 'manifest_version', m.version), 'V4', 'proposed', p_actor, p_correlation, v_id);
  PERFORM governance._cm_link(v_art, m.manifest_id, 'covers', p_actor, p_correlation);
  FOR e IN SELECT * FROM jsonb_array_elements(v_items) LOOP
    IF e ->> 'artifact_id' IS NOT NULL THEN
      v_ev := (SELECT a.artifact_id FROM governance.artifacts a WHERE a.artifact_id = (e ->> 'artifact_id')::uuid AND a.superseded_at IS NULL);
      IF v_ev IS NOT NULL THEN PERFORM governance._cm_link(v_ev, v_art, 'evidences', p_actor, p_correlation); END IF;
    END IF;
  END LOOP;
  PERFORM governance.ledger(NULL, NULL, 'release_candidate', v_id, v_version, CASE WHEN v_version = 1 THEN 'candidate.assembled' ELSE 'candidate.amended' END, p_actor,
                            jsonb_build_object('digest', v_digest, 'label', btrim(p_label), 'head_sha', p_head_sha, 'manifest_version', m.version, 'items', jsonb_array_length(v_items), 'release', 'not_a_release'), p_correlation);
  RETURN (SELECT to_jsonb(c) FROM governance.cm_release_candidates c WHERE c.candidate_id = v_id AND c.version = v_version);
END $$;
REVOKE ALL ON FUNCTION governance.cm_assemble_candidate(uuid, int, text, text, jsonb, text, text, jsonb, date, date, jsonb, uuid[], uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.cm_assemble_candidate(uuid, int, text, text, jsonb, text, text, jsonb, date, date, jsonb, uuid[], uuid, uuid) TO eye_commit;

/* THE EVIDENCE VERDICT of a candidate version, as of NOW (database clock) — pure reading; the check records it, the attestation re-reads it.
   Each reason: {class: evidence | stale | unverifiable | foreign_version, …}. */
CREATE OR REPLACE FUNCTION governance._cm_verdict(p_candidate uuid, p_version int) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE c governance.cm_release_candidates%ROWTYPE; r jsonb := '[]'::jsonb; f text; e jsonb; a governance.artifacts%ROWTYPE; m governance.cm_manifests%ROWTYPE; v_now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO c FROM governance.cm_release_candidates WHERE candidate_id = p_candidate AND version = p_version;
  SELECT * INTO m FROM governance.cm_manifests WHERE state = 'current';
  IF c.head_sha = 'unknown' THEN r := r || jsonb_build_array(jsonb_build_object('class', 'unverifiable', 'what', 'head', 'detail', 'the build''s head SHA is unknown: no evidence can be bound to it')); END IF;
  IF m.manifest_id IS NULL OR m.version <> c.manifest_version OR m.file_digest <> c.manifest_digest THEN
    r := r || jsonb_build_array(jsonb_build_object('class', 'foreign_version', 'what', 'manifest', 'detail', format('the candidate is bound to manifest v%s (%s); the registered manifest is %s', c.manifest_version, left(c.manifest_digest, 12),
                                 coalesce('v' || m.version || ' (' || left(m.file_digest, 12) || ')', 'none'))));
  END IF;
  IF c.migration_head IS DISTINCT FROM governance.cm_migration_head() THEN
    r := r || jsonb_build_array(jsonb_build_object('class', 'foreign_version', 'what', 'migration_head', 'detail', format('the candidate names %s; the database runs %s', c.migration_head, governance.cm_migration_head())));
  END IF;
  FOREACH f IN ARRAY governance.cm_required_families() LOOP
    IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(c.evidence) x WHERE x ->> 'family' = f) THEN
      r := r || jsonb_build_array(jsonb_build_object('class', 'evidence', 'what', 'family', 'family', f, 'detail', format('no %s evidence: the family is required (absent evidence refuses the candidate)', replace(f, '_', ' '))));
    END IF;
  END LOOP;
  FOR e IN SELECT * FROM jsonb_array_elements(c.evidence) LOOP
    IF coalesce(e ->> 'digest', '') !~ '^[0-9a-f]{64}$' THEN
      r := r || jsonb_build_array(jsonb_build_object('class', 'unverifiable', 'what', 'item', 'item', e -> 'item', 'ref', e ->> 'ref', 'detail', 'the item carries no digest (64 hex) — it cannot be verified'));
    END IF;
    IF (e ->> 'captured_at')::timestamptz > v_now THEN
      r := r || jsonb_build_array(jsonb_build_object('class', 'unverifiable', 'what', 'item', 'item', e -> 'item', 'ref', e ->> 'ref', 'detail', 'the item claims a capture in the future'));
    END IF;
    IF (e ->> 'valid_until')::timestamptz <= v_now THEN
      r := r || jsonb_build_array(jsonb_build_object('class', 'stale', 'what', 'item', 'item', e -> 'item', 'ref', e ->> 'ref', 'family', e ->> 'family', 'valid_until', e ->> 'valid_until',
                                                     'detail', format('the %s evidence %s expired at %s', replace(e ->> 'family', '_', ' '), e ->> 'ref', e ->> 'valid_until')));
    END IF;
    IF coalesce(e ->> 'bound_head_sha', '') <> c.head_sha THEN
      r := r || jsonb_build_array(jsonb_build_object('class', 'foreign_version', 'what', 'item', 'item', e -> 'item', 'ref', e ->> 'ref',
                                                     'detail', format('the item is bound to head %s, the candidate is %s', coalesce(left(e ->> 'bound_head_sha', 12), '<none>'), left(c.head_sha, 12))));
    END IF;
    IF e ->> 'artifact_id' IS NOT NULL THEN
      SELECT * INTO a FROM governance.artifacts x WHERE x.artifact_id = (e ->> 'artifact_id')::uuid ORDER BY x.version DESC LIMIT 1;
      IF NOT FOUND THEN
        r := r || jsonb_build_array(jsonb_build_object('class', 'unverifiable', 'what', 'item', 'item', e -> 'item', 'ref', e ->> 'ref', 'detail', 'the evidence artifact is not registered'));
      ELSIF a.superseded_at IS NOT NULL OR a.lifecycle IN ('retired', 'superseded', 'quarantined') THEN
        r := r || jsonb_build_array(jsonb_build_object('class', 'unverifiable', 'what', 'item', 'item', e -> 'item', 'ref', e ->> 'ref', 'detail', format('the evidence artifact is %s', CASE WHEN a.superseded_at IS NOT NULL THEN 'superseded' ELSE a.lifecycle END)));
      ELSIF a.digest <> coalesce(e ->> 'digest', '') AND coalesce(a.attributes ->> 'content_digest', '') <> coalesce(e ->> 'digest', '') THEN
        r := r || jsonb_build_array(jsonb_build_object('class', 'unverifiable', 'what', 'item', 'item', e -> 'item', 'ref', e ->> 'ref', 'detail', 'the item''s digest is not the registered artifact''s'));
      ELSIF a.attributes ? 'head_sha' AND a.attributes ->> 'head_sha' <> c.head_sha THEN
        r := r || jsonb_build_array(jsonb_build_object('class', 'foreign_version', 'what', 'item', 'item', e -> 'item', 'ref', e ->> 'ref', 'detail', format('the evidence artifact was produced at head %s', left(a.attributes ->> 'head_sha', 12))));
      END IF;
    END IF;
  END LOOP;
  RETURN r;
END $$;
REVOKE ALL ON FUNCTION governance._cm_verdict(uuid, int) FROM PUBLIC;

/* THE CHECK (the steward): the verdict as of now, the candidate's OPEN holds (an expired exception, a conflict, a conformance drift — any hold
   but the evidence holds this check manages itself), the outcome recorded (conformant | refused | held), the evidence holds opened for what is
   stale (evidence_stale) or absent / unverifiable / foreign (evidence_missing) and lifted when no longer so. The route answers the refusal
   AFTER the commit (the record and its holds stand). */
CREATE OR REPLACE FUNCTION governance.cm_check_candidate(p_candidate uuid, p_version int, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE
  c governance.cm_release_candidates%ROWTYPE; v_reasons jsonb; v_holds jsonb; v_outcome text; v_opened jsonb := '[]'::jsonb; v_lifted int := 0; v_kind text; v_need boolean; v_text text; v_h uuid;
  v_result jsonb; v_n int;
BEGIN
  PERFORM governance.assert_platform('governance.conformance.candidate.check', p_actor, 'release candidate');
  SELECT * INTO c FROM governance.cm_release_candidates WHERE candidate_id = p_candidate AND version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'release candidate rejected (unknown_candidate): no candidate %/v%', p_candidate, p_version USING ERRCODE = '23503'; END IF;
  IF c.state IN ('superseded', 'attested', 'withdrawn') THEN RAISE EXCEPTION 'release candidate rejected (state): version % is %', p_version, c.state USING ERRCODE = '23505'; END IF;
  v_reasons := governance._cm_verdict(p_candidate, p_version);
  -- the evidence holds this check manages: opened for what the verdict finds, lifted when it no longer does
  FOREACH v_kind IN ARRAY ARRAY['evidence_stale', 'evidence_missing'] LOOP
    v_need := EXISTS (SELECT 1 FROM jsonb_array_elements(v_reasons) x WHERE (v_kind = 'evidence_stale' AND x ->> 'class' = 'stale') OR (v_kind = 'evidence_missing' AND x ->> 'class' IN ('evidence', 'unverifiable', 'foreign_version')));
    IF v_need THEN
      IF NOT EXISTS (SELECT 1 FROM governance.holds h WHERE h.subject_artifact = p_candidate AND h.reason_kind = v_kind AND h.lifted_at IS NULL) THEN
        v_text := (SELECT string_agg(x ->> 'detail', '; ') FROM jsonb_array_elements(v_reasons) x
                    WHERE (v_kind = 'evidence_stale' AND x ->> 'class' = 'stale') OR (v_kind = 'evidence_missing' AND x ->> 'class' IN ('evidence', 'unverifiable', 'foreign_version')));
        v_h := gen_random_uuid();
        INSERT INTO governance.holds (hold_id, scope, subject_artifact, reason_kind, reason, opened_by, correlation_id)
        VALUES (v_h, 'PLATFORM', p_candidate, v_kind, left(format('release candidate %s v%s: %s', c.label, p_version, v_text), 2000), p_actor, p_correlation);
        v_opened := v_opened || jsonb_build_array(jsonb_build_object('hold_id', v_h, 'reason_kind', v_kind));
      END IF;
    ELSE
      UPDATE governance.holds SET lifted_at = clock_timestamp(), lifted_by = p_actor, lift_reason = format('the check of v%s finds no %s evidence', p_version, CASE v_kind WHEN 'evidence_stale' THEN 'stale' ELSE 'absent, unverifiable or foreign' END)
       WHERE subject_artifact = p_candidate AND reason_kind = v_kind AND lifted_at IS NULL;
      GET DIAGNOSTICS v_n = ROW_COUNT; v_lifted := v_lifted + v_n;
    END IF;
  END LOOP;
  v_holds := governance._cm_open_holds(p_candidate, ARRAY['evidence_stale', 'evidence_missing']);
  v_outcome := CASE WHEN jsonb_array_length(v_holds) > 0 THEN 'held' WHEN jsonb_array_length(v_reasons) > 0 THEN 'refused' ELSE 'conformant' END;
  v_result := jsonb_build_object('outcome', v_outcome, 'reasons', v_reasons, 'holds', v_holds, 'required_families', to_jsonb(governance.cm_required_families()),
    'carried_families', (SELECT jsonb_agg(f) FROM unnest(governance.cm_evidence_families()) f WHERE NOT (f = ANY (governance.cm_required_families()))),
    'carried_by', 'quality: B64 / H1 · deployment: B106 / B111 · operations: B63 / B64 — never inferred present',
    'checked_at', clock_timestamp(), 'version', p_version, 'digest', c.digest, 'evidence_holds_opened', v_opened, 'evidence_holds_lifted', v_lifted,
    'not_a_release', 'a conformant candidate is a local conformance record — not a release (B65), not production admission (R1)');
  UPDATE governance.cm_release_candidates SET state = v_outcome, check_result = v_result, checked_by = p_actor, checked_at = clock_timestamp()
   WHERE candidate_id = p_candidate AND version = p_version;
  PERFORM governance._cm_artifact('release_candidate', 'RC:' || p_candidate::text, format('%s (release candidate — not a release)', c.label),
                                  jsonb_build_object('version', p_version, 'digest', c.digest, 'state', v_outcome, 'head_sha', c.head_sha, 'manifest_version', c.manifest_version), 'V4', 'proposed', p_actor, p_correlation, p_candidate);
  PERFORM governance.ledger(NULL, NULL, 'release_candidate', p_candidate, p_version, 'candidate.checked', p_actor,
                            jsonb_build_object('outcome', v_outcome, 'reasons', v_reasons, 'holds', v_holds, 'evidence_holds_opened', v_opened), p_correlation);
  RETURN v_result || jsonb_build_object('candidate_id', p_candidate, 'label', c.label);
END $$;
REVOKE ALL ON FUNCTION governance.cm_check_candidate(uuid, int, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.cm_check_candidate(uuid, int, uuid, uuid) TO eye_commit;

/* ATTEST a conformant candidate (independent assurance — a named human; never the proposer, never a builder, never an agent): on the exact
   digest, RE-CHECKED at this instant (no open hold of any kind, no evidence expired since the check, nothing foreign since), SIGNED
   (`manifest_attestation`, the PLATFORM signature written here after the approver test). Not a release (B65); not production admission (R1). */
CREATE OR REPLACE FUNCTION governance.cm_attest_candidate(p_candidate uuid, p_version int, p_digest text, p_reason text, p_key_id text, p_signature text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE c governance.cm_release_candidates%ROWTYPE; v_now jsonb; v_holds jsonb; v_sig uuid := gen_random_uuid();
BEGIN
  PERFORM governance.assert_platform('governance.conformance.candidate.attest', p_actor, 'release candidate');
  SELECT * INTO c FROM governance.cm_release_candidates WHERE candidate_id = p_candidate AND version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'release candidate rejected (unknown_candidate): no candidate %/v%', p_candidate, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('release candidate', p_actor, NULL, NULL, ARRAY['independent_assurance'], c.proposed_by, c.builders, 'attesting a release candidate''s conformance');
  IF c.state <> 'conformant' THEN RAISE EXCEPTION 'release candidate rejected (state): version % is %; only a conformant check is attested', p_version, c.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM c.digest THEN RAISE EXCEPTION 'release candidate rejected (stale): the attestation names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'release candidate rejected (reason): an attestation states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  v_holds := governance._cm_open_holds(p_candidate, ARRAY[]::text[]);
  IF jsonb_array_length(v_holds) > 0 THEN
    RAISE EXCEPTION 'release candidate rejected (held): % — the candidate is held at this instant', (SELECT string_agg((h ->> 'reason_kind') || ': ' || (h ->> 'reason'), '; ') FROM jsonb_array_elements(v_holds) h) USING ERRCODE = '23505';
  END IF;
  v_now := governance._cm_verdict(p_candidate, p_version);
  IF jsonb_array_length(v_now) > 0 THEN
    RAISE EXCEPTION 'release candidate rejected (stale): the check is no longer true — %', (SELECT string_agg(x ->> 'detail', '; ') FROM jsonb_array_elements(v_now) x) USING ERRCODE = '23505';
  END IF;
  IF p_key_id IS NULL OR p_key_id !~ '^ed25519:[0-9a-f]{16}$' OR p_signature IS NULL OR p_signature !~ '^[A-Za-z0-9+/]{86}==$' THEN
    RAISE EXCEPTION 'release candidate rejected (signature): the attestation carries the attester''s Ed25519 signature over the candidate''s digest' USING ERRCODE = '22023';
  END IF;
  INSERT INTO governance.signatures (signature_id, scope, subject_kind, subject_id, subject_version, subject_digest, signer, signer_role, key_id, algorithm, signature, bound_action, correlation_id)
  VALUES (v_sig, 'PLATFORM', 'manifest_attestation', p_candidate, p_version, c.digest, p_actor, 'independent_assurance', p_key_id, 'ed25519', p_signature, 'governance.conformance.candidate.attest', p_correlation);
  UPDATE governance.cm_release_candidates SET state = 'attested', attested_by = p_actor, attested_at = clock_timestamp(), attestation_reason = btrim(p_reason), signature_id = v_sig
   WHERE candidate_id = p_candidate AND version = p_version;
  PERFORM governance._cm_artifact('release_candidate', 'RC:' || p_candidate::text, format('%s (release candidate — not a release)', c.label),
                                  jsonb_build_object('version', p_version, 'digest', c.digest, 'state', 'attested', 'head_sha', c.head_sha, 'manifest_version', c.manifest_version, 'signature_id', v_sig), 'V4', 'active', p_actor, p_correlation, p_candidate);
  PERFORM governance.ledger(NULL, NULL, 'release_candidate', p_candidate, p_version, 'candidate.attested', p_actor,
                            jsonb_build_object('digest', c.digest, 'signature_id', v_sig, 'reason', btrim(p_reason), 'release', 'not_a_release (B65)', 'production_admission', 'R1'), p_correlation);
  RETURN jsonb_build_object('candidate_id', p_candidate, 'version', p_version, 'state', 'attested', 'digest', c.digest, 'signature_id', v_sig,
                            'boundary', 'attested conformant on local evidence — NOT a release (B65 substituted), NOT production admission (R1), NOT real acceptance (R2)');
END $$;
REVOKE ALL ON FUNCTION governance.cm_attest_candidate(uuid, int, text, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.cm_attest_candidate(uuid, int, text, text, text, text, uuid, uuid) TO eye_commit;

/* WITHDRAW a candidate (the steward or the product authority): withdrawn, its §CM holds (evidence, drift) lifted with the reason; the holds of
   other parts (an expired exception, a conflict) are theirs to lift. */
CREATE OR REPLACE FUNCTION governance.cm_withdraw_candidate(p_candidate uuid, p_version int, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE c governance.cm_release_candidates%ROWTYPE; v_lifted int;
BEGIN
  PERFORM governance.assert_platform('governance.conformance.candidate.withdraw', p_actor, 'release candidate');
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['conformance_steward', 'product_authority']) THEN
    RAISE EXCEPTION 'release candidate rejected (authority): withdrawing a candidate is the conformance steward''s or the product authority''s act' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO c FROM governance.cm_release_candidates WHERE candidate_id = p_candidate AND version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'release candidate rejected (unknown_candidate): no candidate %/v%', p_candidate, p_version USING ERRCODE = '23503'; END IF;
  IF c.state IN ('withdrawn', 'superseded') THEN RAISE EXCEPTION 'release candidate rejected (state): version % is %', p_version, c.state USING ERRCODE = '23505'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'release candidate rejected (reason): a withdrawal states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  UPDATE governance.cm_release_candidates SET state = 'withdrawn', withdrawn_by = p_actor, withdrawn_at = clock_timestamp(), withdraw_reason = btrim(p_reason) WHERE candidate_id = p_candidate AND version = p_version;
  UPDATE governance.holds SET lifted_at = clock_timestamp(), lifted_by = p_actor, lift_reason = 'the release candidate was withdrawn: ' || btrim(p_reason)
   WHERE subject_artifact = p_candidate AND lifted_at IS NULL AND reason_kind IN ('evidence_stale', 'evidence_missing', 'conformance_drift');
  GET DIAGNOSTICS v_lifted = ROW_COUNT;
  PERFORM governance._cm_artifact('release_candidate', 'RC:' || p_candidate::text, format('%s (release candidate — not a release)', c.label),
                                  jsonb_build_object('version', p_version, 'digest', c.digest, 'state', 'withdrawn', 'head_sha', c.head_sha, 'manifest_version', c.manifest_version), 'V4', 'retired', p_actor, p_correlation, p_candidate);
  PERFORM governance.ledger(NULL, NULL, 'release_candidate', p_candidate, p_version, 'candidate.withdrawn', p_actor, jsonb_build_object('reason', btrim(p_reason), 'holds_lifted', v_lifted), p_correlation);
  RETURN jsonb_build_object('candidate_id', p_candidate, 'version', p_version, 'state', 'withdrawn', 'holds_lifted', v_lifted);
END $$;
REVOKE ALL ON FUNCTION governance.cm_withdraw_candidate(uuid, int, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.cm_withdraw_candidate(uuid, int, text, uuid, uuid) TO eye_commit;

-- §CM.6 THE CONFORMANCE MONITOR ───────────────────────────────────────────────────────────────────────────────────────────────────────────
/* RECORD what the monitor observed (the after-tick hook under the attention agent — its own action, governance.conformance.monitor, on the
   ticking DOMAIN's route — or the conformance steward at PLATFORM). The service READ FIRST (the build identity, the committed manifest, the
   registered state) and computed the findings; this write reconciles them BY FINGERPRINT: a new one opened (with a `conformance_drift` — or,
   for expired evidence, an `evidence_stale` — hold on its subject candidate when it asks for one; the hold's source is the finding), an open monitor finding no longer observed RESOLVED (its
   hold lifted). A run is recorded on change. PLATFORM rows only (no attention item — the workspace and the ledger show them). */
CREATE OR REPLACE FUNCTION governance.cm_record_monitor(p_observed jsonb, p_findings jsonb, p_via text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE
  f jsonb; v_id uuid; v_opened int := 0; v_resolved int := 0; v_hopen int := 0; v_hlift int := 0; v_digest text; v_last text; o record; v_subject uuid; v_run uuid := NULL; v_n int;
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.conformance.monitor']);
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN
    RAISE EXCEPTION 'conformance finding rejected (actor): the monitor records under the acting principal' USING ERRCODE = '42501';
  END IF;
  IF NOT ((public.eye_scope() = 'PLATFORM' AND governance.holds_role(p_actor, NULL, NULL, ARRAY['conformance_steward']))
          OR (public.eye_scope() = 'DOMAIN' AND governance.holds_role(p_actor, public.eye_tenant(), public.eye_domain(), ARRAY['attention_agent']))) THEN
    RAISE EXCEPTION 'conformance finding rejected (authority): the conformance monitor runs under the attention tick (attention agent) or the conformance steward' USING ERRCODE = '42501';
  END IF;
  IF p_via NOT IN ('tick', 'steward') OR (p_via = 'tick') <> (public.eye_scope() = 'DOMAIN') THEN
    RAISE EXCEPTION 'conformance finding rejected (via): a tick records from a domain''s tick, the steward from PLATFORM' USING ERRCODE = '22023';
  END IF;
  IF p_observed IS NULL OR jsonb_typeof(p_observed) <> 'object' OR p_findings IS NULL OR jsonb_typeof(p_findings) <> 'array' THEN
    RAISE EXCEPTION 'conformance finding rejected (observation): the monitor records its observation and its findings' USING ERRCODE = '22023';
  END IF;
  FOR f IN SELECT * FROM jsonb_array_elements(p_findings) LOOP
    IF NOT ((f ->> 'kind') = ANY (governance.cm_monitor_kinds())) OR length(coalesce(f ->> 'fingerprint', '')) < 3 OR length(btrim(coalesce(f ->> 'summary', ''))) < 8
       OR (f ->> 'subject_artifact' IS NOT NULL AND (f ->> 'subject_artifact') !~ '^[0-9a-f-]{36}$') OR coalesce(f ->> 'hold_kind', 'conformance_drift') NOT IN ('conformance_drift', 'evidence_stale') THEN
      RAISE EXCEPTION 'conformance finding rejected (finding): each finding names a monitor kind (%), a fingerprint, a summary', array_to_string(governance.cm_monitor_kinds(), ' | ') USING ERRCODE = '22023';
    END IF;
  END LOOP;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.cm.monitor', 0));
  -- open what is newly observed
  FOR f IN SELECT * FROM jsonb_array_elements(p_findings) LOOP
    SELECT finding_id INTO v_id FROM governance.cm_findings WHERE fingerprint = f ->> 'fingerprint' AND state = 'open';
    IF v_id IS NULL THEN
      v_id := gen_random_uuid(); v_subject := (f ->> 'subject_artifact')::uuid;
      INSERT INTO governance.cm_findings (finding_id, kind, fingerprint, subject_artifact, summary, observed, expected, state, opened_by, correlation_id)
      VALUES (v_id, f ->> 'kind', f ->> 'fingerprint', v_subject, btrim(f ->> 'summary'), coalesce(f -> 'observed', '{}'::jsonb), coalesce(f -> 'expected', '{}'::jsonb), 'open', p_actor, p_correlation);
      v_opened := v_opened + 1;
      IF (f ->> 'hold') = 'true' AND v_subject IS NOT NULL
         AND EXISTS (SELECT 1 FROM governance.cm_release_candidates c WHERE c.candidate_id = v_subject AND c.state NOT IN ('superseded', 'withdrawn')) THEN
        INSERT INTO governance.holds (hold_id, scope, subject_artifact, reason_kind, source_artifact, reason, opened_by, correlation_id)
        VALUES (gen_random_uuid(), 'PLATFORM', v_subject, coalesce(f ->> 'hold_kind', 'conformance_drift'), v_id,
                left(CASE WHEN f ->> 'hold_kind' = 'evidence_stale' THEN 'evidence expired: ' ELSE 'conformance drift: ' END || btrim(f ->> 'summary'), 2000), p_actor, p_correlation);
        v_hopen := v_hopen + 1;
      END IF;
      PERFORM governance.ledger(NULL, NULL, 'conformance_finding', v_id, NULL, 'finding.opened', p_actor, jsonb_build_object('kind', f ->> 'kind', 'fingerprint', f ->> 'fingerprint', 'subject', v_subject, 'via', p_via), p_correlation);
    END IF;
  END LOOP;
  -- resolve what is no longer observed (the monitor's kinds only; the registration's findings close with a registration)
  FOR o IN SELECT * FROM governance.cm_findings x WHERE x.state = 'open' AND x.kind = ANY (governance.cm_monitor_kinds())
             AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_findings) y WHERE y ->> 'fingerprint' = x.fingerprint) FOR UPDATE LOOP
    UPDATE governance.cm_findings SET state = 'resolved', resolved_by = p_actor, resolved_at = clock_timestamp(), resolution = 'no longer observed by the monitor' WHERE finding_id = o.finding_id;
    UPDATE governance.holds SET lifted_at = clock_timestamp(), lifted_by = p_actor, lift_reason = 'the conformance finding is no longer observed' WHERE source_artifact = o.finding_id AND lifted_at IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT; v_hlift := v_hlift + v_n;
    v_resolved := v_resolved + 1;
    PERFORM governance.ledger(NULL, NULL, 'conformance_finding', o.finding_id, NULL, 'finding.resolved', p_actor, jsonb_build_object('kind', o.kind, 'fingerprint', o.fingerprint, 'via', p_via), p_correlation);
  END LOOP;
  v_digest := governance.digest(p_observed);
  SELECT observation_digest INTO v_last FROM governance.cm_monitor_runs ORDER BY recorded_at DESC LIMIT 1;
  IF v_opened > 0 OR v_resolved > 0 OR v_last IS DISTINCT FROM v_digest THEN
    v_run := gen_random_uuid();
    INSERT INTO governance.cm_monitor_runs (run_id, via, ticked_tenant, ticked_domain, observed, observation_digest, opened, resolved, holds_opened, holds_lifted, open_after, actor_principal_id, correlation_id)
    VALUES (v_run, p_via, CASE WHEN p_via = 'tick' THEN public.eye_tenant() END, CASE WHEN p_via = 'tick' THEN public.eye_domain() END, p_observed, v_digest, v_opened, v_resolved, v_hopen, v_hlift,
            (SELECT count(*) FROM governance.cm_findings WHERE state = 'open'), p_actor, p_correlation);
  END IF;
  RETURN jsonb_build_object('recorded', v_run IS NOT NULL, 'run_id', v_run, 'opened', v_opened, 'resolved', v_resolved, 'holds_opened', v_hopen, 'holds_lifted', v_hlift,
                            'open', (SELECT count(*) FROM governance.cm_findings WHERE state = 'open'), 'observation_digest', v_digest);
END $$;
REVOKE ALL ON FUNCTION governance.cm_record_monitor(jsonb, jsonb, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.cm_record_monitor(jsonb, jsonb, text, uuid, uuid) TO eye_commit;


-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR — data authority, ownership and stewardship registries, component ownership and transfer, stewardship cases, the B90 residuals (F-P7D-25)
-- (folded at integration from the part-local file 0115_b107_x_dr.sql, unchanged but for the marked `B107 integration` edits; apply order §0, §RG, §CM, §DR, §PG, §AR, §DG)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 0115 §DR — CP-6 B107 part `ownership` (2026-10-15): DATA GOVERNANCE AND OWNERSHIP (F-P7D-25: V0 V00-T-082; V4 ES-04-001/-002, ES-11-001/
-- -002/-005; V7 DP-01-001/-002/-005/-006, DP-04-001/-002/-005/-006, DP-55-001/-002/-005/-006, App A DAT-GV-01/-02/-03/-04/-07/-10; V8 PER-19)
-- and the CARRIED B90 residuals (CP6_BATCHES §B90.9 #5: DP-49-005, DP-49-006, DP-41-005). Applies ALONE on 0001–0114 + the prelude (§0).
--
--   §DR.0 THE VOCABULARIES AND THE HELPERS — duties, case kinds, gap kinds, the transfer checklist, the SLA by consequence; the timer owner
--         `stewardship_case` (0114 §SV.0's owner-kind list copied whole, plus B107 dr — a seam the prelude lacked); the artifact / link / hold
--         helpers every port below writes the §0 core through.
--   §DR.1 THE DATA AUTHORITY REGISTRY (DOMAIN; V00-T-082, DP-04-001/-002, DAT-GV-01/-04): per catalog asset (products.catalog_assets — the
--         authority's id IS the asset's id) the singular owner, the steward, the custodian, the producer, the consumers, the policy and quality
--         authorities, the escalation path, the evidence obligation, the write rights and delegated duties; proposed by a steward, ACCEPTED by
--         the named owner (ownership acceptance), RATIFIED by another named human (never the proposer, never the owner), recertified by the
--         owner; RESOLVED LIVE against the principals, the roles, B94's owner resolution and the catalog's own owner (governance.dr_resolve).
--   §DR.2 THE DOMAIN REGISTRY EXTENSION (DOMAIN; DAT-GV-02): the domain's accountable leader, its boundary and its EXTENSION CONTRACT beside
--         tenancy.domains (untouched) — including the domain's governance mode (observed | enforced).
--   §DR.3 THE OWNERSHIP-GAP REGISTER AND RECONCILIATION (DP-04-005, DP-01-005): a material asset without a ratified authority, an owner
--         lost, conflicting authorities (the registry and the catalog naming different owners — both instructions PRESERVED), an unresolved
--         duty; opened with its escalation path, HELD (governance.holds `ownership_gap`: new consumption stops — §DR.8), escalated by age,
--         visible until resolved (the condition gone) or ACCEPTED by a named approver until a date; the tick reconciles a registered domain.
--   §DR.4 THE DATA CAPABILITY INVENTORY (PLATFORM; DP-01-001/-002/-005/-006): the DAT ids (imported read-only from audit/requirements/v07.csv
--         by the steward's TS reader) → group, layer, authority class, lifecycle, deployment scope, owner; RECONCILED against the observed
--         database (schemas, relations, functions); unresolved → a PLATFORM gap and a hold; ADMISSION to the governed inventory refused while
--         unresolved, drifting or held (the disputed state preserved). Production admission is R1 — never claimed.
--   §DR.5 COMPONENT OWNERSHIP AND THE RATIFIED TRANSFER (PLATFORM; ES-04-001/-002, ES-11-001/-002/-005, PER-19): one accountable owning team
--         per component, primary and secondary contacts, the operator role, owned contracts (one owner per contract), state stores, policy
--         decisions, telemetry namespace and failure domain (distinguishable when units are shared); every assignment is a TRANSFER with the
--         nine-item checklist (code, state, contracts, dashboards, alerts, runbooks, risks, exceptions, incidents — the open exceptions read
--         from the §0 links), accepted by the receiving owner, RATIFIED and SIGNED (governance.signatures `ownership_transfer`) by a product or
--         operations authority who is neither party; contacts reconciled (gaps).
--   §DR.6 STEWARDSHIP CASES (DOMAIN; DP-55-001/-002/-005, DAT-GV-07): identity | semantic | quality | access | classification | correction |
--         lifecycle | data_exception — subject, owner, evidence, proposed action, reviewers by consequence, segregation (never the proposer;
--         never the owner for access and exceptions), decision, conditions, expiry, closure; the SLA timer (`stewardship.sla`) and the sweep
--         escalate by consequence, hold the subject (C3+ past SLA; an expired exception), and keep the condition visible until closure.
--   §DR.7 THE RESPONSIBILITY EVIDENCE RECORD (DOMAIN; DP-01-006, DP-04-006, DP-55-006 — B+X:R1): the signed matrix (B94, referenced), the
--         recertification, the stewardship-queue evidence (SLA attainment, segregation test, exception ageing, override review, a sampled
--         decision set), privileged changes and joint exercises, bound to the build identity and the period; attested and SIGNED by a named
--         customer authority; `claim = 'demonstration'`; production admission R1 — never claimed.
--   §DR.8 THE READS — the data product registry view (DAT-GV-03), the responsibility portal's database half (DAT-GV-10).
--   §DR.9 THE CARRIED B90 RESIDUALS (each re-declaration COPIED WHOLE from its last definition in 0095, the change marked `-- B107 dr`):
--         products.register_subscription and products.serve_metric consult catalog_trust and the asset's open governance holds — the stop of
--         new consumption WIRED (DP-49-005); products.retire_lineage — the lineage-retirement port with its evidence on the catalog ledger
--         (DP-49-006; catalog_events' vocabulary copied whole + `lineage.retired`); products.degrade_product declares the CAUSE when the tick
--         degrades a product whose owner is lost or whose policy violation is recorded (DP-41-005 — only a domain review restores it then).
--
-- THREE CLAIMS, never mixed: CONSTRUCTION (these ports and phase6-ownership-b107); DEMONSTRATED OPERATION (the act on SYNTHETIC NORDWERK
-- personas — every evidence record `claim = 'demonstration'`); REAL ACCEPTANCE / PRODUCTION ADMISSION (R1/R2/H2) — never claimed here.
-- Refusals in the class form `<noun> rejected (<class>): …` with §DR's nouns (data authority | ownership record | stewardship case), and the
-- B90 families for the re-declared B90 ports. 0001–0114 and the prelude are untouched.
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.0 THE VOCABULARIES AND THE HELPERS
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
/* The seven duties of DP-04-002 (owner, steward, custodian, producer, consumer, policy authority, quality authority). */
CREATE OR REPLACE FUNCTION governance.dr_duties() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'owner', 'steward', 'custodian', 'producer', 'consumer', 'policy_authority', 'quality_authority'] $$;
/* The stewardship case kinds (DP-55-001, DAT-GV-07). */
CREATE OR REPLACE FUNCTION governance.dr_case_kinds() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'identity', 'semantic', 'quality', 'access', 'classification', 'correction', 'lifecycle', 'data_exception'] $$;
/* The ownership gap kinds (DP-04-005, DP-01-005, ES-11-001). */
CREATE OR REPLACE FUNCTION governance.dr_gap_kinds() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'no_owner', 'owner_lost', 'conflicting_authorities', 'unresolved_authority', 'contact_lost', 'case_unowned'] $$;
/* The ownership transfer checklist (ES-11-005): every item is stated with a reference, none is optional. */
CREATE OR REPLACE FUNCTION governance.dr_transfer_items() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'code', 'state', 'contracts', 'dashboards', 'alerts', 'runbooks', 'risks', 'exceptions', 'incidents'] $$;
/* The stewardship SLA by consequence (DP-55-005 "escalate by consequence"): the higher the consequence, the shorter the review window. */
CREATE OR REPLACE FUNCTION governance.dr_case_sla(p_consequence text) RETURNS interval LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE p_consequence WHEN 'C0' THEN interval '30 days' WHEN 'C1' THEN interval '14 days' WHEN 'C2' THEN interval '5 days'
                            WHEN 'C3' THEN interval '2 days' WHEN 'C4' THEN interval '1 day' END $$;
/* Distinct approvals a decision needs: two named reviewers at C3 and C4, one below. */
CREATE OR REPLACE FUNCTION governance.dr_reviewers_required(p_consequence text) RETURNS int LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN p_consequence IN ('C3', 'C4') THEN 2 ELSE 1 END $$;
/* The ownership recertification period (the catalog's, 0095 §K.1) and the age after which an open gap escalates. */
CREATE OR REPLACE FUNCTION governance.dr_recertification_period() RETURNS interval LANGUAGE sql IMMUTABLE AS $$ SELECT interval '180 days' $$;
CREATE OR REPLACE FUNCTION governance.dr_gap_escalation_after() RETURNS interval LANGUAGE sql IMMUTABLE AS $$ SELECT interval '3 days' $$;
GRANT EXECUTE ON FUNCTION governance.dr_duties(), governance.dr_case_kinds(), governance.dr_gap_kinds(), governance.dr_transfer_items(),
  governance.dr_case_sla(text), governance.dr_reviewers_required(text), governance.dr_recertification_period(), governance.dr_gap_escalation_after() TO eye_app, eye_commit;

-- B107 dr — the timer owner: a stewardship SLA timer is owned by its case (0114 §SV.0's owner-kind list, copied whole, plus `stewardship_case`).
-- THE INTEGRATOR: §AR / §PG may widen the same list for their timers — fold the additions into one list.
ALTER TABLE executive.workflow_timers DROP CONSTRAINT IF EXISTS workflow_timers_owner_kind_check;
ALTER TABLE executive.workflow_timers ADD CONSTRAINT workflow_timers_owner_kind_check CHECK (owner_kind IN ('task', 'workflow_instance', 'grant', 'commitment_item', 'gate',
  -- B94 sv (0114 §SV.0)
  'service_case',
  -- B107 dr (0115 §DR.0)
  'stewardship_case'));

/* An active HUMAN homed at PLATFORM (a vendor-side owner, contact or authority). */
CREATE OR REPLACE FUNCTION governance.dr_platform_human(p_principal uuid) RETURNS boolean
STABLE SECURITY DEFINER SET search_path = identity, pg_catalog, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM identity.principals p WHERE p.id = p_principal AND p.kind = 'human' AND p.status = 'active' AND p.scope = 'PLATFORM')
$$ LANGUAGE sql;
REVOKE ALL ON FUNCTION governance.dr_platform_human(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_platform_human(uuid) TO eye_app, eye_commit;

/* A principal's display name for the governance reads: a PLATFORM principal's to anyone authenticated; a tenant's within its tenant only. */
CREATE OR REPLACE FUNCTION governance.dr_name(p_principal uuid) RETURNS text
STABLE SECURITY DEFINER SET search_path = identity, public, pg_catalog, pg_temp AS $$
  SELECT p.display_name FROM identity.principals p
   WHERE p.id = p_principal AND public.eye_scope() <> 'NONE' AND (p.scope = 'PLATFORM' OR p.tenant_id = public.eye_tenant())
$$ LANGUAGE sql;
REVOKE ALL ON FUNCTION governance.dr_name(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_name(uuid) TO eye_app, eye_commit;

/* The live holders of a role covering the domain (DOMAIN bindings of the domain, TENANT bindings of the tenant) — active humans only. */
CREATE OR REPLACE FUNCTION governance.dr_role_holders(p_tenant uuid, p_domain uuid, p_role text) RETURNS uuid[]
STABLE SECURITY DEFINER SET search_path = identity, pg_catalog, pg_temp AS $$
  SELECT coalesce(array_agg(DISTINCT b.principal_id ORDER BY b.principal_id), '{}')
    FROM identity.role_bindings b JOIN identity.principals p ON p.id = b.principal_id
   WHERE b.role_code = p_role AND b.revoked_at IS NULL AND p.status = 'active' AND p.kind = 'human' AND b.tenant_id = p_tenant
     AND (b.scope = 'TENANT' OR (b.scope = 'DOMAIN' AND b.domain_id = p_domain))
$$ LANGUAGE sql;
REVOKE ALL ON FUNCTION governance.dr_role_holders(uuid, uuid, text) FROM PUBLIC;

/* The DOMAIN port head: the route's action (one of p_actions — answered), the bound scope, the acting principal. */
CREATE OR REPLACE FUNCTION governance.dr_domain_head(p_actions text[], p_tenant uuid, p_domain uuid, p_actor uuid, p_noun text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE v text;
BEGIN
  v := observation.assert_authority(p_actions);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN
    RAISE EXCEPTION '% rejected (actor): the act is recorded under the acting principal', p_noun USING ERRCODE = '42501';
  END IF;
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dr_domain_head(text[], uuid, uuid, uuid, text) FROM PUBLIC;

/* REGISTER an object in the §0 core: a new artifact version when the digest changed (the current one superseded), nothing when it did not.
   Answers the current version. */
CREATE OR REPLACE FUNCTION governance.dr_register(p_id uuid, p_scope text, p_tenant uuid, p_domain uuid, p_kind text, p_key text, p_title text, p_owner uuid, p_owner_role text,
                                                  p_class text, p_lifecycle text, p_attributes jsonb, p_digest text, p_actor uuid, p_correlation uuid) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE cur governance.artifacts%ROWTYPE; v int;
BEGIN
  SELECT * INTO cur FROM governance.artifacts a WHERE a.artifact_id = p_id AND a.superseded_at IS NULL FOR UPDATE;
  IF FOUND AND cur.digest = p_digest AND cur.lifecycle = p_lifecycle THEN RETURN cur.version; END IF;
  IF FOUND THEN UPDATE governance.artifacts SET superseded_at = clock_timestamp() WHERE artifact_id = p_id AND version = cur.version; END IF;
  v := coalesce(cur.version, 0) + 1;
  INSERT INTO governance.artifacts (artifact_id, version, scope, tenant_id, domain_id, kind, external_key, title, owner_principal_id, owner_role, authority_class, controlling_volume,
                                    lifecycle, attributes, source, digest, recorded_by, correlation_id)
  VALUES (p_id, v, p_scope, p_tenant, p_domain, p_kind, left(p_key, 200), left(btrim(p_title), 500), p_owner, p_owner_role, p_class, 'V7', p_lifecycle,
          coalesce(p_attributes, '{}'::jsonb), jsonb_build_object('part', 'B107 §DR', 'migration', '0115_b107_x_dr'), p_digest, p_actor, p_correlation);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dr_register(uuid, text, uuid, uuid, text, text, text, uuid, text, text, text, jsonb, text, uuid, uuid) FROM PUBLIC;

/* LINK two artifacts (once: an identical live link is answered, not repeated). */
CREATE OR REPLACE FUNCTION governance.dr_link(p_scope text, p_tenant uuid, p_domain uuid, p_from uuid, p_to uuid, p_relation text, p_attributes jsonb, p_actor uuid, p_correlation uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v uuid;
BEGIN
  SELECT l.link_id INTO v FROM governance.links_live l WHERE l.from_artifact = p_from AND l.to_artifact = p_to AND l.relation = p_relation LIMIT 1;
  IF v IS NOT NULL THEN RETURN v; END IF;
  v := gen_random_uuid();
  INSERT INTO governance.links (link_id, scope, tenant_id, domain_id, from_artifact, to_artifact, relation, attributes, recorded_by, correlation_id)
  VALUES (v, p_scope, p_tenant, p_domain, p_from, p_to, p_relation, coalesce(p_attributes, '{}'::jsonb), p_actor, p_correlation);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dr_link(text, uuid, uuid, uuid, uuid, text, jsonb, uuid, uuid) FROM PUBLIC;

/* RETIRE the live links of a relation from an artifact (a later row each — never an update). */
CREATE OR REPLACE FUNCTION governance.dr_retire_links(p_from uuid, p_relation text, p_actor uuid, p_correlation uuid) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE l record; n int := 0;
BEGIN
  FOR l IN SELECT * FROM governance.links_live x WHERE x.from_artifact = p_from AND x.relation = p_relation LOOP
    INSERT INTO governance.links (link_id, scope, tenant_id, domain_id, from_artifact, to_artifact, relation, retired, retires_link, recorded_by, correlation_id)
    VALUES (gen_random_uuid(), l.scope, l.tenant_id, l.domain_id, l.from_artifact, l.to_artifact, l.relation, true, l.link_id, p_actor, p_correlation);
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;
REVOKE ALL ON FUNCTION governance.dr_retire_links(uuid, text, uuid, uuid) FROM PUBLIC;

/* OPEN a hold on a subject (once per subject + reason + source while open): answers the hold id. */
CREATE OR REPLACE FUNCTION governance.dr_open_hold(p_tenant uuid, p_domain uuid, p_subject uuid, p_reason_kind text, p_source uuid, p_reason text, p_actor uuid, p_correlation uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v uuid;
BEGIN
  SELECT h.hold_id INTO v FROM governance.holds h WHERE h.subject_artifact = p_subject AND h.reason_kind = p_reason_kind AND h.source_artifact IS NOT DISTINCT FROM p_source AND h.lifted_at IS NULL LIMIT 1;
  IF v IS NOT NULL THEN RETURN v; END IF;
  v := gen_random_uuid();
  INSERT INTO governance.holds (hold_id, scope, tenant_id, domain_id, subject_artifact, reason_kind, source_artifact, reason, opened_by, correlation_id)
  VALUES (v, CASE WHEN p_domain IS NULL THEN 'PLATFORM' ELSE 'DOMAIN' END, p_tenant, p_domain, p_subject, p_reason_kind, p_source, left(btrim(p_reason), 1000), p_actor, p_correlation);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dr_open_hold(uuid, uuid, uuid, text, uuid, text, uuid, uuid) FROM PUBLIC;

/* LIFT the open holds of a subject opened by a source (or of a reason kind on the subject when p_source is NULL): answers the lifted ids. */
CREATE OR REPLACE FUNCTION governance.dr_lift_holds(p_subject uuid, p_reason_kind text, p_source uuid, p_reason text, p_actor uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v jsonb;
BEGIN
  WITH u AS (UPDATE governance.holds h SET lifted_at = clock_timestamp(), lifted_by = p_actor, lift_reason = left(btrim(p_reason), 1000)
              WHERE h.subject_artifact = p_subject AND h.lifted_at IS NULL AND (p_reason_kind IS NULL OR h.reason_kind = p_reason_kind)
                AND (p_source IS NULL OR h.source_artifact = p_source) RETURNING h.hold_id)
  SELECT coalesce(jsonb_agg(u.hold_id), '[]'::jsonb) INTO v FROM u;
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dr_lift_holds(uuid, text, uuid, text, uuid) FROM PUBLIC;

/* The OPEN holds of a subject that stop NEW CONSUMPTION (DP-49-005 / DP-04-005): an ownership gap, an expired data exception, a conflict, a
   stewardship decision past its SLA at C3+ (evidence_stale with a stewardship case as its source). */
CREATE OR REPLACE FUNCTION governance.dr_consumption_holds(p_subject uuid) RETURNS jsonb
STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('hold_id', h.hold_id, 'reason_kind', h.reason_kind, 'reason', h.reason, 'opened_at', h.opened_at) ORDER BY h.opened_at), '[]'::jsonb)
    FROM governance.holds h WHERE h.subject_artifact = p_subject AND h.lifted_at IS NULL AND h.reason_kind IN ('ownership_gap', 'exception_expired', 'conflict', 'evidence_stale')
$$ LANGUAGE sql;
REVOKE ALL ON FUNCTION governance.dr_consumption_holds(uuid) FROM PUBLIC;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.1 THE DATA AUTHORITY REGISTRY (DOMAIN; versioned; the authority's id is the catalog asset's id)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
CREATE TABLE governance.data_authorities (
  authority_id          uuid NOT NULL,                                   -- = products.catalog_assets.asset_id
  version               int  NOT NULL CHECK (version >= 1),
  scope                 text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id             uuid NOT NULL,
  domain_id             uuid NOT NULL,
  asset_kind            text NOT NULL,
  asset_ref             text NOT NULL,
  asset_title           text NOT NULL,
  owner_principal_id    uuid NOT NULL,                                   -- the SINGULAR accountable owner (a named, active human of the tenant)
  steward_principal_id  uuid NOT NULL,                                   -- the named steward (never the owner)
  custodian_role        text NOT NULL REFERENCES identity.roles (code),  -- technical custody
  custodian_principal_id uuid,                                           -- optionally NAMED (then holds the custodian role)
  producer              text NOT NULL CHECK (length(btrim(producer)) BETWEEN 3 AND 300),   -- the producing source / pipeline / system, by reference
  consumer_roles        text[] NOT NULL DEFAULT '{}',
  policy_authority_role text NOT NULL REFERENCES identity.roles (code),
  quality_authority_role text NOT NULL REFERENCES identity.roles (code),
  escalation_path       text NOT NULL CHECK (length(btrim(escalation_path)) BETWEEN 8 AND 500),
  evidence_obligation   text NOT NULL CHECK (length(btrim(evidence_obligation)) BETWEEN 8 AND 500),
  write_rights          text[] NOT NULL DEFAULT '{}',                    -- the actions that may write the asset's authoritative state
  delegated_duties      jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(delegated_duties) = 'array'),   -- [{duty, to, until}]
  responsibility_key    text,                                            -- the B94 responsibility-matrix row this authority answers to
  state                 text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'ratified', 'rejected', 'superseded')),
  owner_accepted_at     timestamptz,
  digest                text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  proposed_by           uuid NOT NULL,
  proposed_at           timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by            uuid,
  decided_at            timestamptz,
  decision_reason       text,
  recertify_by          timestamptz,
  recertified_at        timestamptz,
  superseded_at         timestamptz,
  correlation_id        uuid NOT NULL,
  PRIMARY KEY (authority_id, version),
  CONSTRAINT gda_scope CHECK (observation.scope_ok(scope, tenant_id, domain_id)),
  CONSTRAINT gda_owner_not_steward CHECK (owner_principal_id <> steward_principal_id),
  CONSTRAINT gda_decided CHECK (state = 'proposed' OR (decided_by IS NOT NULL AND decided_at IS NOT NULL AND decision_reason IS NOT NULL)),
  CONSTRAINT gda_sod CHECK (decided_by IS NULL OR (decided_by <> proposed_by AND decided_by <> owner_principal_id)),
  CONSTRAINT gda_ratified CHECK (state NOT IN ('ratified', 'superseded') OR (owner_accepted_at IS NOT NULL AND recertify_by IS NOT NULL)),
  CONSTRAINT gda_superseded CHECK ((state = 'superseded') = (superseded_at IS NOT NULL))
);
CREATE UNIQUE INDEX gda_one_ratified ON governance.data_authorities (authority_id) WHERE state = 'ratified';
CREATE UNIQUE INDEX gda_one_proposed ON governance.data_authorities (authority_id) WHERE state = 'proposed';
CREATE INDEX gda_domain ON governance.data_authorities (tenant_id, domain_id, state);
/* A version moves forward only: its declaration is immutable; only the acceptance, the decision, the recertification and the supersession
   are set; never deleted. */
CREATE OR REPLACE FUNCTION governance.dr_authority_forward() RETURNS trigger LANGUAGE plpgsql SET search_path = governance, pg_catalog, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'data authority rejected (state): a data authority version is never deleted' USING ERRCODE = '2F002'; END IF;
  IF (to_jsonb(NEW) - ARRAY['state', 'owner_accepted_at', 'decided_by', 'decided_at', 'decision_reason', 'recertify_by', 'recertified_at', 'superseded_at'])
     IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['state', 'owner_accepted_at', 'decided_by', 'decided_at', 'decision_reason', 'recertify_by', 'recertified_at', 'superseded_at']) THEN
    RAISE EXCEPTION 'data authority rejected (state): version %/% is immutable; a change is a new version', OLD.authority_id, OLD.version USING ERRCODE = '2F002';
  END IF;
  IF OLD.state IN ('rejected', 'superseded') OR (OLD.state = 'ratified' AND NEW.state NOT IN ('ratified', 'superseded')) THEN
    RAISE EXCEPTION 'data authority rejected (state): version %/% is %', OLD.authority_id, OLD.version, OLD.state USING ERRCODE = '2F002';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER gda_forward BEFORE UPDATE OR DELETE ON governance.data_authorities FOR EACH ROW EXECUTE FUNCTION governance.dr_authority_forward();

/* The authority as JSON (the reads and the ports' answers). */
CREATE OR REPLACE FUNCTION governance.dr_authority_json(a governance.data_authorities) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT (to_jsonb(a) - 'scope' - 'correlation_id') || jsonb_build_object('owner_name', governance.dr_name(a.owner_principal_id), 'steward_name', governance.dr_name(a.steward_principal_id),
         'proposed_by_name', governance.dr_name(a.proposed_by), 'decided_by_name', governance.dr_name(a.decided_by))
$$;
GRANT EXECUTE ON FUNCTION governance.dr_authority_json(governance.data_authorities) TO eye_app, eye_commit;

/* The canonical body of a proposal (what the digest covers). */
CREATE OR REPLACE FUNCTION governance.dr_authority_body(a governance.data_authorities) RETURNS jsonb
LANGUAGE sql IMMUTABLE AS $$
  SELECT jsonb_build_object('authority_id', a.authority_id, 'version', a.version, 'tenant_id', a.tenant_id, 'domain_id', a.domain_id, 'asset', jsonb_build_object('kind', a.asset_kind, 'ref', a.asset_ref),
    'owner', a.owner_principal_id, 'steward', a.steward_principal_id, 'custodian_role', a.custodian_role, 'custodian', a.custodian_principal_id, 'producer', a.producer,
    'consumer_roles', to_jsonb(a.consumer_roles), 'policy_authority_role', a.policy_authority_role, 'quality_authority_role', a.quality_authority_role,
    'escalation_path', a.escalation_path, 'evidence_obligation', a.evidence_obligation, 'write_rights', to_jsonb(a.write_rights), 'delegated_duties', a.delegated_duties,
    'responsibility_key', a.responsibility_key)
$$;

/* PROPOSE (governance.ownership.authority.propose): a data steward or the domain administrator declares the duties of ONE catalog asset of
   the domain. Every named duty holder is an active human of the tenant; every role exists; a named custodian holds the custodian role; a
   responsibility key names a row of the domain's APPROVED B94 matrix; owner ≠ steward. One open proposal at a time (state); the expected
   version is the latest (stale). */
CREATE OR REPLACE FUNCTION governance.dr_propose_authority(p_authority uuid, p_tenant uuid, p_domain uuid, p_expected int, p_duties jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, products, service, executive, identity, decision, observation, public, pg_catalog, pg_temp AS $$
DECLARE asset products.catalog_assets%ROWTYPE; v_latest int; v_open int; a governance.data_authorities%ROWTYPE; v_owner uuid; v_steward uuid; v_cust uuid; d jsonb; r text;
        v_roles text[]; v_rights text[]; v_resp text;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.authority.propose'], p_tenant, p_domain, p_actor, 'data authority');
  IF NOT executive.holds_role(p_actor, p_tenant, p_domain, ARRAY['data_steward', 'domain_admin']) THEN
    RAISE EXCEPTION 'data authority rejected (authority): a data authority is proposed by a data steward or the domain administrator' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO asset FROM products.catalog_assets x WHERE x.asset_id = p_authority AND x.tenant_id = p_tenant AND x.domain_id = p_domain;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_asset): % is not a catalog asset of this domain (catalogue it first)', p_authority USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.authority:' || p_authority::text, 0));
  SELECT coalesce(max(x.version), 0), count(*) FILTER (WHERE x.state = 'proposed') INTO v_latest, v_open FROM governance.data_authorities x WHERE x.authority_id = p_authority;
  IF v_open > 0 THEN RAISE EXCEPTION 'data authority rejected (state): a proposal for % % is open (v%); it is accepted and ratified, or rejected, first', asset.kind, asset.ref, v_latest USING ERRCODE = '22023'; END IF;
  IF p_expected IS DISTINCT FROM v_latest THEN RAISE EXCEPTION 'data authority rejected (stale): the latest version is %, the proposal names %', v_latest, coalesce(p_expected::text, 'none') USING ERRCODE = '22023'; END IF;
  IF p_duties IS NULL OR jsonb_typeof(p_duties) <> 'object' THEN RAISE EXCEPTION 'data authority rejected (duties): the duties are an object (owner, steward, custodianRole, producer, policyAuthorityRole, qualityAuthorityRole, escalationPath, evidenceObligation …)' USING ERRCODE = '22023'; END IF;
  BEGIN v_owner := (p_duties ->> 'owner')::uuid; v_steward := (p_duties ->> 'steward')::uuid; v_cust := NULLIF(p_duties ->> 'custodian', '')::uuid;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'data authority rejected (duties): owner, steward and custodian are principal ids' USING ERRCODE = '22023'; END;
  IF v_owner IS NULL OR NOT decision.is_active_human(v_owner, p_tenant) THEN RAISE EXCEPTION 'data authority rejected (unknown_owner): the owner is ONE named, active human of the tenant (singular accountability)' USING ERRCODE = '22023'; END IF;
  IF v_steward IS NULL OR NOT decision.is_active_human(v_steward, p_tenant) THEN RAISE EXCEPTION 'data authority rejected (unknown_steward): the steward is a named, active human of the tenant' USING ERRCODE = '22023'; END IF;
  IF v_owner = v_steward THEN RAISE EXCEPTION 'data authority rejected (separation_of_duties): the owner and the steward are different people (the steward administers what the owner is accountable for)' USING ERRCODE = '42501'; END IF;
  FOREACH r IN ARRAY ARRAY['custodianRole', 'policyAuthorityRole', 'qualityAuthorityRole'] LOOP
    IF NOT EXISTS (SELECT 1 FROM identity.roles x WHERE x.code = p_duties ->> r) THEN
      RAISE EXCEPTION 'data authority rejected (role): % names no role (%)', r, coalesce(p_duties ->> r, 'none') USING ERRCODE = '22023';
    END IF;
  END LOOP;
  IF v_cust IS NOT NULL AND NOT (v_cust = ANY (governance.dr_role_holders(p_tenant, p_domain, p_duties ->> 'custodianRole'))) THEN
    RAISE EXCEPTION 'data authority rejected (unknown_custodian): the named custodian holds % in this domain', p_duties ->> 'custodianRole' USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_duties ->> 'producer', ''))) NOT BETWEEN 3 AND 300 THEN RAISE EXCEPTION 'data authority rejected (producer): the producer is named by reference (3–300 characters)' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_duties ->> 'escalationPath', ''))) NOT BETWEEN 8 AND 500 THEN RAISE EXCEPTION 'data authority rejected (escalation): the escalation path is stated (8–500 characters)' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_duties ->> 'evidenceObligation', ''))) NOT BETWEEN 8 AND 500 THEN RAISE EXCEPTION 'data authority rejected (evidence): the evidence obligation is stated (8–500 characters)' USING ERRCODE = '22023'; END IF;
  IF p_duties ? 'consumerRoles' AND jsonb_typeof(p_duties -> 'consumerRoles') <> 'array' THEN RAISE EXCEPTION 'data authority rejected (role): consumerRoles is a list of roles' USING ERRCODE = '22023'; END IF;
  SELECT coalesce(array_agg(x ORDER BY x), '{}') INTO v_roles FROM (SELECT DISTINCT jsonb_array_elements_text(coalesce(p_duties -> 'consumerRoles', '[]'::jsonb)) x) q;
  IF EXISTS (SELECT 1 FROM unnest(v_roles) x WHERE NOT EXISTS (SELECT 1 FROM identity.roles y WHERE y.code = x)) THEN RAISE EXCEPTION 'data authority rejected (role): a consumer role names no role' USING ERRCODE = '22023'; END IF;
  IF p_duties ? 'writeRights' AND jsonb_typeof(p_duties -> 'writeRights') <> 'array' THEN RAISE EXCEPTION 'data authority rejected (write_rights): writeRights is a list of actions' USING ERRCODE = '22023'; END IF;
  SELECT coalesce(array_agg(x ORDER BY x), '{}') INTO v_rights FROM (SELECT DISTINCT jsonb_array_elements_text(coalesce(p_duties -> 'writeRights', '[]'::jsonb)) x) q;
  IF EXISTS (SELECT 1 FROM unnest(v_rights) x WHERE x !~ '^[a-z][a-z0-9_]*(\.[a-z0-9_]+)+$') THEN RAISE EXCEPTION 'data authority rejected (write_rights): a write right is an action name (e.g. products.catalog.owner.set)' USING ERRCODE = '22023'; END IF;
  IF p_duties ? 'delegatedDuties' AND jsonb_typeof(p_duties -> 'delegatedDuties') <> 'array' THEN RAISE EXCEPTION 'data authority rejected (delegation): delegatedDuties is a list of {duty, to, until}' USING ERRCODE = '22023'; END IF;
  FOR d IN SELECT x FROM jsonb_array_elements(coalesce(p_duties -> 'delegatedDuties', '[]'::jsonb)) x LOOP
    IF jsonb_typeof(d) <> 'object' OR NOT ((d ->> 'duty') = ANY (governance.dr_duties())) OR (d ->> 'duty') = 'owner' THEN
      RAISE EXCEPTION 'data authority rejected (delegation): a delegated duty is one of steward, custodian, producer, consumer, policy_authority, quality_authority (accountability is never delegated)' USING ERRCODE = '22023';
    END IF;
    BEGIN
      IF NOT decision.is_active_human((d ->> 'to')::uuid, p_tenant) THEN RAISE EXCEPTION 'x'; END IF;
      IF (d ->> 'until')::timestamptz <= clock_timestamp() OR (d ->> 'until')::timestamptz > clock_timestamp() + interval '366 days' THEN RAISE EXCEPTION 'x'; END IF;
    EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'data authority rejected (delegation): a delegation names an active human of the tenant and an end within 366 days' USING ERRCODE = '22023'; END;
  END LOOP;
  v_resp := NULLIF(btrim(coalesce(p_duties ->> 'responsibilityKey', '')), '');
  IF v_resp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM service.responsibility_matrices m JOIN service.responsibility_rows rr ON rr.matrix_id = m.matrix_id AND rr.version = m.version
                                          WHERE m.tenant_id = p_tenant AND m.domain_id = p_domain AND m.state = 'approved' AND rr.responsibility_key = v_resp) THEN
    RAISE EXCEPTION 'data authority rejected (unknown_responsibility): % is no row of the domain''s approved responsibility matrix', v_resp USING ERRCODE = '22023';
  END IF;
  a.authority_id := p_authority; a.version := v_latest + 1; a.scope := 'DOMAIN'; a.tenant_id := p_tenant; a.domain_id := p_domain;
  a.asset_kind := asset.kind; a.asset_ref := asset.ref; a.asset_title := asset.title; a.owner_principal_id := v_owner; a.steward_principal_id := v_steward;
  a.custodian_role := p_duties ->> 'custodianRole'; a.custodian_principal_id := v_cust; a.producer := btrim(p_duties ->> 'producer'); a.consumer_roles := v_roles;
  a.policy_authority_role := p_duties ->> 'policyAuthorityRole'; a.quality_authority_role := p_duties ->> 'qualityAuthorityRole';
  a.escalation_path := btrim(p_duties ->> 'escalationPath'); a.evidence_obligation := btrim(p_duties ->> 'evidenceObligation'); a.write_rights := v_rights;
  a.delegated_duties := coalesce(p_duties -> 'delegatedDuties', '[]'::jsonb); a.responsibility_key := v_resp; a.state := 'proposed';
  a.digest := governance.digest(governance.dr_authority_body(a)); a.proposed_by := p_actor; a.proposed_at := clock_timestamp(); a.correlation_id := p_correlation;
  INSERT INTO governance.data_authorities VALUES (a.*);
  PERFORM governance.ledger(p_tenant, p_domain, 'data_authority', p_authority, a.version, 'authority.proposed', p_actor,
                            jsonb_build_object('asset', jsonb_build_object('kind', asset.kind, 'ref', asset.ref), 'owner', v_owner, 'steward', v_steward, 'digest', a.digest), p_correlation);
  SELECT * INTO a FROM governance.data_authorities x WHERE x.authority_id = p_authority AND x.version = v_latest + 1;
  RETURN governance.dr_authority_json(a);
END $$;
REVOKE ALL ON FUNCTION governance.dr_propose_authority(uuid, uuid, uuid, int, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_propose_authority(uuid, uuid, uuid, int, jsonb, uuid, uuid) TO eye_commit;

/* ACCEPT OWNERSHIP (governance.ownership.authority.accept; DP-01-006 "ownership acceptance"): the NAMED OWNER's own act on the exact digest. */
CREATE OR REPLACE FUNCTION governance.dr_accept_authority(p_authority uuid, p_tenant uuid, p_domain uuid, p_version int, p_digest text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE a governance.data_authorities%ROWTYPE;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.authority.accept'], p_tenant, p_domain, p_actor, 'data authority');
  SELECT * INTO a FROM governance.data_authorities x WHERE x.authority_id = p_authority AND x.version = p_version AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_authority): no version % of % in this domain', p_version, p_authority USING ERRCODE = '22023'; END IF;
  IF a.state <> 'proposed' THEN RAISE EXCEPTION 'data authority rejected (state): version % is %; only a proposal is accepted', p_version, a.state USING ERRCODE = '22023'; END IF;
  IF onboarding.principal_kind(p_actor) IS DISTINCT FROM 'human' THEN RAISE EXCEPTION 'data authority rejected (actor): ownership is accepted by a named human' USING ERRCODE = '42501'; END IF;
  IF a.owner_principal_id <> p_actor THEN RAISE EXCEPTION 'data authority rejected (ownership): ownership of % % is accepted by its named owner only', a.asset_kind, a.asset_ref USING ERRCODE = '42501'; END IF;
  IF p_digest IS DISTINCT FROM a.digest THEN RAISE EXCEPTION 'data authority rejected (stale): the digest accepted is not version %''s (%)', p_version, a.digest USING ERRCODE = '22023'; END IF;
  IF a.owner_accepted_at IS NOT NULL THEN RAISE EXCEPTION 'data authority rejected (duplicate): ownership of version % was accepted at %', p_version, a.owner_accepted_at USING ERRCODE = '22023'; END IF;
  UPDATE governance.data_authorities SET owner_accepted_at = clock_timestamp() WHERE authority_id = p_authority AND version = p_version RETURNING * INTO a;
  PERFORM governance.ledger(p_tenant, p_domain, 'data_authority', p_authority, p_version, 'authority.owner_accepted', p_actor, jsonb_build_object('digest', a.digest), p_correlation);
  RETURN governance.dr_authority_json(a);
END $$;
REVOKE ALL ON FUNCTION governance.dr_accept_authority(uuid, uuid, uuid, int, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_accept_authority(uuid, uuid, uuid, int, text, uuid, uuid) TO eye_commit;

/* DECIDE (governance.ownership.authority.ratify; human-gated): RATIFY or REJECT a proposal on the exact digest — the approver test (a named
   human holding domain_admin or data_steward; never the proposer; never the owner whose authority it creates); ratification needs the
   owner's acceptance. The ratified version supersedes the prior one, is registered in the §0 core (kind data_authority) and starts the
   recertification clock. */
CREATE OR REPLACE FUNCTION governance.dr_decide_authority(p_authority uuid, p_tenant uuid, p_domain uuid, p_version int, p_digest text, p_decision text, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, decision, public, pg_catalog, pg_temp AS $$
DECLARE a governance.data_authorities%ROWTYPE; v_now timestamptz := clock_timestamp(); v_art int;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.authority.ratify'], p_tenant, p_domain, p_actor, 'data authority');
  SELECT * INTO a FROM governance.data_authorities x WHERE x.authority_id = p_authority AND x.version = p_version AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_authority): no version % of % in this domain', p_version, p_authority USING ERRCODE = '22023'; END IF;
  PERFORM governance.assert_approver('data authority', p_actor, p_tenant, p_domain, ARRAY['domain_admin', 'data_steward'], a.proposed_by, ARRAY[a.owner_principal_id], 'ratifying a data authority');
  IF a.state <> 'proposed' THEN RAISE EXCEPTION 'data authority rejected (state): version % is %; only a proposal is decided', p_version, a.state USING ERRCODE = '22023'; END IF;
  IF p_digest IS DISTINCT FROM a.digest THEN RAISE EXCEPTION 'data authority rejected (stale): the digest decided is not version %''s (%)', p_version, a.digest USING ERRCODE = '22023'; END IF;
  IF p_decision IS NULL OR p_decision NOT IN ('ratify', 'reject') THEN RAISE EXCEPTION 'data authority rejected (decision): ratify or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'data authority rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'reject' THEN
    UPDATE governance.data_authorities SET state = 'rejected', decided_by = p_actor, decided_at = v_now, decision_reason = btrim(p_reason) WHERE authority_id = p_authority AND version = p_version RETURNING * INTO a;
    PERFORM governance.ledger(p_tenant, p_domain, 'data_authority', p_authority, p_version, 'authority.rejected', p_actor, jsonb_build_object('reason', btrim(p_reason)), p_correlation);
    RETURN governance.dr_authority_json(a);
  END IF;
  IF a.owner_accepted_at IS NULL THEN RAISE EXCEPTION 'data authority rejected (state): the named owner has not accepted version % — ownership is accepted before it is ratified', p_version USING ERRCODE = '22023'; END IF;
  IF NOT decision.is_active_human(a.owner_principal_id, p_tenant) OR NOT decision.is_active_human(a.steward_principal_id, p_tenant) THEN
    RAISE EXCEPTION 'data authority rejected (state): the owner or the steward of version % is no longer an active human of the tenant', p_version USING ERRCODE = '22023';
  END IF;
  UPDATE governance.data_authorities SET state = 'superseded', superseded_at = v_now WHERE authority_id = p_authority AND state = 'ratified';
  UPDATE governance.data_authorities SET state = 'ratified', decided_by = p_actor, decided_at = v_now, decision_reason = btrim(p_reason),
         recertify_by = v_now + governance.dr_recertification_period(), recertified_at = v_now WHERE authority_id = p_authority AND version = p_version RETURNING * INTO a;
  v_art := governance.dr_register(p_authority, 'DOMAIN', p_tenant, p_domain, 'data_authority', a.asset_kind || ':' || a.asset_ref, 'Data authority — ' || a.asset_title,
                                  a.owner_principal_id, NULL, 'data_authority', 'active',
                                  jsonb_build_object('authority_version', a.version, 'steward', a.steward_principal_id, 'custodian_role', a.custodian_role, 'policy_authority_role', a.policy_authority_role,
                                                     'quality_authority_role', a.quality_authority_role, 'escalation_path', a.escalation_path), a.digest, p_actor, p_correlation);
  PERFORM governance.ledger(p_tenant, p_domain, 'data_authority', p_authority, p_version, 'authority.ratified', p_actor,
                            jsonb_build_object('reason', btrim(p_reason), 'digest', a.digest, 'artifact_version', v_art, 'recertify_by', a.recertify_by), p_correlation);
  RETURN governance.dr_authority_json(a);
END $$;
REVOKE ALL ON FUNCTION governance.dr_decide_authority(uuid, uuid, uuid, int, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_decide_authority(uuid, uuid, uuid, int, text, text, text, uuid, uuid) TO eye_commit;

/* RECERTIFY (governance.ownership.authority.recertify; DP-04-006 "ownership recertification"): the OWNER's own act on the ratified version. */
CREATE OR REPLACE FUNCTION governance.dr_recertify_authority(p_authority uuid, p_tenant uuid, p_domain uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE a governance.data_authorities%ROWTYPE; v_now timestamptz := clock_timestamp(); v_prior timestamptz;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.authority.recertify'], p_tenant, p_domain, p_actor, 'data authority');
  SELECT * INTO a FROM governance.data_authorities x WHERE x.authority_id = p_authority AND x.state = 'ratified' AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_authority): % has no ratified authority in this domain', p_authority USING ERRCODE = '22023'; END IF;
  IF onboarding.principal_kind(p_actor) IS DISTINCT FROM 'human' THEN RAISE EXCEPTION 'data authority rejected (actor): ownership is recertified by a named human' USING ERRCODE = '42501'; END IF;
  IF a.owner_principal_id <> p_actor THEN RAISE EXCEPTION 'data authority rejected (ownership): ownership of % % is recertified by its owner', a.asset_kind, a.asset_ref USING ERRCODE = '42501'; END IF;
  v_prior := a.recertify_by;
  UPDATE governance.data_authorities SET recertify_by = v_now + governance.dr_recertification_period(), recertified_at = v_now WHERE authority_id = p_authority AND version = a.version RETURNING * INTO a;
  PERFORM governance.ledger(p_tenant, p_domain, 'data_authority', p_authority, a.version, 'authority.recertified', p_actor, jsonb_build_object('prior_recertify_by', v_prior, 'recertify_by', a.recertify_by), p_correlation);
  RETURN governance.dr_authority_json(a);
END $$;
REVOKE ALL ON FUNCTION governance.dr_recertify_authority(uuid, uuid, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_recertify_authority(uuid, uuid, uuid, uuid, uuid) TO eye_commit;

/* THE OWNERSHIP SERVICE (DAT-GV-04, DP-04-002 "continuously reconcile"): one asset's duties RESOLVED LIVE — owner and steward (named:
   resolved while an active human of the tenant, else LOST), custodian (named, or the role's live holders), producer (declared), consumers
   (the declared roles; a product's live consumer register), policy and quality authorities (the roles' live holders), B94's owner
   resolution for the responsibility key, the recertification, the catalog's own owner compared (agree | conflict | catalog_unowned), the
   open gaps and holds — and the overall state undeclared | proposed | resolved | unresolved. Never infers an owner. Definer read guarded by
   the caller's bound scope (N-01). */
CREATE OR REPLACE FUNCTION governance.dr_resolve(p_tenant uuid, p_domain uuid, p_authority uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, products, service, identity, decision, observation, public, pg_catalog, pg_temp AS $$
DECLARE asset products.catalog_assets%ROWTYPE; a governance.data_authorities%ROWTYPE; p governance.data_authorities%ROWTYPE; v_duties jsonb := '{}'::jsonb; v_h uuid[];
        v_unresolved text[] := '{}'; v_role text; v_key text; v_cat text; v_resp jsonb; v_consumers jsonb;
BEGIN
  PERFORM observation.assert_read_scope(p_tenant, p_domain, 'the data authority of an asset');
  SELECT * INTO asset FROM products.catalog_assets x WHERE x.asset_id = p_authority AND x.tenant_id = p_tenant AND x.domain_id = p_domain;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO a FROM governance.data_authorities x WHERE x.authority_id = p_authority AND x.state = 'ratified';
  SELECT * INTO p FROM governance.data_authorities x WHERE x.authority_id = p_authority AND x.state = 'proposed';
  IF a.authority_id IS NOT NULL THEN
    v_duties := v_duties || jsonb_build_object('owner', jsonb_build_object('principal', a.owner_principal_id, 'name', governance.dr_name(a.owner_principal_id),
                  'state', CASE WHEN decision.is_active_human(a.owner_principal_id, p_tenant) THEN 'resolved' ELSE 'lost' END));
    v_duties := v_duties || jsonb_build_object('steward', jsonb_build_object('principal', a.steward_principal_id, 'name', governance.dr_name(a.steward_principal_id),
                  'state', CASE WHEN decision.is_active_human(a.steward_principal_id, p_tenant) THEN 'resolved' ELSE 'lost' END));
    v_h := governance.dr_role_holders(p_tenant, p_domain, a.custodian_role);
    v_duties := v_duties || jsonb_build_object('custodian', jsonb_build_object('role', a.custodian_role, 'principal', a.custodian_principal_id, 'holders', to_jsonb(v_h),
                  'state', CASE WHEN a.custodian_principal_id IS NOT NULL THEN CASE WHEN a.custodian_principal_id = ANY (v_h) THEN 'resolved' ELSE 'lost' END
                                WHEN cardinality(v_h) = 0 THEN 'unfilled' WHEN cardinality(v_h) = 1 THEN 'resolved' ELSE 'ambiguous' END));
    v_duties := v_duties || jsonb_build_object('producer', jsonb_build_object('ref', a.producer, 'state', 'declared'));
    v_consumers := CASE WHEN asset.kind = 'product' AND asset.ref ~ '^[0-9a-f-]{36}$' THEN
                     (SELECT coalesce(jsonb_agg(jsonb_build_object('consumer_id', c.consumer_id, 'principal', c.consumer_principal_id, 'state', c.state) ORDER BY c.registered_at), '[]'::jsonb)
                        FROM products.product_consumers c WHERE c.product_id = asset.ref::uuid AND c.state IN ('registered', 'accepted')) ELSE '[]'::jsonb END;
    v_duties := v_duties || jsonb_build_object('consumer', jsonb_build_object('roles', to_jsonb(a.consumer_roles), 'registered', v_consumers, 'state', 'declared'));
    FOREACH v_role IN ARRAY ARRAY['policy_authority', 'quality_authority'] LOOP
      v_key := CASE v_role WHEN 'policy_authority' THEN a.policy_authority_role ELSE a.quality_authority_role END;
      v_h := governance.dr_role_holders(p_tenant, p_domain, v_key);
      v_duties := v_duties || jsonb_build_object(v_role, jsonb_build_object('role', v_key, 'holders', to_jsonb(v_h), 'state', CASE WHEN cardinality(v_h) = 0 THEN 'unfilled' ELSE 'resolved' END));
    END LOOP;
    SELECT coalesce(array_agg(k ORDER BY k), '{}') INTO v_unresolved FROM jsonb_each(v_duties) e(k, v) WHERE v ->> 'state' IN ('lost', 'unfilled', 'ambiguous');
    IF a.responsibility_key IS NOT NULL THEN v_resp := service.owner_resolution(p_tenant, p_domain, a.responsibility_key, 'local-dev'); END IF;
    v_cat := CASE WHEN asset.owner_principal_id IS NULL THEN 'catalog_unowned' WHEN asset.owner_principal_id = a.owner_principal_id THEN 'agree' ELSE 'conflict' END;
  END IF;
  RETURN jsonb_build_object(
    'authority_id', p_authority, 'at', clock_timestamp(),
    'asset', jsonb_build_object('kind', asset.kind, 'ref', asset.ref, 'title', asset.title, 'owner', asset.owner_principal_id, 'owner_name', governance.dr_name(asset.owner_principal_id),
                                'trusted', asset.trusted, 'discoverable', asset.discoverable, 'flags', asset.flags, 'classification', asset.classification),
    'state', CASE WHEN a.authority_id IS NULL AND p.authority_id IS NOT NULL THEN 'proposed' WHEN a.authority_id IS NULL THEN 'undeclared'
                  WHEN cardinality(v_unresolved) = 0 AND v_cat <> 'conflict' THEN 'resolved' ELSE 'unresolved' END,
    'ratified', CASE WHEN a.authority_id IS NULL THEN NULL ELSE governance.dr_authority_json(a) END,
    'proposal', CASE WHEN p.authority_id IS NULL THEN NULL ELSE governance.dr_authority_json(p) END,
    'duties', v_duties, 'unresolved', to_jsonb(v_unresolved),
    'escalation_path', a.escalation_path, 'evidence_obligation', a.evidence_obligation, 'write_rights', to_jsonb(a.write_rights), 'delegated_duties', a.delegated_duties,
    'responsibility', v_resp,
    'recertification', CASE WHEN a.authority_id IS NULL THEN NULL ELSE jsonb_build_object('recertify_by', a.recertify_by, 'recertified_at', a.recertified_at,
                                                                                            'state', CASE WHEN a.recertify_by < clock_timestamp() THEN 'lapsed' ELSE 'current' END) END,
    'catalog_agreement', CASE WHEN a.authority_id IS NULL THEN NULL ELSE jsonb_build_object('state', v_cat, 'catalog_owner', asset.owner_principal_id, 'registry_owner', a.owner_principal_id) END,
    'gaps', (SELECT coalesce(jsonb_agg(jsonb_build_object('gap_id', g.gap_id, 'gap_kind', g.gap_kind, 'state', g.state, 'opened_at', g.opened_at) ORDER BY g.opened_at), '[]'::jsonb)
               FROM governance.ownership_gaps g WHERE g.subject_id = p_authority AND g.state <> 'resolved'),
    'holds', governance.dr_consumption_holds(p_authority));
END $$;
-- (granted after §DR.3 declares the gap register it reads)

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.2 THE DOMAIN REGISTRY EXTENSION (DOMAIN; DAT-GV-02) — beside tenancy.domains, which is untouched
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
CREATE TABLE governance.domain_registry (
  domain_id          uuid NOT NULL,
  version            int  NOT NULL CHECK (version >= 1),
  scope              text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id          uuid NOT NULL,
  accountable_leader uuid NOT NULL,                                     -- a named, active human of the tenant
  boundary           text NOT NULL CHECK (length(btrim(boundary)) BETWEEN 12 AND 2000),
  extension_contract jsonb NOT NULL CHECK (jsonb_typeof(extension_contract) = 'object'),   -- {version, extension_points[], compatibility, governance: observed | enforced}
  governance_mode    text NOT NULL CHECK (governance_mode IN ('observed', 'enforced')),
  state              text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'ratified', 'rejected', 'superseded')),
  digest             text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  proposed_by        uuid NOT NULL,
  proposed_at        timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by         uuid,
  decided_at         timestamptz,
  decision_reason    text,
  superseded_at      timestamptz,
  correlation_id     uuid NOT NULL,
  PRIMARY KEY (domain_id, version),
  CONSTRAINT gdr_scope CHECK (observation.scope_ok(scope, tenant_id, domain_id)),
  CONSTRAINT gdr_decided CHECK (state = 'proposed' OR (decided_by IS NOT NULL AND decided_at IS NOT NULL AND decision_reason IS NOT NULL)),
  CONSTRAINT gdr_sod CHECK (decided_by IS NULL OR (decided_by <> proposed_by AND decided_by <> accountable_leader)),
  CONSTRAINT gdr_superseded CHECK ((state = 'superseded') = (superseded_at IS NOT NULL))
);
CREATE UNIQUE INDEX gdr_one_ratified ON governance.domain_registry (domain_id) WHERE state = 'ratified';
CREATE UNIQUE INDEX gdr_one_proposed ON governance.domain_registry (domain_id) WHERE state = 'proposed';
CREATE OR REPLACE FUNCTION governance.dr_domain_forward() RETURNS trigger LANGUAGE plpgsql SET search_path = governance, pg_catalog, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'data authority rejected (state): a domain registry version is never deleted' USING ERRCODE = '2F002'; END IF;
  IF (to_jsonb(NEW) - ARRAY['state', 'decided_by', 'decided_at', 'decision_reason', 'superseded_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['state', 'decided_by', 'decided_at', 'decision_reason', 'superseded_at'])
     OR OLD.state IN ('rejected', 'superseded') THEN
    RAISE EXCEPTION 'data authority rejected (state): domain registry version %/% is immutable', OLD.domain_id, OLD.version USING ERRCODE = '2F002';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER gdr_forward BEFORE UPDATE OR DELETE ON governance.domain_registry FOR EACH ROW EXECUTE FUNCTION governance.dr_domain_forward();

/* PROPOSE (governance.ownership.domain.propose): the domain administrator or the tenant administrator declares the domain's accountable
   leader, boundary and extension contract ({version 'vN', extensionPoints [≥1], compatibility backward|forward|full|none, governance
   observed|enforced}). */
CREATE OR REPLACE FUNCTION governance.dr_propose_domain(p_tenant uuid, p_domain uuid, p_expected int, p_leader uuid, p_boundary text, p_contract jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, tenancy, executive, decision, public, pg_catalog, pg_temp AS $$
DECLARE v_latest int; v_open int; v_status text; v_body jsonb; v_mode text; v_contract jsonb; r governance.domain_registry%ROWTYPE;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.domain.propose'], p_tenant, p_domain, p_actor, 'data authority');
  IF NOT executive.holds_role(p_actor, p_tenant, p_domain, ARRAY['domain_admin', 'tenant_admin']) THEN
    RAISE EXCEPTION 'data authority rejected (authority): a domain''s registry entry is proposed by the domain or the tenant administrator' USING ERRCODE = '42501';
  END IF;
  SELECT d.status INTO v_status FROM tenancy.domains d WHERE d.id = p_domain AND d.tenant_id = p_tenant;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_domain): % is not a domain of this tenant', p_domain USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.domain:' || p_domain::text, 0));
  SELECT coalesce(max(x.version), 0), count(*) FILTER (WHERE x.state = 'proposed') INTO v_latest, v_open FROM governance.domain_registry x WHERE x.domain_id = p_domain;
  IF v_open > 0 THEN RAISE EXCEPTION 'data authority rejected (state): a domain registry proposal is open (v%)', v_latest USING ERRCODE = '22023'; END IF;
  IF p_expected IS DISTINCT FROM v_latest THEN RAISE EXCEPTION 'data authority rejected (stale): the latest version is %, the proposal names %', v_latest, coalesce(p_expected::text, 'none') USING ERRCODE = '22023'; END IF;
  IF p_leader IS NULL OR NOT decision.is_active_human(p_leader, p_tenant) THEN RAISE EXCEPTION 'data authority rejected (unknown_leader): the accountable leader is a named, active human of the tenant' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_boundary, ''))) NOT BETWEEN 12 AND 2000 THEN RAISE EXCEPTION 'data authority rejected (boundary): the boundary says what the domain owns (12–2000 characters)' USING ERRCODE = '22023'; END IF;
  IF p_contract IS NULL OR jsonb_typeof(p_contract) <> 'object' OR coalesce(p_contract ->> 'version', '') !~ '^v[0-9]{1,4}$'
     OR jsonb_typeof(p_contract -> 'extensionPoints') <> 'array' OR jsonb_array_length(p_contract -> 'extensionPoints') = 0
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_contract -> 'extensionPoints') x WHERE jsonb_typeof(x) <> 'string' OR length(btrim(x #>> '{}')) NOT BETWEEN 3 AND 120)
     OR coalesce(p_contract ->> 'compatibility', '') NOT IN ('backward', 'forward', 'full', 'none') THEN
    RAISE EXCEPTION 'data authority rejected (contract): the extension contract names its version (vN), its extension points (1+) and its compatibility (backward | forward | full | none)' USING ERRCODE = '22023';
  END IF;
  v_mode := coalesce(p_contract ->> 'governance', 'observed');
  IF v_mode NOT IN ('observed', 'enforced') THEN RAISE EXCEPTION 'data authority rejected (contract): the governance mode is observed or enforced' USING ERRCODE = '22023'; END IF;
  v_contract := jsonb_build_object('version', p_contract ->> 'version', 'extension_points', p_contract -> 'extensionPoints', 'compatibility', p_contract ->> 'compatibility', 'governance', v_mode);
  v_body := jsonb_build_object('domain_id', p_domain, 'version', v_latest + 1, 'leader', p_leader, 'boundary', btrim(p_boundary), 'contract', v_contract);
  INSERT INTO governance.domain_registry (domain_id, version, tenant_id, accountable_leader, boundary, extension_contract, governance_mode, digest, proposed_by, correlation_id)
  VALUES (p_domain, v_latest + 1, p_tenant, p_leader, btrim(p_boundary), v_contract, v_mode, governance.digest(v_body), p_actor, p_correlation) RETURNING * INTO r;
  PERFORM governance.ledger(p_tenant, p_domain, 'domain', p_domain, r.version, 'domain.proposed', p_actor, jsonb_build_object('leader', p_leader, 'digest', r.digest, 'domain_status', v_status), p_correlation);
  RETURN (to_jsonb(r) - 'scope' - 'correlation_id') || jsonb_build_object('leader_name', governance.dr_name(r.accountable_leader), 'domain_status', v_status);
END $$;
REVOKE ALL ON FUNCTION governance.dr_propose_domain(uuid, uuid, int, uuid, text, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_propose_domain(uuid, uuid, int, uuid, text, jsonb, uuid, uuid) TO eye_commit;

/* DECIDE (governance.ownership.domain.ratify; human-gated): the customer sponsor or the tenant administrator — never the proposer, never the
   leader the entry appoints — ratifies or rejects on the digest; the ratified entry is registered (kind domain, DOMAIN scope). */
CREATE OR REPLACE FUNCTION governance.dr_decide_domain(p_tenant uuid, p_domain uuid, p_version int, p_digest text, p_decision text, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, tenancy, public, pg_catalog, pg_temp AS $$
DECLARE r governance.domain_registry%ROWTYPE; v_now timestamptz := clock_timestamp(); v_name text;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.domain.ratify'], p_tenant, p_domain, p_actor, 'data authority');
  SELECT * INTO r FROM governance.domain_registry x WHERE x.domain_id = p_domain AND x.version = p_version AND x.tenant_id = p_tenant FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_domain_entry): no version % of the domain''s registry entry', p_version USING ERRCODE = '22023'; END IF;
  PERFORM governance.assert_approver('data authority', p_actor, p_tenant, p_domain, ARRAY['customer_sponsor', 'tenant_admin'], r.proposed_by, ARRAY[r.accountable_leader], 'ratifying a domain''s registry entry');
  IF r.state <> 'proposed' THEN RAISE EXCEPTION 'data authority rejected (state): version % is %', p_version, r.state USING ERRCODE = '22023'; END IF;
  IF p_digest IS DISTINCT FROM r.digest THEN RAISE EXCEPTION 'data authority rejected (stale): the digest decided is not version %''s', p_version USING ERRCODE = '22023'; END IF;
  IF p_decision IS NULL OR p_decision NOT IN ('ratify', 'reject') THEN RAISE EXCEPTION 'data authority rejected (decision): ratify or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'data authority rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'ratify' THEN
    UPDATE governance.domain_registry SET state = 'superseded', superseded_at = v_now WHERE domain_id = p_domain AND state = 'ratified';
  END IF;
  UPDATE governance.domain_registry SET state = CASE WHEN p_decision = 'ratify' THEN 'ratified' ELSE 'rejected' END, decided_by = p_actor, decided_at = v_now, decision_reason = btrim(p_reason)
   WHERE domain_id = p_domain AND version = p_version RETURNING * INTO r;
  IF p_decision = 'ratify' THEN
    SELECT d.name INTO v_name FROM tenancy.domains d WHERE d.id = p_domain;
    PERFORM governance.dr_register(p_domain, 'DOMAIN', p_tenant, p_domain, 'domain', 'DOMAIN:' || p_domain::text, 'Domain — ' || coalesce(v_name, p_domain::text), r.accountable_leader, NULL,
                                   'domain_registry', 'active', jsonb_build_object('registry_version', r.version, 'contract', r.extension_contract, 'governance', r.governance_mode), r.digest, p_actor, p_correlation);
  END IF;
  PERFORM governance.ledger(p_tenant, p_domain, 'domain', p_domain, p_version, CASE WHEN p_decision = 'ratify' THEN 'domain.ratified' ELSE 'domain.rejected' END, p_actor,
                            jsonb_build_object('reason', btrim(p_reason), 'digest', r.digest, 'governance', r.governance_mode), p_correlation);
  RETURN (to_jsonb(r) - 'scope' - 'correlation_id') || jsonb_build_object('leader_name', governance.dr_name(r.accountable_leader));
END $$;
REVOKE ALL ON FUNCTION governance.dr_decide_domain(uuid, uuid, int, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_decide_domain(uuid, uuid, int, text, text, text, uuid, uuid) TO eye_commit;

/* The domain's ratified governance mode (observed when none is ratified). */
CREATE OR REPLACE FUNCTION governance.dr_domain_mode(p_domain uuid) RETURNS text
STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce((SELECT r.governance_mode FROM governance.domain_registry r WHERE r.domain_id = p_domain AND r.state = 'ratified'), 'unregistered')
$$ LANGUAGE sql;
REVOKE ALL ON FUNCTION governance.dr_domain_mode(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_domain_mode(uuid) TO eye_app, eye_commit;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.3 THE OWNERSHIP-GAP REGISTER AND RECONCILIATION (DP-04-005, DP-01-005)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
/* THE GAP: a subject (a catalog asset, a product, a component, a data capability, a stewardship case) whose ownership does not resolve.
   PLATFORM rows are the vendor's (components, data capabilities); DOMAIN rows the customer's. The DETAIL preserves the state found at
   opening (the conflicting instructions, verbatim). open → escalated → accepted (a named approver accepts the residual until a date; the hold
   lifts, the gap stays listed) | resolved (the condition no longer holds — never by inference: the reconciliation re-reads it). */
CREATE TABLE governance.ownership_gaps (
  gap_id          uuid PRIMARY KEY,
  scope           text NOT NULL CHECK (scope IN ('PLATFORM', 'DOMAIN')),
  tenant_id       uuid,
  domain_id       uuid,
  subject_kind    text NOT NULL CHECK (subject_kind IN ('catalog_asset', 'product', 'component', 'data_capability', 'stewardship_case')),
  subject_id      uuid NOT NULL,
  subject_label   text NOT NULL CHECK (length(btrim(subject_label)) BETWEEN 1 AND 300),
  gap_kind        text NOT NULL CHECK (gap_kind = ANY (governance.dr_gap_kinds())),
  detail          jsonb NOT NULL CHECK (jsonb_typeof(detail) = 'object'),
  escalation_path text NOT NULL CHECK (length(btrim(escalation_path)) >= 4),
  state           text NOT NULL DEFAULT 'open' CHECK (state IN ('open', 'escalated', 'accepted', 'resolved')),
  held            boolean NOT NULL,                                        -- the subject held while the gap is open (governance.holds ownership_gap)
  opened_by       uuid NOT NULL,
  opened_at       timestamptz NOT NULL DEFAULT clock_timestamp(),
  escalations     int NOT NULL DEFAULT 0 CHECK (escalations >= 0),
  escalated_at    timestamptz,
  accepted_by     uuid,
  accepted_at     timestamptz,
  accepted_until  timestamptz,
  accept_reason   text,
  resolved_by     uuid,
  resolved_at     timestamptz,
  resolution      text,
  correlation_id  uuid NOT NULL,
  CONSTRAINT gog_scope CHECK ((scope = 'PLATFORM' AND tenant_id IS NULL AND domain_id IS NULL) OR (scope = 'DOMAIN' AND tenant_id IS NOT NULL AND domain_id IS NOT NULL)),
  CONSTRAINT gog_accepted CHECK ((state = 'accepted') = (accepted_by IS NOT NULL AND accepted_at IS NOT NULL AND accepted_until IS NOT NULL AND accept_reason IS NOT NULL) OR state = 'resolved'),
  CONSTRAINT gog_resolved CHECK ((state = 'resolved') = (resolved_at IS NOT NULL AND resolution IS NOT NULL))
);
CREATE UNIQUE INDEX gog_one_live ON governance.ownership_gaps (subject_id, gap_kind) WHERE state <> 'resolved';
CREATE INDEX gog_domain ON governance.ownership_gaps (tenant_id, domain_id, state);
CREATE OR REPLACE FUNCTION governance.dr_gap_forward() RETURNS trigger LANGUAGE plpgsql SET search_path = governance, pg_catalog, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'data authority rejected (state): an ownership gap is never deleted' USING ERRCODE = '2F002'; END IF;
  IF OLD.state = 'resolved' OR (NEW.gap_id, NEW.scope, NEW.tenant_id, NEW.domain_id, NEW.subject_kind, NEW.subject_id, NEW.gap_kind, NEW.detail, NEW.opened_by, NEW.opened_at)
     IS DISTINCT FROM (OLD.gap_id, OLD.scope, OLD.tenant_id, OLD.domain_id, OLD.subject_kind, OLD.subject_id, OLD.gap_kind, OLD.detail, OLD.opened_by, OLD.opened_at) THEN
    RAISE EXCEPTION 'data authority rejected (state): gap % is % — its opening record is immutable', OLD.gap_id, OLD.state USING ERRCODE = '2F002';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER gog_forward BEFORE UPDATE OR DELETE ON governance.ownership_gaps FOR EACH ROW EXECUTE FUNCTION governance.dr_gap_forward();

/* OPEN a gap (internal): the row, the hold (when held), the attention item (DOMAIN subjects — a PLATFORM gap is shown in the workspace and
   the ledger), the ledger event. Answers the gap row as jsonb (an existing live gap of the same subject and kind is answered as is). */
CREATE OR REPLACE FUNCTION governance.dr_open_gap(p_tenant uuid, p_domain uuid, p_subject_kind text, p_subject uuid, p_label text, p_kind text, p_detail jsonb, p_path text, p_held boolean,
                                                  p_named_owner uuid, p_consequence text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, pg_catalog, pg_temp AS $$
DECLARE g governance.ownership_gaps%ROWTYPE; v_ev uuid; v_item jsonb;
BEGIN
  SELECT * INTO g FROM governance.ownership_gaps x WHERE x.subject_id = p_subject AND x.gap_kind = p_kind AND x.state <> 'resolved';
  IF FOUND THEN RETURN to_jsonb(g) || jsonb_build_object('existing', true); END IF;
  INSERT INTO governance.ownership_gaps (gap_id, scope, tenant_id, domain_id, subject_kind, subject_id, subject_label, gap_kind, detail, escalation_path, held, opened_by, correlation_id)
  VALUES (gen_random_uuid(), CASE WHEN p_domain IS NULL THEN 'PLATFORM' ELSE 'DOMAIN' END, p_tenant, p_domain, p_subject_kind, p_subject, left(btrim(p_label), 300), p_kind,
          coalesce(p_detail, '{}'::jsonb), coalesce(NULLIF(btrim(coalesce(p_path, '')), ''), 'the steward, then the domain administrator'), p_held, p_actor, p_correlation) RETURNING * INTO g;
  IF p_held THEN
    PERFORM governance.dr_open_hold(p_tenant, p_domain, p_subject, 'ownership_gap', g.gap_id,
              format('ownership gap (%s) on %s: new consumption and authoritative changes stop until it is resolved or accepted', p_kind, g.subject_label), p_actor, p_correlation);
  END IF;
  v_ev := governance.ledger(p_tenant, p_domain, 'ownership_gap', g.gap_id, NULL, 'gap.opened', p_actor,
                            jsonb_build_object('subject_kind', p_subject_kind, 'subject_id', p_subject, 'gap_kind', p_kind, 'held', p_held, 'detail', g.detail, 'escalation_path', g.escalation_path), p_correlation);
  IF p_domain IS NOT NULL THEN
    v_item := executive.b33_raise_routed(p_tenant, p_domain, 'governance.ownership', CASE p_subject_kind WHEN 'stewardship_case' THEN 'stewardship_case' WHEN 'product' THEN 'product' ELSE 'asset' END,
                p_subject, left(format('Ownership gap (%s): %s — escalation: %s', replace(p_kind, '_', ' '), g.subject_label, g.escalation_path), 512),
                jsonb_build_array(format('the ownership of %s does not resolve (%s)', g.subject_label, p_kind)), p_named_owner, v_ev, 'OwnershipGapOpened',
                jsonb_build_object('gap_id', g.gap_id, 'gap_kind', p_kind, 'held', p_held, 'escalation_path', g.escalation_path, 'by', 'B107 §DR'),
                jsonb_build_object('consequence', coalesce(p_consequence, 'C2')), p_actor, p_correlation);
  END IF;
  RETURN to_jsonb(g) || jsonb_build_object('existing', false, 'item', v_item);
END $$;
REVOKE ALL ON FUNCTION governance.dr_open_gap(uuid, uuid, text, uuid, text, text, jsonb, text, boolean, uuid, text, uuid, uuid) FROM PUBLIC;

/* RESOLVE a gap (internal): the condition no longer holds — the hold lifted, the items closed, the ledger event. */
CREATE OR REPLACE FUNCTION governance.dr_resolve_gap(p_gap uuid, p_resolution text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, pg_catalog, pg_temp AS $$
DECLARE g governance.ownership_gaps%ROWTYPE;
BEGIN
  UPDATE governance.ownership_gaps SET state = 'resolved', resolved_by = p_actor, resolved_at = clock_timestamp(), resolution = left(btrim(p_resolution), 1000)
   WHERE gap_id = p_gap AND state <> 'resolved' RETURNING * INTO g;
  IF NOT FOUND THEN RETURN NULL; END IF;
  PERFORM governance.dr_lift_holds(g.subject_id, 'ownership_gap', g.gap_id, 'the ownership gap is resolved: ' || p_resolution, p_actor);
  IF g.domain_id IS NOT NULL THEN
    PERFORM executive.b33_close_items(g.tenant_id, g.domain_id, 'governance.ownership', NULL, g.subject_id, 'the ownership gap is resolved', p_actor, p_correlation);
  END IF;
  PERFORM governance.ledger(g.tenant_id, g.domain_id, 'ownership_gap', g.gap_id, NULL, 'gap.resolved', p_actor, jsonb_build_object('resolution', g.resolution), p_correlation);
  RETURN to_jsonb(g);
END $$;
REVOKE ALL ON FUNCTION governance.dr_resolve_gap(uuid, text, uuid, uuid) FROM PUBLIC;

/* What a domain's assets SAY about their ownership now (internal; the reconciliation's read): one row per (asset, gap kind) found. MATERIAL
   assets are products and sources; a ratified authority's failures are found on any asset. */
CREATE OR REPLACE FUNCTION governance.dr_domain_findings(p_tenant uuid, p_domain uuid) RETURNS TABLE (subject_kind text, subject_id uuid, label text, gap_kind text, detail jsonb, path text, owner uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, products, decision, pg_catalog, pg_temp AS $$
  WITH x AS (
    SELECT a.asset_id, a.kind, a.ref, a.title, a.owner_principal_id AS catalog_owner, r.authority_id, r.version, r.owner_principal_id AS owner, r.steward_principal_id AS steward,
           r.custodian_role, r.custodian_principal_id, r.policy_authority_role, r.quality_authority_role, r.escalation_path,
           p.product_id, p.product_key, p.owner_principal_id AS product_owner, p.state AS product_state
      FROM products.catalog_assets a
      LEFT JOIN governance.data_authorities r ON r.authority_id = a.asset_id AND r.state = 'ratified'
      LEFT JOIN products.products_current p ON a.kind = 'product' AND p.product_id::text = a.ref AND p.tenant_id = a.tenant_id AND p.domain_id = a.domain_id
     WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain)
  SELECT 'catalog_asset', x.asset_id, x.kind || ' ' || x.title || ' (' || x.ref || ')', 'no_owner',
         jsonb_build_object('reason', 'no ratified data authority: the asset does not resolve to an approved authority and ownership contract (DP-01-005)', 'catalog_owner', x.catalog_owner),
         'the data steward, then the domain administrator', x.catalog_owner
    FROM x WHERE x.authority_id IS NULL AND x.kind IN ('product', 'source')
  UNION ALL
  SELECT 'catalog_asset', x.asset_id, x.kind || ' ' || x.title || ' (' || x.ref || ')', 'owner_lost',
         jsonb_build_object('reason', CASE WHEN x.authority_id IS NOT NULL AND NOT decision.is_active_human(x.owner, p_tenant) THEN 'the ratified owner is no longer an active human of the tenant'
                                           ELSE 'the product''s own owner is no longer an active human of the tenant' END,
                            'registry_owner', x.owner, 'product_owner', x.product_owner, 'authority_version', x.version),
         coalesce(x.escalation_path, 'the data steward, then the domain administrator'), NULL::uuid
    FROM x WHERE (x.authority_id IS NOT NULL AND NOT decision.is_active_human(x.owner, p_tenant))
              OR (x.product_id IS NOT NULL AND x.product_state IN ('registered', 'released', 'degraded') AND NOT decision.is_active_human(x.product_owner, p_tenant))
  UNION ALL
  SELECT 'catalog_asset', x.asset_id, x.kind || ' ' || x.title || ' (' || x.ref || ')', 'conflicting_authorities',
         jsonb_build_object('reason', 'the data authority registry and the catalog name different owners — both instructions preserved; one is corrected by its own governed act',
                            'instructions', jsonb_build_array(jsonb_build_object('source', 'governance.data_authorities v' || x.version, 'owner', x.owner),
                                                              jsonb_build_object('source', 'products.catalog_assets', 'owner', x.catalog_owner))),
         x.escalation_path, x.owner
    FROM x WHERE x.authority_id IS NOT NULL AND x.catalog_owner IS NOT NULL AND x.catalog_owner <> x.owner AND decision.is_active_human(x.owner, p_tenant)
  UNION ALL
  SELECT 'catalog_asset', x.asset_id, x.kind || ' ' || x.title || ' (' || x.ref || ')', 'unresolved_authority',
         jsonb_build_object('reason', 'a duty of the ratified authority does not resolve',
                            'steward', CASE WHEN decision.is_active_human(x.steward, p_tenant) THEN 'resolved' ELSE 'lost' END,
                            'custodian', CASE WHEN x.custodian_principal_id IS NOT NULL THEN CASE WHEN x.custodian_principal_id = ANY (governance.dr_role_holders(p_tenant, p_domain, x.custodian_role)) THEN 'resolved' ELSE 'lost' END
                                              WHEN cardinality(governance.dr_role_holders(p_tenant, p_domain, x.custodian_role)) = 0 THEN 'unfilled'
                                              WHEN cardinality(governance.dr_role_holders(p_tenant, p_domain, x.custodian_role)) > 1 THEN 'ambiguous (several hold the role and none is named)' ELSE 'resolved' END,
                            'policy_authority', CASE WHEN cardinality(governance.dr_role_holders(p_tenant, p_domain, x.policy_authority_role)) = 0 THEN 'unfilled' ELSE 'resolved' END,
                            'quality_authority', CASE WHEN cardinality(governance.dr_role_holders(p_tenant, p_domain, x.quality_authority_role)) = 0 THEN 'unfilled' ELSE 'resolved' END),
         x.escalation_path, x.owner
    FROM x WHERE x.authority_id IS NOT NULL AND decision.is_active_human(x.owner, p_tenant)
              AND (NOT decision.is_active_human(x.steward, p_tenant)
                   OR (x.custodian_principal_id IS NOT NULL AND NOT (x.custodian_principal_id = ANY (governance.dr_role_holders(p_tenant, p_domain, x.custodian_role))))
                   OR (x.custodian_principal_id IS NULL AND cardinality(governance.dr_role_holders(p_tenant, p_domain, x.custodian_role)) <> 1)
                   OR cardinality(governance.dr_role_holders(p_tenant, p_domain, x.policy_authority_role)) = 0
                   OR cardinality(governance.dr_role_holders(p_tenant, p_domain, x.quality_authority_role)) = 0)
$$;
REVOKE ALL ON FUNCTION governance.dr_domain_findings(uuid, uuid) FROM PUBLIC;

/* RECONCILE A DOMAIN (governance.ownership.reconcile — a data steward or the domain administrator — or executive.attention.tick): the
   findings read FIRST, then: a NEW finding opens its gap (HELD — new consumption stops — for an owner lost, conflicting authorities or an
   unresolved duty; for a missing authority only in an ENFORCED domain: an observed domain lists it as debt); an ACCEPTED gap past its date
   with the condition still present re-opens; a live gap whose condition is gone RESOLVES; an open gap older than the escalation age
   ESCALATES (its escalation path; a C3 item). Answers what changed and the products to DEGRADE (DP-41-005: a released product whose owner is
   lost, or whose policy violation is recorded — the caller degrades them through products.degrade_product, never from inside this port). */
CREATE OR REPLACE FUNCTION governance.dr_reconcile_domain(p_run uuid, p_tenant uuid, p_domain uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, products, executive, decision, public, pg_catalog, pg_temp AS $$
DECLARE v_action text; v_mode text; f record; g governance.ownership_gaps%ROWTYPE; v_found jsonb := '[]'::jsonb; v_opened jsonb := '[]'::jsonb; v_reopened jsonb := '[]'::jsonb;
        v_resolved jsonb := '[]'::jsonb; v_escalated jsonb := '[]'::jsonb; v_degrade jsonb; v_r jsonb; v_ev uuid; v_held boolean; v_now timestamptz := clock_timestamp();
BEGIN
  v_action := governance.dr_domain_head(ARRAY['governance.ownership.reconcile', 'executive.attention.tick'], p_tenant, p_domain, p_actor, 'data authority');
  IF v_action = 'governance.ownership.reconcile' AND NOT executive.holds_role(p_actor, p_tenant, p_domain, ARRAY['data_steward', 'domain_admin']) THEN
    RAISE EXCEPTION 'data authority rejected (authority): ownership is reconciled by a data steward, the domain administrator or the attention tick' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.ownership.reconcile:' || p_domain::text, 0));
  v_mode := governance.dr_domain_mode(p_domain);
  -- 1. THE FINDINGS (read first)
  FOR f IN SELECT * FROM governance.dr_domain_findings(p_tenant, p_domain) ORDER BY 2, 4 LOOP
    v_found := v_found || jsonb_build_object('subject_id', f.subject_id, 'gap_kind', f.gap_kind);
    SELECT * INTO g FROM governance.ownership_gaps x WHERE x.subject_id = f.subject_id AND x.gap_kind = f.gap_kind AND x.state <> 'resolved';
    v_held := f.gap_kind <> 'no_owner' OR v_mode = 'enforced';
    IF NOT FOUND THEN
      v_r := governance.dr_open_gap(p_tenant, p_domain, f.subject_kind, f.subject_id, f.label, f.gap_kind, f.detail, f.path, v_held, f.owner, 'C2', p_actor, p_correlation);
      v_opened := v_opened || jsonb_build_object('gap_id', v_r ->> 'gap_id', 'subject_id', f.subject_id, 'gap_kind', f.gap_kind, 'held', v_held);
    ELSIF g.state = 'accepted' AND g.accepted_until < v_now THEN
      UPDATE governance.ownership_gaps SET state = 'open', accepted_by = NULL, accepted_at = NULL, accepted_until = NULL, accept_reason = NULL, held = v_held WHERE gap_id = g.gap_id;
      IF v_held THEN
        PERFORM governance.dr_open_hold(p_tenant, p_domain, g.subject_id, 'ownership_gap', g.gap_id,
                  format('ownership gap (%s) on %s: its acceptance lapsed at %s and the condition still holds', g.gap_kind, g.subject_label, g.accepted_until), p_actor, p_correlation);
      END IF;
      v_ev := governance.ledger(p_tenant, p_domain, 'ownership_gap', g.gap_id, NULL, 'gap.reopened', p_actor, jsonb_build_object('accepted_until', g.accepted_until), p_correlation);
      PERFORM executive.b33_raise_routed(p_tenant, p_domain, 'governance.ownership', 'asset', g.subject_id, left(format('Ownership gap RE-OPENED (%s): %s — the acceptance lapsed', g.gap_kind, g.subject_label), 512),
                jsonb_build_array('the accepted residual expired and the condition still holds'), f.owner, v_ev, 'OwnershipGapReopened', jsonb_build_object('gap_id', g.gap_id), jsonb_build_object('consequence', 'C2'), p_actor, p_correlation);
      v_reopened := v_reopened || jsonb_build_object('gap_id', g.gap_id, 'subject_id', g.subject_id, 'gap_kind', g.gap_kind);
    ELSIF g.state IN ('open', 'escalated') AND g.held <> v_held THEN
      -- the domain's mode changed: an enforced domain holds a missing authority; an observed one lists it
      UPDATE governance.ownership_gaps SET held = v_held WHERE gap_id = g.gap_id;
      IF v_held THEN PERFORM governance.dr_open_hold(p_tenant, p_domain, g.subject_id, 'ownership_gap', g.gap_id, format('ownership gap (%s) on %s: the domain enforces its ownership contract', g.gap_kind, g.subject_label), p_actor, p_correlation);
      ELSE PERFORM governance.dr_lift_holds(g.subject_id, 'ownership_gap', g.gap_id, 'the domain observes (does not enforce) a missing authority', p_actor); END IF;
    END IF;
  END LOOP;
  -- 2. RESOLUTION: a live DOMAIN gap of a reconciled kind whose condition is gone
  FOR g IN SELECT * FROM governance.ownership_gaps x WHERE x.tenant_id = p_tenant AND x.domain_id = p_domain AND x.state <> 'resolved' AND x.subject_kind = 'catalog_asset'
             AND NOT (jsonb_build_object('subject_id', x.subject_id, 'gap_kind', x.gap_kind) <@ ANY (ARRAY(SELECT jsonb_array_elements(v_found)))) LOOP
    v_r := governance.dr_resolve_gap(g.gap_id, format('the reconciliation (%s) no longer finds %s on %s', CASE WHEN v_action = 'executive.attention.tick' THEN 'tick' ELSE 'steward' END, g.gap_kind, g.subject_label), p_actor, p_correlation);
    v_resolved := v_resolved || jsonb_build_object('gap_id', g.gap_id, 'subject_id', g.subject_id, 'gap_kind', g.gap_kind);
  END LOOP;
  -- 3. ESCALATION by age (the recorded escalation path; a C3 item)
  FOR g IN SELECT * FROM governance.ownership_gaps x WHERE x.tenant_id = p_tenant AND x.domain_id = p_domain AND x.state IN ('open', 'escalated')
             AND coalesce(x.escalated_at, x.opened_at) < v_now - governance.dr_gap_escalation_after() LOOP
    UPDATE governance.ownership_gaps SET state = 'escalated', escalations = escalations + 1, escalated_at = v_now WHERE gap_id = g.gap_id;
    v_ev := governance.ledger(p_tenant, p_domain, 'ownership_gap', g.gap_id, NULL, 'gap.escalated', p_actor, jsonb_build_object('escalations', g.escalations + 1, 'escalation_path', g.escalation_path), p_correlation);
    PERFORM executive.b33_raise_routed(p_tenant, p_domain, 'governance.ownership', CASE g.subject_kind WHEN 'stewardship_case' THEN 'stewardship_case' ELSE 'asset' END, g.subject_id,
              left(format('ESCALATED ownership gap (%s, level %s): %s — %s', g.gap_kind, g.escalations + 1, g.subject_label, g.escalation_path), 512),
              jsonb_build_array(format('open since %s, beyond the escalation age %s', g.opened_at, governance.dr_gap_escalation_after())), NULL, v_ev, 'OwnershipGapEscalated',
              jsonb_build_object('gap_id', g.gap_id, 'level', g.escalations + 1), jsonb_build_object('consequence', 'C3'), p_actor, p_correlation);
    v_escalated := v_escalated || jsonb_build_object('gap_id', g.gap_id, 'level', g.escalations + 1);
  END LOOP;
  -- 4. THE PRODUCTS TO DEGRADE (DP-41-005): released, owner lost or a recorded policy violation
  SELECT coalesce(jsonb_agg(jsonb_build_object('product_id', p.product_id, 'product_key', p.product_key,
           'cause', CASE WHEN NOT decision.is_active_human(p.owner_principal_id, p_tenant) THEN 'owner_lost' ELSE 'policy_violation' END,
           'reason', CASE WHEN NOT decision.is_active_human(p.owner_principal_id, p_tenant)
                          THEN format('the product''s owner is no longer an active human of the tenant (ownership lost — DP-41-005); restored through an accepted domain review once an owner is named')
                          ELSE format('a policy violation is recorded on the product (stewardship case %s approved — DP-41-005); restored through an accepted domain review',
                                      (SELECT string_agg(c.case_ref, ', ' ORDER BY c.case_ref) FROM governance.stewardship_cases c WHERE c.subject_kind = 'product' AND c.subject_id = p.product_id
                                          AND c.kind IN ('access', 'classification') AND c.state = 'approved')) END) ORDER BY p.product_key), '[]'::jsonb)
    INTO v_degrade
    FROM products.products_current p
   WHERE p.tenant_id = p_tenant AND p.domain_id = p_domain AND p.state = 'released'
     AND (NOT decision.is_active_human(p.owner_principal_id, p_tenant)
          OR EXISTS (SELECT 1 FROM governance.stewardship_cases c WHERE c.subject_kind = 'product' AND c.subject_id = p.product_id AND c.kind IN ('access', 'classification') AND c.state = 'approved'));
  PERFORM governance.ledger(p_tenant, p_domain, 'ownership_run', p_run, NULL, 'reconcile.ran', p_actor,
                            jsonb_build_object('trigger', CASE WHEN v_action = 'executive.attention.tick' THEN 'tick' ELSE 'steward' END, 'mode', v_mode, 'found', jsonb_array_length(v_found),
                                               'opened', jsonb_array_length(v_opened), 'reopened', jsonb_array_length(v_reopened), 'resolved', jsonb_array_length(v_resolved),
                                               'escalated', jsonb_array_length(v_escalated), 'degrade', v_degrade), p_correlation);
  RETURN jsonb_build_object('run_id', p_run, 'mode', v_mode, 'at', v_now, 'found', v_found, 'opened', v_opened, 'reopened', v_reopened, 'resolved', v_resolved, 'escalated', v_escalated,
                            'degrade', v_degrade,
                            'open', (SELECT count(*) FROM governance.ownership_gaps x WHERE x.tenant_id = p_tenant AND x.domain_id = p_domain AND x.state IN ('open', 'escalated')));
END $$;
REVOKE ALL ON FUNCTION governance.dr_reconcile_domain(uuid, uuid, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_reconcile_domain(uuid, uuid, uuid, uuid, uuid) TO eye_commit;

/* The tick's cheap look (a read inside the tick's write): is the domain registered (a ratified registry entry), and is a reconciliation due? */
CREATE OR REPLACE FUNCTION governance.dr_reconcile_due(p_tenant uuid, p_domain uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT jsonb_build_object('mode', governance.dr_domain_mode(p_domain), 'registered', governance.dr_domain_mode(p_domain) <> 'unregistered')
$$;
REVOKE ALL ON FUNCTION governance.dr_reconcile_due(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_reconcile_due(uuid, uuid) TO eye_commit;

/* ACCEPT A GAP (governance.ownership.gap.accept — DOMAIN; governance.ownership.platform_gap.accept — PLATFORM; human-gated): a named approver
   (DOMAIN: the domain or tenant administrator; PLATFORM: the product or operations authority) — never the one who opened it, never the owner
   of the subject — accepts the RESIDUAL until a date (≤ 90 days): the hold lifts, the gap stays LISTED as accepted, and the reconciliation
   re-opens it at that date if the condition still holds. */
CREATE OR REPLACE FUNCTION governance.dr_accept_gap(p_gap uuid, p_tenant uuid, p_domain uuid, p_until timestamptz, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, public, pg_catalog, pg_temp AS $$
DECLARE g governance.ownership_gaps%ROWTYPE; v_owner uuid; v_lifted jsonb;
BEGIN
  SELECT * INTO g FROM governance.ownership_gaps x WHERE x.gap_id = p_gap FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_gap): % is not an ownership gap', p_gap USING ERRCODE = '22023'; END IF;
  IF g.scope = 'PLATFORM' THEN
    PERFORM governance.assert_platform('governance.ownership.platform_gap.accept', p_actor, 'data authority');
    SELECT o.accountable_principal_id INTO v_owner FROM governance.component_ownerships o WHERE o.component_artifact = g.subject_id AND o.superseded_at IS NULL;
    PERFORM governance.assert_approver('data authority', p_actor, NULL, NULL, ARRAY['product_authority', 'operations_authority'], g.opened_by, CASE WHEN v_owner IS NULL THEN NULL ELSE ARRAY[v_owner] END, 'accepting an ownership gap');
  ELSE
    PERFORM governance.dr_domain_head(ARRAY['governance.ownership.gap.accept'], p_tenant, p_domain, p_actor, 'data authority');
    IF g.tenant_id IS DISTINCT FROM p_tenant OR g.domain_id IS DISTINCT FROM p_domain THEN RAISE EXCEPTION 'data authority rejected (unknown_gap): % is not an ownership gap of this domain', p_gap USING ERRCODE = '22023'; END IF;
    SELECT r.owner_principal_id INTO v_owner FROM governance.data_authorities r WHERE r.authority_id = g.subject_id AND r.state = 'ratified';
    PERFORM governance.assert_approver('data authority', p_actor, p_tenant, p_domain, ARRAY['domain_admin', 'tenant_admin'], g.opened_by, CASE WHEN v_owner IS NULL THEN NULL ELSE ARRAY[v_owner] END, 'accepting an ownership gap');
  END IF;
  IF g.state NOT IN ('open', 'escalated') THEN RAISE EXCEPTION 'data authority rejected (state): gap % is %', p_gap, g.state USING ERRCODE = '22023'; END IF;
  IF p_until IS NULL OR p_until <= clock_timestamp() OR p_until > clock_timestamp() + interval '90 days' THEN
    RAISE EXCEPTION 'data authority rejected (expiry): a residual is accepted until a date within 90 days' USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 12 THEN RAISE EXCEPTION 'data authority rejected (reason): an acceptance states its reason and its compensating control (12+ characters)' USING ERRCODE = '22023'; END IF;
  UPDATE governance.ownership_gaps SET state = 'accepted', accepted_by = p_actor, accepted_at = clock_timestamp(), accepted_until = p_until, accept_reason = btrim(p_reason) WHERE gap_id = p_gap RETURNING * INTO g;
  v_lifted := governance.dr_lift_holds(g.subject_id, 'ownership_gap', g.gap_id, format('residual accepted until %s: %s', p_until, btrim(p_reason)), p_actor);
  IF g.domain_id IS NOT NULL THEN PERFORM executive.b33_close_items(g.tenant_id, g.domain_id, 'governance.ownership', NULL, g.subject_id, 'the ownership gap''s residual was accepted until ' || p_until, p_actor, p_correlation); END IF;
  PERFORM governance.ledger(g.tenant_id, g.domain_id, 'ownership_gap', g.gap_id, NULL, 'gap.accepted', p_actor, jsonb_build_object('until', p_until, 'reason', btrim(p_reason), 'lifted', v_lifted), p_correlation);
  RETURN to_jsonb(g) || jsonb_build_object('lifted', v_lifted);
END $$;
REVOKE ALL ON FUNCTION governance.dr_accept_gap(uuid, uuid, uuid, timestamptz, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_accept_gap(uuid, uuid, uuid, timestamptz, text, uuid, uuid) TO eye_commit;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.4 THE DATA CAPABILITY INVENTORY (PLATFORM; DP-01-001/-002/-005/-006)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
CREATE TABLE governance.data_capabilities (
  capability_id      uuid NOT NULL,
  version            int  NOT NULL CHECK (version >= 1),
  scope              text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  dat_key            text NOT NULL CHECK (dat_key ~ '^DAT-[A-Z]{2}-[0-9]{2}$'),
  title              text NOT NULL CHECK (length(btrim(title)) BETWEEN 2 AND 200),
  capability_group   text NOT NULL CHECK (length(btrim(capability_group)) BETWEEN 2 AND 120),
  layer              text NOT NULL CHECK (length(btrim(layer)) BETWEEN 2 AND 120),
  authority_class    text NOT NULL CHECK (length(btrim(authority_class)) BETWEEN 2 AND 120),
  purpose            text,
  lifecycle          text NOT NULL CHECK (lifecycle IN ('planned', 'implemented', 'deprecated', 'retired')),
  deployment_scope   text NOT NULL CHECK (deployment_scope IN ('PLATFORM', 'TENANT', 'DOMAIN')),
  owner_principal_id uuid,
  owner_role         text REFERENCES identity.roles (code),
  owner_accepted_at  timestamptz,
  realization        jsonb NOT NULL CHECK (jsonb_typeof(realization) = 'object'),   -- {schemas[], relations[], functions[]}
  source             jsonb NOT NULL CHECK (jsonb_typeof(source) = 'object'),        -- {file, digest, row} — imported read-only
  observed           jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(observed) = 'object'),
  conformance        text NOT NULL DEFAULT 'unreconciled' CHECK (conformance IN ('unreconciled', 'conformant', 'drift', 'unresolved')),
  reconciled_at      timestamptz,
  admission          text NOT NULL DEFAULT 'not_admitted' CHECK (admission IN ('not_admitted', 'admitted')),
  admitted_by        uuid,
  admitted_at        timestamptz,
  admission_reason   text,
  digest             text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  declared_by        uuid NOT NULL,
  declared_at        timestamptz NOT NULL DEFAULT clock_timestamp(),
  superseded_at      timestamptz,
  correlation_id     uuid NOT NULL,
  PRIMARY KEY (capability_id, version),
  CONSTRAINT gdc_owner_pair CHECK ((owner_principal_id IS NULL) = (owner_role IS NULL)),
  CONSTRAINT gdc_admitted CHECK ((admission = 'admitted') = (admitted_by IS NOT NULL AND admitted_at IS NOT NULL AND admission_reason IS NOT NULL)),
  CONSTRAINT gdc_sod CHECK (admitted_by IS NULL OR (admitted_by <> declared_by AND admitted_by IS DISTINCT FROM owner_principal_id))
);
CREATE UNIQUE INDEX gdc_one_current ON governance.data_capabilities (capability_id) WHERE superseded_at IS NULL;
CREATE UNIQUE INDEX gdc_key_current ON governance.data_capabilities (dat_key) WHERE superseded_at IS NULL;
CREATE OR REPLACE FUNCTION governance.dr_capability_forward() RETURNS trigger LANGUAGE plpgsql SET search_path = governance, pg_catalog, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'data authority rejected (state): a data capability version is never deleted' USING ERRCODE = '2F002'; END IF;
  IF OLD.superseded_at IS NOT NULL OR (to_jsonb(NEW) - ARRAY['owner_accepted_at', 'observed', 'conformance', 'reconciled_at', 'admission', 'admitted_by', 'admitted_at', 'admission_reason', 'superseded_at'])
     IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['owner_accepted_at', 'observed', 'conformance', 'reconciled_at', 'admission', 'admitted_by', 'admitted_at', 'admission_reason', 'superseded_at']) THEN
    RAISE EXCEPTION 'data authority rejected (state): data capability version %/% is immutable; a change is a new version', OLD.dat_key, OLD.version USING ERRCODE = '2F002';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER gdc_forward BEFORE UPDATE OR DELETE ON governance.data_capabilities FOR EACH ROW EXECUTE FUNCTION governance.dr_capability_forward();

/* DECLARE (governance.ownership.capability.declare; the conformance steward): one DAT id's declaration — idempotent (the same body answers
   the current version unchanged: the importer re-runs safely); a changed body is a NEW version (expected = the current version), which is
   NOT admitted and not reconciled until it is reconciled and admitted again. The owner, when named, is an active PLATFORM human holding the
   owner role at PLATFORM. Registered in the §0 core (kind capability, attributes.class data_capability). */
CREATE OR REPLACE FUNCTION governance.dr_declare_capability(p_capability uuid, p_dat_key text, p_title text, p_group text, p_layer text, p_class text, p_purpose text, p_lifecycle text,
                                                            p_deployment_scope text, p_owner uuid, p_owner_role text, p_realization jsonb, p_source jsonb, p_expected int, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, identity, public, pg_catalog, pg_temp AS $$
DECLARE cur governance.data_capabilities%ROWTYPE; v_id uuid; v_body jsonb; v_digest text; c governance.data_capabilities%ROWTYPE; k text;
BEGIN
  PERFORM governance.assert_platform('governance.ownership.capability.declare', p_actor, 'data authority');
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['conformance_steward']) THEN
    RAISE EXCEPTION 'data authority rejected (authority): the data capability inventory is declared by the conformance steward' USING ERRCODE = '42501';
  END IF;
  IF coalesce(p_dat_key, '') !~ '^DAT-[A-Z]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'data authority rejected (key): a data capability is a DAT id (DAT-XX-00)' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_title, ''))) NOT BETWEEN 2 AND 200 OR length(btrim(coalesce(p_group, ''))) NOT BETWEEN 2 AND 120 OR length(btrim(coalesce(p_layer, ''))) NOT BETWEEN 2 AND 120
     OR length(btrim(coalesce(p_class, ''))) NOT BETWEEN 2 AND 120 THEN
    RAISE EXCEPTION 'data authority rejected (declaration): a data capability names its title, group, layer and authority class' USING ERRCODE = '22023';
  END IF;
  IF p_lifecycle IS NULL OR p_lifecycle NOT IN ('planned', 'implemented', 'deprecated', 'retired') THEN RAISE EXCEPTION 'data authority rejected (lifecycle): planned, implemented, deprecated or retired' USING ERRCODE = '22023'; END IF;
  IF p_deployment_scope IS NULL OR p_deployment_scope NOT IN ('PLATFORM', 'TENANT', 'DOMAIN') THEN RAISE EXCEPTION 'data authority rejected (scope): the deployment scope is PLATFORM, TENANT or DOMAIN' USING ERRCODE = '22023'; END IF;
  IF (p_owner IS NULL) <> (p_owner_role IS NULL) THEN RAISE EXCEPTION 'data authority rejected (owner): an owner is named with the role it owns under' USING ERRCODE = '22023'; END IF;
  IF p_owner IS NOT NULL AND (NOT governance.dr_platform_human(p_owner) OR NOT governance.holds_role(p_owner, NULL, NULL, ARRAY[p_owner_role])
                              OR NOT EXISTS (SELECT 1 FROM identity.role_bindings b WHERE b.principal_id = p_owner AND b.role_code = p_owner_role AND b.scope = 'PLATFORM' AND b.revoked_at IS NULL)) THEN
    RAISE EXCEPTION 'data authority rejected (unknown_owner): the owner is an active PLATFORM human holding % at PLATFORM', p_owner_role USING ERRCODE = '22023';
  END IF;
  IF p_realization IS NULL OR jsonb_typeof(p_realization) <> 'object' THEN RAISE EXCEPTION 'data authority rejected (realization): the realization is {schemas, relations, functions}' USING ERRCODE = '22023'; END IF;
  FOREACH k IN ARRAY ARRAY['schemas', 'relations', 'functions'] LOOP
    IF p_realization ? k AND (jsonb_typeof(p_realization -> k) <> 'array' OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_realization -> k) x WHERE jsonb_typeof(x) <> 'string' OR (x #>> '{}') !~ '^[a-z_][a-z0-9_]*(\.[a-z_][a-z0-9_]*)?$')) THEN
      RAISE EXCEPTION 'data authority rejected (realization): % is a list of database names (schema, schema.relation, schema.function)', k USING ERRCODE = '22023';
    END IF;
  END LOOP;
  IF p_source IS NULL OR jsonb_typeof(p_source) <> 'object' THEN RAISE EXCEPTION 'data authority rejected (source): the source names the file, its digest and the row it was read from' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.capability:' || p_dat_key, 0));
  SELECT * INTO cur FROM governance.data_capabilities x WHERE x.dat_key = p_dat_key AND x.superseded_at IS NULL;
  v_id := coalesce(cur.capability_id, p_capability, gen_random_uuid());
  IF p_capability IS NOT NULL AND cur.capability_id IS NOT NULL AND p_capability <> cur.capability_id THEN
    RAISE EXCEPTION 'data authority rejected (duplicate): % is declared as capability %', p_dat_key, cur.capability_id USING ERRCODE = '23505';
  END IF;
  v_body := jsonb_build_object('dat_key', p_dat_key, 'title', btrim(p_title), 'group', btrim(p_group), 'layer', btrim(p_layer), 'authority_class', btrim(p_class), 'purpose', NULLIF(btrim(coalesce(p_purpose, '')), ''),
                               'lifecycle', p_lifecycle, 'deployment_scope', p_deployment_scope, 'owner', p_owner, 'owner_role', p_owner_role,
                               'realization', jsonb_build_object('schemas', coalesce(p_realization -> 'schemas', '[]'::jsonb), 'relations', coalesce(p_realization -> 'relations', '[]'::jsonb),
                                                                 'functions', coalesce(p_realization -> 'functions', '[]'::jsonb)));
  v_digest := governance.digest(v_body);
  IF cur.capability_id IS NOT NULL AND cur.digest = v_digest THEN
    RETURN (to_jsonb(cur) - 'scope' - 'correlation_id') || jsonb_build_object('unchanged', true);
  END IF;
  IF p_expected IS DISTINCT FROM coalesce(cur.version, 0) THEN
    RAISE EXCEPTION 'data authority rejected (stale): % is at version %, the declaration names %', p_dat_key, coalesce(cur.version, 0), coalesce(p_expected::text, 'none') USING ERRCODE = '22023';
  END IF;
  IF cur.capability_id IS NOT NULL THEN UPDATE governance.data_capabilities SET superseded_at = clock_timestamp() WHERE capability_id = cur.capability_id AND version = cur.version; END IF;
  INSERT INTO governance.data_capabilities (capability_id, version, dat_key, title, capability_group, layer, authority_class, purpose, lifecycle, deployment_scope, owner_principal_id, owner_role,
                                            realization, source, digest, declared_by, correlation_id)
  VALUES (v_id, coalesce(cur.version, 0) + 1, p_dat_key, btrim(p_title), btrim(p_group), btrim(p_layer), btrim(p_class), NULLIF(btrim(coalesce(p_purpose, '')), ''), p_lifecycle, p_deployment_scope,
          p_owner, p_owner_role, v_body -> 'realization', p_source, v_digest, p_actor, p_correlation) RETURNING * INTO c;
  PERFORM governance.dr_register(v_id, 'PLATFORM', NULL, NULL, 'capability', p_dat_key, btrim(p_title), p_owner, p_owner_role, btrim(p_class),
                                 CASE p_lifecycle WHEN 'planned' THEN 'proposed' WHEN 'implemented' THEN 'active' ELSE p_lifecycle END,
                                 jsonb_build_object('class', 'data_capability', 'group', btrim(p_group), 'layer', btrim(p_layer), 'deployment_scope', p_deployment_scope, 'capability_version', c.version),
                                 v_digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'data_capability', v_id, c.version, 'capability.declared', p_actor, jsonb_build_object('dat_key', p_dat_key, 'digest', v_digest, 'source', p_source), p_correlation);
  RETURN (to_jsonb(c) - 'scope' - 'correlation_id') || jsonb_build_object('unchanged', false);
END $$;
REVOKE ALL ON FUNCTION governance.dr_declare_capability(uuid, text, text, text, text, text, text, text, text, uuid, text, jsonb, jsonb, int, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_declare_capability(uuid, text, text, text, text, text, text, text, text, uuid, text, jsonb, jsonb, int, uuid, uuid) TO eye_commit;

/* What the database OBSERVES of a realization (internal): each declared schema, relation and function present or missing. */
CREATE OR REPLACE FUNCTION governance.dr_observe_realization(p_realization jsonb) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT jsonb_build_object(
    'schemas', coalesce((SELECT jsonb_agg(jsonb_build_object('name', s, 'present', EXISTS (SELECT 1 FROM pg_namespace n WHERE n.nspname = s)) ORDER BY s)
                           FROM jsonb_array_elements_text(coalesce(p_realization -> 'schemas', '[]'::jsonb)) s), '[]'::jsonb),
    'relations', coalesce((SELECT jsonb_agg(jsonb_build_object('name', r, 'present', to_regclass(r) IS NOT NULL) ORDER BY r)
                             FROM jsonb_array_elements_text(coalesce(p_realization -> 'relations', '[]'::jsonb)) r), '[]'::jsonb),
    'functions', coalesce((SELECT jsonb_agg(jsonb_build_object('name', f, 'present', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                                                                                          WHERE n.nspname = split_part(f, '.', 1) AND p.proname = split_part(f, '.', 2))) ORDER BY f)
                             FROM jsonb_array_elements_text(coalesce(p_realization -> 'functions', '[]'::jsonb)) f), '[]'::jsonb))
$$;
REVOKE ALL ON FUNCTION governance.dr_observe_realization(jsonb) FROM PUBLIC;

/* RECONCILE (governance.ownership.capability.reconcile; the conformance steward): the declaration against the OBSERVED database and the
   owner against the principals: conformant | drift (a declared object is missing, or nothing realizes an implemented capability) |
   unresolved (no owner, the owner lost or no longer holding the role). Unresolved opens a PLATFORM gap and holds the capability
   (ownership_gap); drift holds it (conformance_drift); a cleared condition resolves / lifts. The state found is recorded. */
CREATE OR REPLACE FUNCTION governance.dr_reconcile_capability(p_capability uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, identity, public, pg_catalog, pg_temp AS $$
DECLARE c governance.data_capabilities%ROWTYPE; v_obs jsonb; v_missing jsonb; v_owner text; v_conf text; v_gap jsonb; g governance.ownership_gaps%ROWTYPE; v_empty boolean;
BEGIN
  PERFORM governance.assert_platform('governance.ownership.capability.reconcile', p_actor, 'data authority');
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['conformance_steward']) THEN
    RAISE EXCEPTION 'data authority rejected (authority): the data capability inventory is reconciled by the conformance steward' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO c FROM governance.data_capabilities x WHERE x.capability_id = p_capability AND x.superseded_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_capability): % is not a declared data capability', p_capability USING ERRCODE = '22023'; END IF;
  v_obs := governance.dr_observe_realization(c.realization);
  SELECT coalesce(jsonb_agg(x ->> 'name'), '[]'::jsonb) INTO v_missing FROM (SELECT jsonb_array_elements(v_obs -> 'schemas') x UNION ALL SELECT jsonb_array_elements(v_obs -> 'relations')
                                                                             UNION ALL SELECT jsonb_array_elements(v_obs -> 'functions')) q WHERE NOT (x ->> 'present')::boolean;
  v_empty := jsonb_array_length(v_obs -> 'schemas') + jsonb_array_length(v_obs -> 'relations') + jsonb_array_length(v_obs -> 'functions') = 0;
  v_owner := CASE WHEN c.owner_principal_id IS NULL THEN 'none'
                  WHEN NOT governance.dr_platform_human(c.owner_principal_id) THEN 'lost'
                  WHEN NOT EXISTS (SELECT 1 FROM identity.role_bindings b WHERE b.principal_id = c.owner_principal_id AND b.role_code = c.owner_role AND b.scope = 'PLATFORM' AND b.revoked_at IS NULL) THEN 'lost'
                  ELSE 'resolved' END;
  v_conf := CASE WHEN v_owner <> 'resolved' THEN 'unresolved' WHEN jsonb_array_length(v_missing) > 0 OR (v_empty AND c.lifecycle = 'implemented') THEN 'drift' ELSE 'conformant' END;
  UPDATE governance.data_capabilities SET observed = jsonb_build_object('realization', v_obs, 'missing', v_missing, 'owner', v_owner, 'nothing_realizes', v_empty), conformance = v_conf, reconciled_at = clock_timestamp()
   WHERE capability_id = c.capability_id AND version = c.version RETURNING * INTO c;
  -- the ownership gap (PLATFORM) and its hold
  IF v_owner <> 'resolved' THEN
    v_gap := governance.dr_open_gap(NULL, NULL, 'data_capability', c.capability_id, c.dat_key || ' ' || c.title, CASE v_owner WHEN 'none' THEN 'no_owner' ELSE 'owner_lost' END,
                                    jsonb_build_object('reason', CASE v_owner WHEN 'none' THEN 'no accountable owner is declared' ELSE 'the declared owner is no longer an active PLATFORM human holding ' || c.owner_role END,
                                                       'owner', c.owner_principal_id, 'owner_role', c.owner_role, 'version', c.version),
                                    'the conformance steward, then the product authority', true, NULL, 'C2', p_actor, p_correlation);
  END IF;
  FOR g IN SELECT * FROM governance.ownership_gaps x WHERE x.subject_id = c.capability_id AND x.state <> 'resolved'
             AND (v_owner = 'resolved' OR x.gap_kind <> CASE v_owner WHEN 'none' THEN 'no_owner' ELSE 'owner_lost' END) LOOP
    PERFORM governance.dr_resolve_gap(g.gap_id, format('the reconciliation finds the owner %s', v_owner), p_actor, p_correlation);
  END LOOP;
  IF v_conf = 'drift' THEN
    PERFORM governance.dr_open_hold(NULL, NULL, c.capability_id, 'conformance_drift', c.capability_id,
              format('%s drifts from its declaration: %s', c.dat_key, CASE WHEN v_empty THEN 'nothing realizes an implemented capability' ELSE 'missing ' || (v_missing #>> '{}') END), p_actor, p_correlation);
  ELSE
    PERFORM governance.dr_lift_holds(c.capability_id, 'conformance_drift', c.capability_id, 'the declaration is observed again', p_actor);
  END IF;
  PERFORM governance.ledger(NULL, NULL, 'data_capability', c.capability_id, c.version, 'capability.reconciled', p_actor, jsonb_build_object('conformance', v_conf, 'missing', v_missing, 'owner', v_owner), p_correlation);
  RETURN (to_jsonb(c) - 'scope' - 'correlation_id') || jsonb_build_object('holds', governance.dr_consumption_holds(c.capability_id),
          'drift_holds', (SELECT count(*) FROM governance.holds h WHERE h.subject_artifact = c.capability_id AND h.lifted_at IS NULL AND h.reason_kind = 'conformance_drift'));
END $$;
REVOKE ALL ON FUNCTION governance.dr_reconcile_capability(uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_reconcile_capability(uuid, uuid, uuid) TO eye_commit;

/* ACCEPT (governance.ownership.capability.accept): the NAMED OWNER accepts ownership of the current version, on its digest. */
CREATE OR REPLACE FUNCTION governance.dr_accept_capability(p_capability uuid, p_version int, p_digest text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE c governance.data_capabilities%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.ownership.capability.accept', p_actor, 'data authority');
  SELECT * INTO c FROM governance.data_capabilities x WHERE x.capability_id = p_capability AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_capability): no version % of %', p_version, p_capability USING ERRCODE = '22023'; END IF;
  IF onboarding.principal_kind(p_actor) IS DISTINCT FROM 'human' THEN RAISE EXCEPTION 'data authority rejected (actor): ownership is accepted by a named human' USING ERRCODE = '42501'; END IF;
  IF c.owner_principal_id IS DISTINCT FROM p_actor THEN RAISE EXCEPTION 'data authority rejected (ownership): ownership of % is accepted by its named owner only', c.dat_key USING ERRCODE = '42501'; END IF;
  IF c.superseded_at IS NOT NULL THEN RAISE EXCEPTION 'data authority rejected (stale): version % of % is superseded', p_version, c.dat_key USING ERRCODE = '22023'; END IF;
  IF p_digest IS DISTINCT FROM c.digest THEN RAISE EXCEPTION 'data authority rejected (stale): the digest accepted is not version %''s', p_version USING ERRCODE = '22023'; END IF;
  IF c.owner_accepted_at IS NOT NULL THEN RAISE EXCEPTION 'data authority rejected (duplicate): ownership was accepted at %', c.owner_accepted_at USING ERRCODE = '22023'; END IF;
  UPDATE governance.data_capabilities SET owner_accepted_at = clock_timestamp() WHERE capability_id = p_capability AND version = p_version RETURNING * INTO c;
  PERFORM governance.ledger(NULL, NULL, 'data_capability', c.capability_id, c.version, 'capability.owner_accepted', p_actor, jsonb_build_object('digest', c.digest), p_correlation);
  RETURN to_jsonb(c) - 'scope' - 'correlation_id';
END $$;
REVOKE ALL ON FUNCTION governance.dr_accept_capability(uuid, int, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_accept_capability(uuid, int, text, uuid, uuid) TO eye_commit;

/* ADMIT (governance.ownership.capability.admit; human-gated): the product or operations authority — never the declarer, never the owner —
   admits the CURRENT version into the governed inventory on its digest, only when it is conformant as reconciled AFTER its declaration, its
   owner accepted, and no hold stands on it; otherwise refused (held), the disputed state preserved and the gap routed (DP-01-005). This is
   the inventory's admission — PRODUCTION admission is R1 and never claimed here. */
CREATE OR REPLACE FUNCTION governance.dr_admit_capability(p_capability uuid, p_version int, p_digest text, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE c governance.data_capabilities%ROWTYPE; v_holds jsonb; v_blocking text[] := '{}';
BEGIN
  PERFORM governance.assert_platform('governance.ownership.capability.admit', p_actor, 'data authority');
  SELECT * INTO c FROM governance.data_capabilities x WHERE x.capability_id = p_capability AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_capability): no version % of %', p_version, p_capability USING ERRCODE = '22023'; END IF;
  PERFORM governance.assert_approver('data authority', p_actor, NULL, NULL, ARRAY['product_authority', 'operations_authority'], c.declared_by,
                                     CASE WHEN c.owner_principal_id IS NULL THEN NULL ELSE ARRAY[c.owner_principal_id] END, 'admitting a data capability');
  IF c.superseded_at IS NOT NULL OR p_digest IS DISTINCT FROM c.digest THEN RAISE EXCEPTION 'data authority rejected (stale): admission names the current version and its digest' USING ERRCODE = '22023'; END IF;
  IF c.admission = 'admitted' THEN RAISE EXCEPTION 'data authority rejected (duplicate): % v% was admitted at %', c.dat_key, c.version, c.admitted_at USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'data authority rejected (reason): an admission states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('hold_id', h.hold_id, 'reason_kind', h.reason_kind, 'reason', h.reason)), '[]'::jsonb) INTO v_holds
    FROM governance.holds h WHERE h.subject_artifact = c.capability_id AND h.lifted_at IS NULL;
  IF c.conformance <> 'conformant' OR c.reconciled_at IS NULL OR c.reconciled_at < c.declared_at THEN v_blocking := v_blocking || format('the declaration is %s as last reconciled', c.conformance); END IF;
  IF c.owner_accepted_at IS NULL THEN v_blocking := v_blocking || 'the owner has not accepted ownership'::text; END IF;
  IF jsonb_array_length(v_holds) > 0 THEN v_blocking := v_blocking || format('%s open hold(s)', jsonb_array_length(v_holds)); END IF;
  IF cardinality(v_blocking) > 0 THEN
    RAISE EXCEPTION 'data authority rejected (held): % is not admitted — %; the disputed state is preserved and routed to governance (DP-01-005)', c.dat_key, array_to_string(v_blocking, '; ') USING ERRCODE = '22023';
  END IF;
  UPDATE governance.data_capabilities SET admission = 'admitted', admitted_by = p_actor, admitted_at = clock_timestamp(), admission_reason = btrim(p_reason)
   WHERE capability_id = c.capability_id AND version = c.version RETURNING * INTO c;
  PERFORM governance.ledger(NULL, NULL, 'data_capability', c.capability_id, c.version, 'capability.admitted', p_actor, jsonb_build_object('digest', c.digest, 'reason', btrim(p_reason),
                            'production_admission', 'R1 — external; never claimed by this record'), p_correlation);
  RETURN (to_jsonb(c) - 'scope' - 'correlation_id') || jsonb_build_object('production_admission', 'R1 — external; never claimed by this record');
END $$;
REVOKE ALL ON FUNCTION governance.dr_admit_capability(uuid, int, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_admit_capability(uuid, int, text, text, uuid, uuid) TO eye_commit;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.5 COMPONENT OWNERSHIP AND THE RATIFIED TRANSFER (PLATFORM; ES-04-001/-002, ES-11-001/-002/-005, PER-19)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
/* THE OWNERSHIP RECORD of a logical component or deployable unit (a §0 artifact of kind component | deployable_unit — §RG / §CM register
   them; this part reads them by kind, never their tables): versioned, ONE current per component; every version is made by a RATIFIED
   TRANSFER (the first assignment is a transfer from nobody). */
CREATE TABLE governance.component_ownerships (
  ownership_id            uuid NOT NULL,
  version                 int  NOT NULL CHECK (version >= 1),
  scope                   text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  component_artifact      uuid NOT NULL,
  component_key           text NOT NULL,
  component_kind          text NOT NULL CHECK (component_kind IN ('component', 'deployable_unit')),
  owning_team             text NOT NULL CHECK (length(btrim(owning_team)) BETWEEN 2 AND 120),   -- exactly ONE accountable owning team (ES-04-001)
  accountable_principal_id uuid NOT NULL,
  primary_contact         uuid NOT NULL,
  secondary_contact       uuid NOT NULL,
  operator_role           text NOT NULL REFERENCES identity.roles (code),                    -- PER-19: operates; content only under an approved support purpose
  owned_contracts         text[] NOT NULL CHECK (cardinality(owned_contracts) >= 1),         -- ES-11-002: the contracts its owned behaviour exposes
  state_stores            text[] NOT NULL DEFAULT '{}',
  policy_decisions        text[] NOT NULL DEFAULT '{}',
  telemetry_namespace     text NOT NULL CHECK (length(btrim(telemetry_namespace)) BETWEEN 2 AND 120),
  failure_domain          text NOT NULL CHECK (length(btrim(failure_domain)) BETWEEN 2 AND 120),
  deployable_units        text[] NOT NULL CHECK (cardinality(deployable_units) >= 1),
  transfer_id             uuid NOT NULL,
  signature_id            uuid NOT NULL,
  digest                  text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  ratified_by             uuid NOT NULL,
  ratified_at             timestamptz NOT NULL DEFAULT clock_timestamp(),
  superseded_at           timestamptz,
  correlation_id          uuid NOT NULL,
  PRIMARY KEY (ownership_id, version),
  CONSTRAINT gco_contacts CHECK (primary_contact <> secondary_contact)
);
CREATE UNIQUE INDEX gco_one_current ON governance.component_ownerships (ownership_id) WHERE superseded_at IS NULL;
CREATE UNIQUE INDEX gco_component_current ON governance.component_ownerships (component_artifact) WHERE superseded_at IS NULL;
CREATE OR REPLACE FUNCTION governance.dr_ownership_forward() RETURNS trigger LANGUAGE plpgsql SET search_path = governance, pg_catalog, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.superseded_at IS NOT NULL OR (to_jsonb(NEW) - 'superseded_at') IS DISTINCT FROM (to_jsonb(OLD) - 'superseded_at') THEN
    RAISE EXCEPTION 'ownership record rejected (state): an ownership version is immutable; only its supersession is set, once' USING ERRCODE = '2F002';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER gco_forward BEFORE UPDATE OR DELETE ON governance.component_ownerships FOR EACH ROW EXECUTE FUNCTION governance.dr_ownership_forward();

/* THE TRANSFER (ES-11-005): the proposed ownership, the nine-item checklist (each with a reference), the open exceptions on the component
   (read from the §0 links `excepts`, snapshotted), the digest; proposed → accepted (the RECEIVING accountable owner) → ratified (signed) |
   rejected | withdrawn. */
CREATE TABLE governance.component_transfers (
  transfer_id        uuid PRIMARY KEY,
  scope              text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  ownership_id       uuid NOT NULL,
  component_artifact uuid NOT NULL,
  component_key      text NOT NULL,
  from_version       int,
  from_accountable   uuid,
  proposal           jsonb NOT NULL CHECK (jsonb_typeof(proposal) = 'object'),
  checklist          jsonb NOT NULL CHECK (jsonb_typeof(checklist) = 'object'),
  open_exceptions    jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(open_exceptions) = 'array'),
  digest             text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  state              text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'accepted', 'ratified', 'rejected', 'withdrawn')),
  proposed_by        uuid NOT NULL,
  proposed_at        timestamptz NOT NULL DEFAULT clock_timestamp(),
  accepted_by        uuid,
  accepted_at        timestamptz,
  decided_by         uuid,
  decided_at         timestamptz,
  decision_reason    text,
  signature_id       uuid,
  correlation_id     uuid NOT NULL,
  CONSTRAINT gct_accepted CHECK (state NOT IN ('accepted', 'ratified') OR (accepted_by IS NOT NULL AND accepted_at IS NOT NULL)),
  CONSTRAINT gct_decided CHECK (state NOT IN ('ratified', 'rejected', 'withdrawn') OR (decided_by IS NOT NULL AND decided_at IS NOT NULL AND decision_reason IS NOT NULL)),
  CONSTRAINT gct_signed CHECK (state <> 'ratified' OR signature_id IS NOT NULL),
  CONSTRAINT gct_sod CHECK (decided_by IS NULL OR state = 'withdrawn' OR (decided_by <> proposed_by AND decided_by IS DISTINCT FROM accepted_by AND decided_by IS DISTINCT FROM from_accountable))
);
CREATE UNIQUE INDEX gct_one_live ON governance.component_transfers (component_artifact) WHERE state IN ('proposed', 'accepted');
CREATE OR REPLACE FUNCTION governance.dr_transfer_forward() RETURNS trigger LANGUAGE plpgsql SET search_path = governance, pg_catalog, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.state IN ('ratified', 'rejected', 'withdrawn')
     OR (to_jsonb(NEW) - ARRAY['state', 'accepted_by', 'accepted_at', 'decided_by', 'decided_at', 'decision_reason', 'signature_id'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['state', 'accepted_by', 'accepted_at', 'decided_by', 'decided_at', 'decision_reason', 'signature_id']) THEN
    RAISE EXCEPTION 'ownership record rejected (state): transfer % is % — its proposal is immutable', OLD.transfer_id, OLD.state USING ERRCODE = '2F002';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER gct_forward BEFORE UPDATE OR DELETE ON governance.component_transfers FOR EACH ROW EXECUTE FUNCTION governance.dr_transfer_forward();

/* A text[] from a jsonb array of strings (NULL when the value is not one): trimmed, distinct, sorted. */
CREATE OR REPLACE FUNCTION governance.dr_texts(p jsonb) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN p IS NULL OR jsonb_typeof(p) = 'null' THEN '{}'::text[]
              WHEN jsonb_typeof(p) <> 'array' OR EXISTS (SELECT 1 FROM jsonb_array_elements(p) x WHERE jsonb_typeof(x) <> 'string' OR length(btrim(x #>> '{}')) = 0) THEN NULL
              ELSE (SELECT coalesce(array_agg(DISTINCT btrim(x) ORDER BY btrim(x)), '{}') FROM jsonb_array_elements_text(p) x) END
$$;

/* PROPOSE A TRANSFER (governance.ownership.component.propose): the conformance steward, a product or operations authority, or the CURRENT
   accountable owner proposes who owns a component next. Checked: the component (a current §0 artifact of kind component | deployable_unit);
   the expected version; one live transfer per component; the team, the accountable owner and two DIFFERENT contacts (active PLATFORM
   humans); the operator role; the owned contracts (1+; ONE owner per contract — ES-11-002); DISTINGUISHABILITY where a deployable unit is
   shared (ES-04-002: no shared state store, contract or policy decision; its own telemetry namespace and failure domain); the CHECKLIST — all
   nine items, each with a reference (ES-11-005); the component's open exceptions snapshotted from the §0 links. */
CREATE OR REPLACE FUNCTION governance.dr_propose_transfer(p_transfer uuid, p_component uuid, p_expected int, p_proposal jsonb, p_checklist jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, identity, public, pg_catalog, pg_temp AS $$
DECLARE art governance.artifacts%ROWTYPE; cur governance.component_ownerships%ROWTYPE; o record; v_contracts text[]; v_stores text[]; v_policies text[]; v_units text[];
        v_acc uuid; v_primary uuid; v_secondary uuid; v_missing text[]; v_bad text[]; v_exc jsonb; v_prop jsonb; t governance.component_transfers%ROWTYPE; v_overlap text;
BEGIN
  PERFORM governance.assert_platform('governance.ownership.component.propose', p_actor, 'ownership record');
  SELECT * INTO art FROM governance.artifacts a WHERE a.artifact_id = p_component AND a.superseded_at IS NULL AND a.scope = 'PLATFORM';
  IF NOT FOUND OR art.kind NOT IN ('component', 'deployable_unit') THEN
    RAISE EXCEPTION 'ownership record rejected (unknown_component): % is not a current component or deployable unit of the registry', p_component USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.component:' || p_component::text, 0));
  SELECT * INTO cur FROM governance.component_ownerships x WHERE x.component_artifact = p_component AND x.superseded_at IS NULL;
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['conformance_steward', 'product_authority', 'operations_authority']) AND cur.accountable_principal_id IS DISTINCT FROM p_actor THEN
    RAISE EXCEPTION 'ownership record rejected (authority): a transfer is proposed by the conformance steward, a product or operations authority, or the current accountable owner' USING ERRCODE = '42501';
  END IF;
  IF p_expected IS DISTINCT FROM coalesce(cur.version, 0) THEN RAISE EXCEPTION 'ownership record rejected (stale): % is at ownership version %, the transfer names %', art.external_key, coalesce(cur.version, 0), coalesce(p_expected::text, 'none') USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM governance.component_transfers x WHERE x.component_artifact = p_component AND x.state IN ('proposed', 'accepted')) THEN
    RAISE EXCEPTION 'ownership record rejected (state): a transfer of % is already in flight', art.external_key USING ERRCODE = '22023';
  END IF;
  IF p_proposal IS NULL OR jsonb_typeof(p_proposal) <> 'object' THEN RAISE EXCEPTION 'ownership record rejected (proposal): the proposal is an object' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_proposal ->> 'owningTeam', ''))) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'ownership record rejected (team): exactly one accountable owning team is named (ES-04-001)' USING ERRCODE = '22023'; END IF;
  BEGIN v_acc := (p_proposal ->> 'accountable')::uuid; v_primary := (p_proposal ->> 'primaryContact')::uuid; v_secondary := (p_proposal ->> 'secondaryContact')::uuid;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'ownership record rejected (contacts): the accountable owner and the contacts are principal ids' USING ERRCODE = '22023'; END;
  IF v_acc IS NULL OR NOT governance.dr_platform_human(v_acc) THEN RAISE EXCEPTION 'ownership record rejected (unknown_owner): the accountable owner is an active PLATFORM human' USING ERRCODE = '22023'; END IF;
  IF v_primary IS NULL OR v_secondary IS NULL OR NOT governance.dr_platform_human(v_primary) OR NOT governance.dr_platform_human(v_secondary) THEN
    RAISE EXCEPTION 'ownership record rejected (contacts): the primary and secondary operational contacts are active PLATFORM humans (ES-11-001)' USING ERRCODE = '22023';
  END IF;
  IF v_primary = v_secondary THEN RAISE EXCEPTION 'ownership record rejected (contacts): the primary and the secondary contact are two different people (ES-11-001)' USING ERRCODE = '22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM identity.roles r WHERE r.code = coalesce(p_proposal ->> 'operatorRole', 'operations_authority')) THEN RAISE EXCEPTION 'ownership record rejected (role): the operator role names no role' USING ERRCODE = '22023'; END IF;
  v_contracts := governance.dr_texts(p_proposal -> 'ownedContracts'); v_stores := governance.dr_texts(p_proposal -> 'stateStores');
  v_policies := governance.dr_texts(p_proposal -> 'policyDecisions'); v_units := governance.dr_texts(p_proposal -> 'deployableUnits');
  IF v_contracts IS NULL OR cardinality(v_contracts) = 0 THEN RAISE EXCEPTION 'ownership record rejected (contracts): the owned contracts are listed (1+) — a service exposes only contracts its owned behaviour requires (ES-11-002)' USING ERRCODE = '22023'; END IF;
  IF v_stores IS NULL OR v_policies IS NULL OR v_units IS NULL OR cardinality(v_units) = 0 THEN
    RAISE EXCEPTION 'ownership record rejected (proposal): stateStores and policyDecisions are lists, deployableUnits a list of 1+' USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_proposal ->> 'telemetryNamespace', ''))) NOT BETWEEN 2 AND 120 OR length(btrim(coalesce(p_proposal ->> 'failureDomain', ''))) NOT BETWEEN 2 AND 120 THEN
    RAISE EXCEPTION 'ownership record rejected (proposal): the telemetry namespace and the failure domain are named' USING ERRCODE = '22023';
  END IF;
  -- one owner per contract (ES-11-002)
  SELECT string_agg(format('%s (owned by %s)', c, o2.component_key), ', ') INTO v_overlap
    FROM governance.component_ownerships o2, unnest(o2.owned_contracts) c
   WHERE o2.superseded_at IS NULL AND o2.component_artifact <> p_component AND c = ANY (v_contracts);
  IF v_overlap IS NOT NULL THEN RAISE EXCEPTION 'ownership record rejected (duplicate): a contract has one owner — %', v_overlap USING ERRCODE = '23505'; END IF;
  -- distinguishability where a deployable unit is shared (ES-04-002)
  FOR o IN SELECT * FROM governance.component_ownerships o2 WHERE o2.superseded_at IS NULL AND o2.component_artifact <> p_component AND o2.deployable_units && v_units LOOP
    v_bad := '{}';
    IF o.state_stores && v_stores THEN v_bad := v_bad || ('state stores ' || array_to_string(ARRAY(SELECT unnest(o.state_stores) INTERSECT SELECT unnest(v_stores)), ', ')); END IF;
    IF o.policy_decisions && v_policies THEN v_bad := v_bad || ('policy decisions ' || array_to_string(ARRAY(SELECT unnest(o.policy_decisions) INTERSECT SELECT unnest(v_policies)), ', ')); END IF;
    IF o.telemetry_namespace = btrim(p_proposal ->> 'telemetryNamespace') THEN v_bad := v_bad || ('the telemetry namespace ' || o.telemetry_namespace); END IF;
    IF o.failure_domain = btrim(p_proposal ->> 'failureDomain') THEN v_bad := v_bad || ('the failure domain ' || o.failure_domain); END IF;
    IF cardinality(v_bad) > 0 THEN
      RAISE EXCEPTION 'ownership record rejected (distinguishability): % shares deployable unit(s) % with %, so state, contracts, policy decisions, telemetry and failure isolation stay distinguishable — shared: %',
        art.external_key, array_to_string(ARRAY(SELECT unnest(o.deployable_units) INTERSECT SELECT unnest(v_units)), ', '), o.component_key, array_to_string(v_bad, '; ') USING ERRCODE = '22023';
    END IF;
  END LOOP;
  -- the checklist (ES-11-005)
  IF p_checklist IS NULL OR jsonb_typeof(p_checklist) <> 'object' THEN RAISE EXCEPTION 'ownership record rejected (checklist): the checklist is an object of the nine items' USING ERRCODE = '22023'; END IF;
  SELECT coalesce(array_agg(i ORDER BY i), '{}') INTO v_missing FROM unnest(governance.dr_transfer_items()) i
   WHERE jsonb_typeof(p_checklist -> i) <> 'object' OR length(btrim(coalesce(p_checklist -> i ->> 'ref', ''))) < 4;
  IF cardinality(v_missing) > 0 THEN
    RAISE EXCEPTION 'ownership record rejected (checklist): a transfer includes code, state, contracts, dashboards, alerts, runbooks, risks, exceptions and unresolved incidents, each with a reference — missing: %', array_to_string(v_missing, ', ') USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_checklist) k WHERE NOT (k = ANY (governance.dr_transfer_items()))) THEN
    RAISE EXCEPTION 'ownership record rejected (checklist): the checklist holds the nine items only' USING ERRCODE = '22023';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('exception', l.from_artifact, 'key', a.external_key, 'title', a.title, 'lifecycle', a.lifecycle) ORDER BY a.external_key), '[]'::jsonb) INTO v_exc
    FROM governance.links_live l LEFT JOIN governance.artifacts a ON a.artifact_id = l.from_artifact AND a.superseded_at IS NULL
   WHERE l.to_artifact = p_component AND l.relation = 'excepts';
  v_prop := jsonb_build_object('owning_team', btrim(p_proposal ->> 'owningTeam'), 'accountable', v_acc, 'primary_contact', v_primary, 'secondary_contact', v_secondary,
                               'operator_role', coalesce(p_proposal ->> 'operatorRole', 'operations_authority'), 'owned_contracts', to_jsonb(v_contracts), 'state_stores', to_jsonb(v_stores),
                               'policy_decisions', to_jsonb(v_policies), 'telemetry_namespace', btrim(p_proposal ->> 'telemetryNamespace'), 'failure_domain', btrim(p_proposal ->> 'failureDomain'),
                               'deployable_units', to_jsonb(v_units));
  INSERT INTO governance.component_transfers (transfer_id, ownership_id, component_artifact, component_key, from_version, from_accountable, proposal, checklist, open_exceptions, digest, proposed_by, correlation_id)
  VALUES (p_transfer, coalesce(cur.ownership_id, gen_random_uuid()), p_component, art.external_key, cur.version, cur.accountable_principal_id, v_prop, p_checklist, v_exc,
          governance.digest(jsonb_build_object('transfer_id', p_transfer, 'component', p_component, 'from_version', cur.version, 'proposal', v_prop, 'checklist', p_checklist, 'open_exceptions', v_exc)),
          p_actor, p_correlation) RETURNING * INTO t;
  PERFORM governance.ledger(NULL, NULL, 'component_transfer', p_transfer, NULL, 'transfer.proposed', p_actor,
                            jsonb_build_object('component', p_component, 'component_key', art.external_key, 'from_version', cur.version, 'to', v_acc, 'digest', t.digest), p_correlation);
  RETURN to_jsonb(t) - 'scope' - 'correlation_id';
END $$;
REVOKE ALL ON FUNCTION governance.dr_propose_transfer(uuid, uuid, int, jsonb, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_propose_transfer(uuid, uuid, int, jsonb, jsonb, uuid, uuid) TO eye_commit;

/* ACCEPT (governance.ownership.component.accept): the RECEIVING accountable owner accepts what is handed over, on the digest. */
CREATE OR REPLACE FUNCTION governance.dr_accept_transfer(p_transfer uuid, p_digest text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE t governance.component_transfers%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.ownership.component.accept', p_actor, 'ownership record');
  SELECT * INTO t FROM governance.component_transfers x WHERE x.transfer_id = p_transfer FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ownership record rejected (unknown_transfer): % is not a transfer', p_transfer USING ERRCODE = '22023'; END IF;
  IF onboarding.principal_kind(p_actor) IS DISTINCT FROM 'human' THEN RAISE EXCEPTION 'ownership record rejected (actor): ownership is accepted by a named human' USING ERRCODE = '42501'; END IF;
  IF (t.proposal ->> 'accountable')::uuid IS DISTINCT FROM p_actor THEN RAISE EXCEPTION 'ownership record rejected (ownership): the transfer of % is accepted by its receiving accountable owner only', t.component_key USING ERRCODE = '42501'; END IF;
  IF t.state <> 'proposed' THEN RAISE EXCEPTION 'ownership record rejected (state): transfer % is %', p_transfer, t.state USING ERRCODE = '22023'; END IF;
  IF p_digest IS DISTINCT FROM t.digest THEN RAISE EXCEPTION 'ownership record rejected (stale): the digest accepted is not the transfer''s' USING ERRCODE = '22023'; END IF;
  UPDATE governance.component_transfers SET state = 'accepted', accepted_by = p_actor, accepted_at = clock_timestamp() WHERE transfer_id = p_transfer RETURNING * INTO t;
  PERFORM governance.ledger(NULL, NULL, 'component_transfer', p_transfer, NULL, 'transfer.accepted', p_actor, jsonb_build_object('digest', t.digest), p_correlation);
  RETURN to_jsonb(t) - 'scope' - 'correlation_id';
END $$;
REVOKE ALL ON FUNCTION governance.dr_accept_transfer(uuid, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_accept_transfer(uuid, text, uuid, uuid) TO eye_commit;

/* RECORD A PLATFORM SIGNATURE (internal to this part's signing ports — the §0 sibling of executive.record_signature): the acting principal's
   Ed25519 signature by key reference over a subject digest, kind ownership_transfer only here; one per signer per subject version. The
   caller's bound action is asserted; the signer's PLATFORM role recorded. */
CREATE OR REPLACE FUNCTION governance.dr_record_platform_signature(p_signature uuid, p_action text, p_kind text, p_subject uuid, p_version int, p_digest text, p_key_id text, p_signature_text text,
                                                                   p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, identity, public, pg_catalog, pg_temp AS $$
DECLARE v_role text;
BEGIN
  PERFORM governance.assert_platform(p_action, p_actor, 'ownership record');
  IF p_kind IS DISTINCT FROM 'ownership_transfer' OR p_action IS DISTINCT FROM 'governance.ownership.component.ratify' THEN
    RAISE EXCEPTION 'ownership record rejected (signature): this port signs ownership transfers under their ratification only' USING ERRCODE = '22023';
  END IF;
  SELECT b.role_code INTO v_role FROM identity.role_bindings b WHERE b.principal_id = p_actor AND b.scope = 'PLATFORM' AND b.revoked_at IS NULL
     AND b.role_code IN ('product_authority', 'operations_authority') ORDER BY b.role_code LIMIT 1;
  IF v_role IS NULL THEN RAISE EXCEPTION 'ownership record rejected (authority): an ownership transfer is signed by a product or operations authority' USING ERRCODE = '42501'; END IF;
  IF EXISTS (SELECT 1 FROM governance.signatures s WHERE s.subject_kind = p_kind AND s.subject_id = p_subject AND s.subject_version = p_version AND s.signer = p_actor) THEN
    RAISE EXCEPTION 'ownership record rejected (duplicate): % % is already signed by this principal', p_kind, p_subject USING ERRCODE = '22023';
  END IF;
  INSERT INTO governance.signatures (signature_id, scope, subject_kind, subject_id, subject_version, subject_digest, signer, signer_role, key_id, algorithm, signature, bound_action, correlation_id)
  VALUES (p_signature, 'PLATFORM', p_kind, p_subject, p_version, p_digest, p_actor, v_role, p_key_id, 'ed25519', p_signature_text, p_action, p_correlation);
  RETURN jsonb_build_object('signature_id', p_signature, 'subject_kind', p_kind, 'subject_id', p_subject, 'subject_version', p_version, 'subject_digest', p_digest, 'signer', p_actor,
                            'signer_role', v_role, 'key_id', p_key_id, 'signed_at', clock_timestamp());
END $$;
REVOKE ALL ON FUNCTION governance.dr_record_platform_signature(uuid, text, text, uuid, int, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_record_platform_signature(uuid, text, text, uuid, int, text, text, text, uuid, uuid) TO eye_commit;

/* DECIDE (governance.ownership.component.ratify; human-gated): RATIFY — signed first (the port verifies the signature: the actor's, over
   the transfer's digest) — or REJECT. The approver test: a product or operations authority, never the proposer, never either party of the
   transfer (the outgoing or the receiving accountable owner). Ratification makes the next ownership version (the prior superseded),
   registers it (§0 artifact kind role, key OWNER:<component>), links component —owned_by→ ownership (the prior link retired) and resolves
   the component's ownership gaps. */
CREATE OR REPLACE FUNCTION governance.dr_decide_transfer(p_transfer uuid, p_digest text, p_decision text, p_reason text, p_signature uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE t governance.component_transfers%ROWTYPE; cur governance.component_ownerships%ROWTYPE; o governance.component_ownerships%ROWTYPE; art governance.artifacts%ROWTYPE;
        s governance.signatures%ROWTYPE; v_now timestamptz := clock_timestamp(); g record; v_resolved jsonb := '[]'::jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.ownership.component.ratify', p_actor, 'ownership record');
  SELECT * INTO t FROM governance.component_transfers x WHERE x.transfer_id = p_transfer FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ownership record rejected (unknown_transfer): % is not a transfer', p_transfer USING ERRCODE = '22023'; END IF;
  PERFORM governance.assert_approver('ownership record', p_actor, NULL, NULL, ARRAY['product_authority', 'operations_authority'], t.proposed_by,
                                     array_remove(ARRAY[t.from_accountable, (t.proposal ->> 'accountable')::uuid], NULL), 'ratifying an ownership transfer');
  IF p_decision IS NULL OR p_decision NOT IN ('ratify', 'reject') THEN RAISE EXCEPTION 'ownership record rejected (decision): ratify or reject' USING ERRCODE = '22023'; END IF;
  IF t.state NOT IN ('proposed', 'accepted') OR (p_decision = 'ratify' AND t.state <> 'accepted') THEN
    RAISE EXCEPTION 'ownership record rejected (state): transfer % is %', p_transfer, t.state || CASE WHEN t.state = 'proposed' THEN ' — the receiving owner accepts it before it is ratified' ELSE '' END USING ERRCODE = '22023';
  END IF;
  IF p_digest IS DISTINCT FROM t.digest THEN RAISE EXCEPTION 'ownership record rejected (stale): the digest decided is not the transfer''s' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'ownership record rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'reject' THEN
    UPDATE governance.component_transfers SET state = 'rejected', decided_by = p_actor, decided_at = v_now, decision_reason = btrim(p_reason) WHERE transfer_id = p_transfer RETURNING * INTO t;
    PERFORM governance.ledger(NULL, NULL, 'component_transfer', p_transfer, NULL, 'transfer.rejected', p_actor, jsonb_build_object('reason', btrim(p_reason)), p_correlation);
    RETURN to_jsonb(t) - 'scope' - 'correlation_id';
  END IF;
  SELECT * INTO s FROM governance.signatures x WHERE x.signature_id = p_signature;
  IF NOT FOUND OR s.subject_kind <> 'ownership_transfer' OR s.subject_id <> p_transfer OR s.subject_digest <> t.digest OR s.signer <> p_actor THEN
    RAISE EXCEPTION 'ownership record rejected (signature): a ratification is signed by the ratifying authority over the transfer''s digest first' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO art FROM governance.artifacts a WHERE a.artifact_id = t.component_artifact AND a.superseded_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'ownership record rejected (unknown_component): the component is no longer current in the registry' USING ERRCODE = '22023'; END IF;
  SELECT * INTO cur FROM governance.component_ownerships x WHERE x.component_artifact = t.component_artifact AND x.superseded_at IS NULL FOR UPDATE;
  IF coalesce(cur.version, 0) IS DISTINCT FROM coalesce(t.from_version, 0) THEN RAISE EXCEPTION 'ownership record rejected (stale): the ownership moved since the transfer was proposed' USING ERRCODE = '22023'; END IF;
  IF cur.ownership_id IS NOT NULL THEN UPDATE governance.component_ownerships SET superseded_at = v_now WHERE ownership_id = cur.ownership_id AND version = cur.version; END IF;
  INSERT INTO governance.component_ownerships (ownership_id, version, component_artifact, component_key, component_kind, owning_team, accountable_principal_id, primary_contact, secondary_contact,
                                               operator_role, owned_contracts, state_stores, policy_decisions, telemetry_namespace, failure_domain, deployable_units, transfer_id, signature_id, digest,
                                               ratified_by, correlation_id)
  VALUES (t.ownership_id, coalesce(cur.version, 0) + 1, t.component_artifact, t.component_key, art.kind, t.proposal ->> 'owning_team', (t.proposal ->> 'accountable')::uuid,
          (t.proposal ->> 'primary_contact')::uuid, (t.proposal ->> 'secondary_contact')::uuid, t.proposal ->> 'operator_role',
          ARRAY(SELECT jsonb_array_elements_text(t.proposal -> 'owned_contracts')), ARRAY(SELECT jsonb_array_elements_text(t.proposal -> 'state_stores')),
          ARRAY(SELECT jsonb_array_elements_text(t.proposal -> 'policy_decisions')), t.proposal ->> 'telemetry_namespace', t.proposal ->> 'failure_domain',
          ARRAY(SELECT jsonb_array_elements_text(t.proposal -> 'deployable_units')), t.transfer_id, s.signature_id, t.digest, p_actor, p_correlation) RETURNING * INTO o;
  UPDATE governance.component_transfers SET state = 'ratified', decided_by = p_actor, decided_at = v_now, decision_reason = btrim(p_reason), signature_id = s.signature_id WHERE transfer_id = p_transfer RETURNING * INTO t;
  PERFORM governance.dr_register(o.ownership_id, 'PLATFORM', NULL, NULL, 'role', 'OWNER:' || o.component_key, 'Ownership — ' || art.title || ' (' || o.owning_team || ')', o.accountable_principal_id, NULL,
                                 'component_ownership', 'active', jsonb_build_object('ownership_version', o.version, 'owning_team', o.owning_team, 'owned_contracts', to_jsonb(o.owned_contracts),
                                                                                     'deployable_units', to_jsonb(o.deployable_units), 'operator_role', o.operator_role), o.digest, p_actor, p_correlation);
  PERFORM governance.dr_retire_links(t.component_artifact, 'owned_by', p_actor, p_correlation);
  PERFORM governance.dr_link('PLATFORM', NULL, NULL, t.component_artifact, o.ownership_id, 'owned_by', jsonb_build_object('version', o.version, 'transfer_id', t.transfer_id), p_actor, p_correlation);
  FOR g IN SELECT x.gap_id FROM governance.ownership_gaps x WHERE x.subject_id = t.component_artifact AND x.state <> 'resolved' LOOP
    PERFORM governance.dr_resolve_gap(g.gap_id, 'a ratified ownership transfer named the owner and the contacts', p_actor, p_correlation);
    v_resolved := v_resolved || to_jsonb(g.gap_id);
  END LOOP;
  PERFORM governance.ledger(NULL, NULL, 'component_transfer', p_transfer, NULL, 'transfer.ratified', p_actor,
                            jsonb_build_object('ownership_id', o.ownership_id, 'version', o.version, 'signature_id', s.signature_id, 'digest', t.digest, 'gaps_resolved', v_resolved), p_correlation);
  RETURN (to_jsonb(t) - 'scope' - 'correlation_id') || jsonb_build_object('ownership', to_jsonb(o) - 'scope' - 'correlation_id', 'gaps_resolved', v_resolved);
END $$;
REVOKE ALL ON FUNCTION governance.dr_decide_transfer(uuid, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_decide_transfer(uuid, text, text, text, uuid, uuid, uuid) TO eye_commit;

/* WITHDRAW (governance.ownership.component.withdraw): the proposer withdraws a transfer in flight. */
CREATE OR REPLACE FUNCTION governance.dr_withdraw_transfer(p_transfer uuid, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE t governance.component_transfers%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.ownership.component.withdraw', p_actor, 'ownership record');
  SELECT * INTO t FROM governance.component_transfers x WHERE x.transfer_id = p_transfer FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ownership record rejected (unknown_transfer): % is not a transfer', p_transfer USING ERRCODE = '22023'; END IF;
  IF t.proposed_by <> p_actor THEN RAISE EXCEPTION 'ownership record rejected (authority): a transfer is withdrawn by its proposer' USING ERRCODE = '42501'; END IF;
  IF t.state NOT IN ('proposed', 'accepted') THEN RAISE EXCEPTION 'ownership record rejected (state): transfer % is %', p_transfer, t.state USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'ownership record rejected (reason): a withdrawal states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  UPDATE governance.component_transfers SET state = 'withdrawn', decided_by = p_actor, decided_at = clock_timestamp(), decision_reason = btrim(p_reason) WHERE transfer_id = p_transfer RETURNING * INTO t;
  PERFORM governance.ledger(NULL, NULL, 'component_transfer', p_transfer, NULL, 'transfer.withdrawn', p_actor, jsonb_build_object('reason', btrim(p_reason)), p_correlation);
  RETURN to_jsonb(t) - 'scope' - 'correlation_id';
END $$;
REVOKE ALL ON FUNCTION governance.dr_withdraw_transfer(uuid, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_withdraw_transfer(uuid, text, uuid, uuid) TO eye_commit;

/* RECONCILE THE COMPONENTS (governance.ownership.component.reconcile; the conformance steward): every current component / deployable unit of
   the registry — no ratified ownership → a PLATFORM gap no_owner (held); a ratified ownership whose accountable owner or a contact is no
   longer an active PLATFORM human → contact_lost (held); cleared conditions resolve. */
CREATE OR REPLACE FUNCTION governance.dr_reconcile_components(p_run uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE a record; o governance.component_ownerships%ROWTYPE; v_kind text; v_lost text[]; v_opened jsonb := '[]'::jsonb; v_resolved jsonb := '[]'::jsonb; g record; v_seen int := 0; v_r jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.ownership.component.reconcile', p_actor, 'ownership record');
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['conformance_steward']) THEN
    RAISE EXCEPTION 'ownership record rejected (authority): component ownership is reconciled by the conformance steward' USING ERRCODE = '42501';
  END IF;
  FOR a IN SELECT x.artifact_id, x.external_key, x.title, x.kind FROM governance.artifacts x WHERE x.scope = 'PLATFORM' AND x.superseded_at IS NULL AND x.kind IN ('component', 'deployable_unit')
             AND x.lifecycle IN ('proposed', 'active', 'deprecated') ORDER BY x.external_key LOOP
    v_seen := v_seen + 1;
    SELECT * INTO o FROM governance.component_ownerships x WHERE x.component_artifact = a.artifact_id AND x.superseded_at IS NULL;
    v_kind := NULL; v_lost := '{}';
    IF NOT FOUND THEN v_kind := 'no_owner';
    ELSE
      IF NOT governance.dr_platform_human(o.accountable_principal_id) THEN v_lost := v_lost || 'accountable owner'::text; END IF;
      IF NOT governance.dr_platform_human(o.primary_contact) THEN v_lost := v_lost || 'primary contact'::text; END IF;
      IF NOT governance.dr_platform_human(o.secondary_contact) THEN v_lost := v_lost || 'secondary contact'::text; END IF;
      IF cardinality(v_lost) > 0 THEN v_kind := 'contact_lost'; END IF;
    END IF;
    IF v_kind IS NOT NULL THEN
      v_r := governance.dr_open_gap(NULL, NULL, 'component', a.artifact_id, a.external_key || ' ' || a.title, v_kind,
                                    jsonb_build_object('reason', CASE v_kind WHEN 'no_owner' THEN 'no ratified ownership record names an accountable owning team (ES-04-001, ES-11-001)'
                                                                                   ELSE 'no longer an active PLATFORM human: ' || array_to_string(v_lost, ', ') END,
                                                       'ownership_version', o.version),
                                    'the conformance steward, then the operations authority', true, NULL, 'C2', p_actor, p_correlation);
      IF NOT (v_r ->> 'existing')::boolean THEN v_opened := v_opened || jsonb_build_object('gap_id', v_r ->> 'gap_id', 'component', a.external_key, 'gap_kind', v_kind); END IF;
    END IF;
    FOR g IN SELECT x.gap_id, x.gap_kind FROM governance.ownership_gaps x WHERE x.subject_id = a.artifact_id AND x.state <> 'resolved' AND x.gap_kind IS DISTINCT FROM v_kind LOOP
      PERFORM governance.dr_resolve_gap(g.gap_id, 'the reconciliation no longer finds ' || g.gap_kind, p_actor, p_correlation);
      v_resolved := v_resolved || jsonb_build_object('gap_id', g.gap_id, 'component', a.external_key, 'gap_kind', g.gap_kind);
    END LOOP;
  END LOOP;
  PERFORM governance.ledger(NULL, NULL, 'ownership_run', p_run, NULL, 'components.reconciled', p_actor, jsonb_build_object('seen', v_seen, 'opened', v_opened, 'resolved', v_resolved), p_correlation);
  RETURN jsonb_build_object('run_id', p_run, 'seen', v_seen, 'opened', v_opened, 'resolved', v_resolved,
                            'open', (SELECT count(*) FROM governance.ownership_gaps x WHERE x.scope = 'PLATFORM' AND x.subject_kind = 'component' AND x.state IN ('open', 'escalated')));
END $$;
REVOKE ALL ON FUNCTION governance.dr_reconcile_components(uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_reconcile_components(uuid, uuid, uuid) TO eye_commit;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.6 STEWARDSHIP CASES (DOMAIN; DP-55-001/-002/-005, DAT-GV-07) — the durable queue of data adjudication
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
CREATE TABLE governance.stewardship_cases (
  case_id            uuid PRIMARY KEY,
  scope              text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id          uuid NOT NULL,
  domain_id          uuid NOT NULL,
  case_ref           text NOT NULL CHECK (case_ref ~ '^STW-[0-9]{4,}$'),
  kind               text NOT NULL CHECK (kind = ANY (governance.dr_case_kinds())),
  subject_kind       text NOT NULL CHECK (subject_kind IN ('catalog_asset', 'product', 'glossary_term')),
  subject_id         uuid NOT NULL,
  subject_label      text NOT NULL,
  title              text NOT NULL CHECK (length(btrim(title)) BETWEEN 4 AND 200),
  proposed_action    text NOT NULL CHECK (length(btrim(proposed_action)) BETWEEN 8 AND 2000),
  evidence           jsonb NOT NULL CHECK (jsonb_typeof(evidence) = 'array' AND jsonb_array_length(evidence) >= 1),
  consequence        text NOT NULL CHECK (consequence IN ('C0', 'C1', 'C2', 'C3', 'C4')),
  owner_principal_id uuid,                                              -- resolved at opening (and re-resolved by the sweep); NULL = the case lacks an owner
  reviewers_required int  NOT NULL CHECK (reviewers_required BETWEEN 1 AND 3),
  reviews            jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(reviews) = 'array'),
  state              text NOT NULL DEFAULT 'open' CHECK (state IN ('open', 'in_review', 'approved', 'rejected', 'expired', 'closed', 'withdrawn')),
  decision           text CHECK (decision IN ('approved', 'rejected')),
  decided_by         uuid,
  decided_at         timestamptz,
  conditions         jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(conditions) = 'array'),
  expires_at         timestamptz,
  first_due_at       timestamptz NOT NULL,
  due_at             timestamptz NOT NULL,
  escalation_level   int NOT NULL DEFAULT 0 CHECK (escalation_level >= 0),
  escalated_at       timestamptz,
  closed_by          uuid,
  closed_at          timestamptz,
  closure_note       text,
  closure_evidence   jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(closure_evidence) = 'array'),
  digest             text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  opened_by          uuid NOT NULL,
  opened_at          timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at         timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id     uuid NOT NULL,
  CONSTRAINT gsc_scope CHECK (observation.scope_ok(scope, tenant_id, domain_id)),
  CONSTRAINT gsc_ref_once UNIQUE (tenant_id, case_ref),
  CONSTRAINT gsc_decided CHECK ((decision IS NOT NULL) = (decided_by IS NOT NULL AND decided_at IS NOT NULL)),
  CONSTRAINT gsc_decision_state CHECK (state NOT IN ('approved', 'rejected', 'expired') OR decision IS NOT NULL),
  CONSTRAINT gsc_sod CHECK (decided_by IS NULL OR decided_by <> opened_by),
  CONSTRAINT gsc_exception_expiry CHECK (kind <> 'data_exception' OR decision IS DISTINCT FROM 'approved' OR expires_at IS NOT NULL),
  CONSTRAINT gsc_closed CHECK ((state = 'closed') = (closed_at IS NOT NULL AND closed_by IS NOT NULL))
);
CREATE INDEX gsc_queue ON governance.stewardship_cases (tenant_id, domain_id, state, due_at);
CREATE INDEX gsc_subject ON governance.stewardship_cases (subject_id, state);
CREATE OR REPLACE FUNCTION governance.dr_case_forward() RETURNS trigger LANGUAGE plpgsql SET search_path = governance, pg_catalog, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'stewardship case rejected (state): a stewardship case is never deleted' USING ERRCODE = '2F002'; END IF;
  IF OLD.state IN ('closed', 'withdrawn')
     OR (NEW.case_id, NEW.tenant_id, NEW.domain_id, NEW.case_ref, NEW.kind, NEW.subject_kind, NEW.subject_id, NEW.title, NEW.proposed_action, NEW.evidence, NEW.consequence, NEW.reviewers_required,
         NEW.first_due_at, NEW.digest, NEW.opened_by, NEW.opened_at)
        IS DISTINCT FROM (OLD.case_id, OLD.tenant_id, OLD.domain_id, OLD.case_ref, OLD.kind, OLD.subject_kind, OLD.subject_id, OLD.title, OLD.proposed_action, OLD.evidence, OLD.consequence,
                          OLD.reviewers_required, OLD.first_due_at, OLD.digest, OLD.opened_by, OLD.opened_at)
     OR (OLD.decision IS NOT NULL AND NEW.decision IS DISTINCT FROM OLD.decision) THEN
    RAISE EXCEPTION 'stewardship case rejected (state): case % is % — what was opened and what was decided are immutable', OLD.case_ref, OLD.state USING ERRCODE = '2F002';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER gsc_forward BEFORE UPDATE OR DELETE ON governance.stewardship_cases FOR EACH ROW EXECUTE FUNCTION governance.dr_case_forward();

/* The case's accountable owner as resolved NOW (internal): the subject's ratified data authority's owner (a product: its catalog asset's
   authority, else the product's own owner), a glossary term's owner — while an active human of the tenant; NULL otherwise. */
CREATE OR REPLACE FUNCTION governance.dr_case_owner(p_tenant uuid, p_domain uuid, p_subject_kind text, p_subject uuid) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, products, decision, pg_catalog, pg_temp AS $$
  SELECT CASE WHEN o IS NOT NULL AND decision.is_active_human(o, p_tenant) THEN o END FROM (SELECT CASE p_subject_kind
    WHEN 'catalog_asset' THEN (SELECT r.owner_principal_id FROM governance.data_authorities r WHERE r.authority_id = p_subject AND r.state = 'ratified')
    WHEN 'product' THEN coalesce((SELECT r.owner_principal_id FROM products.catalog_assets a JOIN governance.data_authorities r ON r.authority_id = a.asset_id AND r.state = 'ratified'
                                    WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.kind = 'product' AND a.ref = p_subject::text
                                      AND decision.is_active_human(r.owner_principal_id, p_tenant)),
                                 (SELECT p.owner_principal_id FROM products.products_current p WHERE p.product_id = p_subject AND p.tenant_id = p_tenant AND p.domain_id = p_domain))
    WHEN 'glossary_term' THEN (SELECT g.owner_principal_id FROM products.glossary_terms g WHERE g.term_id = p_subject AND g.tenant_id = p_tenant AND g.domain_id = p_domain)
  END AS o) q
$$;
REVOKE ALL ON FUNCTION governance.dr_case_owner(uuid, uuid, text, uuid) FROM PUBLIC;

/* The subject's artifacts a hold names (internal): the subject itself, and for a product its catalog asset (the stop of consumption reads
   both). */
CREATE OR REPLACE FUNCTION governance.dr_subject_artifacts(p_tenant uuid, p_domain uuid, p_subject_kind text, p_subject uuid) RETURNS uuid[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = products, pg_catalog, pg_temp AS $$
  SELECT ARRAY[p_subject] || CASE WHEN p_subject_kind = 'product' THEN coalesce(ARRAY(SELECT a.asset_id FROM products.catalog_assets a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain
                                                                                        AND a.kind = 'product' AND a.ref = p_subject::text), '{}') ELSE '{}'::uuid[] END
$$;
REVOKE ALL ON FUNCTION governance.dr_subject_artifacts(uuid, uuid, text, uuid) FROM PUBLIC;

/* Cancel the case's pending SLA timers (internal). */
CREATE OR REPLACE FUNCTION governance.dr_cancel_case_timers(p_case uuid) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = executive, pg_catalog, pg_temp AS $$
DECLARE n int;
BEGIN
  UPDATE executive.workflow_timers SET cancelled_at = clock_timestamp() WHERE owner_kind = 'stewardship_case' AND owner_id = p_case AND fired_at IS NULL AND cancelled_at IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;
REVOKE ALL ON FUNCTION governance.dr_cancel_case_timers(uuid) FROM PUBLIC;

/* Lift every hold a case opened on its subject and close its items (internal; a decision, a closure, a withdrawal). */
CREATE OR REPLACE FUNCTION governance.dr_case_release(c governance.stewardship_cases, p_reason_kinds text[], p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, pg_catalog, pg_temp AS $$
DECLARE v jsonb := '[]'::jsonb; s uuid; k text; g record;
BEGIN
  FOREACH s IN ARRAY governance.dr_subject_artifacts(c.tenant_id, c.domain_id, c.subject_kind, c.subject_id) LOOP
    FOREACH k IN ARRAY p_reason_kinds LOOP
      v := v || governance.dr_lift_holds(s, k, c.case_id, p_reason, p_actor);
    END LOOP;
  END LOOP;
  PERFORM executive.b33_close_items(c.tenant_id, c.domain_id, 'governance.ownership', 'stewardship_case', c.case_id, p_reason, p_actor, p_correlation);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dr_case_release(governance.stewardship_cases, text[], text, uuid, uuid) FROM PUBLIC;

/* The case as JSON. */
CREATE OR REPLACE FUNCTION governance.dr_case_json(c governance.stewardship_cases) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT (to_jsonb(c) - 'scope' - 'correlation_id') || jsonb_build_object('owner_name', governance.dr_name(c.owner_principal_id), 'opened_by_name', governance.dr_name(c.opened_by),
         'decided_by_name', governance.dr_name(c.decided_by), 'approvals', (SELECT count(*) FROM jsonb_array_elements(c.reviews) r WHERE r ->> 'outcome' = 'approve'),
         'sla', governance.dr_case_sla(c.consequence)::text)
$$;
GRANT EXECUTE ON FUNCTION governance.dr_case_json(governance.stewardship_cases) TO eye_app, eye_commit;

/* OPEN (governance.ownership.case.open): a case on one subject of the domain — its kind, title, proposed action, evidence (1+ {kind, ref}),
   consequence (C0..C4). The owner resolved now; the reviewers required and the SLA by consequence; the SLA timer scheduled. A case WITHOUT
   an accountable owner opens visibly: an ownership gap (case_unowned) and a hold on its subject (affected use constrained) — it cannot be
   approved until the owner resolves. */
CREATE OR REPLACE FUNCTION governance.dr_open_case(p_case uuid, p_tenant uuid, p_domain uuid, p_kind text, p_subject_kind text, p_subject uuid, p_title text, p_action text, p_evidence jsonb,
                                                   p_consequence text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, products, executive, public, pg_catalog, pg_temp AS $$
DECLARE c governance.stewardship_cases%ROWTYPE; v_label text; v_owner uuid; v_n int; v_now timestamptz := clock_timestamp(); v_gap jsonb; s uuid; v_body jsonb;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.case.open'], p_tenant, p_domain, p_actor, 'stewardship case');
  IF p_kind IS NULL OR NOT (p_kind = ANY (governance.dr_case_kinds())) THEN RAISE EXCEPTION 'stewardship case rejected (kind): identity, semantic, quality, access, classification, correction, lifecycle or data_exception' USING ERRCODE = '22023'; END IF;
  IF p_consequence IS NULL OR p_consequence NOT IN ('C0', 'C1', 'C2', 'C3', 'C4') THEN RAISE EXCEPTION 'stewardship case rejected (consequence): C0..C4' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_title, ''))) NOT BETWEEN 4 AND 200 THEN RAISE EXCEPTION 'stewardship case rejected (title): 4–200 characters' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_action, ''))) NOT BETWEEN 8 AND 2000 THEN RAISE EXCEPTION 'stewardship case rejected (action): the proposed action is stated (8–2000 characters)' USING ERRCODE = '22023'; END IF;
  IF p_evidence IS NULL OR jsonb_typeof(p_evidence) <> 'array' OR jsonb_array_length(p_evidence) = 0
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_evidence) e WHERE jsonb_typeof(e) <> 'object' OR length(btrim(coalesce(e ->> 'kind', ''))) < 2 OR length(btrim(coalesce(e ->> 'ref', ''))) < 2) THEN
    RAISE EXCEPTION 'stewardship case rejected (evidence): a case carries its evidence — 1+ items of {kind, ref}' USING ERRCODE = '22023';
  END IF;
  v_label := CASE p_subject_kind
    WHEN 'catalog_asset' THEN (SELECT a.kind || ' ' || a.title || ' (' || a.ref || ')' FROM products.catalog_assets a WHERE a.asset_id = p_subject AND a.tenant_id = p_tenant AND a.domain_id = p_domain)
    WHEN 'product' THEN (SELECT 'product ' || p.title || ' (' || p.product_key || ')' FROM products.products_current p WHERE p.product_id = p_subject AND p.tenant_id = p_tenant AND p.domain_id = p_domain)
    WHEN 'glossary_term' THEN (SELECT 'term ' || g.term FROM products.glossary_terms g WHERE g.term_id = p_subject AND g.tenant_id = p_tenant AND g.domain_id = p_domain) END;
  IF v_label IS NULL THEN RAISE EXCEPTION 'stewardship case rejected (unknown_subject): % % is not a catalog asset, product or glossary term of this domain', coalesce(p_subject_kind, 'subject'), p_subject USING ERRCODE = '22023'; END IF;
  v_owner := governance.dr_case_owner(p_tenant, p_domain, p_subject_kind, p_subject);
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.case_ref:' || p_tenant::text, 0));
  SELECT count(*) INTO v_n FROM governance.stewardship_cases x WHERE x.tenant_id = p_tenant;
  v_body := jsonb_build_object('kind', p_kind, 'subject', jsonb_build_object('kind', p_subject_kind, 'id', p_subject), 'title', btrim(p_title), 'action', btrim(p_action), 'evidence', p_evidence, 'consequence', p_consequence);
  INSERT INTO governance.stewardship_cases (case_id, tenant_id, domain_id, case_ref, kind, subject_kind, subject_id, subject_label, title, proposed_action, evidence, consequence, owner_principal_id,
                                            reviewers_required, first_due_at, due_at, digest, opened_by, correlation_id)
  VALUES (p_case, p_tenant, p_domain, 'STW-' || lpad((v_n + 1)::text, 4, '0'), p_kind, p_subject_kind, p_subject, v_label, btrim(p_title), btrim(p_action), p_evidence, p_consequence, v_owner,
          governance.dr_reviewers_required(p_consequence), v_now + governance.dr_case_sla(p_consequence), v_now + governance.dr_case_sla(p_consequence), governance.digest(v_body), p_actor, p_correlation)
  RETURNING * INTO c;
  PERFORM executive._schedule_timer(gen_random_uuid(), p_tenant, p_domain, 'stewardship_case', p_case, 'stewardship.sla', c.due_at,
                                    jsonb_build_object('case', p_case, 'case_ref', c.case_ref, 'consequence', p_consequence, 'level', 0), p_actor, p_correlation);
  PERFORM governance.dr_register(p_case, 'DOMAIN', p_tenant, p_domain, 'stewardship_case', c.case_ref, c.case_ref || ' — ' || c.title, v_owner, NULL, 'stewardship_case', 'active',
                                 jsonb_build_object('kind', p_kind, 'consequence', p_consequence, 'subject_kind', p_subject_kind, 'subject_id', p_subject), c.digest, p_actor, p_correlation);
  FOREACH s IN ARRAY governance.dr_subject_artifacts(p_tenant, p_domain, p_subject_kind, p_subject) LOOP
    IF EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.artifact_id = s AND a.superseded_at IS NULL) THEN
      PERFORM governance.dr_link('DOMAIN', p_tenant, p_domain, p_case, s, 'governs', jsonb_build_object('case_kind', p_kind), p_actor, p_correlation);
    END IF;
  END LOOP;
  PERFORM governance.ledger(p_tenant, p_domain, 'stewardship_case', p_case, NULL, 'case.opened', p_actor,
                            jsonb_build_object('case_ref', c.case_ref, 'kind', p_kind, 'subject', v_label, 'consequence', p_consequence, 'owner', v_owner, 'due_at', c.due_at, 'digest', c.digest), p_correlation);
  IF v_owner IS NULL THEN
    v_gap := governance.dr_open_gap(p_tenant, p_domain, 'stewardship_case', p_case, c.case_ref || ' — ' || v_label, 'case_unowned',
                                    jsonb_build_object('reason', 'the case''s subject resolves to no accountable owner (no ratified data authority, or its owner lost)', 'subject', v_label),
                                    'the data steward, then the domain administrator', false, NULL, p_consequence, p_actor, p_correlation);
    FOREACH s IN ARRAY governance.dr_subject_artifacts(p_tenant, p_domain, p_subject_kind, p_subject) LOOP
      PERFORM governance.dr_open_hold(p_tenant, p_domain, s, 'ownership_gap', p_case,
                format('%s lacks an accountable owner: affected use of %s is constrained until the owner resolves (DP-55-005)', c.case_ref, v_label), p_actor, p_correlation);
    END LOOP;
  END IF;
  RETURN governance.dr_case_json(c) || jsonb_build_object('gap', v_gap);
END $$;
REVOKE ALL ON FUNCTION governance.dr_open_case(uuid, uuid, uuid, text, text, uuid, text, text, jsonb, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_open_case(uuid, uuid, uuid, text, text, uuid, text, text, jsonb, text, uuid, uuid) TO eye_commit;

/* REVIEW (governance.ownership.case.review; human-gated): one reviewer's approve | reject on the case's digest. The approver test: a data
   steward or the domain administrator (and the privacy officer for access and classification), never the proposer; for an ACCESS or a
   DATA EXCEPTION case never the subject's owner (the owner whose authority it expands). One review per reviewer; an approval of a case that
   lacks an owner is refused (held). A rejection decides; approvals decide when the consequence's count is met — with the deciding review's
   conditions and expiry (a data exception's expiry is required, ≤ 366 days). The decision cancels the SLA timer and lifts the case's SLA
   holds. */
CREATE OR REPLACE FUNCTION governance.dr_review_case(p_case uuid, p_tenant uuid, p_domain uuid, p_digest text, p_outcome text, p_note text, p_conditions jsonb, p_expires_at timestamptz,
                                                     p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, public, pg_catalog, pg_temp AS $$
DECLARE c governance.stewardship_cases%ROWTYPE; v_approvals int; v_now timestamptz := clock_timestamp(); v_released jsonb;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.case.review'], p_tenant, p_domain, p_actor, 'stewardship case');
  SELECT * INTO c FROM governance.stewardship_cases x WHERE x.case_id = p_case AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'stewardship case rejected (unknown_case): % is not a stewardship case of this domain', p_case USING ERRCODE = '22023'; END IF;
  PERFORM governance.assert_approver('stewardship case', p_actor, p_tenant, p_domain,
                                     CASE WHEN c.kind IN ('access', 'classification') THEN ARRAY['data_steward', 'domain_admin', 'privacy_officer'] ELSE ARRAY['data_steward', 'domain_admin'] END,
                                     c.opened_by, CASE WHEN c.kind IN ('access', 'data_exception') AND c.owner_principal_id IS NOT NULL THEN ARRAY[c.owner_principal_id] ELSE NULL END,
                                     'deciding a ' || replace(c.kind, '_', ' ') || ' case');
  IF c.state NOT IN ('open', 'in_review') THEN RAISE EXCEPTION 'stewardship case rejected (state): % is %', c.case_ref, c.state USING ERRCODE = '22023'; END IF;
  IF p_digest IS DISTINCT FROM c.digest THEN RAISE EXCEPTION 'stewardship case rejected (stale): the digest reviewed is not %''s', c.case_ref USING ERRCODE = '22023'; END IF;
  IF p_outcome IS NULL OR p_outcome NOT IN ('approve', 'reject') THEN RAISE EXCEPTION 'stewardship case rejected (outcome): approve or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_note, ''))) < 8 THEN RAISE EXCEPTION 'stewardship case rejected (note): a review states its grounds (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(c.reviews) r WHERE (r ->> 'reviewer')::uuid = p_actor) THEN
    RAISE EXCEPTION 'stewardship case rejected (duplicate): this reviewer has reviewed % already — a decision needs distinct reviewers', c.case_ref USING ERRCODE = '22023';
  END IF;
  IF p_outcome = 'approve' AND c.owner_principal_id IS NULL THEN
    RAISE EXCEPTION 'stewardship case rejected (held): % lacks an accountable owner — an unowned change is never approved; the ownership gap stays open until the owner resolves (DP-55-005)', c.case_ref USING ERRCODE = '22023';
  END IF;
  IF p_conditions IS NOT NULL AND (jsonb_typeof(p_conditions) <> 'array' OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_conditions) x WHERE jsonb_typeof(x) <> 'string' OR length(btrim(x #>> '{}')) < 8)) THEN
    RAISE EXCEPTION 'stewardship case rejected (conditions): conditions are a list of statements (8+ characters each)' USING ERRCODE = '22023';
  END IF;
  IF p_expires_at IS NOT NULL AND (p_expires_at <= v_now OR p_expires_at > v_now + interval '366 days') THEN
    RAISE EXCEPTION 'stewardship case rejected (expiry): an expiry is in the future and within 366 days' USING ERRCODE = '22023';
  END IF;
  IF p_outcome = 'approve' AND c.kind = 'data_exception' AND p_expires_at IS NULL THEN
    RAISE EXCEPTION 'stewardship case rejected (expiry): a data exception is narrow and EXPIRES — the approval names its expiry (within 366 days)' USING ERRCODE = '22023';
  END IF;
  c.reviews := c.reviews || jsonb_build_object('reviewer', p_actor, 'outcome', p_outcome, 'note', btrim(p_note), 'at', v_now, 'conditions', coalesce(p_conditions, '[]'::jsonb), 'expires_at', p_expires_at);
  SELECT count(*) INTO v_approvals FROM jsonb_array_elements(c.reviews) r WHERE r ->> 'outcome' = 'approve';
  IF p_outcome = 'reject' THEN
    UPDATE governance.stewardship_cases SET reviews = c.reviews, state = 'rejected', decision = 'rejected', decided_by = p_actor, decided_at = v_now, updated_at = v_now WHERE case_id = p_case RETURNING * INTO c;
  ELSIF v_approvals >= c.reviewers_required THEN
    UPDATE governance.stewardship_cases SET reviews = c.reviews, state = 'approved', decision = 'approved', decided_by = p_actor, decided_at = v_now, conditions = coalesce(p_conditions, '[]'::jsonb),
           expires_at = p_expires_at, updated_at = v_now WHERE case_id = p_case RETURNING * INTO c;
  ELSE
    UPDATE governance.stewardship_cases SET reviews = c.reviews, state = 'in_review', updated_at = v_now WHERE case_id = p_case RETURNING * INTO c;
  END IF;
  IF c.decision IS NOT NULL THEN
    PERFORM governance.dr_cancel_case_timers(p_case);
    v_released := governance.dr_case_release(c, ARRAY['evidence_stale'], format('%s decided (%s) by a named reviewer', c.case_ref, c.decision), p_actor, p_correlation);
    -- the SLA hold (C3+ past its SLA) is opened as ownership_gap by the sweep with the case as its source; a decision ends it (the owner hold of an unowned case stays until it resolves)
    IF c.owner_principal_id IS NOT NULL THEN v_released := v_released || governance.dr_case_release(c, ARRAY['ownership_gap'], format('%s decided (%s)', c.case_ref, c.decision), p_actor, p_correlation); END IF;
  END IF;
  PERFORM governance.ledger(p_tenant, p_domain, 'stewardship_case', p_case, NULL, CASE WHEN c.decision IS NULL THEN 'case.reviewed' ELSE 'case.decided' END, p_actor,
                            jsonb_build_object('case_ref', c.case_ref, 'outcome', p_outcome, 'approvals', v_approvals, 'required', c.reviewers_required, 'decision', c.decision,
                                               'conditions', c.conditions, 'expires_at', c.expires_at, 'released', v_released), p_correlation);
  RETURN governance.dr_case_json(c) || jsonb_build_object('released', v_released);
END $$;
REVOKE ALL ON FUNCTION governance.dr_review_case(uuid, uuid, uuid, text, text, text, jsonb, timestamptz, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_review_case(uuid, uuid, uuid, text, text, text, jsonb, timestamptz, uuid, uuid) TO eye_commit;

/* CLOSE (governance.ownership.case.close): the subject's owner or a data steward / the domain administrator closes a DECIDED (or expired)
   case with its closure note and evidence — an approved case's conditions each evidenced (one evidence item per condition at least). The
   case's holds lift (an expired exception ends with its closure). */
CREATE OR REPLACE FUNCTION governance.dr_close_case(p_case uuid, p_tenant uuid, p_domain uuid, p_note text, p_evidence jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, public, pg_catalog, pg_temp AS $$
DECLARE c governance.stewardship_cases%ROWTYPE; v_released jsonb; g record;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.case.close'], p_tenant, p_domain, p_actor, 'stewardship case');
  SELECT * INTO c FROM governance.stewardship_cases x WHERE x.case_id = p_case AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'stewardship case rejected (unknown_case): % is not a stewardship case of this domain', p_case USING ERRCODE = '22023'; END IF;
  IF c.owner_principal_id IS DISTINCT FROM p_actor AND NOT executive.holds_role(p_actor, p_tenant, p_domain, ARRAY['data_steward', 'domain_admin']) THEN
    RAISE EXCEPTION 'stewardship case rejected (authority): a case is closed by its subject''s owner, a data steward or the domain administrator' USING ERRCODE = '42501';
  END IF;
  IF c.state NOT IN ('approved', 'rejected', 'expired') THEN RAISE EXCEPTION 'stewardship case rejected (state): % is %; a decided case is closed', c.case_ref, c.state USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_note, ''))) < 8 THEN RAISE EXCEPTION 'stewardship case rejected (note): a closure states what was done (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_evidence IS NULL OR jsonb_typeof(p_evidence) <> 'array' OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_evidence) e WHERE jsonb_typeof(e) <> 'object' OR length(btrim(coalesce(e ->> 'ref', ''))) < 2)
     OR (c.decision = 'approved' AND jsonb_array_length(p_evidence) < greatest(1, jsonb_array_length(c.conditions))) THEN
    RAISE EXCEPTION 'stewardship case rejected (evidence): a closure carries its evidence ({kind, ref}) — at least one item per condition of an approved case (% condition(s))', jsonb_array_length(c.conditions) USING ERRCODE = '22023';
  END IF;
  UPDATE governance.stewardship_cases SET state = 'closed', closed_by = p_actor, closed_at = clock_timestamp(), closure_note = btrim(p_note), closure_evidence = p_evidence, updated_at = clock_timestamp()
   WHERE case_id = p_case RETURNING * INTO c;
  PERFORM governance.dr_cancel_case_timers(p_case);
  v_released := governance.dr_case_release(c, ARRAY['ownership_gap', 'exception_expired', 'evidence_stale'], format('%s closed: %s', c.case_ref, btrim(p_note)), p_actor, p_correlation);
  FOR g IN SELECT x.gap_id FROM governance.ownership_gaps x WHERE x.subject_id = p_case AND x.state <> 'resolved' LOOP
    PERFORM governance.dr_resolve_gap(g.gap_id, 'the case is closed', p_actor, p_correlation);
  END LOOP;
  PERFORM governance.ledger(p_tenant, p_domain, 'stewardship_case', p_case, NULL, 'case.closed', p_actor, jsonb_build_object('case_ref', c.case_ref, 'note', btrim(p_note), 'evidence', p_evidence, 'released', v_released), p_correlation);
  RETURN governance.dr_case_json(c) || jsonb_build_object('released', v_released);
END $$;
REVOKE ALL ON FUNCTION governance.dr_close_case(uuid, uuid, uuid, text, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_close_case(uuid, uuid, uuid, text, jsonb, uuid, uuid) TO eye_commit;

/* WITHDRAW (governance.ownership.case.withdraw): the opener withdraws an undecided case; its timer cancelled, its holds lifted. */
CREATE OR REPLACE FUNCTION governance.dr_withdraw_case(p_case uuid, p_tenant uuid, p_domain uuid, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, public, pg_catalog, pg_temp AS $$
DECLARE c governance.stewardship_cases%ROWTYPE; v_released jsonb; g record;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.case.withdraw'], p_tenant, p_domain, p_actor, 'stewardship case');
  SELECT * INTO c FROM governance.stewardship_cases x WHERE x.case_id = p_case AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'stewardship case rejected (unknown_case): % is not a stewardship case of this domain', p_case USING ERRCODE = '22023'; END IF;
  IF c.opened_by <> p_actor THEN RAISE EXCEPTION 'stewardship case rejected (authority): a case is withdrawn by the one who opened it' USING ERRCODE = '42501'; END IF;
  IF c.state NOT IN ('open', 'in_review') THEN RAISE EXCEPTION 'stewardship case rejected (state): % is %', c.case_ref, c.state USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'stewardship case rejected (reason): a withdrawal states why (8+ characters)' USING ERRCODE = '22023'; END IF;
  UPDATE governance.stewardship_cases SET state = 'withdrawn', closure_note = btrim(p_reason), updated_at = clock_timestamp() WHERE case_id = p_case RETURNING * INTO c;
  PERFORM governance.dr_cancel_case_timers(p_case);
  v_released := governance.dr_case_release(c, ARRAY['ownership_gap', 'evidence_stale'], format('%s withdrawn: %s', c.case_ref, btrim(p_reason)), p_actor, p_correlation);
  FOR g IN SELECT x.gap_id FROM governance.ownership_gaps x WHERE x.subject_id = p_case AND x.state <> 'resolved' LOOP
    PERFORM governance.dr_resolve_gap(g.gap_id, 'the case was withdrawn', p_actor, p_correlation);
  END LOOP;
  PERFORM governance.ledger(p_tenant, p_domain, 'stewardship_case', p_case, NULL, 'case.withdrawn', p_actor, jsonb_build_object('case_ref', c.case_ref, 'reason', btrim(p_reason)), p_correlation);
  RETURN governance.dr_case_json(c);
END $$;
REVOKE ALL ON FUNCTION governance.dr_withdraw_case(uuid, uuid, uuid, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_withdraw_case(uuid, uuid, uuid, text, uuid, uuid) TO eye_commit;

/* THE SWEEP (executive.attention.tick — the step `governance-stewardship-sla` and the `stewardship.sla` timer, which names its case): on the
   database clock,
     (1) an UNOWNED undecided case whose subject now resolves to an owner takes it — its gap resolves, its subject's hold lifts;
     (2) an undecided case PAST ITS SLA escalates by consequence — level + 1, the next window, a governance.ownership item at the case's
         consequence (one level higher per escalation, capped at C4), and at C3+ a hold on its subject (affected use constrained until a
         named reviewer decides);
     (3) an approved case PAST ITS EXPIRY expires — a data exception holds its subject (exception_expired) until the case is closed or a new
         case approves a renewal; conditions not evidenced by their expiry hold it (evidence_stale).
   Reads first (the candidate list), then each write; never one statement across the context. */
CREATE OR REPLACE FUNCTION governance.dr_sweep_cases(p_tenant uuid, p_domain uuid, p_case uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, public, pg_catalog, pg_temp AS $$
DECLARE c governance.stewardship_cases%ROWTYPE; v_now timestamptz := clock_timestamp(); v_owner uuid; v_ids uuid[]; v_id uuid; v_ev uuid; s uuid; g record;
        v_owned jsonb := '[]'::jsonb; v_escalated jsonb := '[]'::jsonb; v_expired jsonb := '[]'::jsonb; v_cons text;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['executive.attention.tick'], p_tenant, p_domain, p_actor, 'stewardship case');
  SELECT coalesce(array_agg(x.case_id ORDER BY x.due_at), '{}') INTO v_ids FROM governance.stewardship_cases x
   WHERE x.tenant_id = p_tenant AND x.domain_id = p_domain AND (p_case IS NULL OR x.case_id = p_case)
     AND ((x.state IN ('open', 'in_review') AND (x.owner_principal_id IS NULL OR x.due_at <= v_now)) OR (x.state = 'approved' AND x.expires_at IS NOT NULL AND x.expires_at <= v_now));
  FOREACH v_id IN ARRAY v_ids LOOP
    SELECT * INTO c FROM governance.stewardship_cases x WHERE x.case_id = v_id FOR UPDATE;
    -- (1) the owner, re-resolved
    IF c.state IN ('open', 'in_review') AND c.owner_principal_id IS NULL THEN
      v_owner := governance.dr_case_owner(c.tenant_id, c.domain_id, c.subject_kind, c.subject_id);
      IF v_owner IS NOT NULL THEN
        UPDATE governance.stewardship_cases SET owner_principal_id = v_owner, updated_at = v_now WHERE case_id = c.case_id RETURNING * INTO c;
        FOREACH s IN ARRAY governance.dr_subject_artifacts(c.tenant_id, c.domain_id, c.subject_kind, c.subject_id) LOOP
          PERFORM governance.dr_lift_holds(s, 'ownership_gap', c.case_id, c.case_ref || ' has an accountable owner now', p_actor);
        END LOOP;
        FOR g IN SELECT x.gap_id FROM governance.ownership_gaps x WHERE x.subject_id = c.case_id AND x.state <> 'resolved' LOOP
          PERFORM governance.dr_resolve_gap(g.gap_id, 'the case''s subject resolves to an accountable owner', p_actor, p_correlation);
        END LOOP;
        PERFORM governance.ledger(c.tenant_id, c.domain_id, 'stewardship_case', c.case_id, NULL, 'case.owner_resolved', p_actor, jsonb_build_object('case_ref', c.case_ref, 'owner', v_owner), p_correlation);
        v_owned := v_owned || jsonb_build_object('case_ref', c.case_ref, 'owner', v_owner);
      END IF;
    END IF;
    -- (2) past its SLA
    IF c.state IN ('open', 'in_review') AND c.due_at <= v_now THEN
      v_cons := 'C' || least(4, substr(c.consequence, 2)::int + c.escalation_level)::text;
      UPDATE governance.stewardship_cases SET escalation_level = escalation_level + 1, escalated_at = v_now, due_at = v_now + governance.dr_case_sla(c.consequence), updated_at = v_now
       WHERE case_id = c.case_id RETURNING * INTO c;
      PERFORM executive._schedule_timer(gen_random_uuid(), c.tenant_id, c.domain_id, 'stewardship_case', c.case_id, 'stewardship.sla', c.due_at,
                                        jsonb_build_object('case', c.case_id, 'case_ref', c.case_ref, 'consequence', c.consequence, 'level', c.escalation_level), p_actor, p_correlation);
      v_ev := governance.ledger(c.tenant_id, c.domain_id, 'stewardship_case', c.case_id, NULL, 'case.escalated', p_actor,
                                jsonb_build_object('case_ref', c.case_ref, 'level', c.escalation_level, 'consequence', v_cons, 'next_due_at', c.due_at), p_correlation);
      PERFORM executive.b33_raise_routed(c.tenant_id, c.domain_id, 'governance.ownership', 'stewardship_case', c.case_id,
                left(format('Stewardship case %s past its SLA (level %s, %s): %s — %s', c.case_ref, c.escalation_level, v_cons, c.title, c.subject_label), 512),
                jsonb_build_array(format('no decision by the SLA of a %s case (%s)', c.consequence, governance.dr_case_sla(c.consequence))), c.owner_principal_id, v_ev, 'StewardshipCaseEscalated',
                jsonb_build_object('case_ref', c.case_ref, 'level', c.escalation_level, 'kind', c.kind), jsonb_build_object('consequence', v_cons), p_actor, p_correlation);
      IF v_cons IN ('C3', 'C4') THEN
        FOREACH s IN ARRAY governance.dr_subject_artifacts(c.tenant_id, c.domain_id, c.subject_kind, c.subject_id) LOOP
          PERFORM governance.dr_open_hold(c.tenant_id, c.domain_id, s, 'evidence_stale', c.case_id,
                    format('%s (%s) is past its SLA without an independent decision: affected use of %s is constrained until a named reviewer decides', c.case_ref, v_cons, c.subject_label), p_actor, p_correlation);
        END LOOP;
      END IF;
      v_escalated := v_escalated || jsonb_build_object('case_ref', c.case_ref, 'level', c.escalation_level, 'consequence', v_cons);
    END IF;
    -- (3) past its expiry
    IF c.state = 'approved' AND c.expires_at IS NOT NULL AND c.expires_at <= v_now THEN
      UPDATE governance.stewardship_cases SET state = 'expired', updated_at = v_now WHERE case_id = c.case_id RETURNING * INTO c;
      v_ev := governance.ledger(c.tenant_id, c.domain_id, 'stewardship_case', c.case_id, NULL, 'case.expired', p_actor, jsonb_build_object('case_ref', c.case_ref, 'expires_at', c.expires_at), p_correlation);
      FOREACH s IN ARRAY governance.dr_subject_artifacts(c.tenant_id, c.domain_id, c.subject_kind, c.subject_id) LOOP
        PERFORM governance.dr_open_hold(c.tenant_id, c.domain_id, s, CASE WHEN c.kind = 'data_exception' THEN 'exception_expired' ELSE 'evidence_stale' END, c.case_id,
                  CASE WHEN c.kind = 'data_exception' THEN format('the data exception %s expired at %s: affected use of %s is held until it is closed or a renewal is approved with current evidence', c.case_ref, c.expires_at, c.subject_label)
                       ELSE format('the conditions of %s were not evidenced by %s', c.case_ref, c.expires_at) END, p_actor, p_correlation);
      END LOOP;
      PERFORM executive.b33_raise_routed(c.tenant_id, c.domain_id, 'governance.ownership', 'stewardship_case', c.case_id,
                left(format('%s %s EXPIRED at %s: %s', CASE WHEN c.kind = 'data_exception' THEN 'Data exception' ELSE 'Stewardship decision' END, c.case_ref, c.expires_at, c.subject_label), 512),
                jsonb_build_array('the decision''s expiry passed before its closure'), c.owner_principal_id, v_ev, 'StewardshipCaseExpired', jsonb_build_object('case_ref', c.case_ref, 'kind', c.kind),
                jsonb_build_object('consequence', c.consequence), p_actor, p_correlation);
      v_expired := v_expired || jsonb_build_object('case_ref', c.case_ref, 'kind', c.kind);
    END IF;
  END LOOP;
  RETURN jsonb_build_object('candidates', cardinality(v_ids), 'owner_resolved', v_owned, 'escalated', v_escalated, 'expired', v_expired);
END $$;
REVOKE ALL ON FUNCTION governance.dr_sweep_cases(uuid, uuid, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_sweep_cases(uuid, uuid, uuid, uuid, uuid) TO eye_commit;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.7 THE RESPONSIBILITY EVIDENCE RECORD (DOMAIN; DP-01-006, DP-04-006, DP-55-006 — the in-product half of B+X:R1)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
CREATE TABLE governance.responsibility_evidence (
  record_id          uuid PRIMARY KEY,
  scope              text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id          uuid NOT NULL,
  domain_id          uuid NOT NULL,
  deployment_profile text NOT NULL CHECK (deployment_profile IN ('local-dev', 'saas', 'private-cloud', 'on-premise')),
  period_from        timestamptz NOT NULL,
  period_to          timestamptz NOT NULL,
  bound              jsonb NOT NULL CHECK (jsonb_typeof(bound) = 'object'),            -- the build identity: head SHA, migration head, policy bundle version, contract digests
  matrix             jsonb NOT NULL CHECK (jsonb_typeof(matrix) = 'object'),           -- B94's approved, SIGNED responsibility matrix (referenced, never rewritten)
  authorities        jsonb NOT NULL CHECK (jsonb_typeof(authorities) = 'object'),      -- the ratified authorities and their recertification
  stewardship        jsonb NOT NULL CHECK (jsonb_typeof(stewardship) = 'object'),      -- SLA, segregation, exception ageing, override review, sampled decisions
  privileged_changes jsonb NOT NULL CHECK (jsonb_typeof(privileged_changes) = 'array'),
  exercises          jsonb NOT NULL CHECK (jsonb_typeof(exercises) = 'array'),         -- B94's joint operating exercises in the period
  gaps               jsonb NOT NULL CHECK (jsonb_typeof(gaps) = 'object'),
  digest             text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  claim              text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  production_admission text NOT NULL DEFAULT 'R1: production admission and continued operation are decided on real infrastructure by named external authorities — this record is construction / demonstration evidence only, never an admission',
  state              text NOT NULL DEFAULT 'assembled' CHECK (state IN ('assembled', 'attested', 'rejected')),
  assembled_by       uuid NOT NULL,
  assembled_at       timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by         uuid,
  decided_at         timestamptz,
  decision_reason    text,
  signature_id       uuid,
  correlation_id     uuid NOT NULL,
  CONSTRAINT gre_scope CHECK (observation.scope_ok(scope, tenant_id, domain_id)),
  CONSTRAINT gre_period CHECK (period_from < period_to),
  CONSTRAINT gre_decided CHECK ((state = 'assembled') = (decided_by IS NULL)),
  CONSTRAINT gre_sod CHECK (decided_by IS NULL OR decided_by <> assembled_by),
  CONSTRAINT gre_signed CHECK (state <> 'attested' OR signature_id IS NOT NULL)
);
CREATE INDEX gre_domain ON governance.responsibility_evidence (tenant_id, domain_id, assembled_at DESC);
CREATE OR REPLACE FUNCTION governance.dr_evidence_forward() RETURNS trigger LANGUAGE plpgsql SET search_path = governance, pg_catalog, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.state <> 'assembled'
     OR (to_jsonb(NEW) - ARRAY['state', 'decided_by', 'decided_at', 'decision_reason', 'signature_id']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['state', 'decided_by', 'decided_at', 'decision_reason', 'signature_id']) THEN
    RAISE EXCEPTION 'data authority rejected (state): an evidence record is immutable once assembled; only its attestation is set, once' USING ERRCODE = '2F002';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER gre_forward BEFORE UPDATE OR DELETE ON governance.responsibility_evidence FOR EACH ROW EXECUTE FUNCTION governance.dr_evidence_forward();

/* ASSEMBLE (governance.ownership.evidence.assemble; a data steward or the domain administrator): the evidence of one period, READ from the
   records (never typed): the B94 matrix approved for the profile and its signatures; the ratified authorities with their recertification;
   the stewardship queue — opened, decided, decided within the first SLA, the attainment, the escalations, the SEGREGATION TEST (decisions or
   reviews by the opener; exception decisions by the owner — each must be 0), the exception AGEING, the OVERRIDE review (residuals accepted),
   a SAMPLE of decided cases (deterministic, for a person's quality review); the privileged changes (ratifications, acceptances, decisions);
   B94's joint exercises; the open gaps; bound to the build identity the caller passes and the migration head read here. */
CREATE OR REPLACE FUNCTION governance.dr_assemble_evidence(p_record uuid, p_tenant uuid, p_domain uuid, p_profile text, p_from timestamptz, p_to timestamptz, p_bound jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, service, executive, products, public, pg_catalog, pg_temp AS $$
DECLARE m service.responsibility_matrices%ROWTYPE; v_matrix jsonb; v_auth jsonb; v_stew jsonb; v_priv jsonb; v_ex jsonb; v_gaps jsonb; v_bound jsonb; r governance.responsibility_evidence%ROWTYPE;
        v_decided int; v_within int;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.evidence.assemble'], p_tenant, p_domain, p_actor, 'data authority');
  IF NOT executive.holds_role(p_actor, p_tenant, p_domain, ARRAY['data_steward', 'domain_admin']) THEN
    RAISE EXCEPTION 'data authority rejected (authority): responsibility evidence is assembled by a data steward or the domain administrator' USING ERRCODE = '42501';
  END IF;
  IF coalesce(p_profile, '') NOT IN ('local-dev', 'saas', 'private-cloud', 'on-premise') THEN RAISE EXCEPTION 'data authority rejected (profile): local-dev, saas, private-cloud or on-premise' USING ERRCODE = '22023'; END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_from >= p_to OR p_to > clock_timestamp() OR p_to - p_from > interval '366 days' THEN
    RAISE EXCEPTION 'data authority rejected (period): a period under review is closed (from before to, to not in the future) and at most 366 days' USING ERRCODE = '22023';
  END IF;
  IF p_bound IS NULL OR jsonb_typeof(p_bound) <> 'object' THEN RAISE EXCEPTION 'data authority rejected (bound): the build identity is an object' USING ERRCODE = '22023'; END IF;
  SELECT * INTO m FROM service.responsibility_matrices x WHERE x.tenant_id = p_tenant AND x.domain_id = p_domain AND x.deployment_profile = p_profile AND x.state = 'approved';
  v_matrix := CASE WHEN m.matrix_id IS NULL THEN jsonb_build_object('state', 'missing', 'reason', format('the domain has no approved responsibility matrix for %s', p_profile))
                   ELSE jsonb_build_object('state', 'approved', 'matrix_id', m.matrix_id, 'version', m.version, 'digest', m.digest, 'signature_id', m.signature_id, 'decided_by', m.decided_by,
                                           'decided_at', m.decided_at, 'signatures', executive.signature_of('responsibility_matrix', m.matrix_id, m.version),
                                           'rows', (SELECT count(*) FROM service.responsibility_rows rr WHERE rr.matrix_id = m.matrix_id AND rr.version = m.version)) END;
  SELECT jsonb_build_object('ratified', count(*), 'recertified_in_period', count(*) FILTER (WHERE a.recertified_at >= p_from AND a.recertified_at < p_to),
           'lapsed', count(*) FILTER (WHERE a.recertify_by < p_to), 'owner_accepted', count(*) FILTER (WHERE a.owner_accepted_at IS NOT NULL),
           'items', coalesce(jsonb_agg(jsonb_build_object('authority_id', a.authority_id, 'asset', a.asset_kind || ':' || a.asset_ref, 'version', a.version, 'digest', a.digest, 'owner', a.owner_principal_id,
                                                          'recertify_by', a.recertify_by, 'recertified_at', a.recertified_at) ORDER BY a.asset_kind, a.asset_ref), '[]'::jsonb))
    INTO v_auth FROM governance.data_authorities a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.state = 'ratified';
  SELECT count(*) FILTER (WHERE c.decided_at >= p_from AND c.decided_at < p_to), count(*) FILTER (WHERE c.decided_at >= p_from AND c.decided_at < p_to AND c.decided_at <= c.first_due_at)
    INTO v_decided, v_within FROM governance.stewardship_cases c WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain;
  v_stew := jsonb_build_object(
    'opened', (SELECT count(*) FROM governance.stewardship_cases c WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain AND c.opened_at >= p_from AND c.opened_at < p_to),
    'decided', v_decided, 'decided_within_sla', v_within,
    'sla_attainment_pct', CASE WHEN v_decided = 0 THEN NULL ELSE round(100.0 * v_within / v_decided, 2) END,
    'escalated', (SELECT count(*) FROM governance.stewardship_cases c WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain AND c.escalated_at >= p_from AND c.escalated_at < p_to),
    'open_now', (SELECT count(*) FROM governance.stewardship_cases c WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain AND c.state IN ('open', 'in_review')),
    'segregation', jsonb_build_object(
       'decided_by_opener', (SELECT count(*) FROM governance.stewardship_cases c WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain AND c.decided_by = c.opened_by),
       'reviewed_by_opener', (SELECT count(*) FROM governance.stewardship_cases c, jsonb_array_elements(c.reviews) rv WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain AND (rv ->> 'reviewer')::uuid = c.opened_by),
       'exception_approved_by_owner', (SELECT count(*) FROM governance.stewardship_cases c, jsonb_array_elements(c.reviews) rv WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain
                                         AND c.kind IN ('access', 'data_exception') AND rv ->> 'outcome' = 'approve' AND (rv ->> 'reviewer')::uuid = c.owner_principal_id),
       'note', 'each count must be 0 — the ports refuse these acts; the test re-reads the record'),
    'exception_ageing', coalesce((SELECT jsonb_agg(jsonb_build_object('case_ref', c.case_ref, 'state', c.state, 'approved_at', c.decided_at, 'expires_at', c.expires_at, 'closed_at', c.closed_at,
                                                                     'age_days', round(extract(epoch FROM (least(coalesce(c.closed_at, p_to), p_to) - c.decided_at)) / 86400.0, 1),
                                                                     'days_to_expiry', round(extract(epoch FROM (c.expires_at - p_to)) / 86400.0, 1)) ORDER BY c.decided_at)
                                    FROM governance.stewardship_cases c WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain AND c.kind = 'data_exception' AND c.decision = 'approved' AND c.decided_at < p_to
                                      AND (c.closed_at IS NULL OR c.closed_at >= p_from)), '[]'::jsonb),
    'override_review', coalesce((SELECT jsonb_agg(jsonb_build_object('gap_id', g.gap_id, 'gap_kind', g.gap_kind, 'subject', g.subject_label, 'accepted_by', g.accepted_by, 'accepted_until', g.accepted_until,
                                                                    'reason', g.accept_reason) ORDER BY g.accepted_at)
                                   FROM governance.ownership_gaps g WHERE g.tenant_id = p_tenant AND g.domain_id = p_domain AND g.accepted_at >= p_from AND g.accepted_at < p_to), '[]'::jsonb),
    'sample', coalesce((SELECT jsonb_agg(jsonb_build_object('case_ref', q.case_ref, 'kind', q.kind, 'consequence', q.consequence, 'decision', q.decision, 'reviews', q.reviews, 'conditions', q.conditions))
                          FROM (SELECT c.* FROM governance.stewardship_cases c WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain AND c.decided_at >= p_from AND c.decided_at < p_to
                                 ORDER BY md5(c.case_id::text || p_from::text) LIMIT 5) q), '[]'::jsonb),
    'sample_rule', 'up to five decided cases of the period, ordered by md5(case_id || period start): a deterministic draw for a person''s quality review');
  SELECT coalesce(jsonb_agg(jsonb_build_object('event', e.event, 'subject_kind', e.subject_kind, 'subject_id', e.subject_id, 'version', e.version, 'actor', e.actor_principal_id, 'at', e.occurred_at) ORDER BY e.occurred_at), '[]'::jsonb)
    INTO v_priv FROM governance.events e
   WHERE e.tenant_id = p_tenant AND e.domain_id = p_domain AND e.occurred_at >= p_from AND e.occurred_at < p_to
     AND e.event IN ('authority.ratified', 'authority.rejected', 'domain.ratified', 'gap.accepted', 'case.decided', 'authority.recertified');
  SELECT coalesce(jsonb_agg(jsonb_build_object('exercise_id', x.exercise_id, 'title', x.title, 'held_on', x.held_on, 'outcome', x.outcome, 'claim', x.claim) ORDER BY x.held_on), '[]'::jsonb)
    INTO v_ex FROM service.joint_exercises x WHERE x.tenant_id = p_tenant AND x.domain_id = p_domain AND x.held_on >= p_from::date AND x.held_on <= p_to::date;
  SELECT jsonb_build_object('open', count(*) FILTER (WHERE g.state IN ('open', 'escalated')), 'accepted', count(*) FILTER (WHERE g.state = 'accepted'),
                            'items', coalesce(jsonb_agg(jsonb_build_object('gap_id', g.gap_id, 'gap_kind', g.gap_kind, 'subject', g.subject_label, 'state', g.state) ORDER BY g.opened_at), '[]'::jsonb))
    INTO v_gaps FROM governance.ownership_gaps g WHERE g.tenant_id = p_tenant AND g.domain_id = p_domain AND g.state <> 'resolved';
  v_bound := p_bound || jsonb_build_object('migration_head', (SELECT max(filename) FROM public.schema_migrations), 'deployment_profile', p_profile,
                                           'authority_digests', governance.digest(v_auth -> 'items'), 'matrix_digest', v_matrix ->> 'digest');
  INSERT INTO governance.responsibility_evidence (record_id, tenant_id, domain_id, deployment_profile, period_from, period_to, bound, matrix, authorities, stewardship, privileged_changes, exercises, gaps,
                                                  digest, assembled_by, correlation_id)
  VALUES (p_record, p_tenant, p_domain, p_profile, p_from, p_to, v_bound, v_matrix, v_auth, v_stew, v_priv, v_ex, v_gaps,
          governance.digest(jsonb_build_object('record_id', p_record, 'tenant', p_tenant, 'domain', p_domain, 'profile', p_profile, 'from', p_from, 'to', p_to, 'bound', v_bound, 'matrix', v_matrix,
                                               'authorities', v_auth, 'stewardship', v_stew, 'privileged_changes', v_priv, 'exercises', v_ex, 'gaps', v_gaps, 'claim', 'demonstration')),
          p_actor, p_correlation) RETURNING * INTO r;
  PERFORM governance.ledger(p_tenant, p_domain, 'responsibility_evidence', p_record, 1, 'evidence.assembled', p_actor, jsonb_build_object('digest', r.digest, 'from', p_from, 'to', p_to, 'profile', p_profile), p_correlation);
  RETURN to_jsonb(r) - 'scope' - 'correlation_id';
END $$;
REVOKE ALL ON FUNCTION governance.dr_assemble_evidence(uuid, uuid, uuid, text, timestamptz, timestamptz, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_assemble_evidence(uuid, uuid, uuid, text, timestamptz, timestamptz, jsonb, uuid, uuid) TO eye_commit;

/* ATTEST (governance.ownership.evidence.attest; human-gated): the onboarding authority or the customer sponsor — never the assembler —
   attests (SIGNED first: executive.signatures `responsibility_matrix` over the record's digest, by the attester; the port verifies it) or
   rejects. An attestation needs the B94 matrix APPROVED and SIGNED and a clean segregation test; it is the customer's attestation of
   demonstration evidence — production admission stays R1. */
CREATE OR REPLACE FUNCTION governance.dr_attest_evidence(p_record uuid, p_tenant uuid, p_domain uuid, p_digest text, p_decision text, p_reason text, p_signature uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, public, pg_catalog, pg_temp AS $$
DECLARE r governance.responsibility_evidence%ROWTYPE; s executive.signatures%ROWTYPE; v_seg int;
BEGIN
  PERFORM governance.dr_domain_head(ARRAY['governance.ownership.evidence.attest'], p_tenant, p_domain, p_actor, 'data authority');
  SELECT * INTO r FROM governance.responsibility_evidence x WHERE x.record_id = p_record AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data authority rejected (unknown_record): % is not an evidence record of this domain', p_record USING ERRCODE = '22023'; END IF;
  PERFORM governance.assert_approver('data authority', p_actor, p_tenant, p_domain, ARRAY['onboarding_authority', 'customer_sponsor'], r.assembled_by, NULL, 'attesting responsibility evidence');
  IF r.state <> 'assembled' THEN RAISE EXCEPTION 'data authority rejected (state): record % is %', p_record, r.state USING ERRCODE = '22023'; END IF;
  IF p_digest IS DISTINCT FROM r.digest THEN RAISE EXCEPTION 'data authority rejected (stale): the digest attested is not the record''s' USING ERRCODE = '22023'; END IF;
  IF p_decision IS NULL OR p_decision NOT IN ('attest', 'reject') THEN RAISE EXCEPTION 'data authority rejected (decision): attest or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'data authority rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'attest' THEN
    v_seg := coalesce((r.stewardship #>> '{segregation,decided_by_opener}')::int, 0) + coalesce((r.stewardship #>> '{segregation,reviewed_by_opener}')::int, 0)
             + coalesce((r.stewardship #>> '{segregation,exception_approved_by_owner}')::int, 0);
    IF r.matrix ->> 'state' <> 'approved' OR r.matrix ->> 'signature_id' IS NULL THEN
      RAISE EXCEPTION 'data authority rejected (held): the record carries no approved, signed responsibility matrix (%) — it is attested only over a signed matrix', coalesce(r.matrix ->> 'reason', 'unsigned') USING ERRCODE = '22023';
    END IF;
    IF v_seg > 0 THEN RAISE EXCEPTION 'data authority rejected (held): the segregation test of the record is not clean (% violation(s))', v_seg USING ERRCODE = '22023'; END IF;
    SELECT * INTO s FROM executive.signatures x WHERE x.signature_id = p_signature;
    IF NOT FOUND OR s.subject_kind <> 'responsibility_matrix' OR s.subject_id <> p_record OR s.subject_digest <> r.digest OR s.signer <> p_actor THEN
      RAISE EXCEPTION 'data authority rejected (signature): an attestation is signed by the attester over the record''s digest first' USING ERRCODE = '22023';
    END IF;
  END IF;
  UPDATE governance.responsibility_evidence SET state = CASE WHEN p_decision = 'attest' THEN 'attested' ELSE 'rejected' END, decided_by = p_actor, decided_at = clock_timestamp(),
         decision_reason = btrim(p_reason), signature_id = CASE WHEN p_decision = 'attest' THEN p_signature END WHERE record_id = p_record RETURNING * INTO r;
  PERFORM governance.ledger(p_tenant, p_domain, 'responsibility_evidence', p_record, 1, CASE WHEN p_decision = 'attest' THEN 'evidence.attested' ELSE 'evidence.rejected' END, p_actor,
                            jsonb_build_object('digest', r.digest, 'reason', btrim(p_reason), 'signature_id', r.signature_id, 'claim', r.claim), p_correlation);
  RETURN to_jsonb(r) - 'scope' - 'correlation_id';
END $$;
REVOKE ALL ON FUNCTION governance.dr_attest_evidence(uuid, uuid, uuid, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_attest_evidence(uuid, uuid, uuid, text, text, text, uuid, uuid, uuid) TO eye_commit;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.8 THE READS (definer reads guarded by the caller's bound scope — N-01)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
/* THE DATA PRODUCT REGISTRY VIEW (DAT-GV-03): every product of the domain — purpose, contracts, consumers, SLOs (declared and the latest
   observation per measure), cost, lifecycle — with its GOVERNANCE: the catalog entry's ratified authority (owner, steward), its trust, the
   open gaps and the holds that stop new consumption. Read over products.* (B90), never written. */
CREATE OR REPLACE FUNCTION governance.dr_products(p_tenant uuid, p_domain uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, products, public, pg_catalog, pg_temp AS $$
BEGIN
  PERFORM observation.assert_read_scope(p_tenant, p_domain, 'the data product registry');
  RETURN coalesce((SELECT jsonb_agg(jsonb_build_object(
      'product_id', p.product_id, 'product_key', p.product_key, 'title', p.title, 'kind', p.kind, 'purpose', p.purpose, 'state', p.state, 'released_version', p.released_version,
      'degraded_reason', p.degraded_reason, 'owner', p.owner_principal_id, 'owner_name', governance.dr_name(p.owner_principal_id),
      'contract', coalesce(p.declaration -> 'contract', '{}'::jsonb), 'serving_modes', coalesce(p.declaration -> 'serving_modes', '[]'::jsonb),
      'slo', jsonb_build_object('declared', coalesce(p.declaration -> 'slo', '{}'::jsonb),
                                'observed', coalesce((SELECT jsonb_object_agg(o.measure, jsonb_build_object('value', o.value, 'threshold', o.threshold, 'met', o.met, 'observed_at', o.observed_at))
                                                        FROM (SELECT DISTINCT ON (x.measure) x.* FROM products.slo_observations x WHERE x.product_id = p.product_id ORDER BY x.measure, x.observed_at DESC) o), '{}'::jsonb)),
      'consumers', (SELECT jsonb_build_object('registered', count(*) FILTER (WHERE c.state = 'registered'), 'accepted', count(*) FILTER (WHERE c.state = 'accepted'), 'revoked', count(*) FILTER (WHERE c.state = 'revoked'))
                      FROM products.product_consumers c WHERE c.product_id = p.product_id),
      'cost', (SELECT jsonb_build_object('amount', k.amount::text, 'currency', k.currency, 'period_start', k.period_start, 'period_end', k.period_end)
                 FROM products.cost_attributions k WHERE k.product_id = p.product_id ORDER BY k.period_end DESC, k.attributed_at DESC LIMIT 1),
      'scorecard', (SELECT jsonb_build_object('overall', s.overall, 'computed_at', s.computed_at, 'attainment_pct', s.attainment_pct) FROM products.scorecards s WHERE s.product_id = p.product_id ORDER BY s.computed_at DESC LIMIT 1),
      'governance', (SELECT jsonb_build_object('asset_id', a.asset_id, 'trusted', a.trusted, 'discoverable', a.discoverable,
                                               'authority', (SELECT jsonb_build_object('version', r.version, 'owner', r.owner_principal_id, 'owner_name', governance.dr_name(r.owner_principal_id),
                                                                                       'steward', r.steward_principal_id, 'steward_name', governance.dr_name(r.steward_principal_id), 'recertify_by', r.recertify_by)
                                                              FROM governance.data_authorities r WHERE r.authority_id = a.asset_id AND r.state = 'ratified'),
                                               'gaps', (SELECT count(*) FROM governance.ownership_gaps g WHERE g.subject_id = a.asset_id AND g.state IN ('open', 'escalated')),
                                               'holds', governance.dr_consumption_holds(a.asset_id) || governance.dr_consumption_holds(p.product_id))
                       FROM products.catalog_assets a WHERE a.tenant_id = p.tenant_id AND a.domain_id = p.domain_id AND a.kind = 'product' AND a.ref = p.product_id::text))
    ORDER BY p.product_key) FROM products.products_current p WHERE p.tenant_id = p_tenant AND p.domain_id = p_domain), '[]'::jsonb);
END $$;
REVOKE ALL ON FUNCTION governance.dr_products(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_products(uuid, uuid) TO eye_app, eye_commit;

/* THE RESPONSIBILITY PORTAL's database half (DAT-GV-10, PER-19): the CUSTOMER's duties (B94's approved matrix rows with their live owner
   resolution, the domain's registry entry, every catalog asset's authority state) and the PLATFORM's (component ownerships — team,
   contacts, operator role, owned contracts — and the data capabilities' owners; a platform operator inspects customer content only under an
   approved support purpose: B94's service.live_grant), the approvals (ratifications, acceptances, decisions — the ledger), the evidence
   records, the escalations (open gaps, escalated undecided cases). Nothing inferred: an undeclared duty reads undeclared. */
CREATE OR REPLACE FUNCTION governance.dr_portal(p_tenant uuid, p_domain uuid, p_profile text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, service, products, tenancy, public, pg_catalog, pg_temp AS $$
DECLARE m service.responsibility_matrices%ROWTYPE;
BEGIN
  PERFORM observation.assert_read_scope(p_tenant, p_domain, 'the responsibility portal');
  SELECT * INTO m FROM service.responsibility_matrices x WHERE x.tenant_id = p_tenant AND x.domain_id = p_domain AND x.deployment_profile = coalesce(p_profile, 'local-dev') AND x.state = 'approved';
  RETURN jsonb_build_object(
    'at', clock_timestamp(), 'profile', coalesce(p_profile, 'local-dev'),
    'domain', (SELECT jsonb_build_object('domain_id', d.id, 'name', d.name, 'status', d.status, 'governance_mode', governance.dr_domain_mode(d.id),
                                         'registry', (SELECT (to_jsonb(r) - 'scope' - 'correlation_id') || jsonb_build_object('leader_name', governance.dr_name(r.accountable_leader))
                                                        FROM governance.domain_registry r WHERE r.domain_id = d.id AND r.state = 'ratified'),
                                         'proposal', (SELECT (to_jsonb(r) - 'scope' - 'correlation_id') || jsonb_build_object('leader_name', governance.dr_name(r.accountable_leader))
                                                        FROM governance.domain_registry r WHERE r.domain_id = d.id AND r.state = 'proposed'))
                 FROM tenancy.domains d WHERE d.id = p_domain AND d.tenant_id = p_tenant),
    'customer_duties', jsonb_build_object(
       'matrix', CASE WHEN m.matrix_id IS NULL THEN jsonb_build_object('state', 'undeclared', 'reason', 'no approved responsibility matrix for this profile (B94 §SA)')
                      ELSE jsonb_build_object('state', 'approved', 'matrix_id', m.matrix_id, 'version', m.version, 'digest', m.digest, 'signature_id', m.signature_id) END,
       'responsibilities', CASE WHEN m.matrix_id IS NULL THEN '[]'::jsonb ELSE
         (SELECT coalesce(jsonb_agg(jsonb_build_object('key', rr.responsibility_key, 'title', rr.title, 'owner_role', rr.owner_role, 'operator_role', rr.operator_role, 'customer_authority', rr.customer_authority,
                                                       'escalation_path', rr.escalation_path, 'resolution', service.owner_resolution(p_tenant, p_domain, rr.responsibility_key, coalesce(p_profile, 'local-dev')))
                                    ORDER BY rr.responsibility_key), '[]'::jsonb)
            FROM service.responsibility_rows rr WHERE rr.matrix_id = m.matrix_id AND rr.version = m.version) END,
       'data_authorities', (SELECT coalesce(jsonb_agg(jsonb_build_object('asset_id', a.asset_id, 'kind', a.kind, 'ref', a.ref, 'title', a.title,
                                                    'state', CASE WHEN r.authority_id IS NOT NULL THEN 'ratified' WHEN pr.authority_id IS NOT NULL THEN 'proposed' ELSE 'undeclared' END,
                                                    'version', coalesce(r.version, pr.version), 'owner', r.owner_principal_id, 'owner_name', governance.dr_name(r.owner_principal_id),
                                                    'steward', r.steward_principal_id, 'steward_name', governance.dr_name(r.steward_principal_id), 'escalation_path', r.escalation_path,
                                                    'recertify_by', r.recertify_by, 'recertification', CASE WHEN r.recertify_by IS NULL THEN NULL WHEN r.recertify_by < clock_timestamp() THEN 'lapsed' ELSE 'current' END,
                                                    'proposal_digest', pr.digest, 'proposal_owner', pr.owner_principal_id, 'proposal_owner_accepted', pr.owner_accepted_at IS NOT NULL,
                                                    'proposed_by', pr.proposed_by, 'gaps', (SELECT count(*) FROM governance.ownership_gaps g WHERE g.subject_id = a.asset_id AND g.state IN ('open', 'escalated')))
                                                  ORDER BY (r.authority_id IS NULL AND pr.authority_id IS NULL), a.kind, a.title), '[]'::jsonb)
                              FROM products.catalog_assets a
                              LEFT JOIN governance.data_authorities r ON r.authority_id = a.asset_id AND r.state = 'ratified'
                              LEFT JOIN governance.data_authorities pr ON pr.authority_id = a.asset_id AND pr.state = 'proposed'
                             WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain)),
    'platform_duties', jsonb_build_object(
       'components', (SELECT coalesce(jsonb_agg(jsonb_build_object('component', o.component_key, 'kind', o.component_kind, 'owning_team', o.owning_team, 'version', o.version,
                                    'accountable_name', governance.dr_name(o.accountable_principal_id), 'primary_name', governance.dr_name(o.primary_contact), 'secondary_name', governance.dr_name(o.secondary_contact),
                                    'operator_role', o.operator_role, 'owned_contracts', to_jsonb(o.owned_contracts), 'failure_domain', o.failure_domain) ORDER BY o.component_key), '[]'::jsonb)
                        FROM governance.component_ownerships o WHERE o.superseded_at IS NULL),
       'capabilities', (SELECT coalesce(jsonb_agg(jsonb_build_object('dat_key', c.dat_key, 'title', c.title, 'owner_name', governance.dr_name(c.owner_principal_id), 'owner_role', c.owner_role,
                                    'conformance', c.conformance, 'admission', c.admission) ORDER BY c.dat_key), '[]'::jsonb)
                          FROM governance.data_capabilities c WHERE c.superseded_at IS NULL),
       'operator_rule', 'PER-19: a platform operator operates availability, capacity, change and recovery; it inspects customer content only under an approved support purpose — B94''s support grant, checked live (service.live_grant) in every port, every attempt logged; this portal shows duties, never the customer''s content'),
    'approvals', (SELECT coalesce(jsonb_agg(jsonb_build_object('event', e.event, 'subject_kind', e.subject_kind, 'subject_id', e.subject_id, 'version', e.version, 'actor', e.actor_principal_id,
                                                               'actor_name', governance.dr_name(e.actor_principal_id), 'at', e.occurred_at) ORDER BY e.occurred_at DESC), '[]'::jsonb)
                    FROM (SELECT * FROM governance.events x WHERE x.tenant_id = p_tenant AND x.domain_id = p_domain
                             AND x.event IN ('authority.owner_accepted', 'authority.ratified', 'authority.rejected', 'authority.recertified', 'domain.ratified', 'gap.accepted', 'case.decided',
                                             'evidence.attested', 'evidence.rejected') ORDER BY x.occurred_at DESC LIMIT 50) e),
    'evidence', (SELECT coalesce(jsonb_agg(jsonb_build_object('record_id', r.record_id, 'state', r.state, 'period_from', r.period_from, 'period_to', r.period_to, 'digest', r.digest, 'claim', r.claim,
                                                              'production_admission', r.production_admission, 'assembled_at', r.assembled_at, 'decided_by_name', governance.dr_name(r.decided_by),
                                                              'signature_id', r.signature_id) ORDER BY r.assembled_at DESC), '[]'::jsonb)
                   FROM governance.responsibility_evidence r WHERE r.tenant_id = p_tenant AND r.domain_id = p_domain),
    'escalations', jsonb_build_object(
       'gaps', (SELECT coalesce(jsonb_agg(jsonb_build_object('gap_id', g.gap_id, 'gap_kind', g.gap_kind, 'subject', g.subject_label, 'state', g.state, 'escalations', g.escalations,
                                                             'escalation_path', g.escalation_path, 'held', g.held, 'opened_at', g.opened_at) ORDER BY g.opened_at), '[]'::jsonb)
                  FROM governance.ownership_gaps g WHERE g.tenant_id = p_tenant AND g.domain_id = p_domain AND g.state IN ('open', 'escalated')),
       'cases', (SELECT coalesce(jsonb_agg(jsonb_build_object('case_ref', c.case_ref, 'kind', c.kind, 'consequence', c.consequence, 'escalation_level', c.escalation_level, 'due_at', c.due_at, 'title', c.title)
                                           ORDER BY c.due_at), '[]'::jsonb)
                   FROM governance.stewardship_cases c WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain AND c.state IN ('open', 'in_review') AND c.escalation_level > 0)));
END $$;
REVOKE ALL ON FUNCTION governance.dr_portal(uuid, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_portal(uuid, uuid, text) TO eye_app, eye_commit;

REVOKE ALL ON FUNCTION governance.dr_resolve(uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dr_resolve(uuid, uuid, uuid) TO eye_app, eye_commit;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DR.9 THE CARRIED B90 RESIDUALS (CP6_BATCHES §B90.9 #5)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- (a) DP-49-006 — THE LINEAGE-RETIREMENT PORT. The catalog ledger's vocabulary (0095 §K.2's list, copied whole) plus `lineage.retired` — B107 dr.
ALTER TABLE products.catalog_events DROP CONSTRAINT IF EXISTS catalog_events_event_check;
ALTER TABLE products.catalog_events ADD CONSTRAINT catalog_events_event_check CHECK (event IN (
  'asset.catalogued', 'asset.owner_set', 'asset.flagged', 'asset.flag_cleared', 'asset.reconciled', 'asset.recertified',
  'lineage.declared', 'term.defined', 'term.redefined', 'catalog.reconciled',
  -- B107 dr (0115 §DR.9)
  'lineage.retired'));

/* RETIRE A LINEAGE EDGE (products.catalog.lineage.retire): the steward's act, or either asset's owner's (as its declaration is) — the edge
   retired ONCE with its reason (the trigger of 0095 admits the retirement triple only), the RETIREMENT EVIDENCE on the catalog ledger
   (lineage.retired: the edge, its ends, the reason, the evidence the caller cites). Nothing is inferred from the retirement: lineage_missing
   and orphan are the next reconciliation's to find. */
CREATE OR REPLACE FUNCTION products.retire_lineage(p_edge_id uuid, p_tenant uuid, p_domain uuid, p_reason text, p_evidence jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
SECURITY DEFINER SET search_path = products, executive, identity, observation, ctx, public, pg_catalog, pg_temp AS $$
DECLARE e products.lineage_edges%ROWTYPE; f products.catalog_assets%ROWTYPE; t products.catalog_assets%ROWTYPE;
BEGIN
  PERFORM observation.assert_authority(ARRAY['products.catalog.lineage.retire']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'lineage rejected (actor): retired by the acting principal' USING ERRCODE = '42501'; END IF;
  SELECT * INTO e FROM products.lineage_edges x WHERE x.edge_id = p_edge_id AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'lineage rejected (unknown_edge): % is not a lineage edge of this domain', p_edge_id USING ERRCODE = '22023'; END IF;
  SELECT * INTO f FROM products.catalog_assets x WHERE x.asset_id = e.from_asset_id;
  SELECT * INTO t FROM products.catalog_assets x WHERE x.asset_id = e.to_asset_id;
  IF NOT executive.holds_role(p_actor, p_tenant, p_domain, ARRAY['data_steward', 'domain_admin', 'platform_admin']) AND f.owner_principal_id IS DISTINCT FROM p_actor AND t.owner_principal_id IS DISTINCT FROM p_actor THEN
    RAISE EXCEPTION 'lineage rejected (authority): lineage is retired by a data steward or by the owner of either asset' USING ERRCODE = '42501';
  END IF;
  IF e.retired_at IS NOT NULL THEN RAISE EXCEPTION 'lineage rejected (state): edge % was retired at % (%) — a retirement is set once', p_edge_id, e.retired_at, e.retirement_reason USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'lineage rejected (reason): a retirement says why (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_evidence IS NOT NULL AND jsonb_typeof(p_evidence) <> 'object' THEN RAISE EXCEPTION 'lineage rejected (evidence): the retirement evidence is an object' USING ERRCODE = '22023'; END IF;
  UPDATE products.lineage_edges SET retired_at = clock_timestamp(), retired_by = p_actor, retirement_reason = btrim(p_reason) WHERE edge_id = p_edge_id RETURNING * INTO e;
  PERFORM products.catalog_event(e.from_asset_id, p_tenant, p_domain, 'lineage.retired', p_actor,
            jsonb_build_object('edge_id', e.edge_id, 'from_asset_id', e.from_asset_id, 'to_asset_id', e.to_asset_id, 'kind', e.kind, 'declared_at', e.declared_at, 'reason', btrim(p_reason),
                               'evidence', coalesce(p_evidence, '{}'::jsonb), 'note', 'retirement evidence (DP-49-006); lineage coverage is the next reconciliation''s to judge'), p_correlation);
  RETURN (to_jsonb(e) - 'scope' - 'correlation_id') || jsonb_build_object('from_title', f.title, 'from_kind', f.kind, 'from_ref', f.ref, 'to_title', t.title, 'to_kind', t.kind, 'to_ref', t.ref);
END $$ LANGUAGE plpgsql;
REVOKE ALL ON FUNCTION products.retire_lineage(uuid, uuid, uuid, text, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION products.retire_lineage(uuid, uuid, uuid, text, jsonb, uuid, uuid) TO eye_commit;

-- (b) DP-49-005 — catalog_trust consulted by subscription registration and metric serving; (c) DP-41-005 — the degradation's declared cause.
/* B107 dr — re-declared WHOLE from 0095 §E.3 (its last definition); the changes are marked `B107 dr`.
   REGISTER A SUBSCRIPTION (products.subscription.register): the consumer's own act (or a steward's for a named consumer) on a RELEASED
   event product, under the AUTHORITY BOUNDARY — the consumer a named, active human of THIS tenant; the purpose one of the product's policy
   purposes; the granted fields a subset of the schema's; the time window instants or null; the consequence class named; the filters
   (event_kinds, ordering_keys, subject_ids, subject_kinds); the accepted schema version the product's current; the lag policy
   {max_lag_events, max_lag_seconds}; whether corrections and replays can be processed. Opens `registered`; the owner authorizes. */
CREATE OR REPLACE FUNCTION products.register_subscription(
  p_subscription_id uuid, p_product_id uuid, p_tenant uuid, p_domain uuid, p_consumer uuid, p_purpose text, p_granted jsonb, p_filters jsonb, p_schema_version text, p_lag_policy jsonb,
  p_handles_corrections boolean, p_handles_replays boolean, p_actor uuid, p_event_id uuid, p_correlation uuid
) RETURNS jsonb
SECURITY DEFINER SET search_path = products, executive, identity, observation, ctx, public, pg_catalog, pg_temp AS $$
DECLARE r products.products_current%ROWTYPE; ep products.event_products%ROWTYPE; s products.event_subscriptions%ROWTYPE; c identity.principals%ROWTYPE; e jsonb; v_from timestamptz; v_to timestamptz; k text;
        v_trust jsonb; v_holds jsonb;   -- B107 dr
BEGIN
  PERFORM observation.assert_authority(ARRAY['products.subscription.register']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'subscription rejected (actor): registered by the acting principal' USING ERRCODE = '42501'; END IF;
  IF p_consumer IS DISTINCT FROM p_actor AND NOT executive.holds_role(p_actor, p_tenant, p_domain, ARRAY['data_steward', 'domain_admin', 'platform_admin']) THEN
    RAISE EXCEPTION 'subscription rejected (authority): a subscription is registered by its consumer, or by a data steward for a named consumer' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO c FROM identity.principals x WHERE x.id = p_consumer;
  IF NOT FOUND THEN RAISE EXCEPTION 'subscription rejected (unknown_consumer): % is not a principal', p_consumer USING ERRCODE = '22023'; END IF;
  IF c.tenant_id IS DISTINCT FROM p_tenant OR c.kind <> 'human' OR c.status <> 'active' THEN
    RAISE EXCEPTION 'subscription rejected (authority): the authority boundary (DP-43-002) — a subscription is granted to a named, active human of this tenant; % is not one', p_consumer USING ERRCODE = '42501';
  END IF;
  SELECT * INTO r FROM products.products_current x WHERE x.product_id = p_product_id AND x.tenant_id = p_tenant AND x.domain_id = p_domain;
  IF NOT FOUND THEN RAISE EXCEPTION 'subscription rejected (unknown_product): % is not a product of this domain', p_product_id USING ERRCODE = '22023'; END IF;
  IF r.kind <> 'event' THEN RAISE EXCEPTION 'subscription rejected (kind): product % is of kind %; a subscription is on an event product', r.product_key, r.kind USING ERRCODE = '22023'; END IF;
  IF r.state NOT IN ('released', 'degraded') THEN RAISE EXCEPTION 'subscription rejected (state): product % is %; a subscription is registered on a released event product', r.product_key, r.state USING ERRCODE = '22023'; END IF;
  -- B107 dr (0115 §DR.9; DP-49-005): THE STOP OF NEW CONSUMPTION, wired — the product's catalog entry is consulted (catalog_trust: untrusted or
  -- undiscoverable stops a new subscription; an entry the catalog does not know is coverage debt, recorded on the event, not refused), and so
  -- are the governance holds on the product and its catalog entry (an ownership gap, an expired data exception, a conflict, a stewardship
  -- decision past its SLA — B107 §DR). Existing subscriptions are untouched (the stop is of NEW consumption).
  v_trust := products.catalog_trust('product', p_product_id::text);
  v_holds := governance.dr_consumption_holds(p_product_id) || CASE WHEN (v_trust ->> 'known')::boolean THEN governance.dr_consumption_holds((v_trust ->> 'asset_id')::uuid) ELSE '[]'::jsonb END;
  IF (v_trust ->> 'known')::boolean AND NOT ((v_trust ->> 'trusted')::boolean AND (v_trust ->> 'discoverable')::boolean) THEN
    RAISE EXCEPTION 'subscription rejected (state): product % is % in the catalog (flags: %) — new consumption stops until the catalog trusts it again (DP-49-005)', r.product_key,
      CASE WHEN NOT (v_trust ->> 'discoverable')::boolean THEN 'undiscoverable' ELSE 'untrusted' END,
      coalesce((SELECT string_agg(f ->> 'kind', ', ') FROM jsonb_array_elements(v_trust -> 'flags') f), 'none') USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(v_holds) > 0 THEN
    RAISE EXCEPTION 'subscription rejected (state): product % is held by governance (%) — new consumption stops until the hold is lifted (DP-49-005, DP-04-005)', r.product_key,
      (SELECT string_agg(DISTINCT h ->> 'reason_kind', ', ') FROM jsonb_array_elements(v_holds) h) USING ERRCODE = '22023';
  END IF;
  -- end B107 dr
  SELECT * INTO ep FROM products.event_products x WHERE x.product_id = p_product_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'subscription rejected (state): product % has no event declaration', r.product_key USING ERRCODE = '22023'; END IF;
  IF p_purpose IS NULL OR length(btrim(p_purpose)) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'subscription rejected (purpose): a subscription states its purpose' USING ERRCODE = '22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(coalesce(r.declaration #> '{policy,purposes}', '[]'::jsonb)) p WHERE p = btrim(p_purpose)) THEN
    RAISE EXCEPTION 'subscription rejected (purpose): purpose % is outside the product''s policy purposes (%)', btrim(p_purpose), (SELECT string_agg(p, ', ') FROM jsonb_array_elements_text(coalesce(r.declaration #> '{policy,purposes}', '[]'::jsonb)) p) USING ERRCODE = '22023';
  END IF;
  -- the DATA scope: fields ⊆ the schema's
  IF p_granted IS NULL OR jsonb_typeof(p_granted) <> 'object' OR jsonb_typeof(p_granted -> 'fields') <> 'array' OR jsonb_array_length(p_granted -> 'fields') = 0 THEN
    RAISE EXCEPTION 'subscription rejected (fields): the grant names the fields it needs (a non-empty subset of the schema''s: %)', array_to_string(ep.schema_fields, ', ') USING ERRCODE = '22023';
  END IF;
  FOR e IN SELECT x FROM jsonb_array_elements(p_granted -> 'fields') x LOOP
    IF jsonb_typeof(e) <> 'string' OR (e #>> '{}') <> ALL (ep.schema_fields) THEN
      RAISE EXCEPTION 'subscription rejected (fields): % is not a field of schema % (%); a subscription grants only declared data', e, ep.schema_version, array_to_string(ep.schema_fields, ', ') USING ERRCODE = '22023';
    END IF;
  END LOOP;
  -- the CONSEQUENCE class and the TIME window
  IF jsonb_typeof(p_granted -> 'consequence') <> 'string' OR (p_granted ->> 'consequence') NOT IN ('C0', 'C1', 'C2', 'C3', 'C4') THEN
    RAISE EXCEPTION 'subscription rejected (consequence): the grant names the consequence class the consumer may act on (C0..C4)' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_from := CASE WHEN jsonb_typeof(p_granted -> 'from') = 'string' THEN (p_granted ->> 'from')::timestamptz ELSE NULL END;
    v_to := CASE WHEN jsonb_typeof(p_granted -> 'to') = 'string' THEN (p_granted ->> 'to')::timestamptz ELSE NULL END;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'subscription rejected (window): the time window''s from and to are instants or null' USING ERRCODE = '22023'; END;
  IF (p_granted ? 'from' AND jsonb_typeof(p_granted -> 'from') NOT IN ('string', 'null')) OR (p_granted ? 'to' AND jsonb_typeof(p_granted -> 'to') NOT IN ('string', 'null')) OR (v_from IS NOT NULL AND v_to IS NOT NULL AND v_from >= v_to) THEN
    RAISE EXCEPTION 'subscription rejected (window): the time window''s from and to are instants or null, from before to' USING ERRCODE = '22023';
  END IF;
  -- the FILTERS
  IF p_filters IS NOT NULL AND jsonb_typeof(p_filters) <> 'object' THEN RAISE EXCEPTION 'subscription rejected (filters): the filters are an object {event_kinds?, ordering_keys?, subject_ids?, subject_kinds?}' USING ERRCODE = '22023'; END IF;
  FOR k IN SELECT jsonb_object_keys(coalesce(p_filters, '{}'::jsonb)) LOOP
    IF k NOT IN ('event_kinds', 'ordering_keys', 'subject_ids', 'subject_kinds') OR jsonb_typeof(p_filters -> k) <> 'array' THEN
      RAISE EXCEPTION 'subscription rejected (filters): % is not a filter (event_kinds, ordering_keys, subject_ids, subject_kinds — each an array)', k USING ERRCODE = '22023';
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(coalesce(p_filters -> 'event_kinds', '[]'::jsonb)) x WHERE x <> ALL (products.event_kinds())) THEN
    RAISE EXCEPTION 'subscription rejected (filters): an event kind filter names change, signal, correction, lifecycle, quality or strategic' USING ERRCODE = '22023';
  END IF;
  -- the SCHEMA version accepted, the LAG policy, the capabilities
  IF p_schema_version IS DISTINCT FROM ep.schema_version THEN
    RAISE EXCEPTION 'subscription rejected (schema): product % serves schema version %; a subscription accepts the current version (% was named)', r.product_key, ep.schema_version, coalesce(p_schema_version, 'null') USING ERRCODE = '22023';
  END IF;
  IF p_lag_policy IS NULL OR jsonb_typeof(p_lag_policy) <> 'object'
     OR jsonb_typeof(p_lag_policy -> 'max_lag_events') <> 'number' OR (p_lag_policy ->> 'max_lag_events') !~ '^[0-9]+$' OR (p_lag_policy ->> 'max_lag_events')::bigint < 1
     OR jsonb_typeof(p_lag_policy -> 'max_lag_seconds') <> 'number' OR (p_lag_policy ->> 'max_lag_seconds') !~ '^[0-9]+$' OR (p_lag_policy ->> 'max_lag_seconds')::bigint < 1 THEN
    RAISE EXCEPTION 'subscription rejected (lag_policy): the lag policy names max_lag_events and max_lag_seconds (whole numbers ≥ 1)' USING ERRCODE = '22023';
  END IF;
  IF p_handles_corrections IS NULL OR p_handles_replays IS NULL THEN RAISE EXCEPTION 'subscription rejected (capability): a subscription declares whether it can process corrections and replays' USING ERRCODE = '22023'; END IF;
  INSERT INTO products.event_subscriptions (subscription_id, product_id, tenant_id, domain_id, consumer_principal_id, consumer_domain_id, purpose, granted, filters, schema_version, lag_policy,
                                            handles_corrections, handles_replays, registered_by, correlation_id)
  VALUES (p_subscription_id, p_product_id, p_tenant, p_domain, p_consumer, coalesce(c.domain_id, p_domain), btrim(p_purpose),
          jsonb_build_object('fields', p_granted -> 'fields', 'consequence', p_granted ->> 'consequence', 'from', v_from, 'to', v_to),
          coalesce(p_filters, '{}'::jsonb), p_schema_version, jsonb_build_object('max_lag_events', (p_lag_policy ->> 'max_lag_events')::bigint, 'max_lag_seconds', (p_lag_policy ->> 'max_lag_seconds')::bigint),
          p_handles_corrections, p_handles_replays, p_actor, p_correlation) RETURNING * INTO s;
  INSERT INTO products.product_events (event_id, scope, tenant_id, domain_id, product_id, event, actor_principal_id, details, correlation_id)
  VALUES (p_event_id, 'DOMAIN', p_tenant, p_domain, p_product_id, 'subscription.registered', p_actor,
          jsonb_build_object('subscription_id', p_subscription_id, 'consumer', p_consumer, 'purpose', btrim(p_purpose), 'fields', p_granted -> 'fields', 'consequence', p_granted ->> 'consequence', 'schema_version', p_schema_version)
          || jsonb_build_object('catalog_trust', v_trust - 'flags'), p_correlation);   -- B107 dr: the trust read consulted, recorded
  RETURN products.subscription_json(s);
END $$ LANGUAGE plpgsql;
REVOKE ALL ON FUNCTION products.register_subscription(uuid,uuid,uuid,uuid,uuid,text,jsonb,jsonb,text,jsonb,boolean,boolean,uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION products.register_subscription(uuid,uuid,uuid,uuid,uuid,text,jsonb,jsonb,text,jsonb,boolean,boolean,uuid,uuid,uuid) TO eye_commit;

/* B107 dr — re-declared WHOLE from 0095 §M.5 (its last definition); the changes are marked `B107 dr`.
   SERVE (products.metric.serve; DAT-SV-04): the model by key; the version EFFECTIVE at the instant (the database's when none is given); the
   grain the model's or an override among the measure's grains; the filters the model's plus the caller's on the declared dimensions; the
   measure computed and answered per grain key WITH the grain, the unit, the version and digest, the SOURCE REVISION, the certification
   standing and expiry, the effective time, the instant. The EXECUTIVE view refuses an uncertified, withdrawn or expired model — dashboards
   are access modes; the ANALYST view serves it MARKED. Every serving is recorded; freshness_seconds is observed on the product. */
CREATE OR REPLACE FUNCTION products.serve_metric(
  p_serving_id uuid, p_tenant uuid, p_domain uuid, p_metric_key text, p_grain text, p_filters jsonb, p_as_of timestamptz, p_view text, p_actor uuid, p_correlation uuid
) RETURNS jsonb
SECURITY DEFINER SET search_path = products, executive, identity, observation, ctx, public, pg_catalog, pg_temp AS $$
DECLARE m products.semantic_models%ROWTYPE; r products.products_current%ROWTYPE; pv products.metric_versions%ROWTYPE; c products.metric_certifications%ROWTYPE;
        v_spec jsonb; v_grain text; v_filters jsonb; v_as_of timestamptz; v_now timestamptz := clock_timestamp(); v_certified boolean; k text;
        v_rows jsonb; v_revision text; v_n int; v_newest timestamptz; v_digest text; v_fresh numeric; v_threshold numeric; v_standing text;
        v_trust jsonb; v_holds jsonb; v_stopped text;   -- B107 dr
BEGIN
  PERFORM observation.assert_authority(ARRAY['products.metric.serve']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'metric rejected (actor): served to the acting principal' USING ERRCODE = '42501'; END IF;
  IF p_view IS NULL OR p_view NOT IN ('executive', 'analyst') THEN RAISE EXCEPTION 'metric rejected (view): a metric is served in the executive or the analyst view' USING ERRCODE = '22023'; END IF;
  SELECT * INTO m FROM products.semantic_models x WHERE x.metric_key = p_metric_key AND x.tenant_id = p_tenant AND x.domain_id = p_domain;
  IF NOT FOUND THEN RAISE EXCEPTION 'metric rejected (unknown_metric): % is not a semantic model of this domain', coalesce(p_metric_key, 'null') USING ERRCODE = '22023'; END IF;
  SELECT * INTO r FROM products.products_current x WHERE x.product_id = m.model_id;
  IF r.state IN ('withdrawn', 'retired') THEN RAISE EXCEPTION 'metric rejected (state): product % is %; nothing is served from it', r.product_key, r.state USING ERRCODE = '22023'; END IF;
  -- B107 dr (0115 §DR.9; DP-49-005): THE STOP OF NEW CONSUMPTION, wired — the metric product's catalog entry (catalog_trust) and its governance
  -- holds: the EXECUTIVE view refuses an untrusted, undiscoverable or held metric (a basis for an executive report must be trusted); the
  -- ANALYST view serves it MARKED. An entry the catalog does not know is coverage debt: served, said.
  v_trust := products.catalog_trust('product', m.model_id::text);
  v_holds := governance.dr_consumption_holds(m.model_id) || CASE WHEN (v_trust ->> 'known')::boolean THEN governance.dr_consumption_holds((v_trust ->> 'asset_id')::uuid) ELSE '[]'::jsonb END;
  v_stopped := CASE WHEN (v_trust ->> 'known')::boolean AND NOT (v_trust ->> 'discoverable')::boolean THEN 'undiscoverable in the catalog'
                    WHEN (v_trust ->> 'known')::boolean AND NOT (v_trust ->> 'trusted')::boolean THEN 'untrusted in the catalog'
                    WHEN jsonb_array_length(v_holds) > 0 THEN 'held by governance (' || (SELECT string_agg(DISTINCT h ->> 'reason_kind', ', ') FROM jsonb_array_elements(v_holds) h) || ')' END;
  IF p_view = 'executive' AND v_stopped IS NOT NULL THEN
    RAISE EXCEPTION 'metric rejected (state): metric % is % — the executive view stops new consumption of it (DP-49-005); the analyst view serves it marked', m.metric_key, v_stopped USING ERRCODE = '22023';
  END IF;
  -- end B107 dr
  v_as_of := date_trunc('milliseconds', coalesce(p_as_of, v_now));   -- millisecond precision: the instant round-trips through a caller's ISO 8601 string
  IF v_as_of > v_now THEN RAISE EXCEPTION 'metric rejected (as_of): the instant is not in the future (asked %, now %)', v_as_of, v_now USING ERRCODE = '22023'; END IF;
  SELECT * INTO pv FROM products.metric_versions x WHERE x.model_id = m.model_id AND x.effective_from <= v_as_of ORDER BY x.effective_from DESC, x.version DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'metric rejected (effective): no definition of metric % is effective at % (the first is effective from %)', m.metric_key, v_as_of, m.effective_from USING ERRCODE = '22023'; END IF;
  SELECT * INTO c FROM products.metric_certifications x WHERE x.model_id = m.model_id AND x.state = 'active' ORDER BY x.certified_at DESC LIMIT 1;
  v_certified := m.state = 'certified' AND c.certification_id IS NOT NULL AND c.version = pv.version AND c.expires_at > v_now;
  v_standing := CASE WHEN v_certified THEN 'certified' WHEN m.state = 'certified' AND c.version <> pv.version THEN 'certified at another version (' || c.version || '); version ' || pv.version || ' is effective at the instant'
                     WHEN m.state = 'certified' THEN 'certification past its expiry (' || c.expires_at || '), not yet swept' ELSE m.state END;
  IF p_view = 'executive' AND NOT v_certified THEN
    RAISE EXCEPTION 'metric rejected (certification): metric % is % — the executive view serves certified metrics only (dashboards are access modes); the analyst view serves it marked uncertified', m.metric_key, v_standing USING ERRCODE = '22023';
  END IF;
  v_spec := products.metric_measures() -> (pv.definition ->> 'measure');
  v_grain := coalesce(p_grain, pv.definition ->> 'grain');
  IF NOT (v_spec -> 'grains' ? v_grain) THEN
    RAISE EXCEPTION 'metric rejected (grain): measure % allows the grains %; % is not among them', pv.definition ->> 'measure', (SELECT string_agg(x, ', ') FROM jsonb_array_elements_text(v_spec -> 'grains') x), v_grain USING ERRCODE = '22023';
  END IF;
  IF p_filters IS NOT NULL AND jsonb_typeof(p_filters) <> 'object' THEN RAISE EXCEPTION 'metric rejected (filter): filters are an object of dimension → value' USING ERRCODE = '22023'; END IF;
  FOR k IN SELECT x FROM jsonb_object_keys(coalesce(p_filters, '{}'::jsonb)) x LOOP
    IF NOT (pv.definition -> 'dimensions' ? k) THEN RAISE EXCEPTION 'metric rejected (filter): filter % is not a dimension of metric % (%)', k, m.metric_key, (SELECT string_agg(x, ', ') FROM jsonb_array_elements_text(pv.definition -> 'dimensions') x) USING ERRCODE = '22023'; END IF;
    IF jsonb_typeof(p_filters -> k) NOT IN ('string', 'number', 'boolean') THEN RAISE EXCEPTION 'metric rejected (filter): filter % is a scalar value', k USING ERRCODE = '22023'; END IF;
  END LOOP;
  v_filters := (pv.definition -> 'filters') || coalesce(p_filters, '{}'::jsonb);
  CASE pv.definition ->> 'measure'
    WHEN 'measure_observations' THEN
      SELECT coalesce(jsonb_agg(jsonb_build_object('grain_key', x.grain_key, 'value', x.value) ORDER BY x.grain_key), '[]'::jsonb), max(x.source_revision), max(x.source_rows), max(x.source_newest_at)
        INTO v_rows, v_revision, v_n, v_newest FROM products.measure_measure_observations(p_tenant, p_domain, v_grain, v_filters, v_as_of, pv.definition ->> 'aggregation') x;
    WHEN 'health_score' THEN
      SELECT coalesce(jsonb_agg(jsonb_build_object('grain_key', x.grain_key, 'value', x.value) ORDER BY x.grain_key), '[]'::jsonb), max(x.source_revision), max(x.source_rows), max(x.source_newest_at)
        INTO v_rows, v_revision, v_n, v_newest FROM products.measure_health_score(p_tenant, p_domain, v_grain, v_filters, v_as_of, pv.definition ->> 'aggregation') x;
    WHEN 'exposure_eur_at_risk' THEN
      SELECT coalesce(jsonb_agg(jsonb_build_object('grain_key', x.grain_key, 'value', x.value) ORDER BY x.grain_key), '[]'::jsonb), max(x.source_revision), max(x.source_rows), max(x.source_newest_at)
        INTO v_rows, v_revision, v_n, v_newest FROM products.measure_exposure_eur_at_risk(p_tenant, p_domain, v_grain, v_filters, v_as_of, pv.definition ->> 'aggregation') x;
    ELSE RAISE EXCEPTION 'metric rejected (measure): % is not a whitelisted measure', pv.definition ->> 'measure' USING ERRCODE = '22023';
  END CASE;
  -- an empty result set still has a revision (the sha256 of nothing read) and no freshness
  IF v_revision IS NULL THEN v_revision := encode(digest('', 'sha256'), 'hex'); v_n := 0; END IF;
  v_digest := encode(digest(v_rows::text, 'sha256'), 'hex');
  INSERT INTO products.metric_servings (serving_id, model_id, tenant_id, domain_id, version, view, grain, filters, as_of, certified, source_revision, source_rows, value_digest, result, served_to, served_at, correlation_id)
  VALUES (p_serving_id, m.model_id, p_tenant, p_domain, pv.version, p_view, v_grain, v_filters, v_as_of, v_certified, v_revision, v_n, v_digest, v_rows, p_actor, v_now, p_correlation);
  IF v_newest IS NOT NULL THEN
    v_fresh := extract(epoch FROM (v_now - v_newest));
    v_threshold := CASE WHEN jsonb_typeof(r.declaration #> '{slo,freshness_seconds}') = 'number' THEN (r.declaration #>> '{slo,freshness_seconds}')::numeric ELSE NULL END;
    PERFORM products.observe_slo(gen_random_uuid(), m.model_id, p_tenant, p_domain, 'freshness_seconds', v_fresh, v_threshold, v_threshold IS NULL OR v_fresh <= v_threshold, 'metric serve (§M)',
                                 jsonb_build_object('serving_id', p_serving_id, 'view', p_view, 'grain', v_grain, 'as_of', v_as_of, 'source_newest_at', v_newest), p_actor, p_correlation);
  END IF;
  RETURN jsonb_build_object(
    'serving_id', p_serving_id, 'model_id', m.model_id, 'metric_key', m.metric_key, 'title', m.title, 'view', p_view,
    'version', pv.version, 'digest', pv.digest, 'effective_from', pv.effective_from, 'measure', pv.definition ->> 'measure', 'unit', pv.definition ->> 'unit', 'aggregation', pv.definition ->> 'aggregation',
    'grain', v_grain, 'filters', v_filters, 'as_of', v_as_of, 'served_at', v_now,
    'certified', v_certified, 'certification_standing', v_standing,
    'certification', CASE WHEN c.certification_id IS NULL THEN NULL ELSE jsonb_build_object('certification_id', c.certification_id, 'version', c.version, 'certified_by', c.certified_by, 'certified_at', c.certified_at, 'expires_at', c.expires_at, 'signature_id', c.signature_id, 'state', c.state) END,
    'last_valid_version', m.last_valid_version,
    'source', v_spec ->> 'source', 'source_revision', v_revision, 'source_rows', v_n, 'source_newest_at', v_newest, 'freshness_seconds', v_fresh,
    'values', v_rows, 'value_digest', v_digest,
    'note', CASE WHEN v_certified THEN 'certified — served as the executive view would' ELSE 'UNCERTIFIED (' || v_standing || ') — served in the analyst view only; not a basis for an executive report' END)
    -- B107 dr: the catalog's trust and the governance holds consulted, and the mark when consumption is stopped
    || jsonb_build_object('catalog_trust', v_trust - 'flags', 'governance_holds', v_holds, 'consumption',
         CASE WHEN v_stopped IS NULL THEN CASE WHEN (v_trust ->> 'known')::boolean THEN 'trusted' ELSE 'not catalogued — coverage debt (DP-49-006)' END
              ELSE 'STOPPED for new consumption: ' || v_stopped || ' — served in the analyst view only, marked' END);
END $$ LANGUAGE plpgsql;
REVOKE ALL ON FUNCTION products.serve_metric(uuid,uuid,uuid,text,text,jsonb,timestamptz,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION products.serve_metric(uuid,uuid,uuid,text,text,jsonb,timestamptz,text,uuid,uuid) TO eye_commit;

/* B107 dr — re-declared WHOLE from 0095 §R.4 (its last definition); the changes are marked `B107 dr`.
   DEGRADE (products.product.degrade — the owner or a steward — OR executive.attention.tick — the step, after grace_ticks consecutive
   below-floor scorecards): released → degraded with a reason, NEVER silently: every ACCEPTED consumer gets an attention item of class
   product.degradation (subject kind product), routed to the consumer when it is an active human, else by the class's roles under the
   active policy (0094 §D's idiom for raising an item from a port); the event names every item raised. */
CREATE OR REPLACE FUNCTION products.degrade_product(
  p_product_id uuid, p_tenant uuid, p_domain uuid, p_reason text, p_actor uuid, p_event_id uuid, p_correlation uuid
) RETURNS jsonb
SECURITY DEFINER SET search_path = products, executive, identity, observation, decision, ctx, public, pg_catalog, pg_temp AS $$
DECLARE r products.products_current%ROWTYPE; c record; pol executive.attention_policies%ROWTYPE; v_now timestamptz := clock_timestamp(); v_by_tick boolean := public.eye_bound_action() = 'executive.attention.tick';
        v_item uuid; v_cause uuid; v_owner uuid; v_eval jsonb; v_route jsonb; v_state text; v_notified jsonb := '[]'::jsonb;
        v_by text;   -- B107 dr
BEGIN
  PERFORM observation.assert_authority(ARRAY['products.product.degrade', 'executive.attention.tick']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'data product rejected (actor): degraded by the acting principal' USING ERRCODE = '42501'; END IF;
  SELECT * INTO r FROM products.products_current x WHERE x.product_id = p_product_id AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data product rejected (unknown_product): % is not a product of this domain', p_product_id USING ERRCODE = '22023'; END IF;
  IF NOT v_by_tick AND p_actor <> r.owner_principal_id AND NOT executive.holds_role(p_actor, p_tenant, p_domain, ARRAY['data_steward', 'domain_admin', 'platform_admin']) THEN
    RAISE EXCEPTION 'data product rejected (authority): a product is degraded by its owner, by a data steward, or by the attention tick' USING ERRCODE = '42501';
  END IF;
  IF r.state <> 'released' THEN RAISE EXCEPTION 'data product rejected (state): product % is %; a released product degrades', r.product_key, r.state USING ERRCODE = '22023'; END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 8 THEN RAISE EXCEPTION 'data product rejected (reason): a degradation names its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  -- B107 dr (0115 §DR.9; DP-41-005): DEGRADATION DECLARED BY THE PRODUCT on the loss of its owner or a recorded policy violation — when the
  -- TICK degrades, the cause is read from the record (the owner no longer an active human of the tenant; an APPROVED access or classification
  -- stewardship case on the product = a confirmed policy violation), else the SLO (the scorecard step). `by` carries it: only a degradation
  -- `by` = 'tick' (the SLO) is restored by a later ok scorecard; an owner loss or a policy violation is restored through an accepted domain
  -- review, as a person's degradation is (restore_product reads `by`).
  v_by := CASE WHEN NOT v_by_tick THEN 'human'
               WHEN NOT decision.is_active_human(r.owner_principal_id, p_tenant) THEN 'owner_lost'
               WHEN EXISTS (SELECT 1 FROM governance.stewardship_cases sc WHERE sc.subject_kind = 'product' AND sc.subject_id = p_product_id AND sc.kind IN ('access', 'classification') AND sc.state = 'approved') THEN 'policy_violation'
               ELSE 'tick' END;
  -- end B107 dr
  UPDATE products.products_current SET state = 'degraded', degraded_reason = btrim(p_reason), degraded_at = v_now, updated_at = v_now WHERE product_id = p_product_id RETURNING * INTO r;
  SELECT * INTO pol FROM executive.attention_policies a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.state = 'active';
  FOR c IN SELECT x.* FROM products.product_consumers x WHERE x.product_id = p_product_id AND x.state = 'accepted' ORDER BY x.registered_at LOOP
    v_item := gen_random_uuid(); v_cause := gen_random_uuid();
    v_owner := CASE WHEN decision.is_active_human(c.consumer_principal_id, p_tenant) THEN c.consumer_principal_id END;
    v_eval := executive.evaluate_attention(CASE WHEN pol.policy_id IS NULL THEN NULL ELSE pol.rules END, 'product.degradation',
                                           jsonb_build_object('consequence', 'C2', 'confidence', 1, 'hours_to_window', 0)) || jsonb_build_object('policy_version', pol.version);
    v_route := executive.attention_route(pol.rules, 'product.degradation', v_eval ->> 'outcome', v_owner, p_tenant, p_domain);
    v_state := v_route ->> 'state';
    INSERT INTO executive.attention_items (item_id, scope, tenant_id, domain_id, signal_class, subject_kind, subject_id, cause_event_id, cause_event_type, title, outcome, state,
                                           owner_principal_id, route_roles, policy_id, policy_version, evaluation, details, due_at, escalations, correlation_id)
    VALUES (v_item, 'DOMAIN', p_tenant, p_domain, 'product.degradation', 'product', p_product_id, v_cause, 'ProductDegraded',
            left(format('Product %s DEGRADED: %s', r.product_key, btrim(p_reason)), 512), v_eval ->> 'outcome', v_state,
            v_owner, ARRAY(SELECT jsonb_array_elements_text(v_route -> 'route_roles')), pol.policy_id, pol.version, v_eval,
            jsonb_build_object('product_id', p_product_id, 'product_key', r.product_key, 'consumer_id', c.consumer_id, 'consumer_principal_id', c.consumer_principal_id, 'contract_version', c.contract_version,
                               'impact', c.impact, 'reason', btrim(p_reason), 'last_valid_version', r.released_version, 'raised_at', v_now,
                               'by', CASE v_by WHEN 'tick' THEN 'the attention tick step product-scorecards' WHEN 'owner_lost' THEN 'the attention tick: the product''s owner is lost (B107 §DR)'
                                               WHEN 'policy_violation' THEN 'the attention tick: a policy violation is recorded (B107 §DR)' ELSE 'the degradation port' END),   -- B107 dr
            (v_route ->> 'due_at')::timestamptz, (v_route ->> 'escalations')::int, p_correlation);
    PERFORM executive.attention_event(v_item, p_tenant, p_domain,
              CASE v_state WHEN 'open' THEN 'item.routed' WHEN 'escalated' THEN 'item.escalated' WHEN 'unrouted' THEN 'item.unrouted' ELSE 'item.deprioritized' END,
              p_actor, jsonb_build_object('outcome', v_eval ->> 'outcome', 'reasons', v_eval -> 'reasons', 'policy_version', pol.version, 'owner', v_owner, 'route_roles', v_route -> 'route_roles',
                                          'due_at', v_route -> 'due_at', 'cause_event_id', v_cause, 'cause_event_type', 'ProductDegraded', 'unrouted', coalesce((v_route ->> 'unrouted')::boolean, false)), p_correlation);
    v_notified := v_notified || jsonb_build_object('consumer_id', c.consumer_id, 'consumer_principal_id', c.consumer_principal_id, 'item_id', v_item, 'state', v_state, 'owner', v_owner);
  END LOOP;
  INSERT INTO products.product_events (event_id, scope, tenant_id, domain_id, product_id, event, actor_principal_id, details, correlation_id)
  VALUES (p_event_id, 'DOMAIN', p_tenant, p_domain, p_product_id, 'product.degraded', p_actor,
          jsonb_build_object('reason', btrim(p_reason), 'by', v_by, 'notified', v_notified, 'released_version', r.released_version), p_correlation);   -- B107 dr: the declared cause
  RETURN products.product_json(r) || jsonb_build_object('notified', v_notified);
END $$ LANGUAGE plpgsql;
REVOKE ALL ON FUNCTION products.degrade_product(uuid,uuid,uuid,text,uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION products.degrade_product(uuid,uuid,uuid,text,uuid,uuid,uuid) TO eye_commit;

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- RLS AND GRANTS (§DR's tables). DOMAIN rows (authorities, the domain registry, cases, evidence, a domain's gaps) under the domain isolation
-- idiom — NO PLATFORM-sees-all clause: a platform operator never reads a customer's stewardship content (PER-19; content only under B94's
-- support grant). PLATFORM rows (data capabilities, component ownerships and transfers, PLATFORM gaps) are readable by every authenticated
-- context (the vendor's registries are not tenant data). SELECT to eye_app and eye_commit; no write grant — the definer ports write.
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['governance.data_authorities', 'governance.domain_registry', 'governance.stewardship_cases', 'governance.responsibility_evidence'] LOOP
    EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', t);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($f$CREATE POLICY domain_isolation ON %s USING (tenant_id = public.eye_tenant() AND (public.eye_scope() = 'TENANT' OR domain_id = public.eye_domain()))$f$, t);
    EXECUTE format('GRANT SELECT ON %s TO eye_app, eye_commit', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['governance.data_capabilities', 'governance.component_ownerships', 'governance.component_transfers'] LOOP
    EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', t);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($f$CREATE POLICY platform_registry ON %s USING (public.eye_scope() <> 'NONE')$f$, t);
    EXECUTE format('GRANT SELECT ON %s TO eye_app, eye_commit', t);
  END LOOP;
  REVOKE ALL ON governance.ownership_gaps FROM PUBLIC;
  ALTER TABLE governance.ownership_gaps ENABLE ROW LEVEL SECURITY;
  ALTER TABLE governance.ownership_gaps FORCE ROW LEVEL SECURITY;
  CREATE POLICY gap_visibility ON governance.ownership_gaps USING (
    (scope = 'PLATFORM' AND public.eye_scope() <> 'NONE')
    OR (scope = 'DOMAIN' AND tenant_id = public.eye_tenant() AND (public.eye_scope() = 'TENANT' OR domain_id = public.eye_domain())));
  GRANT SELECT ON governance.ownership_gaps TO eye_app, eye_commit;
END $$;


-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §PG — the product-governance workspace: baseline and decision rights, the one exception registry, conflicts, change proposals, the governance registry (F-P7-F-12, F-P7D-25)
-- (folded at integration from the part-local file 0115_b107_x_pg.sql, unchanged but for the marked `B107 integration` edits; apply order §0, §RG, §CM, §DR, §PG, §AR, §DG)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 0115 §PG — CP-6 B107: THE PRODUCT-GOVERNANCE WORKSPACE (F-P7-F-12 the product governance workspace; F-P7D-25's exception service,
-- conflict register, change control and governance registry). Applies ALONE on top of 0001–0114 + the prelude (0115 §0). Nothing earlier is
-- re-declared; every object here is new and prefixed `ws_` (the module/PDP block `workspace`), except the ONE shared PLATFORM-signing port
-- `governance.record_platform_signature` that every part may call after the fold (its TS twin: src/governance/workspace/platform-signing.ts).
--
--   §PG.1 THE SHARED PLATFORM SIGNATURE PORT — a named human's Ed25519 signature (the SignatureService key path) recorded in the prelude's
--         governance.signatures under the CALLER's bound action.
--   §PG.2 THE PRODUCT BASELINE (PR-01-001/-002/-005, CAP-AU-01/-02, ADR-005): the capability inventory read from the capability ARTIFACTS
--         (§RG imports them), ONE accountable owner per capability with its domain boundary, the DECISION-RIGHTS matrix (CAP-AU-03: propose /
--         review / approve / operate / audit; singular approver; separation of duties; delegation) and the SIGNED baseline decision — which is
--         also the executive baseline attestation (IA-72-006 / DP-72-006): it binds the exact scope tuple, the exception ageing and the
--         conformance trend. HELD while authority is unresolved (an orphan or duplicate capability, a lapsed owner, no signed rights, an open
--         conflict) — the disputed state preserved and shown, never represented as resolved.
--   §PG.3 THE ONE EXCEPTION REGISTRY (V03-T-451/-453, ES-02-004, DAT-GV-08, CAP-AU-10): every V03-T-453 field; an INDEPENDENT approver (never
--         the proposer, never the owner, never the owner of the component whose authority the exception expands); constitutional
--         boundaries unwaivable (a closed list); EXPIRY → `expired` and every affected artifact (the release candidate, a data release) HELD
--         (governance.holds `exception_expired`) until a renewal with CURRENT evidence is approved independently (or the exception is closed on
--         its exit criteria); ageing; REPEATS → a remediation review that holds further approvals on the contract until decided. The
--         repository's EXCEPTIONS.md and the C15 SCX records are NOT here: read-only, reported by the workspace (src/governance/workspace/
--         repository-registers.ts) — never governed, renewed, closed or expired by the product.
--   §PG.4 THE CONFLICT REGISTER (FEX-32, IA-02-005, DP-02-005): a conflict HOLDS every affected release at the LAST CONFORMANT candidate,
--         selects the highest authority, exposes the impacted requirements and journeys; resolved only by the governing authority (SIGNED
--         `conflict_resolution`) by closure (the highest authority prevails) or amendment (an approved change proposal) — and the trace closes
--         (the prevailing artifact `governs` every impacted one; the superseded meaning linked `supersedes`).
--   §PG.5 CHANGE PROPOSALS (ES-72-003, PR-72-002/-003): consumer impact, compatibility, migration, replay, rollback and evidence plans required
--         BEFORE approval; the deterministic impact (dependents through the live links, ordered, digested — recomputed at approval: a changed
--         impact is stale); constitutional, identity-altering or cross-volume change needs the authority CHAIN (product authority AND
--         independent assurance); a subject under an open conflict or hold is held (IA-72-005, PR-72-005). SIGNED `change_approval`.
--   §PG.6 THE GOVERNANCE REGISTRY (ES-72-001/-005, IA-72-001/-002, INF-DL-08, DP-72-001/-002, DAT-GV-06): decision records, standards,
--         technical debt (decision-active risk with objectives, customers, consequences, owner, due date, investment, VERIFIED closure) and
--         deprecations — accountable owner, approving authority, lifecycle, version, effective time, dependencies, review cadence, supersession,
--         controlled amendment, retirement proof; THE POSTURE (declared vs observed, every dimension conformant | non_conformant | unknown —
--         never inferred healthy) and its versioned snapshots.
--
-- THREE CLAIMS, never mixed: CONSTRUCTION (this migration, its ports and phase6-workspace-b107); DEMONSTRATED OPERATION (the act — every
-- record here `claim = 'demonstration'`, the CHECK admits nothing else); REAL ACCEPTANCE (named product owners and independent release
-- authorities, executive attestation in production: H3 / R1) — never claimed, and no row here can carry it.
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- §PG.0 VOCABULARIES AND INTERNAL HELPERS ──────────────────────────────────────────────────────────────────────────────────────────────────
CREATE SEQUENCE IF NOT EXISTS governance.ws_ref_seq;

/* The constitutional boundaries no ordinary exception may waive (EXCEPTIONS.md's rigor rule + the product's own): closed list. */
CREATE OR REPLACE FUNCTION governance.ws_constitutional_invariants() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'human_authority', 'provenance', 'temporal_truth', 'tenant_isolation', 'append_only_audit', 'tamper_detection', 'fail_closed_authorization',
  'explainability', 'claim_separation', 'separation_of_duties', 'supply_chain_authorization'] $$;
/* The governed act classes a decision-rights matrix covers (besides capability keys), and the duties. */
CREATE OR REPLACE FUNCTION governance.ws_act_classes() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'baseline', 'decision_rights', 'exception', 'conflict', 'change', 'record', 'release'] $$;
CREATE OR REPLACE FUNCTION governance.ws_duties() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY['propose', 'review', 'approve', 'operate', 'audit'] $$;
/* The classes a baseline's rights must cover with an approver before it can be signed. */
CREATE OR REPLACE FUNCTION governance.ws_required_classes() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY['baseline', 'exception', 'change', 'conflict'] $$;
CREATE OR REPLACE FUNCTION governance.ws_governance_roles() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'product_authority', 'design_system_authority', 'independent_assurance', 'operations_authority', 'conformance_steward'] $$;
/* THE AUTHORITY RANK (the declared rule a conflict uses to select the highest authority; the owner may revise): the artifact's authority
   class (constitutional 1 · controlling 2 · normative 3 · informative 4 · anything else / none 5), then the controlling volume (V0 before V9),
   then the earliest effective time. */
CREATE OR REPLACE FUNCTION governance.ws_authority_rank(p_class text) RETURNS int LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE lower(coalesce(p_class, '')) WHEN 'constitutional' THEN 1 WHEN 'controlling' THEN 2 WHEN 'normative' THEN 3 WHEN 'informative' THEN 4 ELSE 5 END $$;
GRANT EXECUTE ON FUNCTION governance.ws_constitutional_invariants(), governance.ws_act_classes(), governance.ws_duties(), governance.ws_required_classes(),
  governance.ws_governance_roles(), governance.ws_authority_rank(text) TO eye_app, eye_commit;

CREATE OR REPLACE FUNCTION governance.ws_next_ref(p_prefix text) RETURNS text
LANGUAGE sql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$ SELECT p_prefix || '-' || lpad(nextval('governance.ws_ref_seq')::text, 4, '0') $$;
REVOKE ALL ON FUNCTION governance.ws_next_ref(text) FROM PUBLIC;

/* Is the principal an active human? */
CREATE OR REPLACE FUNCTION governance.ws_is_human(p uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = identity, pg_catalog, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM identity.principals x WHERE x.id = p AND x.kind = 'human' AND x.status = 'active') $$;
REVOKE ALL ON FUNCTION governance.ws_is_human(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_is_human(uuid) TO eye_app, eye_commit;

/* A principal's display name (vendor-side registries name their people; read through a definer, as products.catalog_principal_name does for a tenant). */
CREATE OR REPLACE FUNCTION governance.ws_principal_name(p uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = identity, pg_catalog, pg_temp AS $$
  SELECT x.display_name FROM identity.principals x WHERE x.id = p $$;
REVOKE ALL ON FUNCTION governance.ws_principal_name(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_principal_name(uuid) TO eye_app, eye_commit;

/* REGISTER an object of this part as a PLATFORM artifact (artifact_id = the object's id): a new version, the previous one superseded. */
CREATE OR REPLACE FUNCTION governance.ws_register(p_id uuid, p_kind text, p_key text, p_title text, p_owner uuid, p_owner_role text, p_authority_class text, p_volume text,
                                                  p_lifecycle text, p_attributes jsonb, p_digest text, p_actor uuid, p_correlation uuid) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v int;
BEGIN
  SELECT coalesce(max(a.version), 0) INTO v FROM governance.artifacts a WHERE a.artifact_id = p_id;
  UPDATE governance.artifacts SET superseded_at = clock_timestamp() WHERE artifact_id = p_id AND superseded_at IS NULL;
  INSERT INTO governance.artifacts (artifact_id, version, scope, kind, external_key, title, owner_principal_id, owner_role, authority_class, controlling_volume, lifecycle, attributes, source,
                                    digest, recorded_by, correlation_id)
  VALUES (p_id, v + 1, 'PLATFORM', p_kind, p_key, left(p_title, 500), p_owner, p_owner_role, p_authority_class, p_volume, p_lifecycle, coalesce(p_attributes, '{}'::jsonb),
          jsonb_build_object('part', '§PG', 'claim', 'demonstration'), p_digest, p_actor, p_correlation);
  RETURN v + 1;
END $$;
REVOKE ALL ON FUNCTION governance.ws_register(uuid, text, text, text, uuid, text, text, text, text, jsonb, text, uuid, uuid) FROM PUBLIC;

/* LINK two artifacts (PLATFORM) unless the same live link stands; returns the link id (new or standing). */
CREATE OR REPLACE FUNCTION governance.ws_link(p_from uuid, p_to uuid, p_relation text, p_attributes jsonb, p_actor uuid, p_correlation uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v uuid;
BEGIN
  IF p_from = p_to THEN RETURN NULL; END IF;
  SELECT l.link_id INTO v FROM governance.links_live l WHERE l.from_artifact = p_from AND l.to_artifact = p_to AND l.relation = p_relation AND l.scope = 'PLATFORM' LIMIT 1;
  IF v IS NOT NULL THEN RETURN v; END IF;
  v := gen_random_uuid();
  INSERT INTO governance.links (link_id, scope, from_artifact, to_artifact, relation, attributes, recorded_by, correlation_id)
  VALUES (v, 'PLATFORM', p_from, p_to, p_relation, coalesce(p_attributes, '{}'::jsonb) || jsonb_build_object('part', '§PG'), p_actor, p_correlation);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.ws_link(uuid, uuid, text, jsonb, uuid, uuid) FROM PUBLIC;

/* OPEN a hold on a subject artifact (PLATFORM) unless the same hold (subject + source + reason kind) is open; returns the hold id. */
CREATE OR REPLACE FUNCTION governance.ws_open_hold(p_subject uuid, p_reason_kind text, p_source uuid, p_reason text, p_actor uuid, p_correlation uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v uuid;
BEGIN
  SELECT h.hold_id INTO v FROM governance.holds h WHERE h.subject_artifact = p_subject AND h.reason_kind = p_reason_kind AND h.source_artifact IS NOT DISTINCT FROM p_source AND h.lifted_at IS NULL LIMIT 1;
  IF v IS NOT NULL THEN RETURN v; END IF;
  v := gen_random_uuid();
  INSERT INTO governance.holds (hold_id, scope, subject_artifact, reason_kind, source_artifact, reason, opened_by, correlation_id)
  VALUES (v, 'PLATFORM', p_subject, p_reason_kind, p_source, p_reason, p_actor, p_correlation);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.ws_open_hold(uuid, text, uuid, text, uuid, uuid) FROM PUBLIC;

/* LIFT every open hold a source opened for a reason kind (never deleted: lifted_at / lifted_by / lift_reason); returns the lifted holds. */
CREATE OR REPLACE FUNCTION governance.ws_lift_holds(p_source uuid, p_reason_kind text, p_lift_reason text, p_actor uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v jsonb;
BEGIN
  WITH l AS (
    UPDATE governance.holds h SET lifted_at = clock_timestamp(), lifted_by = p_actor, lift_reason = p_lift_reason
     WHERE h.source_artifact = p_source AND h.reason_kind = p_reason_kind AND h.lifted_at IS NULL
    RETURNING h.hold_id, h.subject_artifact)
  SELECT coalesce(jsonb_agg(jsonb_build_object('hold_id', l.hold_id, 'subject', l.subject_artifact) ORDER BY l.subject_artifact), '[]'::jsonb) INTO v FROM l;
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.ws_lift_holds(uuid, text, text, uuid) FROM PUBLIC;

/* Validate a list of evidence items: each {kind, ref, digest (64 hex), captured_at (≤ now), valid_until (optional, > captured_at)}.
   p_current: every item captured within the last p_days and still valid now, and (p_after) captured after that instant. Raises in the
   noun's class form: (evidence) 422, (stale) 409. Returns the normalised list. */
CREATE OR REPLACE FUNCTION governance.ws_evidence(p_noun text, p_items jsonb, p_current boolean, p_days int, p_after timestamptz) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE e jsonb; v_out jsonb := '[]'::jsonb; v_cap timestamptz; v_until timestamptz;
BEGIN
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION '% rejected (evidence): at least one evidence item {kind, ref, digest, captured_at, valid_until?} is named', p_noun USING ERRCODE = '22023';
  END IF;
  FOR e IN SELECT x FROM jsonb_array_elements(p_items) x LOOP
    IF jsonb_typeof(e) <> 'object' OR length(btrim(coalesce(e ->> 'kind', ''))) < 2 OR length(btrim(coalesce(e ->> 'ref', ''))) < 2 OR coalesce(e ->> 'digest', '') !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION '% rejected (evidence): an evidence item names its kind, its reference and its digest (64 hex)', p_noun USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_cap := (e ->> 'captured_at')::timestamptz;
      v_until := CASE WHEN e ? 'valid_until' AND e ->> 'valid_until' IS NOT NULL THEN (e ->> 'valid_until')::timestamptz END;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION '% rejected (evidence): captured_at and valid_until are instants', p_noun USING ERRCODE = '22023';
    END;
    IF v_cap IS NULL OR v_cap > clock_timestamp() + interval '1 minute' THEN
      RAISE EXCEPTION '% rejected (evidence): % was captured at an instant not yet reached (or none)', p_noun, e ->> 'ref' USING ERRCODE = '22023';
    END IF;
    IF v_until IS NOT NULL AND v_until <= v_cap THEN RAISE EXCEPTION '% rejected (evidence): % is valid until before it was captured', p_noun, e ->> 'ref' USING ERRCODE = '22023'; END IF;
    IF p_current THEN
      IF v_cap < clock_timestamp() - make_interval(days => p_days) OR (v_until IS NOT NULL AND v_until <= clock_timestamp()) OR (p_after IS NOT NULL AND v_cap < p_after) THEN
        RAISE EXCEPTION '% rejected (stale): % is not current evidence (captured %, valid until %; current means captured within % days%, still valid)', p_noun, e ->> 'ref', v_cap,
          coalesce(v_until::text, 'open'), p_days, CASE WHEN p_after IS NULL THEN '' ELSE ' and after ' || p_after::text END USING ERRCODE = '23505';
      END IF;
    END IF;
    v_out := v_out || jsonb_build_object('kind', btrim(e ->> 'kind'), 'ref', btrim(e ->> 'ref'), 'digest', e ->> 'digest', 'captured_at', v_cap, 'valid_until', v_until);
  END LOOP;
  RETURN v_out;
END $$;
REVOKE ALL ON FUNCTION governance.ws_evidence(text, jsonb, boolean, int, timestamptz) FROM PUBLIC;

/* Every id names a CURRENT artifact (any of p_kinds, or any kind when NULL); raises (unknown_artifact) 404. */
CREATE OR REPLACE FUNCTION governance.ws_assert_artifacts(p_noun text, p_ids uuid[], p_kinds text[], p_what text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v uuid;
BEGIN
  FOREACH v IN ARRAY coalesce(p_ids, '{}') LOOP
    IF NOT EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.artifact_id = v AND a.superseded_at IS NULL AND (p_kinds IS NULL OR a.kind = ANY (p_kinds))) THEN
      RAISE EXCEPTION '% rejected (unknown_artifact): % names %, which is not a current % artifact', p_noun, p_what, v, coalesce(array_to_string(p_kinds, ' / '), 'governance') USING ERRCODE = '23503';
    END IF;
  END LOOP;
END $$;
REVOKE ALL ON FUNCTION governance.ws_assert_artifacts(text, uuid[], text[], text) FROM PUBLIC;

-- §PG.1 THE SHARED PLATFORM SIGNATURE PORT ─────────────────────────────────────────────────────────────────────────────────────────────────
/* RECORD a PLATFORM signature (the prelude's governance.signatures): the CALLER's bound action asserted (each part passes the action of the act
   the signature belongs to), PLATFORM scope, the signer is the acting principal — an active HUMAN holding p_signer_role at PLATFORM; the bytes
   are the TS signer's (platform-signing.ts — Ed25519 over the ASCII hex of the subject digest, the key by reference
   EYE_EXECUTIVE_SIGNING_KEY_<NAME>, the SignatureService path). One per signer per subject version. The deciding port then verifies the row
   (subject, version, digest, signer, bound action) before it acts — the signer never decides who may sign what. */
CREATE OR REPLACE FUNCTION governance.record_platform_signature(p_signature_id uuid, p_action text, p_kind text, p_subject_id uuid, p_subject_version int, p_subject_digest text,
                                                                p_key_id text, p_signature text, p_signer_role text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
BEGIN
  PERFORM observation.assert_authority(ARRAY[p_action]);
  IF public.eye_scope() IS DISTINCT FROM 'PLATFORM' THEN RAISE EXCEPTION 'signature rejected (authority): a platform signature is recorded at PLATFORM scope' USING ERRCODE = '42501'; END IF;
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'signature rejected (actor): recorded by the acting principal' USING ERRCODE = '42501'; END IF;
  IF NOT governance.ws_is_human(p_actor) THEN RAISE EXCEPTION 'signature rejected (actor): a named human signs; an agent never does' USING ERRCODE = '42501'; END IF;
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY[p_signer_role]) THEN
    RAISE EXCEPTION 'signature rejected (authority): the signer holds % at PLATFORM', coalesce(p_signer_role, '<none>') USING ERRCODE = '42501';
  END IF;
  IF NOT (p_kind = ANY (governance.signature_kinds())) THEN RAISE EXCEPTION 'signature rejected (kind): % is not a platform signature kind', p_kind USING ERRCODE = '22023'; END IF;
  IF coalesce(p_subject_digest, '') !~ '^[0-9a-f]{64}$' OR coalesce(p_key_id, '') !~ '^ed25519:[0-9a-f]{16}$' OR coalesce(p_signature, '') !~ '^[A-Za-z0-9+/]{86}==$' THEN
    RAISE EXCEPTION 'signature rejected (format): a 64-hex subject digest, an ed25519 key id and a 64-byte signature' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM governance.signatures s WHERE s.subject_kind = p_kind AND s.subject_id = p_subject_id AND s.subject_version = p_subject_version AND s.signer = p_actor) THEN
    RAISE EXCEPTION 'signature rejected (state): % %/% is already signed by this principal', p_kind, p_subject_id, p_subject_version USING ERRCODE = '22023';
  END IF;
  INSERT INTO governance.signatures (signature_id, scope, subject_kind, subject_id, subject_version, subject_digest, signer, signer_role, key_id, algorithm, signature, bound_action, correlation_id)
  VALUES (p_signature_id, 'PLATFORM', p_kind, p_subject_id, p_subject_version, p_subject_digest, p_actor, p_signer_role, p_key_id, 'ed25519', p_signature, p_action, p_correlation);
  RETURN jsonb_build_object('signature_id', p_signature_id, 'subject_kind', p_kind, 'subject_id', p_subject_id, 'subject_version', p_subject_version, 'subject_digest', p_subject_digest,
                            'signer', p_actor, 'signer_role', p_signer_role, 'key_id', p_key_id, 'signed_at', clock_timestamp());
END $$;
REVOKE ALL ON FUNCTION governance.record_platform_signature(uuid, text, text, uuid, int, text, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.record_platform_signature(uuid, text, text, uuid, int, text, text, text, text, uuid, uuid) TO eye_commit;

/* The deciding port's check: the signature row exists for exactly this subject version, digest, signer and action. */
CREATE OR REPLACE FUNCTION governance.ws_signed(p_signature uuid, p_kind text, p_subject uuid, p_version int, p_digest text, p_actor uuid, p_action text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT p_signature IS NOT NULL AND EXISTS (SELECT 1 FROM governance.signatures s WHERE s.signature_id = p_signature AND s.subject_kind = p_kind AND s.subject_id = p_subject
           AND s.subject_version = p_version AND s.subject_digest = p_digest AND s.signer = p_actor AND s.bound_action = p_action) $$;
REVOKE ALL ON FUNCTION governance.ws_signed(uuid, text, uuid, int, text, uuid, text) FROM PUBLIC;

/* The signatures of a subject (an invoker read: PLATFORM rows are readable by every authenticated context). */
CREATE OR REPLACE FUNCTION governance.platform_signature_of(p_kind text, p_subject uuid, p_version int) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('signature_id', s.signature_id, 'signer', s.signer, 'signer_role', s.signer_role, 'key_id', s.key_id, 'algorithm', s.algorithm,
                                               'signature', s.signature, 'subject_digest', s.subject_digest, 'bound_action', s.bound_action, 'signed_at', s.signed_at) ORDER BY s.signed_at), '[]'::jsonb)
    FROM governance.signatures s WHERE s.subject_kind = p_kind AND s.subject_id = p_subject AND s.subject_version = p_version $$;
GRANT EXECUTE ON FUNCTION governance.platform_signature_of(text, uuid, int) TO eye_app, eye_commit;

-- §PG.2 THE PRODUCT BASELINE: owners, decision rights, the signed baseline decision ────────────────────────────────────────────────────────
/* ONE accountable owner per capability (ADR-005): a named active human holding the stated role at PLATFORM, the capability's domain boundary;
   a new assignment supersedes the old (versioned, never edited). */
CREATE TABLE governance.ws_capability_owners (
  capability_id      uuid NOT NULL,
  version            int  NOT NULL CHECK (version >= 1),
  scope              text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  capability_key     text NOT NULL,
  owner_principal_id uuid NOT NULL,
  owner_role         text NOT NULL REFERENCES identity.roles (code),
  domain_boundary    text NOT NULL CHECK (length(btrim(domain_boundary)) BETWEEN 3 AND 200),
  reason             text NOT NULL CHECK (length(btrim(reason)) >= 8),
  assigned_by        uuid NOT NULL,
  assigned_at        timestamptz NOT NULL DEFAULT clock_timestamp(),
  superseded_at      timestamptz,
  correlation_id     uuid NOT NULL,
  PRIMARY KEY (capability_id, version)
);
CREATE UNIQUE INDEX wco_one_owner ON governance.ws_capability_owners (capability_id) WHERE superseded_at IS NULL;

/* THE DECISION-RIGHTS MATRIX (CAP-AU-03): rows {subject (an act class or a capability key), duty, role, principal?, delegate?: {to, until}};
   versioned; SIGNED (`decision_rights`) by the product authority — never the proposer. */
CREATE TABLE governance.ws_decision_rights (
  matrix_id       uuid NOT NULL,
  version         int  NOT NULL CHECK (version >= 1),
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  ref             text NOT NULL,
  rows            jsonb NOT NULL CHECK (jsonb_typeof(rows) = 'array'),
  digest          text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  state           text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'approved', 'rejected', 'superseded')),
  proposed_by     uuid NOT NULL,
  proposed_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by      uuid,
  decided_at      timestamptz,
  decision_reason text,
  signature_id    uuid,
  claim           text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  correlation_id  uuid NOT NULL,
  PRIMARY KEY (matrix_id, version)
);
CREATE UNIQUE INDEX wdr_one_open ON governance.ws_decision_rights (matrix_id) WHERE state = 'proposed';
CREATE UNIQUE INDEX wdr_one_approved ON governance.ws_decision_rights ((true)) WHERE state = 'approved';

/* THE BASELINE: the inventory, owners and boundaries, the rights, the exception ageing and conformance trend, the scope tuple, the gaps —
   SIGNED (`baseline_decision`) by the product authority; the signed decision is the executive baseline attestation. */
CREATE TABLE governance.ws_baselines (
  baseline_id     uuid NOT NULL,
  version         int  NOT NULL CHECK (version >= 1),
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  ref             text NOT NULL,
  title           text NOT NULL CHECK (length(btrim(title)) BETWEEN 8 AND 300),
  inventory       jsonb NOT NULL,
  domains         jsonb NOT NULL,
  rights          jsonb,
  exceptions      jsonb NOT NULL,
  conflicts       jsonb NOT NULL,
  holds           jsonb NOT NULL,
  trend           jsonb NOT NULL,
  scope_tuple     jsonb NOT NULL,
  gaps            jsonb NOT NULL,
  digest          text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  state           text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'signed', 'rejected', 'superseded')),
  proposed_by     uuid NOT NULL,
  proposed_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by      uuid,
  decided_at      timestamptz,
  decision_reason text,
  signature_id    uuid,
  claim           text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  correlation_id  uuid NOT NULL,
  PRIMARY KEY (baseline_id, version)
);
CREATE UNIQUE INDEX wbl_one_open ON governance.ws_baselines (baseline_id) WHERE state = 'proposed';
CREATE UNIQUE INDEX wbl_one_signed ON governance.ws_baselines ((true)) WHERE state = 'signed';

/* The current approved decision-rights matrix, or NULL. */
CREATE OR REPLACE FUNCTION governance.ws_rights_current() RETURNS governance.ws_decision_rights
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT r FROM governance.ws_decision_rights r WHERE r.state = 'approved' LIMIT 1 $$;
REVOKE ALL ON FUNCTION governance.ws_rights_current() FROM PUBLIC;

/* RESOLVE a duty on a subject against the approved matrix: {governed: bool, matrix, rows: [{role, principal, delegate, delegate_live}]}.
   Not governed (no approved matrix, or no row for the subject/duty) → the port's own role rule applies (stated, never hidden). */
CREATE OR REPLACE FUNCTION governance.ws_rights_resolve(p_subject text, p_duty text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE m governance.ws_decision_rights; v jsonb;
BEGIN
  m := governance.ws_rights_current();
  IF m.matrix_id IS NULL THEN RETURN jsonb_build_object('governed', false, 'reason', 'no approved decision-rights matrix: the port''s own role rule applies'); END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('role', r ->> 'role', 'principal', r -> 'principal', 'delegate', r -> 'delegate',
           'delegate_live', (r -> 'delegate') IS NOT NULL AND jsonb_typeof(r -> 'delegate') = 'object' AND (r -> 'delegate' ->> 'until')::date >= (clock_timestamp() AT TIME ZONE 'UTC')::date)), '[]'::jsonb)
    INTO v FROM jsonb_array_elements(m.rows) r WHERE r ->> 'subject' = p_subject AND r ->> 'duty' = p_duty;
  IF jsonb_array_length(v) = 0 THEN
    RETURN jsonb_build_object('governed', false, 'matrix', jsonb_build_object('matrix_id', m.matrix_id, 'version', m.version), 'reason', format('the approved matrix %s v%s has no %s row for %s: the port''s own role rule applies', m.ref, m.version, p_duty, p_subject));
  END IF;
  RETURN jsonb_build_object('governed', true, 'matrix', jsonb_build_object('matrix_id', m.matrix_id, 'version', m.version, 'ref', m.ref), 'rows', v);
END $$;
REVOKE ALL ON FUNCTION governance.ws_rights_resolve(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_rights_resolve(text, text) TO eye_app, eye_commit;

/* THE RIGHTS CHECK every deciding port makes: when the approved matrix governs (subject, duty), the actor is the row's named principal (or
   its LIVE delegate), or — on a row naming no principal — a holder of the row's role at PLATFORM. Raises (authority) 403. */
CREATE OR REPLACE FUNCTION governance.ws_assert_rights(p_noun text, p_subject text, p_duty text, p_actor uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE r jsonb := governance.ws_rights_resolve(p_subject, p_duty); x jsonb;
BEGIN
  IF NOT (r ->> 'governed')::boolean THEN RETURN r; END IF;
  FOR x IN SELECT y FROM jsonb_array_elements(r -> 'rows') y LOOP
    IF jsonb_typeof(x -> 'principal') = 'string' THEN
      IF (x ->> 'principal')::uuid = p_actor AND governance.holds_role(p_actor, NULL, NULL, ARRAY[x ->> 'role']) THEN RETURN r || jsonb_build_object('via', 'named'); END IF;
      IF (x ->> 'delegate_live')::boolean AND (x -> 'delegate' ->> 'to')::uuid = p_actor AND governance.holds_role(p_actor, NULL, NULL, ARRAY[x ->> 'role']) THEN
        RETURN r || jsonb_build_object('via', 'delegate', 'delegate_until', x -> 'delegate' ->> 'until');
      END IF;
    ELSIF governance.holds_role(p_actor, NULL, NULL, ARRAY[x ->> 'role']) THEN
      RETURN r || jsonb_build_object('via', 'role');
    END IF;
  END LOOP;
  RAISE EXCEPTION '% rejected (authority): the approved decision-rights matrix % v% assigns % of % to %', p_noun, r -> 'matrix' ->> 'ref', r -> 'matrix' ->> 'version', p_duty, p_subject,
    (SELECT string_agg(CASE WHEN jsonb_typeof(y -> 'principal') = 'string' THEN format('%s (%s%s)', y ->> 'role', governance.ws_principal_name((y ->> 'principal')::uuid),
                              CASE WHEN (y ->> 'delegate_live')::boolean THEN ', delegated to ' || governance.ws_principal_name((y -> 'delegate' ->> 'to')::uuid) || ' until ' || (y -> 'delegate' ->> 'until') ELSE '' END)
                            ELSE y ->> 'role' END, ' or ') FROM jsonb_array_elements(r -> 'rows') y) USING ERRCODE = '42501';
END $$;
REVOKE ALL ON FUNCTION governance.ws_assert_rights(text, text, text, uuid) FROM PUBLIC;

/* ASSIGN the accountable owner of a capability (the product authority; human-gated): a named active human holding owner_role at PLATFORM. */
CREATE OR REPLACE FUNCTION governance.ws_assign_owner(p_capability uuid, p_owner uuid, p_owner_role text, p_domain_boundary text, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE a governance.artifacts%ROWTYPE; v int; prev uuid;
BEGIN
  PERFORM governance.assert_platform('governance.baseline.owner.assign', p_actor, 'product baseline');
  IF NOT governance.ws_is_human(p_actor) THEN RAISE EXCEPTION 'product baseline rejected (actor): an accountable owner is assigned by a named human' USING ERRCODE = '42501'; END IF;
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['product_authority']) THEN RAISE EXCEPTION 'product baseline rejected (authority): the product authority assigns capability owners' USING ERRCODE = '42501'; END IF;
  SELECT * INTO a FROM governance.artifacts x WHERE x.artifact_id = p_capability AND x.superseded_at IS NULL AND x.kind = 'capability';
  IF NOT FOUND THEN RAISE EXCEPTION 'product baseline rejected (unknown_capability): % is not a current capability artifact', p_capability USING ERRCODE = '23503'; END IF;
  IF NOT governance.ws_is_human(p_owner) THEN RAISE EXCEPTION 'product baseline rejected (owner): an accountable owner is a named active human (ADR-005)' USING ERRCODE = '22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM identity.roles r WHERE r.code = p_owner_role) OR NOT governance.holds_role(p_owner, NULL, NULL, ARRAY[p_owner_role]) THEN
    RAISE EXCEPTION 'product baseline rejected (owner): the owner holds % at PLATFORM', coalesce(p_owner_role, '<none>') USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_domain_boundary, ''))) < 3 THEN RAISE EXCEPTION 'product baseline rejected (domain): the capability''s domain boundary is named' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'product baseline rejected (reason): an assignment states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  SELECT o.owner_principal_id INTO prev FROM governance.ws_capability_owners o WHERE o.capability_id = p_capability AND o.superseded_at IS NULL FOR UPDATE;
  SELECT coalesce(max(o.version), 0) INTO v FROM governance.ws_capability_owners o WHERE o.capability_id = p_capability;
  UPDATE governance.ws_capability_owners SET superseded_at = clock_timestamp() WHERE capability_id = p_capability AND superseded_at IS NULL;
  INSERT INTO governance.ws_capability_owners (capability_id, version, capability_key, owner_principal_id, owner_role, domain_boundary, reason, assigned_by, correlation_id)
  VALUES (p_capability, v + 1, a.external_key, p_owner, p_owner_role, btrim(p_domain_boundary), btrim(p_reason), p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'capability', p_capability, v + 1, 'baseline.owner_assigned', p_actor,
            jsonb_build_object('capability_key', a.external_key, 'owner', p_owner, 'owner_role', p_owner_role, 'domain_boundary', btrim(p_domain_boundary), 'previous_owner', prev, 'reason', btrim(p_reason)), p_correlation);
  RETURN jsonb_build_object('capability_id', p_capability, 'capability_key', a.external_key, 'version', v + 1, 'owner', p_owner, 'owner_name', governance.ws_principal_name(p_owner),
                            'owner_role', p_owner_role, 'domain_boundary', btrim(p_domain_boundary), 'previous_owner', prev);
END $$;
REVOKE ALL ON FUNCTION governance.ws_assign_owner(uuid, uuid, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_assign_owner(uuid, uuid, text, text, text, uuid, uuid) TO eye_commit;

/* VALIDATE a decision-rights matrix's rows; returns the normalised rows (sorted) or raises in the class form:
   (rows) the vocabulary; (singular) one approve row per subject; (separation_of_duties) the approver's role never the proposer's, the
   auditor's role never the approver's, proposer's or operator's, a named principal never in two of propose/approve/audit for one subject;
   (delegation) only approve/review delegate, to an active human holding the row's role, never the row's own principal, at most 90 days. */
CREATE OR REPLACE FUNCTION governance.ws_rights_rows(p_rows jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, identity, pg_catalog, pg_temp AS $$
DECLARE r jsonb; v_out jsonb := '[]'::jsonb; s text; v_roles text[]; v_pp text[];
BEGIN
  IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) = 0 OR jsonb_array_length(p_rows) > 500 THEN
    RAISE EXCEPTION 'decision rights rejected (rows): a matrix is a non-empty list of rows (at most 500)' USING ERRCODE = '22023';
  END IF;
  FOR r IN SELECT x FROM jsonb_array_elements(p_rows) x LOOP
    IF jsonb_typeof(r) <> 'object' OR coalesce(r ->> 'subject', '') = '' OR NOT ((r ->> 'duty') = ANY (governance.ws_duties())) OR NOT EXISTS (SELECT 1 FROM identity.roles x WHERE x.code = r ->> 'role') THEN
      RAISE EXCEPTION 'decision rights rejected (rows): each row names a subject, a duty (%) and a known role', array_to_string(governance.ws_duties(), ' | ') USING ERRCODE = '22023';
    END IF;
    IF NOT ((r ->> 'subject') = ANY (governance.ws_act_classes()))
       AND NOT EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.kind = 'capability' AND a.superseded_at IS NULL AND a.external_key = r ->> 'subject') THEN
      RAISE EXCEPTION 'decision rights rejected (unknown_subject): % is neither an act class (%) nor a current capability''s key', r ->> 'subject', array_to_string(governance.ws_act_classes(), ', ') USING ERRCODE = '23503';
    END IF;
    IF r ? 'principal' AND jsonb_typeof(r -> 'principal') = 'string' THEN
      IF NOT governance.ws_is_human((r ->> 'principal')::uuid) OR NOT governance.holds_role((r ->> 'principal')::uuid, NULL, NULL, ARRAY[r ->> 'role']) THEN
        RAISE EXCEPTION 'decision rights rejected (rows): the named principal of % / % is an active human holding % at PLATFORM', r ->> 'subject', r ->> 'duty', r ->> 'role' USING ERRCODE = '22023';
      END IF;
    END IF;
    IF r ? 'delegate' AND jsonb_typeof(r -> 'delegate') = 'object' THEN
      IF NOT ((r ->> 'duty') IN ('approve', 'review')) OR jsonb_typeof(r -> 'principal') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'decision rights rejected (delegation): only a named principal''s approve or review duty is delegated' USING ERRCODE = '22023';
      END IF;
      IF NOT governance.ws_is_human((r -> 'delegate' ->> 'to')::uuid) OR NOT governance.holds_role((r -> 'delegate' ->> 'to')::uuid, NULL, NULL, ARRAY[r ->> 'role'])
         OR (r -> 'delegate' ->> 'to') = (r ->> 'principal') THEN
        RAISE EXCEPTION 'decision rights rejected (delegation): the delegate of % / % is another active human holding %', r ->> 'subject', r ->> 'duty', r ->> 'role' USING ERRCODE = '22023';
      END IF;
      IF coalesce(r -> 'delegate' ->> 'until', '') !~ '^\d{4}-\d{2}-\d{2}$' OR (r -> 'delegate' ->> 'until')::date < (clock_timestamp() AT TIME ZONE 'UTC')::date
         OR (r -> 'delegate' ->> 'until')::date > (clock_timestamp() AT TIME ZONE 'UTC')::date + 90 THEN
        RAISE EXCEPTION 'decision rights rejected (delegation): a delegation runs until a day (YYYY-MM-DD) from today to 90 days ahead' USING ERRCODE = '22023';
      END IF;
    END IF;
    v_out := v_out || jsonb_build_object('subject', r ->> 'subject', 'duty', r ->> 'duty', 'role', r ->> 'role',
                                         'principal', CASE WHEN jsonb_typeof(r -> 'principal') = 'string' THEN r -> 'principal' ELSE 'null'::jsonb END,
                                         'delegate', CASE WHEN jsonb_typeof(r -> 'delegate') = 'object' THEN jsonb_build_object('to', r -> 'delegate' ->> 'to', 'until', r -> 'delegate' ->> 'until') ELSE 'null'::jsonb END);
  END LOOP;
  FOR s IN SELECT DISTINCT x ->> 'subject' FROM jsonb_array_elements(v_out) x LOOP
    IF (SELECT count(*) FROM jsonb_array_elements(v_out) x WHERE x ->> 'subject' = s AND x ->> 'duty' = 'approve') > 1 THEN
      RAISE EXCEPTION 'decision rights rejected (singular): % has more than one approve row — decision rights are singular', s USING ERRCODE = '22023';
    END IF;
    IF (SELECT count(*) FROM jsonb_array_elements(v_out) x WHERE x ->> 'subject' = s AND x ->> 'duty' = 'audit') > 0 AND (SELECT count(*) FROM jsonb_array_elements(v_out) x WHERE x ->> 'subject' = s AND x ->> 'duty' = 'approve') = 0 THEN
      RAISE EXCEPTION 'decision rights rejected (singular): % is audited but has no approver', s USING ERRCODE = '22023';
    END IF;
    SELECT array_agg(x ->> 'role') INTO v_roles FROM jsonb_array_elements(v_out) x WHERE x ->> 'subject' = s AND x ->> 'duty' = 'approve';
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_out) x WHERE x ->> 'subject' = s AND x ->> 'duty' = 'propose' AND x ->> 'role' = ANY (coalesce(v_roles, '{}'))) THEN
      RAISE EXCEPTION 'decision rights rejected (separation_of_duties): % — the approving role also proposes', s USING ERRCODE = '42501';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_out) x JOIN jsonb_array_elements(v_out) y ON y ->> 'subject' = s AND y ->> 'duty' IN ('approve', 'propose', 'operate') AND y ->> 'role' = x ->> 'role'
                WHERE x ->> 'subject' = s AND x ->> 'duty' = 'audit') THEN
      RAISE EXCEPTION 'decision rights rejected (separation_of_duties): % — the auditing role also proposes, approves or operates', s USING ERRCODE = '42501';
    END IF;
    SELECT array_agg(DISTINCT x ->> 'principal') INTO v_pp FROM jsonb_array_elements(v_out) x WHERE x ->> 'subject' = s AND x ->> 'duty' IN ('propose', 'approve', 'audit') AND jsonb_typeof(x -> 'principal') = 'string'
      GROUP BY x ->> 'principal' HAVING count(DISTINCT x ->> 'duty') > 1 LIMIT 1;
    IF v_pp IS NOT NULL THEN RAISE EXCEPTION 'decision rights rejected (separation_of_duties): % — one named principal holds two of propose / approve / audit', s USING ERRCODE = '42501'; END IF;
  END LOOP;
  RETURN (SELECT jsonb_agg(x ORDER BY x ->> 'subject', array_position(governance.ws_duties(), x ->> 'duty'), x ->> 'role', coalesce(x ->> 'principal', '')) FROM jsonb_array_elements(v_out) x);
END $$;
REVOKE ALL ON FUNCTION governance.ws_rights_rows(jsonb) FROM PUBLIC;

/* PROPOSE a decision-rights matrix version (the product authority or the conformance steward). */
CREATE OR REPLACE FUNCTION governance.ws_propose_rights(p_matrix uuid, p_rows jsonb, p_expected_version int, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE v_cur int; v_rows jsonb; v_digest text; v_ref text;
BEGIN
  PERFORM governance.assert_platform('governance.rights.propose', p_actor, 'decision rights');
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['product_authority', 'conformance_steward']) THEN
    RAISE EXCEPTION 'decision rights rejected (authority): a matrix is proposed by the product authority or the conformance steward' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.ws_decision_rights:' || p_matrix::text, 0));
  SELECT coalesce(max(r.version), 0), max(r.ref) INTO v_cur, v_ref FROM governance.ws_decision_rights r WHERE r.matrix_id = p_matrix;
  IF p_expected_version IS DISTINCT FROM v_cur THEN
    RAISE EXCEPTION 'decision rights rejected (stale): the matrix is at version % (expected %)', v_cur, coalesce(p_expected_version::text, '<none>') USING ERRCODE = '23505';
  END IF;
  v_rows := governance.ws_rights_rows(p_rows);
  v_ref := coalesce(v_ref, governance.ws_next_ref('PDR'));
  v_digest := governance.digest(jsonb_build_object('matrix_id', p_matrix, 'version', v_cur + 1, 'rows', v_rows));
  UPDATE governance.ws_decision_rights SET state = 'superseded' WHERE matrix_id = p_matrix AND state = 'proposed';
  INSERT INTO governance.ws_decision_rights (matrix_id, version, ref, rows, digest, proposed_by, correlation_id) VALUES (p_matrix, v_cur + 1, v_ref, v_rows, v_digest, p_actor, p_correlation);
  IF v_cur = 0 THEN  -- a later version is registered when decided (the approved matrix's artifact stays current until then)
    PERFORM governance.ws_register(p_matrix, 'baseline', v_ref, 'Decision-rights matrix ' || v_ref || ' (propose / review / approve / operate / audit)', p_actor, 'product_authority', 'controlling', 'V8',
              'proposed', jsonb_build_object('object', 'decision_rights', 'version', v_cur + 1, 'rows', jsonb_array_length(v_rows)), v_digest, p_actor, p_correlation);
  END IF;
  PERFORM governance.ledger(NULL, NULL, 'decision_rights', p_matrix, v_cur + 1, 'rights.proposed', p_actor, jsonb_build_object('digest', v_digest, 'rows', jsonb_array_length(v_rows)), p_correlation);
  RETURN jsonb_build_object('matrix_id', p_matrix, 'ref', v_ref, 'version', v_cur + 1, 'state', 'proposed', 'digest', v_digest, 'rows', v_rows);
END $$;
REVOKE ALL ON FUNCTION governance.ws_propose_rights(uuid, jsonb, int, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_propose_rights(uuid, jsonb, int, uuid, uuid) TO eye_commit;

/* DECIDE (approve | reject) a matrix version — the product authority (the approver test: never the proposer), on the exact digest; APPROVE is
   SIGNED (`decision_rights`); an approved matrix supersedes the previous one; when one is in force, its own `decision_rights` approve row governs. */
CREATE OR REPLACE FUNCTION governance.ws_decide_rights(p_matrix uuid, p_version int, p_decision text, p_digest text, p_reason text, p_signature uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE m governance.ws_decision_rights%ROWTYPE; v_via jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.rights.decide', p_actor, 'decision rights');
  SELECT * INTO m FROM governance.ws_decision_rights x WHERE x.matrix_id = p_matrix AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'decision rights rejected (unknown_matrix): no decision-rights matrix %/v%', p_matrix, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('decision rights', p_actor, NULL, NULL, ARRAY['product_authority'], m.proposed_by, NULL, 'deciding the decision-rights matrix');
  v_via := governance.ws_assert_rights('decision rights', 'decision_rights', 'approve', p_actor);
  IF m.state <> 'proposed' THEN RAISE EXCEPTION 'decision rights rejected (state): version % is %', p_version, m.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM m.digest THEN RAISE EXCEPTION 'decision rights rejected (stale): the decision names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF p_decision NOT IN ('approve', 'reject') THEN RAISE EXCEPTION 'decision rights rejected (decision): approve or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'decision rights rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'approve' THEN
    IF NOT governance.ws_signed(p_signature, 'decision_rights', p_matrix, p_version, m.digest, p_actor, 'governance.rights.decide') THEN
      RAISE EXCEPTION 'decision rights rejected (signature): approval carries the decider''s signature over the matrix digest' USING ERRCODE = '22023';
    END IF;
    UPDATE governance.ws_decision_rights SET state = 'superseded' WHERE state = 'approved';
  END IF;
  UPDATE governance.ws_decision_rights SET state = CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END, decided_by = p_actor, decided_at = clock_timestamp(),
         decision_reason = btrim(p_reason), signature_id = CASE WHEN p_decision = 'approve' THEN p_signature END
   WHERE matrix_id = p_matrix AND version = p_version;
  PERFORM governance.ws_register(p_matrix, 'baseline', m.ref, 'Decision-rights matrix ' || m.ref || ' (propose / review / approve / operate / audit)', p_actor, 'product_authority', 'controlling', 'V8',
            CASE WHEN p_decision = 'approve' THEN 'active' ELSE 'retired' END, jsonb_build_object('object', 'decision_rights', 'version', p_version, 'state', CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END),
            m.digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'decision_rights', p_matrix, p_version, CASE WHEN p_decision = 'approve' THEN 'rights.approved' ELSE 'rights.rejected' END, p_actor,
            jsonb_build_object('digest', m.digest, 'reason', btrim(p_reason), 'signature_id', p_signature, 'rights_via', v_via), p_correlation);
  RETURN jsonb_build_object('matrix_id', p_matrix, 'ref', m.ref, 'version', p_version, 'state', CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END, 'digest', m.digest, 'signature_id', p_signature);
END $$;
REVOKE ALL ON FUNCTION governance.ws_decide_rights(uuid, int, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_decide_rights(uuid, int, text, text, text, uuid, uuid, uuid) TO eye_commit;

-- §PG.3 THE ONE EXCEPTION REGISTRY ───────────────────────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE governance.ws_exceptions (
  exception_id          uuid NOT NULL,
  version               int  NOT NULL CHECK (version >= 1),
  scope                 text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  ref                   text NOT NULL,
  renewal_of            int,
  class                 text NOT NULL DEFAULT 'product' CHECK (class = 'product'),
  title                 text NOT NULL CHECK (length(btrim(title)) BETWEEN 8 AND 300),
  requirement_ref       text NOT NULL CHECK (length(btrim(requirement_ref)) BETWEEN 3 AND 200),
  requirement_artifact  uuid,
  contract_key          text NOT NULL CHECK (length(btrim(contract_key)) BETWEEN 3 AND 200),
  system_scope          uuid[] NOT NULL,
  customer_scope        jsonb NOT NULL CHECK (jsonb_typeof(customer_scope) = 'object'),
  reason                text NOT NULL CHECK (length(btrim(reason)) >= 20),
  evidence              jsonb NOT NULL CHECK (jsonb_typeof(evidence) = 'array'),
  risk                  jsonb NOT NULL CHECK (jsonb_typeof(risk) = 'object'),
  affected_invariants   text[] NOT NULL,
  compensating_controls jsonb NOT NULL CHECK (jsonb_typeof(compensating_controls) = 'array'),
  owner_principal_id    uuid NOT NULL,
  expands_authority     boolean NOT NULL,
  removes_control       boolean NOT NULL,
  approver_roles        text[] NOT NULL,
  starts_at             timestamptz NOT NULL,
  expires_at            timestamptz NOT NULL,
  monitoring            text NOT NULL CHECK (length(btrim(monitoring)) >= 8),
  exit_criteria         text NOT NULL CHECK (length(btrim(exit_criteria)) >= 8),
  remediation_plan      text NOT NULL CHECK (length(btrim(remediation_plan)) >= 8),
  affected_artifacts    uuid[] NOT NULL,
  state                 text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'approved', 'rejected', 'withdrawn', 'expired', 'closed', 'superseded')),
  digest                text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  proposed_by           uuid NOT NULL,
  proposed_at           timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by            uuid,
  decided_role          text,
  decided_at            timestamptz,
  decision_reason       text,
  signature_id          uuid,
  expired_at            timestamptz,
  closed_by             uuid,
  closed_at             timestamptz,
  close_reason          text,
  exit_evidence         jsonb,
  claim                 text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  correlation_id        uuid NOT NULL,
  PRIMARY KEY (exception_id, version),
  CONSTRAINT wex_window CHECK (expires_at > starts_at AND expires_at <= starts_at + interval '366 days')
);
CREATE UNIQUE INDEX wex_one_open ON governance.ws_exceptions (exception_id) WHERE state = 'proposed';
CREATE INDEX wex_contract ON governance.ws_exceptions (contract_key);
CREATE INDEX wex_expiry ON governance.ws_exceptions (expires_at) WHERE state = 'approved';

/* REPEATS (V03-T-451): a review opened when a contract accumulates REPEAT_THRESHOLD (3) distinct exceptions, or one exception's third period
   (a second renewal); while it is open, no exception on the contract is approved; decided by the product authority — remediation (a plan, an
   owner, a due day) or a formal change review (a change proposal). */
CREATE TABLE governance.ws_exception_reviews (
  review_id       uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  ref             text NOT NULL,
  contract_key    text NOT NULL,
  trigger         text NOT NULL CHECK (trigger IN ('repeated_exceptions', 'repeated_renewal')),
  exceptions      uuid[] NOT NULL,
  state           text NOT NULL DEFAULT 'open' CHECK (state IN ('open', 'remediation', 'change_review')),
  opened_by       uuid NOT NULL,
  opened_at       timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by      uuid,
  decided_at      timestamptz,
  decision_reason text,
  remediation     jsonb,
  change_proposal uuid,
  correlation_id  uuid NOT NULL
);
CREATE UNIQUE INDEX wer_one_open ON governance.ws_exception_reviews (contract_key) WHERE state = 'open';
CREATE OR REPLACE FUNCTION governance.ws_repeat_threshold() RETURNS int LANGUAGE sql IMMUTABLE AS $$ SELECT 3 $$;
GRANT EXECUTE ON FUNCTION governance.ws_repeat_threshold() TO eye_app, eye_commit;
/* Evidence is CURRENT for a renewal or a closure when captured within this many days (and after the prior approval). */
CREATE OR REPLACE FUNCTION governance.ws_evidence_currency_days() RETURNS int LANGUAGE sql IMMUTABLE AS $$ SELECT 30 $$;
GRANT EXECUTE ON FUNCTION governance.ws_evidence_currency_days() TO eye_app, eye_commit;

/* The customer scope, validated: {"all": true} or {"tenants": [uuid…], "domains": [{"tenant", "domain"}…]} naming known tenants / domains. */
CREATE OR REPLACE FUNCTION governance.ws_customer_scope(p jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, tenancy, pg_catalog, pg_temp AS $$
DECLARE x jsonb; v_t jsonb := '[]'::jsonb; v_d jsonb := '[]'::jsonb;
BEGIN
  IF jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'governance exception rejected (customer_scope): the customer scope is an object' USING ERRCODE = '22023'; END IF;
  IF coalesce((p ->> 'all')::boolean, false) THEN RETURN jsonb_build_object('all', true, 'tenants', '[]'::jsonb, 'domains', '[]'::jsonb); END IF;
  FOR x IN SELECT y FROM jsonb_array_elements(coalesce(p -> 'tenants', '[]'::jsonb)) y LOOP
    IF NOT EXISTS (SELECT 1 FROM tenancy.tenants t WHERE t.id::text = x #>> '{}') THEN RAISE EXCEPTION 'governance exception rejected (unknown_tenant): % is not a tenant', x #>> '{}' USING ERRCODE = '23503'; END IF;
    v_t := v_t || to_jsonb(x #>> '{}');
  END LOOP;
  FOR x IN SELECT y FROM jsonb_array_elements(coalesce(p -> 'domains', '[]'::jsonb)) y LOOP
    IF NOT EXISTS (SELECT 1 FROM tenancy.domains d WHERE d.id::text = x ->> 'domain' AND d.tenant_id::text = x ->> 'tenant') THEN
      RAISE EXCEPTION 'governance exception rejected (unknown_domain): % is not a domain of %', x ->> 'domain', x ->> 'tenant' USING ERRCODE = '23503';
    END IF;
    v_d := v_d || jsonb_build_object('tenant', x ->> 'tenant', 'domain', x ->> 'domain');
  END LOOP;
  IF jsonb_array_length(v_t) + jsonb_array_length(v_d) = 0 THEN
    RAISE EXCEPTION 'governance exception rejected (customer_scope): the customer scope names all customers or at least one tenant or domain' USING ERRCODE = '22023';
  END IF;
  RETURN jsonb_build_object('all', false, 'tenants', v_t, 'domains', v_d);
END $$;
REVOKE ALL ON FUNCTION governance.ws_customer_scope(jsonb) FROM PUBLIC;

/* Does an exception's customer scope cover a domain? */
CREATE OR REPLACE FUNCTION governance.ws_scope_covers(p_scope jsonb, p_tenant uuid, p_domain uuid) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT coalesce((p_scope ->> 'all')::boolean, false)
      OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(coalesce(p_scope -> 'tenants', '[]'::jsonb)) t WHERE t = p_tenant::text)
      OR EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(p_scope -> 'domains', '[]'::jsonb)) d WHERE d ->> 'tenant' = p_tenant::text AND d ->> 'domain' = p_domain::text) $$;
GRANT EXECUTE ON FUNCTION governance.ws_scope_covers(jsonb, uuid, uuid) TO eye_app, eye_commit;

/* The owners of the components an exception's system scope names (ES-02-004: none of them approves it). */
CREATE OR REPLACE FUNCTION governance.ws_scope_owners(p_scope uuid[]) RETURNS uuid[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce(array_agg(DISTINCT a.owner_principal_id) FILTER (WHERE a.owner_principal_id IS NOT NULL), '{}') FROM governance.artifacts a
   WHERE a.artifact_id = ANY (coalesce(p_scope, '{}')) AND a.superseded_at IS NULL $$;
REVOKE ALL ON FUNCTION governance.ws_scope_owners(uuid[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_scope_owners(uuid[]) TO eye_app, eye_commit;  -- a read of PLATFORM artifact owners (readable by every context)

/* PROPOSE an exception (new: expected version 0) or its RENEWAL (expected = the current version, which is approved or expired). Every
   V03-T-453 field; constitutional boundaries refused; renewal evidence CURRENT (captured within 30 days, after the prior approval, still
   valid). A proposal that makes its contract a repeat opens the remediation review. */
CREATE OR REPLACE FUNCTION governance.ws_propose_exception(p_exception uuid, p_body jsonb, p_expected_version int, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, identity, public, pg_catalog, pg_temp AS $$
DECLARE cur governance.ws_exceptions%ROWTYPE; v_cur int; v_ref text; v_scope jsonb; v_evidence jsonb; v_inv text[]; v_bad text[]; v_sys uuid[]; v_aff uuid[]; v_owner uuid;
        v_starts timestamptz; v_expires timestamptz; v_req uuid; v_risk jsonb; v_controls jsonb; v_roles text[]; v_digest text; v_version int; v_contract text;
        v_count int; v_review jsonb := NULL; v_rid uuid; v_list uuid[]; v_exp boolean; v_rem boolean;
BEGIN
  PERFORM governance.assert_platform('governance.exception.propose', p_actor, 'governance exception');
  IF NOT governance.holds_role(p_actor, NULL, NULL, governance.ws_governance_roles()) THEN
    RAISE EXCEPTION 'governance exception rejected (authority): an exception is proposed by a holder of a product-governance role' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_body) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'governance exception rejected (body): the exception is an object' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.ws_exceptions:' || p_exception::text, 0));
  SELECT coalesce(max(e.version), 0) INTO v_cur FROM governance.ws_exceptions e WHERE e.exception_id = p_exception;
  IF p_expected_version IS DISTINCT FROM v_cur THEN
    RAISE EXCEPTION 'governance exception rejected (stale): the exception is at version % (expected %)', v_cur, coalesce(p_expected_version::text, '<none>') USING ERRCODE = '23505';
  END IF;
  IF v_cur > 0 THEN
    SELECT * INTO cur FROM governance.ws_exceptions e WHERE e.exception_id = p_exception AND e.version = v_cur;
    IF cur.state NOT IN ('approved', 'expired') THEN
      RAISE EXCEPTION 'governance exception rejected (state): only an approved or expired exception is renewed (version % is %)', v_cur, cur.state USING ERRCODE = '23505';
    END IF;
  END IF;
  -- the fields (a renewal may restate them; the identity — contract, requirement, system scope — stays the exception's)
  v_contract := btrim(coalesce(p_body ->> 'contractKey', cur.contract_key, ''));
  IF v_cur > 0 AND v_contract IS DISTINCT FROM cur.contract_key THEN RAISE EXCEPTION 'governance exception rejected (identity): a renewal keeps its contract (%)', cur.contract_key USING ERRCODE = '22023'; END IF;
  IF length(v_contract) < 3 THEN RAISE EXCEPTION 'governance exception rejected (contract): the contract the exception is against is named (contractKey)' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_body ->> 'requirementRef', cur.requirement_ref, ''))) < 3 THEN RAISE EXCEPTION 'governance exception rejected (requirement): the unmet requirement is named (requirementRef)' USING ERRCODE = '22023'; END IF;
  v_req := CASE WHEN p_body ? 'requirementArtifact' AND jsonb_typeof(p_body -> 'requirementArtifact') = 'string' THEN (p_body ->> 'requirementArtifact')::uuid ELSE cur.requirement_artifact END;
  IF v_req IS NOT NULL THEN PERFORM governance.ws_assert_artifacts('governance exception', ARRAY[v_req], ARRAY['requirement'], 'requirementArtifact'); END IF;
  v_sys := CASE WHEN p_body ? 'systemScope' THEN ARRAY(SELECT DISTINCT x::uuid FROM jsonb_array_elements_text(p_body -> 'systemScope') x ORDER BY 1) ELSE cur.system_scope END;
  IF cardinality(coalesce(v_sys, '{}')) = 0 THEN RAISE EXCEPTION 'governance exception rejected (system_scope): the system scope names at least one component / unit / interface artifact' USING ERRCODE = '22023'; END IF;
  PERFORM governance.ws_assert_artifacts('governance exception', v_sys, ARRAY['component', 'deployable_unit', 'interface', 'schema', 'policy_bundle', 'data_product', 'capability'], 'systemScope');
  v_aff := CASE WHEN p_body ? 'affectedArtifacts' THEN ARRAY(SELECT DISTINCT x::uuid FROM jsonb_array_elements_text(p_body -> 'affectedArtifacts') x ORDER BY 1) ELSE cur.affected_artifacts END;
  v_aff := coalesce(v_aff, '{}');
  PERFORM governance.ws_assert_artifacts('governance exception', v_aff, ARRAY['release_candidate', 'data_product', 'capability', 'deployable_unit'], 'affectedArtifacts');
  v_scope := governance.ws_customer_scope(coalesce(p_body -> 'customerScope', cur.customer_scope));
  v_inv := CASE WHEN p_body ? 'affectedInvariants' THEN ARRAY(SELECT DISTINCT lower(btrim(x)) FROM jsonb_array_elements_text(p_body -> 'affectedInvariants') x ORDER BY 1) ELSE cur.affected_invariants END;
  v_bad := ARRAY(SELECT x FROM unnest(coalesce(v_inv, '{}')) x WHERE x = ANY (governance.ws_constitutional_invariants()));
  IF cardinality(v_bad) > 0 THEN
    RAISE EXCEPTION 'governance exception rejected (constitutional): % cannot be waived through an ordinary exception — it is a constitutional boundary (amend only through the authority chain)', array_to_string(v_bad, ', ') USING ERRCODE = '22023';
  END IF;
  v_risk := coalesce(p_body -> 'risk', cur.risk);
  IF jsonb_typeof(v_risk) IS DISTINCT FROM 'object' OR NOT ((v_risk ->> 'level') IN ('low', 'medium', 'high', 'critical')) OR length(btrim(coalesce(v_risk ->> 'statement', ''))) < 12 THEN
    RAISE EXCEPTION 'governance exception rejected (risk): the risk is {level: low | medium | high | critical, statement (12+ characters)}' USING ERRCODE = '22023';
  END IF;
  v_controls := coalesce(p_body -> 'compensatingControls', cur.compensating_controls);
  IF jsonb_typeof(v_controls) IS DISTINCT FROM 'array' OR jsonb_array_length(v_controls) = 0
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_controls) c WHERE jsonb_typeof(c) <> 'string' OR length(btrim(c #>> '{}')) < 8) THEN
    RAISE EXCEPTION 'governance exception rejected (controls): at least one compensating control is stated (8+ characters each)' USING ERRCODE = '22023';
  END IF;
  v_owner := CASE WHEN jsonb_typeof(p_body -> 'owner') = 'string' THEN (p_body ->> 'owner')::uuid ELSE cur.owner_principal_id END;
  IF v_owner IS NULL OR NOT governance.ws_is_human(v_owner) THEN RAISE EXCEPTION 'governance exception rejected (owner): the exception''s owner is a named active human' USING ERRCODE = '22023'; END IF;
  v_exp := coalesce((p_body ->> 'expandsAuthority')::boolean, cur.expands_authority, false);
  v_rem := coalesce((p_body ->> 'removesControl')::boolean, cur.removes_control, false);
  v_starts := coalesce((p_body ->> 'startsAt')::timestamptz, clock_timestamp());
  v_expires := (p_body ->> 'expiresAt')::timestamptz;
  IF v_expires IS NULL OR v_expires <= clock_timestamp() OR v_expires <= v_starts OR v_expires > v_starts + interval '366 days' THEN
    RAISE EXCEPTION 'governance exception rejected (expiry): an exception expires at a named instant after now and its start, within 366 days ("later" is not an expiry)' USING ERRCODE = '22023';
  END IF;
  IF v_starts < clock_timestamp() - interval '1 day' THEN RAISE EXCEPTION 'governance exception rejected (start): an exception starts now or later (never back-dated)' USING ERRCODE = '22023'; END IF;
  FOR v_ref IN SELECT k FROM unnest(ARRAY['title', 'reason', 'monitoring', 'exitCriteria', 'remediationPlan']) k LOOP
    IF length(btrim(coalesce(p_body ->> v_ref, CASE v_ref WHEN 'title' THEN cur.title WHEN 'reason' THEN cur.reason WHEN 'monitoring' THEN cur.monitoring WHEN 'exitCriteria' THEN cur.exit_criteria ELSE cur.remediation_plan END, ''))) < (CASE v_ref WHEN 'reason' THEN 20 ELSE 8 END) THEN
      RAISE EXCEPTION 'governance exception rejected (%): % is stated (% + characters)', lower(v_ref), v_ref, CASE v_ref WHEN 'reason' THEN 20 ELSE 8 END USING ERRCODE = '22023';
    END IF;
  END LOOP;
  -- the evidence: named on a new exception; CURRENT on a renewal (captured within 30 days, after the prior approval, still valid)
  v_evidence := governance.ws_evidence('governance exception', p_body -> 'evidence', v_cur > 0, governance.ws_evidence_currency_days(), CASE WHEN v_cur > 0 THEN cur.decided_at END);
  v_roles := CASE WHEN v_exp OR v_rem THEN ARRAY['independent_assurance'] ELSE ARRAY['independent_assurance', 'product_authority'] END;
  v_version := v_cur + 1;
  v_ref := CASE WHEN v_cur > 0 THEN cur.ref ELSE governance.ws_next_ref('GEX') END;
  v_digest := governance.digest(jsonb_build_object('exception_id', p_exception, 'version', v_version, 'title', btrim(coalesce(p_body ->> 'title', cur.title)),
               'requirement_ref', btrim(coalesce(p_body ->> 'requirementRef', cur.requirement_ref)), 'requirement_artifact', v_req, 'contract_key', v_contract, 'system_scope', to_jsonb(v_sys),
               'customer_scope', v_scope, 'reason', btrim(coalesce(p_body ->> 'reason', cur.reason)), 'evidence', v_evidence, 'risk', v_risk, 'affected_invariants', to_jsonb(coalesce(v_inv, '{}')),
               'compensating_controls', v_controls, 'owner', v_owner, 'expands_authority', v_exp, 'removes_control', v_rem, 'approver_roles', to_jsonb(v_roles), 'starts_at', v_starts,
               'expires_at', v_expires, 'monitoring', btrim(coalesce(p_body ->> 'monitoring', cur.monitoring)), 'exit_criteria', btrim(coalesce(p_body ->> 'exitCriteria', cur.exit_criteria)),
               'remediation_plan', btrim(coalesce(p_body ->> 'remediationPlan', cur.remediation_plan)), 'affected_artifacts', to_jsonb(v_aff), 'renewal_of', CASE WHEN v_cur > 0 THEN v_cur END));
  INSERT INTO governance.ws_exceptions (exception_id, version, ref, renewal_of, title, requirement_ref, requirement_artifact, contract_key, system_scope, customer_scope, reason, evidence, risk,
                                        affected_invariants, compensating_controls, owner_principal_id, expands_authority, removes_control, approver_roles, starts_at, expires_at, monitoring,
                                        exit_criteria, remediation_plan, affected_artifacts, digest, proposed_by, correlation_id)
  VALUES (p_exception, v_version, v_ref, CASE WHEN v_cur > 0 THEN v_cur END, btrim(coalesce(p_body ->> 'title', cur.title)), btrim(coalesce(p_body ->> 'requirementRef', cur.requirement_ref)), v_req,
          v_contract, v_sys, v_scope, btrim(coalesce(p_body ->> 'reason', cur.reason)), v_evidence, v_risk, coalesce(v_inv, '{}'), v_controls, v_owner, v_exp, v_rem, v_roles, v_starts, v_expires,
          btrim(coalesce(p_body ->> 'monitoring', cur.monitoring)), btrim(coalesce(p_body ->> 'exitCriteria', cur.exit_criteria)), btrim(coalesce(p_body ->> 'remediationPlan', cur.remediation_plan)),
          v_aff, v_digest, p_actor, p_correlation);
  IF v_cur = 0 THEN  -- a renewal is registered when decided (the exception's artifact keeps its standing until then)
    PERFORM governance.ws_register(p_exception, 'exception', v_ref, btrim(coalesce(p_body ->> 'title', cur.title)), v_owner, NULL, NULL, NULL, 'proposed',
              jsonb_build_object('version', v_version, 'state', 'proposed', 'contract_key', v_contract, 'expires_at', v_expires, 'class', 'product'), v_digest, p_actor, p_correlation);
    FOR v_rid IN SELECT unnest(v_sys) LOOP PERFORM governance.ws_link(p_exception, v_rid, 'excepts', jsonb_build_object('scope', 'system'), p_actor, p_correlation); END LOOP;
    IF v_req IS NOT NULL THEN PERFORM governance.ws_link(p_exception, v_req, 'excepts', jsonb_build_object('scope', 'requirement'), p_actor, p_correlation); END IF;
    FOR v_rid IN SELECT unnest(v_aff) LOOP PERFORM governance.ws_link(p_exception, v_rid, 'covers', jsonb_build_object('scope', 'affected promotion'), p_actor, p_correlation); END LOOP;
  END IF;
  -- REPEATS (V03-T-451): the contract's distinct live-or-proposed exceptions, or this exception's third period
  SELECT count(DISTINCT e.exception_id), array_agg(DISTINCT e.exception_id) INTO v_count, v_list FROM governance.ws_exceptions e
   WHERE e.contract_key = v_contract AND e.state IN ('proposed', 'approved', 'expired', 'closed', 'superseded');
  IF (v_cur = 0 AND v_count >= governance.ws_repeat_threshold()) OR v_version >= 3 THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('governance.ws_exception_reviews:' || v_contract, 0));
    SELECT jsonb_build_object('review_id', r.review_id, 'ref', r.ref, 'state', r.state, 'existing', true) INTO v_review FROM governance.ws_exception_reviews r WHERE r.contract_key = v_contract AND r.state = 'open';
    IF v_review IS NULL THEN
      v_rid := gen_random_uuid();
      INSERT INTO governance.ws_exception_reviews (review_id, ref, contract_key, trigger, exceptions, opened_by, correlation_id)
      VALUES (v_rid, governance.ws_next_ref('GRR'), v_contract, CASE WHEN v_cur = 0 THEN 'repeated_exceptions' ELSE 'repeated_renewal' END, v_list, p_actor, p_correlation);
      PERFORM governance.ledger(NULL, NULL, 'governance_exception', v_rid, 1, 'exception.review_opened', p_actor,
                jsonb_build_object('contract_key', v_contract, 'trigger', CASE WHEN v_cur = 0 THEN 'repeated_exceptions' ELSE 'repeated_renewal' END, 'exceptions', to_jsonb(v_list),
                                   'rule', 'repeated exceptions are architecture evidence: remediation or formal change review — they never quietly redefine the baseline'), p_correlation);
      SELECT jsonb_build_object('review_id', r.review_id, 'ref', r.ref, 'state', r.state, 'existing', false) INTO v_review FROM governance.ws_exception_reviews r WHERE r.review_id = v_rid;
    END IF;
  END IF;
  PERFORM governance.ledger(NULL, NULL, 'governance_exception', p_exception, v_version, CASE WHEN v_cur = 0 THEN 'exception.proposed' ELSE 'exception.renewal_proposed' END, p_actor,
            jsonb_build_object('digest', v_digest, 'contract_key', v_contract, 'expires_at', v_expires, 'approver_roles', to_jsonb(v_roles), 'renewal_of', CASE WHEN v_cur > 0 THEN v_cur END,
                               'review', v_review), p_correlation);
  RETURN jsonb_build_object('exception_id', p_exception, 'ref', v_ref, 'version', v_version, 'state', 'proposed', 'digest', v_digest, 'approver_roles', to_jsonb(v_roles),
                            'renewal_of', CASE WHEN v_cur > 0 THEN v_cur END, 'review', v_review, 'expires_at', v_expires);
END $$;
REVOKE ALL ON FUNCTION governance.ws_propose_exception(uuid, jsonb, int, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_propose_exception(uuid, jsonb, int, uuid, uuid) TO eye_commit;

/* DECIDE (approve | reject) an exception version — INDEPENDENTLY: a named human holding one of the version's approver roles, never the
   proposer, never the owner, never an owner of a component the exception expands (ES-02-004); the decision-rights matrix's `exception`
   approve row when one governs; on the exact digest; HELD while a remediation review on the contract is open; refused once the window has
   passed; evidence still valid. APPROVE is SIGNED (`exception_approval`). A RENEWAL's approval supersedes the prior version and LIFTS the
   holds its expiry opened (the affected promotion released) and closes its attention items. */
CREATE OR REPLACE FUNCTION governance.ws_decide_exception(p_exception uuid, p_version int, p_decision text, p_digest text, p_reason text, p_signature uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, public, pg_catalog, pg_temp AS $$
DECLARE e governance.ws_exceptions%ROWTYPE; v_owners uuid[]; v_review governance.ws_exception_reviews%ROWTYPE; v_lifted jsonb := '[]'::jsonb; v_role text; v_via jsonb; v_items jsonb := '[]'::jsonb; d record;
BEGIN
  PERFORM governance.assert_platform('governance.exception.decide', p_actor, 'governance exception');
  SELECT * INTO e FROM governance.ws_exceptions x WHERE x.exception_id = p_exception AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'governance exception rejected (unknown_exception): no exception %/v%', p_exception, p_version USING ERRCODE = '23503'; END IF;
  v_owners := governance.ws_scope_owners(e.system_scope);
  IF p_actor = ANY (v_owners) AND (e.expands_authority OR e.removes_control) THEN
    RAISE EXCEPTION 'governance exception rejected (separation_of_duties): you own a component whose authority this exception expands or whose independent control it removes — no component owner approves it (ES-02-004)' USING ERRCODE = '42501';
  END IF;
  IF p_actor = e.owner_principal_id THEN
    RAISE EXCEPTION 'governance exception rejected (separation_of_duties): the exception''s owner never approves it (independent approver)' USING ERRCODE = '42501';
  END IF;
  PERFORM governance.assert_approver('governance exception', p_actor, NULL, NULL, e.approver_roles, e.proposed_by, array_append(v_owners, e.owner_principal_id), 'approving an exception');
  v_via := governance.ws_assert_rights('governance exception', 'exception', 'approve', p_actor);
  IF e.state <> 'proposed' THEN RAISE EXCEPTION 'governance exception rejected (state): version % is %', p_version, e.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM e.digest THEN RAISE EXCEPTION 'governance exception rejected (stale): the decision names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF p_decision NOT IN ('approve', 'reject') THEN RAISE EXCEPTION 'governance exception rejected (decision): approve or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'governance exception rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  SELECT r.code INTO v_role FROM identity.role_bindings b JOIN identity.roles r ON r.code = b.role_code
   WHERE b.principal_id = p_actor AND b.revoked_at IS NULL AND b.scope = 'PLATFORM' AND b.role_code = ANY (e.approver_roles) ORDER BY array_position(e.approver_roles, b.role_code) LIMIT 1;
  IF p_decision = 'approve' THEN
    SELECT * INTO v_review FROM governance.ws_exception_reviews r WHERE r.contract_key = e.contract_key AND r.state = 'open';
    IF FOUND THEN
      RAISE EXCEPTION 'governance exception rejected (held): the repeated exceptions against % are under remediation review % — no exception on the contract is approved until the product authority decides it (V03-T-451)', e.contract_key, v_review.ref USING ERRCODE = '23505';
    END IF;
    IF e.expires_at <= clock_timestamp() THEN
      RAISE EXCEPTION 'governance exception rejected (expired): version % expired at % before it was approved — propose a renewal with current evidence', p_version, e.expires_at USING ERRCODE = '23505';
    END IF;
    PERFORM governance.ws_evidence('governance exception', e.evidence, true, 366, NULL);
    IF NOT governance.ws_signed(p_signature, 'exception_approval', p_exception, p_version, e.digest, p_actor, 'governance.exception.decide') THEN
      RAISE EXCEPTION 'governance exception rejected (signature): approval carries the approver''s signature over the exception digest' USING ERRCODE = '22023';
    END IF;
    IF e.renewal_of IS NOT NULL THEN
      UPDATE governance.ws_exceptions SET state = 'superseded' WHERE exception_id = p_exception AND version = e.renewal_of AND state IN ('approved', 'expired');
      v_lifted := governance.ws_lift_holds(p_exception, 'exception_expired', format('renewed: %s v%s approved by %s with current evidence', e.ref, p_version, governance.ws_principal_name(p_actor)), p_actor);
      FOR d IN SELECT DISTINCT i.tenant_id, i.domain_id FROM executive.attention_items i WHERE i.subject_id = p_exception AND i.signal_class = 'governance.exception' AND i.state <> 'closed' LOOP
        v_items := v_items || executive.b33_close_items(d.tenant_id, d.domain_id, 'governance.exception', 'governance_exception', p_exception, format('%s renewed (v%s approved)', e.ref, p_version), p_actor, p_correlation);
      END LOOP;
    END IF;
  END IF;
  UPDATE governance.ws_exceptions SET state = CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END, decided_by = p_actor, decided_role = v_role, decided_at = clock_timestamp(),
         decision_reason = btrim(p_reason), signature_id = CASE WHEN p_decision = 'approve' THEN p_signature END
   WHERE exception_id = p_exception AND version = p_version;
  PERFORM governance.ws_register(p_exception, 'exception', e.ref, e.title, e.owner_principal_id, NULL, NULL, NULL, CASE WHEN p_decision = 'approve' THEN 'active' ELSE 'retired' END,
            jsonb_build_object('version', p_version, 'state', CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END, 'contract_key', e.contract_key, 'expires_at', e.expires_at, 'class', 'product'),
            e.digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'governance_exception', p_exception, p_version, CASE WHEN p_decision = 'approve' THEN (CASE WHEN e.renewal_of IS NULL THEN 'exception.approved' ELSE 'exception.renewed' END) ELSE 'exception.rejected' END,
            p_actor, jsonb_build_object('digest', e.digest, 'reason', btrim(p_reason), 'role', v_role, 'signature_id', p_signature, 'holds_lifted', v_lifted, 'items_closed', v_items, 'rights_via', v_via), p_correlation);
  RETURN jsonb_build_object('exception_id', p_exception, 'ref', e.ref, 'version', p_version, 'state', CASE WHEN p_decision = 'approve' THEN 'approved' ELSE 'rejected' END, 'digest', e.digest,
                            'decided_role', v_role, 'signature_id', p_signature, 'holds_lifted', v_lifted, 'expires_at', e.expires_at);
END $$;
REVOKE ALL ON FUNCTION governance.ws_decide_exception(uuid, int, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_decide_exception(uuid, int, text, text, text, uuid, uuid, uuid) TO eye_commit;

/* WITHDRAW an open proposal (its proposer or its owner). */
CREATE OR REPLACE FUNCTION governance.ws_withdraw_exception(p_exception uuid, p_version int, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE e governance.ws_exceptions%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.exception.withdraw', p_actor, 'governance exception');
  SELECT * INTO e FROM governance.ws_exceptions x WHERE x.exception_id = p_exception AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'governance exception rejected (unknown_exception): no exception %/v%', p_exception, p_version USING ERRCODE = '23503'; END IF;
  IF p_actor NOT IN (e.proposed_by, e.owner_principal_id) THEN RAISE EXCEPTION 'governance exception rejected (ownership): a proposal is withdrawn by its proposer or its owner' USING ERRCODE = '42501'; END IF;
  IF e.state <> 'proposed' THEN RAISE EXCEPTION 'governance exception rejected (state): version % is %', p_version, e.state USING ERRCODE = '23505'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'governance exception rejected (reason): a withdrawal states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  UPDATE governance.ws_exceptions SET state = 'withdrawn', decided_by = p_actor, decided_at = clock_timestamp(), decision_reason = btrim(p_reason) WHERE exception_id = p_exception AND version = p_version;
  PERFORM governance.ledger(NULL, NULL, 'governance_exception', p_exception, p_version, 'exception.withdrawn', p_actor, jsonb_build_object('reason', btrim(p_reason)), p_correlation);
  RETURN jsonb_build_object('exception_id', p_exception, 'ref', e.ref, 'version', p_version, 'state', 'withdrawn');
END $$;
REVOKE ALL ON FUNCTION governance.ws_withdraw_exception(uuid, int, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_withdraw_exception(uuid, int, text, uuid, uuid) TO eye_commit;

/* CLOSE an approved or expired exception on its EXIT CRITERIA (verified closure): an approver of the exception (never its owner or proposer),
   on current exit evidence; the holds its expiry opened are lifted (the requirement is met — nothing is excepted any more). */
CREATE OR REPLACE FUNCTION governance.ws_close_exception(p_exception uuid, p_version int, p_exit_evidence jsonb, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, public, pg_catalog, pg_temp AS $$
DECLARE e governance.ws_exceptions%ROWTYPE; v_ev jsonb; v_lifted jsonb; d record;
BEGIN
  PERFORM governance.assert_platform('governance.exception.close', p_actor, 'governance exception');
  SELECT * INTO e FROM governance.ws_exceptions x WHERE x.exception_id = p_exception AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'governance exception rejected (unknown_exception): no exception %/v%', p_exception, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('governance exception', p_actor, NULL, NULL, e.approver_roles, e.proposed_by, array_append(governance.ws_scope_owners(e.system_scope), e.owner_principal_id), 'closing an exception on its exit criteria');
  IF e.state NOT IN ('approved', 'expired') THEN RAISE EXCEPTION 'governance exception rejected (state): version % is % — only an approved or expired exception is closed', p_version, e.state USING ERRCODE = '23505'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'governance exception rejected (reason): a closure states how the exit criteria are met (8+ characters)' USING ERRCODE = '22023'; END IF;
  v_ev := governance.ws_evidence('governance exception', p_exit_evidence, true, governance.ws_evidence_currency_days(), e.decided_at);
  UPDATE governance.ws_exceptions SET state = 'closed', closed_by = p_actor, closed_at = clock_timestamp(), close_reason = btrim(p_reason), exit_evidence = v_ev WHERE exception_id = p_exception AND version = p_version;
  v_lifted := governance.ws_lift_holds(p_exception, 'exception_expired', format('closed: %s v%s exit criteria met (verified by %s)', e.ref, p_version, governance.ws_principal_name(p_actor)), p_actor);
  FOR d IN SELECT DISTINCT i.tenant_id, i.domain_id FROM executive.attention_items i WHERE i.subject_id = p_exception AND i.signal_class = 'governance.exception' AND i.state <> 'closed' LOOP
    PERFORM executive.b33_close_items(d.tenant_id, d.domain_id, 'governance.exception', 'governance_exception', p_exception, format('%s closed on its exit criteria', e.ref), p_actor, p_correlation);
  END LOOP;
  PERFORM governance.ws_register(p_exception, 'exception', e.ref, e.title, e.owner_principal_id, NULL, NULL, NULL, 'retired',
            jsonb_build_object('version', p_version, 'state', 'closed', 'contract_key', e.contract_key, 'class', 'product'), e.digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'governance_exception', p_exception, p_version, 'exception.closed', p_actor,
            jsonb_build_object('reason', btrim(p_reason), 'exit_evidence', v_ev, 'holds_lifted', v_lifted), p_correlation);
  RETURN jsonb_build_object('exception_id', p_exception, 'ref', e.ref, 'version', p_version, 'state', 'closed', 'holds_lifted', v_lifted);
END $$;
REVOKE ALL ON FUNCTION governance.ws_close_exception(uuid, int, jsonb, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_close_exception(uuid, int, jsonb, text, uuid, uuid) TO eye_commit;

/* THE EXPIRY SWEEP (idempotent; nothing written when nothing expired): every approved exception past its expiry → `expired`, every affected
   artifact HELD (`exception_expired`) until a renewal with current evidence or a closure. Run by the conformance steward at PLATFORM
   (governance.exception.sweep) or by the ATTENTION TICK in a domain (executive.attention.tick: the PLATFORM rows through this definer port,
   and — the tick's own domain only — a `governance.exception` attention item for each expired exception whose customer scope covers it). */
CREATE OR REPLACE FUNCTION governance.ws_sweep_exceptions(p_action text, p_tenant uuid, p_domain uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, observation, public, pg_catalog, pg_temp AS $$
DECLARE e record; a uuid; v_expired jsonb := '[]'::jsonb; v_holds jsonb; v_items jsonb := '[]'::jsonb; v_ev uuid; v_item jsonb;
BEGIN
  IF p_action = 'executive.attention.tick' THEN
    PERFORM observation.assert_authority(ARRAY['executive.attention.tick']);
    PERFORM observation.assert_scope(p_tenant, p_domain);
    IF p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'governance exception rejected (actor): the sweep is recorded under the acting principal' USING ERRCODE = '42501'; END IF;
  ELSIF p_action = 'governance.exception.sweep' THEN
    PERFORM governance.assert_platform('governance.exception.sweep', p_actor, 'governance exception');
    IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['conformance_steward']) THEN
      RAISE EXCEPTION 'governance exception rejected (authority): the vendor-side sweep is the conformance steward''s' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'governance exception rejected (authority): the sweep runs under governance.exception.sweep or executive.attention.tick' USING ERRCODE = '42501';
  END IF;
  FOR e IN SELECT x.exception_id, x.version, x.ref, x.title, x.expires_at, x.affected_artifacts, x.contract_key FROM governance.ws_exceptions x
            WHERE x.state = 'approved' AND x.expires_at <= clock_timestamp() ORDER BY x.expires_at, x.exception_id FOR UPDATE SKIP LOCKED LOOP
    UPDATE governance.ws_exceptions SET state = 'expired', expired_at = clock_timestamp() WHERE exception_id = e.exception_id AND version = e.version;
    v_holds := '[]'::jsonb;
    FOREACH a IN ARRAY e.affected_artifacts LOOP
      v_holds := v_holds || to_jsonb(governance.ws_open_hold(a, 'exception_expired', e.exception_id,
                   format('exception %s v%s (%s) expired at %s — the affected promotion is held until a renewal with current evidence is approved independently, or the exception is closed on its exit criteria',
                          e.ref, e.version, e.contract_key, e.expires_at), p_actor, p_correlation));
    END LOOP;
    PERFORM governance.ws_register(e.exception_id, 'exception', e.ref, e.title, (SELECT owner_principal_id FROM governance.ws_exceptions WHERE exception_id = e.exception_id AND version = e.version),
              NULL, NULL, NULL, 'deprecated', jsonb_build_object('version', e.version, 'state', 'expired', 'contract_key', e.contract_key, 'expires_at', e.expires_at, 'class', 'product'),
              (SELECT digest FROM governance.ws_exceptions WHERE exception_id = e.exception_id AND version = e.version), p_actor, p_correlation);
    PERFORM governance.ledger(NULL, NULL, 'governance_exception', e.exception_id, e.version, 'exception.expired', p_actor,
              jsonb_build_object('expires_at', e.expires_at, 'holds', v_holds, 'via', p_action), p_correlation);
    v_expired := v_expired || jsonb_build_object('exception_id', e.exception_id, 'ref', e.ref, 'version', e.version, 'expires_at', e.expires_at, 'holds', v_holds);
  END LOOP;
  IF p_action = 'executive.attention.tick' THEN
    FOR e IN SELECT x.exception_id, x.version, x.ref, x.title, x.expires_at, x.owner_principal_id FROM governance.ws_exceptions x
              WHERE x.state = 'expired' AND governance.ws_scope_covers(x.customer_scope, p_tenant, p_domain) ORDER BY x.expires_at LOOP
      SELECT g.event_id INTO v_ev FROM governance.events g WHERE g.subject_id = e.exception_id AND g.version = e.version AND g.event = 'exception.expired' ORDER BY g.occurred_at LIMIT 1;
      CONTINUE WHEN v_ev IS NULL;  -- the item is keyed on the expiry event (one item per expiry per domain, never re-raised)
      v_item := executive.b33_raise_routed(p_tenant, p_domain, 'governance.exception', 'governance_exception', e.exception_id,
                  format('Exception %s expired — the affected promotion is held until renewal with current evidence', e.ref),
                  jsonb_build_array(format('expired at %s', e.expires_at)), NULL, v_ev, 'governance.exception_expired',
                  jsonb_build_object('ref', e.ref, 'version', e.version, 'title', e.title, 'workspace', '/admin/governance'), NULL, p_actor, p_correlation);
      IF NOT coalesce((v_item ->> 'existing')::boolean, false) THEN v_items := v_items || v_item; END IF;
    END LOOP;
  END IF;
  RETURN jsonb_build_object('expired', v_expired, 'items_raised', v_items, 'via', p_action, 'swept_at', clock_timestamp());
END $$;
REVOKE ALL ON FUNCTION governance.ws_sweep_exceptions(text, uuid, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_sweep_exceptions(text, uuid, uuid, uuid, uuid) TO eye_commit;

/* DECIDE a remediation review (the product authority, never its opener): `remediation` (a plan, an accountable owner — a named human —, a due
   day) or `change_review` (a change proposal of this registry). Exceptions on the contract may be approved again only after this. */
CREATE OR REPLACE FUNCTION governance.ws_decide_review(p_review uuid, p_decision text, p_body jsonb, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE r governance.ws_exception_reviews%ROWTYPE; v_rem jsonb := NULL; v_cp uuid := NULL;
BEGIN
  PERFORM governance.assert_platform('governance.remediation.decide', p_actor, 'governance exception');
  SELECT * INTO r FROM governance.ws_exception_reviews x WHERE x.review_id = p_review FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'governance exception rejected (unknown_review): no remediation review %', p_review USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('governance exception', p_actor, NULL, NULL, ARRAY['product_authority'], r.opened_by, NULL, 'deciding a remediation review');
  IF r.state <> 'open' THEN RAISE EXCEPTION 'governance exception rejected (state): review % is %', r.ref, r.state USING ERRCODE = '23505'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'governance exception rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'remediation' THEN
    IF length(btrim(coalesce(p_body ->> 'plan', ''))) < 20 OR coalesce(p_body ->> 'dueOn', '') !~ '^\d{4}-\d{2}-\d{2}$' OR jsonb_typeof(p_body -> 'owner') <> 'string'
       OR NOT governance.ws_is_human((p_body ->> 'owner')::uuid) OR (p_body ->> 'dueOn')::date < (clock_timestamp() AT TIME ZONE 'UTC')::date THEN
      RAISE EXCEPTION 'governance exception rejected (remediation): a remediation names its plan (20+ characters), its accountable owner (a named human) and its due day (today or later)' USING ERRCODE = '22023';
    END IF;
    v_rem := jsonb_build_object('plan', btrim(p_body ->> 'plan'), 'owner', p_body ->> 'owner', 'due_on', p_body ->> 'dueOn');
  ELSIF p_decision = 'change_review' THEN
    v_cp := CASE WHEN jsonb_typeof(p_body -> 'changeProposal') = 'string' THEN (p_body ->> 'changeProposal')::uuid END;
    IF v_cp IS NULL OR NOT EXISTS (SELECT 1 FROM governance.ws_change_proposals c WHERE c.proposal_id = v_cp) THEN
      RAISE EXCEPTION 'governance exception rejected (unknown_proposal): a formal change review names a change proposal of this registry' USING ERRCODE = '23503';
    END IF;
  ELSE
    RAISE EXCEPTION 'governance exception rejected (decision): remediation or change_review' USING ERRCODE = '22023';
  END IF;
  UPDATE governance.ws_exception_reviews SET state = p_decision, decided_by = p_actor, decided_at = clock_timestamp(), decision_reason = btrim(p_reason), remediation = v_rem, change_proposal = v_cp
   WHERE review_id = p_review;
  PERFORM governance.ledger(NULL, NULL, 'governance_exception', p_review, 1, 'exception.review_decided', p_actor,
            jsonb_build_object('contract_key', r.contract_key, 'decision', p_decision, 'remediation', v_rem, 'change_proposal', v_cp, 'reason', btrim(p_reason)), p_correlation);
  RETURN jsonb_build_object('review_id', p_review, 'ref', r.ref, 'contract_key', r.contract_key, 'state', p_decision, 'remediation', v_rem, 'change_proposal', v_cp);
END $$;
REVOKE ALL ON FUNCTION governance.ws_decide_review(uuid, text, jsonb, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_decide_review(uuid, text, jsonb, text, uuid, uuid) TO eye_commit;

/* THE AGEING (a read): per exception — the effective state on the database clock (an approved exception past its expiry reads
   `expired (sweep pending)`: never shown in force), age, days to expiry, periods, renewals; and the totals and buckets. */
CREATE OR REPLACE FUNCTION governance.ws_exception_ageing() RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  WITH cur AS (
    SELECT DISTINCT ON (e.exception_id) e.* FROM governance.ws_exceptions e WHERE e.state NOT IN ('withdrawn') ORDER BY e.exception_id, e.version DESC),
  firsts AS (SELECT e.exception_id, min(e.starts_at) AS first_start, count(*) FILTER (WHERE e.renewal_of IS NOT NULL AND e.state IN ('approved', 'expired', 'closed', 'superseded')) AS renewals
              FROM governance.ws_exceptions e GROUP BY e.exception_id),
  xr AS (
    SELECT c.exception_id, c.ref, c.version, c.contract_key, c.title,
           CASE WHEN c.state = 'approved' AND c.expires_at <= clock_timestamp() THEN 'expired (sweep pending)' ELSE c.state END AS effective_state,
           c.expires_at, floor(extract(epoch FROM (clock_timestamp() - f.first_start)) / 86400)::int AS age_days,
           CASE WHEN c.state = 'approved' THEN floor(extract(epoch FROM (c.expires_at - clock_timestamp())) / 86400)::int END AS days_to_expiry, f.renewals
      FROM cur c JOIN firsts f ON f.exception_id = c.exception_id)
  SELECT jsonb_build_object(
    'rows', coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.expires_at) FROM xr r), '[]'::jsonb),
    'totals', jsonb_build_object(
      'in_force', (SELECT count(*) FROM xr r WHERE r.effective_state = 'approved'),
      'expired', (SELECT count(*) FROM xr r WHERE r.effective_state IN ('expired', 'expired (sweep pending)')),
      'proposed', (SELECT count(*) FROM xr r WHERE r.effective_state = 'proposed'),
      'closed', (SELECT count(*) FROM xr r WHERE r.effective_state = 'closed'),
      'expiring_14d', (SELECT count(*) FROM xr r WHERE r.effective_state = 'approved' AND r.days_to_expiry < 14),
      'renewals', (SELECT coalesce(sum(r.renewals), 0) FROM xr r),
      'mean_age_days_open', (SELECT round(avg(r.age_days)::numeric, 1) FROM xr r WHERE r.effective_state IN ('approved', 'expired', 'expired (sweep pending)', 'proposed'))),
    'buckets', jsonb_build_object(
      '0-30', (SELECT count(*) FROM xr r WHERE r.effective_state NOT IN ('closed', 'rejected') AND r.age_days <= 30),
      '31-90', (SELECT count(*) FROM xr r WHERE r.effective_state NOT IN ('closed', 'rejected') AND r.age_days BETWEEN 31 AND 90),
      '91-180', (SELECT count(*) FROM xr r WHERE r.effective_state NOT IN ('closed', 'rejected') AND r.age_days BETWEEN 91 AND 180),
      '>180', (SELECT count(*) FROM xr r WHERE r.effective_state NOT IN ('closed', 'rejected') AND r.age_days > 180)),
    'read_at', clock_timestamp()) $$;
GRANT EXECUTE ON FUNCTION governance.ws_exception_ageing() TO eye_app, eye_commit;

-- §PG.5 (declared before the conflict register, which names change proposals) CHANGE PROPOSALS ────────────────────────────────────────────
CREATE TABLE governance.ws_change_proposals (
  proposal_id     uuid NOT NULL,
  version         int  NOT NULL CHECK (version >= 1),
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  ref             text NOT NULL,
  title           text NOT NULL CHECK (length(btrim(title)) BETWEEN 8 AND 300),
  change_class    text NOT NULL CHECK (change_class IN ('interface', 'object', 'policy', 'model', 'agent', 'workflow', 'deployment', 'requirement', 'capability', 'baseline', 'data_contract')),
  subjects        uuid[] NOT NULL,
  description     text NOT NULL CHECK (length(btrim(description)) >= 20),
  plans           jsonb NOT NULL CHECK (jsonb_typeof(plans) = 'object'),
  missing_plans   text[] NOT NULL,
  builders        uuid[] NOT NULL,
  alters_identity boolean NOT NULL,
  cross_volume    boolean NOT NULL,
  constitutional  boolean NOT NULL,
  required_roles  text[] NOT NULL,
  impact          jsonb NOT NULL,
  impact_digest   text NOT NULL CHECK (impact_digest ~ '^[0-9a-f]{64}$'),
  digest          text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  state           text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'approved', 'rejected', 'withdrawn', 'superseded')),
  proposed_by     uuid NOT NULL,
  proposed_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_at      timestamptz,
  decision_reason text,
  claim           text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  correlation_id  uuid NOT NULL,
  PRIMARY KEY (proposal_id, version)
);
CREATE UNIQUE INDEX wcp_one_open ON governance.ws_change_proposals (proposal_id) WHERE state = 'proposed';
CREATE TABLE governance.ws_change_approvals (
  proposal_id    uuid NOT NULL,
  version        int  NOT NULL,
  approver       uuid NOT NULL,
  scope          text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  role           text NOT NULL,
  decision       text NOT NULL CHECK (decision IN ('approve', 'reject')),
  reason         text NOT NULL,
  signature_id   uuid,
  decided_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id uuid NOT NULL,
  PRIMARY KEY (proposal_id, version, approver),
  CONSTRAINT wca_signed CHECK (decision = 'reject' OR signature_id IS NOT NULL)
);
CREATE TRIGGER wca_append_only BEFORE UPDATE OR DELETE ON governance.ws_change_approvals FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

/* THE PLANS a change carries before approval (ES-72-003). */
CREATE OR REPLACE FUNCTION governance.ws_change_plans() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY['consumer_impact', 'compatibility', 'migration', 'replay', 'rollback', 'evidence'] $$;
GRANT EXECUTE ON FUNCTION governance.ws_change_plans() TO eye_app, eye_commit;

/* THE DETERMINISTIC IMPACT of changing the subjects: every artifact that depends on them through the LIVE links (a link from → to reads "from
   depends on to" for every relation but supersedes / owned_by / conflicts_with / governs — `governs` reads the other way: a governing artifact
   is not a dependent of what it governs), transitively to depth 6, each at its shortest depth, ordered
   (depth, kind, external key, id) and digested — the same links, the same impact digest. (An invoker read: PLATFORM rows are readable by
   every authenticated context.) §RG's impact explorer is the registry's own; this is the change proposal's binding of it. */
CREATE OR REPLACE FUNCTION governance.ws_impact(p_subjects uuid[]) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  WITH RECURSIVE walk(artifact_id, depth, via, relation) AS (
    SELECT s, 0, NULL::uuid, NULL::text FROM unnest(coalesce(p_subjects, '{}')) s
    UNION ALL
    SELECT l.from_artifact, w.depth + 1, w.artifact_id, l.relation FROM walk w JOIN governance.links_live l ON l.to_artifact = w.artifact_id
     WHERE w.depth < 6 AND l.relation NOT IN ('supersedes', 'owned_by', 'conflicts_with', 'governs')),
  best AS (SELECT DISTINCT ON (w.artifact_id) w.artifact_id, w.depth, w.via, w.relation FROM walk w WHERE w.depth > 0 AND NOT (w.artifact_id = ANY (coalesce(p_subjects, '{}')))
            ORDER BY w.artifact_id, w.depth, w.via, w.relation),
  deps AS (SELECT b.artifact_id, b.depth, b.via, b.relation, a.kind, a.external_key, a.title, a.version FROM best b
             LEFT JOIN governance.artifacts a ON a.artifact_id = b.artifact_id AND a.superseded_at IS NULL),
  listed AS (SELECT coalesce(jsonb_agg(jsonb_build_object('artifact_id', r.artifact_id, 'version', r.version, 'kind', coalesce(r.kind, 'unregistered'), 'key', r.external_key, 'title', r.title,
                                                          'depth', r.depth, 'via', r.via, 'relation', r.relation) ORDER BY r.depth, coalesce(r.kind, 'zzz'), r.external_key, r.artifact_id), '[]'::jsonb) AS l FROM deps r)
  SELECT jsonb_build_object('subjects', to_jsonb(ARRAY(SELECT DISTINCT s FROM unnest(coalesce(p_subjects, '{}')) s ORDER BY 1)), 'dependents', l.l,
                            'by_kind', coalesce((SELECT jsonb_object_agg(k, n) FROM (SELECT x ->> 'kind' AS k, count(*) AS n FROM jsonb_array_elements(l.l) x GROUP BY 1) q), '{}'::jsonb),
                            'count', jsonb_array_length(l.l),
                            'digest', governance.digest(jsonb_build_object('subjects', to_jsonb(ARRAY(SELECT DISTINCT s FROM unnest(coalesce(p_subjects, '{}')) s ORDER BY 1)), 'dependents', l.l)))
    FROM listed l $$;
GRANT EXECUTE ON FUNCTION governance.ws_impact(uuid[]) TO eye_app, eye_commit;

/* PROPOSE a change (any product-governance role; an AGENT may draft — it never approves): the class, the subject artifacts, the six plans (a
   proposal may be incomplete — what is missing is listed; it is NOT approvable until complete), the declared builders, identity / cross-volume /
   constitutional reach (cross-volume is also derived: the subjects span volumes), the impact computed and digested. */
CREATE OR REPLACE FUNCTION governance.ws_propose_change(p_proposal uuid, p_body jsonb, p_expected_version int, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE v_cur int; v_ref text; v_subjects uuid[]; v_plans jsonb := '{}'::jsonb; v_missing text[] := '{}'; k text; v_builders uuid[]; v_cross boolean; v_const boolean; v_ident boolean;
        v_roles text[]; v_impact jsonb; v_digest text; v_class text; v_s uuid;
BEGIN
  PERFORM governance.assert_platform('governance.change.propose', p_actor, 'change proposal');
  IF NOT governance.holds_role(p_actor, NULL, NULL, governance.ws_governance_roles()) THEN
    RAISE EXCEPTION 'change proposal rejected (authority): a change is proposed by a holder of a product-governance role' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_body) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'change proposal rejected (body): the proposal is an object' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.ws_change_proposals:' || p_proposal::text, 0));
  SELECT coalesce(max(c.version), 0), max(c.ref) INTO v_cur, v_ref FROM governance.ws_change_proposals c WHERE c.proposal_id = p_proposal;
  IF p_expected_version IS DISTINCT FROM v_cur THEN
    RAISE EXCEPTION 'change proposal rejected (stale): the proposal is at version % (expected %)', v_cur, coalesce(p_expected_version::text, '<none>') USING ERRCODE = '23505';
  END IF;
  IF v_cur > 0 AND EXISTS (SELECT 1 FROM governance.ws_change_proposals c WHERE c.proposal_id = p_proposal AND c.version = v_cur AND c.state IN ('approved', 'rejected', 'withdrawn')) THEN
    RAISE EXCEPTION 'change proposal rejected (state): the proposal is decided — a new change is a new proposal' USING ERRCODE = '23505';
  END IF;
  v_class := p_body ->> 'changeClass';
  IF NOT (coalesce(v_class, '') IN ('interface', 'object', 'policy', 'model', 'agent', 'workflow', 'deployment', 'requirement', 'capability', 'baseline', 'data_contract')) THEN
    RAISE EXCEPTION 'change proposal rejected (class): the change class is interface, object, policy, model, agent, workflow, deployment, requirement, capability, baseline or data_contract' USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_body ->> 'title', ''))) < 8 OR length(btrim(coalesce(p_body ->> 'description', ''))) < 20 THEN
    RAISE EXCEPTION 'change proposal rejected (description): a title (8+) and a description (20+ characters)' USING ERRCODE = '22023';
  END IF;
  v_subjects := ARRAY(SELECT DISTINCT x::uuid FROM jsonb_array_elements_text(coalesce(p_body -> 'subjects', '[]'::jsonb)) x ORDER BY 1);
  IF cardinality(v_subjects) = 0 THEN RAISE EXCEPTION 'change proposal rejected (subjects): the change names the artifacts it changes' USING ERRCODE = '22023'; END IF;
  PERFORM governance.ws_assert_artifacts('change proposal', v_subjects, NULL, 'subjects');
  FOREACH k IN ARRAY governance.ws_change_plans() LOOP
    IF length(btrim(coalesce(p_body -> 'plans' ->> k, ''))) >= 20 THEN v_plans := v_plans || jsonb_build_object(k, btrim(p_body -> 'plans' ->> k));
    ELSE v_missing := v_missing || k; END IF;
  END LOOP;
  v_builders := ARRAY(SELECT DISTINCT x::uuid FROM jsonb_array_elements_text(coalesce(p_body -> 'builders', '[]'::jsonb)) x ORDER BY 1);
  v_ident := coalesce((p_body ->> 'altersIdentity')::boolean, false);
  v_const := coalesce((p_body ->> 'constitutional')::boolean, false);
  v_cross := coalesce((p_body ->> 'crossVolume')::boolean, false)
             OR (SELECT count(DISTINCT a.controlling_volume) FROM governance.artifacts a WHERE a.artifact_id = ANY (v_subjects) AND a.superseded_at IS NULL AND a.controlling_volume IS NOT NULL) > 1;
  v_roles := CASE WHEN v_ident OR v_const OR v_cross THEN ARRAY['product_authority', 'independent_assurance'] ELSE ARRAY['product_authority'] END;
  v_impact := governance.ws_impact(v_subjects);
  v_ref := coalesce(v_ref, governance.ws_next_ref('GCP'));
  v_digest := governance.digest(jsonb_build_object('proposal_id', p_proposal, 'version', v_cur + 1, 'title', btrim(p_body ->> 'title'), 'class', v_class, 'subjects', to_jsonb(v_subjects),
               'description', btrim(p_body ->> 'description'), 'plans', v_plans, 'builders', to_jsonb(v_builders), 'alters_identity', v_ident, 'cross_volume', v_cross, 'constitutional', v_const,
               'required_roles', to_jsonb(v_roles), 'impact_digest', v_impact ->> 'digest'));
  UPDATE governance.ws_change_proposals SET state = 'superseded' WHERE proposal_id = p_proposal AND state = 'proposed';
  INSERT INTO governance.ws_change_proposals (proposal_id, version, ref, title, change_class, subjects, description, plans, missing_plans, builders, alters_identity, cross_volume, constitutional,
                                              required_roles, impact, impact_digest, digest, proposed_by, correlation_id)
  VALUES (p_proposal, v_cur + 1, v_ref, btrim(p_body ->> 'title'), v_class, v_subjects, btrim(p_body ->> 'description'), v_plans, v_missing, v_builders, v_ident, v_cross, v_const, v_roles,
          v_impact, v_impact ->> 'digest', v_digest, p_actor, p_correlation);
  PERFORM governance.ws_register(p_proposal, 'change_proposal', v_ref, btrim(p_body ->> 'title'), p_actor, NULL, NULL, NULL, 'proposed',
            jsonb_build_object('version', v_cur + 1, 'class', v_class, 'missing_plans', to_jsonb(v_missing), 'impact_count', v_impact -> 'count'), v_digest, p_actor, p_correlation);
  FOREACH v_s IN ARRAY v_subjects LOOP PERFORM governance.ws_link(p_proposal, v_s, 'governs', jsonb_build_object('as', 'changes'), p_actor, p_correlation); END LOOP;
  PERFORM governance.ledger(NULL, NULL, 'change_proposal', p_proposal, v_cur + 1, 'change.proposed', p_actor,
            jsonb_build_object('digest', v_digest, 'class', v_class, 'missing_plans', to_jsonb(v_missing), 'impact_digest', v_impact ->> 'digest', 'impact_count', v_impact -> 'count',
                               'required_roles', to_jsonb(v_roles)), p_correlation);
  RETURN jsonb_build_object('proposal_id', p_proposal, 'ref', v_ref, 'version', v_cur + 1, 'state', 'proposed', 'digest', v_digest, 'missing_plans', to_jsonb(v_missing),
                            'approvable', cardinality(v_missing) = 0, 'required_roles', to_jsonb(v_roles), 'cross_volume', v_cross, 'impact', v_impact);
END $$;
REVOKE ALL ON FUNCTION governance.ws_propose_change(uuid, jsonb, int, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_propose_change(uuid, jsonb, int, uuid, uuid) TO eye_commit;

/* DECIDE a change version (approve | reject): a named human holding a required role not yet given by another approver (the authority chain:
   product authority, plus independent assurance for constitutional / identity-altering / cross-volume change); never the proposer or a declared
   builder; the matrix's `change` approve row (the product authority's step) or review row (independent assurance's step) when it governs; on the exact digest; REFUSED while a plan is missing (ES-72-003), when the
   impact moved since the proposal (stale), or while a subject is under an open conflict or hold (held). APPROVE is SIGNED (`change_approval`);
   the change is approved when every required role has approved; one reject rejects. */
CREATE OR REPLACE FUNCTION governance.ws_decide_change(p_proposal uuid, p_version int, p_decision text, p_digest text, p_reason text, p_signature uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE c governance.ws_change_proposals%ROWTYPE; v_open text[]; v_role text; v_impact jsonb; v_done text[]; v_state text; v_blocking jsonb; v_via jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.change.decide', p_actor, 'change proposal');
  SELECT * INTO c FROM governance.ws_change_proposals x WHERE x.proposal_id = p_proposal AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'change proposal rejected (unknown_proposal): no change proposal %/v%', p_proposal, p_version USING ERRCODE = '23503'; END IF;
  SELECT array_agg(a.role) INTO v_done FROM governance.ws_change_approvals a WHERE a.proposal_id = p_proposal AND a.version = p_version AND a.decision = 'approve';
  v_open := ARRAY(SELECT r FROM unnest(c.required_roles) r WHERE NOT (r = ANY (coalesce(v_done, '{}'))));
  IF EXISTS (SELECT 1 FROM governance.ws_change_approvals a WHERE a.proposal_id = p_proposal AND a.version = p_version AND a.approver = p_actor) THEN
    RAISE EXCEPTION 'change proposal rejected (separation_of_duties): you have already decided version % — each required role is a distinct named approver', p_version USING ERRCODE = '42501';
  END IF;
  PERFORM governance.assert_approver('change proposal', p_actor, NULL, NULL, CASE WHEN cardinality(v_open) = 0 THEN c.required_roles ELSE v_open END, c.proposed_by, c.builders, 'approving a change');
  SELECT b.role_code INTO v_role FROM identity.role_bindings b WHERE b.principal_id = p_actor AND b.revoked_at IS NULL AND b.scope = 'PLATFORM'
     AND b.role_code = ANY (CASE WHEN cardinality(v_open) = 0 THEN c.required_roles ELSE v_open END) ORDER BY array_position(c.required_roles, b.role_code) LIMIT 1;
  -- the matrix: the product authority's step is the `change` APPROVE row (singular); independent assurance's step in the chain is its REVIEW row
  v_via := governance.ws_assert_rights('change proposal', 'change', CASE WHEN v_role = 'independent_assurance' THEN 'review' ELSE 'approve' END, p_actor);
  IF c.state <> 'proposed' THEN RAISE EXCEPTION 'change proposal rejected (state): version % is %', p_version, c.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM c.digest THEN RAISE EXCEPTION 'change proposal rejected (stale): the decision names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF p_decision NOT IN ('approve', 'reject') THEN RAISE EXCEPTION 'change proposal rejected (decision): approve or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'change proposal rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'approve' THEN
    IF cardinality(c.missing_plans) > 0 THEN
      RAISE EXCEPTION 'change proposal rejected (plans): % — a change carries its consumer impact, compatibility, migration, replay, rollback and evidence plans before approval (ES-72-003)', array_to_string(c.missing_plans, ', ') || ' missing' USING ERRCODE = '22023';
    END IF;
    v_impact := governance.ws_impact(c.subjects);
    IF v_impact ->> 'digest' IS DISTINCT FROM c.impact_digest THEN
      RAISE EXCEPTION 'change proposal rejected (stale): the impact moved since the proposal (% then, % now) — re-propose with the current impact', c.impact ->> 'count', v_impact ->> 'count' USING ERRCODE = '23505';
    END IF;
    SELECT jsonb_agg(jsonb_build_object('subject', h.subject_artifact, 'reason_kind', h.reason_kind, 'reason', h.reason)) INTO v_blocking FROM governance.holds h
     WHERE h.lifted_at IS NULL AND h.subject_artifact = ANY (c.subjects);
    IF v_blocking IS NULL THEN
      SELECT jsonb_agg(jsonb_build_object('conflict', k.ref, 'state', k.state)) INTO v_blocking FROM governance.ws_conflicts k WHERE k.state = 'open' AND k.conflicting && c.subjects;
    END IF;
    IF v_blocking IS NOT NULL THEN
      RAISE EXCEPTION 'change proposal rejected (held): a subject of the change is under an open conflict or hold — constrained until it is resolved (%)', v_blocking::text USING ERRCODE = '23505';
    END IF;
    IF NOT governance.ws_signed(p_signature, 'change_approval', p_proposal, p_version, c.digest, p_actor, 'governance.change.decide') THEN
      RAISE EXCEPTION 'change proposal rejected (signature): approval carries the approver''s signature over the proposal digest' USING ERRCODE = '22023';
    END IF;
  END IF;
  INSERT INTO governance.ws_change_approvals (proposal_id, version, approver, role, decision, reason, signature_id, correlation_id)
  VALUES (p_proposal, p_version, p_actor, coalesce(v_role, 'unknown'), p_decision, btrim(p_reason), CASE WHEN p_decision = 'approve' THEN p_signature END, p_correlation);
  v_done := CASE WHEN p_decision = 'approve' THEN array_append(coalesce(v_done, '{}'), v_role) ELSE v_done END;
  v_state := CASE WHEN p_decision = 'reject' THEN 'rejected'
                  WHEN NOT EXISTS (SELECT 1 FROM unnest(c.required_roles) r WHERE NOT (r = ANY (v_done))) THEN 'approved' ELSE 'proposed' END;
  IF v_state <> 'proposed' THEN
    UPDATE governance.ws_change_proposals SET state = v_state, decided_at = clock_timestamp(), decision_reason = btrim(p_reason) WHERE proposal_id = p_proposal AND version = p_version;
    PERFORM governance.ws_register(p_proposal, 'change_proposal', c.ref, c.title, c.proposed_by, NULL, NULL, NULL, CASE WHEN v_state = 'approved' THEN 'active' ELSE 'retired' END,
              jsonb_build_object('version', p_version, 'class', c.change_class, 'state', v_state), c.digest, p_actor, p_correlation);
  END IF;
  PERFORM governance.ledger(NULL, NULL, 'change_proposal', p_proposal, p_version, CASE p_decision WHEN 'reject' THEN 'change.rejected' ELSE (CASE WHEN v_state = 'approved' THEN 'change.approved' ELSE 'change.approval_recorded' END) END,
            p_actor, jsonb_build_object('digest', c.digest, 'role', v_role, 'reason', btrim(p_reason), 'signature_id', p_signature, 'awaiting', to_jsonb(ARRAY(SELECT r FROM unnest(c.required_roles) r WHERE NOT (r = ANY (coalesce(v_done, '{}'))))),
                                        'rights_via', v_via), p_correlation);
  RETURN jsonb_build_object('proposal_id', p_proposal, 'ref', c.ref, 'version', p_version, 'state', v_state, 'role', v_role, 'digest', c.digest,
                            'awaiting', to_jsonb(ARRAY(SELECT r FROM unnest(c.required_roles) r WHERE NOT (r = ANY (coalesce(v_done, '{}'))))));
END $$;
REVOKE ALL ON FUNCTION governance.ws_decide_change(uuid, int, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_decide_change(uuid, int, text, text, text, uuid, uuid, uuid) TO eye_commit;

-- §PG.4 THE CONFLICT REGISTER ─────────────────────────────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE governance.ws_conflicts (
  conflict_id       uuid PRIMARY KEY,
  scope             text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  ref               text NOT NULL,
  kind              text NOT NULL CHECK (kind IN ('cross_volume', 'requirement', 'authority_unresolved', 'dependency_unresolved', 'data_contract')),
  title             text NOT NULL CHECK (length(btrim(title)) BETWEEN 8 AND 300),
  description       text NOT NULL CHECK (length(btrim(description)) >= 20),
  conflicting       uuid[] NOT NULL,
  ranking           jsonb NOT NULL,
  highest_authority uuid NOT NULL,
  impacted          uuid[] NOT NULL,
  affected_releases uuid[] NOT NULL,
  last_conformant   uuid,
  holds             jsonb NOT NULL,
  digest            text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  state             text NOT NULL DEFAULT 'open' CHECK (state IN ('open', 'resolved')),
  raised_by         uuid NOT NULL,
  raised_at         timestamptz NOT NULL DEFAULT clock_timestamp(),
  resolved_by       uuid,
  resolved_at       timestamptz,
  resolution        jsonb,
  signature_id      uuid,
  claim             text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  correlation_id    uuid NOT NULL
);

/* RAISE a conflict (the conformance steward, the product authority or independent assurance — an agent may raise: holding is the conservative
   direction): two or more controlling artifacts (one for an unresolved authority / dependency), the impacted requirements and journeys, the
   highest authority SELECTED by the declared rank, every affected release candidate (named, or linked to a conflicting / impacted artifact)
   HELD (`conflict`), and the LAST CONFORMANT candidate recorded (the newest current candidate outside the conflict with no open hold). */
CREATE OR REPLACE FUNCTION governance.ws_raise_conflict(p_conflict uuid, p_body jsonb, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE v_kind text; v_conf uuid[]; v_imp uuid[]; v_rel uuid[]; v_rank jsonb; v_high uuid; v_last uuid; v_holds jsonb := '[]'::jsonb; v_ref text; v_digest text; a uuid;
BEGIN
  PERFORM governance.assert_platform('governance.conflict.raise', p_actor, 'conformance conflict');
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['conformance_steward', 'product_authority', 'independent_assurance']) THEN
    RAISE EXCEPTION 'conformance conflict rejected (authority): a conflict is raised by the conformance steward, the product authority or independent assurance' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM governance.ws_conflicts c WHERE c.conflict_id = p_conflict) THEN RAISE EXCEPTION 'conformance conflict rejected (duplicate): % is already raised', p_conflict USING ERRCODE = '23505'; END IF;
  v_kind := p_body ->> 'kind';
  IF NOT (coalesce(v_kind, '') IN ('cross_volume', 'requirement', 'authority_unresolved', 'dependency_unresolved', 'data_contract')) THEN
    RAISE EXCEPTION 'conformance conflict rejected (kind): cross_volume, requirement, authority_unresolved, dependency_unresolved or data_contract' USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_body ->> 'title', ''))) < 8 OR length(btrim(coalesce(p_body ->> 'description', ''))) < 20 THEN
    RAISE EXCEPTION 'conformance conflict rejected (description): a title (8+) and a description (20+ characters)' USING ERRCODE = '22023';
  END IF;
  v_conf := ARRAY(SELECT DISTINCT x::uuid FROM jsonb_array_elements_text(coalesce(p_body -> 'conflicting', '[]'::jsonb)) x ORDER BY 1);
  IF cardinality(v_conf) < (CASE WHEN v_kind IN ('authority_unresolved', 'dependency_unresolved') THEN 1 ELSE 2 END) THEN
    RAISE EXCEPTION 'conformance conflict rejected (conflicting): a conflict names two or more controlling artifacts (one for an unresolved authority or dependency)' USING ERRCODE = '22023';
  END IF;
  PERFORM governance.ws_assert_artifacts('conformance conflict', v_conf, NULL, 'conflicting');
  v_imp := ARRAY(SELECT DISTINCT x::uuid FROM jsonb_array_elements_text(coalesce(p_body -> 'impacted', '[]'::jsonb)) x ORDER BY 1);
  PERFORM governance.ws_assert_artifacts('conformance conflict', v_imp, ARRAY['requirement', 'journey', 'capability', 'component', 'interface', 'schema', 'data_product'], 'impacted');
  PERFORM governance.ws_assert_artifacts('conformance conflict',
            ARRAY(SELECT DISTINCT x::uuid FROM jsonb_array_elements_text(coalesce(p_body -> 'affectedReleases', '[]'::jsonb)) x), ARRAY['release_candidate'], 'affectedReleases');
  SELECT jsonb_agg(jsonb_build_object('artifact_id', a2.artifact_id, 'key', a2.external_key, 'kind', a2.kind, 'authority_class', a2.authority_class, 'controlling_volume', a2.controlling_volume,
                                      'rank', governance.ws_authority_rank(a2.authority_class), 'effective_from', a2.effective_from)
                   ORDER BY governance.ws_authority_rank(a2.authority_class), coalesce(a2.controlling_volume, 'V~'), a2.effective_from, a2.artifact_id)
    INTO v_rank FROM governance.artifacts a2 WHERE a2.artifact_id = ANY (v_conf) AND a2.superseded_at IS NULL;
  v_high := (v_rank -> 0 ->> 'artifact_id')::uuid;
  v_rel := ARRAY(SELECT DISTINCT r FROM (
             SELECT x::uuid AS r FROM jsonb_array_elements_text(coalesce(p_body -> 'affectedReleases', '[]'::jsonb)) x
             UNION SELECT CASE WHEN l.from_artifact = ANY (v_conf || v_imp) THEN l.to_artifact ELSE l.from_artifact END
               FROM governance.links_live l WHERE (l.from_artifact = ANY (v_conf || v_imp) OR l.to_artifact = ANY (v_conf || v_imp))) q
            WHERE EXISTS (SELECT 1 FROM governance.artifacts ra WHERE ra.artifact_id = q.r AND ra.kind = 'release_candidate' AND ra.superseded_at IS NULL) ORDER BY 1);
  SELECT ra.artifact_id INTO v_last FROM governance.artifacts ra WHERE ra.kind = 'release_candidate' AND ra.superseded_at IS NULL AND ra.lifecycle IN ('active', 'proposed')
     AND NOT (ra.artifact_id = ANY (v_rel)) AND NOT EXISTS (SELECT 1 FROM governance.holds h WHERE h.subject_artifact = ra.artifact_id AND h.lifted_at IS NULL)
   ORDER BY ra.effective_from DESC, ra.artifact_id LIMIT 1;
  v_ref := governance.ws_next_ref('GCF');
  FOREACH a IN ARRAY v_rel LOOP
    v_holds := v_holds || to_jsonb(governance.ws_open_hold(a, 'conflict', p_conflict,
                 format('conformance conflict %s (%s): the release is held at the last conformant candidate%s until the governing authority resolves it and the trace closes',
                        v_ref, v_kind, CASE WHEN v_last IS NULL THEN ' (none recorded)' ELSE ' ' || (SELECT external_key FROM governance.artifacts WHERE artifact_id = v_last AND superseded_at IS NULL) END),
                 p_actor, p_correlation));
  END LOOP;
  v_digest := governance.digest(jsonb_build_object('conflict_id', p_conflict, 'kind', v_kind, 'title', btrim(p_body ->> 'title'), 'description', btrim(p_body ->> 'description'),
               'conflicting', to_jsonb(v_conf), 'ranking', v_rank, 'highest_authority', v_high, 'impacted', to_jsonb(v_imp), 'affected_releases', to_jsonb(v_rel), 'last_conformant', v_last));
  INSERT INTO governance.ws_conflicts (conflict_id, ref, kind, title, description, conflicting, ranking, highest_authority, impacted, affected_releases, last_conformant, holds, digest, raised_by, correlation_id)
  VALUES (p_conflict, v_ref, v_kind, btrim(p_body ->> 'title'), btrim(p_body ->> 'description'), v_conf, v_rank, v_high, v_imp, v_rel, v_last, v_holds, v_digest, p_actor, p_correlation);
  PERFORM governance.ws_register(p_conflict, 'conflict', v_ref, btrim(p_body ->> 'title'), NULL, 'product_authority', NULL, NULL, 'active',
            jsonb_build_object('state', 'open', 'kind', v_kind, 'highest_authority', v_high, 'last_conformant', v_last), v_digest, p_actor, p_correlation);
  FOREACH a IN ARRAY v_conf LOOP PERFORM governance.ws_link(p_conflict, a, 'conflicts_with', jsonb_build_object('rank', (SELECT x -> 'rank' FROM jsonb_array_elements(v_rank) x WHERE (x ->> 'artifact_id')::uuid = a)), p_actor, p_correlation); END LOOP;
  FOREACH a IN ARRAY v_imp LOOP PERFORM governance.ws_link(p_conflict, a, 'covers', jsonb_build_object('as', 'impacted'), p_actor, p_correlation); END LOOP;
  PERFORM governance.ledger(NULL, NULL, 'conflict', p_conflict, 1, 'conflict.raised', p_actor,
            jsonb_build_object('digest', v_digest, 'kind', v_kind, 'highest_authority', v_high, 'affected_releases', to_jsonb(v_rel), 'last_conformant', v_last, 'holds', v_holds), p_correlation);
  RETURN jsonb_build_object('conflict_id', p_conflict, 'ref', v_ref, 'state', 'open', 'digest', v_digest, 'ranking', v_rank, 'highest_authority', v_high, 'affected_releases', to_jsonb(v_rel),
                            'last_conformant', v_last, 'holds', v_holds);
END $$;
REVOKE ALL ON FUNCTION governance.ws_raise_conflict(uuid, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_raise_conflict(uuid, jsonb, uuid, uuid) TO eye_commit;

/* RESOLVE a conflict (the product authority — the governing authority; never its raiser; the matrix's `conflict` approve row), on the
   conflict's digest, SIGNED (`conflict_resolution`): CLOSURE — the highest authority prevails; AMENDMENT — another artifact prevails only through
   an APPROVED change proposal whose subjects include the highest-authority artifact (explicit amendment). THE TRACE CLOSES: the prevailing
   artifact `governs` every impacted artifact, and `supersedes` each other conflicting one (in the conflict's meaning); the holds lifted. */
CREATE OR REPLACE FUNCTION governance.ws_resolve_conflict(p_conflict uuid, p_body jsonb, p_digest text, p_signature uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE c governance.ws_conflicts%ROWTYPE; v_mode text; v_prev uuid; v_cp uuid; v_links jsonb := '[]'::jsonb; v_lifted jsonb; a uuid; v_res jsonb; v_via jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.conflict.resolve', p_actor, 'conformance conflict');
  SELECT * INTO c FROM governance.ws_conflicts x WHERE x.conflict_id = p_conflict FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'conformance conflict rejected (unknown_conflict): no conflict %', p_conflict USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('conformance conflict', p_actor, NULL, NULL, ARRAY['product_authority'], c.raised_by, NULL, 'resolving a conformance conflict');
  v_via := governance.ws_assert_rights('conformance conflict', 'conflict', 'approve', p_actor);
  IF c.state <> 'open' THEN RAISE EXCEPTION 'conformance conflict rejected (state): % is %', c.ref, c.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM c.digest THEN RAISE EXCEPTION 'conformance conflict rejected (stale): the resolution names a digest other than the conflict''s' USING ERRCODE = '23505'; END IF;
  v_mode := p_body ->> 'mode';
  v_prev := CASE WHEN jsonb_typeof(p_body -> 'prevailing') = 'string' THEN (p_body ->> 'prevailing')::uuid END;
  IF length(btrim(coalesce(p_body ->> 'rationale', ''))) < 20 THEN RAISE EXCEPTION 'conformance conflict rejected (rationale): a resolution states its rationale (20+ characters)' USING ERRCODE = '22023'; END IF;
  IF v_prev IS NULL OR NOT (v_prev = ANY (c.conflicting)) THEN RAISE EXCEPTION 'conformance conflict rejected (prevailing): the prevailing artifact is one of the conflicting artifacts' USING ERRCODE = '22023'; END IF;
  IF v_mode = 'closure' THEN
    IF v_prev IS DISTINCT FROM c.highest_authority THEN
      RAISE EXCEPTION 'conformance conflict rejected (authority_chain): closure keeps the highest authority (%); another artifact prevails only by explicit amendment (an approved change proposal)',
        (SELECT external_key FROM governance.artifacts WHERE artifact_id = c.highest_authority AND superseded_at IS NULL) USING ERRCODE = '22023';
    END IF;
  ELSIF v_mode = 'amendment' THEN
    v_cp := CASE WHEN jsonb_typeof(p_body -> 'changeProposal') = 'string' THEN (p_body ->> 'changeProposal')::uuid END;
    IF v_cp IS NULL OR NOT EXISTS (SELECT 1 FROM governance.ws_change_proposals p WHERE p.proposal_id = v_cp AND p.state = 'approved' AND c.highest_authority = ANY (p.subjects)) THEN
      RAISE EXCEPTION 'conformance conflict rejected (amendment): an amendment names an APPROVED change proposal that changes the highest-authority artifact' USING ERRCODE = '22023';
    END IF;
  ELSE
    RAISE EXCEPTION 'conformance conflict rejected (mode): closure or amendment' USING ERRCODE = '22023';
  END IF;
  IF NOT governance.ws_signed(p_signature, 'conflict_resolution', p_conflict, 1, c.digest, p_actor, 'governance.conflict.resolve') THEN
    RAISE EXCEPTION 'conformance conflict rejected (signature): a resolution carries the governing authority''s signature over the conflict digest' USING ERRCODE = '22023';
  END IF;
  FOREACH a IN ARRAY c.impacted LOOP
    v_links := v_links || jsonb_build_object('from', v_prev, 'to', a, 'relation', 'governs', 'link_id', governance.ws_link(v_prev, a, 'governs', jsonb_build_object('conflict', c.ref), p_actor, p_correlation));
  END LOOP;
  FOREACH a IN ARRAY c.conflicting LOOP
    IF a <> v_prev THEN
      v_links := v_links || jsonb_build_object('from', v_prev, 'to', a, 'relation', 'supersedes', 'link_id', governance.ws_link(v_prev, a, 'supersedes', jsonb_build_object('conflict', c.ref, 'mode', v_mode), p_actor, p_correlation));
    END IF;
  END LOOP;
  v_lifted := governance.ws_lift_holds(p_conflict, 'conflict', format('resolved: %s by %s (%s) — the trace closed', c.ref, governance.ws_principal_name(p_actor), v_mode), p_actor);
  v_res := jsonb_build_object('mode', v_mode, 'prevailing', v_prev, 'change_proposal', v_cp, 'rationale', btrim(p_body ->> 'rationale'), 'trace', v_links, 'trace_closed', true, 'holds_lifted', v_lifted);
  UPDATE governance.ws_conflicts SET state = 'resolved', resolved_by = p_actor, resolved_at = clock_timestamp(), resolution = v_res, signature_id = p_signature WHERE conflict_id = p_conflict;
  PERFORM governance.ws_register(p_conflict, 'conflict', c.ref, c.title, p_actor, 'product_authority', NULL, NULL, 'retired',
            jsonb_build_object('state', 'resolved', 'kind', c.kind, 'mode', v_mode, 'prevailing', v_prev), c.digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'conflict', p_conflict, 1, 'conflict.resolved', p_actor, v_res || jsonb_build_object('signature_id', p_signature, 'rights_via', v_via), p_correlation);
  RETURN jsonb_build_object('conflict_id', p_conflict, 'ref', c.ref, 'state', 'resolved', 'resolution', v_res, 'signature_id', p_signature);
END $$;
REVOKE ALL ON FUNCTION governance.ws_resolve_conflict(uuid, jsonb, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_resolve_conflict(uuid, jsonb, text, uuid, uuid, uuid) TO eye_commit;

-- §PG.2 (cont.) THE BASELINE PROPOSAL AND DECISION ─────────────────────────────────────────────────────────────────────────────────────────
/* THE INVENTORY READ (the baseline's raw material and the workspace's): every current capability artifact with its accountable owner (and
   the owner's standing: active, or LAPSED when the owner is no longer an active human holding the role), grouped by domain boundary; the
   orphans (no owner), the duplicates (two capabilities of one normalised title in one boundary), the lapsed. */
CREATE OR REPLACE FUNCTION governance.ws_inventory() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  WITH caps AS (
    SELECT a.artifact_id, a.version, a.external_key, a.title, a.authority_class, a.controlling_volume, a.lifecycle, a.attributes ->> 'domain' AS declared_domain,
           o.owner_principal_id, o.owner_role, o.domain_boundary, o.version AS owner_version,
           CASE WHEN o.owner_principal_id IS NULL THEN 'orphan'
                WHEN NOT governance.ws_is_human(o.owner_principal_id) OR NOT governance.holds_role(o.owner_principal_id, NULL, NULL, ARRAY[o.owner_role]) THEN 'lapsed'
                ELSE 'owned' END AS standing
      FROM governance.artifacts a LEFT JOIN governance.ws_capability_owners o ON o.capability_id = a.artifact_id AND o.superseded_at IS NULL
     WHERE a.kind = 'capability' AND a.superseded_at IS NULL AND a.lifecycle IN ('proposed', 'active')),
  dup AS (SELECT lower(regexp_replace(btrim(c.title), '\s+', ' ', 'g')) AS t, coalesce(c.domain_boundary, c.declared_domain, '') AS d, array_agg(c.external_key ORDER BY c.external_key) AS keys
            FROM caps c GROUP BY 1, 2 HAVING count(*) > 1)
  SELECT jsonb_build_object(
    'capabilities', coalesce((SELECT jsonb_agg(jsonb_build_object('capability_id', c.artifact_id, 'version', c.version, 'key', c.external_key, 'title', c.title, 'authority_class', c.authority_class,
                                 'controlling_volume', c.controlling_volume, 'lifecycle', c.lifecycle, 'domain_boundary', coalesce(c.domain_boundary, c.declared_domain), 'owner', c.owner_principal_id,
                                 'owner_name', governance.ws_principal_name(c.owner_principal_id), 'owner_role', c.owner_role, 'owner_version', c.owner_version, 'standing', c.standing)
                               ORDER BY c.external_key) FROM caps c), '[]'::jsonb),
    'domains', coalesce((SELECT jsonb_agg(jsonb_build_object('domain_boundary', d.b, 'capabilities', d.n) ORDER BY d.b) FROM
                          (SELECT coalesce(c.domain_boundary, c.declared_domain, '(no boundary)') AS b, count(*) AS n FROM caps c GROUP BY 1) d), '[]'::jsonb),
    'orphans', coalesce((SELECT jsonb_agg(c.external_key ORDER BY c.external_key) FROM caps c WHERE c.standing = 'orphan'), '[]'::jsonb),
    'lapsed', coalesce((SELECT jsonb_agg(c.external_key ORDER BY c.external_key) FROM caps c WHERE c.standing = 'lapsed'), '[]'::jsonb),
    'duplicates', coalesce((SELECT jsonb_agg(jsonb_build_object('title', d.t, 'domain_boundary', d.d, 'keys', to_jsonb(d.keys)) ORDER BY d.t) FROM dup d), '[]'::jsonb),
    'count', (SELECT count(*) FROM caps)) $$;
REVOKE ALL ON FUNCTION governance.ws_inventory() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_inventory() TO eye_app, eye_commit;

/* THE CONFORMANCE TREND (the baseline binds it): holds and conflicts opened / lifted, exceptions expired, in the last 30 and 90 days. */
CREATE OR REPLACE FUNCTION governance.ws_trend() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT jsonb_object_agg(w.label, jsonb_build_object(
    'holds_opened', (SELECT count(*) FROM governance.holds h WHERE h.opened_at >= clock_timestamp() - w.span),
    'holds_lifted', (SELECT count(*) FROM governance.holds h WHERE h.lifted_at >= clock_timestamp() - w.span),
    'holds_open_now', (SELECT count(*) FROM governance.holds h WHERE h.lifted_at IS NULL),
    'conflicts_raised', (SELECT count(*) FROM governance.ws_conflicts c WHERE c.raised_at >= clock_timestamp() - w.span),
    'conflicts_resolved', (SELECT count(*) FROM governance.ws_conflicts c WHERE c.resolved_at >= clock_timestamp() - w.span),
    'exceptions_expired', (SELECT count(*) FROM governance.ws_exceptions e WHERE e.expired_at >= clock_timestamp() - w.span)))
    FROM (VALUES ('30d', interval '30 days'), ('90d', interval '90 days')) w(label, span) $$;
REVOKE ALL ON FUNCTION governance.ws_trend() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_trend() TO eye_app, eye_commit;

/* The baseline's SCOPE TUPLE (PR-01-006 / PR-72-006 / IA-72-006): exactly what the decision is bound to. */
CREATE OR REPLACE FUNCTION governance.ws_scope_keys() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'capability_version', 'journeys', 'roles', 'tenant_or_domain', 'deployment_profile', 'entitlement', 'data_versions', 'model_versions', 'configuration_digest', 'consequence_class', 'period'] $$;
GRANT EXECUTE ON FUNCTION governance.ws_scope_keys() TO eye_app, eye_commit;

/* PROPOSE a baseline version (the product authority or the conformance steward): assembled HERE from the registries — the inventory, the
   boundaries, the approved rights (or its absence), the exception ageing, the open conflicts and holds, the trend — with the scope tuple; the
   GAPS recorded (what would hold the signature). A proposal with gaps is allowed: the disputed state is preserved and shown. */
CREATE OR REPLACE FUNCTION governance.ws_propose_baseline(p_baseline uuid, p_title text, p_scope jsonb, p_expected_version int, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE v_cur int; v_ref text; v_inv jsonb; m governance.ws_decision_rights; v_rights jsonb := NULL; v_exc jsonb; v_conf jsonb; v_holds jsonb; v_trend jsonb; v_gaps jsonb := '[]'::jsonb;
        v_digest text; k text; v_missing text[];
BEGIN
  PERFORM governance.assert_platform('governance.baseline.propose', p_actor, 'product baseline');
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['product_authority', 'conformance_steward']) THEN
    RAISE EXCEPTION 'product baseline rejected (authority): a baseline is proposed by the product authority or the conformance steward' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(coalesce(p_title, ''))) < 8 THEN RAISE EXCEPTION 'product baseline rejected (title): a baseline has a title (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF jsonb_typeof(p_scope) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'product baseline rejected (scope): the scope tuple is an object' USING ERRCODE = '22023'; END IF;
  FOREACH k IN ARRAY governance.ws_scope_keys() LOOP
    IF NOT (p_scope ? k) OR p_scope -> k IS NULL OR p_scope -> k = 'null'::jsonb OR (jsonb_typeof(p_scope -> k) = 'string' AND length(btrim(p_scope ->> k)) = 0)
       OR (jsonb_typeof(p_scope -> k) = 'array' AND jsonb_array_length(p_scope -> k) = 0) THEN
      v_missing := array_append(v_missing, k);
    END IF;
  END LOOP;
  IF v_missing IS NOT NULL THEN
    RAISE EXCEPTION 'product baseline rejected (scope): the decision is bound to the exact %; missing: %', array_to_string(governance.ws_scope_keys(), ', '), array_to_string(v_missing, ', ') USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_scope ->> 'configuration_digest', '') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'product baseline rejected (scope): configuration_digest is 64 hex' USING ERRCODE = '22023'; END IF;
  IF NOT (coalesce(p_scope ->> 'consequence_class', '') ~ '^C[0-4]$') THEN RAISE EXCEPTION 'product baseline rejected (scope): consequence_class is C0–C4' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.ws_baselines:' || p_baseline::text, 0));
  SELECT coalesce(max(b.version), 0), max(b.ref) INTO v_cur, v_ref FROM governance.ws_baselines b WHERE b.baseline_id = p_baseline;
  IF p_expected_version IS DISTINCT FROM v_cur THEN
    RAISE EXCEPTION 'product baseline rejected (stale): the baseline is at version % (expected %)', v_cur, coalesce(p_expected_version::text, '<none>') USING ERRCODE = '23505';
  END IF;
  v_inv := governance.ws_inventory();
  m := governance.ws_rights_current();
  IF m.matrix_id IS NOT NULL THEN v_rights := jsonb_build_object('matrix_id', m.matrix_id, 'ref', m.ref, 'version', m.version, 'digest', m.digest, 'signature_id', m.signature_id); END IF;
  v_exc := governance.ws_exception_ageing();
  SELECT coalesce(jsonb_agg(jsonb_build_object('conflict_id', c.conflict_id, 'ref', c.ref, 'kind', c.kind, 'raised_at', c.raised_at) ORDER BY c.raised_at), '[]'::jsonb) INTO v_conf
    FROM governance.ws_conflicts c WHERE c.state = 'open';
  SELECT coalesce(jsonb_agg(jsonb_build_object('hold_id', h.hold_id, 'subject', h.subject_artifact, 'reason_kind', h.reason_kind, 'opened_at', h.opened_at) ORDER BY h.opened_at, h.hold_id), '[]'::jsonb) INTO v_holds
    FROM governance.holds h WHERE h.lifted_at IS NULL AND h.scope = 'PLATFORM';
  v_trend := governance.ws_trend();
  IF (v_inv ->> 'count')::int = 0 THEN v_gaps := v_gaps || jsonb_build_object('gap', 'no_capabilities', 'detail', 'no capability artifact is registered (§RG imports the V8 capability inventory)'); END IF;
  IF jsonb_array_length(v_inv -> 'orphans') > 0 THEN v_gaps := v_gaps || jsonb_build_object('gap', 'orphans', 'detail', v_inv -> 'orphans'); END IF;
  IF jsonb_array_length(v_inv -> 'lapsed') > 0 THEN v_gaps := v_gaps || jsonb_build_object('gap', 'lapsed_owners', 'detail', v_inv -> 'lapsed'); END IF;
  IF jsonb_array_length(v_inv -> 'duplicates') > 0 THEN v_gaps := v_gaps || jsonb_build_object('gap', 'duplicates', 'detail', v_inv -> 'duplicates'); END IF;
  IF v_rights IS NULL THEN v_gaps := v_gaps || jsonb_build_object('gap', 'no_decision_rights', 'detail', 'no approved, signed decision-rights matrix');
  ELSE
    SELECT array_agg(c) INTO v_missing FROM unnest(governance.ws_required_classes()) c
     WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(m.rows) r WHERE r ->> 'subject' = c AND r ->> 'duty' = 'approve');
    IF v_missing IS NOT NULL THEN v_gaps := v_gaps || jsonb_build_object('gap', 'rights_uncovered', 'detail', to_jsonb(v_missing)); END IF;
  END IF;
  IF jsonb_array_length(v_conf) > 0 THEN v_gaps := v_gaps || jsonb_build_object('gap', 'open_conflicts', 'detail', v_conf); END IF;
  v_ref := coalesce(v_ref, governance.ws_next_ref('PBL'));
  v_digest := governance.digest(jsonb_build_object('baseline_id', p_baseline, 'version', v_cur + 1, 'title', btrim(p_title), 'inventory', v_inv -> 'capabilities', 'domains', v_inv -> 'domains',
               'rights', v_rights, 'exceptions', v_exc - 'read_at', 'conflicts', v_conf, 'holds', v_holds, 'trend', v_trend, 'scope', p_scope, 'gaps', v_gaps));
  UPDATE governance.ws_baselines SET state = 'superseded' WHERE baseline_id = p_baseline AND state = 'proposed';
  INSERT INTO governance.ws_baselines (baseline_id, version, ref, title, inventory, domains, rights, exceptions, conflicts, holds, trend, scope_tuple, gaps, digest, proposed_by, correlation_id)
  VALUES (p_baseline, v_cur + 1, v_ref, btrim(p_title), v_inv, v_inv -> 'domains', v_rights, v_exc - 'read_at', v_conf, v_holds, v_trend, p_scope, v_gaps, v_digest, p_actor, p_correlation);
  IF v_cur = 0 THEN  -- a later version is registered when decided (the signed baseline's artifact stays current until then)
    PERFORM governance.ws_register(p_baseline, 'baseline', v_ref, btrim(p_title), p_actor, 'product_authority', 'controlling', 'V8', 'proposed',
              jsonb_build_object('object', 'product_baseline', 'version', v_cur + 1, 'capabilities', v_inv -> 'count', 'gaps', jsonb_array_length(v_gaps)), v_digest, p_actor, p_correlation);
  END IF;
  PERFORM governance.ledger(NULL, NULL, 'baseline', p_baseline, v_cur + 1, 'baseline.proposed', p_actor, jsonb_build_object('digest', v_digest, 'capabilities', v_inv -> 'count', 'gaps', v_gaps), p_correlation);
  RETURN jsonb_build_object('baseline_id', p_baseline, 'ref', v_ref, 'version', v_cur + 1, 'state', 'proposed', 'digest', v_digest, 'gaps', v_gaps, 'signable', jsonb_array_length(v_gaps) = 0,
                            'capabilities', v_inv -> 'count');
END $$;
REVOKE ALL ON FUNCTION governance.ws_propose_baseline(uuid, text, jsonb, int, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_propose_baseline(uuid, text, jsonb, int, uuid, uuid) TO eye_commit;

/* DECIDE (sign | reject) a baseline version — the product authority (never the proposer; the matrix's `baseline` approve row), on the exact
   digest; SIGN is refused HELD while the version records gaps or the registry moved since (an open conflict now, an owner lapsed now): the
   unresolved authority holds the release of the baseline (PR-01-005). SIGNED (`baseline_decision`): the executive baseline attestation —
   construction / demonstration only (`claim = demonstration`); the real executive attestation is H3. The previous signed baseline superseded;
   the capabilities linked `part_of` the baseline. */
CREATE OR REPLACE FUNCTION governance.ws_decide_baseline(p_baseline uuid, p_version int, p_decision text, p_digest text, p_reason text, p_signature uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE b governance.ws_baselines%ROWTYPE; v_now jsonb; v_held jsonb := '[]'::jsonb; x jsonb; v_via jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.baseline.decide', p_actor, 'product baseline');
  SELECT * INTO b FROM governance.ws_baselines y WHERE y.baseline_id = p_baseline AND y.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'product baseline rejected (unknown_baseline): no baseline %/v%', p_baseline, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('product baseline', p_actor, NULL, NULL, ARRAY['product_authority'], b.proposed_by, NULL, 'signing the product baseline');
  v_via := governance.ws_assert_rights('product baseline', 'baseline', 'approve', p_actor);
  IF b.state <> 'proposed' THEN RAISE EXCEPTION 'product baseline rejected (state): version % is %', p_version, b.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM b.digest THEN RAISE EXCEPTION 'product baseline rejected (stale): the decision names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF p_decision NOT IN ('sign', 'reject') THEN RAISE EXCEPTION 'product baseline rejected (decision): sign or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'product baseline rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'sign' THEN
    IF jsonb_array_length(b.gaps) > 0 THEN
      RAISE EXCEPTION 'product baseline rejected (held): authority is unresolved — % — the baseline is held, the disputed state preserved; resolve through the authority chain and propose again',
        (SELECT string_agg(g ->> 'gap', ', ') FROM jsonb_array_elements(b.gaps) g) USING ERRCODE = '23505';
    END IF;
    v_now := governance.ws_inventory();
    IF jsonb_array_length(v_now -> 'orphans') + jsonb_array_length(v_now -> 'lapsed') + jsonb_array_length(v_now -> 'duplicates') > 0
       OR EXISTS (SELECT 1 FROM governance.ws_conflicts c WHERE c.state = 'open')
       OR (governance.ws_rights_current()).digest IS DISTINCT FROM (b.rights ->> 'digest')
       OR (v_now -> 'capabilities') IS DISTINCT FROM (b.inventory -> 'capabilities') THEN
      RAISE EXCEPTION 'product baseline rejected (stale): the registry moved since version % was proposed (owners, rights, capabilities or conflicts) — propose again on the current state', p_version USING ERRCODE = '23505';
    END IF;
    IF NOT governance.ws_signed(p_signature, 'baseline_decision', p_baseline, p_version, b.digest, p_actor, 'governance.baseline.decide') THEN
      RAISE EXCEPTION 'product baseline rejected (signature): signing carries the product authority''s signature over the baseline digest' USING ERRCODE = '22023';
    END IF;
    UPDATE governance.ws_baselines SET state = 'superseded' WHERE state = 'signed';
  END IF;
  UPDATE governance.ws_baselines SET state = CASE WHEN p_decision = 'sign' THEN 'signed' ELSE 'rejected' END, decided_by = p_actor, decided_at = clock_timestamp(), decision_reason = btrim(p_reason),
         signature_id = CASE WHEN p_decision = 'sign' THEN p_signature END WHERE baseline_id = p_baseline AND version = p_version;
  PERFORM governance.ws_register(p_baseline, 'baseline', b.ref, b.title, p_actor, 'product_authority', 'controlling', 'V8', CASE WHEN p_decision = 'sign' THEN 'active' ELSE 'retired' END,
            jsonb_build_object('object', 'product_baseline', 'version', p_version, 'state', CASE WHEN p_decision = 'sign' THEN 'signed' ELSE 'rejected' END), b.digest, p_actor, p_correlation);
  IF p_decision = 'sign' THEN
    FOR x IN SELECT y FROM jsonb_array_elements(b.inventory -> 'capabilities') y LOOP
      PERFORM governance.ws_link((x ->> 'capability_id')::uuid, p_baseline, 'part_of', jsonb_build_object('baseline_version', p_version), p_actor, p_correlation);
    END LOOP;
  END IF;
  PERFORM governance.ledger(NULL, NULL, 'baseline', p_baseline, p_version, CASE WHEN p_decision = 'sign' THEN 'baseline.signed' ELSE 'baseline.rejected' END, p_actor,
            jsonb_build_object('digest', b.digest, 'reason', btrim(p_reason), 'signature_id', p_signature, 'rights_via', v_via, 'claim', 'demonstration',
                               'attestation', 'the signed baseline decision is the executive baseline attestation of this construction — the real attestation is H3'), p_correlation);
  RETURN jsonb_build_object('baseline_id', p_baseline, 'ref', b.ref, 'version', p_version, 'state', CASE WHEN p_decision = 'sign' THEN 'signed' ELSE 'rejected' END, 'digest', b.digest,
                            'signature_id', p_signature, 'claim', 'demonstration');
END $$;
REVOKE ALL ON FUNCTION governance.ws_decide_baseline(uuid, int, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_decide_baseline(uuid, int, text, text, text, uuid, uuid, uuid) TO eye_commit;

-- §PG.6 THE GOVERNANCE REGISTRY ────────────────────────────────────────────────────────────────────────────────────────────────────────────
CREATE TABLE governance.ws_records (
  record_id          uuid NOT NULL,
  version            int  NOT NULL CHECK (version >= 1),
  scope              text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  ref                text NOT NULL,
  kind               text NOT NULL CHECK (kind IN ('decision_record', 'standard', 'debt', 'deprecation')),
  title              text NOT NULL CHECK (length(btrim(title)) BETWEEN 8 AND 300),
  statement          text NOT NULL CHECK (length(btrim(statement)) >= 20),
  owner_principal_id uuid NOT NULL,
  approving_role     text NOT NULL,
  dependencies       uuid[] NOT NULL,
  review_cadence_days int NOT NULL CHECK (review_cadence_days BETWEEN 1 AND 730),
  supersedes_record  uuid,
  details            jsonb NOT NULL CHECK (jsonb_typeof(details) = 'object'),
  state              text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'active', 'rejected', 'superseded', 'closed', 'retired')),
  effective_from     timestamptz,
  next_review_due    date,
  last_reviewed_at   timestamptz,
  reviews            int NOT NULL DEFAULT 0,
  digest             text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  proposed_by        uuid NOT NULL,
  proposed_at        timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by         uuid,
  decided_at         timestamptz,
  decision_reason    text,
  closure            jsonb,
  closed_by          uuid,
  closed_at          timestamptz,
  claim              text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  correlation_id     uuid NOT NULL,
  PRIMARY KEY (record_id, version)
);
CREATE UNIQUE INDEX wrc_one_open ON governance.ws_records (record_id) WHERE state = 'proposed';
CREATE UNIQUE INDEX wrc_one_active ON governance.ws_records (record_id) WHERE state = 'active';

/* PROPOSE a record version (any product-governance role): a new record (expected 0) or a CONTROLLED AMENDMENT (expected = the current version;
   the active version stays in force until the amendment is approved). ES-72-001's fields; a debt (ES-72-005) carries its affected objectives,
   customers, consequences, due day and investment; a deprecation its subject artifact, sunset day and migration path. */
CREATE OR REPLACE FUNCTION governance.ws_propose_record(p_record uuid, p_body jsonb, p_expected_version int, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE v_cur int; v_ref text; v_kind text; v_prev governance.ws_records%ROWTYPE; v_owner uuid; v_role text; v_deps uuid[]; v_cad int; v_sup uuid; v_det jsonb := '{}'::jsonb; v_digest text;
BEGIN
  PERFORM governance.assert_platform('governance.record.propose', p_actor, 'governance record');
  IF NOT governance.holds_role(p_actor, NULL, NULL, governance.ws_governance_roles()) THEN
    RAISE EXCEPTION 'governance record rejected (authority): a record is proposed by a holder of a product-governance role' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_body) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'governance record rejected (body): the record is an object' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.ws_records:' || p_record::text, 0));
  SELECT coalesce(max(r.version), 0), max(r.ref) INTO v_cur, v_ref FROM governance.ws_records r WHERE r.record_id = p_record;
  IF p_expected_version IS DISTINCT FROM v_cur THEN
    RAISE EXCEPTION 'governance record rejected (stale): the record is at version % (expected %)', v_cur, coalesce(p_expected_version::text, '<none>') USING ERRCODE = '23505';
  END IF;
  IF v_cur > 0 THEN
    SELECT * INTO v_prev FROM governance.ws_records r WHERE r.record_id = p_record AND r.version = v_cur;
    IF v_prev.state IN ('closed', 'retired', 'rejected') AND NOT EXISTS (SELECT 1 FROM governance.ws_records r WHERE r.record_id = p_record AND r.state = 'active') THEN
      RAISE EXCEPTION 'governance record rejected (state): % is % — a new record is a new record', v_prev.ref, v_prev.state USING ERRCODE = '23505';
    END IF;
  END IF;
  v_kind := coalesce(p_body ->> 'kind', v_prev.kind);
  IF v_cur > 0 AND v_kind IS DISTINCT FROM v_prev.kind THEN RAISE EXCEPTION 'governance record rejected (kind): an amendment keeps its kind (%)', v_prev.kind USING ERRCODE = '22023'; END IF;
  IF NOT (coalesce(v_kind, '') IN ('decision_record', 'standard', 'debt', 'deprecation')) THEN RAISE EXCEPTION 'governance record rejected (kind): decision_record, standard, debt or deprecation' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_body ->> 'title', ''))) < 8 OR length(btrim(coalesce(p_body ->> 'statement', ''))) < 20 THEN
    RAISE EXCEPTION 'governance record rejected (statement): a title (8+) and a statement (20+ characters)' USING ERRCODE = '22023';
  END IF;
  v_owner := CASE WHEN jsonb_typeof(p_body -> 'owner') = 'string' THEN (p_body ->> 'owner')::uuid ELSE v_prev.owner_principal_id END;
  IF v_owner IS NULL OR NOT governance.ws_is_human(v_owner) THEN RAISE EXCEPTION 'governance record rejected (owner): the accountable owner is a named active human' USING ERRCODE = '22023'; END IF;
  v_role := coalesce(p_body ->> 'approvingRole', v_prev.approving_role);
  IF NOT (coalesce(v_role, '') = ANY (governance.ws_governance_roles())) OR v_role = 'conformance_steward' THEN
    RAISE EXCEPTION 'governance record rejected (approving_role): the approving authority is product_authority, design_system_authority, independent_assurance or operations_authority' USING ERRCODE = '22023';
  END IF;
  v_deps := CASE WHEN p_body ? 'dependencies' THEN ARRAY(SELECT DISTINCT x::uuid FROM jsonb_array_elements_text(p_body -> 'dependencies') x ORDER BY 1) ELSE coalesce(v_prev.dependencies, '{}') END;
  PERFORM governance.ws_assert_artifacts('governance record', v_deps, NULL, 'dependencies');
  v_cad := coalesce((p_body ->> 'reviewCadenceDays')::int, v_prev.review_cadence_days);
  IF v_cad IS NULL OR v_cad NOT BETWEEN 1 AND 730 THEN RAISE EXCEPTION 'governance record rejected (cadence): a review cadence of 1–730 days' USING ERRCODE = '22023'; END IF;
  v_sup := CASE WHEN jsonb_typeof(p_body -> 'supersedesRecord') = 'string' THEN (p_body ->> 'supersedesRecord')::uuid ELSE v_prev.supersedes_record END;
  IF v_sup IS NOT NULL AND NOT EXISTS (SELECT 1 FROM governance.ws_records r WHERE r.record_id = v_sup AND r.state = 'active' AND r.record_id <> p_record) THEN
    RAISE EXCEPTION 'governance record rejected (unknown_record): supersedesRecord names an active record of this registry' USING ERRCODE = '23503';
  END IF;
  IF v_kind = 'debt' THEN
    IF jsonb_typeof(p_body -> 'details' -> 'affectedObjectives') <> 'array' OR jsonb_array_length(p_body -> 'details' -> 'affectedObjectives') = 0
       OR jsonb_typeof(p_body -> 'details' -> 'customers') <> 'array' OR length(btrim(coalesce(p_body -> 'details' ->> 'consequences', ''))) < 12
       OR coalesce(p_body -> 'details' ->> 'dueOn', '') !~ '^\d{4}-\d{2}-\d{2}$' OR length(btrim(coalesce(p_body -> 'details' ->> 'investment', ''))) < 3 THEN
      RAISE EXCEPTION 'governance record rejected (debt): a debt names its affected objectives, customers (a list, possibly empty), consequences (12+), due day and investment — decision-active risk (ES-72-005)' USING ERRCODE = '22023';
    END IF;
    v_det := jsonb_build_object('affected_objectives', p_body -> 'details' -> 'affectedObjectives', 'customers', p_body -> 'details' -> 'customers', 'consequences', btrim(p_body -> 'details' ->> 'consequences'),
                                'due_on', p_body -> 'details' ->> 'dueOn', 'investment', btrim(p_body -> 'details' ->> 'investment'));
  ELSIF v_kind = 'deprecation' THEN
    IF jsonb_typeof(p_body -> 'details' -> 'subject') <> 'string' OR coalesce(p_body -> 'details' ->> 'sunsetOn', '') !~ '^\d{4}-\d{2}-\d{2}$' OR length(btrim(coalesce(p_body -> 'details' ->> 'migration', ''))) < 12 THEN
      RAISE EXCEPTION 'governance record rejected (deprecation): a deprecation names its subject artifact, sunset day and migration path (12+)' USING ERRCODE = '22023';
    END IF;
    PERFORM governance.ws_assert_artifacts('governance record', ARRAY[(p_body -> 'details' ->> 'subject')::uuid], NULL, 'details.subject');
    v_det := jsonb_build_object('subject', p_body -> 'details' ->> 'subject', 'sunset_on', p_body -> 'details' ->> 'sunsetOn', 'migration', btrim(p_body -> 'details' ->> 'migration'));
  ELSE
    v_det := CASE WHEN jsonb_typeof(p_body -> 'details') = 'object' THEN p_body -> 'details' ELSE '{}'::jsonb END;
  END IF;
  v_ref := coalesce(v_ref, governance.ws_next_ref(CASE v_kind WHEN 'decision_record' THEN 'GDR' WHEN 'standard' THEN 'GST' WHEN 'debt' THEN 'GTD' ELSE 'GDP' END));
  v_digest := governance.digest(jsonb_build_object('record_id', p_record, 'version', v_cur + 1, 'kind', v_kind, 'title', btrim(p_body ->> 'title'), 'statement', btrim(p_body ->> 'statement'),
               'owner', v_owner, 'approving_role', v_role, 'dependencies', to_jsonb(v_deps), 'review_cadence_days', v_cad, 'supersedes_record', v_sup, 'details', v_det));
  UPDATE governance.ws_records SET state = 'superseded' WHERE record_id = p_record AND state = 'proposed';
  INSERT INTO governance.ws_records (record_id, version, ref, kind, title, statement, owner_principal_id, approving_role, dependencies, review_cadence_days, supersedes_record, details, digest, proposed_by, correlation_id)
  VALUES (p_record, v_cur + 1, v_ref, v_kind, btrim(p_body ->> 'title'), btrim(p_body ->> 'statement'), v_owner, v_role, v_deps, v_cad, v_sup, v_det, v_digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'governance_record', p_record, v_cur + 1, CASE WHEN v_cur = 0 THEN 'record.proposed' ELSE 'record.amendment_proposed' END, p_actor,
            jsonb_build_object('digest', v_digest, 'kind', v_kind, 'approving_role', v_role), p_correlation);
  RETURN jsonb_build_object('record_id', p_record, 'ref', v_ref, 'version', v_cur + 1, 'kind', v_kind, 'state', 'proposed', 'digest', v_digest, 'approving_role', v_role);
END $$;
REVOKE ALL ON FUNCTION governance.ws_propose_record(uuid, jsonb, int, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_propose_record(uuid, jsonb, int, uuid, uuid) TO eye_commit;

/* DECIDE (approve | reject) a record version: a named human holding the record's approving role (never the proposer, never its owner — the
   owner is accountable, the authority approves); on the exact digest. APPROVE: the version becomes ACTIVE (effective now, next review due
   after the cadence), the prior active version superseded (controlled amendment), a superseded record retired with the supersession linked. */
CREATE OR REPLACE FUNCTION governance.ws_decide_record(p_record uuid, p_version int, p_decision text, p_digest text, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE r governance.ws_records%ROWTYPE; v_kind text; d uuid; v_via jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.record.decide', p_actor, 'governance record');
  SELECT * INTO r FROM governance.ws_records x WHERE x.record_id = p_record AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'governance record rejected (unknown_record): no record %/v%', p_record, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('governance record', p_actor, NULL, NULL, ARRAY[r.approving_role], r.proposed_by, ARRAY[r.owner_principal_id], 'approving a governance record');
  v_via := governance.ws_assert_rights('governance record', 'record', 'approve', p_actor);
  IF r.state <> 'proposed' THEN RAISE EXCEPTION 'governance record rejected (state): version % is %', p_version, r.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM r.digest THEN RAISE EXCEPTION 'governance record rejected (stale): the decision names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF p_decision NOT IN ('approve', 'reject') THEN RAISE EXCEPTION 'governance record rejected (decision): approve or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'governance record rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  v_kind := CASE r.kind WHEN 'standard' THEN 'standard' ELSE 'decision_record' END;
  IF p_decision = 'approve' THEN
    UPDATE governance.ws_records SET state = 'superseded' WHERE record_id = p_record AND state = 'active';
    UPDATE governance.ws_records SET state = 'active', effective_from = clock_timestamp(), next_review_due = (clock_timestamp() AT TIME ZONE 'UTC')::date + r.review_cadence_days,
           decided_by = p_actor, decided_at = clock_timestamp(), decision_reason = btrim(p_reason) WHERE record_id = p_record AND version = p_version;
    PERFORM governance.ws_register(p_record, v_kind, r.ref, r.title, r.owner_principal_id, r.approving_role, 'normative', NULL, 'active',
              jsonb_build_object('record_kind', r.kind, 'version', p_version, 'review_cadence_days', r.review_cadence_days, 'details', r.details), r.digest, p_actor, p_correlation);
    FOREACH d IN ARRAY r.dependencies LOOP PERFORM governance.ws_link(p_record, d, 'depends_on', '{}'::jsonb, p_actor, p_correlation); END LOOP;
    IF r.supersedes_record IS NOT NULL THEN
      UPDATE governance.ws_records SET state = 'retired', closure = jsonb_build_object('mode', 'superseded', 'by', p_record, 'by_ref', r.ref), closed_by = p_actor, closed_at = clock_timestamp()
       WHERE record_id = r.supersedes_record AND state = 'active';
      PERFORM governance.ws_link(p_record, r.supersedes_record, 'supersedes', '{}'::jsonb, p_actor, p_correlation);
    END IF;
    IF r.kind = 'deprecation' THEN PERFORM governance.ws_link(p_record, (r.details ->> 'subject')::uuid, 'governs', jsonb_build_object('as', 'deprecation'), p_actor, p_correlation); END IF;
  ELSE
    UPDATE governance.ws_records SET state = 'rejected', decided_by = p_actor, decided_at = clock_timestamp(), decision_reason = btrim(p_reason) WHERE record_id = p_record AND version = p_version;
  END IF;
  PERFORM governance.ledger(NULL, NULL, 'governance_record', p_record, p_version, CASE WHEN p_decision = 'approve' THEN 'record.approved' ELSE 'record.rejected' END, p_actor,
            jsonb_build_object('digest', r.digest, 'reason', btrim(p_reason), 'rights_via', v_via), p_correlation);
  RETURN jsonb_build_object('record_id', p_record, 'ref', r.ref, 'version', p_version, 'state', CASE WHEN p_decision = 'approve' THEN 'active' ELSE 'rejected' END, 'digest', r.digest,
                            'next_review_due', CASE WHEN p_decision = 'approve' THEN ((clock_timestamp() AT TIME ZONE 'UTC')::date + r.review_cadence_days) END);
END $$;
REVOKE ALL ON FUNCTION governance.ws_decide_record(uuid, int, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_decide_record(uuid, int, text, text, text, uuid, uuid) TO eye_commit;

/* RECORD A REVIEW of an active record (its owner or a holder of its approving role — a named human): the cadence honoured, the next review due. */
CREATE OR REPLACE FUNCTION governance.ws_review_record(p_record uuid, p_version int, p_note text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE r governance.ws_records%ROWTYPE; v_next date;
BEGIN
  PERFORM governance.assert_platform('governance.record.review', p_actor, 'governance record');
  SELECT * INTO r FROM governance.ws_records x WHERE x.record_id = p_record AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'governance record rejected (unknown_record): no record %/v%', p_record, p_version USING ERRCODE = '23503'; END IF;
  IF NOT governance.ws_is_human(p_actor) THEN RAISE EXCEPTION 'governance record rejected (actor): a review is a named human''s act' USING ERRCODE = '42501'; END IF;
  IF p_actor <> r.owner_principal_id AND NOT governance.holds_role(p_actor, NULL, NULL, ARRAY[r.approving_role]) THEN
    RAISE EXCEPTION 'governance record rejected (authority): a review is the owner''s or the approving authority''s (%)', r.approving_role USING ERRCODE = '42501';
  END IF;
  IF r.state <> 'active' THEN RAISE EXCEPTION 'governance record rejected (state): only an active record is reviewed (version % is %)', p_version, r.state USING ERRCODE = '23505'; END IF;
  IF length(btrim(coalesce(p_note, ''))) < 12 THEN RAISE EXCEPTION 'governance record rejected (note): a review states what was found (12+ characters)' USING ERRCODE = '22023'; END IF;
  v_next := (clock_timestamp() AT TIME ZONE 'UTC')::date + r.review_cadence_days;
  UPDATE governance.ws_records SET last_reviewed_at = clock_timestamp(), next_review_due = v_next, reviews = reviews + 1 WHERE record_id = p_record AND version = p_version;
  PERFORM governance.ledger(NULL, NULL, 'governance_record', p_record, p_version, 'record.reviewed', p_actor,
            jsonb_build_object('note', btrim(p_note), 'next_review_due', v_next, 'was_due', r.next_review_due, 'overdue', r.next_review_due < (clock_timestamp() AT TIME ZONE 'UTC')::date), p_correlation);
  RETURN jsonb_build_object('record_id', p_record, 'ref', r.ref, 'version', p_version, 'next_review_due', v_next, 'reviews', r.reviews + 1);
END $$;
REVOKE ALL ON FUNCTION governance.ws_review_record(uuid, int, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_review_record(uuid, int, text, uuid, uuid) TO eye_commit;

/* CLOSE an active record: a debt by VERIFIED CLOSURE (`verified_closure` — current evidence, verified by a holder of the approving role who is
   neither the owner nor the proposer); any record by RETIREMENT PROOF (`retirement` — current evidence and, optionally, its successor
   artifact). The artifact retired; the evidence kept with the record. */
CREATE OR REPLACE FUNCTION governance.ws_close_record(p_record uuid, p_version int, p_mode text, p_evidence jsonb, p_successor uuid, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE r governance.ws_records%ROWTYPE; v_ev jsonb; v_closure jsonb;
BEGIN
  PERFORM governance.assert_platform('governance.record.close', p_actor, 'governance record');
  SELECT * INTO r FROM governance.ws_records x WHERE x.record_id = p_record AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'governance record rejected (unknown_record): no record %/v%', p_record, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('governance record', p_actor, NULL, NULL, ARRAY[r.approving_role], r.proposed_by, ARRAY[r.owner_principal_id],
            CASE WHEN p_mode = 'verified_closure' THEN 'verifying a debt''s closure' ELSE 'retiring a governance record' END);
  IF r.state <> 'active' THEN RAISE EXCEPTION 'governance record rejected (state): only an active record is closed (version % is %)', p_version, r.state USING ERRCODE = '23505'; END IF;
  IF p_mode NOT IN ('verified_closure', 'retirement') THEN RAISE EXCEPTION 'governance record rejected (mode): verified_closure or retirement' USING ERRCODE = '22023'; END IF;
  IF p_mode = 'verified_closure' AND r.kind <> 'debt' THEN RAISE EXCEPTION 'governance record rejected (mode): a verified closure closes a debt; other records are retired with proof' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 12 THEN RAISE EXCEPTION 'governance record rejected (reason): a closure states what was verified (12+ characters)' USING ERRCODE = '22023'; END IF;
  v_ev := governance.ws_evidence('governance record', p_evidence, true, governance.ws_evidence_currency_days(), NULL);
  IF p_successor IS NOT NULL THEN PERFORM governance.ws_assert_artifacts('governance record', ARRAY[p_successor], NULL, 'successor'); END IF;
  v_closure := jsonb_build_object('mode', p_mode, 'evidence', v_ev, 'successor', p_successor, 'reason', btrim(p_reason), 'verified_by', p_actor);
  UPDATE governance.ws_records SET state = CASE WHEN p_mode = 'verified_closure' THEN 'closed' ELSE 'retired' END, closure = v_closure, closed_by = p_actor, closed_at = clock_timestamp()
   WHERE record_id = p_record AND version = p_version;
  PERFORM governance.ws_register(p_record, CASE r.kind WHEN 'standard' THEN 'standard' ELSE 'decision_record' END, r.ref, r.title, r.owner_principal_id, r.approving_role, 'normative', NULL, 'retired',
            jsonb_build_object('record_kind', r.kind, 'version', p_version, 'closure', p_mode), r.digest, p_actor, p_correlation);
  IF p_successor IS NOT NULL THEN PERFORM governance.ws_link(p_successor, p_record, 'supersedes', jsonb_build_object('as', 'retirement successor'), p_actor, p_correlation); END IF;
  PERFORM governance.ledger(NULL, NULL, 'governance_record', p_record, p_version, CASE WHEN p_mode = 'verified_closure' THEN 'record.closure_verified' ELSE 'record.retired' END, p_actor, v_closure, p_correlation);
  RETURN jsonb_build_object('record_id', p_record, 'ref', r.ref, 'version', p_version, 'state', CASE WHEN p_mode = 'verified_closure' THEN 'closed' ELSE 'retired' END, 'closure', v_closure);
END $$;
REVOKE ALL ON FUNCTION governance.ws_close_record(uuid, int, text, jsonb, uuid, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_close_record(uuid, int, text, jsonb, uuid, text, uuid, uuid) TO eye_commit;

/* THE POSTURE (IA-72-002 / DP-72-002: declared vs observed): every dimension `conformant` | `non_conformant` | `unknown` — UNKNOWN where nothing
   is declared (never inferred healthy) — with what makes it so. */
CREATE OR REPLACE FUNCTION governance.ws_posture() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v_inv jsonb := governance.ws_inventory(); v_age jsonb := governance.ws_exception_ageing(); m governance.ws_decision_rights := governance.ws_rights_current();
        v_dims jsonb := '{}'::jsonb; n_over int; n_debt int; n_rec int; n_conf int; n_holds int; v_signed boolean; v_today date := (clock_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
  v_signed := EXISTS (SELECT 1 FROM governance.ws_baselines b WHERE b.state = 'signed');
  v_dims := v_dims || jsonb_build_object('baseline', jsonb_build_object('state', CASE WHEN v_signed THEN 'conformant' WHEN EXISTS (SELECT 1 FROM governance.ws_baselines) THEN 'non_conformant' ELSE 'unknown' END,
              'detail', CASE WHEN v_signed THEN (SELECT jsonb_build_object('ref', b.ref, 'version', b.version, 'signed_at', b.decided_at) FROM governance.ws_baselines b WHERE b.state = 'signed')
                             ELSE to_jsonb('no signed product baseline'::text) END));
  v_dims := v_dims || jsonb_build_object('ownership', jsonb_build_object('state', CASE WHEN (v_inv ->> 'count')::int = 0 THEN 'unknown'
                 WHEN jsonb_array_length(v_inv -> 'orphans') + jsonb_array_length(v_inv -> 'lapsed') + jsonb_array_length(v_inv -> 'duplicates') > 0 THEN 'non_conformant' ELSE 'conformant' END,
              'capabilities', v_inv -> 'count', 'orphans', v_inv -> 'orphans', 'lapsed', v_inv -> 'lapsed', 'duplicates', v_inv -> 'duplicates'));
  v_dims := v_dims || jsonb_build_object('decision_rights', jsonb_build_object('state', CASE WHEN m.matrix_id IS NULL THEN 'unknown' ELSE 'conformant' END,
              'detail', CASE WHEN m.matrix_id IS NULL THEN to_jsonb('no approved decision-rights matrix'::text) ELSE jsonb_build_object('ref', m.ref, 'version', m.version) END));
  v_dims := v_dims || jsonb_build_object('exceptions', jsonb_build_object('state', CASE WHEN NOT EXISTS (SELECT 1 FROM governance.ws_exceptions) THEN 'unknown'
                 WHEN (v_age -> 'totals' ->> 'expired')::int > 0 THEN 'non_conformant' ELSE 'conformant' END, 'totals', v_age -> 'totals', 'buckets', v_age -> 'buckets',
              'open_reviews', (SELECT count(*) FROM governance.ws_exception_reviews r WHERE r.state = 'open')));
  SELECT count(*) INTO n_conf FROM governance.ws_conflicts c WHERE c.state = 'open';
  v_dims := v_dims || jsonb_build_object('conflicts', jsonb_build_object('state', CASE WHEN n_conf > 0 THEN 'non_conformant' WHEN EXISTS (SELECT 1 FROM governance.ws_conflicts) THEN 'conformant' ELSE 'unknown' END, 'open', n_conf));
  SELECT count(*) INTO n_rec FROM governance.ws_records r WHERE r.state = 'active';
  SELECT count(*) INTO n_over FROM governance.ws_records r WHERE r.state = 'active' AND r.next_review_due < v_today;
  SELECT count(*) INTO n_debt FROM governance.ws_records r WHERE r.state = 'active' AND r.kind = 'debt' AND (r.details ->> 'due_on')::date < v_today;
  v_dims := v_dims || jsonb_build_object('records', jsonb_build_object('state', CASE WHEN n_rec = 0 THEN 'unknown' WHEN n_over + n_debt > 0 THEN 'non_conformant' ELSE 'conformant' END,
              'active', n_rec, 'reviews_overdue', n_over, 'debt_past_due', n_debt));
  SELECT count(*) INTO n_holds FROM governance.holds h WHERE h.lifted_at IS NULL AND h.scope = 'PLATFORM';
  v_dims := v_dims || jsonb_build_object('holds', jsonb_build_object('state', CASE WHEN n_holds > 0 THEN 'non_conformant' WHEN EXISTS (SELECT 1 FROM governance.holds h WHERE h.scope = 'PLATFORM') THEN 'conformant' ELSE 'unknown' END,
              'open', n_holds));
  RETURN jsonb_build_object('dimensions', v_dims,
    'summary', (SELECT jsonb_object_agg(s, n) FROM (SELECT d.value ->> 'state' AS s, count(*) AS n FROM jsonb_each(v_dims) d GROUP BY 1) q),
    'rule', 'a dimension is conformant only on a declaration and an observation that agree; unknown where nothing is declared — never inferred healthy, complete, current, authorized or recovered',
    'read_at', clock_timestamp());
END $$;
REVOKE ALL ON FUNCTION governance.ws_posture() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_posture() TO eye_app, eye_commit;

/* THE POSTURE SNAPSHOTS (append-only): the observed state VERSIONED — recorded by the conformance steward only when it changed. */
CREATE TABLE governance.ws_posture_snapshots (
  snapshot_id    uuid PRIMARY KEY,
  scope          text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  seq            int  NOT NULL UNIQUE,
  posture        jsonb NOT NULL,
  digest         text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  recorded_by    uuid NOT NULL,
  recorded_at    timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id uuid NOT NULL
);
CREATE TRIGGER wps_append_only BEFORE UPDATE OR DELETE ON governance.ws_posture_snapshots FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

CREATE OR REPLACE FUNCTION governance.ws_record_posture(p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE v jsonb; v_digest text; v_last text; v_seq int; v_id uuid := gen_random_uuid();
BEGIN
  PERFORM governance.assert_platform('governance.posture.record', p_actor, 'governance record');
  IF NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['conformance_steward']) THEN
    RAISE EXCEPTION 'governance record rejected (authority): the posture is recorded by the conformance steward' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('governance.ws_posture_snapshots', 0));
  v := governance.ws_posture() - 'read_at';
  v_digest := governance.digest(v);
  SELECT s.digest, s.seq INTO v_last, v_seq FROM governance.ws_posture_snapshots s ORDER BY s.seq DESC LIMIT 1;
  IF v_last = v_digest THEN RETURN jsonb_build_object('recorded', false, 'seq', v_seq, 'digest', v_digest, 'reason', 'the observed posture is unchanged since the last snapshot'); END IF;
  INSERT INTO governance.ws_posture_snapshots (snapshot_id, seq, posture, digest, recorded_by, correlation_id) VALUES (v_id, coalesce(v_seq, 0) + 1, v, v_digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'posture', v_id, coalesce(v_seq, 0) + 1, 'posture.recorded', p_actor, jsonb_build_object('digest', v_digest, 'summary', v -> 'summary'), p_correlation);
  RETURN jsonb_build_object('recorded', true, 'snapshot_id', v_id, 'seq', coalesce(v_seq, 0) + 1, 'digest', v_digest, 'posture', v);
END $$;
REVOKE ALL ON FUNCTION governance.ws_record_posture(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ws_record_posture(uuid, uuid) TO eye_commit;

-- §PG.7 RLS AND GRANTS (the prelude's idiom: PLATFORM rows readable by every authenticated context; SELECT only; the definer ports write) ──
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['governance.ws_capability_owners', 'governance.ws_decision_rights', 'governance.ws_baselines', 'governance.ws_exceptions', 'governance.ws_exception_reviews',
                           'governance.ws_change_proposals', 'governance.ws_change_approvals', 'governance.ws_conflicts', 'governance.ws_records', 'governance.ws_posture_snapshots'] LOOP
    EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', t);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($f$CREATE POLICY governance_visibility ON %s USING ((scope = 'PLATFORM' AND public.eye_scope() <> 'NONE') OR public.eye_scope() = 'PLATFORM')$f$, t);
    EXECUTE format('GRANT SELECT ON %s TO eye_app, eye_commit', t);
  END LOOP;
END $$;


-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §AR — scope-specific acceptance records, attestations per obligation, evidence expiry and expansion holds, operational and release acceptance (F-R0-04, F-P7D-25)
-- (folded at integration from the part-local file 0115_b107_x_ar.sql, unchanged but for the marked `B107 integration` edits; apply order §0, §RG, §CM, §DR, §PG, §AR, §DG)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 0115 §AR — CP-6 B107: SCOPE-SPECIFIC ACCEPTANCE RECORDS (F-R0-04; F-P7D-25 operational acceptance; F-P7-E-17 PAT-48 / OBJ-40 / JRN-24;
-- F-P7-F-12 OBJ-40). Applies alone on top of 0001–0114 and the prelude (0115 §0). Nothing of 0001–0114 or §0 is edited.
--
--   THE RECORD (governance.acceptance_records — DOMAIN, versioned): kind capability | operational | release | design; the exact SCOPE TUPLE
--     (capability + version, journeys, roles, tenant, domain, deployment profile, entitlement, data and model versions, configuration digest,
--     consequence class, period; for an operational record also artifacts, integrations, data classes, workloads, products, infrastructure;
--     for a release record the release candidate's identity) — a blanket value ('*', 'all', 'any', an empty list) is refused (PAT-48);
--     EVIDENCE ITEMS referenced by id + digest + captured_at + valid_until (the evidence VAULT, governance.acceptance_evidence — append-only;
--     B94's records and the shared artifacts are REFERENCED and verified, never rewritten); CONDITIONS (time-bounded; an absent evidence SLOT
--     becomes an open condition — ES-71-003, TS-020, PR-71-006); linked EXCEPTIONS (artifacts of kind exception, §PG's registry — an
--     expired one refuses); REQUIRED OBLIGATIONS (product, independent assurance, operations, security, privacy, AI fitness, data, business,
--     customer, design) each attested by a DISTINCT named human through governance.assert_approver and SIGNED (executive.signatures kind
--     acceptance_attestation): `accepted` only when every obligation is signed (ES-71-002: one person per obligation, never one role for all);
--     the customer VERIFIES before it attests (JRN-24); `claim` CHECK = 'demonstration'.
--   EVIDENCE EXPIRY (FEX-31, ES-71-004/-005, IA-71-005, DP-71-005, PR-71-005): the sweep (the attention tick's step and the
--     acceptance.evidence_expiry timer) reconciles every record in force against what it declared — an expired or failed evidence item, an
--     overdue condition, a passed review date, a changed capability, an expired linked exception, a held release candidate, the end of the
--     period — and turns it CONSTRAINED (the capability limited to the previously accepted UNAFFECTED scope), LAPSED (period over) or keeps
--     it; attention `governance.acceptance` is raised and an `acceptance_constrained` HOLD stops EXPANSION (a new domain, journeys, roles,
--     profile, data, models or a higher consequence class); only a RE-ACCEPTANCE (a new version over renewed evidence, every obligation
--     attested again) lifts it. Triggers by act (material change, incident, control failure, model or agent withdrawal, SLO exhaustion) put
--     the record under review (constrained) or suspend it.
--   THE OPT-IN REQUEST GATE (Q5): a capability marked `enforce_acceptance` (governance.acceptance_enforcement, PLATFORM, the product
--     authority) gates its action prefixes in a domain where it is not accepted for the requesting role or consequence class — never reads,
--     corrections, withdrawals, attention, warnings, mandatory controls or human gates (the entitlement gate's exemptions, plus governance.*).
--
-- THREE CLAIMS, never mixed: CONSTRUCTION (these ports + phase6-acceptance-b107); DEMONSTRATED OPERATION (the act on SYNTHETIC NORDWERK
-- personas — every record claim = 'demonstration'); REAL ACCEPTANCE by named independent and customer authorities, production admission
-- (R1/R2/H2/H3) — never claimed and impossible to record here (the CHECK admits only 'demonstration'). B64 (SLO computation) is not built:
-- SLO exhaustion is a declared trigger kind, never computed here.
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- §AR.0 THE TIMER OWNER — B107 ar: an acceptance.evidence_expiry timer is owned by its acceptance record (0114 §SV.0's owner_kind list,
-- copied whole, plus `acceptance_record`). The integrator merges the other parts' owners into one list.
ALTER TABLE executive.workflow_timers DROP CONSTRAINT IF EXISTS workflow_timers_owner_kind_check;
ALTER TABLE executive.workflow_timers ADD CONSTRAINT workflow_timers_owner_kind_check CHECK (owner_kind IN ('task', 'workflow_instance', 'grant', 'commitment_item', 'gate',
  -- B94 sv (0114 §SV.0)
  'service_case',
  -- B107 dr (0115 §DR.0) — B107 integration: §DR's kind kept (§AR applies after §DR in the fold)
  'stewardship_case',
  -- B107 ar (0115 §AR.0)
  'acceptance_record'));

-- §AR.1 THE VOCABULARIES ───────────────────────────────────────────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION governance.ar_kinds() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY['capability', 'operational', 'release', 'design'] $$;
/* The obligations a record may require, each a distinct named authority (ES-71-002). */
CREATE OR REPLACE FUNCTION governance.ar_obligations() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'product', 'independent_assurance', 'operations', 'security', 'privacy', 'ai_fitness', 'data', 'business', 'customer', 'design'] $$;
/* The roles that may attest an obligation (the demonstration's staffing; naming the real people is H2's — ES-71-002 B+X:staffing). Security
   and AI fitness are independent-assurance obligations here (no security or model authority role exists yet) — still one person each. */
CREATE OR REPLACE FUNCTION governance.ar_obligation_roles(p text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT CASE p
  WHEN 'product' THEN ARRAY['product_authority'] WHEN 'independent_assurance' THEN ARRAY['independent_assurance'] WHEN 'operations' THEN ARRAY['operations_authority']
  WHEN 'security' THEN ARRAY['independent_assurance'] WHEN 'privacy' THEN ARRAY['privacy_officer'] WHEN 'ai_fitness' THEN ARRAY['independent_assurance']
  WHEN 'data' THEN ARRAY['data_steward'] WHEN 'business' THEN ARRAY['executive', 'customer_sponsor'] WHEN 'customer' THEN ARRAY['customer_sponsor', 'onboarding_authority']
  WHEN 'design' THEN ARRAY['design_system_authority'] END $$;
/* The minimum obligations of a kind (a proposer may add, never remove). */
CREATE OR REPLACE FUNCTION governance.ar_min_obligations(p text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT CASE p
  WHEN 'capability' THEN ARRAY['product', 'independent_assurance', 'customer'] WHEN 'operational' THEN ARRAY['operations', 'independent_assurance', 'customer']
  WHEN 'release' THEN ARRAY['product', 'independent_assurance'] WHEN 'design' THEN ARRAY['design', 'independent_assurance'] END $$;
/* The evidence vault's kinds (INF-OP-12, DAT-OP-12: readiness, change, incident, recovery, exercise and acceptance evidence). */
CREATE OR REPLACE FUNCTION governance.ar_evidence_kinds() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'test_report', 'journey_evidence', 'build', 'release_candidate', 'conformance', 'exercise', 'drill', 'incident', 'change', 'readiness',
  'runbook', 'dashboard', 'alert', 'on_call', 'incident_roles', 'capacity', 'backup', 'recovery', 'degraded_mode', 'customer_communications', 'escalation',
  'security_review', 'privacy_review', 'accessibility', 'resilience', 'support_readiness', 'parity', 'deployment',
  'migration_acceptance', 'golive_decision', 'admission_record', 'value_review', 'design_package', 'other'] $$;
/* The evidence SLOTS a kind expects; an absent current item is an OPEN CONDITION, never a silent pass (ES-71-003, TS-020, V04-T-003, PR-71-006). */
CREATE OR REPLACE FUNCTION governance.ar_slots(p text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT CASE p
  WHEN 'operational' THEN ARRAY['runbook', 'dashboard', 'alert', 'on_call', 'incident_roles', 'capacity', 'backup', 'recovery', 'degraded_mode', 'customer_communications', 'escalation']
  WHEN 'capability' THEN ARRAY['security_review', 'privacy_review', 'accessibility', 'resilience', 'recovery', 'support_readiness', 'parity']
  ELSE ARRAY[]::text[] END $$;
/* The subjects an evidence item may reference (verified against the referenced row, never rewritten). */
CREATE OR REPLACE FUNCTION governance.ar_evidence_subjects() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'onboarding.migration_acceptance', 'implementation.golive_decision', 'service.admission_record', 'service.value_review', 'service.control_drill',
  'service.joint_exercise', 'executive.signature', 'governance.artifact', 'external'] $$;
/* The keys an OPERATIONAL scope adds (IA-71-003, DP-71-003): exact artifacts, integrations, data classes, workloads, products, infrastructure. */
CREATE OR REPLACE FUNCTION governance.ar_operational_scope_keys() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY['artifacts', 'integrations', 'data_classes', 'workloads', 'products', 'infrastructure'] $$;
/* Review triggers (ES-71-005): what an act may declare; the sweep raises the rest itself. */
CREATE OR REPLACE FUNCTION governance.ar_trigger_kinds() RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY[
  'material_change', 'incident', 'control_failure', 'model_withdrawal', 'agent_withdrawal', 'slo_exhaustion',
  'evidence_expired', 'evidence_failed', 'condition_overdue', 'review_due', 'period_ended', 'capability_changed', 'exception_expired', 'release_held'] $$;
CREATE OR REPLACE FUNCTION governance.ar_class_rank(p text) RETURNS int LANGUAGE sql IMMUTABLE AS $$ SELECT array_position(ARRAY['C0', 'C1', 'C2', 'C3', 'C4'], p) $$;
GRANT EXECUTE ON FUNCTION governance.ar_kinds(), governance.ar_obligations(), governance.ar_obligation_roles(text), governance.ar_min_obligations(text),
  governance.ar_evidence_kinds(), governance.ar_slots(text), governance.ar_evidence_subjects(), governance.ar_operational_scope_keys(), governance.ar_trigger_kinds(),
  governance.ar_class_rank(text) TO eye_app, eye_commit;

-- §AR.2 THE TABLES ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* THE EVIDENCE VAULT (INF-OP-12, DAT-OP-12, IADR-022): append-only items, each a digest-bound reference with its capture and validity; a
   renewal or a failure is a LATER item (renews). Every item is SYNTHETIC on a demonstration (claim). */
CREATE TABLE governance.acceptance_evidence (
  evidence_id     uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id       uuid NOT NULL,
  domain_id       uuid NOT NULL,
  kind            text NOT NULL CONSTRAINT gae_kind CHECK (kind = ANY (governance.ar_evidence_kinds())),
  title           text NOT NULL CHECK (length(btrim(title)) BETWEEN 4 AND 300),
  subject_kind    text NOT NULL CONSTRAINT gae_subject CHECK (subject_kind = ANY (governance.ar_evidence_subjects())),
  subject_id      uuid,
  subject_version int,
  subject_digest  text NOT NULL CHECK (subject_digest ~ '^[0-9a-f]{64}$'),
  pointer         text CHECK (pointer IS NULL OR length(btrim(pointer)) BETWEEN 3 AND 500),
  covers          jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(covers) = 'object'),
  outcome         text NOT NULL DEFAULT 'passed' CHECK (outcome IN ('passed', 'failed', 'recorded')),
  captured_at     timestamptz NOT NULL,
  valid_until     timestamptz NOT NULL,
  renews          uuid REFERENCES governance.acceptance_evidence (evidence_id),
  digest          text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  claim           text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  recorded_by     uuid NOT NULL,
  recorded_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  CONSTRAINT gae_validity CHECK (valid_until > captured_at),
  CONSTRAINT gae_reference CHECK ((subject_kind = 'external') = (subject_id IS NULL) AND (subject_kind <> 'external' OR pointer IS NOT NULL))
);
CREATE INDEX gae_domain ON governance.acceptance_evidence (tenant_id, domain_id, kind, recorded_at DESC);
CREATE TRIGGER gae_append_only BEFORE UPDATE OR DELETE ON governance.acceptance_evidence FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

/* THE ACCEPTANCE RECORD — versioned per record_id; a version's content is digest-bound and never edited (state columns move). */
CREATE TABLE governance.acceptance_records (
  record_id        uuid NOT NULL,
  version          int  NOT NULL CHECK (version >= 1),
  scope            text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id        uuid NOT NULL,
  domain_id        uuid NOT NULL,
  kind             text NOT NULL CONSTRAINT gac_kind CHECK (kind = ANY (governance.ar_kinds())),
  title            text NOT NULL CHECK (length(btrim(title)) BETWEEN 4 AND 300),
  subject_artifact uuid NOT NULL,
  subject_key      text NOT NULL,
  subject_digest   text NOT NULL CHECK (subject_digest ~ '^[0-9a-f]{64}$'),
  scope_tuple      jsonb NOT NULL CHECK (jsonb_typeof(scope_tuple) = 'object'),
  obligations      text[] NOT NULL CHECK (cardinality(obligations) >= 2),
  evidence         jsonb NOT NULL CHECK (jsonb_typeof(evidence) = 'array'),
  conditions       jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(conditions) = 'array'),
  exceptions       jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(exceptions) = 'array'),
  operational      jsonb CHECK (operational IS NULL OR jsonb_typeof(operational) = 'object'),
  builders         uuid[] NOT NULL DEFAULT '{}',
  digest           text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  state            text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'accepted', 'constrained', 'suspended', 'lapsed', 'withheld', 'withdrawn', 'superseded')),
  effective_scope  jsonb,
  constrained_reasons jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(constrained_reasons) = 'array'),
  claim            text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  real_acceptance  text NOT NULL DEFAULT 'R2: acceptance by named independent and customer authorities is external — this record is construction or demonstration evidence only',
  proposed_by      uuid NOT NULL,
  proposed_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
  accepted_at      timestamptz,
  constrained_at   timestamptz,
  ended_by         uuid,
  ended_at         timestamptz,
  end_reason       text,
  expiry_timer_id  uuid,
  correlation_id   uuid NOT NULL,
  PRIMARY KEY (record_id, version),
  CONSTRAINT gac_accepted CHECK (state IN ('proposed', 'withheld', 'withdrawn', 'superseded') OR accepted_at IS NOT NULL OR state = 'superseded'),
  CONSTRAINT gac_constrained CHECK (state NOT IN ('constrained', 'suspended', 'lapsed') OR constrained_at IS NOT NULL)
);
CREATE UNIQUE INDEX gac_one_proposed ON governance.acceptance_records (record_id) WHERE state = 'proposed';
CREATE UNIQUE INDEX gac_one_in_force ON governance.acceptance_records (record_id) WHERE state IN ('accepted', 'constrained', 'suspended', 'lapsed');
CREATE INDEX gac_subject ON governance.acceptance_records (tenant_id, subject_artifact, state);

/* THE ATTESTATIONS (append-only): one named human per obligation per version, SIGNED when attesting (executive.signatures
   acceptance_attestation over the version's digest). A withholding ends the version (withheld) and exposes the unmet obligation. */
CREATE TABLE governance.acceptance_attestations (
  attestation_id  uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id       uuid NOT NULL,
  domain_id       uuid NOT NULL,
  record_id       uuid NOT NULL,
  version         int  NOT NULL,
  obligation      text NOT NULL CONSTRAINT gat_obligation CHECK (obligation = ANY (governance.ar_obligations())),
  decision        text NOT NULL CHECK (decision IN ('attest', 'withhold')),
  attester        uuid NOT NULL,
  attester_role   text NOT NULL,
  record_digest   text NOT NULL CHECK (record_digest ~ '^[0-9a-f]{64}$'),
  signature_id    uuid,
  reason          text NOT NULL CHECK (length(btrim(reason)) >= 8),
  claim           text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  attested_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  FOREIGN KEY (record_id, version) REFERENCES governance.acceptance_records (record_id, version),
  CONSTRAINT gat_one_per_obligation UNIQUE (record_id, version, obligation),
  CONSTRAINT gat_one_per_person UNIQUE (record_id, version, attester),
  CONSTRAINT gat_signed CHECK (decision <> 'attest' OR signature_id IS NOT NULL)
);
CREATE TRIGGER gat_append_only BEFORE UPDATE OR DELETE ON governance.acceptance_attestations FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

/* THE CUSTOMER VERIFICATION (JRN-24's customer-verify stage): the customer's named human verifies the version against its own scope before the
   customer obligation is attested. Append-only; one per version. */
CREATE TABLE governance.acceptance_verifications (
  verification_id uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id       uuid NOT NULL,
  domain_id       uuid NOT NULL,
  record_id       uuid NOT NULL,
  version         int  NOT NULL,
  record_digest   text NOT NULL CHECK (record_digest ~ '^[0-9a-f]{64}$'),
  outcome         text NOT NULL CHECK (outcome IN ('verified', 'not_verified')),
  findings        text NOT NULL CHECK (length(btrim(findings)) >= 8),
  verifier        uuid NOT NULL,
  verified_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  FOREIGN KEY (record_id, version) REFERENCES governance.acceptance_records (record_id, version),
  CONSTRAINT gav_one UNIQUE (record_id, version)
);
CREATE TRIGGER gav_append_only BEFORE UPDATE OR DELETE ON governance.acceptance_verifications FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

/* A CONDITION MET (append-only): the condition's key on the record, the CURRENT evidence that meets it, the named human. */
CREATE TABLE governance.acceptance_condition_events (
  event_id        uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id       uuid NOT NULL,
  domain_id       uuid NOT NULL,
  record_id       uuid NOT NULL,
  version         int  NOT NULL,
  condition_key   text NOT NULL,
  evidence_id     uuid NOT NULL REFERENCES governance.acceptance_evidence (evidence_id),
  reason          text NOT NULL CHECK (length(btrim(reason)) >= 8),
  met_by          uuid NOT NULL,
  met_at          timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  FOREIGN KEY (record_id, version) REFERENCES governance.acceptance_records (record_id, version),
  CONSTRAINT gace_once UNIQUE (record_id, version, condition_key)
);
CREATE TRIGGER gace_append_only BEFORE UPDATE OR DELETE ON governance.acceptance_condition_events FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

/* THE REVIEW TRIGGERS (ES-71-005, IA-71-005): what put a record under review, suspended or lapsed it — the sweep's findings and the acts. */
CREATE TABLE governance.acceptance_triggers (
  trigger_id      uuid PRIMARY KEY,
  scope           text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id       uuid NOT NULL,
  domain_id       uuid NOT NULL,
  record_id       uuid NOT NULL,
  version         int  NOT NULL,
  kind            text NOT NULL CONSTRAINT gtr_kind CHECK (kind = ANY (governance.ar_trigger_kinds())),
  policy          text NOT NULL CHECK (policy IN ('review', 'suspend', 'lapse')),
  detail          jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(detail) = 'object'),
  source          text NOT NULL CHECK (source IN ('sweep', 'act')),
  raised_by       uuid NOT NULL,
  raised_at       timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  FOREIGN KEY (record_id, version) REFERENCES governance.acceptance_records (record_id, version)
);
CREATE INDEX gtr_record ON governance.acceptance_triggers (record_id, version, raised_at);
CREATE TRIGGER gtr_append_only BEFORE UPDATE OR DELETE ON governance.acceptance_triggers FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

/* THE OPT-IN GATE'S REGISTER (PLATFORM, the vendor's; versioned, append-only): a capability marked enforce_acceptance and the action prefixes it
   covers. The current row per capability is the highest version. */
CREATE TABLE governance.acceptance_enforcement (
  capability_key  text NOT NULL,
  version         int  NOT NULL CHECK (version >= 1),
  scope           text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id       uuid CHECK (tenant_id IS NULL),
  domain_id       uuid CHECK (domain_id IS NULL),
  capability_artifact uuid NOT NULL,
  enforced        boolean NOT NULL,
  action_prefixes text[] NOT NULL,
  reason          text NOT NULL CHECK (length(btrim(reason)) >= 8),
  digest          text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  set_by          uuid NOT NULL,
  set_at          timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id  uuid NOT NULL,
  PRIMARY KEY (capability_key, version),
  CONSTRAINT gaf_prefixes CHECK (NOT enforced OR cardinality(action_prefixes) >= 1)
);
CREATE TRIGGER gaf_append_only BEFORE UPDATE OR DELETE ON governance.acceptance_enforcement FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();

-- RLS and grants (the prelude's idioms): the DOMAIN tables under domain isolation; the PLATFORM register readable by every authenticated
-- context (the vendor's registry, not tenant data); SELECT only — the definer ports write.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['governance.acceptance_evidence', 'governance.acceptance_records', 'governance.acceptance_attestations', 'governance.acceptance_verifications',
                           'governance.acceptance_condition_events', 'governance.acceptance_triggers'] LOOP
    EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', t);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($f$CREATE POLICY domain_isolation ON %s USING (tenant_id = public.eye_tenant() AND (public.eye_scope() = 'TENANT' OR domain_id = public.eye_domain()))$f$, t);
    EXECUTE format('GRANT SELECT ON %s TO eye_app, eye_commit', t);
  END LOOP;
  REVOKE ALL ON governance.acceptance_enforcement FROM PUBLIC;
  ALTER TABLE governance.acceptance_enforcement ENABLE ROW LEVEL SECURITY;
  ALTER TABLE governance.acceptance_enforcement FORCE ROW LEVEL SECURITY;
  CREATE POLICY governance_visibility ON governance.acceptance_enforcement USING (public.eye_scope() <> 'NONE');
  GRANT SELECT ON governance.acceptance_enforcement TO eye_app, eye_commit;
END $$;

-- §AR.3 INTERNAL HELPERS (SECURITY DEFINER where they write; REVOKE PUBLIC; granted to no runtime role — the ports call them) ──────────────
/* The acting principal is the route's. */
CREATE OR REPLACE FUNCTION governance._ar_actor(p_noun text, p_actor uuid) RETURNS void
LANGUAGE plpgsql STABLE SET search_path = public, pg_catalog, pg_temp AS $$
BEGIN
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN
    RAISE EXCEPTION '% rejected (actor): the act is recorded under the acting principal', p_noun USING ERRCODE = '42501';
  END IF;
END $$;
REVOKE ALL ON FUNCTION governance._ar_actor(text, uuid) FROM PUBLIC;

/* REGISTER (or re-version) an artifact of the shared core: nothing when the current version carries the same digest; otherwise the current
   version is superseded and the next written (the prelude's rule: one current version per artifact and per kind + key + owner scope). */
CREATE OR REPLACE FUNCTION governance._ar_artifact(p_id uuid, p_tenant uuid, p_domain uuid, p_kind text, p_key text, p_title text, p_lifecycle text, p_attrs jsonb, p_digest text,
                                                   p_actor uuid, p_correlation uuid) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE cur governance.artifacts%ROWTYPE;
BEGIN
  SELECT * INTO cur FROM governance.artifacts a WHERE a.artifact_id = p_id AND a.superseded_at IS NULL FOR UPDATE;
  IF FOUND AND cur.digest = p_digest AND cur.lifecycle = p_lifecycle THEN RETURN cur.version; END IF;
  IF FOUND THEN UPDATE governance.artifacts SET superseded_at = clock_timestamp() WHERE artifact_id = p_id AND version = cur.version; END IF;
  INSERT INTO governance.artifacts (artifact_id, version, scope, tenant_id, domain_id, kind, external_key, title, owner_role, authority_class, controlling_volume, lifecycle,
                                    attributes, source, digest, recorded_by, correlation_id)
  VALUES (p_id, coalesce(cur.version, 0) + 1, CASE WHEN p_domain IS NOT NULL THEN 'DOMAIN' WHEN p_tenant IS NOT NULL THEN 'TENANT' ELSE 'PLATFORM' END, p_tenant, p_domain, p_kind, p_key,
          left(p_title, 500), 'product_authority', 'acceptance', 'V8', p_lifecycle, coalesce(p_attrs, '{}'::jsonb), jsonb_build_object('part', 'B107 §AR', 'claim', 'demonstration'),
          p_digest, p_actor, p_correlation);
  RETURN coalesce(cur.version, 0) + 1;
END $$;
REVOKE ALL ON FUNCTION governance._ar_artifact(uuid, uuid, uuid, text, text, text, text, jsonb, text, uuid, uuid) FROM PUBLIC;

/* A LINK of the shared core, written once (a live link of the same from/to/relation answers itself). */
CREATE OR REPLACE FUNCTION governance._ar_link(p_tenant uuid, p_domain uuid, p_from uuid, p_to uuid, p_relation text, p_attrs jsonb, p_actor uuid, p_correlation uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v uuid;
BEGIN
  SELECT l.link_id INTO v FROM governance.links l WHERE l.from_artifact = p_from AND l.to_artifact = p_to AND l.relation = p_relation AND NOT l.retired
     AND NOT EXISTS (SELECT 1 FROM governance.links r WHERE r.retires_link = l.link_id) LIMIT 1;
  IF v IS NOT NULL THEN RETURN v; END IF;
  v := gen_random_uuid();
  INSERT INTO governance.links (link_id, scope, tenant_id, domain_id, from_artifact, to_artifact, relation, attributes, recorded_by, correlation_id)
  VALUES (v, CASE WHEN p_domain IS NOT NULL THEN 'DOMAIN' WHEN p_tenant IS NOT NULL THEN 'TENANT' ELSE 'PLATFORM' END, p_tenant, p_domain, p_from, p_to, p_relation,
          coalesce(p_attrs, '{}'::jsonb), p_actor, p_correlation);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance._ar_link(uuid, uuid, uuid, uuid, text, jsonb, uuid, uuid) FROM PUBLIC;

/* A blanket value anywhere in a scope (PAT-48: "no blanket acceptance"): '*', 'all', 'any', 'every', '%' as a whole string value, or an empty list. */
CREATE OR REPLACE FUNCTION governance.ar_blanket(p jsonb) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
  WITH RECURSIVE walk(path, v) AS (
    SELECT ARRAY[k], e FROM jsonb_each(CASE WHEN jsonb_typeof(p) = 'object' THEN p ELSE '{}'::jsonb END) AS x(k, e)
    UNION ALL
    SELECT w.path || c.k, c.e FROM walk w, LATERAL (
      SELECT o.k, o.e FROM jsonb_each(CASE WHEN jsonb_typeof(w.v) = 'object' THEN w.v ELSE '{}'::jsonb END) AS o(k, e)
      UNION ALL
      SELECT '[' || (a.i - 1)::text || ']', a.e FROM jsonb_array_elements(CASE WHEN jsonb_typeof(w.v) = 'array' THEN w.v ELSE '[]'::jsonb END) WITH ORDINALITY AS a(e, i)) c
  )
  SELECT array_to_string(path, '.') FROM walk
   WHERE (jsonb_typeof(v) = 'string' AND lower(btrim(v #>> '{}')) IN ('*', 'all', 'any', 'every', '%', 'everything', 'everyone'))
      OR (jsonb_typeof(v) = 'array' AND jsonb_array_length(v) = 0)
   ORDER BY 1 LIMIT 1
$$;
GRANT EXECUTE ON FUNCTION governance.ar_blanket(jsonb) TO eye_app, eye_commit;

/* The EFFECTIVE scope (FEX-31): the accepted scope minus what the affected evidence items COVER (journeys, roles, data keys). An item covering
   the whole scope (no covers) removes nothing — the record stays within its previously accepted scope, expansion held. */
CREATE OR REPLACE FUNCTION governance.ar_effective_scope(p_scope jsonb, p_affected jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
  WITH cut AS (
    SELECT coalesce(jsonb_agg(DISTINCT j) FILTER (WHERE j IS NOT NULL), '[]'::jsonb) AS journeys,
           coalesce((SELECT jsonb_agg(DISTINCT r) FROM jsonb_array_elements(coalesce(p_affected, '[]'::jsonb)) a, jsonb_array_elements_text(coalesce(a -> 'covers' -> 'roles', '[]'::jsonb)) r), '[]'::jsonb) AS roles,
           coalesce((SELECT jsonb_agg(DISTINCT k) FROM jsonb_array_elements(coalesce(p_affected, '[]'::jsonb)) a, jsonb_array_elements_text(coalesce(a -> 'covers' -> 'data', '[]'::jsonb)) k), '[]'::jsonb) AS data
      FROM jsonb_array_elements(coalesce(p_affected, '[]'::jsonb)) a LEFT JOIN LATERAL jsonb_array_elements_text(coalesce(a -> 'covers' -> 'journeys', '[]'::jsonb)) j ON true
  )
  SELECT p_scope
         || jsonb_build_object('journeys', coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements_text(p_scope -> 'journeys') x WHERE NOT (cut.journeys ? x)), '[]'::jsonb),
                               'roles', coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements_text(p_scope -> 'roles') x WHERE NOT (cut.roles ? x)), '[]'::jsonb),
                               'data_versions', coalesce((SELECT jsonb_object_agg(k, v) FROM jsonb_each(coalesce(p_scope -> 'data_versions', '{}'::jsonb)) e(k, v) WHERE NOT (cut.data ? k)), '{}'::jsonb),
                               'removed', jsonb_build_object('journeys', cut.journeys, 'roles', cut.roles, 'data', cut.data))
    FROM cut
$$;
GRANT EXECUTE ON FUNCTION governance.ar_effective_scope(jsonb, jsonb) TO eye_app, eye_commit;

/* EXPANSION (ES-71-004): what the proposed scope adds beyond the previously accepted one — a domain, journeys, roles, a profile, data or model
   keys, a higher consequence class. An empty array means no expansion. */
CREATE OR REPLACE FUNCTION governance.ar_expansion(p_prior jsonb, p_next jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce(jsonb_agg(x), '[]'::jsonb) FROM (
    SELECT 'domain ' || (p_next ->> 'domain') AS x WHERE (p_next ->> 'domain') IS DISTINCT FROM (p_prior ->> 'domain')
    UNION ALL SELECT 'journey ' || j FROM jsonb_array_elements_text(coalesce(p_next -> 'journeys', '[]'::jsonb)) j WHERE NOT (coalesce(p_prior -> 'journeys', '[]'::jsonb) ? j)
    UNION ALL SELECT 'role ' || r FROM jsonb_array_elements_text(coalesce(p_next -> 'roles', '[]'::jsonb)) r WHERE NOT (coalesce(p_prior -> 'roles', '[]'::jsonb) ? r)
    UNION ALL SELECT 'deployment profile ' || (p_next ->> 'deployment_profile') WHERE (p_next ->> 'deployment_profile') IS DISTINCT FROM (p_prior ->> 'deployment_profile')
    UNION ALL SELECT 'data ' || k FROM jsonb_object_keys(coalesce(p_next -> 'data_versions', '{}'::jsonb)) k WHERE NOT (coalesce(p_prior -> 'data_versions', '{}'::jsonb) ? k)
    UNION ALL SELECT 'model ' || k FROM jsonb_object_keys(coalesce(p_next -> 'model_versions', '{}'::jsonb)) k WHERE NOT (coalesce(p_prior -> 'model_versions', '{}'::jsonb) ? k)
    UNION ALL SELECT 'consequence class ' || (p_next ->> 'consequence_class')
     WHERE coalesce(governance.ar_class_rank(p_next ->> 'consequence_class'), 0) > coalesce(governance.ar_class_rank(p_prior ->> 'consequence_class'), 0)
  ) s
$$;
GRANT EXECUTE ON FUNCTION governance.ar_expansion(jsonb, jsonb) TO eye_app, eye_commit;

/* Verify an evidence reference against its row (never rewriting it): the row exists in this tenant/domain (a shared artifact may be PLATFORM)
   and its digest; answers the digest the item binds. */
CREATE OR REPLACE FUNCTION governance._ar_reference(p_tenant uuid, p_domain uuid, p_kind text, p_id uuid, p_version int) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, onboarding, implementation, service, executive, pg_catalog, pg_temp AS $$
DECLARE v jsonb;
BEGIN
  CASE p_kind
    WHEN 'onboarding.migration_acceptance' THEN
      SELECT jsonb_build_object('digest', a.digest, 'state', a.decision, 'what', 'migration acceptance (' || a.decision || ')') INTO v FROM onboarding.migration_acceptances a
       WHERE a.acceptance_id = p_id AND a.tenant_id = p_tenant AND a.domain_id = p_domain;
    WHEN 'implementation.golive_decision' THEN
      SELECT jsonb_build_object('digest', g.gate_digest, 'state', g.decision, 'what', 'go-live decision (' || g.decision || ')') INTO v FROM implementation.golive_decisions g
       WHERE g.decision_id = p_id AND g.tenant_id = p_tenant AND g.domain_id = p_domain;
    WHEN 'service.admission_record' THEN
      SELECT jsonb_build_object('digest', a.digest, 'state', a.state, 'what', 'admission record v' || a.version || ' (' || a.state || ')') INTO v FROM service.admission_records a
       WHERE a.admission_id = p_id AND a.version = coalesce(p_version, (SELECT max(x.version) FROM service.admission_records x WHERE x.admission_id = p_id))
         AND a.tenant_id = p_tenant AND a.domain_id = p_domain;
    WHEN 'service.value_review' THEN
      SELECT jsonb_build_object('digest', r.inputs_digest, 'state', r.state, 'what', 'value review (' || r.state || ')') INTO v FROM service.value_reviews r
       WHERE r.review_id = p_id AND r.tenant_id = p_tenant AND r.domain_id = p_domain;
    WHEN 'service.control_drill' THEN
      SELECT jsonb_build_object('digest', encode(sha256(convert_to(to_jsonb(d)::text, 'UTF8')), 'hex'), 'state', d.outcome, 'what', 'control drill ' || d.kind || ' (' || d.outcome || ')') INTO v
        FROM service.control_drills d WHERE d.drill_id = p_id AND d.tenant_id = p_tenant AND d.domain_id = p_domain;
    WHEN 'service.joint_exercise' THEN
      SELECT jsonb_build_object('digest', encode(sha256(convert_to(to_jsonb(x)::text, 'UTF8')), 'hex'), 'state', x.outcome, 'what', 'joint exercise (' || x.outcome || ')') INTO v
        FROM service.joint_exercises x WHERE x.exercise_id = p_id AND x.tenant_id = p_tenant AND x.domain_id = p_domain;
    WHEN 'executive.signature' THEN
      SELECT jsonb_build_object('digest', s.subject_digest, 'state', s.subject_kind, 'what', 'signature over ' || s.subject_kind) INTO v FROM executive.signatures s
       WHERE s.signature_id = p_id AND s.tenant_id = p_tenant AND s.domain_id = p_domain;
    WHEN 'governance.artifact' THEN
      SELECT jsonb_build_object('digest', a.digest, 'state', a.lifecycle, 'what', a.kind || ' ' || a.external_key || ' v' || a.version) INTO v FROM governance.artifacts a
       WHERE a.artifact_id = p_id AND (p_version IS NULL AND a.superseded_at IS NULL OR a.version = p_version)
         AND (a.scope = 'PLATFORM' OR (a.tenant_id = p_tenant AND (a.domain_id IS NULL OR a.domain_id = p_domain)));
    ELSE v := NULL;
  END CASE;
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance._ar_reference(uuid, uuid, text, uuid, int) FROM PUBLIC;

/* The JRN-24 journey of a version (trace → build → test → assure → deploy → exercise → customer verify → attest), from facts only: each stage
   done or open with what shows it. Informational except where a port requires a stage (customer verify before the customer attests). */
CREATE OR REPLACE FUNCTION governance.ar_journey(p_record uuid, p_version int) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE r governance.acceptance_records%ROWTYPE; v_now timestamptz := clock_timestamp(); v_items jsonb; v_out jsonb := '[]'::jsonb; v_traced int; s text; v_done boolean; v_by text;
BEGIN
  SELECT * INTO r FROM governance.acceptance_records x WHERE x.record_id = p_record AND x.version = p_version;
  IF NOT FOUND THEN RETURN NULL; END IF;
  PERFORM observation.assert_read_scope(r.tenant_id, r.domain_id, 'an acceptance record''s journey');
  SELECT coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'id', e.evidence_id, 'current', e.valid_until > v_now AND e.outcome <> 'failed')), '[]'::jsonb) INTO v_items
    FROM governance.acceptance_evidence e WHERE e.evidence_id IN (SELECT (x ->> 'evidence_id')::uuid FROM jsonb_array_elements(r.evidence) x);
  SELECT count(*) INTO v_traced FROM governance.links_live l JOIN governance.artifacts a ON a.artifact_id = CASE WHEN l.from_artifact = r.subject_artifact THEN l.to_artifact ELSE l.from_artifact END
   WHERE (l.from_artifact = r.subject_artifact OR l.to_artifact = r.subject_artifact) AND a.superseded_at IS NULL AND a.kind IN ('requirement', 'journey');
  FOREACH s IN ARRAY ARRAY['trace', 'build', 'test', 'assure', 'deploy', 'exercise', 'customer_verify', 'attest'] LOOP
    v_done := false; v_by := NULL;
    CASE s
      WHEN 'trace' THEN v_done := v_traced > 0; v_by := CASE WHEN v_traced > 0 THEN v_traced || ' live trace link(s) to requirements or journeys' ELSE 'no live trace link to a requirement or journey (§RG''s registry)' END;
      WHEN 'build' THEN v_done := EXISTS (SELECT 1 FROM jsonb_array_elements(v_items) i WHERE i ->> 'kind' IN ('build', 'release_candidate') AND (i ->> 'current')::boolean);
      WHEN 'test' THEN v_done := EXISTS (SELECT 1 FROM jsonb_array_elements(v_items) i WHERE i ->> 'kind' IN ('test_report', 'journey_evidence') AND (i ->> 'current')::boolean);
      WHEN 'assure' THEN v_done := EXISTS (SELECT 1 FROM governance.acceptance_attestations a WHERE a.record_id = p_record AND a.version = p_version AND a.obligation = 'independent_assurance' AND a.decision = 'attest');
      WHEN 'deploy' THEN v_done := EXISTS (SELECT 1 FROM jsonb_array_elements(v_items) i WHERE i ->> 'kind' IN ('deployment', 'golive_decision', 'admission_record', 'migration_acceptance') AND (i ->> 'current')::boolean);
      WHEN 'exercise' THEN v_done := EXISTS (SELECT 1 FROM jsonb_array_elements(v_items) i WHERE i ->> 'kind' IN ('exercise', 'drill', 'recovery', 'resilience') AND (i ->> 'current')::boolean);
      WHEN 'customer_verify' THEN v_done := EXISTS (SELECT 1 FROM governance.acceptance_verifications v WHERE v.record_id = p_record AND v.version = p_version AND v.outcome = 'verified');
      WHEN 'attest' THEN v_done := r.accepted_at IS NOT NULL;
    END CASE;
    v_out := v_out || jsonb_build_array(jsonb_build_object('stage', s, 'done', v_done, 'shown_by', v_by));
  END LOOP;
  RETURN jsonb_build_object('stages', v_out, 'current', (SELECT x ->> 'stage' FROM jsonb_array_elements(v_out) WITH ORDINALITY t(x, i) WHERE NOT (x ->> 'done')::boolean ORDER BY i LIMIT 1),
                            'note', 'customer verify and attest by a REAL customer are R2 — on a demonstration they are SYNTHETIC personas');
END $$;
REVOKE ALL ON FUNCTION governance.ar_journey(uuid, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_journey(uuid, int) TO eye_app, eye_commit;

/* A display name for an actor of this domain's acceptance (the named authorities are named): a PLATFORM-homed principal (the vendor's
   governance roles) or a principal of the caller's own tenant. */
CREATE OR REPLACE FUNCTION governance.ar_principal_name(p uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = identity, public, pg_catalog, pg_temp AS $$
  SELECT x.display_name FROM identity.principals x WHERE x.id = p AND (x.scope = 'PLATFORM' OR x.tenant_id = public.eye_tenant()) AND public.eye_scope() <> 'NONE'
$$;
REVOKE ALL ON FUNCTION governance.ar_principal_name(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_principal_name(uuid) TO eye_app, eye_commit;

-- §AR.4 THE EVIDENCE VAULT'S PORT ──────────────────────────────────────────────────────────────────────────────────────────────────────────
/* RECORD an evidence item (governance.acceptance.evidence.record — the conformance steward, the operations authority, the domain admin, the
   implementation lead or the onboarding authority; an agent may draft evidence, never accept it). A reference is VERIFIED against its row and
   its digest bound (a mismatch is refused); an external item names its pointer and digest. A renewal or a failure renews an earlier item of
   the same kind in the same domain. */
CREATE OR REPLACE FUNCTION governance.ar_record_evidence(p_evidence uuid, p_tenant uuid, p_domain uuid, p_kind text, p_title text, p_subject_kind text, p_subject_id uuid,
                                                         p_subject_version int, p_digest text, p_pointer text, p_covers jsonb, p_outcome text, p_captured_at timestamptz,
                                                         p_valid_until timestamptz, p_renews uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE v_ref jsonb; v_digest text := p_digest; v_now timestamptz := clock_timestamp(); v_item jsonb; prior governance.acceptance_evidence%ROWTYPE; k text;
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.acceptance.evidence.record']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  PERFORM governance._ar_actor('acceptance record', p_actor);
  IF p_kind IS NULL OR NOT (p_kind = ANY (governance.ar_evidence_kinds())) THEN
    RAISE EXCEPTION 'acceptance record rejected (evidence): % is not an evidence kind (%)', coalesce(p_kind, '<none>'), array_to_string(governance.ar_evidence_kinds(), ', ') USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_title, ''))) < 4 THEN RAISE EXCEPTION 'acceptance record rejected (evidence): an item has a title (4+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_subject_kind IS NULL OR NOT (p_subject_kind = ANY (governance.ar_evidence_subjects())) THEN
    RAISE EXCEPTION 'acceptance record rejected (evidence): % is not a referenceable subject (%)', coalesce(p_subject_kind, '<none>'), array_to_string(governance.ar_evidence_subjects(), ', ') USING ERRCODE = '22023';
  END IF;
  IF p_outcome NOT IN ('passed', 'failed', 'recorded') THEN RAISE EXCEPTION 'acceptance record rejected (evidence): the outcome is passed, failed or recorded' USING ERRCODE = '22023'; END IF;
  IF p_captured_at IS NULL OR p_captured_at > v_now + interval '5 minutes' THEN RAISE EXCEPTION 'acceptance record rejected (evidence): an item was captured at a past instant' USING ERRCODE = '22023'; END IF;
  IF p_valid_until IS NULL OR p_valid_until <= p_captured_at OR p_valid_until > p_captured_at + interval '1100 days' THEN
    RAISE EXCEPTION 'acceptance record rejected (evidence): an item is valid until an instant after its capture and within three years — evidence expires' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(coalesce(p_covers, '{}'::jsonb)) <> 'object' THEN RAISE EXCEPTION 'acceptance record rejected (evidence): covers is an object {journeys, roles, data}' USING ERRCODE = '22023'; END IF;
  FOR k IN SELECT jsonb_object_keys(coalesce(p_covers, '{}'::jsonb)) LOOP
    IF k NOT IN ('journeys', 'roles', 'data') OR jsonb_typeof(p_covers -> k) <> 'array' THEN
      RAISE EXCEPTION 'acceptance record rejected (evidence): covers names journeys, roles or data as lists (% is not)', k USING ERRCODE = '22023';
    END IF;
  END LOOP;
  IF p_subject_kind = 'external' THEN
    IF p_subject_id IS NOT NULL OR length(btrim(coalesce(p_pointer, ''))) < 3 OR coalesce(v_digest, '') !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'acceptance record rejected (evidence): an external item names its pointer and its digest (64 hex), and no in-product subject' USING ERRCODE = '22023';
    END IF;
  ELSE
    IF p_subject_id IS NULL THEN RAISE EXCEPTION 'acceptance record rejected (evidence): a % reference names its id', p_subject_kind USING ERRCODE = '22023'; END IF;
    v_ref := governance._ar_reference(p_tenant, p_domain, p_subject_kind, p_subject_id, p_subject_version);
    IF v_ref IS NULL THEN
      RAISE EXCEPTION 'acceptance record rejected (unknown_evidence_subject): % % is not a record of this domain', p_subject_kind, p_subject_id USING ERRCODE = '23503';
    END IF;
    IF v_digest IS NULL THEN v_digest := v_ref ->> 'digest'; END IF;
    IF v_digest IS DISTINCT FROM (v_ref ->> 'digest') THEN
      RAISE EXCEPTION 'acceptance record rejected (stale): the digest named is not the referenced %''s (it reads %)', v_ref ->> 'what', left(v_ref ->> 'digest', 12) USING ERRCODE = '23505';
    END IF;
  END IF;
  IF p_renews IS NOT NULL THEN
    SELECT * INTO prior FROM governance.acceptance_evidence e WHERE e.evidence_id = p_renews AND e.tenant_id = p_tenant AND e.domain_id = p_domain;
    IF NOT FOUND THEN RAISE EXCEPTION 'acceptance record rejected (unknown_evidence): % is not an evidence item of this domain', p_renews USING ERRCODE = '23503'; END IF;
    IF prior.kind <> p_kind THEN RAISE EXCEPTION 'acceptance record rejected (evidence): a renewal keeps the kind (% renews %)', p_kind, prior.kind USING ERRCODE = '22023'; END IF;
    IF EXISTS (SELECT 1 FROM governance.acceptance_evidence e WHERE e.renews = p_renews) THEN
      RAISE EXCEPTION 'acceptance record rejected (duplicate): item % is already renewed', p_renews USING ERRCODE = '23505';
    END IF;
  END IF;
  v_item := jsonb_build_object('evidence_id', p_evidence, 'kind', p_kind, 'subject_kind', p_subject_kind, 'subject_id', p_subject_id, 'subject_version', p_subject_version,
                               'subject_digest', v_digest, 'pointer', p_pointer, 'covers', coalesce(p_covers, '{}'::jsonb), 'outcome', p_outcome,
                               'captured_at', p_captured_at, 'valid_until', p_valid_until, 'renews', p_renews);
  INSERT INTO governance.acceptance_evidence (evidence_id, tenant_id, domain_id, kind, title, subject_kind, subject_id, subject_version, subject_digest, pointer, covers, outcome,
                                              captured_at, valid_until, renews, digest, recorded_by, correlation_id)
  VALUES (p_evidence, p_tenant, p_domain, p_kind, btrim(p_title), p_subject_kind, p_subject_id, p_subject_version, v_digest, p_pointer, coalesce(p_covers, '{}'::jsonb), p_outcome,
          p_captured_at, p_valid_until, p_renews, governance.digest(v_item), p_actor, p_correlation);
  PERFORM governance._ar_artifact(p_evidence, p_tenant, p_domain, 'evidence', 'EVD-' || p_evidence::text, btrim(p_title), 'active',
                                  v_item - 'evidence_id', governance.digest(v_item), p_actor, p_correlation);
  IF p_subject_kind = 'governance.artifact' THEN
    PERFORM governance._ar_link(p_tenant, p_domain, p_evidence, p_subject_id, 'evidences', jsonb_build_object('kind', p_kind), p_actor, p_correlation);
  END IF;
  IF p_renews IS NOT NULL THEN PERFORM governance._ar_link(p_tenant, p_domain, p_evidence, p_renews, 'supersedes', '{}'::jsonb, p_actor, p_correlation); END IF;
  PERFORM governance.ledger(p_tenant, p_domain, 'acceptance_evidence', p_evidence, 1, CASE WHEN p_outcome = 'failed' THEN 'evidence.failed' WHEN p_renews IS NULL THEN 'evidence.recorded' ELSE 'evidence.renewed' END,
                            p_actor, v_item, p_correlation);
  RETURN v_item || jsonb_build_object('digest', governance.digest(v_item), 'reference', v_ref, 'claim', 'demonstration');
END $$;
REVOKE ALL ON FUNCTION governance.ar_record_evidence(uuid, uuid, uuid, text, text, text, uuid, int, text, text, jsonb, text, timestamptz, timestamptz, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_record_evidence(uuid, uuid, uuid, text, text, text, uuid, int, text, text, jsonb, text, timestamptz, timestamptz, uuid, uuid, uuid) TO eye_commit;

-- §AR.5 PROPOSE ───────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* PROPOSE a record (or its next version — the re-acceptance) — governance.acceptance.propose. The exact scope (no blanket — PAT-48), the
   obligations (at least the kind's minimum), CURRENT evidence (missing or stale refuses — PR-71-005), the conditions (absent slots become open
   conditions; a conditional record never admits a consequence class above C2 — ES-71-004 "consequence-limited"), the linked exceptions
   (unexpired), the release candidate unheld (a release record), the EXPANSION HOLD (a constrained, suspended or lapsed record of the same
   subject in this tenant refuses any proposal beyond its previously accepted scope), the expected version. */
CREATE OR REPLACE FUNCTION governance.ar_propose(p_record uuid, p_tenant uuid, p_domain uuid, p_kind text, p_title text, p_subject_key text, p_scope jsonb, p_obligations text[],
                                                 p_evidence uuid[], p_conditions jsonb, p_exceptions uuid[], p_operational jsonb, p_builders uuid[], p_expected_version int,
                                                 p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE
  v_now timestamptz := clock_timestamp(); v_today date := (clock_timestamp() AT TIME ZONE 'UTC')::date;
  subj governance.artifacts%ROWTYPE; v_cur int; v_version int; v_scope jsonb; v_blank text; v_from date; v_to date; k text; x jsonb; o text;
  v_items jsonb := '[]'::jsonb; v_conditions jsonb := '[]'::jsonb; v_exceptions jsonb := '[]'::jsonb; v_builders uuid[]; v_digest text; v_open int;
  v_held jsonb; v_prior governance.acceptance_records%ROWTYPE; v_exp jsonb; v_matrix jsonb; v_kinds text[]; v_task jsonb; v_tasks jsonb := '[]'::jsonb;
  v_subject_kinds text[]; v_obligations text[]; v_operational jsonb := NULL; v_slot text; v_dup uuid;
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.acceptance.propose']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  PERFORM governance._ar_actor('acceptance record', p_actor);
  IF p_kind IS NULL OR NOT (p_kind = ANY (governance.ar_kinds())) THEN
    RAISE EXCEPTION 'acceptance record rejected (kind): % is not a record kind (capability, operational, release, design)', coalesce(p_kind, '<none>') USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_title, ''))) < 4 THEN RAISE EXCEPTION 'acceptance record rejected (title): a record has a title (4+ characters)' USING ERRCODE = '22023'; END IF;

  -- THE SUBJECT (the shared core's artifact: a capability — §RG's registry —, a release candidate — §CM's —, a design component or pattern — §DG's)
  v_subject_kinds := CASE p_kind WHEN 'release' THEN ARRAY['release_candidate'] WHEN 'design' THEN ARRAY['design_component', 'pattern', 'design_asset'] ELSE ARRAY['capability'] END;
  SELECT * INTO subj FROM governance.artifacts a WHERE a.kind = ANY (v_subject_kinds) AND a.external_key = p_subject_key AND a.superseded_at IS NULL AND a.scope = 'PLATFORM'
   ORDER BY a.effective_from DESC LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'acceptance record rejected (unknown_subject): no current % artifact %', array_to_string(v_subject_kinds, ' or '), coalesce(p_subject_key, '<none>') USING ERRCODE = '23503';
  END IF;
  IF subj.lifecycle NOT IN ('active', 'proposed') THEN
    RAISE EXCEPTION 'acceptance record rejected (state): % % is %', subj.kind, subj.external_key, subj.lifecycle USING ERRCODE = '23505';
  END IF;

  -- THE SCOPE TUPLE (PAT-48, ADR-023, PR-71-002, IA-71-003, DP-71-003): exact and complete; the tenant and domain are the route's
  IF jsonb_typeof(p_scope) <> 'object' THEN RAISE EXCEPTION 'acceptance record rejected (scope): the scope is an object' USING ERRCODE = '22023'; END IF;
  v_blank := governance.ar_blanket(p_scope);
  IF v_blank IS NOT NULL THEN
    RAISE EXCEPTION 'acceptance record rejected (blanket): % is a blanket value — acceptance binds an exact scope (PAT-48: no blanket acceptance)', v_blank USING ERRCODE = '22023';
  END IF;
  FOREACH k IN ARRAY ARRAY['capability_version', 'journeys', 'roles', 'deployment_profile', 'entitlement', 'data_versions', 'model_versions', 'configuration_digest', 'consequence_class', 'period'] LOOP
    IF NOT (p_scope ? k) THEN RAISE EXCEPTION 'acceptance record rejected (scope): the scope names its % (the tuple is exact: capability version, journeys, roles, deployment profile, entitlement, data and model versions, configuration digest, consequence class, period)', k USING ERRCODE = '22023'; END IF;
  END LOOP;
  IF jsonb_typeof(p_scope -> 'journeys') <> 'array' OR jsonb_typeof(p_scope -> 'roles') <> 'array' THEN
    RAISE EXCEPTION 'acceptance record rejected (scope): journeys and roles are lists' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_scope -> 'roles') r WHERE NOT EXISTS (SELECT 1 FROM identity.roles x WHERE x.code = r)) THEN
    RAISE EXCEPTION 'acceptance record rejected (scope): every role in scope is a role of the product (%)', (SELECT string_agg(r, ', ') FROM jsonb_array_elements_text(p_scope -> 'roles') r WHERE NOT EXISTS (SELECT 1 FROM identity.roles x WHERE x.code = r)) USING ERRCODE = '22023';
  END IF;
  IF (p_scope ->> 'deployment_profile') NOT IN ('local-dev', 'saas', 'private-cloud', 'on-premise') THEN
    RAISE EXCEPTION 'acceptance record rejected (scope): the deployment profile is local-dev, saas, private-cloud or on-premise' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_scope -> 'data_versions') <> 'object' OR jsonb_typeof(p_scope -> 'model_versions') <> 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_scope -> 'data_versions')) = 0 THEN
    RAISE EXCEPTION 'acceptance record rejected (scope): data versions (non-empty) and model versions are objects {name: version}' USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_scope ->> 'configuration_digest', '') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'acceptance record rejected (scope): the configuration digest is 64 hex' USING ERRCODE = '22023'; END IF;
  IF governance.ar_class_rank(p_scope ->> 'consequence_class') IS NULL THEN RAISE EXCEPTION 'acceptance record rejected (scope): the consequence class is C0–C4' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_scope ->> 'capability_version', ''))) < 1 OR length(btrim(coalesce(p_scope ->> 'entitlement', ''))) < 2 THEN
    RAISE EXCEPTION 'acceptance record rejected (scope): the capability version and the entitlement are named' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_from := (p_scope -> 'period' ->> 'from')::date; v_to := (p_scope -> 'period' ->> 'to')::date;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'acceptance record rejected (period): the period is {from, to} as days' USING ERRCODE = '22023';
  END;
  IF v_from IS NULL OR v_to IS NULL OR v_to < v_from OR v_to < v_today OR v_to - v_from > 366 THEN
    RAISE EXCEPTION 'acceptance record rejected (period): a period from ≤ to, not ended, at most 366 days — acceptance is time-bounded' USING ERRCODE = '22023';
  END IF;
  IF p_kind = 'operational' THEN
    FOREACH k IN ARRAY governance.ar_operational_scope_keys() LOOP
      IF jsonb_typeof(p_scope -> k) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'acceptance record rejected (scope): an operational acceptance names its % (a non-empty list — IA-71-003, DP-71-003)', k USING ERRCODE = '22023';
      END IF;
    END LOOP;
  END IF;
  v_scope := (p_scope - 'tenant' - 'domain' - 'capability' - 'release') || jsonb_build_object('tenant', p_tenant, 'domain', p_domain, 'capability', CASE WHEN p_kind = 'release' THEN NULL ELSE subj.external_key END);
  IF p_kind = 'release' THEN
    v_scope := v_scope || jsonb_build_object('release', jsonb_build_object('candidate_id', subj.artifact_id, 'version', subj.version, 'key', subj.external_key, 'digest', subj.digest,
                                                                            'identity', subj.attributes));
  END IF;

  -- THE OBLIGATIONS (ES-71-002, PR-71-003)
  v_obligations := ARRAY(SELECT DISTINCT unnest(coalesce(p_obligations, '{}'::text[]) || governance.ar_min_obligations(p_kind)) ORDER BY 1);
  FOREACH o IN ARRAY v_obligations LOOP
    IF NOT (o = ANY (governance.ar_obligations())) THEN RAISE EXCEPTION 'acceptance record rejected (obligation): % is not an obligation (%)', o, array_to_string(governance.ar_obligations(), ', ') USING ERRCODE = '22023'; END IF;
  END LOOP;

  -- THE EVIDENCE (current, passed or recorded, of this domain; covers within scope); missing or stale refuses (PR-71-005)
  IF cardinality(coalesce(p_evidence, '{}'::uuid[])) = 0 THEN RAISE EXCEPTION 'acceptance record rejected (evidence_missing): acceptance is evidence-bound — name the evidence items' USING ERRCODE = '22023'; END IF;
  FOR x IN SELECT to_jsonb(e) FROM governance.acceptance_evidence e WHERE e.evidence_id = ANY (p_evidence) AND e.tenant_id = p_tenant AND e.domain_id = p_domain ORDER BY e.kind, e.recorded_at LOOP
    IF (x ->> 'valid_until')::timestamptz <= v_now THEN
      RAISE EXCEPTION 'acceptance record rejected (stale): evidence % (%) expired at % — renew it first', x ->> 'evidence_id', x ->> 'kind', x ->> 'valid_until' USING ERRCODE = '23505';
    END IF;
    IF x ->> 'outcome' = 'failed' OR EXISTS (SELECT 1 FROM governance.acceptance_evidence f WHERE f.renews = (x ->> 'evidence_id')::uuid AND f.outcome = 'failed') THEN
      RAISE EXCEPTION 'acceptance record rejected (evidence_failed): evidence % (%) records a failure — remediate and retest', x ->> 'evidence_id', x ->> 'kind' USING ERRCODE = '22023';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(coalesce(x -> 'covers' -> 'journeys', '[]'::jsonb)) j WHERE NOT ((v_scope -> 'journeys') ? j))
       OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(coalesce(x -> 'covers' -> 'roles', '[]'::jsonb)) r WHERE NOT ((v_scope -> 'roles') ? r)) THEN
      RAISE EXCEPTION 'acceptance record rejected (scope): evidence % covers journeys or roles outside the declared scope', x ->> 'evidence_id' USING ERRCODE = '22023';
    END IF;
    v_items := v_items || jsonb_build_array(jsonb_build_object('evidence_id', x -> 'evidence_id', 'kind', x -> 'kind', 'title', x -> 'title', 'digest', x -> 'digest',
                                                               'subject_kind', x -> 'subject_kind', 'subject_digest', x -> 'subject_digest', 'covers', x -> 'covers',
                                                               'captured_at', x -> 'captured_at', 'valid_until', x -> 'valid_until', 'recorded_by', x -> 'recorded_by'));
  END LOOP;
  IF jsonb_array_length(v_items) <> cardinality(ARRAY(SELECT DISTINCT unnest(p_evidence))) THEN
    RAISE EXCEPTION 'acceptance record rejected (unknown_evidence): % of the named evidence items are not items of this domain', cardinality(ARRAY(SELECT DISTINCT unnest(p_evidence))) - jsonb_array_length(v_items) USING ERRCODE = '23503';
  END IF;
  v_kinds := ARRAY(SELECT DISTINCT i ->> 'kind' FROM jsonb_array_elements(v_items) i);
  IF p_kind IN ('capability', 'release') AND NOT ('test_report' = ANY (v_kinds) OR 'journey_evidence' = ANY (v_kinds)) THEN
    RAISE EXCEPTION 'acceptance record rejected (evidence_missing): a % acceptance needs current test or journey evidence (PR-71-006)', p_kind USING ERRCODE = '22023';
  END IF;

  -- THE CONDITIONS: the proposer's, plus an OPEN condition for every absent evidence slot (never a silent pass)
  IF jsonb_typeof(coalesce(p_conditions, '[]'::jsonb)) <> 'array' THEN RAISE EXCEPTION 'acceptance record rejected (condition): conditions are a list' USING ERRCODE = '22023'; END IF;
  FOR x IN SELECT * FROM jsonb_array_elements(coalesce(p_conditions, '[]'::jsonb)) LOOP
    IF coalesce(x ->> 'key', '') !~ '^[a-z][a-z0-9_.:-]{1,60}$' OR length(btrim(coalesce(x ->> 'text', ''))) < 8 THEN
      RAISE EXCEPTION 'acceptance record rejected (condition): a condition has a key and a text (8+ characters)' USING ERRCODE = '22023';
    END IF;
    BEGIN
      IF (x ->> 'due')::date < v_today OR (x ->> 'due')::date > v_to THEN
        RAISE EXCEPTION 'acceptance record rejected (condition): condition % is due within the period (by %)', x ->> 'key', v_to USING ERRCODE = '22023';
      END IF;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation THEN
      RAISE EXCEPTION 'acceptance record rejected (condition): condition % names its due day', x ->> 'key' USING ERRCODE = '22023';
    END;
    IF x ->> 'due' IS NULL THEN RAISE EXCEPTION 'acceptance record rejected (condition): condition % names its due day — conditions are time-bounded', x ->> 'key' USING ERRCODE = '22023'; END IF;
    IF v_conditions @> jsonb_build_array(jsonb_build_object('key', x ->> 'key')) THEN RAISE EXCEPTION 'acceptance record rejected (condition): condition key % is named twice', x ->> 'key' USING ERRCODE = '22023'; END IF;
    v_conditions := v_conditions || jsonb_build_array(jsonb_build_object('key', x ->> 'key', 'text', btrim(x ->> 'text'), 'due', x ->> 'due', 'source', 'proposer'));
  END LOOP;
  FOREACH v_slot IN ARRAY governance.ar_slots(p_kind) LOOP
    IF NOT (v_slot = ANY (v_kinds)) THEN
      v_conditions := v_conditions || jsonb_build_array(jsonb_build_object('key', 'slot:' || v_slot, 'text', format('no current %s evidence was named — an open condition until it is recorded and closed', replace(v_slot, '_', ' ')),
                                                                           'due', least(v_to, v_today + 30), 'source', 'slot', 'slot', v_slot));
    END IF;
  END LOOP;
  IF jsonb_array_length(v_conditions) > 0 AND governance.ar_class_rank(v_scope ->> 'consequence_class') > governance.ar_class_rank('C2') THEN
    RAISE EXCEPTION 'acceptance record rejected (conditional): a conditional acceptance (% open conditions) is consequence-limited to C2 (ES-71-004) — close the conditions or lower the class', jsonb_array_length(v_conditions) USING ERRCODE = '22023';
  END IF;

  -- THE OPERATIONAL PART (ES-71-001, IA-71-002, DP-71-002, DAT-DL-08): owners, open risks, constraints, support model, monitoring, review date, withdrawal criteria
  IF p_kind = 'operational' THEN
    IF jsonb_typeof(p_operational) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'acceptance record rejected (operational): an operational acceptance states its operating terms' USING ERRCODE = '22023'; END IF;
    IF jsonb_typeof(p_operational -> 'owners') <> 'array' OR jsonb_array_length(p_operational -> 'owners') = 0
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_operational -> 'owners') w WHERE length(btrim(coalesce(w ->> 'responsibility', ''))) < 3 OR NOT EXISTS (SELECT 1 FROM identity.roles r WHERE r.code = w ->> 'role')) THEN
      RAISE EXCEPTION 'acceptance record rejected (operational): the owners are a list of {responsibility, role} naming roles of the product' USING ERRCODE = '22023';
    END IF;
    IF jsonb_typeof(p_operational -> 'open_risks') <> 'array' OR jsonb_typeof(p_operational -> 'constraints') <> 'array'
       OR jsonb_typeof(p_operational -> 'withdrawal_criteria') <> 'array' OR jsonb_array_length(p_operational -> 'withdrawal_criteria') = 0 THEN
      RAISE EXCEPTION 'acceptance record rejected (operational): open risks and constraints are lists; the withdrawal criteria are a non-empty list' USING ERRCODE = '22023';
    END IF;
    IF length(btrim(coalesce(p_operational ->> 'monitoring', ''))) < 8 THEN RAISE EXCEPTION 'acceptance record rejected (operational): the monitoring is stated (8+ characters)' USING ERRCODE = '22023'; END IF;
    IF (p_operational ->> 'review_date') IS NULL OR (p_operational ->> 'review_date')::date < v_today OR (p_operational ->> 'review_date')::date > v_to THEN
      RAISE EXCEPTION 'acceptance record rejected (operational): the review date falls within the period' USING ERRCODE = '22023';
    END IF;
    -- the support model: B94's approved responsibility matrix of this profile (referenced, never rewritten); absent → an open condition
    SELECT jsonb_build_object('matrix_id', m.matrix_id, 'version', m.version, 'digest', m.digest, 'profile', m.deployment_profile) INTO v_matrix
      FROM service.responsibility_matrices m WHERE m.tenant_id = p_tenant AND m.domain_id = p_domain AND m.deployment_profile = v_scope ->> 'deployment_profile' AND m.state = 'approved'
     ORDER BY m.version DESC LIMIT 1;
    IF v_matrix IS NULL THEN
      v_conditions := v_conditions || jsonb_build_array(jsonb_build_object('key', 'support_model', 'text', 'no approved responsibility matrix (the support model) for this profile — an open condition', 'due', least(v_to, v_today + 30), 'source', 'slot'));
    END IF;
    v_operational := jsonb_build_object('owners', p_operational -> 'owners', 'open_risks', p_operational -> 'open_risks', 'constraints', p_operational -> 'constraints',
                                        'monitoring', btrim(p_operational ->> 'monitoring'), 'review_date', p_operational ->> 'review_date', 'withdrawal_criteria', p_operational -> 'withdrawal_criteria',
                                        'support_model', v_matrix, 'evidence_versions', (SELECT jsonb_object_agg(i ->> 'evidence_id', i ->> 'digest') FROM jsonb_array_elements(v_items) i));
  ELSIF p_operational IS NOT NULL AND p_operational <> '{}'::jsonb THEN
    RAISE EXCEPTION 'acceptance record rejected (operational): operating terms belong to an operational acceptance' USING ERRCODE = '22023';
  END IF;

  -- THE LINKED EXCEPTIONS (ES-68-004): §PG's registry, read through the shared core; an expired or held one refuses
  FOR x IN SELECT to_jsonb(a) FROM governance.artifacts a WHERE a.artifact_id = ANY (coalesce(p_exceptions, '{}'::uuid[])) AND a.superseded_at IS NULL AND a.kind = 'exception' LOOP
    IF x ->> 'lifecycle' <> 'active' OR coalesce((x -> 'attributes' ->> 'expires_at')::timestamptz, 'infinity'::timestamptz) <= v_now
       OR EXISTS (SELECT 1 FROM governance.holds h WHERE h.lifted_at IS NULL AND h.reason_kind = 'exception_expired' AND (h.source_artifact = (x ->> 'artifact_id')::uuid OR h.subject_artifact = (x ->> 'artifact_id')::uuid)) THEN
      RAISE EXCEPTION 'acceptance record rejected (expired): exception % is % — renew it with current evidence before it is carried into an acceptance', x ->> 'external_key',
        CASE WHEN x ->> 'lifecycle' <> 'active' THEN x ->> 'lifecycle' ELSE 'expired' END USING ERRCODE = '23505';
    END IF;
    v_exceptions := v_exceptions || jsonb_build_array(jsonb_build_object('artifact_id', x -> 'artifact_id', 'key', x -> 'external_key', 'version', x -> 'version', 'digest', x -> 'digest',
                                                                         'expires_at', x -> 'attributes' -> 'expires_at'));
  END LOOP;
  IF jsonb_array_length(v_exceptions) <> cardinality(ARRAY(SELECT DISTINCT unnest(coalesce(p_exceptions, '{}'::uuid[])))) THEN
    RAISE EXCEPTION 'acceptance record rejected (unknown_exception): a named exception is not a current exception of the registry' USING ERRCODE = '23503';
  END IF;

  -- A RELEASE CANDIDATE HELD (an expired exception, a conflict, stale evidence — §PG / §CM) is never accepted (FEX-32, V03-T-453)
  IF p_kind = 'release' THEN
    SELECT jsonb_agg(jsonb_build_object('reason_kind', h.reason_kind, 'reason', h.reason)) INTO v_held FROM governance.holds h WHERE h.subject_artifact = subj.artifact_id AND h.lifted_at IS NULL;
    IF v_held IS NOT NULL THEN
      RAISE EXCEPTION 'acceptance record rejected (held): release candidate % is held — %', subj.external_key, (SELECT string_agg(e ->> 'reason_kind' || ': ' || (e ->> 'reason'), '; ') FROM jsonb_array_elements(v_held) e) USING ERRCODE = '23505';
    END IF;
  END IF;

  -- THE VERSION and THE EXPANSION HOLD (ES-71-004)
  SELECT coalesce(max(r.version), 0) INTO v_cur FROM governance.acceptance_records r WHERE r.record_id = p_record;
  IF EXISTS (SELECT 1 FROM governance.acceptance_records r WHERE r.record_id = p_record AND (r.tenant_id <> p_tenant OR r.domain_id <> p_domain OR r.kind <> p_kind OR r.subject_artifact <> subj.artifact_id)) THEN
    RAISE EXCEPTION 'acceptance record rejected (unknown_record): % is not a % record of % in this domain', p_record, p_kind, p_subject_key USING ERRCODE = '23503';
  END IF;
  IF v_cur IS DISTINCT FROM coalesce(p_expected_version, 0) THEN
    RAISE EXCEPTION 'acceptance record rejected (stale): the record is at version % (expected %)', v_cur, coalesce(p_expected_version::text, '0') USING ERRCODE = '23505';
  END IF;
  SELECT r.record_id INTO v_dup FROM governance.acceptance_records r
   WHERE r.tenant_id = p_tenant AND r.domain_id = p_domain AND r.kind = p_kind AND r.subject_artifact = subj.artifact_id AND r.record_id <> p_record
     AND r.state IN ('proposed', 'accepted', 'constrained', 'suspended', 'lapsed') LIMIT 1;
  IF v_dup IS NOT NULL THEN
    RAISE EXCEPTION 'acceptance record rejected (duplicate): record % already governs % here — propose its next version', v_dup, subj.external_key USING ERRCODE = '23505';
  END IF;
  FOR v_prior IN SELECT r.* FROM governance.acceptance_records r JOIN governance.holds h ON h.source_artifact = r.record_id AND h.lifted_at IS NULL AND h.reason_kind = 'acceptance_constrained'
                  WHERE r.tenant_id = p_tenant AND r.subject_artifact = subj.artifact_id AND r.state IN ('constrained', 'suspended', 'lapsed') LOOP
    IF v_prior.record_id <> p_record THEN
      RAISE EXCEPTION 'acceptance record rejected (held): % is % in another scope (record % — %) — expansion to a new scope is held until it is re-accepted (ES-71-004)',
        subj.external_key, v_prior.state, v_prior.record_id, coalesce((SELECT string_agg(e ->> 'kind', ', ') FROM jsonb_array_elements(v_prior.constrained_reasons) e), 'constrained') USING ERRCODE = '23505';
    END IF;
    v_exp := governance.ar_expansion(v_prior.scope_tuple, v_scope);
    IF jsonb_array_length(v_exp) > 0 THEN
      RAISE EXCEPTION 'acceptance record rejected (held): the re-acceptance of % expands beyond its previously accepted scope (%) — re-accept the accepted scope first (ES-71-004)',
        subj.external_key, (SELECT string_agg(e, ', ') FROM jsonb_array_elements_text(v_exp) e) USING ERRCODE = '23505';
    END IF;
  END LOOP;

  -- THE BUILDERS (never attesters): declared, the subject's declared builders, the recorders of its build and test evidence
  v_builders := ARRAY(SELECT DISTINCT b FROM unnest(coalesce(p_builders, '{}'::uuid[])
                        || ARRAY(SELECT (j #>> '{}')::uuid FROM jsonb_array_elements(coalesce(subj.attributes -> 'builders', '[]'::jsonb)) j WHERE (j #>> '{}') ~ '^[0-9a-f-]{36}$')
                        || ARRAY(SELECT (i ->> 'recorded_by')::uuid FROM jsonb_array_elements(v_items) i WHERE i ->> 'kind' IN ('build', 'test_report', 'release_candidate'))) b ORDER BY 1);

  v_version := v_cur + 1;
  v_digest := governance.digest(jsonb_build_object('record_id', p_record, 'version', v_version, 'kind', p_kind, 'title', btrim(p_title), 'subject', jsonb_build_object('artifact_id', subj.artifact_id,
                'version', subj.version, 'key', subj.external_key, 'digest', subj.digest), 'scope', v_scope, 'obligations', to_jsonb(v_obligations), 'evidence', v_items,
                'conditions', v_conditions, 'exceptions', v_exceptions, 'operational', v_operational, 'builders', to_jsonb(v_builders), 'claim', 'demonstration'));
  UPDATE governance.acceptance_records SET state = 'superseded', ended_by = p_actor, ended_at = v_now, end_reason = format('superseded by proposed version %s', v_version)
   WHERE record_id = p_record AND state IN ('proposed', 'withheld');
  INSERT INTO governance.acceptance_records (record_id, version, tenant_id, domain_id, kind, title, subject_artifact, subject_key, subject_digest, scope_tuple, obligations, evidence,
                                            conditions, exceptions, operational, builders, digest, proposed_by, correlation_id)
  VALUES (p_record, v_version, p_tenant, p_domain, p_kind, btrim(p_title), subj.artifact_id, subj.external_key, subj.digest, v_scope, v_obligations, v_items, v_conditions, v_exceptions,
          v_operational, v_builders, v_digest, p_actor, p_correlation);

  -- the shared core: the record is an artifact; it covers its subject; its evidence evidences it; its exceptions except it
  PERFORM governance._ar_artifact(p_record, p_tenant, p_domain, 'acceptance_record', 'ACC-' || p_record::text, btrim(p_title) || ' (claim: demonstration)', 'proposed',
                                  jsonb_build_object('kind', p_kind, 'version', v_version, 'subject', subj.external_key, 'state', 'proposed', 'claim', 'demonstration'),
                                  governance.digest(jsonb_build_object('record', v_digest, 'state', 'proposed')), p_actor, p_correlation);
  PERFORM governance._ar_link(p_tenant, p_domain, p_record, subj.artifact_id, 'covers', jsonb_build_object('kind', p_kind), p_actor, p_correlation);
  FOR x IN SELECT * FROM jsonb_array_elements(v_items) LOOP
    PERFORM governance._ar_link(p_tenant, p_domain, (x ->> 'evidence_id')::uuid, p_record, 'evidences', jsonb_build_object('version', v_version), p_actor, p_correlation);
  END LOOP;
  FOR x IN SELECT * FROM jsonb_array_elements(v_exceptions) LOOP
    PERFORM governance._ar_link(p_tenant, p_domain, (x ->> 'artifact_id')::uuid, p_record, 'excepts', jsonb_build_object('version', v_version), p_actor, p_correlation);
  END LOOP;

  -- the attestations awaited: one governance.attest task per obligation (candidate roles; the port decides who)
  FOREACH o IN ARRAY v_obligations LOOP
    v_task := executive._open_human_task(gen_random_uuid(), p_tenant, p_domain, 'governance.attest', format('attest:%s:%s:%s', p_record, v_version, o),
                jsonb_build_object('kind', 'acceptance_record', 'id', p_record, 'version', v_version, 'obligation', o),
                format('Attest the %s obligation of "%s" v%s', replace(o, '_', ' '), btrim(p_title), v_version), NULL, governance.ar_obligation_roles(o),
                jsonb_build_object('rule', 'a named human holding the obligation''s role; never the proposer, never a builder, never an agent; one person per obligation'),
                NULL, '{}'::jsonb, NULL, NULL, p_actor, p_correlation);
    v_tasks := v_tasks || jsonb_build_array(jsonb_build_object('obligation', o, 'task_id', v_task -> 'task_id'));
  END LOOP;
  PERFORM governance.ledger(p_tenant, p_domain, 'acceptance_record', p_record, v_version, 'acceptance.proposed', p_actor,
                            jsonb_build_object('kind', p_kind, 'subject', subj.external_key, 'digest', v_digest, 'obligations', to_jsonb(v_obligations),
                                               'evidence', (SELECT jsonb_agg(i -> 'evidence_id') FROM jsonb_array_elements(v_items) i), 'conditions', jsonb_array_length(v_conditions),
                                               'exceptions', jsonb_array_length(v_exceptions), 'claim', 'demonstration'), p_correlation);
  RETURN jsonb_build_object('record_id', p_record, 'version', v_version, 'state', 'proposed', 'kind', p_kind, 'digest', v_digest, 'scope', v_scope, 'obligations', to_jsonb(v_obligations),
                            'evidence', v_items, 'conditions', v_conditions, 'exceptions', v_exceptions, 'operational', v_operational, 'builders', to_jsonb(v_builders), 'tasks', v_tasks,
                            'claim', 'demonstration', 'real_acceptance', 'R2: acceptance by named independent and customer authorities is external');
END $$;
REVOKE ALL ON FUNCTION governance.ar_propose(uuid, uuid, uuid, text, text, text, jsonb, text[], uuid[], jsonb, uuid[], jsonb, uuid[], int, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_propose(uuid, uuid, uuid, text, text, text, jsonb, text[], uuid[], jsonb, uuid[], jsonb, uuid[], int, uuid, uuid) TO eye_commit;

-- §AR.6 VERIFY (the customer) AND ATTEST (each obligation) ──────────────────────────────────────────────────────────────────────────────
/* The customer VERIFIES a proposed version against its own scope (JRN-24's customer-verify stage) — governance.acceptance.verify: a named
   human customer sponsor or onboarding authority of THIS tenant, never the proposer or a builder, on the exact digest. */
CREATE OR REPLACE FUNCTION governance.ar_verify(p_record uuid, p_version int, p_tenant uuid, p_domain uuid, p_digest text, p_outcome text, p_findings text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE r governance.acceptance_records%ROWTYPE; v uuid := gen_random_uuid();
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.acceptance.verify']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  PERFORM governance._ar_actor('acceptance attestation', p_actor);
  SELECT * INTO r FROM governance.acceptance_records x WHERE x.record_id = p_record AND x.version = p_version AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'acceptance attestation rejected (unknown_record): no acceptance record %/v% in this domain', p_record, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('acceptance attestation', p_actor, p_tenant, p_domain, ARRAY['customer_sponsor', 'onboarding_authority'], r.proposed_by, r.builders, 'the customer''s verification');
  IF NOT EXISTS (SELECT 1 FROM identity.principals x WHERE x.id = p_actor AND x.tenant_id = p_tenant) THEN
    RAISE EXCEPTION 'acceptance attestation rejected (authority): the customer''s verification is a member of the customer''s own tenant' USING ERRCODE = '42501';
  END IF;
  IF r.state <> 'proposed' THEN RAISE EXCEPTION 'acceptance attestation rejected (state): version % is %', p_version, r.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM r.digest THEN RAISE EXCEPTION 'acceptance attestation rejected (stale): the verification names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF p_outcome NOT IN ('verified', 'not_verified') THEN RAISE EXCEPTION 'acceptance attestation rejected (outcome): verified or not_verified' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_findings, ''))) < 8 THEN RAISE EXCEPTION 'acceptance attestation rejected (findings): the verification states its findings (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM governance.acceptance_verifications x WHERE x.record_id = p_record AND x.version = p_version) THEN
    RAISE EXCEPTION 'acceptance attestation rejected (duplicate): version % is already verified by the customer', p_version USING ERRCODE = '23505';
  END IF;
  INSERT INTO governance.acceptance_verifications (verification_id, tenant_id, domain_id, record_id, version, record_digest, outcome, findings, verifier, correlation_id)
  VALUES (v, p_tenant, p_domain, p_record, p_version, r.digest, p_outcome, btrim(p_findings), p_actor, p_correlation);
  PERFORM governance.ledger(p_tenant, p_domain, 'acceptance_record', p_record, p_version, 'acceptance.' || p_outcome, p_actor, jsonb_build_object('verification_id', v, 'digest', r.digest), p_correlation);
  RETURN jsonb_build_object('verification_id', v, 'record_id', p_record, 'version', p_version, 'outcome', p_outcome, 'digest', r.digest, 'claim', 'demonstration');
END $$;
REVOKE ALL ON FUNCTION governance.ar_verify(uuid, int, uuid, uuid, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_verify(uuid, int, uuid, uuid, text, text, text, uuid, uuid) TO eye_commit;

/* ATTEST (or WITHHOLD) one obligation of a proposed version — governance.acceptance.attest (human-gated): THE APPROVER TEST (a named active
   human holding the obligation's role; never the proposer, never a builder, never an agent), ONE PERSON PER OBLIGATION, the exact digest, the
   evidence still current, the exceptions unexpired, a release candidate unheld, the customer's verification before the customer attests; an
   attestation carries the attester's signature over the digest (executive.signatures acceptance_attestation, bound to this action). The LAST
   attestation ACCEPTS: the record in force for exactly its scope, the prior version superseded, the expansion hold LIFTED, the next expiry
   TIMER scheduled. A withholding ends the version (withheld) with its reason. */
CREATE OR REPLACE FUNCTION governance.ar_attest(p_record uuid, p_version int, p_tenant uuid, p_domain uuid, p_obligation text, p_decision text, p_digest text, p_reason text,
                                                p_signature uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE
  r governance.acceptance_records%ROWTYPE; v_now timestamptz := clock_timestamp(); v_role text; v_att uuid := gen_random_uuid(); v_missing text[]; x jsonb;
  v_state text := 'proposed'; v_lifted jsonb := '[]'::jsonb; v_closed jsonb; v_next timestamptz; v_timer uuid; v_held text; v_roles int; v_prior int;
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.acceptance.attest']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  PERFORM governance._ar_actor('acceptance attestation', p_actor);
  SELECT * INTO r FROM governance.acceptance_records x2 WHERE x2.record_id = p_record AND x2.version = p_version AND x2.tenant_id = p_tenant AND x2.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'acceptance attestation rejected (unknown_record): no acceptance record %/v% in this domain', p_record, p_version USING ERRCODE = '23503'; END IF;
  IF p_obligation IS NULL OR NOT (p_obligation = ANY (r.obligations)) THEN
    RAISE EXCEPTION 'acceptance attestation rejected (obligation): % is not an obligation of version % (%)', coalesce(p_obligation, '<none>'), p_version, array_to_string(r.obligations, ', ') USING ERRCODE = '22023';
  END IF;
  PERFORM governance.assert_approver('acceptance attestation', p_actor, p_tenant, p_domain, governance.ar_obligation_roles(p_obligation), r.proposed_by, r.builders,
                                     format('attesting the %s obligation', replace(p_obligation, '_', ' ')));
  IF p_obligation = 'customer' AND NOT EXISTS (SELECT 1 FROM identity.principals x2 WHERE x2.id = p_actor AND x2.tenant_id = p_tenant) THEN
    RAISE EXCEPTION 'acceptance attestation rejected (authority): the customer''s obligation is attested by a member of the customer''s own tenant' USING ERRCODE = '42501';
  END IF;
  IF r.state <> 'proposed' THEN RAISE EXCEPTION 'acceptance attestation rejected (state): version % is %', p_version, r.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM r.digest THEN RAISE EXCEPTION 'acceptance attestation rejected (stale): the attestation names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF p_decision NOT IN ('attest', 'withhold') THEN RAISE EXCEPTION 'acceptance attestation rejected (decision): attest or withhold' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'acceptance attestation rejected (reason): an attestation states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM governance.acceptance_attestations a WHERE a.record_id = p_record AND a.version = p_version AND a.obligation = p_obligation) THEN
    RAISE EXCEPTION 'acceptance attestation rejected (duplicate): the % obligation of version % is already attested', p_obligation, p_version USING ERRCODE = '23505';
  END IF;
  IF EXISTS (SELECT 1 FROM governance.acceptance_attestations a WHERE a.record_id = p_record AND a.version = p_version AND a.attester = p_actor) THEN
    RAISE EXCEPTION 'acceptance attestation rejected (separation_of_duties): one named human attests ONE obligation — no single person accepts on behalf of the independent authorities (ES-71-002)' USING ERRCODE = '42501';
  END IF;
  SELECT b.role_code INTO v_role FROM identity.role_bindings b WHERE b.principal_id = p_actor AND b.revoked_at IS NULL AND b.role_code = ANY (governance.ar_obligation_roles(p_obligation))
     AND (b.scope = 'PLATFORM' OR (b.scope = 'TENANT' AND b.tenant_id = p_tenant) OR (b.scope = 'DOMAIN' AND b.domain_id = p_domain)) ORDER BY b.role_code LIMIT 1;

  IF p_decision = 'withhold' THEN
    INSERT INTO governance.acceptance_attestations (attestation_id, tenant_id, domain_id, record_id, version, obligation, decision, attester, attester_role, record_digest, reason, correlation_id)
    VALUES (v_att, p_tenant, p_domain, p_record, p_version, p_obligation, 'withhold', p_actor, v_role, r.digest, btrim(p_reason), p_correlation);
    UPDATE governance.acceptance_records SET state = 'withheld', ended_by = p_actor, ended_at = v_now, end_reason = format('the %s obligation was withheld: %s', p_obligation, btrim(p_reason))
     WHERE record_id = p_record AND version = p_version;
    PERFORM executive._resolve_human_tasks(p_tenant, p_domain, jsonb_build_object('kind', 'acceptance_record', 'id', p_record, 'version', p_version), ARRAY['governance.attest'], 'withheld', v_att, p_actor, p_correlation);
    PERFORM governance._ar_artifact(p_record, p_tenant, p_domain, 'acceptance_record', 'ACC-' || p_record::text, r.title || ' (claim: demonstration)', 'retired',
                                    jsonb_build_object('kind', r.kind, 'version', p_version, 'subject', r.subject_key, 'state', 'withheld', 'claim', 'demonstration'),
                                    governance.digest(jsonb_build_object('record', r.digest, 'state', 'withheld')), p_actor, p_correlation);
    PERFORM governance.ledger(p_tenant, p_domain, 'acceptance_record', p_record, p_version, 'acceptance.withheld', p_actor,
                              jsonb_build_object('obligation', p_obligation, 'reason', btrim(p_reason), 'attestation_id', v_att), p_correlation);
    RETURN jsonb_build_object('record_id', p_record, 'version', p_version, 'state', 'withheld', 'obligation', p_obligation, 'attestation_id', v_att,
                              'unmet', to_jsonb(r.obligations), 'claim', 'demonstration');
  END IF;

  -- ATTEST: the evidence current, the exceptions unexpired, the release candidate unheld, the customer's verification before the customer
  FOR x IN SELECT * FROM jsonb_array_elements(r.evidence) LOOP
    IF EXISTS (SELECT 1 FROM governance.acceptance_evidence e WHERE e.evidence_id = (x ->> 'evidence_id')::uuid AND (e.valid_until <= v_now OR e.outcome = 'failed'))
       OR EXISTS (SELECT 1 FROM governance.acceptance_evidence f WHERE f.renews = (x ->> 'evidence_id')::uuid AND f.outcome = 'failed') THEN
      RAISE EXCEPTION 'acceptance attestation rejected (stale): evidence % (%) is no longer current — renew it and propose a new version', x ->> 'evidence_id', x ->> 'kind' USING ERRCODE = '23505';
    END IF;
  END LOOP;
  FOR x IN SELECT * FROM jsonb_array_elements(r.exceptions) LOOP
    IF NOT EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.artifact_id = (x ->> 'artifact_id')::uuid AND a.superseded_at IS NULL AND a.lifecycle = 'active'
                    AND coalesce((a.attributes ->> 'expires_at')::timestamptz, 'infinity'::timestamptz) > v_now)
       OR EXISTS (SELECT 1 FROM governance.holds h WHERE h.lifted_at IS NULL AND h.reason_kind = 'exception_expired' AND (h.source_artifact = (x ->> 'artifact_id')::uuid OR h.subject_artifact = (x ->> 'artifact_id')::uuid)) THEN
      RAISE EXCEPTION 'acceptance attestation rejected (expired): linked exception % expired — it is renewed with current evidence first', x ->> 'key' USING ERRCODE = '23505';
    END IF;
  END LOOP;
  IF r.kind = 'release' THEN
    SELECT string_agg(h.reason_kind || ': ' || h.reason, '; ') INTO v_held FROM governance.holds h WHERE h.subject_artifact = r.subject_artifact AND h.lifted_at IS NULL;
    IF v_held IS NOT NULL THEN RAISE EXCEPTION 'acceptance attestation rejected (held): release candidate % is held — %', r.subject_key, v_held USING ERRCODE = '23505'; END IF;
  END IF;
  IF p_obligation = 'customer' AND NOT EXISTS (SELECT 1 FROM governance.acceptance_verifications v WHERE v.record_id = p_record AND v.version = p_version AND v.outcome = 'verified') THEN
    RAISE EXCEPTION 'acceptance attestation rejected (state): the customer VERIFIES version % before attesting it (JRN-24: customer verify → attest)', p_version USING ERRCODE = '23505';
  END IF;
  IF p_signature IS NULL OR NOT EXISTS (SELECT 1 FROM executive.signatures s WHERE s.signature_id = p_signature AND s.subject_kind = 'acceptance_attestation' AND s.subject_id = p_record
                                                AND s.subject_version = p_version AND s.subject_digest = r.digest AND s.signer = p_actor AND s.bound_action = 'governance.acceptance.attest') THEN
    RAISE EXCEPTION 'acceptance attestation rejected (signature): an attestation carries the attester''s signature over the version''s digest' USING ERRCODE = '22023';
  END IF;
  INSERT INTO governance.acceptance_attestations (attestation_id, tenant_id, domain_id, record_id, version, obligation, decision, attester, attester_role, record_digest, signature_id, reason, correlation_id)
  VALUES (v_att, p_tenant, p_domain, p_record, p_version, p_obligation, 'attest', p_actor, v_role, r.digest, p_signature, btrim(p_reason), p_correlation);
  PERFORM executive._resolve_human_tasks(p_tenant, p_domain, jsonb_build_object('kind', 'acceptance_record', 'id', p_record, 'version', p_version, 'obligation', p_obligation),
                                         ARRAY['governance.attest'], 'attested', v_att, p_actor, p_correlation);
  PERFORM governance.ledger(p_tenant, p_domain, 'acceptance_record', p_record, p_version, 'acceptance.attested', p_actor,
                            jsonb_build_object('obligation', p_obligation, 'role', v_role, 'signature_id', p_signature, 'attestation_id', v_att), p_correlation);

  v_missing := ARRAY(SELECT o FROM unnest(r.obligations) o WHERE NOT EXISTS (SELECT 1 FROM governance.acceptance_attestations a WHERE a.record_id = p_record AND a.version = p_version AND a.obligation = o AND a.decision = 'attest'));
  IF cardinality(v_missing) = 0 THEN
    SELECT count(DISTINCT a.attester_role) INTO v_roles FROM governance.acceptance_attestations a WHERE a.record_id = p_record AND a.version = p_version AND a.decision = 'attest';
    IF v_roles < 2 THEN
      RAISE EXCEPTION 'acceptance attestation rejected (separation_of_duties): one role never accepts every obligation (ES-71-002)' USING ERRCODE = '42501';
    END IF;
    -- ACCEPTED: exactly this scope; the prior version superseded; the expansion hold lifted; the attention closed; the next expiry timer
    SELECT count(*) INTO v_prior FROM governance.acceptance_records p WHERE p.record_id = p_record AND p.version <> p_version AND p.state IN ('accepted', 'constrained', 'suspended', 'lapsed');
    UPDATE governance.acceptance_records SET state = 'superseded', ended_by = p_actor, ended_at = v_now, end_reason = format('re-accepted as version %s over renewed evidence', p_version)
     WHERE record_id = p_record AND version <> p_version AND state IN ('accepted', 'constrained', 'suspended', 'lapsed');
    v_state := 'accepted';
    SELECT min(t) INTO v_next FROM (
      SELECT (e ->> 'valid_until')::timestamptz AS t FROM jsonb_array_elements(r.evidence) e
      UNION ALL SELECT ((c ->> 'due')::date + 1)::timestamptz FROM jsonb_array_elements(r.conditions) c
      UNION ALL SELECT ((r.scope_tuple -> 'period' ->> 'to')::date + 1)::timestamptz
      UNION ALL SELECT ((r.operational ->> 'review_date')::date + 1)::timestamptz WHERE r.operational IS NOT NULL) s;
    v_timer := executive._schedule_timer(gen_random_uuid(), p_tenant, p_domain, 'acceptance_record', p_record, 'acceptance.evidence_expiry', greatest(v_next, v_now),
                                         jsonb_build_object('version', p_version, 'digest', r.digest), p_actor, p_correlation);
    UPDATE governance.acceptance_records SET state = 'accepted', accepted_at = v_now, effective_scope = r.scope_tuple, expiry_timer_id = v_timer WHERE record_id = p_record AND version = p_version;
    WITH l AS (UPDATE governance.holds h SET lifted_at = v_now, lifted_by = p_actor, lift_reason = format('re-accepted: version %s accepted over renewed evidence by every obligation', p_version)
                WHERE h.source_artifact = p_record AND h.lifted_at IS NULL AND h.reason_kind = 'acceptance_constrained' RETURNING h.hold_id)
    SELECT coalesce(jsonb_agg(l.hold_id), '[]'::jsonb) INTO v_lifted FROM l;
    v_closed := executive.b33_close_items(p_tenant, p_domain, 'governance.acceptance', 'acceptance_record', p_record, format('version %s accepted for its exact scope', p_version), p_actor, p_correlation);
    PERFORM governance._ar_artifact(p_record, p_tenant, p_domain, 'acceptance_record', 'ACC-' || p_record::text, r.title || ' (claim: demonstration)', 'active',
                                    jsonb_build_object('kind', r.kind, 'version', p_version, 'subject', r.subject_key, 'state', 'accepted', 'claim', 'demonstration'),
                                    governance.digest(jsonb_build_object('record', r.digest, 'state', 'accepted')), p_actor, p_correlation);
    PERFORM governance.ledger(p_tenant, p_domain, 'acceptance_record', p_record, p_version, CASE WHEN v_prior > 0 THEN 'acceptance.reaccepted' ELSE 'acceptance.accepted' END, p_actor,
                              jsonb_build_object('digest', r.digest, 'scope', r.scope_tuple, 'holds_lifted', v_lifted, 'items_closed', v_closed, 'timer_id', v_timer, 'next_check', v_next,
                                                 'claim', 'demonstration'), p_correlation);
  END IF;
  RETURN jsonb_build_object('record_id', p_record, 'version', p_version, 'state', v_state, 'obligation', p_obligation, 'attestation_id', v_att, 'signature_id', p_signature,
                            'unmet', to_jsonb(v_missing), 'holds_lifted', v_lifted, 'claim', 'demonstration',
                            'real_acceptance', 'R2: acceptance by named independent and customer authorities is external');
END $$;
REVOKE ALL ON FUNCTION governance.ar_attest(uuid, int, uuid, uuid, text, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_attest(uuid, int, uuid, uuid, text, text, text, text, uuid, uuid, uuid) TO eye_commit;

-- §AR.7 THE RECONCILIATION SWEEP (evidence expiry and everything else a record in force declared) ─────────────────────────────────────────
/* What a record in force no longer meets, read from facts (IA-71-002, DP-71-002 "continuously reconcile"): expired or failed evidence (with
   what each covers), overdue conditions, a passed review date, the end of the period, a changed subject, an expired linked exception, a held
   release candidate. Read-only. */
CREATE OR REPLACE FUNCTION governance.ar_findings(p_record uuid, p_version int) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE r governance.acceptance_records%ROWTYPE; v_now timestamptz := clock_timestamp(); v_today date := (clock_timestamp() AT TIME ZONE 'UTC')::date; v jsonb := '[]'::jsonb; x jsonb; e governance.acceptance_evidence%ROWTYPE;
BEGIN
  SELECT * INTO r FROM governance.acceptance_records a WHERE a.record_id = p_record AND a.version = p_version;
  IF NOT FOUND THEN RETURN '[]'::jsonb; END IF;
  PERFORM observation.assert_read_scope(r.tenant_id, r.domain_id, 'an acceptance record''s findings');
  FOR x IN SELECT * FROM jsonb_array_elements(r.evidence) LOOP
    SELECT * INTO e FROM governance.acceptance_evidence a WHERE a.evidence_id = (x ->> 'evidence_id')::uuid;
    IF e.valid_until <= v_now THEN
      v := v || jsonb_build_array(jsonb_build_object('kind', 'evidence_expired', 'ref', e.evidence_id, 'evidence_kind', e.kind, 'title', e.title, 'valid_until', e.valid_until, 'covers', e.covers));
    ELSIF e.outcome = 'failed' OR EXISTS (SELECT 1 FROM governance.acceptance_evidence f WHERE f.renews = e.evidence_id AND f.outcome = 'failed') THEN
      v := v || jsonb_build_array(jsonb_build_object('kind', 'evidence_failed', 'ref', e.evidence_id, 'evidence_kind', e.kind, 'title', e.title, 'covers', e.covers,
                                                     'failure', (SELECT f.evidence_id FROM governance.acceptance_evidence f WHERE f.renews = e.evidence_id AND f.outcome = 'failed' LIMIT 1)));
    END IF;
  END LOOP;
  FOR x IN SELECT * FROM jsonb_array_elements(r.conditions) LOOP
    IF (x ->> 'due')::date < v_today AND NOT EXISTS (SELECT 1 FROM governance.acceptance_condition_events c WHERE c.record_id = p_record AND c.version = p_version AND c.condition_key = x ->> 'key') THEN
      v := v || jsonb_build_array(jsonb_build_object('kind', 'condition_overdue', 'ref', x ->> 'key', 'due', x ->> 'due', 'text', x ->> 'text'));
    END IF;
  END LOOP;
  IF r.operational IS NOT NULL AND (r.operational ->> 'review_date')::date < v_today THEN
    v := v || jsonb_build_array(jsonb_build_object('kind', 'review_due', 'ref', 'review_date', 'due', r.operational ->> 'review_date'));
  END IF;
  IF (r.scope_tuple -> 'period' ->> 'to')::date < v_today THEN
    v := v || jsonb_build_array(jsonb_build_object('kind', 'period_ended', 'ref', 'period', 'ended', r.scope_tuple -> 'period' ->> 'to'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.artifact_id = r.subject_artifact AND a.superseded_at IS NULL AND a.digest = r.subject_digest AND a.lifecycle IN ('active', 'proposed')) THEN
    v := v || jsonb_build_array(jsonb_build_object('kind', 'capability_changed', 'ref', r.subject_key, 'accepted_digest', r.subject_digest,
                                                   'current', (SELECT jsonb_build_object('version', a.version, 'digest', a.digest, 'lifecycle', a.lifecycle) FROM governance.artifacts a WHERE a.artifact_id = r.subject_artifact AND a.superseded_at IS NULL)));
  END IF;
  FOR x IN SELECT * FROM jsonb_array_elements(r.exceptions) LOOP
    IF NOT EXISTS (SELECT 1 FROM governance.artifacts a WHERE a.artifact_id = (x ->> 'artifact_id')::uuid AND a.superseded_at IS NULL AND a.lifecycle = 'active'
                    AND coalesce((a.attributes ->> 'expires_at')::timestamptz, 'infinity'::timestamptz) > v_now)
       OR EXISTS (SELECT 1 FROM governance.holds h WHERE h.lifted_at IS NULL AND h.reason_kind = 'exception_expired' AND (h.source_artifact = (x ->> 'artifact_id')::uuid OR h.subject_artifact = (x ->> 'artifact_id')::uuid)) THEN
      v := v || jsonb_build_array(jsonb_build_object('kind', 'exception_expired', 'ref', x ->> 'key'));
    END IF;
  END LOOP;
  IF r.kind = 'release' AND EXISTS (SELECT 1 FROM governance.holds h WHERE h.subject_artifact = r.subject_artifact AND h.lifted_at IS NULL) THEN
    v := v || jsonb_build_array(jsonb_build_object('kind', 'release_held', 'ref', r.subject_key,
                                                   'holds', (SELECT jsonb_agg(h.reason_kind) FROM governance.holds h WHERE h.subject_artifact = r.subject_artifact AND h.lifted_at IS NULL)));
  END IF;
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.ar_findings(uuid, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_findings(uuid, int) TO eye_app, eye_commit;

/* Apply a record's findings (internal; the sweep, the timer and the trigger act call it inside their own governed write): nothing written when
   nothing is new. An ACCEPTED record with findings turns CONSTRAINED (the effective scope = the accepted scope minus what the affected items
   cover — FEX-31), a passed period LAPSES it; the hold on EXPANSION is opened once; attention `governance.acceptance` is raised; a trigger row
   per new finding; the ledger. */
CREATE OR REPLACE FUNCTION governance._ar_constrain(p_record uuid, p_version int, p_findings jsonb, p_source text, p_policy text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE
  r governance.acceptance_records%ROWTYPE; v_now timestamptz := clock_timestamp(); v_new jsonb := '[]'::jsonb; x jsonb; v_state text; v_eff jsonb; v_hold uuid; v_item jsonb := NULL;
  v_first uuid; v_trig uuid; v_all jsonb;
BEGIN
  SELECT * INTO r FROM governance.acceptance_records a WHERE a.record_id = p_record AND a.version = p_version FOR UPDATE;
  IF NOT FOUND OR r.state NOT IN ('accepted', 'constrained', 'suspended', 'lapsed') THEN RETURN NULL; END IF;
  FOR x IN SELECT * FROM jsonb_array_elements(coalesce(p_findings, '[]'::jsonb)) LOOP
    IF NOT (r.constrained_reasons @> jsonb_build_array(jsonb_build_object('kind', x ->> 'kind', 'ref', x ->> 'ref'))) THEN v_new := v_new || jsonb_build_array(x); END IF;
  END LOOP;
  v_state := CASE WHEN r.state = 'lapsed' OR p_policy = 'lapse' OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_findings) f WHERE f ->> 'kind' = 'period_ended') THEN 'lapsed'
                  WHEN r.state = 'suspended' OR p_policy = 'suspend' THEN 'suspended' ELSE 'constrained' END;
  IF jsonb_array_length(v_new) = 0 AND v_state = r.state THEN RETURN NULL; END IF;
  v_all := r.constrained_reasons || v_new;
  v_eff := CASE WHEN v_state IN ('lapsed', 'suspended') THEN NULL
                ELSE governance.ar_effective_scope(r.scope_tuple, (SELECT coalesce(jsonb_agg(f), '[]'::jsonb) FROM jsonb_array_elements(v_all) f WHERE f ->> 'kind' IN ('evidence_expired', 'evidence_failed'))) END;
  UPDATE governance.acceptance_records SET state = v_state, constrained_at = coalesce(constrained_at, v_now), constrained_reasons = v_all, effective_scope = v_eff
   WHERE record_id = p_record AND version = p_version;
  FOR x IN SELECT * FROM jsonb_array_elements(v_new) LOOP
    v_trig := gen_random_uuid(); v_first := coalesce(v_first, v_trig);
    INSERT INTO governance.acceptance_triggers (trigger_id, tenant_id, domain_id, record_id, version, kind, policy, detail, source, raised_by, correlation_id)
    VALUES (v_trig, r.tenant_id, r.domain_id, p_record, p_version, x ->> 'kind',
            CASE WHEN x ->> 'kind' = 'period_ended' THEN 'lapse' WHEN v_state = 'suspended' THEN 'suspend' ELSE 'review' END, x, p_source, p_actor, p_correlation);
  END LOOP;
  SELECT h.hold_id INTO v_hold FROM governance.holds h WHERE h.source_artifact = p_record AND h.lifted_at IS NULL AND h.reason_kind = 'acceptance_constrained' LIMIT 1;
  IF v_hold IS NULL THEN
    v_hold := gen_random_uuid();
    INSERT INTO governance.holds (hold_id, scope, tenant_id, domain_id, subject_artifact, reason_kind, source_artifact, reason, opened_by, correlation_id)
    VALUES (v_hold, 'DOMAIN', r.tenant_id, r.domain_id, r.subject_artifact, 'acceptance_constrained', p_record,
            format('%s is %s in this scope (%s) — expansion to a new domain, tenant, journey, role, profile, data, model or a higher consequence class is held until re-acceptance over renewed evidence',
                   r.subject_key, v_state, (SELECT string_agg(DISTINCT f ->> 'kind', ', ') FROM jsonb_array_elements(v_all) f)), p_actor, p_correlation);
  END IF;
  IF jsonb_array_length(v_new) > 0 THEN
    v_item := executive.b33_raise_routed(r.tenant_id, r.domain_id, 'governance.acceptance', 'acceptance_record', p_record,
                format('%s is %s: %s', r.subject_key, upper(v_state), (SELECT string_agg(f ->> 'kind' || coalesce(' ' || (f ->> 'evidence_kind'), ''), '; ') FROM jsonb_array_elements(v_new) f)),
                (SELECT jsonb_agg(f ->> 'kind') FROM jsonb_array_elements(v_new) f), NULL, v_first, 'governance.acceptance.' || v_state,
                jsonb_build_object('record_id', p_record, 'version', p_version, 'findings', v_new, 'hold_id', v_hold),
                jsonb_build_object('consequence', r.scope_tuple ->> 'consequence_class'), p_actor, p_correlation);
  END IF;
  PERFORM governance._ar_artifact(p_record, r.tenant_id, r.domain_id, 'acceptance_record', 'ACC-' || p_record::text, r.title || ' (claim: demonstration)', 'active',
                                  jsonb_build_object('kind', r.kind, 'version', p_version, 'subject', r.subject_key, 'state', v_state, 'claim', 'demonstration'),
                                  governance.digest(jsonb_build_object('record', r.digest, 'state', v_state)), p_actor, p_correlation);
  PERFORM governance.ledger(r.tenant_id, r.domain_id, 'acceptance_record', p_record, p_version, 'acceptance.' || v_state, p_actor,
                            jsonb_build_object('findings', v_new, 'effective_scope', v_eff, 'hold_id', v_hold, 'source', p_source, 'attention', v_item), p_correlation);
  RETURN jsonb_build_object('record_id', p_record, 'version', p_version, 'from', r.state, 'state', v_state, 'new_findings', v_new, 'effective_scope', v_eff, 'hold_id', v_hold, 'attention', v_item);
END $$;
REVOKE ALL ON FUNCTION governance._ar_constrain(uuid, int, jsonb, text, text, uuid, uuid) FROM PUBLIC;

/* THE SWEEP — the attention tick's step `acceptance-evidence-expiry` (bound to executive.attention.tick) or an explicit run
   (governance.acceptance.sweep): every record in force of the domain reconciled; reads first (the findings), then the writes. */
CREATE OR REPLACE FUNCTION governance.ar_sweep(p_tenant uuid, p_domain uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE r record; v_found jsonb := '[]'::jsonb; x jsonb; v_out jsonb := '[]'::jsonb; v jsonb; v_checked int := 0;
BEGIN
  PERFORM observation.assert_authority(ARRAY['executive.attention.tick', 'governance.acceptance.sweep']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  PERFORM governance._ar_actor('acceptance record', p_actor);
  FOR r IN SELECT a.record_id, a.version FROM governance.acceptance_records a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.state IN ('accepted', 'constrained', 'suspended', 'lapsed')
            ORDER BY a.accepted_at, a.record_id LOOP
    v_checked := v_checked + 1;
    v_found := v_found || jsonb_build_array(jsonb_build_object('record_id', r.record_id, 'version', r.version, 'findings', governance.ar_findings(r.record_id, r.version)));
  END LOOP;
  FOR x IN SELECT * FROM jsonb_array_elements(v_found) LOOP
    IF jsonb_array_length(x -> 'findings') > 0 THEN
      v := governance._ar_constrain((x ->> 'record_id')::uuid, (x ->> 'version')::int, x -> 'findings', 'sweep', 'review', p_actor, p_correlation);
      IF v IS NOT NULL THEN v_out := v_out || jsonb_build_array(v); END IF;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('checked', v_checked, 'changed', v_out);
END $$;
REVOKE ALL ON FUNCTION governance.ar_sweep(uuid, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_sweep(uuid, uuid, uuid, uuid) TO eye_commit;

/* THE TIMER (acceptance.evidence_expiry, fired by the tick's workflow-timers step): the owning record reconciled now; while it stays accepted
   the next instant is scheduled (the earliest remaining expiry, due day, review date or period end). */
CREATE OR REPLACE FUNCTION governance.ar_timer(p_timer uuid, p_tenant uuid, p_domain uuid, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE t executive.workflow_timers%ROWTYPE; r governance.acceptance_records%ROWTYPE; v jsonb; v_next timestamptz; v_now timestamptz := clock_timestamp(); v_timer uuid; v_findings jsonb;
BEGIN
  PERFORM observation.assert_authority(ARRAY['executive.attention.tick']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  PERFORM governance._ar_actor('acceptance record', p_actor);
  SELECT * INTO t FROM executive.workflow_timers x WHERE x.timer_id = p_timer AND x.tenant_id = p_tenant AND x.domain_id = p_domain AND x.owner_kind = 'acceptance_record';
  IF NOT FOUND THEN RAISE EXCEPTION 'acceptance record rejected (unknown_timer): % is not an acceptance timer of this domain', p_timer USING ERRCODE = '23503'; END IF;
  SELECT * INTO r FROM governance.acceptance_records a WHERE a.record_id = t.owner_id AND a.state IN ('accepted', 'constrained', 'suspended', 'lapsed');
  IF NOT FOUND THEN RETURN jsonb_build_object('record_id', t.owner_id, 'skipped', 'no version of the record is in force'); END IF;
  /* B107 act-found: a timer scheduled for an EARLIER version fires on the version now in force (a re-acceptance) — with no finding nothing
     is constrained (as the sweep): _ar_constrain turned an accepted record CONSTRAINED on an empty finding list */
  v_findings := governance.ar_findings(r.record_id, r.version);
  IF jsonb_array_length(v_findings) > 0 THEN
    v := governance._ar_constrain(r.record_id, r.version, v_findings, 'sweep', 'review', p_actor, p_correlation);
  END IF;
  SELECT * INTO r FROM governance.acceptance_records a WHERE a.record_id = r.record_id AND a.version = r.version;
  IF r.state = 'accepted' THEN
    SELECT min(x) INTO v_next FROM (
      SELECT (e ->> 'valid_until')::timestamptz AS x FROM jsonb_array_elements(r.evidence) e
      UNION ALL SELECT ((c ->> 'due')::date + 1)::timestamptz FROM jsonb_array_elements(r.conditions) c
      UNION ALL SELECT ((r.scope_tuple -> 'period' ->> 'to')::date + 1)::timestamptz
      UNION ALL SELECT ((r.operational ->> 'review_date')::date + 1)::timestamptz WHERE r.operational IS NOT NULL) s WHERE x > v_now;
    IF v_next IS NOT NULL THEN
      v_timer := executive._schedule_timer(gen_random_uuid(), p_tenant, p_domain, 'acceptance_record', r.record_id, 'acceptance.evidence_expiry', v_next,
                                           jsonb_build_object('version', r.version, 'digest', r.digest), p_actor, p_correlation);
      UPDATE governance.acceptance_records SET expiry_timer_id = v_timer WHERE record_id = r.record_id AND version = r.version;
    END IF;
  END IF;
  RETURN jsonb_build_object('record_id', r.record_id, 'version', r.version, 'state', r.state, 'changed', v, 'next_timer', v_timer, 'next_check', v_next);
END $$;
REVOKE ALL ON FUNCTION governance.ar_timer(uuid, uuid, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_timer(uuid, uuid, uuid, uuid, uuid) TO eye_commit;

-- §AR.8 TRIGGERS BY ACT, CONDITIONS MET, WITHDRAWAL ─────────────────────────────────────────────────────────────────────────────────────
/* A REVIEW TRIGGER by act (ES-71-005) — governance.acceptance.trigger (human-gated): a material change, an incident, a control failure, a model
   or agent withdrawal, SLO exhaustion (declared — B64 computes no SLO here) puts the record in force under REVIEW (constrained to its accepted
   scope, expansion held) or SUSPENDS it (nothing in force; the opt-in gate refuses). A named human of the product, operations or assurance
   authority, or the domain administrator. */
CREATE OR REPLACE FUNCTION governance.ar_trigger(p_record uuid, p_tenant uuid, p_domain uuid, p_kind text, p_policy text, p_detail jsonb, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE r governance.acceptance_records%ROWTYPE; v jsonb;
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.acceptance.trigger']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  PERFORM governance._ar_actor('acceptance record', p_actor);
  PERFORM governance.assert_approver('acceptance record', p_actor, p_tenant, p_domain, ARRAY['product_authority', 'operations_authority', 'independent_assurance', 'domain_admin'], NULL, NULL,
                                     'putting an acceptance under review or suspending it');
  IF p_kind IS NULL OR p_kind NOT IN ('material_change', 'incident', 'control_failure', 'model_withdrawal', 'agent_withdrawal', 'slo_exhaustion') THEN
    RAISE EXCEPTION 'acceptance record rejected (trigger): % is not a trigger an act declares (material_change, incident, control_failure, model_withdrawal, agent_withdrawal, slo_exhaustion)', coalesce(p_kind, '<none>') USING ERRCODE = '22023';
  END IF;
  IF p_policy NOT IN ('review', 'suspend') THEN RAISE EXCEPTION 'acceptance record rejected (policy): review or suspend' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'acceptance record rejected (reason): a trigger states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  SELECT * INTO r FROM governance.acceptance_records a WHERE a.record_id = p_record AND a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.state IN ('accepted', 'constrained', 'suspended', 'lapsed') FOR UPDATE;
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM governance.acceptance_records a WHERE a.record_id = p_record AND a.tenant_id = p_tenant AND a.domain_id = p_domain) THEN
      RAISE EXCEPTION 'acceptance record rejected (state): record % has no version in force', p_record USING ERRCODE = '23505';
    END IF;
    RAISE EXCEPTION 'acceptance record rejected (unknown_record): % is not an acceptance record of this domain', p_record USING ERRCODE = '23503';
  END IF;
  IF r.state = 'lapsed' THEN RAISE EXCEPTION 'acceptance record rejected (state): version % lapsed — nothing is in force to review', r.version USING ERRCODE = '23505'; END IF;
  v := governance._ar_constrain(r.record_id, r.version, jsonb_build_array(jsonb_build_object('kind', p_kind, 'ref', gen_random_uuid(), 'reason', btrim(p_reason), 'detail', coalesce(p_detail, '{}'::jsonb),
                                 'by', p_actor, 'carrier', CASE WHEN p_kind = 'slo_exhaustion' THEN 'declared here; SLO computation is B64''s' END)), 'act', p_policy, p_actor, p_correlation);
  RETURN coalesce(v, jsonb_build_object('record_id', r.record_id, 'version', r.version, 'state', r.state, 'unchanged', true));
END $$;
REVOKE ALL ON FUNCTION governance.ar_trigger(uuid, uuid, uuid, text, text, jsonb, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_trigger(uuid, uuid, uuid, text, text, jsonb, text, uuid, uuid) TO eye_commit;

/* A CONDITION MET — governance.acceptance.condition.close (human-gated): the operations, assurance or product authority (never a builder)
   names the CURRENT evidence that meets it (an evidence slot's condition: an item of that kind). A met condition stops counting as overdue;
   it never lifts a constraint by itself — only a re-acceptance does. */
CREATE OR REPLACE FUNCTION governance.ar_condition_met(p_record uuid, p_version int, p_tenant uuid, p_domain uuid, p_key text, p_evidence uuid, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE r governance.acceptance_records%ROWTYPE; c jsonb; e governance.acceptance_evidence%ROWTYPE; v uuid := gen_random_uuid();
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.acceptance.condition.close']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  PERFORM governance._ar_actor('acceptance record', p_actor);
  SELECT * INTO r FROM governance.acceptance_records a WHERE a.record_id = p_record AND a.version = p_version AND a.tenant_id = p_tenant AND a.domain_id = p_domain;
  IF NOT FOUND THEN RAISE EXCEPTION 'acceptance record rejected (unknown_record): no acceptance record %/v% in this domain', p_record, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('acceptance record', p_actor, p_tenant, p_domain, ARRAY['operations_authority', 'independent_assurance', 'product_authority'], NULL, r.builders, 'meeting an acceptance condition');
  IF r.state NOT IN ('proposed', 'accepted', 'constrained') THEN RAISE EXCEPTION 'acceptance record rejected (state): version % is %', p_version, r.state USING ERRCODE = '23505'; END IF;
  SELECT x INTO c FROM jsonb_array_elements(r.conditions) x WHERE x ->> 'key' = p_key;
  IF c IS NULL THEN RAISE EXCEPTION 'acceptance record rejected (unknown_condition): version % has no condition %', p_version, coalesce(p_key, '<none>') USING ERRCODE = '23503'; END IF;
  IF EXISTS (SELECT 1 FROM governance.acceptance_condition_events x WHERE x.record_id = p_record AND x.version = p_version AND x.condition_key = p_key) THEN
    RAISE EXCEPTION 'acceptance record rejected (duplicate): condition % is already met', p_key USING ERRCODE = '23505';
  END IF;
  SELECT * INTO e FROM governance.acceptance_evidence x WHERE x.evidence_id = p_evidence AND x.tenant_id = p_tenant AND x.domain_id = p_domain;
  IF NOT FOUND THEN RAISE EXCEPTION 'acceptance record rejected (unknown_evidence): % is not an evidence item of this domain', p_evidence USING ERRCODE = '23503'; END IF;
  IF e.valid_until <= clock_timestamp() OR e.outcome = 'failed' THEN RAISE EXCEPTION 'acceptance record rejected (stale): a condition is met by CURRENT, passing evidence' USING ERRCODE = '23505'; END IF;
  IF c ->> 'slot' IS NOT NULL AND e.kind <> c ->> 'slot' THEN
    RAISE EXCEPTION 'acceptance record rejected (condition): the % slot is met by % evidence (this item is %)', c ->> 'slot', c ->> 'slot', e.kind USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'acceptance record rejected (reason): a met condition states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  INSERT INTO governance.acceptance_condition_events (event_id, tenant_id, domain_id, record_id, version, condition_key, evidence_id, reason, met_by, correlation_id)
  VALUES (v, p_tenant, p_domain, p_record, p_version, p_key, p_evidence, btrim(p_reason), p_actor, p_correlation);
  PERFORM governance._ar_link(p_tenant, p_domain, p_evidence, p_record, 'evidences', jsonb_build_object('condition', p_key, 'version', p_version), p_actor, p_correlation);
  PERFORM governance.ledger(p_tenant, p_domain, 'acceptance_record', p_record, p_version, 'acceptance.condition_met', p_actor,
                            jsonb_build_object('condition', p_key, 'evidence_id', p_evidence, 'reason', btrim(p_reason)), p_correlation);
  RETURN jsonb_build_object('event_id', v, 'record_id', p_record, 'version', p_version, 'condition', p_key, 'evidence_id', p_evidence, 'state', r.state,
                            'note', 'a met condition never lifts a constraint by itself — a re-acceptance does');
END $$;
REVOKE ALL ON FUNCTION governance.ar_condition_met(uuid, int, uuid, uuid, text, uuid, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_condition_met(uuid, int, uuid, uuid, text, uuid, text, uuid, uuid) TO eye_commit;

/* WITHDRAW (ES-71-004 "reversible") — governance.acceptance.withdraw (human-gated): an acceptance in force by a named human product,
   operations or customer authority; a proposal also by its proposer. Every live version ends; the hold is lifted (nothing is accepted any
   more — a new scope needs a new acceptance); the attention closed; the tasks resolved. */
CREATE OR REPLACE FUNCTION governance.ar_withdraw(p_record uuid, p_tenant uuid, p_domain uuid, p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE v_now timestamptz := clock_timestamp(); v_inforce boolean; v_prop uuid; v_ended jsonb; v_lifted jsonb; v_title text; v_kind text; v_subject text;
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.acceptance.withdraw']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  PERFORM governance._ar_actor('acceptance record', p_actor);
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'acceptance record rejected (reason): a withdrawal states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  SELECT bool_or(a.state IN ('accepted', 'constrained', 'suspended', 'lapsed')), max(CASE WHEN a.state = 'proposed' THEN a.proposed_by::text END)::uuid, max(a.title), max(a.kind), max(a.subject_key)
    INTO v_inforce, v_prop, v_title, v_kind, v_subject
    FROM governance.acceptance_records a WHERE a.record_id = p_record AND a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.state IN ('proposed', 'accepted', 'constrained', 'suspended', 'lapsed');
  IF v_inforce IS NULL THEN
    IF EXISTS (SELECT 1 FROM governance.acceptance_records a WHERE a.record_id = p_record AND a.tenant_id = p_tenant AND a.domain_id = p_domain) THEN
      RAISE EXCEPTION 'acceptance record rejected (state): record % has no live version to withdraw', p_record USING ERRCODE = '23505';
    END IF;
    RAISE EXCEPTION 'acceptance record rejected (unknown_record): % is not an acceptance record of this domain', p_record USING ERRCODE = '23503';
  END IF;
  IF v_inforce OR p_actor IS DISTINCT FROM v_prop THEN
    PERFORM governance.assert_approver('acceptance record', p_actor, p_tenant, p_domain, ARRAY['product_authority', 'operations_authority', 'customer_sponsor', 'onboarding_authority'], NULL, NULL,
                                       'withdrawing an acceptance');
  END IF;
  WITH e AS (UPDATE governance.acceptance_records SET state = 'withdrawn', ended_by = p_actor, ended_at = v_now, end_reason = btrim(p_reason)
              WHERE record_id = p_record AND state IN ('proposed', 'accepted', 'constrained', 'suspended', 'lapsed') RETURNING version, state)
  SELECT jsonb_agg(e.version) INTO v_ended FROM e;
  WITH l AS (UPDATE governance.holds h SET lifted_at = v_now, lifted_by = p_actor, lift_reason = format('the acceptance was withdrawn: %s — nothing of it is in force any more', btrim(p_reason))
              WHERE h.source_artifact = p_record AND h.lifted_at IS NULL AND h.reason_kind = 'acceptance_constrained' RETURNING h.hold_id)
  SELECT coalesce(jsonb_agg(l.hold_id), '[]'::jsonb) INTO v_lifted FROM l;
  PERFORM executive.b33_close_items(p_tenant, p_domain, 'governance.acceptance', 'acceptance_record', p_record, 'the acceptance was withdrawn', p_actor, p_correlation);
  PERFORM executive._resolve_human_tasks(p_tenant, p_domain, jsonb_build_object('kind', 'acceptance_record', 'id', p_record), ARRAY['governance.attest'], 'withdrawn', p_record, p_actor, p_correlation);
  PERFORM governance._ar_artifact(p_record, p_tenant, p_domain, 'acceptance_record', 'ACC-' || p_record::text, v_title || ' (claim: demonstration)', 'retired',
                                  jsonb_build_object('kind', v_kind, 'subject', v_subject, 'state', 'withdrawn', 'claim', 'demonstration'),
                                  governance.digest(jsonb_build_object('record', p_record, 'state', 'withdrawn', 'at', v_now)), p_actor, p_correlation);
  PERFORM governance.ledger(p_tenant, p_domain, 'acceptance_record', p_record, NULL, 'acceptance.withdrawn', p_actor,
                            jsonb_build_object('versions', v_ended, 'reason', btrim(p_reason), 'holds_lifted', v_lifted), p_correlation);
  RETURN jsonb_build_object('record_id', p_record, 'state', 'withdrawn', 'versions', v_ended, 'holds_lifted', v_lifted);
END $$;
REVOKE ALL ON FUNCTION governance.ar_withdraw(uuid, uuid, uuid, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_withdraw(uuid, uuid, uuid, text, uuid, uuid) TO eye_commit;

-- §AR.9 THE OPT-IN REQUEST GATE (Q5) ───────────────────────────────────────────────────────────────────────────────────────────────────────
/* MARK a capability enforce_acceptance (or unmark it) — governance.acceptance.enforce (PLATFORM, human-gated): the product authority, a named
   human, never a builder of the capability. The prefixes never name a mandatory control (identity, tenancy, audit, policy, retention,
   objects, commercial, governance), warnings or attention — those are never gated. */
CREATE OR REPLACE FUNCTION governance.ar_enforce(p_capability_key text, p_enforced boolean, p_prefixes text[], p_reason text, p_actor uuid, p_correlation uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE cap governance.artifacts%ROWTYPE; v_cur int; v_digest text; px text; v_builders uuid[];
BEGIN
  PERFORM governance.assert_platform('governance.acceptance.enforce', p_actor, 'acceptance record');
  SELECT * INTO cap FROM governance.artifacts a WHERE a.kind = 'capability' AND a.external_key = p_capability_key AND a.superseded_at IS NULL AND a.scope = 'PLATFORM';
  IF NOT FOUND THEN RAISE EXCEPTION 'acceptance record rejected (unknown_capability): no current capability %', coalesce(p_capability_key, '<none>') USING ERRCODE = '23503'; END IF;
  v_builders := ARRAY(SELECT (j #>> '{}')::uuid FROM jsonb_array_elements(coalesce(cap.attributes -> 'builders', '[]'::jsonb)) j WHERE (j #>> '{}') ~ '^[0-9a-f-]{36}$');
  PERFORM governance.assert_approver('acceptance record', p_actor, NULL, NULL, ARRAY['product_authority'], NULL, v_builders, 'marking a capability enforce_acceptance');
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'acceptance record rejected (reason): the marking states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_enforced AND cardinality(coalesce(p_prefixes, '{}'::text[])) = 0 THEN RAISE EXCEPTION 'acceptance record rejected (prefixes): an enforced capability names the action prefixes it covers' USING ERRCODE = '22023'; END IF;
  FOREACH px IN ARRAY coalesce(p_prefixes, '{}'::text[]) LOOP
    IF px !~ '^[a-z][a-z0-9_]*(\.[a-z0-9_]+)*\.?$' OR position('.' IN px) = 0 THEN
      RAISE EXCEPTION 'acceptance record rejected (prefixes): % is not an action or an action prefix (domain.supply. — at least two segments)', px USING ERRCODE = '22023';
    END IF;
    IF split_part(px, '.', 1) IN ('identity', 'tenancy', 'audit', 'policy', 'retention', 'objects', 'commercial', 'governance') OR px LIKE 'executive.attention.%' OR px LIKE 'prediction.warning.%'
       OR px IN ('executive.', 'prediction.') THEN
      RAISE EXCEPTION 'acceptance record rejected (prefixes): % covers a mandatory control, warnings or attention — never gated by acceptance', px USING ERRCODE = '22023';
    END IF;
  END LOOP;
  SELECT coalesce(max(e.version), 0) INTO v_cur FROM governance.acceptance_enforcement e WHERE e.capability_key = p_capability_key;
  v_digest := governance.digest(jsonb_build_object('capability', p_capability_key, 'version', v_cur + 1, 'enforced', p_enforced, 'prefixes', to_jsonb(coalesce(p_prefixes, '{}'::text[]))));
  INSERT INTO governance.acceptance_enforcement (capability_key, version, capability_artifact, enforced, action_prefixes, reason, digest, set_by, correlation_id)
  VALUES (p_capability_key, v_cur + 1, cap.artifact_id, p_enforced, coalesce(p_prefixes, '{}'::text[]), btrim(p_reason), v_digest, p_actor, p_correlation);
  PERFORM governance.ledger(NULL, NULL, 'capability', cap.artifact_id, v_cur + 1, CASE WHEN p_enforced THEN 'acceptance.enforced' ELSE 'acceptance.unenforced' END, p_actor,
                            jsonb_build_object('capability', p_capability_key, 'prefixes', to_jsonb(coalesce(p_prefixes, '{}'::text[])), 'reason', btrim(p_reason), 'digest', v_digest), p_correlation);
  RETURN jsonb_build_object('capability', p_capability_key, 'version', v_cur + 1, 'enforced', p_enforced, 'prefixes', to_jsonb(coalesce(p_prefixes, '{}'::text[])), 'digest', v_digest);
END $$;
REVOKE ALL ON FUNCTION governance.ar_enforce(text, boolean, text[], text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_enforce(text, boolean, text[], text, uuid, uuid) TO eye_commit;

/* The enforced capabilities and their prefixes (the vendor's register, no tenant data): the pipeline's cached list — a request whose action
   matches none is never asked anything more. */
CREATE OR REPLACE FUNCTION governance.ar_gate_prefixes() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('capability', e.capability_key, 'prefixes', to_jsonb(e.action_prefixes)) ORDER BY e.capability_key), '[]'::jsonb)
    FROM governance.acceptance_enforcement e
   WHERE e.enforced AND e.version = (SELECT max(x.version) FROM governance.acceptance_enforcement x WHERE x.capability_key = e.capability_key)
$$;
REVOKE ALL ON FUNCTION governance.ar_gate_prefixes() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_gate_prefixes() TO eye_app, eye_commit;

/* THE GATE's answer for one request (read under the request's own evidence context): the enforced capability its action falls under, and
   whether that capability is accepted HERE for the caller's roles and the request's consequence class — accepted or constrained within the
   effective scope; suspended, lapsed, withdrawn or never accepted refuses. */
CREATE OR REPLACE FUNCTION governance.ar_gate(p_tenant uuid, p_domain uuid, p_action text, p_roles text[], p_class text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE v_cap text; r governance.acceptance_records%ROWTYPE; v_eff jsonb;
BEGIN
  PERFORM observation.assert_read_scope(p_tenant, p_domain, 'the acceptance gate');
  SELECT e.capability_key INTO v_cap FROM governance.acceptance_enforcement e, unnest(e.action_prefixes) px
   WHERE e.enforced AND e.version = (SELECT max(x.version) FROM governance.acceptance_enforcement x WHERE x.capability_key = e.capability_key)
     AND (p_action = px OR (right(px, 1) = '.' AND starts_with(p_action, px)))
   ORDER BY length(px) DESC LIMIT 1;
  IF v_cap IS NULL THEN RETURN jsonb_build_object('gated', false, 'available', true); END IF;
  SELECT * INTO r FROM governance.acceptance_records a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.subject_key = v_cap AND a.kind IN ('capability', 'operational')
     AND a.state IN ('accepted', 'constrained', 'suspended', 'lapsed') ORDER BY (a.kind = 'capability') DESC, a.accepted_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('gated', true, 'available', false, 'capability', v_cap, 'state', 'not_accepted',
                              'reason', format('%s is not accepted for this domain — an acceptance names its exact scope (the capability is marked enforce_acceptance)', v_cap));
  END IF;
  IF r.state IN ('suspended', 'lapsed') THEN
    RETURN jsonb_build_object('gated', true, 'available', false, 'capability', v_cap, 'state', r.state, 'record_id', r.record_id, 'version', r.version,
                              'reason', format('%s is %s in this domain (record %s v%s) — nothing of it is in force until it is re-accepted', v_cap, r.state, r.record_id, r.version));
  END IF;
  v_eff := coalesce(r.effective_scope, r.scope_tuple);
  IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(v_eff -> 'roles') x WHERE x = ANY (coalesce(p_roles, '{}'::text[]))) THEN
    RETURN jsonb_build_object('gated', true, 'available', false, 'capability', v_cap, 'state', r.state, 'record_id', r.record_id, 'version', r.version,
                              'reason', format('%s is %s here for the roles %s only — the caller''s roles are outside the %s scope', v_cap, r.state,
                                               (SELECT string_agg(x, ', ') FROM jsonb_array_elements_text(v_eff -> 'roles') x), CASE WHEN r.state = 'constrained' THEN 'constrained' ELSE 'accepted' END));
  END IF;
  IF governance.ar_class_rank(coalesce(p_class, 'C0')) > governance.ar_class_rank(v_eff ->> 'consequence_class') THEN
    RETURN jsonb_build_object('gated', true, 'available', false, 'capability', v_cap, 'state', r.state, 'record_id', r.record_id, 'version', r.version,
                              'reason', format('%s is accepted here up to consequence class %s — this request is %s', v_cap, v_eff ->> 'consequence_class', p_class));
  END IF;
  RETURN jsonb_build_object('gated', true, 'available', true, 'capability', v_cap, 'state', r.state, 'record_id', r.record_id, 'version', r.version,
                            'reason', format('%s is %s here (record %s v%s)', v_cap, r.state, r.record_id, r.version));
END $$;
REVOKE ALL ON FUNCTION governance.ar_gate(uuid, uuid, text, text[], text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_gate(uuid, uuid, text, text[], text) TO eye_app, eye_commit;

-- §AR.10 THE READS ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* THE ACCEPTED-SCOPE READ (FEX-31, CAP-AU-11 "resolve acceptance evidence to exact scope and versions"): the subject's state HERE — accepted,
   constrained (with the effective scope and what was removed), suspended, lapsed, proposed only, or NOT ACCEPTED — the unmet obligations of a
   proposal, the evidence with its age and validity, the open holds, whether expansion is held in this tenant, the gate's marking. Nothing is
   shown accepted by inference: no record in force reads not_accepted. */
CREATE OR REPLACE FUNCTION governance.ar_scope(p_tenant uuid, p_domain uuid, p_subject_key text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE r governance.acceptance_records%ROWTYPE; p governance.acceptance_records%ROWTYPE; v_now timestamptz := clock_timestamp(); v_held boolean; v_enf jsonb; v_ev jsonb;
BEGIN
  PERFORM observation.assert_read_scope(p_tenant, p_domain, 'the accepted scope');
  SELECT * INTO r FROM governance.acceptance_records a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.subject_key = p_subject_key
     AND a.state IN ('accepted', 'constrained', 'suspended', 'lapsed') ORDER BY (a.kind = 'capability') DESC, a.accepted_at DESC LIMIT 1;
  SELECT * INTO p FROM governance.acceptance_records a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.subject_key = p_subject_key AND a.state = 'proposed'
   ORDER BY a.proposed_at DESC LIMIT 1;
  v_held := EXISTS (SELECT 1 FROM governance.holds h JOIN governance.acceptance_records x ON x.record_id = h.source_artifact
                     WHERE h.lifted_at IS NULL AND h.reason_kind = 'acceptance_constrained' AND x.tenant_id = p_tenant AND x.subject_key = p_subject_key);
  SELECT jsonb_build_object('enforced', e.enforced, 'prefixes', to_jsonb(e.action_prefixes), 'version', e.version) INTO v_enf FROM governance.acceptance_enforcement e
   WHERE e.capability_key = p_subject_key ORDER BY e.version DESC LIMIT 1;
  IF r.record_id IS NOT NULL THEN
    SELECT jsonb_agg(jsonb_build_object('evidence_id', e.evidence_id, 'kind', e.kind, 'title', e.title, 'captured_at', e.captured_at, 'valid_until', e.valid_until,
                                        'age_days', round(extract(epoch FROM v_now - e.captured_at) / 86400.0, 2), 'current', e.valid_until > v_now AND e.outcome <> 'failed', 'covers', e.covers) ORDER BY e.valid_until)
      INTO v_ev FROM governance.acceptance_evidence e WHERE e.evidence_id IN (SELECT (x ->> 'evidence_id')::uuid FROM jsonb_array_elements(r.evidence) x);
  END IF;
  RETURN jsonb_build_object(
    'subject', p_subject_key, 'tenant', p_tenant, 'domain', p_domain, 'read_at', v_now,
    'state', CASE WHEN r.record_id IS NOT NULL THEN r.state WHEN p.record_id IS NOT NULL THEN 'proposed_only' ELSE 'not_accepted' END,
    'record', CASE WHEN r.record_id IS NULL THEN NULL ELSE jsonb_build_object('record_id', r.record_id, 'version', r.version, 'kind', r.kind, 'digest', r.digest, 'accepted_at', r.accepted_at,
                                                                              'constrained_at', r.constrained_at, 'reasons', r.constrained_reasons, 'claim', r.claim) END,
    'accepted_scope', r.scope_tuple, 'effective_scope', CASE WHEN r.state IN ('suspended', 'lapsed') THEN NULL ELSE coalesce(r.effective_scope, r.scope_tuple) END,
    'removed', r.effective_scope -> 'removed', 'evidence', v_ev,
    'proposal', CASE WHEN p.record_id IS NULL THEN NULL ELSE jsonb_build_object('record_id', p.record_id, 'version', p.version, 'digest', p.digest,
                  'unmet', (SELECT coalesce(jsonb_agg(o), '[]'::jsonb) FROM unnest(p.obligations) o WHERE NOT EXISTS (SELECT 1 FROM governance.acceptance_attestations a WHERE a.record_id = p.record_id AND a.version = p.version AND a.obligation = o AND a.decision = 'attest'))) END,
    'expansion_held', v_held, 'enforcement', v_enf,
    'boundary', 'scope-specific: this answer is for this tenant and domain only; claim = demonstration — real acceptance is R2');
END $$;
REVOKE ALL ON FUNCTION governance.ar_scope(uuid, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_scope(uuid, uuid, text) TO eye_app, eye_commit;

/* THE ATTESTATION PREVIEW's eligibility (OBJ-40: exact version, eligibility, consequence preview): for each obligation of a version, whether
   THIS principal may attest it and, when not, why — the port's own rules in words (the port decides; this explains). */
CREATE OR REPLACE FUNCTION governance.ar_eligibility(p_record uuid, p_version int, p_principal uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE r governance.acceptance_records%ROWTYPE; o text; v jsonb := '[]'::jsonb; why text[]; v_now timestamptz := clock_timestamp(); v_common text[] := '{}';
BEGIN
  SELECT * INTO r FROM governance.acceptance_records a WHERE a.record_id = p_record AND a.version = p_version;
  IF NOT FOUND THEN RETURN NULL; END IF;
  PERFORM observation.assert_read_scope(r.tenant_id, r.domain_id, 'an attestation''s eligibility');
  IF p_principal IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'acceptance attestation rejected (actor): eligibility is read for the caller only' USING ERRCODE = '42501'; END IF;
  IF onboarding.principal_kind(p_principal) IS DISTINCT FROM 'human' THEN v_common := v_common || 'an agent or a system never attests'::text; END IF;
  IF p_principal = r.proposed_by THEN v_common := v_common || 'you proposed this version (no self-acceptance)'::text; END IF;
  IF p_principal = ANY (r.builders) THEN v_common := v_common || 'you are a builder of the subject (independence)'::text; END IF;
  IF r.state <> 'proposed' THEN v_common := v_common || format('version %s is %s', p_version, r.state); END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(r.evidence) x JOIN governance.acceptance_evidence e ON e.evidence_id = (x ->> 'evidence_id')::uuid WHERE e.valid_until <= v_now OR e.outcome = 'failed') THEN
    v_common := v_common || 'an evidence item is no longer current — a new version over renewed evidence is needed'::text;
  END IF;
  IF r.kind = 'release' AND EXISTS (SELECT 1 FROM governance.holds h WHERE h.subject_artifact = r.subject_artifact AND h.lifted_at IS NULL) THEN
    v_common := v_common || format('release candidate %s is held', r.subject_key);
  END IF;
  IF EXISTS (SELECT 1 FROM governance.acceptance_attestations a WHERE a.record_id = p_record AND a.version = p_version AND a.attester = p_principal) THEN
    v_common := v_common || 'you already attested an obligation of this version (one person per obligation)'::text;
  END IF;
  FOREACH o IN ARRAY r.obligations LOOP
    why := v_common;
    IF EXISTS (SELECT 1 FROM governance.acceptance_attestations a WHERE a.record_id = p_record AND a.version = p_version AND a.obligation = o) THEN why := why || 'already attested'::text; END IF;
    IF NOT governance.holds_role(p_principal, r.tenant_id, r.domain_id, governance.ar_obligation_roles(o)) THEN
      why := why || format('the %s obligation is attested by a %s', replace(o, '_', ' '), array_to_string(governance.ar_obligation_roles(o), ' or '));
    END IF;
    IF o = 'customer' AND NOT EXISTS (SELECT 1 FROM governance.acceptance_verifications x WHERE x.record_id = p_record AND x.version = p_version AND x.outcome = 'verified') THEN
      why := why || 'the customer verifies the version before attesting it'::text;
    END IF;
    v := v || jsonb_build_array(jsonb_build_object('obligation', o, 'roles', to_jsonb(governance.ar_obligation_roles(o)), 'can_attest', cardinality(why) = 0, 'reasons', to_jsonb(why),
                                                   'attested', (SELECT jsonb_build_object('by', a.attester, 'name', governance.ar_principal_name(a.attester), 'role', a.attester_role, 'decision', a.decision, 'at', a.attested_at)
                                                                  FROM governance.acceptance_attestations a WHERE a.record_id = p_record AND a.version = p_version AND a.obligation = o)));
  END LOOP;
  RETURN jsonb_build_object('record_id', p_record, 'version', p_version, 'digest', r.digest, 'obligations', v,
                            'can_verify', governance.holds_role(p_principal, r.tenant_id, r.domain_id, ARRAY['customer_sponsor', 'onboarding_authority']) AND cardinality(v_common) = 0
                                          AND NOT EXISTS (SELECT 1 FROM governance.acceptance_verifications x WHERE x.record_id = p_record AND x.version = p_version));
END $$;
REVOKE ALL ON FUNCTION governance.ar_eligibility(uuid, int, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.ar_eligibility(uuid, int, uuid) TO eye_app, eye_commit;


-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- §DG — design governance: the design baseline, principles, contributions, design acceptance, experience learning, the unsigned conformance package (F-P7-E-17)
-- (folded at integration from the part-local file 0115_b107_x_dg.sql, unchanged but for the marked `B107 integration` edits; apply order §0, §RG, §CM, §DR, §PG, §AR, §DG)
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 0115 §DG — CP-6 B107, part `dg`: DESIGN GOVERNANCE (F-P7-E-17; V9 UX-01/02/03/08/72, UX-ADR-001/002/023/024, REL-01/02/23/24) — the design
-- baseline under the Design System Authority; the principle / prohibition registry and its evaluations (the lint); narrow, expiring design
-- exceptions; the CONTRIBUTION queue over component / pattern versions (propose → review → accept → publish → adopt → measure; deprecate →
-- migrate → retire; amend; reject; close); design asset ownership (one accountable owner, approved status); the design trace over the shared
-- links; DESIGN ACCEPTANCE records (DOMAIN, on §AR's model — kept in this part's own table keyed to the same tuple until the fold); EXPERIENCE
-- LEARNING (a B92 experience action of kind design_change_proposal opens a contribution — telemetry never modifies a pattern); B92's telemetry
-- governance bound as evidence (REL-23); the INDEPENDENT CONFORMANCE PACKAGE for UX-70-006 / UX-66-006, generated and left UNSIGNED (R2).
-- Applies alone on top of 0001–0114 + the prelude (0115 §0). Re-declares NOTHING of an earlier migration.
--
-- THREE CLAIMS, never mixed: CONSTRUCTION (this migration, its ports and phase6-design-b107); DEMONSTRATED OPERATION (the act on SYNTHETIC
-- personas — every design acceptance and conformance package carries `claim = 'demonstration'`); REAL ACCEPTANCE (named independent design
-- authorities signing the conformance package, H3 / R2) — never claimed: no row of this part can carry it (the CHECKs admit `demonstration`
-- only, and a conformance package has no signature column at all).
-- MET-034 (accessibility journey pass rate) stays `unsupported` (B108 is its source; H3 its verification): the design acceptance record carries
-- EMPTY accessibility evidence slots naming that carrier — nothing here computes or claims accessibility.
-- The general context bar stays B80's; UX-ADR-019 / REL-20 (deployment parity) are B106 / R1's.
-- ════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════

-- §DG.1 THE TABLES ─────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
/* THE DESIGN ASSETS (REL-01; UX-72): one row per VERSION of a component, a pattern or a design asset (the token set). One accountable OWNER
   (a named active human) and an APPROVED status, both the Design System Authority's act; an inventory import registers what the repository
   holds (`proposed`, no owner — an ownership gap, shown). A published contribution writes the next version (the prior one `superseded`,
   still readable — consumers are never stranded silently). */
CREATE TABLE governance.design_assets (
  asset_id         uuid NOT NULL,
  version          int  NOT NULL CHECK (version >= 1),
  scope            text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id        uuid CHECK (tenant_id IS NULL),
  domain_id        uuid CHECK (domain_id IS NULL),
  kind             text NOT NULL CHECK (kind IN ('design_component', 'pattern', 'design_asset')),
  asset_key        text NOT NULL CHECK (asset_key ~ '^[a-z][a-z0-9_.-]{2,120}$'),
  title            text NOT NULL CHECK (length(btrim(title)) BETWEEN 3 AND 300),
  source_ref       text NOT NULL CHECK (length(btrim(source_ref)) BETWEEN 3 AND 400),
  package_version  text NOT NULL CHECK (package_version ~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.-]+)?$'),
  source_digest    text CHECK (source_digest IS NULL OR source_digest ~ '^[0-9a-f]{64}$'),
  consumers        jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(consumers) = 'array'),
  owner_principal_id uuid,
  status           text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'approved', 'deprecated', 'retired', 'superseded')),
  contribution_id  uuid,
  digest           text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  registered_by    uuid NOT NULL,
  registered_at    timestamptz NOT NULL DEFAULT clock_timestamp(),
  approved_by      uuid,
  approved_at      timestamptz,
  approval_reason  text,
  superseded_at    timestamptz,
  correlation_id   uuid NOT NULL,
  PRIMARY KEY (asset_id, version),
  CONSTRAINT gda_approved CHECK (status NOT IN ('approved', 'deprecated') OR (owner_principal_id IS NOT NULL AND approved_by IS NOT NULL AND approved_at IS NOT NULL)),
  CONSTRAINT gda_superseded CHECK ((status = 'superseded') = (superseded_at IS NOT NULL))
);
CREATE UNIQUE INDEX gda_one_current ON governance.design_assets (asset_id) WHERE superseded_at IS NULL;
CREATE UNIQUE INDEX gda_key_current ON governance.design_assets (asset_key) WHERE superseded_at IS NULL;

/* THE PRINCIPLES AND PROHIBITIONS (UX-03; UX-ADR-002): the enforceable interaction rules — statement, prohibited behaviour, affected patterns,
   remediation, the lint rule that checks it (if one does). UNWAIVABLE principles (human authority, truth-state separation, provenance,
   accessibility — UX-03-004: no commercial, administrative, model or delivery role may waive them) admit no exception and are never retired.
   Versioned by key; a change is the Design System Authority's (human-gated). Seeded below from V9 (normative, `declared_by` the zero id). */
CREATE TABLE governance.design_principles (
  principle_id     uuid NOT NULL,
  version          int  NOT NULL CHECK (version >= 1),
  scope            text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id        uuid CHECK (tenant_id IS NULL),
  domain_id        uuid CHECK (domain_id IS NULL),
  principle_key    text NOT NULL CHECK (principle_key ~ '^[a-z][a-z0-9_.-]{2,80}$'),
  kind             text NOT NULL CHECK (kind IN ('principle', 'prohibition')),
  statement        text NOT NULL CHECK (length(btrim(statement)) BETWEEN 8 AND 2000),
  prohibited       text,
  affected_patterns text[] NOT NULL DEFAULT '{}',
  remediation      text NOT NULL CHECK (length(btrim(remediation)) >= 8),
  lint_rule        text CHECK (lint_rule IS NULL OR lint_rule IN ('raw-colour', 'optimistic-path', 'surface-definition')),
  unwaivable       boolean NOT NULL DEFAULT false,
  source           text NOT NULL,
  state            text NOT NULL DEFAULT 'active' CHECK (state IN ('active', 'retired', 'superseded')),
  digest           text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  declared_by      uuid NOT NULL,
  declared_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
  reason           text NOT NULL,
  correlation_id   uuid NOT NULL,
  PRIMARY KEY (principle_id, version),
  CONSTRAINT gdp_unwaivable_live CHECK (NOT (unwaivable AND state = 'retired'))
);
CREATE UNIQUE INDEX gdp_key_current ON governance.design_principles (principle_key) WHERE state <> 'superseded';

/* THE EVALUATIONS (UX-03-003): a design evaluated against the explicit principles — the LINT over the web source (a pure function: raw
   colours, optimistic paths, a surface defining the product as chat / dashboard / BI / copilot / report) or a named reviewer's review of an
   asset version. Each finding names its principle; a finding covered by an approved, unexpired, NARROW design exception (that principle ×
   that asset) reads `excepted`, every other one makes the verdict `nonconformant`. Append-only evidence. */
CREATE TABLE governance.design_evaluations (
  evaluation_id    uuid PRIMARY KEY,
  scope            text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id        uuid CHECK (tenant_id IS NULL),
  domain_id        uuid CHECK (domain_id IS NULL),
  source           text NOT NULL CHECK (source IN ('lint', 'review')),
  target_asset_id  uuid,
  target_version   int,
  input_digest     text NOT NULL CHECK (input_digest ~ '^[0-9a-f]{64}$'),
  rules_version    text NOT NULL,
  findings         jsonb NOT NULL CHECK (jsonb_typeof(findings) = 'array'),
  verdict          text NOT NULL CHECK (verdict IN ('conformant', 'nonconformant')),
  counts           jsonb NOT NULL DEFAULT '{}'::jsonb,
  digest           text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  evaluated_by     uuid NOT NULL,
  evaluated_by_kind text NOT NULL,
  evaluated_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id   uuid NOT NULL,
  CONSTRAINT gde_target CHECK ((target_asset_id IS NULL) = (target_version IS NULL)),
  CONSTRAINT gde_review_target CHECK (source = 'lint' OR target_asset_id IS NOT NULL)
);
CREATE INDEX gde_target_idx ON governance.design_evaluations (target_asset_id, evaluated_at DESC);

/* THE DESIGN EXCEPTIONS (UX-03-003/-006): NARROW (one principle × one asset), EXPIRING (≤ 90 days), approved by the Design System Authority —
   never the requester, never the asset's OWNER whose authority it expands (ES-02-004), never for an unwaivable principle; a renewal names the
   exception it renews and may not broaden it (the same principle and asset). An expired exception covers nothing: the evaluation turns
   nonconformant again and an acceptance that relied on it is withheld. Registered as `exception` artifacts (§PG's registry reads them by kind;
   the integrator may fold them into THE ONE exception registry). */
CREATE TABLE governance.design_exceptions (
  exception_id     uuid PRIMARY KEY,
  scope            text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id        uuid CHECK (tenant_id IS NULL),
  domain_id        uuid CHECK (domain_id IS NULL),
  principle_key    text NOT NULL,
  asset_id         uuid NOT NULL,
  asset_version    int  NOT NULL,
  reason           text NOT NULL CHECK (length(btrim(reason)) >= 12),
  compensating     text NOT NULL CHECK (length(btrim(compensating)) >= 8),
  expires_at       timestamptz NOT NULL,
  renews           uuid REFERENCES governance.design_exceptions (exception_id),
  state            text NOT NULL DEFAULT 'requested' CHECK (state IN ('requested', 'approved', 'rejected', 'withdrawn')),
  digest           text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  requested_by     uuid NOT NULL,
  requested_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by       uuid,
  decided_at       timestamptz,
  decision_reason  text,
  signature_id     uuid,
  correlation_id   uuid NOT NULL,
  CONSTRAINT gdx_window CHECK (expires_at > requested_at AND expires_at <= requested_at + interval '90 days'),
  CONSTRAINT gdx_decided CHECK ((state IN ('requested', 'withdrawn')) = (decided_by IS NULL)),
  CONSTRAINT gdx_sod CHECK (decided_by IS NULL OR decided_by <> requested_by),
  CONSTRAINT gdx_signed CHECK (state <> 'approved' OR signature_id IS NOT NULL)
);

/* THE CONTRIBUTIONS (UX-72; UX-ADR-024): the design-system queue over component / pattern versions. Stages: proposed → (review) in_review |
   held → accepted (the Design System Authority's SIGNED act; a constitutional AMENDMENT is ratified by the product authority instead —
   UX-72-004) → published (the asset's next version) → adopted → measured → closed; a DEPRECATION publishes as `deprecated` → migrating
   (consumers moved) → retired (only when no consumer is stranded); rejected / closed end it; AMEND (the proposer or a contributor — recorded
   as a builder, who then never accepts it) returns it to proposed at the next revision. An experience-learning proposal (origin
   `experience_learning`) is opened from a B92 action and changes nothing until a human accepts and publishes it. */
CREATE TABLE governance.design_contributions (
  contribution_id  uuid PRIMARY KEY,
  scope            text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id        uuid CHECK (tenant_id IS NULL),
  domain_id        uuid CHECK (domain_id IS NULL),
  revision         int  NOT NULL DEFAULT 1 CHECK (revision >= 1),
  kind             text NOT NULL CHECK (kind IN ('new_component', 'component_change', 'new_pattern', 'pattern_change', 'deprecation', 'retirement', 'amendment')),
  target_asset_id  uuid,
  target_version   int,
  proposal         jsonb NOT NULL CHECK (jsonb_typeof(proposal) = 'object'),
  summary          text NOT NULL CHECK (length(btrim(summary)) BETWEEN 12 AND 4000),
  plans            jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(plans) = 'object'),
  constitutional   boolean NOT NULL DEFAULT false,
  origin           text NOT NULL DEFAULT 'contributor' CHECK (origin IN ('contributor', 'experience_learning')),
  intake_id        uuid,
  stage            text NOT NULL DEFAULT 'proposed' CHECK (stage IN ('proposed', 'in_review', 'held', 'accepted', 'rejected', 'published', 'adopted', 'measured',
                                                                     'deprecated', 'migrating', 'retired', 'closed')),
  hold_reasons     jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(hold_reasons) = 'array'),
  review           jsonb,
  evidence         jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(evidence) = 'array'),
  digest           text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  proposed_by      uuid NOT NULL,
  proposed_by_kind text NOT NULL CHECK (proposed_by_kind IN ('human', 'agent', 'system')),
  proposed_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
  builders         uuid[] NOT NULL DEFAULT '{}',
  reviewed_by      uuid,
  accepted_by      uuid,
  accepted_at      timestamptz,
  signature_id     uuid,
  published_version int,
  closed_reason    text,
  updated_at       timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id   uuid NOT NULL,
  CONSTRAINT gdc_target CHECK ((target_asset_id IS NULL) = (target_version IS NULL)),
  CONSTRAINT gdc_sod CHECK (accepted_by IS NULL OR (accepted_by <> proposed_by AND NOT (accepted_by = ANY (builders)))),
  CONSTRAINT gdc_signed CHECK (accepted_by IS NULL OR signature_id IS NOT NULL),
  CONSTRAINT gdc_origin CHECK ((origin = 'experience_learning') = (intake_id IS NOT NULL))
);

/* THE DESIGN BASELINE (UX-01; UX-ADR-001): the controlling visual and interaction baseline — the design-system version, the conformance scope,
   its members (asset versions with digests), the principles and the approved exceptions in force — registered (proposed), compared, ATTESTED
   (the Design System Authority's SIGNED act; never the proposer), superseded by the next attested version or rejected. It REFINES Volumes 0
   and 3–8 and never alters them: `constitutional_change` is false by construction. An attestation whose members cannot resolve to an
   approved owner is HELD (governance.holds `ownership_gap`), the proposal preserved. */
CREATE TABLE governance.design_baselines (
  baseline_id      uuid NOT NULL,
  version          int  NOT NULL CHECK (version >= 1),
  scope            text NOT NULL DEFAULT 'PLATFORM' CHECK (scope = 'PLATFORM'),
  tenant_id        uuid CHECK (tenant_id IS NULL),
  domain_id        uuid CHECK (domain_id IS NULL),
  title            text NOT NULL CHECK (length(btrim(title)) BETWEEN 4 AND 300),
  design_system_version text NOT NULL CHECK (length(btrim(design_system_version)) BETWEEN 3 AND 120),
  controlling_volume text NOT NULL DEFAULT 'V9' CHECK (controlling_volume = 'V9'),
  refines          text[] NOT NULL DEFAULT ARRAY['V0', 'V3', 'V4', 'V5', 'V6', 'V7', 'V8'],
  constitutional_change boolean NOT NULL DEFAULT false CHECK (NOT constitutional_change),
  conformance_scope jsonb NOT NULL CHECK (jsonb_typeof(conformance_scope) = 'object'),
  members          jsonb NOT NULL CHECK (jsonb_typeof(members) = 'array'),
  principles       jsonb NOT NULL CHECK (jsonb_typeof(principles) = 'array'),
  exceptions       jsonb NOT NULL CHECK (jsonb_typeof(exceptions) = 'array'),
  state            text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'attested', 'rejected', 'superseded')),
  digest           text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  proposed_by      uuid NOT NULL,
  proposed_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
  decided_by       uuid,
  decided_at       timestamptz,
  decision_reason  text,
  signature_id     uuid,
  correlation_id   uuid NOT NULL,
  PRIMARY KEY (baseline_id, version),
  CONSTRAINT gdb_decided CHECK ((state = 'proposed') = (decided_by IS NULL) OR state = 'superseded'),
  CONSTRAINT gdb_sod CHECK (decided_by IS NULL OR decided_by <> proposed_by),
  CONSTRAINT gdb_signed CHECK (state <> 'attested' OR signature_id IS NOT NULL)
);
CREATE UNIQUE INDEX gdb_one_proposed ON governance.design_baselines (baseline_id) WHERE state = 'proposed';
CREATE UNIQUE INDEX gdb_one_attested ON governance.design_baselines (baseline_id) WHERE state = 'attested';

/* THE EXPERIENCE-LEARNING INTAKES (UX-ADR-024; DOMAIN): a B92 experience action of kind `design_change_proposal` (decided by the domain's named
   product analytics owner) taken into design governance — one intake per action; it OPENS a contribution proposal and changes nothing else. */
CREATE TABLE governance.design_experience_intakes (
  intake_id        uuid PRIMARY KEY,
  scope            text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id        uuid NOT NULL,
  domain_id        uuid NOT NULL,
  action_id        uuid NOT NULL UNIQUE,
  finding_id       uuid NOT NULL,
  journey_key      text,
  statement        text NOT NULL,
  preview_digest   text NOT NULL,
  decided_by       uuid NOT NULL,
  decided_at       timestamptz NOT NULL,
  contribution_id  uuid NOT NULL,
  intaken_by       uuid NOT NULL,
  intaken_by_kind  text NOT NULL,
  intaken_at       timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id   uuid NOT NULL
);

/* THE DESIGN ACCEPTANCE RECORDS (UX-ADR-023, REL-24; DOMAIN — the tenant / domain is part of the accepted tuple): §AR's acceptance-record model
   for kind `design`, kept here in this part's own table keyed to the same tuple (§AR's governance.acceptance_records is not on this branch —
   the integrator folds). The exact design tuple (the attested baseline version and digest, the component and pattern versions, capability,
   canonical journey, persona and role, deployment profile, entitlement, theme, locale, device, assistive technology, configuration digest,
   data versions, period), evidence items with captured_at / valid_until (their ages), findings, conditions, the EMPTY accessibility slots
   (MET-034 unsupported — B108 → H3), the REQUIRED OBLIGATIONS each attested by a DISTINCT named human (design → the Design System Authority,
   assurance → independent assurance, customer → the customer sponsor) and SIGNED (executive.signatures `design_acceptance`); `accepted` only
   when every obligation is signed; `withheld` when evidence expires or a bound version is superseded (the record keeps what was accepted —
   the prior accepted baseline is preserved, nothing re-accepts itself). */
CREATE TABLE governance.design_acceptances (
  acceptance_id    uuid NOT NULL,
  version          int  NOT NULL CHECK (version >= 1),
  scope            text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id        uuid NOT NULL,
  domain_id        uuid NOT NULL,
  kind             text NOT NULL DEFAULT 'design' CHECK (kind = 'design'),
  baseline_id      uuid NOT NULL,
  baseline_version int  NOT NULL,
  baseline_digest  text NOT NULL,
  components       jsonb NOT NULL CHECK (jsonb_typeof(components) = 'array'),
  tuple            jsonb NOT NULL CHECK (jsonb_typeof(tuple) = 'object'),
  evidence         jsonb NOT NULL CHECK (jsonb_typeof(evidence) = 'array' AND jsonb_array_length(evidence) >= 1),
  findings         jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(findings) = 'array'),
  conditions       jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(conditions) = 'array'),
  accessibility    jsonb NOT NULL,
  obligations      text[] NOT NULL CHECK (obligations <@ ARRAY['design', 'assurance', 'customer'] AND obligations @> ARRAY['design', 'assurance']),
  attestations     jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(attestations) = 'array'),
  builders         uuid[] NOT NULL DEFAULT '{}',
  valid_until      timestamptz NOT NULL,
  state            text NOT NULL DEFAULT 'proposed' CHECK (state IN ('proposed', 'accepted', 'withheld', 'rejected', 'superseded')),
  withheld_reason  text,
  withheld_at      timestamptz,
  claim            text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  digest           text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  proposed_by      uuid NOT NULL,
  proposed_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
  accepted_at      timestamptz,
  correlation_id   uuid NOT NULL,
  PRIMARY KEY (acceptance_id, version),
  CONSTRAINT gdac_withheld CHECK (state <> 'withheld' OR (withheld_at IS NOT NULL AND length(btrim(coalesce(withheld_reason, ''))) >= 8)),
  CONSTRAINT gdac_accepted CHECK (state NOT IN ('accepted', 'withheld') OR accepted_at IS NOT NULL)
);
CREATE UNIQUE INDEX gdac_one_open ON governance.design_acceptances (acceptance_id) WHERE state = 'proposed';

/* THE INDEPENDENT CONFORMANCE PACKAGES (UX-70-006, UX-66-006; DOMAIN): the exact design tuple + the evidence with its ages (B92's telemetry
   governance and experience records; B94's onboarding, go-live, admission and value records — by reference: kind, id, digest, captured_at)
   + the findings — GENERATED for named independent authorities to review and sign. LEFT UNSIGNED: no signature column; `signed` is false by
   CHECK; the signed acceptance is R2's. Append-only. */
CREATE TABLE governance.design_conformance_packages (
  package_id       uuid PRIMARY KEY,
  scope            text NOT NULL DEFAULT 'DOMAIN' CHECK (scope = 'DOMAIN'),
  tenant_id        uuid NOT NULL,
  domain_id        uuid NOT NULL,
  target           text NOT NULL CHECK (target IN ('UX-70-006', 'UX-66-006')),
  acceptance_id    uuid,
  acceptance_version int,
  content          jsonb NOT NULL CHECK (jsonb_typeof(content) = 'object'),
  digest           text NOT NULL CHECK (digest ~ '^[0-9a-f]{64}$'),
  signed           boolean NOT NULL DEFAULT false CHECK (NOT signed),
  signature_required text NOT NULL DEFAULT 'R2: the named independent authorities review and sign this package outside the product; nothing here signs it',
  claim            text NOT NULL DEFAULT 'demonstration' CHECK (claim = 'demonstration'),
  generated_by     uuid NOT NULL,
  generated_by_kind text NOT NULL,
  generated_at     timestamptz NOT NULL DEFAULT clock_timestamp(),
  correlation_id   uuid NOT NULL
);

CREATE TRIGGER gde_append_only BEFORE UPDATE OR DELETE ON governance.design_evaluations FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();
CREATE TRIGGER gdi_append_only BEFORE UPDATE OR DELETE ON governance.design_experience_intakes FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();
CREATE TRIGGER gdk_append_only BEFORE UPDATE OR DELETE ON governance.design_conformance_packages FOR EACH ROW EXECUTE FUNCTION public.raise_append_only();
/* Versioned rows are never deleted (a supersession is recorded, a record is never removed). */
CREATE OR REPLACE FUNCTION governance.dg_never_delete() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'design governance rejected (state): % rows are never deleted — a supersession, a retirement or a withdrawal is recorded instead', TG_TABLE_NAME USING ERRCODE = '42501'; END $$;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['design_assets', 'design_principles', 'design_exceptions', 'design_contributions', 'design_baselines', 'design_acceptances'] LOOP
    EXECUTE format('CREATE TRIGGER %I BEFORE DELETE ON governance.%I FOR EACH ROW EXECUTE FUNCTION governance.dg_never_delete()', t || '_never_delete', t);
  END LOOP;
END $$;

-- RLS and grants (the prelude's governance_visibility idiom): PLATFORM rows readable by every authenticated context (the vendor's design
-- system is not tenant data); DOMAIN rows within the tenant / domain; a PLATFORM context reads all. SELECT to eye_app and eye_commit; no write
-- grant — the definer ports write.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['governance.design_assets', 'governance.design_principles', 'governance.design_evaluations', 'governance.design_exceptions',
                           'governance.design_contributions', 'governance.design_baselines', 'governance.design_experience_intakes', 'governance.design_acceptances',
                           'governance.design_conformance_packages'] LOOP
    EXECUTE format('REVOKE ALL ON %s FROM PUBLIC', t);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($f$CREATE POLICY governance_visibility ON %s USING (
      (scope = 'PLATFORM' AND public.eye_scope() <> 'NONE')
      OR (scope = 'TENANT' AND tenant_id = public.eye_tenant())
      OR (scope = 'DOMAIN' AND tenant_id = public.eye_tenant() AND (public.eye_scope() = 'TENANT' OR domain_id = public.eye_domain()))
      OR public.eye_scope() = 'PLATFORM')$f$, t);
    EXECUTE format('GRANT SELECT ON %s TO eye_app, eye_commit', t);
  END LOOP;
END $$;

-- §DG.2 THE SEED: the V9 principles and prohibitions (normative; the zero id declares them — no human approved them here) ─────────────────
INSERT INTO governance.design_principles (principle_id, version, principle_key, kind, statement, prohibited, affected_patterns, remediation, lint_rule, unwaivable, source, digest,
                                          declared_by, reason, correlation_id)
SELECT gen_random_uuid(), 1, s.key, s.kind, s.statement, s.prohibited, s.patterns, s.remediation, s.lint, s.unwaivable, s.source,
       governance.digest(jsonb_build_object('key', s.key, 'version', 1, 'kind', s.kind, 'statement', s.statement, 'prohibited', s.prohibited, 'patterns', to_jsonb(s.patterns),
                                            'remediation', s.remediation, 'lint_rule', s.lint, 'unwaivable', s.unwaivable)),
       '00000000-0000-0000-0000-000000000000'::uuid, 'seeded from Volume 9 by 0115 §DG (normative text; no human approval is claimed)', gen_random_uuid()
  FROM (VALUES
    ('surface-access-mode', 'prohibition', 'Interfaces remain access modes to the operating system (UX-ADR-002).',
       'A surface defining the product as chat, chatbot, copilot, dashboard, BI or report.', ARRAY['page title', 'navigation label', 'workspace heading'],
       'Name the surface by the governed work it serves (observation, decision, governance …), never as a chat, dashboard, BI tool, copilot or report.', 'surface-definition', false, 'V9 UX-ADR-002, UX-03'),
    ('semantic-tokens-only', 'principle', 'Product code consumes semantic design tokens only (UX-ADR-010); a raw colour bypasses the controlled visual baseline.',
       'A raw colour literal (#hex, rgb(), hsl()) in product code.', ARRAY['every component', 'every page'],
       'Replace the literal with the semantic token variable (var(--eye-color-…)) that names its role; a missing role is a design-system contribution.', 'raw-colour', false, 'V9 UX-ADR-010, App A'),
    ('no-optimistic-path', 'prohibition', 'A governed act renders only from the authoritative receipt (UX-ADR-017): there is no optimistic path.',
       'An optimistic update (useOptimistic, an optimistic flag or helper) that shows an act as done before the server''s receipt.', ARRAY['governed action', 'GovernedButton'],
       'Render the result from the receipt; show the pending state as pending.', 'optimistic-path', false, 'V9 UX-ADR-017, UX-03-001'),
    ('no-dark-patterns', 'prohibition', 'No decorative, certainty-inflating or dark-pattern behaviour; engagement is never optimised at the expense of truth, control or comprehension (UX-03-005).',
       'Pre-checked consent, confirm-shaming, hidden costs, false urgency, certainty shown without its uncertainty.', ARRAY['consent', 'approval control', 'forecast display'],
       'Block the non-conformant pattern, preserve the design evidence and remediate through a contribution.', NULL, false, 'V9 UX-03-001, UX-03-005'),
    ('human-authority', 'principle', 'Only a named human approves, accepts, attests or signs; AI and automation recommend, draft and execute pre-authorised reversible steps only (UX-01-004, UX-03-004).',
       'An agent or an automated step shown or recorded as approving, accepting or signing.', ARRAY['approval control', 'acceptance record'],
       'Route the act to the named human authority; show eligibility, separation of duties, the digest and the consequence before the act.', NULL, true, 'V9 UX-03-004'),
    ('truth-state-separation', 'principle', 'Observed, asserted, inferred, assessed and synthetic states stay visually and semantically distinct (UX-03-004).',
       'A synthetic, inferred or assessed value styled or worded as observed.', ARRAY['TruthBadge', 'every value display'],
       'Carry the truth state with the value; never merge them.', NULL, true, 'V9 UX-03-004'),
    ('provenance-visible', 'principle', 'Provenance, freshness and policy stay explicit wherever they change the meaning of what is shown (UX-03-004).',
       'A value shown without the provenance that qualifies it.', ARRAY['every value display'],
       'Show the source, the as-of and the policy beside the value.', NULL, true, 'V9 UX-03-004'),
    ('accessibility', 'principle', 'Accessibility is never waived by a commercial, administrative, model or delivery role (UX-03-004).',
       'An inaccessible control or surface admitted by exception.', ARRAY['every component'],
       'Fix the control; accessibility evidence is B108''s suites (MET-034 stays unsupported until they exist).', NULL, true, 'V9 UX-03-004')
  ) AS s(key, kind, statement, prohibited, patterns, remediation, lint, unwaivable, source);

-- §DG.3 THE INTERNAL HELPERS (definer ports call them; REVOKE PUBLIC, granted to no runtime role) ───────────────────────────────────────────
/* The kind of a principal ('human' | 'agent' | 'system'), active only. */
CREATE OR REPLACE FUNCTION governance.dg_kind(p_principal uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = identity, pg_catalog, pg_temp AS $$
  SELECT p.kind FROM identity.principals p WHERE p.id = p_principal AND p.status = 'active'
$$;
REVOKE ALL ON FUNCTION governance.dg_kind(uuid) FROM PUBLIC;

/* REGISTER (or re-version) an artifact of this part in the shared core: the current version is kept when nothing changed (same digest and
   lifecycle — idempotent); otherwise the current one is superseded and the next version written. Returns the current version. */
CREATE OR REPLACE FUNCTION governance.dg_artifact(p_id uuid, p_kind text, p_key text, p_title text, p_tenant uuid, p_domain uuid, p_owner uuid, p_owner_role text,
                                                  p_lifecycle text, p_attrs jsonb, p_digest text, p_actor uuid, p_corr uuid) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE cur governance.artifacts%ROWTYPE; v int;
BEGIN
  SELECT * INTO cur FROM governance.artifacts a WHERE a.artifact_id = p_id AND a.superseded_at IS NULL FOR UPDATE;
  IF FOUND AND cur.digest = p_digest AND cur.lifecycle = p_lifecycle AND cur.owner_principal_id IS NOT DISTINCT FROM p_owner THEN RETURN cur.version; END IF;
  IF FOUND THEN UPDATE governance.artifacts SET superseded_at = clock_timestamp() WHERE artifact_id = p_id AND version = cur.version; END IF;
  v := coalesce(cur.version, 0) + 1;
  INSERT INTO governance.artifacts (artifact_id, version, scope, tenant_id, domain_id, kind, external_key, title, owner_principal_id, owner_role, authority_class, controlling_volume,
                                    lifecycle, attributes, source, digest, recorded_by, correlation_id)
  VALUES (p_id, v, CASE WHEN p_domain IS NOT NULL THEN 'DOMAIN' WHEN p_tenant IS NOT NULL THEN 'TENANT' ELSE 'PLATFORM' END, p_tenant, p_domain, p_kind, p_key, left(p_title, 500),
          p_owner, p_owner_role, 'design_system_authority', 'V9', p_lifecycle, coalesce(p_attrs, '{}'::jsonb), jsonb_build_object('part', 'dg', 'migration', '0115 §DG'),
          p_digest, p_actor, p_corr);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dg_artifact(uuid, text, text, text, uuid, uuid, uuid, text, text, jsonb, text, uuid, uuid) FROM PUBLIC;

/* A LINK in the shared core (append-only), unless the same live link already exists. Returns the link id (the existing one when present). */
CREATE OR REPLACE FUNCTION governance.dg_link(p_from uuid, p_to uuid, p_relation text, p_tenant uuid, p_domain uuid, p_attrs jsonb, p_actor uuid, p_corr uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v uuid;
BEGIN
  SELECT l.link_id INTO v FROM governance.links_live l WHERE l.from_artifact = p_from AND l.to_artifact = p_to AND l.relation = p_relation LIMIT 1;
  IF v IS NOT NULL THEN RETURN v; END IF;
  v := gen_random_uuid();
  INSERT INTO governance.links (link_id, scope, tenant_id, domain_id, from_artifact, to_artifact, relation, attributes, recorded_by, correlation_id)
  VALUES (v, CASE WHEN p_domain IS NOT NULL THEN 'DOMAIN' WHEN p_tenant IS NOT NULL THEN 'TENANT' ELSE 'PLATFORM' END, p_tenant, p_domain, p_from, p_to, p_relation,
          coalesce(p_attrs, '{}'::jsonb) || jsonb_build_object('part', 'dg'), p_actor, p_corr);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dg_link(uuid, uuid, text, uuid, uuid, jsonb, uuid, uuid) FROM PUBLIC;

/* Retire a live link (a later row; never an update). */
CREATE OR REPLACE FUNCTION governance.dg_unlink(p_link uuid, p_actor uuid, p_corr uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE l governance.links%ROWTYPE; v uuid := gen_random_uuid();
BEGIN
  SELECT * INTO l FROM governance.links_live x WHERE x.link_id = p_link;
  IF NOT FOUND THEN RETURN NULL; END IF;
  INSERT INTO governance.links (link_id, scope, tenant_id, domain_id, from_artifact, to_artifact, relation, retired, retires_link, attributes, recorded_by, correlation_id)
  VALUES (v, l.scope, l.tenant_id, l.domain_id, l.from_artifact, l.to_artifact, l.relation, true, l.link_id, jsonb_build_object('part', 'dg'), p_actor, p_corr);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dg_unlink(uuid, uuid, uuid) FROM PUBLIC;

/* Open a HOLD on a subject artifact (unless one of that reason is already open); lift every open hold of a subject. */
CREATE OR REPLACE FUNCTION governance.dg_hold(p_subject uuid, p_reason_kind text, p_reason text, p_tenant uuid, p_domain uuid, p_actor uuid, p_corr uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE v uuid;
BEGIN
  SELECT h.hold_id INTO v FROM governance.holds h WHERE h.subject_artifact = p_subject AND h.reason_kind = p_reason_kind AND h.lifted_at IS NULL LIMIT 1;
  IF v IS NOT NULL THEN RETURN v; END IF;
  v := gen_random_uuid();
  INSERT INTO governance.holds (hold_id, scope, tenant_id, domain_id, subject_artifact, reason_kind, reason, opened_by, correlation_id)
  VALUES (v, CASE WHEN p_domain IS NOT NULL THEN 'DOMAIN' WHEN p_tenant IS NOT NULL THEN 'TENANT' ELSE 'PLATFORM' END, p_tenant, p_domain, p_subject, p_reason_kind, left(p_reason, 2000), p_actor, p_corr);
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dg_hold(uuid, text, text, uuid, uuid, uuid, uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION governance.dg_lift(p_subject uuid, p_reason text, p_actor uuid) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE n int;
BEGIN
  UPDATE governance.holds SET lifted_at = clock_timestamp(), lifted_by = p_actor, lift_reason = left(p_reason, 2000) WHERE subject_artifact = p_subject AND lifted_at IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;
REVOKE ALL ON FUNCTION governance.dg_lift(uuid, text, uuid) FROM PUBLIC;

/* The approved, unexpired, NARROW exception covering (principle, asset) on the asset's CURRENT version — or NULL. */
CREATE OR REPLACE FUNCTION governance.dg_exception_covering(p_principle text, p_asset uuid) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT x.exception_id FROM governance.design_exceptions x JOIN governance.design_assets a ON a.asset_id = x.asset_id AND a.version = x.asset_version AND a.superseded_at IS NULL
   WHERE x.principle_key = p_principle AND x.asset_id = p_asset AND x.state = 'approved' AND x.expires_at > clock_timestamp()
   ORDER BY x.expires_at DESC LIMIT 1
$$;
REVOKE ALL ON FUNCTION governance.dg_exception_covering(text, uuid) FROM PUBLIC;

/* The digest of an asset version's content. */
CREATE OR REPLACE FUNCTION governance.dg_asset_digest(a governance.design_assets) RETURNS text
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT governance.digest(jsonb_build_object('asset_id', a.asset_id, 'version', a.version, 'kind', a.kind, 'key', a.asset_key, 'title', a.title, 'source_ref', a.source_ref,
                                              'package_version', a.package_version, 'source_digest', a.source_digest, 'consumers', a.consumers, 'owner', a.owner_principal_id,
                                              'status', a.status, 'contribution_id', a.contribution_id))
$$;
REVOKE ALL ON FUNCTION governance.dg_asset_digest(governance.design_assets) FROM PUBLIC;

/* The PLATFORM signature (governance.signatures) a decision names: the decider's, over this version's digest, under this action. */
CREATE OR REPLACE FUNCTION governance.dg_signature_ok(p_signature uuid, p_kind text, p_subject uuid, p_version int, p_digest text, p_signer uuid, p_action text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT p_signature IS NOT NULL AND EXISTS (SELECT 1 FROM governance.signatures s WHERE s.signature_id = p_signature AND s.subject_kind = p_kind AND s.subject_id = p_subject
                                               AND s.subject_version = p_version AND s.subject_digest = p_digest AND s.signer = p_signer AND s.bound_action = p_action)
$$;
REVOKE ALL ON FUNCTION governance.dg_signature_ok(uuid, text, uuid, int, text, uuid, text) FROM PUBLIC;

-- §DG.4 THE PLATFORM SIGNATURE PORT (the B36 key-reference path; §PG's shared TS helper is copied inside this part until the fold) ────────
/* RECORD a named human's Ed25519 signature over a design-governance subject's digest (a baseline attestation, a contribution's acceptance, an
   exception approval), under the CALLER's bound action — the deciding port then verifies it names the decider, the version and the digest. */
CREATE OR REPLACE FUNCTION governance.dg_record_signature(p_signature uuid, p_action text, p_kind text, p_subject uuid, p_version int, p_digest text, p_role text,
                                                          p_key_id text, p_signature_b64 text, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE v_noun text := CASE p_kind WHEN 'baseline_decision' THEN 'design baseline' WHEN 'design_contribution' THEN 'design contribution' ELSE 'design principle' END;
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('governance.design.baseline.decide', 'governance.design.contribution.accept', 'governance.design.exception.decide') THEN
    RAISE EXCEPTION 'design baseline rejected (authority): % is not a design-governance signing act', coalesce(p_action, '<none>') USING ERRCODE = '42501';
  END IF;
  PERFORM governance.assert_platform(p_action, p_actor, v_noun);
  IF p_kind NOT IN ('baseline_decision', 'design_contribution', 'exception_approval') THEN
    RAISE EXCEPTION '% rejected (signature): % is not a design-governance signature kind', v_noun, coalesce(p_kind, '<none>') USING ERRCODE = '22023';
  END IF;
  IF p_digest IS NULL OR p_digest !~ '^[0-9a-f]{64}$' OR p_key_id IS NULL OR p_key_id !~ '^ed25519:[0-9a-f]{16}$' OR p_signature_b64 IS NULL OR p_signature_b64 !~ '^[A-Za-z0-9+/]{86}==$' THEN
    RAISE EXCEPTION '% rejected (signature): an Ed25519 signature by key reference over a 64-hex digest', v_noun USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM governance.signatures s WHERE s.subject_kind = p_kind AND s.subject_id = p_subject AND s.subject_version = p_version AND s.signer = p_actor) THEN
    RAISE EXCEPTION '% rejected (duplicate): %/% is already signed by this principal', v_noun, p_subject, p_version USING ERRCODE = '23505';
  END IF;
  INSERT INTO governance.signatures (signature_id, scope, subject_kind, subject_id, subject_version, subject_digest, signer, signer_role, key_id, algorithm, signature, bound_action, correlation_id)
  VALUES (p_signature, 'PLATFORM', p_kind, p_subject, p_version, p_digest, p_actor, coalesce(p_role, 'design_system_authority'), p_key_id, 'ed25519', p_signature_b64, p_action, p_corr);
  RETURN jsonb_build_object('signature_id', p_signature, 'subject_kind', p_kind, 'subject_id', p_subject, 'subject_version', p_version, 'subject_digest', p_digest,
                            'signer', p_actor, 'key_id', p_key_id, 'signed_at', clock_timestamp());
END $$;
REVOKE ALL ON FUNCTION governance.dg_record_signature(uuid, text, text, uuid, int, text, text, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_record_signature(uuid, text, text, uuid, int, text, text, text, text, uuid, uuid) TO eye_commit;

-- §DG.5 THE DESIGN ASSETS: the inventory import and the owner's approval (REL-01) ─────────────────────────────────────────────────────────
/* REGISTER the repository's design assets (the conformance steward or the Design System Authority; fed by the TS inventory reader over
   packages/tokens and apps/web/components — the sources are read, never written). A new key → version 1, `proposed`, NO owner (the gap is
   shown until the authority names one). A known key with the same source digest → unchanged (idempotent). A known key whose source moved →
   reported as DRIFT and NOT changed: an inventory never modifies an asset; the change is a contribution. */
CREATE OR REPLACE FUNCTION governance.dg_register_assets(p_import uuid, p_assets jsonb, p_source jsonb, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE a jsonb; cur governance.design_assets%ROWTYPE; v_row governance.design_assets%ROWTYPE; v_registered jsonb := '[]'::jsonb; v_drift jsonb := '[]'::jsonb; v_unchanged int := 0;
        v_keys text[] := '{}'; v_key text;
BEGIN
  PERFORM governance.assert_platform('governance.design.asset.register', p_actor, 'design baseline');
  IF jsonb_typeof(p_assets) IS DISTINCT FROM 'array' OR jsonb_array_length(p_assets) NOT BETWEEN 1 AND 400 THEN
    RAISE EXCEPTION 'design baseline rejected (assets): an inventory registers 1–400 assets' USING ERRCODE = '22023';
  END IF;
  FOR a IN SELECT x FROM jsonb_array_elements(p_assets) x LOOP
    v_key := a ->> 'key';
    IF v_key IS NULL OR v_key !~ '^[a-z][a-z0-9_.-]{2,120}$' THEN RAISE EXCEPTION 'design baseline rejected (asset): % is not an asset key', coalesce(v_key, '<none>') USING ERRCODE = '22023'; END IF;
    IF v_key = ANY (v_keys) THEN RAISE EXCEPTION 'design baseline rejected (asset): % is listed twice', v_key USING ERRCODE = '22023'; END IF;
    v_keys := v_keys || v_key;
    IF coalesce(a ->> 'kind', '') NOT IN ('design_component', 'pattern', 'design_asset') THEN
      RAISE EXCEPTION 'design baseline rejected (asset): % is a design_component, a pattern or a design_asset', v_key USING ERRCODE = '22023';
    END IF;
    IF length(btrim(coalesce(a ->> 'title', ''))) < 3 OR length(btrim(coalesce(a ->> 'sourceRef', ''))) < 3 OR coalesce(a ->> 'packageVersion', '') !~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.-]+)?$'
       OR (a ? 'sourceDigest' AND coalesce(a ->> 'sourceDigest', '') !~ '^[0-9a-f]{64}$') OR jsonb_typeof(coalesce(a -> 'consumers', '[]'::jsonb)) <> 'array' THEN
      RAISE EXCEPTION 'design baseline rejected (asset): % states its title, source, package version (semver), source digest (64 hex) and consumers (a list)', v_key USING ERRCODE = '22023';
    END IF;
    SELECT * INTO cur FROM governance.design_assets x WHERE x.asset_key = v_key AND x.superseded_at IS NULL;
    IF NOT FOUND THEN
      v_row := ROW(gen_random_uuid(), 1, 'PLATFORM', NULL, NULL, a ->> 'kind', v_key, btrim(a ->> 'title'), btrim(a ->> 'sourceRef'), a ->> 'packageVersion', a ->> 'sourceDigest',
                   coalesce(a -> 'consumers', '[]'::jsonb), NULL, 'proposed', NULL, repeat('0', 64), p_actor, clock_timestamp(), NULL, NULL, NULL, NULL, p_corr)::governance.design_assets;
      v_row.digest := governance.dg_asset_digest(v_row);
      INSERT INTO governance.design_assets SELECT v_row.*;
      PERFORM governance.dg_artifact(v_row.asset_id, v_row.kind, 'DS:' || v_key, v_row.title, NULL, NULL, NULL, NULL, 'proposed',
                                     jsonb_build_object('source_ref', v_row.source_ref, 'package_version', v_row.package_version, 'asset_version', 1), v_row.digest, p_actor, p_corr);
      v_registered := v_registered || jsonb_build_object('asset_id', v_row.asset_id, 'key', v_key, 'version', 1);
    ELSIF cur.source_digest IS NOT DISTINCT FROM (a ->> 'sourceDigest') AND cur.package_version = (a ->> 'packageVersion') THEN
      v_unchanged := v_unchanged + 1;
    ELSE
      v_drift := v_drift || jsonb_build_object('asset_id', cur.asset_id, 'key', v_key, 'version', cur.version, 'recorded', jsonb_build_object('package_version', cur.package_version, 'source_digest', cur.source_digest),
                                               'observed', jsonb_build_object('package_version', a ->> 'packageVersion', 'source_digest', a ->> 'sourceDigest'),
                                               'note', 'the source moved since this version was recorded — a contribution records the change; the inventory changes nothing');
    END IF;
  END LOOP;
  PERFORM governance.ledger(NULL, NULL, 'design_inventory', p_import, NULL, 'design.inventory_recorded', p_actor,
            jsonb_build_object('registered', jsonb_array_length(v_registered), 'unchanged', v_unchanged, 'drift', v_drift, 'source', coalesce(p_source, '{}'::jsonb)), p_corr);
  RETURN jsonb_build_object('import_id', p_import, 'registered', v_registered, 'unchanged', v_unchanged, 'drift', v_drift);
END $$;
REVOKE ALL ON FUNCTION governance.dg_register_assets(uuid, jsonb, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_register_assets(uuid, jsonb, jsonb, uuid, uuid) TO eye_commit;

/* APPROVE an asset version and name its ONE accountable owner (REL-01): the Design System Authority — a named human, never the registrar —
   on the exact digest of a `proposed` current version; the owner a named active human. */
CREATE OR REPLACE FUNCTION governance.dg_approve_asset(p_asset uuid, p_version int, p_owner uuid, p_digest text, p_reason text, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE a governance.design_assets%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.design.asset.approve', p_actor, 'design baseline');
  SELECT * INTO a FROM governance.design_assets x WHERE x.asset_id = p_asset AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'design baseline rejected (unknown_asset): no design asset %/v%', p_asset, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('design baseline', p_actor, NULL, NULL, ARRAY['design_system_authority'], a.registered_by, NULL, 'approving a design asset and naming its owner');
  IF a.superseded_at IS NOT NULL THEN RAISE EXCEPTION 'design baseline rejected (stale): version % of % is superseded', p_version, a.asset_key USING ERRCODE = '23505'; END IF;
  IF a.status <> 'proposed' THEN RAISE EXCEPTION 'design baseline rejected (state): % v% is %', a.asset_key, p_version, a.status USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM a.digest THEN RAISE EXCEPTION 'design baseline rejected (stale): the approval names a digest other than % v%''s', a.asset_key, p_version USING ERRCODE = '23505'; END IF;
  IF governance.dg_kind(p_owner) IS DISTINCT FROM 'human' THEN
    RAISE EXCEPTION 'design baseline rejected (owner): the accountable owner of a design asset is a named active human' USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'design baseline rejected (reason): an approval states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  a.status := 'approved'; a.owner_principal_id := p_owner; a.approved_by := p_actor; a.approved_at := clock_timestamp(); a.approval_reason := btrim(p_reason);
  a.digest := governance.dg_asset_digest(a);
  UPDATE governance.design_assets SET status = a.status, owner_principal_id = a.owner_principal_id, approved_by = a.approved_by, approved_at = a.approved_at,
         approval_reason = a.approval_reason, digest = a.digest WHERE asset_id = p_asset AND version = p_version;
  PERFORM governance.dg_artifact(a.asset_id, a.kind, 'DS:' || a.asset_key, a.title, NULL, NULL, p_owner, 'design_system_authority', 'active',
                                 jsonb_build_object('source_ref', a.source_ref, 'package_version', a.package_version, 'asset_version', a.version), a.digest, p_actor, p_corr);
  PERFORM governance.ledger(NULL, NULL, 'design_asset', p_asset, p_version, 'design.asset_approved', p_actor,
            jsonb_build_object('owner', p_owner, 'reason', btrim(p_reason), 'digest', a.digest), p_corr);
  RETURN jsonb_build_object('asset_id', p_asset, 'version', p_version, 'key', a.asset_key, 'status', 'approved', 'owner_principal_id', p_owner, 'digest', a.digest);
END $$;
REVOKE ALL ON FUNCTION governance.dg_approve_asset(uuid, int, uuid, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_approve_asset(uuid, int, uuid, text, text, uuid, uuid) TO eye_commit;

-- §DG.6 THE PRINCIPLES, THE EVALUATIONS, THE NARROW EXCEPTIONS (UX-03) ───────────────────────────────────────────────────────────────────────
/* DECLARE a principle or prohibition version (the Design System Authority, a named human; human-gated). An UNWAIVABLE principle stays
   unwaivable and is never retired; a version names the current one it replaces (expected_version). */
CREATE OR REPLACE FUNCTION governance.dg_declare_principle(p_key text, p_expected_version int, p_kind text, p_statement text, p_prohibited text, p_patterns text[], p_remediation text,
                                                          p_lint_rule text, p_unwaivable boolean, p_state text, p_reason text, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE cur governance.design_principles%ROWTYPE; v_id uuid; v_version int; v_digest text; v_state text := coalesce(p_state, 'active');
BEGIN
  PERFORM governance.assert_platform('governance.design.principle.declare', p_actor, 'design principle');
  PERFORM governance.assert_approver('design principle', p_actor, NULL, NULL, ARRAY['design_system_authority'], NULL, NULL, 'declaring a design principle');
  IF p_key IS NULL OR p_key !~ '^[a-z][a-z0-9_.-]{2,80}$' THEN RAISE EXCEPTION 'design principle rejected (key): % is not a principle key', coalesce(p_key, '<none>') USING ERRCODE = '22023'; END IF;
  IF coalesce(p_kind, '') NOT IN ('principle', 'prohibition') OR v_state NOT IN ('active', 'retired') THEN
    RAISE EXCEPTION 'design principle rejected (kind): a principle or a prohibition, active or retired' USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_statement, ''))) < 8 OR length(btrim(coalesce(p_remediation, ''))) < 8 OR length(btrim(coalesce(p_reason, ''))) < 8 THEN
    RAISE EXCEPTION 'design principle rejected (statement): a principle states itself, its remediation and the reason for this version (8+ characters each)' USING ERRCODE = '22023';
  END IF;
  IF p_lint_rule IS NOT NULL AND p_lint_rule NOT IN ('raw-colour', 'optimistic-path', 'surface-definition') THEN
    RAISE EXCEPTION 'design principle rejected (lint): % is not a lint rule (raw-colour, optimistic-path, surface-definition)', p_lint_rule USING ERRCODE = '22023';
  END IF;
  SELECT * INTO cur FROM governance.design_principles x WHERE x.principle_key = p_key AND x.state <> 'superseded' FOR UPDATE;
  IF coalesce(p_expected_version, -1) <> coalesce(cur.version, 0) THEN
    RAISE EXCEPTION 'design principle rejected (stale): % is at version %, not %', p_key, coalesce(cur.version, 0), coalesce(p_expected_version::text, '<none>') USING ERRCODE = '23505';
  END IF;
  IF cur.unwaivable AND (NOT coalesce(p_unwaivable, false) OR v_state = 'retired') THEN
    RAISE EXCEPTION 'design principle rejected (boundary): % is unwaivable (human authority, truth-state separation, provenance, accessibility — UX-03-004); it is never relaxed or retired', p_key USING ERRCODE = '22023';
  END IF;
  v_id := coalesce(cur.principle_id, gen_random_uuid()); v_version := coalesce(cur.version, 0) + 1;
  v_digest := governance.digest(jsonb_build_object('key', p_key, 'version', v_version, 'kind', p_kind, 'statement', btrim(p_statement), 'prohibited', p_prohibited,
                                                   'patterns', to_jsonb(coalesce(p_patterns, '{}')), 'remediation', btrim(p_remediation), 'lint_rule', p_lint_rule, 'unwaivable', coalesce(p_unwaivable, false), 'state', v_state));
  IF cur.principle_id IS NOT NULL THEN UPDATE governance.design_principles SET state = 'superseded' WHERE principle_id = cur.principle_id AND version = cur.version; END IF;
  INSERT INTO governance.design_principles (principle_id, version, principle_key, kind, statement, prohibited, affected_patterns, remediation, lint_rule, unwaivable, source, state, digest,
                                            declared_by, reason, correlation_id)
  VALUES (v_id, v_version, p_key, p_kind, btrim(p_statement), p_prohibited, coalesce(p_patterns, '{}'), btrim(p_remediation), p_lint_rule, coalesce(p_unwaivable, false),
          'declared by the Design System Authority', v_state, v_digest, p_actor, btrim(p_reason), p_corr);
  PERFORM governance.dg_artifact(v_id, 'principle', 'DP:' || p_key, left(btrim(p_statement), 300), NULL, NULL, NULL, 'design_system_authority', CASE v_state WHEN 'retired' THEN 'retired' ELSE 'active' END,
                                 jsonb_build_object('kind', p_kind, 'unwaivable', coalesce(p_unwaivable, false), 'lint_rule', p_lint_rule, 'principle_version', v_version), v_digest, p_actor, p_corr);
  PERFORM governance.ledger(NULL, NULL, 'design_principle', v_id, v_version, 'design.principle_declared', p_actor, jsonb_build_object('key', p_key, 'state', v_state, 'reason', btrim(p_reason)), p_corr);
  RETURN jsonb_build_object('principle_id', v_id, 'key', p_key, 'version', v_version, 'state', v_state, 'digest', v_digest);
END $$;
REVOKE ALL ON FUNCTION governance.dg_declare_principle(text, int, text, text, text, text[], text, text, boolean, text, text, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_declare_principle(text, int, text, text, text, text[], text, text, boolean, text, text, uuid, uuid) TO eye_commit;

/* RECORD an EVALUATION of a design against the principles (UX-03-003): the lint's findings over the web source (the conformance steward or
   the Design System Authority; an agent may run the lint — it judges nothing) or a named reviewer's review of one asset version. Each finding
   names a principle (by key, or by the lint rule it came from) and, when it is about an asset, that asset; a finding covered by a narrow,
   approved, unexpired exception reads `excepted`, every other one `open`; the verdict is `nonconformant` while one is open. */
CREATE OR REPLACE FUNCTION governance.dg_record_evaluation(p_evaluation uuid, p_source text, p_asset uuid, p_asset_version int, p_input_digest text, p_rules_version text, p_findings jsonb,
                                                          p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE f jsonb; v_out jsonb := '[]'::jsonb; v_principle text; v_asset uuid; v_exc uuid; v_open int := 0; v_excepted int := 0; v_digest text; v_target governance.design_assets%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.design.evaluate', p_actor, 'design principle');
  IF coalesce(p_source, '') NOT IN ('lint', 'review') THEN RAISE EXCEPTION 'design principle rejected (source): an evaluation is a lint run or a review' USING ERRCODE = '22023'; END IF;
  IF p_source = 'review' AND (governance.dg_kind(p_actor) IS DISTINCT FROM 'human' OR NOT governance.holds_role(p_actor, NULL, NULL, ARRAY['design_system_authority', 'conformance_steward'])) THEN
    RAISE EXCEPTION 'design principle rejected (actor): a design review is a named human reviewer''s (the Design System Authority or the conformance steward)' USING ERRCODE = '42501';
  END IF;
  IF p_asset IS NOT NULL THEN
    SELECT * INTO v_target FROM governance.design_assets x WHERE x.asset_id = p_asset AND x.version = p_asset_version;
    IF NOT FOUND THEN RAISE EXCEPTION 'design principle rejected (unknown_asset): no design asset %/v%', p_asset, p_asset_version USING ERRCODE = '23503'; END IF;
  ELSIF p_source = 'review' THEN
    RAISE EXCEPTION 'design principle rejected (target): a review names the asset version it evaluates' USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_input_digest, '') !~ '^[0-9a-f]{64}$' OR length(btrim(coalesce(p_rules_version, ''))) < 1 THEN
    RAISE EXCEPTION 'design principle rejected (input): an evaluation names the digest of what it read and its rules version' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_findings) IS DISTINCT FROM 'array' OR jsonb_array_length(p_findings) > 2000 THEN RAISE EXCEPTION 'design principle rejected (findings): a list of at most 2000 findings' USING ERRCODE = '22023'; END IF;
  FOR f IN SELECT x FROM jsonb_array_elements(p_findings) x LOOP
    v_principle := coalesce(f ->> 'principle', (SELECT p.principle_key FROM governance.design_principles p WHERE p.lint_rule = f ->> 'rule' AND p.state = 'active' LIMIT 1));
    IF v_principle IS NULL OR NOT EXISTS (SELECT 1 FROM governance.design_principles p WHERE p.principle_key = v_principle AND p.state = 'active') THEN
      RAISE EXCEPTION 'design principle rejected (unknown_principle): a finding names no active principle (%)', coalesce(f ->> 'principle', f ->> 'rule', '<none>') USING ERRCODE = '23503';
    END IF;
    v_asset := coalesce(nullif(f ->> 'assetId', '')::uuid, (SELECT a.asset_id FROM governance.design_assets a WHERE a.asset_key = f ->> 'assetKey' AND a.superseded_at IS NULL), p_asset);
    v_exc := CASE WHEN v_asset IS NULL THEN NULL ELSE governance.dg_exception_covering(v_principle, v_asset) END;
    IF v_exc IS NULL THEN v_open := v_open + 1; ELSE v_excepted := v_excepted + 1; END IF;
    v_out := v_out || jsonb_build_object('rule', f ->> 'rule', 'principle', v_principle, 'asset_id', v_asset, 'file', f ->> 'file', 'line', f -> 'line', 'excerpt', left(coalesce(f ->> 'excerpt', ''), 240),
                                         'note', left(coalesce(f ->> 'note', ''), 1000), 'status', CASE WHEN v_exc IS NULL THEN 'open' ELSE 'excepted' END, 'exception_id', v_exc);
  END LOOP;
  v_digest := governance.digest(jsonb_build_object('evaluation_id', p_evaluation, 'source', p_source, 'asset', p_asset, 'version', p_asset_version, 'input', p_input_digest, 'rules', p_rules_version, 'findings', v_out));
  INSERT INTO governance.design_evaluations (evaluation_id, source, target_asset_id, target_version, input_digest, rules_version, findings, verdict, counts, digest, evaluated_by, evaluated_by_kind, correlation_id)
  VALUES (p_evaluation, p_source, p_asset, p_asset_version, p_input_digest, p_rules_version, v_out, CASE WHEN v_open = 0 THEN 'conformant' ELSE 'nonconformant' END,
          jsonb_build_object('open', v_open, 'excepted', v_excepted, 'total', v_open + v_excepted), v_digest, p_actor, coalesce(governance.dg_kind(p_actor), 'system'), p_corr);
  PERFORM governance.dg_artifact(p_evaluation, 'evidence', 'DEV:' || p_evaluation, format('Design evaluation (%s) — %s open, %s excepted', p_source, v_open, v_excepted), NULL, NULL, NULL, NULL, 'active',
                                 jsonb_build_object('class', 'design_evaluation', 'verdict', CASE WHEN v_open = 0 THEN 'conformant' ELSE 'nonconformant' END), v_digest, p_actor, p_corr);
  IF p_asset IS NOT NULL THEN PERFORM governance.dg_link(p_evaluation, p_asset, 'evidences', NULL, NULL, jsonb_build_object('asset_version', p_asset_version), p_actor, p_corr); END IF;
  PERFORM governance.ledger(NULL, NULL, 'design_evaluation', p_evaluation, NULL, 'design.evaluated', p_actor,
            jsonb_build_object('source', p_source, 'open', v_open, 'excepted', v_excepted, 'asset', p_asset, 'version', p_asset_version), p_corr);
  RETURN jsonb_build_object('evaluation_id', p_evaluation, 'verdict', CASE WHEN v_open = 0 THEN 'conformant' ELSE 'nonconformant' END, 'open', v_open, 'excepted', v_excepted, 'findings', v_out, 'digest', v_digest);
END $$;
REVOKE ALL ON FUNCTION governance.dg_record_evaluation(uuid, text, uuid, int, text, text, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_record_evaluation(uuid, text, uuid, int, text, text, jsonb, uuid, uuid) TO eye_commit;

/* REQUEST a NARROW, EXPIRING design exception (one principle × one asset's current version; ≤ 90 days): never for an UNWAIVABLE principle; a
   renewal names the exception it renews and keeps its principle and asset (non-broadening — UX-03-006). */
CREATE OR REPLACE FUNCTION governance.dg_request_exception(p_exception uuid, p_principle text, p_asset uuid, p_reason text, p_compensating text, p_expires_at timestamptz, p_renews uuid,
                                                          p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE pr governance.design_principles%ROWTYPE; a governance.design_assets%ROWTYPE; r governance.design_exceptions%ROWTYPE; v_digest text;
BEGIN
  PERFORM governance.assert_platform('governance.design.exception.request', p_actor, 'design principle');
  SELECT * INTO pr FROM governance.design_principles x WHERE x.principle_key = p_principle AND x.state = 'active';
  IF NOT FOUND THEN RAISE EXCEPTION 'design principle rejected (unknown_principle): % is not an active principle', coalesce(p_principle, '<none>') USING ERRCODE = '23503'; END IF;
  IF pr.unwaivable THEN
    RAISE EXCEPTION 'design principle rejected (boundary): % is unwaivable — no commercial, administrative, model or delivery role may waive human authority, truth-state separation, provenance or accessibility (UX-03-004)', p_principle USING ERRCODE = '22023';
  END IF;
  SELECT * INTO a FROM governance.design_assets x WHERE x.asset_id = p_asset AND x.superseded_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'design principle rejected (unknown_asset): % is not a current design asset', p_asset USING ERRCODE = '23503'; END IF;
  IF a.status IN ('retired') THEN RAISE EXCEPTION 'design principle rejected (state): % is retired', a.asset_key USING ERRCODE = '23505'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 12 OR length(btrim(coalesce(p_compensating, ''))) < 8 THEN
    RAISE EXCEPTION 'design principle rejected (reason): an exception states why conformance cannot yet be achieved (12+) and its compensating control (8+)' USING ERRCODE = '22023';
  END IF;
  IF p_expires_at IS NULL OR p_expires_at <= clock_timestamp() OR p_expires_at > clock_timestamp() + interval '90 days' THEN
    RAISE EXCEPTION 'design principle rejected (expiry): a design exception expires in the future and within 90 days' USING ERRCODE = '22023';
  END IF;
  IF p_renews IS NOT NULL THEN
    SELECT * INTO r FROM governance.design_exceptions x WHERE x.exception_id = p_renews;
    IF NOT FOUND OR r.state <> 'approved' THEN RAISE EXCEPTION 'design principle rejected (unknown_exception): % is not an approved design exception to renew', p_renews USING ERRCODE = '23503'; END IF;
    IF r.principle_key <> p_principle OR r.asset_id <> p_asset THEN
      RAISE EXCEPTION 'design principle rejected (broadening): a renewal keeps the principle (%) and the asset of the exception it renews — it never broadens it', r.principle_key USING ERRCODE = '22023';
    END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM governance.design_exceptions x WHERE x.principle_key = p_principle AND x.asset_id = p_asset AND x.state = 'requested') THEN
    RAISE EXCEPTION 'design principle rejected (duplicate): an exception for % on % already awaits its decision', p_principle, a.asset_key USING ERRCODE = '23505';
  END IF;
  v_digest := governance.digest(jsonb_build_object('exception_id', p_exception, 'principle', p_principle, 'principle_digest', pr.digest, 'asset_id', p_asset, 'asset_version', a.version,
                                                   'asset_digest', a.digest, 'reason', btrim(p_reason), 'compensating', btrim(p_compensating), 'expires_at', p_expires_at, 'renews', p_renews));
  INSERT INTO governance.design_exceptions (exception_id, principle_key, asset_id, asset_version, reason, compensating, expires_at, renews, digest, requested_by, correlation_id)
  VALUES (p_exception, p_principle, p_asset, a.version, btrim(p_reason), btrim(p_compensating), p_expires_at, p_renews, v_digest, p_actor, p_corr);
  PERFORM governance.dg_artifact(p_exception, 'exception', 'DX:' || p_exception, format('Design exception: %s on %s v%s', p_principle, a.asset_key, a.version), NULL, NULL, NULL, 'design_system_authority', 'proposed',
                                 jsonb_build_object('class', 'design', 'principle', p_principle, 'expires_at', p_expires_at, 'renews', p_renews), v_digest, p_actor, p_corr);
  PERFORM governance.dg_link(p_exception, p_asset, 'excepts', NULL, NULL, jsonb_build_object('principle', p_principle, 'asset_version', a.version), p_actor, p_corr);
  PERFORM governance.ledger(NULL, NULL, 'design_exception', p_exception, NULL, 'design.exception_requested', p_actor,
            jsonb_build_object('principle', p_principle, 'asset', p_asset, 'version', a.version, 'expires_at', p_expires_at, 'renews', p_renews), p_corr);
  RETURN jsonb_build_object('exception_id', p_exception, 'state', 'requested', 'principle', p_principle, 'asset_id', p_asset, 'asset_version', a.version, 'expires_at', p_expires_at, 'digest', v_digest);
END $$;
REVOKE ALL ON FUNCTION governance.dg_request_exception(uuid, text, uuid, text, text, timestamptz, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_request_exception(uuid, text, uuid, text, text, timestamptz, uuid, uuid, uuid) TO eye_commit;

/* DECIDE a design exception (the Design System Authority; human-gated; SIGNED on approval): never the requester; never the asset's OWNER,
   whose authority the exception expands (ES-02-004); an exception that expired before its decision is refused (`expired`). */
CREATE OR REPLACE FUNCTION governance.dg_decide_exception(p_exception uuid, p_decision text, p_digest text, p_reason text, p_signature uuid, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE x governance.design_exceptions%ROWTYPE; v_owner uuid;
BEGIN
  PERFORM governance.assert_platform('governance.design.exception.decide', p_actor, 'design principle');
  SELECT * INTO x FROM governance.design_exceptions e WHERE e.exception_id = p_exception FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'design principle rejected (unknown_exception): no design exception %', p_exception USING ERRCODE = '23503'; END IF;
  SELECT a.owner_principal_id INTO v_owner FROM governance.design_assets a WHERE a.asset_id = x.asset_id AND a.version = x.asset_version;
  IF v_owner IS NOT NULL AND p_actor = v_owner THEN
    RAISE EXCEPTION 'design principle rejected (separation_of_duties): the owner of the asset never decides an exception that expands their own authority (ES-02-004)' USING ERRCODE = '42501';
  END IF;
  PERFORM governance.assert_approver('design principle', p_actor, NULL, NULL, ARRAY['design_system_authority'], x.requested_by, CASE WHEN v_owner IS NULL THEN NULL ELSE ARRAY[v_owner] END, 'deciding a design exception');
  IF x.state <> 'requested' THEN RAISE EXCEPTION 'design principle rejected (state): the exception is %', x.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM x.digest THEN RAISE EXCEPTION 'design principle rejected (stale): the decision names a digest other than the exception''s' USING ERRCODE = '23505'; END IF;
  IF p_decision NOT IN ('approve', 'reject') THEN RAISE EXCEPTION 'design principle rejected (decision): approve or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'design principle rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'approve' THEN
    IF x.expires_at <= clock_timestamp() THEN RAISE EXCEPTION 'design principle rejected (expired): the exception''s window ended at % — request a new one', x.expires_at USING ERRCODE = '23505'; END IF;
    IF NOT EXISTS (SELECT 1 FROM governance.design_assets a WHERE a.asset_id = x.asset_id AND a.version = x.asset_version AND a.superseded_at IS NULL) THEN
      RAISE EXCEPTION 'design principle rejected (stale): the asset moved past version % — an exception is narrow to the version it names', x.asset_version USING ERRCODE = '23505';
    END IF;
    IF NOT governance.dg_signature_ok(p_signature, 'exception_approval', p_exception, 1, x.digest, p_actor, 'governance.design.exception.decide') THEN
      RAISE EXCEPTION 'design principle rejected (signature): an approval carries the decider''s signature over the exception''s digest' USING ERRCODE = '22023';
    END IF;
  END IF;
  UPDATE governance.design_exceptions SET state = CASE p_decision WHEN 'approve' THEN 'approved' ELSE 'rejected' END, decided_by = p_actor, decided_at = clock_timestamp(),
         decision_reason = btrim(p_reason), signature_id = CASE p_decision WHEN 'approve' THEN p_signature END WHERE exception_id = p_exception;
  PERFORM governance.dg_artifact(p_exception, 'exception', 'DX:' || p_exception, format('Design exception: %s', x.principle_key), NULL, NULL, NULL, 'design_system_authority',
                                 CASE p_decision WHEN 'approve' THEN 'active' ELSE 'retired' END,
                                 jsonb_build_object('class', 'design', 'principle', x.principle_key, 'expires_at', x.expires_at, 'renews', x.renews), x.digest, p_actor, p_corr);
  PERFORM governance.ledger(NULL, NULL, 'design_exception', p_exception, NULL, 'design.exception_' || CASE p_decision WHEN 'approve' THEN 'approved' ELSE 'rejected' END, p_actor,
            jsonb_build_object('reason', btrim(p_reason), 'signature_id', p_signature, 'expires_at', x.expires_at), p_corr);
  RETURN jsonb_build_object('exception_id', p_exception, 'state', CASE p_decision WHEN 'approve' THEN 'approved' ELSE 'rejected' END, 'expires_at', x.expires_at, 'signature_id', p_signature);
END $$;
REVOKE ALL ON FUNCTION governance.dg_decide_exception(uuid, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_decide_exception(uuid, text, text, text, uuid, uuid, uuid) TO eye_commit;

-- §DG.7 THE CONTRIBUTION QUEUE (UX-72; UX-ADR-024) ──────────────────────────────────────────────────────────────────────────────────────────
/* What HOLDS a contribution (UX-72-005: ownership missing, evidence incomplete, a non-conformant design, a deprecation or retirement that would
   strand consumers, a target that moved on) — each reason in words with the hold class it opens. Computed, never stored as truth. */
CREATE OR REPLACE FUNCTION governance.dg_contribution_blockers(c governance.design_contributions) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE t governance.design_assets%ROWTYPE; v jsonb := '[]'::jsonb; v_owner uuid; k text; e governance.design_evaluations%ROWTYPE; v_map jsonb; v_missing jsonb; v_tests jsonb;
BEGIN
  IF c.target_asset_id IS NOT NULL THEN
    SELECT * INTO t FROM governance.design_assets a WHERE a.asset_id = c.target_asset_id AND a.superseded_at IS NULL;
    IF t.version IS DISTINCT FROM c.target_version THEN
      v := v || jsonb_build_object('class', 'evidence_missing', 'reason', format('the target moved on (v%s is current, the proposal names v%s) — amend it against the current version', t.version, c.target_version));
    END IF;
    IF t.status = 'retired' THEN v := v || jsonb_build_object('class', 'evidence_missing', 'reason', 'the target is retired'); END IF;
  ELSIF c.kind NOT IN ('new_component', 'new_pattern', 'amendment') THEN
    v := v || jsonb_build_object('class', 'evidence_missing', 'reason', 'the proposal names no target asset — a contributor amends it to name the component or pattern it changes');
  END IF;
  IF c.kind IN ('new_component', 'new_pattern', 'component_change', 'pattern_change') THEN
    v_owner := coalesce(nullif(c.proposal ->> 'ownerPrincipalId', '')::uuid, t.owner_principal_id);
    IF v_owner IS NULL OR governance.dg_kind(v_owner) IS DISTINCT FROM 'human' THEN
      v := v || jsonb_build_object('class', 'ownership_gap', 'reason', 'ownership is missing — the resulting version names one accountable owner, a named active human (REL-01)');
    END IF;
  END IF;
  IF c.kind IN ('new_component', 'new_pattern', 'component_change', 'pattern_change', 'amendment') THEN
    FOREACH k IN ARRAY CASE WHEN c.kind IN ('new_component', 'new_pattern') THEN ARRAY['rollback'] ELSE ARRAY['compatibility', 'consumers', 'migration', 'rollback'] END LOOP
      IF length(btrim(coalesce(c.plans ->> k, ''))) < 8 THEN v := v || jsonb_build_object('class', 'evidence_missing', 'reason', format('the %s plan is missing (8+ characters)', k)); END IF;
    END LOOP;
    v_tests := c.plans -> 'tests';
    IF jsonb_typeof(v_tests) IS DISTINCT FROM 'array' OR jsonb_array_length(v_tests) = 0 THEN
      v := v || jsonb_build_object('class', 'evidence_missing', 'reason', 'the contribution names the tests that verify it (plans.tests)');
    END IF;
    IF nullif(c.plans ->> 'evaluationId', '') IS NULL THEN
      v := v || jsonb_build_object('class', 'evidence_missing', 'reason', 'the proposed design has no evaluation against the principles (UX-03-003) — run the lint or record a review and name it');
    ELSE
      SELECT * INTO e FROM governance.design_evaluations x WHERE x.evaluation_id = (c.plans ->> 'evaluationId')::uuid;
      IF NOT FOUND THEN v := v || jsonb_build_object('class', 'evidence_missing', 'reason', 'the named evaluation does not exist');
      ELSIF e.verdict <> 'conformant' THEN
        v := v || jsonb_build_object('class', 'evidence_missing', 'reason', format('the design evaluation is nonconformant (%s open finding(s): %s) — the non-conformant pattern is blocked until remediated or narrowly excepted (UX-03-005)',
                                     e.counts ->> 'open', (SELECT string_agg(DISTINCT f ->> 'principle', ', ') FROM jsonb_array_elements(e.findings) f WHERE f ->> 'status' = 'open')));
      END IF;
    END IF;
  END IF;
  IF c.kind = 'deprecation' AND t.asset_id IS NOT NULL THEN
    v_map := coalesce(c.plans -> 'migrationMap', '{}'::jsonb);
    SELECT jsonb_agg(x) INTO v_missing FROM jsonb_array_elements_text(t.consumers) x WHERE length(btrim(coalesce(v_map ->> x, ''))) = 0;
    IF v_missing IS NOT NULL THEN
      v := v || jsonb_build_object('class', 'evidence_missing', 'reason', format('the deprecation would strand %s consumer(s) with no migration target: %s', jsonb_array_length(v_missing),
                                   (SELECT string_agg(y, ', ') FROM jsonb_array_elements_text(v_missing) y)));
    END IF;
  END IF;
  IF c.kind = 'retirement' AND t.asset_id IS NOT NULL THEN
    IF t.status <> 'deprecated' THEN v := v || jsonb_build_object('class', 'evidence_missing', 'reason', 'only a deprecated asset is retired (deprecate and migrate first)'); END IF;
    IF jsonb_array_length(t.consumers) > 0 THEN
      v := v || jsonb_build_object('class', 'evidence_missing', 'reason', format('retirement would strand %s consumer(s): %s', jsonb_array_length(t.consumers), (SELECT string_agg(y, ', ') FROM jsonb_array_elements_text(t.consumers) y)));
    END IF;
  END IF;
  RETURN v;
END $$;
REVOKE ALL ON FUNCTION governance.dg_contribution_blockers(governance.design_contributions) FROM PUBLIC;

/* The digest of a contribution's revision (what a reviewer reads and an authority accepts). */
CREATE OR REPLACE FUNCTION governance.dg_contribution_digest(c governance.design_contributions) RETURNS text
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT governance.digest(jsonb_build_object('contribution_id', c.contribution_id, 'revision', c.revision, 'kind', c.kind, 'target', c.target_asset_id, 'target_version', c.target_version,
                                              'proposal', c.proposal, 'summary', c.summary, 'plans', c.plans, 'constitutional', c.constitutional, 'origin', c.origin, 'intake_id', c.intake_id))
$$;
REVOKE ALL ON FUNCTION governance.dg_contribution_digest(governance.design_contributions) FROM PUBLIC;

/* Validate a contribution's shape (kind × target × proposal); raise in the class form. */
CREATE OR REPLACE FUNCTION governance.dg_contribution_shape(p_kind text, p_target uuid, p_proposal jsonb, p_summary text, p_plans jsonb, p_constitutional boolean, p_origin text) RETURNS int
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE t governance.design_assets%ROWTYPE;
BEGIN
  IF coalesce(p_kind, '') NOT IN ('new_component', 'component_change', 'new_pattern', 'pattern_change', 'deprecation', 'retirement', 'amendment') THEN
    RAISE EXCEPTION 'design contribution rejected (kind): % is not a contribution kind', coalesce(p_kind, '<none>') USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_proposal) IS DISTINCT FROM 'object' OR jsonb_typeof(coalesce(p_plans, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'design contribution rejected (proposal): the proposal and its plans are objects' USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_summary, ''))) < 12 THEN RAISE EXCEPTION 'design contribution rejected (summary): a contribution states what it changes and why (12+ characters)' USING ERRCODE = '22023'; END IF;
  IF coalesce(p_constitutional, false) AND p_kind <> 'amendment' THEN
    RAISE EXCEPTION 'design contribution rejected (constitutional): design governance refines expression within the frozen architecture; constitutional meaning changes only through an explicit amendment ratified by the product authority (UX-72-004)' USING ERRCODE = '22023';
  END IF;
  IF p_kind IN ('new_component', 'new_pattern') THEN
    IF p_target IS NOT NULL THEN RAISE EXCEPTION 'design contribution rejected (target): a new % names no target', replace(p_kind, 'new_', '') USING ERRCODE = '22023'; END IF;
    IF coalesce(p_proposal ->> 'assetKey', '') !~ '^[a-z][a-z0-9_.-]{2,120}$' OR length(btrim(coalesce(p_proposal ->> 'title', ''))) < 3 OR length(btrim(coalesce(p_proposal ->> 'sourceRef', ''))) < 3
       OR coalesce(p_proposal ->> 'packageVersion', '') !~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.-]+)?$' THEN
      RAISE EXCEPTION 'design contribution rejected (proposal): a new asset states its key, title, source and package version (semver)' USING ERRCODE = '22023';
    END IF;
    IF EXISTS (SELECT 1 FROM governance.design_assets a WHERE a.asset_key = p_proposal ->> 'assetKey' AND a.superseded_at IS NULL) THEN
      RAISE EXCEPTION 'design contribution rejected (duplicate): % is already a design asset — propose a change to it', p_proposal ->> 'assetKey' USING ERRCODE = '23505';
    END IF;
  ELSIF p_target IS NOT NULL THEN
    SELECT * INTO t FROM governance.design_assets a WHERE a.asset_id = p_target AND a.superseded_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'design contribution rejected (unknown_asset): % is not a current design asset', p_target USING ERRCODE = '23503'; END IF;
    IF (p_kind = 'component_change' AND t.kind NOT IN ('design_component', 'design_asset')) OR (p_kind = 'pattern_change' AND t.kind <> 'pattern') THEN
      RAISE EXCEPTION 'design contribution rejected (target): a % changes a %', p_kind, CASE p_kind WHEN 'pattern_change' THEN 'pattern' ELSE 'component or design asset' END USING ERRCODE = '22023';
    END IF;
    IF p_kind IN ('component_change', 'pattern_change') AND coalesce(p_proposal ->> 'packageVersion', '') !~ '^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.-]+)?$' THEN
      RAISE EXCEPTION 'design contribution rejected (proposal): a change names the next package version (semver)' USING ERRCODE = '22023';
    END IF;
    IF p_kind IN ('component_change', 'pattern_change') AND (p_proposal ->> 'packageVersion') = t.package_version THEN
      RAISE EXCEPTION 'design contribution rejected (proposal): a change names a package version other than the current one (%)', t.package_version USING ERRCODE = '22023';
    END IF;
    RETURN t.version;
  ELSIF p_kind IN ('deprecation', 'retirement') OR (p_kind IN ('component_change', 'pattern_change') AND coalesce(p_origin, 'contributor') <> 'experience_learning') THEN
    RAISE EXCEPTION 'design contribution rejected (target): a % names the asset it acts on', p_kind USING ERRCODE = '22023';
  END IF;
  RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION governance.dg_contribution_shape(text, uuid, jsonb, text, jsonb, boolean, text) FROM PUBLIC;

/* Insert a contribution (the propose port and the experience intake share it). */
CREATE OR REPLACE FUNCTION governance.dg_insert_contribution(p_id uuid, p_kind text, p_target uuid, p_proposal jsonb, p_summary text, p_plans jsonb, p_constitutional boolean, p_origin text,
                                                            p_intake uuid, p_proposer uuid, p_actor uuid, p_corr uuid) RETURNS governance.design_contributions
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE c governance.design_contributions%ROWTYPE; v_tv int;
BEGIN
  v_tv := governance.dg_contribution_shape(p_kind, p_target, p_proposal, p_summary, p_plans, p_constitutional, p_origin);
  c.contribution_id := p_id; c.scope := 'PLATFORM'; c.revision := 1; c.kind := p_kind; c.target_asset_id := p_target; c.target_version := v_tv; c.proposal := p_proposal;
  c.summary := btrim(p_summary); c.plans := coalesce(p_plans, '{}'::jsonb); c.constitutional := coalesce(p_constitutional, false); c.origin := p_origin; c.intake_id := p_intake;
  c.stage := 'proposed'; c.hold_reasons := '[]'::jsonb; c.evidence := '[]'::jsonb; c.proposed_by := p_proposer; c.proposed_by_kind := coalesce(governance.dg_kind(p_proposer), 'system');
  c.proposed_at := clock_timestamp(); c.builders := '{}'; c.updated_at := clock_timestamp(); c.correlation_id := p_corr;
  c.digest := governance.dg_contribution_digest(c);
  INSERT INTO governance.design_contributions SELECT c.*;
  PERFORM governance.dg_artifact(p_id, 'change_proposal', 'DSC:' || p_id, left(format('Design contribution (%s): %s', p_kind, btrim(p_summary)), 500), NULL, NULL, NULL, 'design_system_authority', 'proposed',
                                 jsonb_build_object('class', 'design_contribution', 'kind', p_kind, 'origin', p_origin, 'stage', 'proposed', 'revision', 1), c.digest, p_actor, p_corr);
  IF p_target IS NOT NULL THEN PERFORM governance.dg_link(p_id, p_target, 'contributes_to', NULL, NULL, jsonb_build_object('target_version', v_tv), p_actor, p_corr); END IF;
  PERFORM governance.ledger(NULL, NULL, 'design_contribution', p_id, 1, 'design.contribution_proposed', p_actor,
            jsonb_build_object('kind', p_kind, 'target', p_target, 'origin', p_origin, 'intake_id', p_intake, 'proposer', p_proposer, 'digest', c.digest), p_corr);
  RETURN c;
END $$;
REVOKE ALL ON FUNCTION governance.dg_insert_contribution(uuid, text, uuid, jsonb, text, jsonb, boolean, text, uuid, uuid, uuid, uuid) FROM PUBLIC;

/* PROPOSE a contribution (a contributor: the Design System Authority, the product authority, the conformance steward, the operations
   authority — an AGENT may propose; proposals are never approvals). */
CREATE OR REPLACE FUNCTION governance.dg_propose_contribution(p_id uuid, p_kind text, p_target uuid, p_proposal jsonb, p_summary text, p_plans jsonb, p_constitutional boolean,
                                                             p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE c governance.design_contributions%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.design.contribution.propose', p_actor, 'design contribution');
  c := governance.dg_insert_contribution(p_id, p_kind, p_target, p_proposal, p_summary, p_plans, p_constitutional, 'contributor', NULL, p_actor, p_actor, p_corr);
  RETURN to_jsonb(c) - 'scope' - 'tenant_id' - 'domain_id' || jsonb_build_object('blockers', governance.dg_contribution_blockers(c));
END $$;
REVOKE ALL ON FUNCTION governance.dg_propose_contribution(uuid, text, uuid, jsonb, text, jsonb, boolean, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_propose_contribution(uuid, text, uuid, jsonb, text, jsonb, boolean, uuid, uuid) TO eye_commit;

/* AMEND a contribution at the next revision (proposed / in review / held): its proposer, or a contributor — who is then recorded as a BUILDER
   and never accepts it. The review restarts; open holds are lifted with the reason. */
CREATE OR REPLACE FUNCTION governance.dg_amend_contribution(p_id uuid, p_revision int, p_target uuid, p_proposal jsonb, p_summary text, p_plans jsonb, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE c governance.design_contributions%ROWTYPE; v_tv int;
BEGIN
  PERFORM governance.assert_platform('governance.design.contribution.amend', p_actor, 'design contribution');
  SELECT * INTO c FROM governance.design_contributions x WHERE x.contribution_id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'design contribution rejected (unknown_contribution): no contribution %', p_id USING ERRCODE = '23503'; END IF;
  IF c.stage NOT IN ('proposed', 'in_review', 'held') THEN RAISE EXCEPTION 'design contribution rejected (state): a % contribution is no longer amended', c.stage USING ERRCODE = '23505'; END IF;
  IF p_revision IS DISTINCT FROM c.revision THEN RAISE EXCEPTION 'design contribution rejected (stale): the contribution is at revision %, not %', c.revision, coalesce(p_revision::text, '<none>') USING ERRCODE = '23505'; END IF;
  v_tv := governance.dg_contribution_shape(c.kind, p_target, p_proposal, p_summary, p_plans, c.constitutional, c.origin);
  c.revision := c.revision + 1; c.target_asset_id := p_target; c.target_version := v_tv; c.proposal := p_proposal; c.summary := btrim(p_summary); c.plans := coalesce(p_plans, '{}'::jsonb);
  c.stage := 'proposed'; c.hold_reasons := '[]'::jsonb; c.review := NULL; c.reviewed_by := NULL; c.updated_at := clock_timestamp();
  IF p_actor <> c.proposed_by AND NOT (p_actor = ANY (c.builders)) THEN c.builders := c.builders || p_actor; END IF;
  c.digest := governance.dg_contribution_digest(c);
  UPDATE governance.design_contributions SET revision = c.revision, target_asset_id = c.target_asset_id, target_version = c.target_version, proposal = c.proposal, summary = c.summary,
         plans = c.plans, stage = c.stage, hold_reasons = c.hold_reasons, review = NULL, reviewed_by = NULL, builders = c.builders, digest = c.digest, updated_at = c.updated_at WHERE contribution_id = p_id;
  PERFORM governance.dg_lift(p_id, format('amended to revision %s', c.revision), p_actor);
  PERFORM governance.dg_artifact(p_id, 'change_proposal', 'DSC:' || p_id, left(format('Design contribution (%s): %s', c.kind, c.summary), 500), NULL, NULL, NULL, 'design_system_authority', 'proposed',
                                 jsonb_build_object('class', 'design_contribution', 'kind', c.kind, 'origin', c.origin, 'stage', 'proposed', 'revision', c.revision), c.digest, p_actor, p_corr);
  IF p_target IS NOT NULL THEN PERFORM governance.dg_link(p_id, p_target, 'contributes_to', NULL, NULL, jsonb_build_object('target_version', v_tv), p_actor, p_corr); END IF;
  PERFORM governance.ledger(NULL, NULL, 'design_contribution', p_id, c.revision, 'design.contribution_amended', p_actor, jsonb_build_object('digest', c.digest, 'builders', to_jsonb(c.builders)), p_corr);
  RETURN to_jsonb(c) - 'scope' - 'tenant_id' - 'domain_id' || jsonb_build_object('blockers', governance.dg_contribution_blockers(c));
END $$;
REVOKE ALL ON FUNCTION governance.dg_amend_contribution(uuid, int, uuid, jsonb, text, jsonb, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_amend_contribution(uuid, int, uuid, jsonb, text, jsonb, uuid, uuid) TO eye_commit;

/* Write the next VERSION of an asset (publish, deprecate, retire, adoption's consumers): the current version superseded, the artifact re-versioned. */
CREATE OR REPLACE FUNCTION governance.dg_next_asset_version(p_asset uuid, p_status text, p_package_version text, p_source_ref text, p_owner uuid, p_consumers jsonb, p_contribution uuid,
                                                           p_approved_by uuid, p_reason text, p_actor uuid, p_corr uuid) RETURNS governance.design_assets
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE cur governance.design_assets%ROWTYPE; n governance.design_assets%ROWTYPE;
BEGIN
  SELECT * INTO cur FROM governance.design_assets a WHERE a.asset_id = p_asset AND a.superseded_at IS NULL FOR UPDATE;
  UPDATE governance.design_assets SET status = 'superseded', superseded_at = clock_timestamp() WHERE asset_id = p_asset AND version = cur.version;
  n := cur; n.version := cur.version + 1; n.status := p_status; n.package_version := coalesce(p_package_version, cur.package_version); n.source_ref := coalesce(p_source_ref, cur.source_ref);
  n.owner_principal_id := coalesce(p_owner, cur.owner_principal_id); n.consumers := coalesce(p_consumers, cur.consumers); n.contribution_id := coalesce(p_contribution, cur.contribution_id);
  n.approved_by := coalesce(p_approved_by, cur.approved_by); n.approved_at := CASE WHEN p_approved_by IS NULL THEN cur.approved_at ELSE clock_timestamp() END;
  n.approval_reason := coalesce(p_reason, cur.approval_reason); n.superseded_at := NULL; n.registered_by := p_actor; n.registered_at := clock_timestamp(); n.correlation_id := p_corr;
  IF p_package_version IS NOT NULL AND p_package_version <> cur.package_version THEN n.source_digest := NULL; END IF;
  n.digest := governance.dg_asset_digest(n);
  INSERT INTO governance.design_assets SELECT n.*;
  PERFORM governance.dg_artifact(n.asset_id, n.kind, 'DS:' || n.asset_key, n.title, NULL, NULL, n.owner_principal_id, 'design_system_authority',
                                 CASE n.status WHEN 'approved' THEN 'active' WHEN 'deprecated' THEN 'deprecated' WHEN 'retired' THEN 'retired' ELSE 'proposed' END,
                                 jsonb_build_object('source_ref', n.source_ref, 'package_version', n.package_version, 'asset_version', n.version), n.digest, p_actor, p_corr);
  RETURN n;
END $$;
REVOKE ALL ON FUNCTION governance.dg_next_asset_version(uuid, text, text, text, uuid, jsonb, uuid, uuid, text, uuid, uuid) FROM PUBLIC;

/* ADVANCE a contribution one governed step. Each step is its own action (governance.design.contribution.<step>) and its own rule:
     review    (the Design System Authority, a named human, never the proposer or a builder): the blockers computed — any → HELD (the
               contribution preserved, its hold reasons shown, governance.holds opened: ownership_gap | evidence_missing); none → in_review;
     accept    (human-gated, SIGNED `design_contribution`, on the exact digest of an in_review revision): the Design System Authority — or, for a
               constitutional AMENDMENT, the product authority (ratification, UX-72-004); never the proposer, never a builder; the blockers
               re-read — any → HELD (409);
     reject    (the Design System Authority or the product authority; never the proposer): the prior baseline and consumers untouched;
     publish   (an accepted change or new asset): the asset's next version written `approved` (the prior one superseded, still readable);
     deprecate (an accepted deprecation): the asset's next version `deprecated`, the migration map recorded;
     adopt     (the steward or the authority): adoption evidence; a DIVERGENT adopter → the asset HELD (conformance_drift), stage unchanged;
     measure   (after adoption): measurement evidence (e.g. B92 telemetry / metric results by reference) — telemetry never changes a pattern;
     migrate   (a deprecation being migrated): consumers moved off the deprecated version;
     retire    (human-gated): only when no consumer remains — otherwise HELD (409: it would strand consumers);
     close     (human-gated): a measured, retired or rejected contribution closed with its reason. */
CREATE OR REPLACE FUNCTION governance.dg_advance_contribution(p_id uuid, p_step text, p_revision int, p_digest text, p_reason text, p_evidence jsonb, p_signature uuid,
                                                             p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE c governance.design_contributions%ROWTYPE; t governance.design_assets%ROWTYPE; n governance.design_assets%ROWTYPE; v_blockers jsonb; v_action text; v_held boolean := false;
        v_class text; v_new uuid; v_ev jsonb := coalesce(p_evidence, '{}'::jsonb); v_list jsonb; v_div jsonb; v_consumers jsonb; v_hold uuid; v_out jsonb := '{}'::jsonb; v_roles text[];
BEGIN
  IF coalesce(p_step, '') NOT IN ('review', 'accept', 'reject', 'publish', 'deprecate', 'adopt', 'measure', 'migrate', 'retire', 'close') THEN
    RAISE EXCEPTION 'design contribution rejected (step): % is not a contribution step', coalesce(p_step, '<none>') USING ERRCODE = '22023';
  END IF;
  v_action := 'governance.design.contribution.' || p_step;
  PERFORM governance.assert_platform(v_action, p_actor, 'design contribution');
  SELECT * INTO c FROM governance.design_contributions x WHERE x.contribution_id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'design contribution rejected (unknown_contribution): no contribution %', p_id USING ERRCODE = '23503'; END IF;
  IF p_revision IS DISTINCT FROM c.revision THEN RAISE EXCEPTION 'design contribution rejected (stale): the contribution is at revision %, not %', c.revision, coalesce(p_revision::text, '<none>') USING ERRCODE = '23505'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'design contribution rejected (reason): a step states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF c.target_asset_id IS NOT NULL THEN SELECT * INTO t FROM governance.design_assets a WHERE a.asset_id = c.target_asset_id AND a.superseded_at IS NULL FOR UPDATE; END IF;

  IF p_step IN ('review', 'accept', 'reject', 'publish', 'deprecate', 'retire', 'close') THEN
    v_roles := CASE WHEN p_step IN ('accept', 'reject') AND c.constitutional THEN ARRAY['product_authority']
                    WHEN p_step = 'reject' THEN ARRAY['design_system_authority', 'product_authority'] ELSE ARRAY['design_system_authority'] END;
    PERFORM governance.assert_approver('design contribution', p_actor, NULL, NULL, v_roles, c.proposed_by, c.builders,
              CASE p_step WHEN 'accept' THEN CASE WHEN c.constitutional THEN 'ratifying a constitutional amendment' ELSE 'accepting a design contribution' END
                          ELSE format('the %s step of a design contribution', p_step) END);
  END IF;

  IF p_step = 'review' THEN
    IF c.stage NOT IN ('proposed', 'held') THEN RAISE EXCEPTION 'design contribution rejected (state): a % contribution is not reviewed', c.stage USING ERRCODE = '23505'; END IF;
    v_blockers := governance.dg_contribution_blockers(c);
    IF jsonb_array_length(v_blockers) > 0 THEN
      v_held := true;
      v_class := CASE WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers) b WHERE b ->> 'class' = 'ownership_gap') THEN 'ownership_gap' ELSE 'evidence_missing' END;
      v_hold := governance.dg_hold(p_id, v_class, left(format('design contribution held at review: %s', (SELECT string_agg(b ->> 'reason', '; ') FROM jsonb_array_elements(v_blockers) b)), 2000), NULL, NULL, p_actor, p_corr);
    END IF;
    UPDATE governance.design_contributions SET stage = CASE WHEN v_held THEN 'held' ELSE 'in_review' END, hold_reasons = v_blockers, reviewed_by = p_actor,
           review = jsonb_build_object('by', p_actor, 'at', clock_timestamp(), 'notes', btrim(p_reason), 'blockers', v_blockers, 'revision', c.revision), updated_at = clock_timestamp() WHERE contribution_id = p_id;
    IF NOT v_held THEN PERFORM governance.dg_lift(p_id, 'reviewed: no blocker remains', p_actor); END IF;
    v_out := jsonb_build_object('stage', CASE WHEN v_held THEN 'held' ELSE 'in_review' END, 'held', v_held, 'blockers', v_blockers, 'hold_id', v_hold);

  ELSIF p_step = 'accept' THEN
    IF c.stage <> 'in_review' THEN RAISE EXCEPTION 'design contribution rejected (state): only a reviewed (in_review) contribution is accepted — this one is %', c.stage USING ERRCODE = '23505'; END IF;
    IF p_digest IS DISTINCT FROM c.digest THEN RAISE EXCEPTION 'design contribution rejected (stale): the acceptance names a digest other than revision %''s', c.revision USING ERRCODE = '23505'; END IF;
    v_blockers := governance.dg_contribution_blockers(c);
    IF jsonb_array_length(v_blockers) > 0 THEN
      v_class := CASE WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers) b WHERE b ->> 'class' = 'ownership_gap') THEN 'ownership_gap' ELSE 'evidence_missing' END;
      v_hold := governance.dg_hold(p_id, v_class, left(format('design contribution held at acceptance: %s', (SELECT string_agg(b ->> 'reason', '; ') FROM jsonb_array_elements(v_blockers) b)), 2000), NULL, NULL, p_actor, p_corr);
      UPDATE governance.design_contributions SET stage = 'held', hold_reasons = v_blockers, updated_at = clock_timestamp() WHERE contribution_id = p_id;
      PERFORM governance.ledger(NULL, NULL, 'design_contribution', p_id, c.revision, 'design.contribution_held', p_actor, jsonb_build_object('blockers', v_blockers, 'hold_id', v_hold), p_corr);
      RETURN jsonb_build_object('contribution_id', p_id, 'held', true, 'stage', 'held', 'blockers', v_blockers, 'hold_id', v_hold);
    END IF;
    IF NOT governance.dg_signature_ok(p_signature, 'design_contribution', p_id, c.revision, c.digest, p_actor, v_action) THEN
      RAISE EXCEPTION 'design contribution rejected (signature): an acceptance carries the authority''s signature over the revision''s digest' USING ERRCODE = '22023';
    END IF;
    UPDATE governance.design_contributions SET stage = 'accepted', accepted_by = p_actor, accepted_at = clock_timestamp(), signature_id = p_signature, hold_reasons = '[]'::jsonb, updated_at = clock_timestamp()
     WHERE contribution_id = p_id;
    v_out := jsonb_build_object('stage', 'accepted', 'signature_id', p_signature);

  ELSIF p_step = 'reject' THEN
    IF c.stage NOT IN ('proposed', 'in_review', 'held', 'accepted') THEN RAISE EXCEPTION 'design contribution rejected (state): a % contribution is not rejected', c.stage USING ERRCODE = '23505'; END IF;
    UPDATE governance.design_contributions SET stage = 'rejected', closed_reason = btrim(p_reason), updated_at = clock_timestamp() WHERE contribution_id = p_id;
    PERFORM governance.dg_lift(p_id, 'rejected: ' || btrim(p_reason), p_actor);
    v_out := jsonb_build_object('stage', 'rejected', 'preserved', 'the prior baseline, asset versions and consumers are untouched');

  ELSIF p_step = 'publish' THEN
    IF c.stage <> 'accepted' OR c.kind IN ('deprecation', 'retirement') THEN
      RAISE EXCEPTION 'design contribution rejected (state): publish takes an accepted change, new asset or amendment (this one is % · %)', c.kind, c.stage USING ERRCODE = '23505';
    END IF;
    IF c.kind IN ('new_component', 'new_pattern') THEN
      v_new := gen_random_uuid();
      n := ROW(v_new, 1, 'PLATFORM', NULL, NULL, CASE c.kind WHEN 'new_pattern' THEN 'pattern' ELSE coalesce(c.proposal ->> 'assetKind', 'design_component') END, c.proposal ->> 'assetKey',
               btrim(c.proposal ->> 'title'), btrim(c.proposal ->> 'sourceRef'), c.proposal ->> 'packageVersion', NULL, coalesce(c.proposal -> 'consumers', '[]'::jsonb),
               (c.proposal ->> 'ownerPrincipalId')::uuid, 'approved', p_id, repeat('0', 64), p_actor, clock_timestamp(), c.accepted_by, clock_timestamp(), 'accepted contribution ' || p_id, NULL, p_corr)::governance.design_assets;
      IF n.kind NOT IN ('design_component', 'pattern', 'design_asset') THEN n.kind := 'design_component'; END IF;
      n.digest := governance.dg_asset_digest(n);
      INSERT INTO governance.design_assets SELECT n.*;
      PERFORM governance.dg_artifact(n.asset_id, n.kind, 'DS:' || n.asset_key, n.title, NULL, NULL, n.owner_principal_id, 'design_system_authority', 'active',
                                     jsonb_build_object('source_ref', n.source_ref, 'package_version', n.package_version, 'asset_version', 1), n.digest, p_actor, p_corr);
      PERFORM governance.dg_link(p_id, n.asset_id, 'contributes_to', NULL, NULL, jsonb_build_object('published_version', 1), p_actor, p_corr);
    ELSIF c.target_asset_id IS NOT NULL THEN
      n := governance.dg_next_asset_version(c.target_asset_id, 'approved', c.proposal ->> 'packageVersion', nullif(c.proposal ->> 'sourceRef', ''), nullif(c.proposal ->> 'ownerPrincipalId', '')::uuid,
                                            NULL, p_id, c.accepted_by, 'accepted contribution ' || p_id, p_actor, p_corr);
    END IF;
    UPDATE governance.design_contributions SET stage = 'published', published_version = n.version, updated_at = clock_timestamp() WHERE contribution_id = p_id;
    v_out := jsonb_build_object('stage', 'published', 'asset_id', n.asset_id, 'asset_version', n.version, 'asset_digest', n.digest);

  ELSIF p_step = 'deprecate' THEN
    IF c.stage <> 'accepted' OR c.kind <> 'deprecation' THEN RAISE EXCEPTION 'design contribution rejected (state): deprecate takes an accepted deprecation' USING ERRCODE = '23505'; END IF;
    n := governance.dg_next_asset_version(c.target_asset_id, 'deprecated', NULL, NULL, NULL, NULL, p_id, NULL, 'deprecated by contribution ' || p_id, p_actor, p_corr);
    UPDATE governance.design_contributions SET stage = 'deprecated', published_version = n.version, updated_at = clock_timestamp() WHERE contribution_id = p_id;
    v_out := jsonb_build_object('stage', 'deprecated', 'asset_id', n.asset_id, 'asset_version', n.version, 'consumers', n.consumers, 'migration_map', c.plans -> 'migrationMap');

  ELSIF p_step = 'adopt' THEN
    IF c.stage NOT IN ('published', 'adopted') THEN RAISE EXCEPTION 'design contribution rejected (state): adoption follows publication (this one is %)', c.stage USING ERRCODE = '23505'; END IF;
    v_list := coalesce(v_ev -> 'adopted', '[]'::jsonb); v_div := coalesce(v_ev -> 'divergent', '[]'::jsonb);
    IF jsonb_typeof(v_list) <> 'array' OR jsonb_typeof(v_div) <> 'array' OR (jsonb_array_length(v_list) + jsonb_array_length(v_div)) = 0 THEN
      RAISE EXCEPTION 'design contribution rejected (evidence): adoption names the consumers that adopted (adopted) and any that diverge (divergent)' USING ERRCODE = '22023';
    END IF;
    v_new := coalesce(t.asset_id, (SELECT a.asset_id FROM governance.design_assets a WHERE a.contribution_id = p_id AND a.superseded_at IS NULL LIMIT 1));
    IF jsonb_array_length(v_div) > 0 THEN
      v_hold := governance.dg_hold(v_new, 'conformance_drift', left(format('adoption diverges from the published version: %s', v_div::text), 2000), NULL, NULL, p_actor, p_corr);
      UPDATE governance.design_contributions SET hold_reasons = jsonb_build_array(jsonb_build_object('class', 'conformance_drift', 'reason', 'adoption diverges', 'divergent', v_div)),
             evidence = evidence || jsonb_build_array(jsonb_build_object('step', 'adopt', 'at', clock_timestamp(), 'by', p_actor, 'adopted', v_list, 'divergent', v_div)), updated_at = clock_timestamp()
       WHERE contribution_id = p_id;
      v_held := true;
      v_out := jsonb_build_object('stage', c.stage, 'held', true, 'hold_id', v_hold, 'divergent', v_div);
    ELSE
      SELECT coalesce(jsonb_agg(DISTINCT x), '[]'::jsonb) INTO v_consumers FROM (SELECT jsonb_array_elements_text(a.consumers) x FROM governance.design_assets a WHERE a.asset_id = v_new AND a.superseded_at IS NULL
                                                                                UNION SELECT jsonb_array_elements_text(v_list)) q;
      UPDATE governance.design_assets SET consumers = v_consumers WHERE asset_id = v_new AND superseded_at IS NULL;
      UPDATE governance.design_assets a SET digest = governance.dg_asset_digest(a) WHERE a.asset_id = v_new AND a.superseded_at IS NULL;
      PERFORM governance.dg_lift(v_new, 'adoption confirmed without divergence', p_actor);
      UPDATE governance.design_contributions SET stage = 'adopted', hold_reasons = '[]'::jsonb,
             evidence = evidence || jsonb_build_array(jsonb_build_object('step', 'adopt', 'at', clock_timestamp(), 'by', p_actor, 'adopted', v_list)), updated_at = clock_timestamp() WHERE contribution_id = p_id;
      v_out := jsonb_build_object('stage', 'adopted', 'consumers', v_consumers);
    END IF;

  ELSIF p_step = 'measure' THEN
    IF c.stage NOT IN ('adopted', 'measured') THEN RAISE EXCEPTION 'design contribution rejected (state): measurement follows adoption (this one is %)', c.stage USING ERRCODE = '23505'; END IF;
    v_list := v_ev -> 'measures';
    IF jsonb_typeof(v_list) IS DISTINCT FROM 'array' OR jsonb_array_length(v_list) = 0
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_list) m WHERE length(coalesce(m ->> 'kind', '')) < 3 OR length(coalesce(m ->> 'ref', '')) < 3) THEN
      RAISE EXCEPTION 'design contribution rejected (evidence): a measurement names its evidence by reference (kind, ref — e.g. a B92 metric result or telemetry definition)' USING ERRCODE = '22023';
    END IF;
    UPDATE governance.design_contributions SET stage = 'measured', evidence = evidence || jsonb_build_array(jsonb_build_object('step', 'measure', 'at', clock_timestamp(), 'by', p_actor, 'measures', v_list,
           'note', 'telemetry is evidence for a human decision; it never modifies a pattern (UX-ADR-024)')), updated_at = clock_timestamp() WHERE contribution_id = p_id;
    v_out := jsonb_build_object('stage', 'measured');

  ELSIF p_step = 'migrate' THEN
    IF c.kind <> 'deprecation' OR c.stage NOT IN ('deprecated', 'migrating') THEN RAISE EXCEPTION 'design contribution rejected (state): migration follows a deprecation' USING ERRCODE = '23505'; END IF;
    v_list := v_ev -> 'migrated';
    IF jsonb_typeof(v_list) IS DISTINCT FROM 'array' OR jsonb_array_length(v_list) = 0 THEN RAISE EXCEPTION 'design contribution rejected (evidence): migration names the consumers moved (migrated)' USING ERRCODE = '22023'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(v_list) m WHERE NOT (t.consumers ? m)) THEN
      RAISE EXCEPTION 'design contribution rejected (evidence): a migrated consumer is not a consumer of %', t.asset_key USING ERRCODE = '22023';
    END IF;
    SELECT coalesce(jsonb_agg(x), '[]'::jsonb) INTO v_consumers FROM jsonb_array_elements_text(t.consumers) x WHERE NOT (v_list ? x);
    UPDATE governance.design_assets SET consumers = v_consumers WHERE asset_id = t.asset_id AND superseded_at IS NULL;
    UPDATE governance.design_assets a SET digest = governance.dg_asset_digest(a) WHERE a.asset_id = t.asset_id AND a.superseded_at IS NULL;
    UPDATE governance.design_contributions SET stage = 'migrating', evidence = evidence || jsonb_build_array(jsonb_build_object('step', 'migrate', 'at', clock_timestamp(), 'by', p_actor, 'migrated', v_list,
           'to', (SELECT jsonb_object_agg(m, c.plans -> 'migrationMap' -> m) FROM jsonb_array_elements_text(v_list) m))), updated_at = clock_timestamp() WHERE contribution_id = p_id;
    v_out := jsonb_build_object('stage', 'migrating', 'remaining_consumers', v_consumers);

  ELSIF p_step = 'retire' THEN
    IF NOT ((c.kind = 'deprecation' AND c.stage IN ('deprecated', 'migrating')) OR (c.kind = 'retirement' AND c.stage = 'accepted')) THEN
      RAISE EXCEPTION 'design contribution rejected (state): retirement follows a deprecation (or an accepted retirement)' USING ERRCODE = '23505';
    END IF;
    IF jsonb_array_length(t.consumers) > 0 THEN
      v_hold := governance.dg_hold(t.asset_id, 'evidence_missing', left(format('retirement held: it would strand %s consumer(s): %s', jsonb_array_length(t.consumers), t.consumers::text), 2000), NULL, NULL, p_actor, p_corr);
      UPDATE governance.design_contributions SET hold_reasons = jsonb_build_array(jsonb_build_object('class', 'evidence_missing', 'reason', 'retirement would strand consumers', 'consumers', t.consumers)),
             updated_at = clock_timestamp() WHERE contribution_id = p_id;
      PERFORM governance.ledger(NULL, NULL, 'design_contribution', p_id, c.revision, 'design.contribution_held', p_actor, jsonb_build_object('step', 'retire', 'consumers', t.consumers, 'hold_id', v_hold), p_corr);
      RETURN jsonb_build_object('contribution_id', p_id, 'held', true, 'stage', c.stage, 'blockers', jsonb_build_array(jsonb_build_object('class', 'evidence_missing',
                                'reason', format('retirement would strand %s consumer(s)', jsonb_array_length(t.consumers)))), 'consumers', t.consumers, 'hold_id', v_hold);
    END IF;
    n := governance.dg_next_asset_version(t.asset_id, 'retired', NULL, NULL, NULL, '[]'::jsonb, p_id, NULL, 'retired by contribution ' || p_id, p_actor, p_corr);
    PERFORM governance.dg_lift(t.asset_id, 'retired with no consumer stranded', p_actor);
    UPDATE governance.design_contributions SET stage = 'retired', published_version = n.version, hold_reasons = '[]'::jsonb, updated_at = clock_timestamp() WHERE contribution_id = p_id;
    v_out := jsonb_build_object('stage', 'retired', 'asset_id', n.asset_id, 'asset_version', n.version);

  ELSIF p_step = 'close' THEN
    IF c.stage NOT IN ('measured', 'retired', 'rejected') THEN RAISE EXCEPTION 'design contribution rejected (state): a % contribution is not closed (measure, retire or reject it first)', c.stage USING ERRCODE = '23505'; END IF;
    UPDATE governance.design_contributions SET stage = 'closed', closed_reason = btrim(p_reason), updated_at = clock_timestamp() WHERE contribution_id = p_id;
    v_out := jsonb_build_object('stage', 'closed');
  END IF;

  SELECT * INTO c FROM governance.design_contributions x WHERE x.contribution_id = p_id;
  PERFORM governance.dg_artifact(p_id, 'change_proposal', 'DSC:' || p_id, left(format('Design contribution (%s): %s', c.kind, c.summary), 500), NULL, NULL, NULL, 'design_system_authority',
                                 CASE WHEN c.stage IN ('proposed', 'in_review', 'held', 'accepted') THEN 'proposed' WHEN c.stage IN ('rejected', 'closed', 'retired') THEN 'retired' ELSE 'active' END,
                                 jsonb_build_object('class', 'design_contribution', 'kind', c.kind, 'origin', c.origin, 'stage', c.stage, 'revision', c.revision), c.digest, p_actor, p_corr);
  PERFORM governance.ledger(NULL, NULL, 'design_contribution', p_id, c.revision, 'design.contribution_' || CASE WHEN v_held THEN 'held' ELSE p_step END, p_actor,
            jsonb_build_object('reason', btrim(p_reason), 'stage', c.stage, 'result', v_out), p_corr);
  RETURN jsonb_build_object('contribution_id', p_id, 'revision', c.revision, 'kind', c.kind, 'held', v_held, 'digest', c.digest) || v_out;
END $$;
REVOKE ALL ON FUNCTION governance.dg_advance_contribution(uuid, text, int, text, text, jsonb, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_advance_contribution(uuid, text, int, text, text, jsonb, uuid, uuid, uuid) TO eye_commit;

-- §DG.8 EXPERIENCE LEARNING (UX-ADR-024) ──────────────────────────────────────────────────────────────────────────────────────────────────
/* INTAKE the domain's B92 experience actions of kind `design_change_proposal` (decided `act` by the domain's named product analytics owner):
   each opens ONE contribution proposal (origin experience_learning, proposed by that owner, naming no target until a contributor amends it)
   and nothing else — telemetry and feedback never modify a pattern. Served by the route (governance.design.intake: the product analytics
   owner, the domain admin, the Design System Authority) and by the attention tick's step (executive.attention.tick — the agent opens
   proposals only). Idempotent: an action already taken in is answered as `already`. */
CREATE OR REPLACE FUNCTION governance.dg_intake_experience(p_tenant uuid, p_domain uuid, p_action uuid, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, analytics, observation, public, pg_catalog, pg_temp AS $$
DECLARE r record; v_intake uuid; v_contribution uuid; c governance.design_contributions%ROWTYPE; v_in jsonb := '[]'::jsonb; v_already jsonb := '[]'::jsonb; v_bound text;
BEGIN
  v_bound := observation.assert_authority(ARRAY['governance.design.intake', 'executive.attention.tick']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN
    RAISE EXCEPTION 'design contribution rejected (actor): the intake is recorded under the acting principal' USING ERRCODE = '42501';
  END IF;
  IF p_action IS NOT NULL AND NOT EXISTS (SELECT 1 FROM analytics.experience_actions a WHERE a.action_id = p_action AND a.tenant_id = p_tenant AND a.domain_id = p_domain) THEN
    RAISE EXCEPTION 'design contribution rejected (unknown_action): % is not an experience action of this domain', p_action USING ERRCODE = '23503';
  END IF;
  IF p_action IS NOT NULL AND NOT EXISTS (SELECT 1 FROM analytics.experience_actions a WHERE a.action_id = p_action AND a.decision = 'act' AND a.kind = 'design_change_proposal') THEN
    RAISE EXCEPTION 'design contribution rejected (kind): only an experience action decided as a design_change_proposal opens a design contribution' USING ERRCODE = '22023';
  END IF;
  FOR r IN SELECT a.action_id, a.finding_id, a.preview_digest, a.decided_by, a.decided_at, f.journey_key, f.statement
             FROM analytics.experience_actions a JOIN analytics.experience_findings f ON f.finding_id = a.finding_id
            WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.decision = 'act' AND a.kind = 'design_change_proposal' AND (p_action IS NULL OR a.action_id = p_action)
            ORDER BY a.decided_at, a.action_id LIMIT 50 LOOP
    SELECT i.intake_id, i.contribution_id INTO v_intake, v_contribution FROM governance.design_experience_intakes i WHERE i.action_id = r.action_id;
    IF FOUND THEN v_already := v_already || jsonb_build_object('action_id', r.action_id, 'intake_id', v_intake, 'contribution_id', v_contribution); CONTINUE; END IF;
    v_intake := gen_random_uuid(); v_contribution := gen_random_uuid();
    INSERT INTO governance.design_experience_intakes (intake_id, tenant_id, domain_id, action_id, finding_id, journey_key, statement, preview_digest, decided_by, decided_at, contribution_id,
                                                      intaken_by, intaken_by_kind, correlation_id)
    VALUES (v_intake, p_tenant, p_domain, r.action_id, r.finding_id, r.journey_key, r.statement, r.preview_digest, r.decided_by, r.decided_at, v_contribution, p_actor, coalesce(governance.dg_kind(p_actor), 'system'), p_corr);
    c := governance.dg_insert_contribution(v_contribution, 'pattern_change', NULL,
           jsonb_build_object('source', 'experience_learning', 'journeyKey', r.journey_key, 'intakeId', v_intake),
           format('Experience learning: a design change proposed from the %s journey (a B92 finding the domain''s product analytics owner decided as a design_change_proposal) — it names no target until a contributor amends it; telemetry never modifies a pattern',
                  coalesce(r.journey_key, 'unattached')),
           '{}'::jsonb, false, 'experience_learning', v_intake, r.decided_by, p_actor, p_corr);
    PERFORM governance.ledger(p_tenant, p_domain, 'design_contribution', v_contribution, 1, 'design.experience_intaken', p_actor,
              jsonb_build_object('action_id', r.action_id, 'finding_id', r.finding_id, 'intake_id', v_intake, 'bound_action', v_bound), p_corr);
    v_in := v_in || jsonb_build_object('action_id', r.action_id, 'intake_id', v_intake, 'contribution_id', v_contribution, 'stage', c.stage);
  END LOOP;
  RETURN jsonb_build_object('intaken', v_in, 'already', v_already);
END $$;
REVOKE ALL ON FUNCTION governance.dg_intake_experience(uuid, uuid, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_intake_experience(uuid, uuid, uuid, uuid, uuid) TO eye_commit;

-- §DG.9 THE DESIGN BASELINE (UX-01; UX-ADR-001) ─────────────────────────────────────────────────────────────────────────────────────────────
/* REGISTER a baseline version (proposed): its members are the CURRENT versions of the named assets (digests taken here, never from the
   caller), the active principles and the approved unexpired exceptions on the members — the design-system version and the conformance scope
   stated. One open proposal per baseline; expected_version guards the race. */
CREATE OR REPLACE FUNCTION governance.dg_propose_baseline(p_baseline uuid, p_expected_version int, p_title text, p_dsv text, p_scope jsonb, p_members uuid[], p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE v_cur int; v_members jsonb; v_principles jsonb; v_exceptions jsonb; v_digest text; v_version int; k text; v_missing uuid; v_retired text;
BEGIN
  PERFORM governance.assert_platform('governance.design.baseline.propose', p_actor, 'design baseline');
  IF length(btrim(coalesce(p_title, ''))) < 4 OR length(btrim(coalesce(p_dsv, ''))) < 3 THEN
    RAISE EXCEPTION 'design baseline rejected (title): a baseline states its title and the design-system version it binds' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_scope) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'design baseline rejected (scope): the conformance scope is an object' USING ERRCODE = '22023'; END IF;
  FOR k IN SELECT jsonb_object_keys(p_scope) LOOP
    IF k NOT IN ('capabilities', 'journeys', 'profiles', 'themes', 'locales', 'devices', 'assistive_technologies', 'roles') OR jsonb_typeof(p_scope -> k) <> 'array'
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_scope -> k) e WHERE jsonb_typeof(e) <> 'string') THEN
      RAISE EXCEPTION 'design baseline rejected (scope): % is not a conformance-scope list (capabilities, journeys, profiles, themes, locales, devices, assistive_technologies, roles)', k USING ERRCODE = '22023';
    END IF;
  END LOOP;
  IF NOT EXISTS (SELECT 1 FROM jsonb_each(p_scope) e WHERE jsonb_array_length(e.value) > 0) THEN
    RAISE EXCEPTION 'design baseline rejected (scope): a baseline names what it covers (at least one non-empty scope list)' USING ERRCODE = '22023';
  END IF;
  IF p_members IS NULL OR cardinality(p_members) = 0 THEN RAISE EXCEPTION 'design baseline rejected (members): a baseline names its component and pattern versions' USING ERRCODE = '22023'; END IF;
  SELECT m INTO v_missing FROM unnest(p_members) m WHERE NOT EXISTS (SELECT 1 FROM governance.design_assets a WHERE a.asset_id = m AND a.superseded_at IS NULL) LIMIT 1;
  IF v_missing IS NOT NULL THEN RAISE EXCEPTION 'design baseline rejected (unknown_asset): % is not a current design asset', v_missing USING ERRCODE = '23503'; END IF;
  SELECT a.asset_key INTO v_retired FROM governance.design_assets a WHERE a.asset_id = ANY (p_members) AND a.superseded_at IS NULL AND a.status = 'retired' LIMIT 1;
  IF v_retired IS NOT NULL THEN RAISE EXCEPTION 'design baseline rejected (state): % is retired and is no member of a baseline', v_retired USING ERRCODE = '23505'; END IF;
  SELECT jsonb_agg(jsonb_build_object('asset_id', a.asset_id, 'version', a.version, 'kind', a.kind, 'key', a.asset_key, 'digest', a.digest, 'status', a.status, 'owner', a.owner_principal_id,
                                      'package_version', a.package_version) ORDER BY a.asset_key)
    INTO v_members FROM governance.design_assets a WHERE a.asset_id = ANY (p_members) AND a.superseded_at IS NULL;
  SELECT coalesce(jsonb_agg(jsonb_build_object('key', p.principle_key, 'version', p.version, 'digest', p.digest, 'unwaivable', p.unwaivable) ORDER BY p.principle_key), '[]'::jsonb)
    INTO v_principles FROM governance.design_principles p WHERE p.state = 'active';
  SELECT coalesce(jsonb_agg(jsonb_build_object('exception_id', x.exception_id, 'principle', x.principle_key, 'asset_id', x.asset_id, 'asset_version', x.asset_version, 'expires_at', x.expires_at, 'digest', x.digest)
                            ORDER BY x.exception_id), '[]'::jsonb)
    INTO v_exceptions FROM governance.design_exceptions x WHERE x.asset_id = ANY (p_members) AND x.state = 'approved' AND x.expires_at > clock_timestamp();
  SELECT max(b.version) INTO v_cur FROM governance.design_baselines b WHERE b.baseline_id = p_baseline;
  IF coalesce(p_expected_version, -1) <> coalesce(v_cur, 0) THEN
    RAISE EXCEPTION 'design baseline rejected (stale): the baseline is at version %, not %', coalesce(v_cur, 0), coalesce(p_expected_version::text, '<none>') USING ERRCODE = '23505';
  END IF;
  IF EXISTS (SELECT 1 FROM governance.design_baselines b WHERE b.baseline_id = p_baseline AND b.state = 'proposed') THEN
    RAISE EXCEPTION 'design baseline rejected (state): a proposed version awaits its decision' USING ERRCODE = '23505';
  END IF;
  v_version := coalesce(v_cur, 0) + 1;
  v_digest := governance.digest(jsonb_build_object('baseline_id', p_baseline, 'version', v_version, 'title', btrim(p_title), 'design_system_version', btrim(p_dsv), 'controlling_volume', 'V9',
                                                   'refines', to_jsonb(ARRAY['V0', 'V3', 'V4', 'V5', 'V6', 'V7', 'V8']), 'scope', p_scope, 'members', v_members, 'principles', v_principles, 'exceptions', v_exceptions));
  INSERT INTO governance.design_baselines (baseline_id, version, title, design_system_version, conformance_scope, members, principles, exceptions, digest, proposed_by, correlation_id)
  VALUES (p_baseline, v_version, btrim(p_title), btrim(p_dsv), p_scope, v_members, v_principles, v_exceptions, v_digest, p_actor, p_corr);
  IF v_cur IS NULL THEN
    PERFORM governance.dg_artifact(p_baseline, 'baseline', 'DSB:' || p_baseline, btrim(p_title), NULL, NULL, NULL, 'design_system_authority', 'proposed',
                                   jsonb_build_object('class', 'design_baseline', 'baseline_version', v_version, 'state', 'proposed'), v_digest, p_actor, p_corr);
  END IF;
  PERFORM governance.ledger(NULL, NULL, 'design_baseline', p_baseline, v_version, 'design.baseline_proposed', p_actor, jsonb_build_object('digest', v_digest, 'members', jsonb_array_length(v_members)), p_corr);
  RETURN jsonb_build_object('baseline_id', p_baseline, 'version', v_version, 'state', 'proposed', 'digest', v_digest, 'members', v_members, 'principles', v_principles, 'exceptions', v_exceptions);
END $$;
REVOKE ALL ON FUNCTION governance.dg_propose_baseline(uuid, int, text, text, jsonb, uuid[], uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_propose_baseline(uuid, int, text, text, jsonb, uuid[], uuid, uuid) TO eye_commit;

/* What HOLDS a baseline's attestation (UX-01-005): a member whose version moved on, is not approved, or has no accountable owner; an
   exception it carries that has since expired. */
CREATE OR REPLACE FUNCTION governance.dg_baseline_blockers(p_baseline uuid, p_version int) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT coalesce(jsonb_agg(x ORDER BY x ->> 'key'), '[]'::jsonb) FROM (
    SELECT jsonb_build_object('key', m ->> 'key', 'class', CASE WHEN a.owner_principal_id IS NULL THEN 'ownership_gap' ELSE 'evidence_missing' END,
                              'reason', CASE WHEN a.asset_id IS NULL THEN format('%s v%s is no longer the current version', m ->> 'key', m ->> 'version')
                                             WHEN a.owner_principal_id IS NULL THEN format('%s has no accountable owner (REL-01)', m ->> 'key')
                                             ELSE format('%s is %s, not approved', m ->> 'key', a.status) END) AS x
      FROM governance.design_baselines b CROSS JOIN LATERAL jsonb_array_elements(b.members) m
      LEFT JOIN governance.design_assets a ON a.asset_id = (m ->> 'asset_id')::uuid AND a.version = (m ->> 'version')::int AND a.superseded_at IS NULL
     WHERE b.baseline_id = p_baseline AND b.version = p_version AND (a.asset_id IS NULL OR a.owner_principal_id IS NULL OR a.status NOT IN ('approved', 'deprecated'))
    UNION ALL
    SELECT jsonb_build_object('key', e ->> 'principle', 'class', 'exception_expired', 'reason', format('the exception on %s for %s expired at %s', e ->> 'asset_id', e ->> 'principle', e ->> 'expires_at'))
      FROM governance.design_baselines b CROSS JOIN LATERAL jsonb_array_elements(b.exceptions) e
     WHERE b.baseline_id = p_baseline AND b.version = p_version AND (e ->> 'expires_at')::timestamptz <= clock_timestamp()) q
$$;
REVOKE ALL ON FUNCTION governance.dg_baseline_blockers(uuid, int) FROM PUBLIC;

/* DECIDE a baseline version: ATTEST (the Design System Authority, a named human, never the proposer; SIGNED `baseline_decision` over the exact
   digest) or REJECT. An attestation with an unresolved member is HELD: the proposal preserved, governance.holds `ownership_gap` (or
   `exception_expired`) opened on the baseline, the blocking list answered (the route answers 409); the next attestation lifts it. The prior
   attested version is superseded; the members are linked `part_of` the baseline (members no longer present unlinked). */
CREATE OR REPLACE FUNCTION governance.dg_decide_baseline(p_baseline uuid, p_version int, p_decision text, p_digest text, p_reason text, p_signature uuid, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, onboarding, public, pg_catalog, pg_temp AS $$
DECLARE b governance.design_baselines%ROWTYPE; v_blockers jsonb; v_hold uuid; m jsonb; l record;
BEGIN
  PERFORM governance.assert_platform('governance.design.baseline.decide', p_actor, 'design baseline');
  SELECT * INTO b FROM governance.design_baselines x WHERE x.baseline_id = p_baseline AND x.version = p_version FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'design baseline rejected (unknown_baseline): no design baseline %/v%', p_baseline, p_version USING ERRCODE = '23503'; END IF;
  PERFORM governance.assert_approver('design baseline', p_actor, NULL, NULL, ARRAY['design_system_authority'], b.proposed_by, NULL,
            CASE p_decision WHEN 'reject' THEN 'rejecting a design baseline' ELSE 'attesting a design baseline' END);
  IF b.state <> 'proposed' THEN RAISE EXCEPTION 'design baseline rejected (state): version % is %', p_version, b.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM b.digest THEN RAISE EXCEPTION 'design baseline rejected (stale): the decision names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF p_decision NOT IN ('attest', 'reject') THEN RAISE EXCEPTION 'design baseline rejected (decision): attest or reject' USING ERRCODE = '22023'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'design baseline rejected (reason): a decision states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF p_decision = 'reject' THEN
    UPDATE governance.design_baselines SET state = 'rejected', decided_by = p_actor, decided_at = clock_timestamp(), decision_reason = btrim(p_reason) WHERE baseline_id = p_baseline AND version = p_version;
    PERFORM governance.ledger(NULL, NULL, 'design_baseline', p_baseline, p_version, 'design.baseline_rejected', p_actor, jsonb_build_object('reason', btrim(p_reason)), p_corr);
    RETURN jsonb_build_object('baseline_id', p_baseline, 'version', p_version, 'state', 'rejected', 'preserved', 'the attested baseline in force (if any) is unchanged');
  END IF;
  v_blockers := governance.dg_baseline_blockers(p_baseline, p_version);
  IF jsonb_array_length(v_blockers) > 0 THEN
    v_hold := governance.dg_hold(p_baseline, CASE WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers) x WHERE x ->> 'class' = 'ownership_gap') THEN 'ownership_gap'
                                                  WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers) x WHERE x ->> 'class' = 'exception_expired') THEN 'exception_expired' ELSE 'evidence_missing' END,
                                 left(format('design baseline v%s held at attestation: %s', p_version, (SELECT string_agg(x ->> 'reason', '; ') FROM jsonb_array_elements(v_blockers) x)), 2000), NULL, NULL, p_actor, p_corr);
    PERFORM governance.ledger(NULL, NULL, 'design_baseline', p_baseline, p_version, 'design.baseline_held', p_actor, jsonb_build_object('blockers', v_blockers, 'hold_id', v_hold), p_corr);
    RETURN jsonb_build_object('baseline_id', p_baseline, 'version', p_version, 'state', 'proposed', 'held', true, 'blocking', v_blockers, 'hold_id', v_hold,
                              'preserved', 'the proposal is kept as proposed; the attested baseline in force (if any) is unchanged');
  END IF;
  IF NOT governance.dg_signature_ok(p_signature, 'baseline_decision', p_baseline, p_version, b.digest, p_actor, 'governance.design.baseline.decide') THEN
    RAISE EXCEPTION 'design baseline rejected (signature): an attestation carries the authority''s signature over the version''s digest' USING ERRCODE = '22023';
  END IF;
  UPDATE governance.design_baselines SET state = 'superseded' WHERE baseline_id = p_baseline AND state = 'attested';
  UPDATE governance.design_baselines SET state = 'attested', decided_by = p_actor, decided_at = clock_timestamp(), decision_reason = btrim(p_reason), signature_id = p_signature
   WHERE baseline_id = p_baseline AND version = p_version;
  PERFORM governance.dg_lift(p_baseline, format('version %s attested', p_version), p_actor);
  PERFORM governance.dg_artifact(p_baseline, 'baseline', 'DSB:' || p_baseline, b.title, NULL, NULL, p_actor, 'design_system_authority', 'active',
                                 jsonb_build_object('class', 'design_baseline', 'baseline_version', p_version, 'state', 'attested', 'design_system_version', b.design_system_version), b.digest, p_actor, p_corr);
  FOR m IN SELECT x FROM jsonb_array_elements(b.members) x LOOP
    PERFORM governance.dg_link((m ->> 'asset_id')::uuid, p_baseline, 'part_of', NULL, NULL, jsonb_build_object('baseline_version', p_version), p_actor, p_corr);
  END LOOP;
  FOR l IN SELECT x.link_id FROM governance.links_live x WHERE x.to_artifact = p_baseline AND x.relation = 'part_of'
              AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(b.members) m2 WHERE (m2 ->> 'asset_id')::uuid = x.from_artifact) LOOP
    PERFORM governance.dg_unlink(l.link_id, p_actor, p_corr);
  END LOOP;
  PERFORM governance.ledger(NULL, NULL, 'design_baseline', p_baseline, p_version, 'design.baseline_attested', p_actor, jsonb_build_object('digest', b.digest, 'signature_id', p_signature, 'reason', btrim(p_reason)), p_corr);
  RETURN jsonb_build_object('baseline_id', p_baseline, 'version', p_version, 'state', 'attested', 'digest', b.digest, 'signature_id', p_signature);
END $$;
REVOKE ALL ON FUNCTION governance.dg_decide_baseline(uuid, int, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_decide_baseline(uuid, int, text, text, text, uuid, uuid, uuid) TO eye_commit;

-- §DG.10 THE TRACE (UX-08; REL-02) ──────────────────────────────────────────────────────────────────────────────────────────────────────────
/* RECORD (or retire) a design trace link: a design artifact implements a requirement, is verified by a test, covers a journey, is governed by
   a principle … Both ends are current artifacts and one of them is a design artifact (other trace links are §RG's). */
CREATE OR REPLACE FUNCTION governance.dg_record_link(p_from uuid, p_to uuid, p_relation text, p_retire uuid, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, public, pg_catalog, pg_temp AS $$
DECLARE fa governance.artifacts%ROWTYPE; ta governance.artifacts%ROWTYPE; v uuid; l governance.links%ROWTYPE;
BEGIN
  PERFORM governance.assert_platform('governance.design.link.record', p_actor, 'design baseline');
  IF p_retire IS NOT NULL THEN
    SELECT * INTO l FROM governance.links_live x WHERE x.link_id = p_retire;
    IF NOT FOUND THEN RAISE EXCEPTION 'design baseline rejected (unknown_link): % is not a live link', p_retire USING ERRCODE = '23503'; END IF;
    IF coalesce(l.attributes ->> 'part', '') <> 'dg' THEN RAISE EXCEPTION 'design baseline rejected (scope): only a design trace link is retired here (others are §RG''s)' USING ERRCODE = '22023'; END IF;
    v := governance.dg_unlink(p_retire, p_actor, p_corr);
    PERFORM governance.ledger(NULL, NULL, 'design_link', p_retire, NULL, 'design.link_retired', p_actor, jsonb_build_object('retired_by', v), p_corr);
    RETURN jsonb_build_object('retired', p_retire, 'by', v);
  END IF;
  SELECT * INTO fa FROM governance.artifacts a WHERE a.artifact_id = p_from AND a.superseded_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'design baseline rejected (unknown_artifact): % is not a current artifact', p_from USING ERRCODE = '23503'; END IF;
  SELECT * INTO ta FROM governance.artifacts a WHERE a.artifact_id = p_to AND a.superseded_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'design baseline rejected (unknown_artifact): % is not a current artifact', p_to USING ERRCODE = '23503'; END IF;
  IF NOT (fa.kind IN ('design_component', 'pattern', 'design_asset', 'principle', 'baseline') OR ta.kind IN ('design_component', 'pattern', 'design_asset', 'principle', 'baseline')) THEN
    RAISE EXCEPTION 'design baseline rejected (scope): a design trace link has a design artifact at one end (other trace links are §RG''s)' USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_relation, '') NOT IN ('implements', 'verifies', 'covers', 'governs', 'evidences', 'depends_on', 'cites', 'consumes', 'part_of') THEN
    RAISE EXCEPTION 'design baseline rejected (relation): % is not a design trace relation', coalesce(p_relation, '<none>') USING ERRCODE = '22023';
  END IF;
  IF p_from = p_to THEN RAISE EXCEPTION 'design baseline rejected (relation): an artifact is not linked to itself' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM governance.links_live x WHERE x.from_artifact = p_from AND x.to_artifact = p_to AND x.relation = p_relation) THEN
    RAISE EXCEPTION 'design baseline rejected (duplicate): the link already exists' USING ERRCODE = '23505';
  END IF;
  v := governance.dg_link(p_from, p_to, p_relation, NULL, NULL, jsonb_build_object('from_kind', fa.kind, 'to_kind', ta.kind), p_actor, p_corr);
  PERFORM governance.ledger(NULL, NULL, 'design_link', v, NULL, 'design.link_recorded', p_actor, jsonb_build_object('from', p_from, 'to', p_to, 'relation', p_relation), p_corr);
  RETURN jsonb_build_object('link_id', v, 'from', p_from, 'to', p_to, 'relation', p_relation);
END $$;
REVOKE ALL ON FUNCTION governance.dg_record_link(uuid, uuid, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_record_link(uuid, uuid, text, uuid, uuid, uuid) TO eye_commit;

/* THE TRACE (an invoker read, the caller's RLS): from one artifact, BOTH directions over the live links, to a bounded depth — the nodes with
   their kind, key, lifecycle and version, the edges with their relation. */
CREATE OR REPLACE FUNCTION governance.dg_trace(p_artifact uuid, p_depth int) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  WITH RECURSIVE walk(id, depth, path) AS (
    SELECT p_artifact, 0, ARRAY[p_artifact]
    UNION
    SELECT CASE WHEN l.from_artifact = w.id THEN l.to_artifact ELSE l.from_artifact END, w.depth + 1,
           w.path || CASE WHEN l.from_artifact = w.id THEN l.to_artifact ELSE l.from_artifact END
      FROM walk w JOIN governance.links_live l ON (l.from_artifact = w.id OR l.to_artifact = w.id)
     WHERE w.depth < least(greatest(coalesce(p_depth, 2), 1), 4) AND NOT ((CASE WHEN l.from_artifact = w.id THEN l.to_artifact ELSE l.from_artifact END) = ANY (w.path))
  ), nodes AS (SELECT id, min(depth) AS depth FROM walk GROUP BY id)
  SELECT jsonb_build_object(
    'root', p_artifact,
    'nodes', coalesce((SELECT jsonb_agg(jsonb_build_object('artifact_id', n.id, 'depth', n.depth, 'kind', a.kind, 'key', a.external_key, 'title', a.title, 'lifecycle', a.lifecycle,
                                                          'version', a.version, 'scope', a.scope, 'known', a.artifact_id IS NOT NULL) ORDER BY n.depth, a.kind, a.external_key)
                         FROM nodes n LEFT JOIN governance.artifacts a ON a.artifact_id = n.id AND a.superseded_at IS NULL), '[]'::jsonb),
    'edges', coalesce((SELECT jsonb_agg(DISTINCT jsonb_build_object('link_id', l.link_id, 'from', l.from_artifact, 'to', l.to_artifact, 'relation', l.relation))
                         FROM governance.links_live l WHERE l.from_artifact IN (SELECT id FROM nodes) AND l.to_artifact IN (SELECT id FROM nodes)), '[]'::jsonb))
$$;
REVOKE ALL ON FUNCTION governance.dg_trace(uuid, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_trace(uuid, int) TO eye_app, eye_commit;

/* THE ORPHANS AND CONTRADICTIONS (an invoker read; UX-01-006, UX-08-005): a current design asset that implements no requirement; one without
   an accountable owner; a V9 design requirement (UX-* / REL-*) that no design artifact implements — when such requirements are registered (§RG
   imports them); a retired asset still part of an attested baseline; an approved exception that covers a superseded asset version. Stated,
   never hidden. */
CREATE OR REPLACE FUNCTION governance.dg_orphans() RETURNS jsonb
LANGUAGE sql STABLE SET search_path = governance, pg_catalog, pg_temp AS $$
  SELECT jsonb_build_object(
    'assets_without_requirement', coalesce((SELECT jsonb_agg(jsonb_build_object('asset_id', a.asset_id, 'key', a.asset_key, 'version', a.version) ORDER BY a.asset_key)
      FROM governance.design_assets a WHERE a.superseded_at IS NULL AND a.status <> 'retired'
       AND NOT EXISTS (SELECT 1 FROM governance.links_live l JOIN governance.artifacts r ON r.artifact_id = l.to_artifact AND r.superseded_at IS NULL AND r.kind = 'requirement'
                        WHERE l.from_artifact = a.asset_id AND l.relation IN ('implements', 'covers'))), '[]'::jsonb),
    'assets_without_owner', coalesce((SELECT jsonb_agg(jsonb_build_object('asset_id', a.asset_id, 'key', a.asset_key, 'version', a.version, 'status', a.status) ORDER BY a.asset_key)
      FROM governance.design_assets a WHERE a.superseded_at IS NULL AND a.status <> 'retired' AND a.owner_principal_id IS NULL), '[]'::jsonb),
    'requirements_without_design', coalesce((SELECT jsonb_agg(jsonb_build_object('artifact_id', r.artifact_id, 'key', r.external_key) ORDER BY r.external_key)
      FROM governance.artifacts r WHERE r.superseded_at IS NULL AND r.kind = 'requirement' AND (r.external_key LIKE 'V9:UX-%' OR r.external_key LIKE 'V9:REL-%')
       AND NOT EXISTS (SELECT 1 FROM governance.links_live l JOIN governance.artifacts d ON d.artifact_id = l.from_artifact AND d.superseded_at IS NULL
                                                             AND d.kind IN ('design_component', 'pattern', 'design_asset', 'principle', 'baseline')
                        WHERE l.to_artifact = r.artifact_id AND l.relation IN ('implements', 'covers'))), '[]'::jsonb),
    'contradictions', coalesce((SELECT jsonb_agg(x) FROM (
        SELECT jsonb_build_object('kind', 'retired_member', 'asset_id', a.asset_id, 'key', a.asset_key, 'baseline_id', b.baseline_id, 'baseline_version', b.version) AS x
          FROM governance.design_baselines b CROSS JOIN LATERAL jsonb_array_elements(b.members) m JOIN governance.design_assets a ON a.asset_id = (m ->> 'asset_id')::uuid AND a.superseded_at IS NULL
         WHERE b.state = 'attested' AND a.status = 'retired'
        UNION ALL
        SELECT jsonb_build_object('kind', 'exception_on_superseded_version', 'exception_id', x.exception_id, 'asset_id', x.asset_id, 'asset_version', x.asset_version)
          FROM governance.design_exceptions x WHERE x.state = 'approved' AND x.expires_at > clock_timestamp()
           AND NOT EXISTS (SELECT 1 FROM governance.design_assets a WHERE a.asset_id = x.asset_id AND a.version = x.asset_version AND a.superseded_at IS NULL)) q), '[]'::jsonb))
$$;
REVOKE ALL ON FUNCTION governance.dg_orphans() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_orphans() TO eye_app, eye_commit;

/* THE CONFORMANCE STATUS of the design system (a definer read over PLATFORM rows only — the vendor's design system, readable by every
   authenticated context; UX-01-001): WITHHELD with every reason (no attested baseline; a member
   without an approved owner; the latest lint evaluation nonconformant; an expired exception the baseline carries; an orphan or a
   contradiction) — or `no_blocking_finding`, which is NOT conformance: conformance is accepted only by a design acceptance record, per scope,
   by named humans. Nothing is shown conformant by inference. */
CREATE OR REPLACE FUNCTION governance.dg_conformance() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, pg_catalog, pg_temp AS $$
DECLARE b governance.design_baselines%ROWTYPE; v_reasons jsonb := '[]'::jsonb; e governance.design_evaluations%ROWTYPE; o jsonb; x jsonb;
BEGIN
  SELECT * INTO b FROM governance.design_baselines x0 WHERE x0.state = 'attested' ORDER BY x0.decided_at DESC LIMIT 1;
  IF NOT FOUND THEN v_reasons := v_reasons || jsonb_build_object('class', 'no_baseline', 'reason', 'no design baseline is attested');
  ELSE
    FOR x IN SELECT y FROM jsonb_array_elements(governance.dg_baseline_blockers(b.baseline_id, b.version)) y LOOP
      v_reasons := v_reasons || jsonb_build_object('class', x ->> 'class', 'reason', x ->> 'reason');
    END LOOP;
  END IF;
  SELECT * INTO e FROM governance.design_evaluations x1 WHERE x1.source = 'lint' ORDER BY x1.evaluated_at DESC LIMIT 1;
  IF NOT FOUND THEN v_reasons := v_reasons || jsonb_build_object('class', 'unevaluated', 'reason', 'the web source has not been evaluated against the principles (no lint run)');
  ELSIF e.verdict = 'nonconformant' THEN v_reasons := v_reasons || jsonb_build_object('class', 'nonconformant', 'reason', format('the latest lint run has %s open finding(s)', e.counts ->> 'open'));
  END IF;
  o := governance.dg_orphans();
  IF jsonb_array_length(o -> 'assets_without_owner') > 0 THEN
    v_reasons := v_reasons || jsonb_build_object('class', 'ownership_gap', 'reason', format('%s design asset(s) have no accountable owner', jsonb_array_length(o -> 'assets_without_owner')));
  END IF;
  IF jsonb_array_length(o -> 'assets_without_requirement') > 0 THEN
    v_reasons := v_reasons || jsonb_build_object('class', 'orphan', 'reason', format('%s design asset(s) trace to no requirement', jsonb_array_length(o -> 'assets_without_requirement')));
  END IF;
  IF jsonb_array_length(o -> 'requirements_without_design') > 0 THEN
    v_reasons := v_reasons || jsonb_build_object('class', 'orphan', 'reason', format('%s registered design requirement(s) have no implementing design artifact', jsonb_array_length(o -> 'requirements_without_design')));
  END IF;
  IF jsonb_array_length(o -> 'contradictions') > 0 THEN
    v_reasons := v_reasons || jsonb_build_object('class', 'contradiction', 'reason', format('%s contradiction(s) in the design trace', jsonb_array_length(o -> 'contradictions')));
  END IF;
  RETURN jsonb_build_object('state', CASE WHEN jsonb_array_length(v_reasons) = 0 THEN 'no_blocking_finding' ELSE 'withheld' END, 'reasons', v_reasons,
                            'baseline', CASE WHEN b.baseline_id IS NULL THEN NULL ELSE jsonb_build_object('baseline_id', b.baseline_id, 'version', b.version, 'digest', b.digest, 'title', b.title,
                                                                                                          'design_system_version', b.design_system_version, 'attested_at', b.decided_at) END,
                            'latest_lint', CASE WHEN e.evaluation_id IS NULL THEN NULL ELSE jsonb_build_object('evaluation_id', e.evaluation_id, 'verdict', e.verdict, 'counts', e.counts, 'at', e.evaluated_at) END,
                            'note', 'conformance is accepted only by a design acceptance record for a declared scope, attested by named humans — never inferred from the absence of findings',
                            'as_of', clock_timestamp());
END $$;
REVOKE ALL ON FUNCTION governance.dg_conformance() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_conformance() TO eye_app, eye_commit;

-- §DG.11 DESIGN ACCEPTANCE (UX-ADR-023; REL-24; DOMAIN) ────────────────────────────────────────────────────────────────────────────────────
/* The role each obligation is attested by. */
CREATE OR REPLACE FUNCTION governance.dg_obligation_roles(p_obligation text) RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT CASE p_obligation WHEN 'design' THEN ARRAY['design_system_authority'] WHEN 'assurance' THEN ARRAY['independent_assurance'] WHEN 'customer' THEN ARRAY['customer_sponsor'] END
$$;
GRANT EXECUTE ON FUNCTION governance.dg_obligation_roles(text) TO eye_app, eye_commit;

/* The accessibility slots every design acceptance carries — EMPTY: MET-034 is unsupported (B108 is its source, H3 its verification). */
CREATE OR REPLACE FUNCTION governance.dg_accessibility_slots() RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT jsonb_build_object('status', 'unsupported', 'metric', 'MET-034', 'carrier', 'B108 (source) → H3',
    'slots', jsonb_build_array(jsonb_build_object('kind', 'automated_journey_checks', 'status', 'empty'), jsonb_build_object('kind', 'manual_review', 'status', 'empty'),
                               jsonb_build_object('kind', 'assistive_technology_journeys', 'status', 'empty')),
    'note', 'no accessibility result is computed, inferred or claimed here; the slots are filled when B108''s suites record journey results')
$$;
GRANT EXECUTE ON FUNCTION governance.dg_accessibility_slots() TO eye_app, eye_commit;

/* PROPOSE a design acceptance record version (the conformance steward, the domain admin — never an approval): the EXACT tuple — the attested
   baseline (version, digest), component and pattern versions that are members of it, the scope tuple, evidence items with their windows,
   findings, conditions, the obligations (design and assurance always; customer when the customer accepts too) and the declared builders (the
   proposers and builders of the contributions that produced the bound versions are added). One open proposal per record. */
CREATE OR REPLACE FUNCTION governance.dg_propose_acceptance(p_acceptance uuid, p_tenant uuid, p_domain uuid, p_expected_version int, p_baseline uuid, p_components uuid[], p_tuple jsonb,
                                                           p_evidence jsonb, p_findings jsonb, p_conditions jsonb, p_obligations text[], p_builders uuid[], p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, observation, public, pg_catalog, pg_temp AS $$
DECLARE b governance.design_baselines%ROWTYPE; v_components jsonb; k text; e jsonb; v_cur int; v_version int; v_digest text; v_valid timestamptz; v_builders uuid[]; v_missing uuid;
        v_obl text[] := coalesce(p_obligations, ARRAY['design', 'assurance']);
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.design.acceptance.propose']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'design acceptance rejected (actor): the act is recorded under the acting principal' USING ERRCODE = '42501'; END IF;
  SELECT * INTO b FROM governance.design_baselines x WHERE x.baseline_id = p_baseline AND x.state = 'attested';
  IF NOT FOUND THEN RAISE EXCEPTION 'design acceptance rejected (state): % has no attested version — a design acceptance binds an attested baseline', p_baseline USING ERRCODE = '23505'; END IF;
  IF p_components IS NULL OR cardinality(p_components) = 0 THEN RAISE EXCEPTION 'design acceptance rejected (components): the record names the component and pattern versions it accepts' USING ERRCODE = '22023'; END IF;
  SELECT c INTO v_missing FROM unnest(p_components) c WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(b.members) m WHERE (m ->> 'asset_id')::uuid = c) LIMIT 1;
  IF v_missing IS NOT NULL THEN RAISE EXCEPTION 'design acceptance rejected (scope): % is not a member of the attested baseline v%', v_missing, b.version USING ERRCODE = '22023'; END IF;
  SELECT jsonb_agg(m ORDER BY m ->> 'key') INTO v_components FROM jsonb_array_elements(b.members) m WHERE (m ->> 'asset_id')::uuid = ANY (p_components);
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_components) m WHERE NOT EXISTS (SELECT 1 FROM governance.design_assets a WHERE a.asset_id = (m ->> 'asset_id')::uuid AND a.version = (m ->> 'version')::int AND a.superseded_at IS NULL)) THEN
    RAISE EXCEPTION 'design acceptance rejected (stale): a bound component version moved on since baseline v% — attest the next baseline first', b.version USING ERRCODE = '23505';
  END IF;
  IF jsonb_typeof(p_tuple) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'design acceptance rejected (tuple): the scope tuple is an object' USING ERRCODE = '22023'; END IF;
  FOREACH k IN ARRAY ARRAY['capability', 'journey', 'persona', 'role', 'deployment_profile', 'theme', 'locale', 'device'] LOOP
    IF length(btrim(coalesce(p_tuple ->> k, ''))) < 2 THEN RAISE EXCEPTION 'design acceptance rejected (tuple): the tuple names its % (UX-ADR-023: acceptance is exact)', k USING ERRCODE = '22023'; END IF;
  END LOOP;
  FOR k IN SELECT jsonb_object_keys(p_tuple) LOOP
    IF k NOT IN ('capability', 'journey', 'persona', 'role', 'deployment_profile', 'theme', 'locale', 'device', 'entitlement', 'assistive_technology', 'configuration_digest',
                 'data_versions', 'model_versions', 'period_from', 'period_to') THEN
      RAISE EXCEPTION 'design acceptance rejected (tuple): % is not a dimension of the design tuple', k USING ERRCODE = '22023';
    END IF;
  END LOOP;
  IF (p_tuple ->> 'deployment_profile') NOT IN ('local-dev', 'saas', 'private-cloud', 'on-premise') THEN
    RAISE EXCEPTION 'design acceptance rejected (tuple): % is not a deployment profile', p_tuple ->> 'deployment_profile' USING ERRCODE = '22023';
  END IF;
  IF p_tuple ? 'configuration_digest' AND coalesce(p_tuple ->> 'configuration_digest', '') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'design acceptance rejected (tuple): the configuration digest is 64 hex' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_evidence) IS DISTINCT FROM 'array' OR jsonb_array_length(p_evidence) NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'design acceptance rejected (evidence): a record binds 1–50 evidence items' USING ERRCODE = '22023';
  END IF;
  FOR e IN SELECT x FROM jsonb_array_elements(p_evidence) x LOOP
    IF length(coalesce(e ->> 'kind', '')) < 3 OR length(coalesce(e ->> 'ref', '')) < 3 OR coalesce(e ->> 'digest', '') !~ '^[0-9a-f]{64}$'
       OR (e ->> 'capturedAt') IS NULL OR (e ->> 'validUntil') IS NULL THEN
      RAISE EXCEPTION 'design acceptance rejected (evidence): each item names its kind, reference, digest (64 hex), capturedAt and validUntil' USING ERRCODE = '22023';
    END IF;
    IF (e ->> 'capturedAt')::timestamptz > clock_timestamp() OR (e ->> 'validUntil')::timestamptz <= (e ->> 'capturedAt')::timestamptz THEN
      RAISE EXCEPTION 'design acceptance rejected (evidence): % was captured in the future or is valid for no time', e ->> 'ref' USING ERRCODE = '22023';
    END IF;
    IF (e ->> 'validUntil')::timestamptz <= clock_timestamp() THEN
      RAISE EXCEPTION 'design acceptance rejected (expired): the evidence % expired at % — renew it before it is bound', e ->> 'ref', e ->> 'validUntil' USING ERRCODE = '23505';
    END IF;
  END LOOP;
  IF jsonb_typeof(coalesce(p_findings, '[]'::jsonb)) <> 'array' OR jsonb_typeof(coalesce(p_conditions, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'design acceptance rejected (findings): findings and conditions are lists' USING ERRCODE = '22023';
  END IF;
  IF NOT (v_obl @> ARRAY['design', 'assurance'] AND v_obl <@ ARRAY['design', 'assurance', 'customer']) THEN
    RAISE EXCEPTION 'design acceptance rejected (obligations): design and assurance always (one role never accepts all — ES-71-002), customer when the customer accepts' USING ERRCODE = '22023';
  END IF;
  SELECT array_agg(DISTINCT u) INTO v_builders FROM (
    SELECT unnest(coalesce(p_builders, '{}')) u
    UNION SELECT unnest(c.builders) FROM governance.design_contributions c
            JOIN governance.design_assets a ON a.contribution_id = c.contribution_id
            JOIN jsonb_array_elements(v_components) m ON a.asset_id = (m ->> 'asset_id')::uuid AND a.version = (m ->> 'version')::int
    UNION SELECT c.proposed_by FROM governance.design_contributions c
            JOIN governance.design_assets a ON a.contribution_id = c.contribution_id
            JOIN jsonb_array_elements(v_components) m ON a.asset_id = (m ->> 'asset_id')::uuid AND a.version = (m ->> 'version')::int) q WHERE u IS NOT NULL;
  SELECT max(x.version) INTO v_cur FROM governance.design_acceptances x WHERE x.acceptance_id = p_acceptance;
  IF v_cur IS NOT NULL AND NOT EXISTS (SELECT 1 FROM governance.design_acceptances x WHERE x.acceptance_id = p_acceptance AND x.tenant_id = p_tenant AND x.domain_id = p_domain) THEN
    RAISE EXCEPTION 'design acceptance rejected (unknown_acceptance): % is not a design acceptance record of this domain', p_acceptance USING ERRCODE = '23503';
  END IF;
  IF coalesce(p_expected_version, -1) <> coalesce(v_cur, 0) THEN
    RAISE EXCEPTION 'design acceptance rejected (stale): the record is at version %, not %', coalesce(v_cur, 0), coalesce(p_expected_version::text, '<none>') USING ERRCODE = '23505';
  END IF;
  IF EXISTS (SELECT 1 FROM governance.design_acceptances x WHERE x.acceptance_id = p_acceptance AND x.state = 'proposed') THEN
    RAISE EXCEPTION 'design acceptance rejected (state): a proposed version awaits its attestations' USING ERRCODE = '23505';
  END IF;
  v_version := coalesce(v_cur, 0) + 1;
  SELECT min((x ->> 'validUntil')::timestamptz) INTO v_valid FROM jsonb_array_elements(p_evidence) x;
  v_digest := governance.digest(jsonb_build_object('acceptance_id', p_acceptance, 'version', v_version, 'tenant_id', p_tenant, 'domain_id', p_domain, 'kind', 'design',
                                                   'baseline', jsonb_build_object('baseline_id', b.baseline_id, 'version', b.version, 'digest', b.digest), 'components', v_components, 'tuple', p_tuple,
                                                   'evidence', p_evidence, 'findings', coalesce(p_findings, '[]'::jsonb), 'conditions', coalesce(p_conditions, '[]'::jsonb),
                                                   'accessibility', governance.dg_accessibility_slots(), 'obligations', to_jsonb(v_obl), 'builders', to_jsonb(coalesce(v_builders, '{}')),
                                                   'valid_until', v_valid, 'claim', 'demonstration'));
  INSERT INTO governance.design_acceptances (acceptance_id, version, tenant_id, domain_id, baseline_id, baseline_version, baseline_digest, components, tuple, evidence, findings, conditions,
                                             accessibility, obligations, builders, valid_until, digest, proposed_by, correlation_id)
  VALUES (p_acceptance, v_version, p_tenant, p_domain, b.baseline_id, b.version, b.digest, v_components, p_tuple, p_evidence, coalesce(p_findings, '[]'::jsonb), coalesce(p_conditions, '[]'::jsonb),
          governance.dg_accessibility_slots(), v_obl, coalesce(v_builders, '{}'), v_valid, v_digest, p_actor, p_corr);
  PERFORM governance.dg_artifact(p_acceptance, 'acceptance_record', 'DAC:' || p_acceptance, format('Design acceptance: %s · %s (SYNTHETIC demonstration record)', p_tuple ->> 'capability', p_tuple ->> 'journey'),
                                 p_tenant, p_domain, NULL, NULL, 'proposed', jsonb_build_object('kind', 'design', 'record_version', v_version, 'state', 'proposed', 'claim', 'demonstration'), v_digest, p_actor, p_corr);
  PERFORM governance.ledger(p_tenant, p_domain, 'design_acceptance', p_acceptance, v_version, 'design.acceptance_proposed', p_actor,
            jsonb_build_object('digest', v_digest, 'baseline_version', b.version, 'obligations', to_jsonb(v_obl), 'valid_until', v_valid), p_corr);
  RETURN jsonb_build_object('acceptance_id', p_acceptance, 'version', v_version, 'state', 'proposed', 'digest', v_digest, 'valid_until', v_valid, 'obligations', to_jsonb(v_obl),
                            'builders', to_jsonb(coalesce(v_builders, '{}')), 'components', v_components, 'claim', 'demonstration');
END $$;
REVOKE ALL ON FUNCTION governance.dg_propose_acceptance(uuid, uuid, uuid, int, uuid, uuid[], jsonb, jsonb, jsonb, jsonb, text[], uuid[], uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_propose_acceptance(uuid, uuid, uuid, int, uuid, uuid[], jsonb, jsonb, jsonb, jsonb, text[], uuid[], uuid, uuid) TO eye_commit;

/* ATTEST one obligation of a proposed design acceptance version (human-gated; SIGNED executive.signatures `design_acceptance`): the obligation's
   role, a named active HUMAN, never the proposer, never a builder, never an agent; a DISTINCT human per obligation (one person never accepts
   two obligations — ES-71-002); on the exact digest; refused once any evidence item expired (`expired`) or a bound version moved on (`stale`).
   ACCEPTED when every obligation is signed (the prior accepted version superseded; the components linked `accepted_in`). */
CREATE OR REPLACE FUNCTION governance.dg_attest_acceptance(p_acceptance uuid, p_version int, p_tenant uuid, p_domain uuid, p_obligation text, p_digest text, p_reason text, p_signature uuid,
                                                          p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, observation, public, pg_catalog, pg_temp AS $$
DECLARE r governance.design_acceptances%ROWTYPE; v_att jsonb; v_done boolean; m jsonb; v_role text;
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.design.acceptance.attest']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'design acceptance rejected (actor): the act is recorded under the acting principal' USING ERRCODE = '42501'; END IF;
  SELECT * INTO r FROM governance.design_acceptances x WHERE x.acceptance_id = p_acceptance AND x.version = p_version AND x.tenant_id = p_tenant AND x.domain_id = p_domain FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'design acceptance rejected (unknown_acceptance): no design acceptance %/v% in this domain', p_acceptance, p_version USING ERRCODE = '23503'; END IF;
  IF p_obligation IS NULL OR NOT (p_obligation = ANY (r.obligations)) THEN
    RAISE EXCEPTION 'design acceptance rejected (obligation): % is not an obligation of this record (%)', coalesce(p_obligation, '<none>'), array_to_string(r.obligations, ', ') USING ERRCODE = '22023';
  END IF;
  PERFORM governance.assert_approver('design acceptance', p_actor, p_tenant, p_domain, governance.dg_obligation_roles(p_obligation), r.proposed_by, r.builders,
                                     format('attesting the %s obligation of a design acceptance', p_obligation));
  IF r.state <> 'proposed' THEN RAISE EXCEPTION 'design acceptance rejected (state): version % is %', p_version, r.state USING ERRCODE = '23505'; END IF;
  IF p_digest IS DISTINCT FROM r.digest THEN RAISE EXCEPTION 'design acceptance rejected (stale): the attestation names a digest other than version %''s', p_version USING ERRCODE = '23505'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 8 THEN RAISE EXCEPTION 'design acceptance rejected (reason): an attestation states its reason (8+ characters)' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(r.attestations) a WHERE a ->> 'obligation' = p_obligation) THEN
    RAISE EXCEPTION 'design acceptance rejected (duplicate): the % obligation is already attested', p_obligation USING ERRCODE = '23505';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(r.attestations) a WHERE (a ->> 'principal')::uuid = p_actor) THEN
    RAISE EXCEPTION 'design acceptance rejected (separation_of_duties): one person attests one obligation — a distinct named human per obligation (ES-71-002)' USING ERRCODE = '42501';
  END IF;
  IF r.valid_until <= clock_timestamp() OR EXISTS (SELECT 1 FROM jsonb_array_elements(r.evidence) e WHERE (e ->> 'validUntil')::timestamptz <= clock_timestamp()) THEN
    RAISE EXCEPTION 'design acceptance rejected (expired): bound evidence expired at % — propose the next version over renewed evidence', r.valid_until USING ERRCODE = '23505';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM governance.design_baselines b WHERE b.baseline_id = r.baseline_id AND b.version = r.baseline_version AND b.state = 'attested')
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(r.components) c WHERE NOT EXISTS (SELECT 1 FROM governance.design_assets a WHERE a.asset_id = (c ->> 'asset_id')::uuid AND a.version = (c ->> 'version')::int AND a.superseded_at IS NULL)) THEN
    RAISE EXCEPTION 'design acceptance rejected (stale): the bound baseline or a bound component version is no longer current' USING ERRCODE = '23505';
  END IF;
  IF p_signature IS NULL OR NOT EXISTS (SELECT 1 FROM executive.signatures s WHERE s.signature_id = p_signature AND s.subject_kind = 'design_acceptance' AND s.subject_id = p_acceptance
                                                 AND s.subject_version = p_version AND s.subject_digest = r.digest AND s.signer = p_actor AND s.bound_action = 'governance.design.acceptance.attest') THEN
    RAISE EXCEPTION 'design acceptance rejected (signature): an attestation carries the attester''s signature over the record''s digest' USING ERRCODE = '22023';
  END IF;
  v_role := (governance.dg_obligation_roles(p_obligation))[1];
  v_att := r.attestations || jsonb_build_object('obligation', p_obligation, 'principal', p_actor, 'role', v_role, 'signature_id', p_signature, 'reason', btrim(p_reason), 'at', clock_timestamp());
  v_done := (SELECT bool_and(EXISTS (SELECT 1 FROM jsonb_array_elements(v_att) a WHERE a ->> 'obligation' = o)) FROM unnest(r.obligations) o);
  IF v_done THEN
    UPDATE governance.design_acceptances SET state = 'superseded' WHERE acceptance_id = p_acceptance AND state IN ('accepted', 'withheld');
  END IF;
  UPDATE governance.design_acceptances SET attestations = v_att, state = CASE WHEN v_done THEN 'accepted' ELSE 'proposed' END, accepted_at = CASE WHEN v_done THEN clock_timestamp() END
   WHERE acceptance_id = p_acceptance AND version = p_version;
  IF v_done THEN
    PERFORM governance.dg_artifact(p_acceptance, 'acceptance_record', 'DAC:' || p_acceptance, format('Design acceptance: %s · %s (SYNTHETIC demonstration record)', r.tuple ->> 'capability', r.tuple ->> 'journey'),
                                   p_tenant, p_domain, NULL, NULL, 'active', jsonb_build_object('kind', 'design', 'record_version', p_version, 'state', 'accepted', 'claim', 'demonstration'), r.digest, p_actor, p_corr);
    FOR m IN SELECT x FROM jsonb_array_elements(r.components) x LOOP
      PERFORM governance.dg_link((m ->> 'asset_id')::uuid, p_acceptance, 'accepted_in', p_tenant, p_domain, jsonb_build_object('asset_version', m -> 'version', 'record_version', p_version), p_actor, p_corr);
    END LOOP;
    PERFORM executive.b33_close_items(p_tenant, p_domain, 'governance.acceptance', 'acceptance_record', p_acceptance, format('design acceptance v%s accepted by every obligation', p_version), p_actor, p_corr);
  END IF;
  PERFORM governance.ledger(p_tenant, p_domain, 'design_acceptance', p_acceptance, p_version, CASE WHEN v_done THEN 'design.acceptance_accepted' ELSE 'design.acceptance_attested' END, p_actor,
            jsonb_build_object('obligation', p_obligation, 'signature_id', p_signature, 'remaining', (SELECT to_jsonb(array_agg(o ORDER BY i)) FROM unnest(r.obligations) WITH ORDINALITY u(o, i)
                                                                                                         WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_att) a WHERE a ->> 'obligation' = u.o))), p_corr);
  RETURN jsonb_build_object('acceptance_id', p_acceptance, 'version', p_version, 'state', CASE WHEN v_done THEN 'accepted' ELSE 'proposed' END, 'attestations', v_att,
                            'remaining', (SELECT coalesce(to_jsonb(array_agg(u.o ORDER BY u.i)), '[]'::jsonb) FROM unnest(r.obligations) WITH ORDINALITY u(o, i)
                                         WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_att) a WHERE a ->> 'obligation' = u.o)),
                            'claim', 'demonstration');
END $$;
REVOKE ALL ON FUNCTION governance.dg_attest_acceptance(uuid, int, uuid, uuid, text, text, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_attest_acceptance(uuid, int, uuid, uuid, text, text, text, uuid, uuid, uuid) TO eye_commit;

/* THE SWEEP (the attention tick's step, executive.attention.tick; DOMAIN): an ACCEPTED design acceptance whose evidence expired, whose window
   ended, whose baseline version is no longer the attested one or whose bound component version moved on is WITHHELD (conformance withheld;
   what was accepted is kept and shown — the prior accepted baseline preserved; only a new version over renewed evidence accepts again) and
   raises `governance.acceptance` attention. Nothing withheld → nothing written. */
CREATE OR REPLACE FUNCTION governance.dg_sweep_acceptances(p_tenant uuid, p_domain uuid, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, executive, observation, public, pg_catalog, pg_temp AS $$
DECLARE r governance.design_acceptances%ROWTYPE; v_reasons jsonb; v_out jsonb := '[]'::jsonb; v_event uuid; v_item jsonb; v_checked int := 0;
BEGIN
  PERFORM observation.assert_authority(ARRAY['executive.attention.tick']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  FOR r IN SELECT * FROM governance.design_acceptances x WHERE x.tenant_id = p_tenant AND x.domain_id = p_domain AND x.state = 'accepted' ORDER BY x.acceptance_id FOR UPDATE LOOP
    v_checked := v_checked + 1;
    SELECT coalesce(jsonb_agg(y), '[]'::jsonb) INTO v_reasons FROM (
      SELECT format('evidence %s expired at %s', e ->> 'ref', e ->> 'validUntil') AS y FROM jsonb_array_elements(r.evidence) e WHERE (e ->> 'validUntil')::timestamptz <= clock_timestamp()
      UNION ALL SELECT format('the acceptance window ended at %s', r.valid_until) WHERE r.valid_until <= clock_timestamp()
        AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r.evidence) e WHERE (e ->> 'validUntil')::timestamptz <= clock_timestamp())
      UNION ALL SELECT format('design baseline v%s is no longer the attested version', r.baseline_version)
       WHERE NOT EXISTS (SELECT 1 FROM governance.design_baselines b WHERE b.baseline_id = r.baseline_id AND b.version = r.baseline_version AND b.state = 'attested')
      UNION ALL SELECT format('%s v%s was superseded', c ->> 'key', c ->> 'version') FROM jsonb_array_elements(r.components) c
       WHERE NOT EXISTS (SELECT 1 FROM governance.design_assets a WHERE a.asset_id = (c ->> 'asset_id')::uuid AND a.version = (c ->> 'version')::int AND a.superseded_at IS NULL)) q;
    CONTINUE WHEN jsonb_array_length(v_reasons) = 0;
    UPDATE governance.design_acceptances SET state = 'withheld', withheld_at = clock_timestamp(),
           withheld_reason = left('conformance withheld: ' || (SELECT string_agg(z, '; ') FROM jsonb_array_elements_text(v_reasons) z), 2000)
     WHERE acceptance_id = r.acceptance_id AND version = r.version;
    v_event := governance.ledger(p_tenant, p_domain, 'design_acceptance', r.acceptance_id, r.version, 'design.acceptance_withheld', p_actor, jsonb_build_object('reasons', v_reasons), p_corr);
    PERFORM governance.dg_artifact(r.acceptance_id, 'acceptance_record', 'DAC:' || r.acceptance_id, format('Design acceptance: %s · %s (SYNTHETIC demonstration record)', r.tuple ->> 'capability', r.tuple ->> 'journey'),
                                   p_tenant, p_domain, NULL, NULL, 'quarantined', jsonb_build_object('kind', 'design', 'record_version', r.version, 'state', 'withheld', 'claim', 'demonstration'), r.digest, p_actor, p_corr);
    v_item := executive.b33_raise_routed(p_tenant, p_domain, 'governance.acceptance', 'acceptance_record', r.acceptance_id,
                left(format('Design acceptance withheld: %s · %s — %s', r.tuple ->> 'capability', r.tuple ->> 'journey', v_reasons ->> 0), 500), v_reasons, r.proposed_by, v_event,
                'design_acceptance.withheld', jsonb_build_object('record_version', r.version, 'part', 'dg'), NULL, p_actor, p_corr);
    v_out := v_out || jsonb_build_object('acceptance_id', r.acceptance_id, 'version', r.version, 'reasons', v_reasons, 'item', v_item);
  END LOOP;
  RETURN jsonb_build_object('checked', v_checked, 'withheld', v_out);
END $$;
REVOKE ALL ON FUNCTION governance.dg_sweep_acceptances(uuid, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_sweep_acceptances(uuid, uuid, uuid, uuid) TO eye_commit;

-- §DG.12 B92's TELEMETRY GOVERNANCE AS EVIDENCE (REL-23) AND THE INDEPENDENT CONFORMANCE PACKAGE (UX-70-006, UX-66-006) ─────────────────────
/* REL-23 — the domain's telemetry governance, bound by reference as design evidence: purpose (the approved purposes and their privacy-officer
   decisions), consent (current grants / withdrawals per purpose — counts only), lineage (each approved event definition → journey step →
   purpose), coverage (journey steps with an approved definition), privacy review (who decided, when), metric governance (the metric
   definitions by state; MET-034's own row says `unsupported`). Each item: kind, id, digest, captured_at. A guarded definer read (N-01). */
CREATE OR REPLACE FUNCTION governance.dg_telemetry_evidence(p_tenant uuid, p_domain uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = governance, analytics, observation, pg_catalog, pg_temp AS $$
BEGIN
  PERFORM observation.assert_read_scope(p_tenant, p_domain, 'the telemetry governance evidence');
  RETURN jsonb_build_object(
    'purposes', coalesce((SELECT jsonb_agg(jsonb_build_object('kind', 'telemetry_purpose', 'id', p.purpose_id, 'key', p.purpose_key, 'version', p.version, 'purpose_kind', p.purpose_kind,
        'retention_days', p.retention_days, 'state', p.state, 'privacy_review', jsonb_build_object('decided_by', p.decided_by, 'decided_at', p.decided_at), 'digest', p.digest, 'captured_at', p.decided_at)
        ORDER BY p.purpose_key, p.version) FROM analytics.purposes p WHERE p.tenant_id = p_tenant AND p.domain_id = p_domain AND p.state IN ('approved', 'retired')), '[]'::jsonb),
    'consent', coalesce((SELECT jsonb_agg(jsonb_build_object('purpose_key', q.purpose_key, 'granted', q.granted, 'withdrawn', q.withdrawn) ORDER BY q.purpose_key) FROM (
        SELECT l.purpose_key, count(*) FILTER (WHERE l.decision = 'granted') AS granted, count(*) FILTER (WHERE l.decision = 'withdrawn') AS withdrawn
          FROM (SELECT DISTINCT ON (c.principal_id, c.purpose_key) c.purpose_key, c.decision FROM analytics.consents c WHERE c.tenant_id = p_tenant AND c.domain_id = p_domain
                 ORDER BY c.principal_id, c.purpose_key, c.recorded_at DESC) l GROUP BY l.purpose_key) q), '[]'::jsonb),
    'lineage', coalesce((SELECT jsonb_agg(jsonb_build_object('kind', 'telemetry_definition', 'id', d.definition_id, 'event_key', d.event_key, 'version', d.version, 'journey_key', d.journey_key,
        'step_key', d.step_key, 'purpose_key', d.purpose_key, 'retention_days', d.retention_days, 'collection', d.collection, 'privacy_review', jsonb_build_object('decided_by', d.decided_by, 'decided_at', d.decided_at),
        'digest', d.digest, 'captured_at', d.decided_at) ORDER BY d.event_key) FROM analytics.telemetry_definitions d WHERE d.tenant_id = p_tenant AND d.domain_id = p_domain AND d.state = 'approved'), '[]'::jsonb),
    'coverage', coalesce((SELECT jsonb_agg(jsonb_build_object('journey_key', j.journey_key, 'version', j.version,
        'steps', coalesce(cardinality(j.steps), 0),
        'steps_instrumented', (SELECT count(DISTINCT d.step_key) FROM analytics.telemetry_definitions d WHERE d.tenant_id = p_tenant AND d.domain_id = p_domain AND d.state = 'approved' AND d.journey_key = j.journey_key))
        ORDER BY j.journey_key) FROM analytics.experience_journeys j WHERE j.tenant_id = p_tenant AND j.domain_id = p_domain AND j.state = 'active'), '[]'::jsonb),
    'metric_governance', jsonb_build_object(
        'by_state', coalesce((SELECT jsonb_object_agg(s.state, s.n) FROM (SELECT m.state, count(*) AS n FROM analytics.metric_definitions m WHERE m.tenant_id = p_tenant AND m.domain_id = p_domain GROUP BY m.state) s), '{}'::jsonb),
        'met_034', (SELECT jsonb_build_object('metric_key', m.metric_key, 'version', m.version, 'state', m.state, 'supported', m.supported, 'unsupported_reason', m.unsupported_reason, 'digest', m.digest)
                      FROM analytics.metric_definitions m WHERE m.tenant_id = p_tenant AND m.domain_id = p_domain AND m.metric_key = 'MET-034' ORDER BY m.version DESC LIMIT 1)),
    'experience', jsonb_build_object(
        'findings', (SELECT count(*) FROM analytics.experience_findings f WHERE f.tenant_id = p_tenant AND f.domain_id = p_domain),
        'actions', coalesce((SELECT jsonb_agg(jsonb_build_object('kind', 'experience_action', 'id', a.action_id, 'action_kind', a.kind, 'decision', a.decision, 'digest', a.preview_digest, 'captured_at', a.decided_at)
                              ORDER BY a.decided_at) FROM analytics.experience_actions a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain), '[]'::jsonb)),
    'read_at', clock_timestamp());
END $$;
REVOKE ALL ON FUNCTION governance.dg_telemetry_evidence(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_telemetry_evidence(uuid, uuid) TO eye_app, eye_commit;

/* An evidence item with its AGE (days since captured, on the database clock). */
CREATE OR REPLACE FUNCTION governance.dg_aged(p_kind text, p_id uuid, p_digest text, p_captured timestamptz, p_extra jsonb) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT jsonb_build_object('kind', p_kind, 'id', p_id, 'digest', p_digest, 'captured_at', p_captured,
                            'age_days', CASE WHEN p_captured IS NULL THEN NULL ELSE round((extract(epoch FROM clock_timestamp() - p_captured) / 86400)::numeric, 1) END) || coalesce(p_extra, '{}'::jsonb)
$$;
REVOKE ALL ON FUNCTION governance.dg_aged(text, uuid, text, timestamptz, jsonb) FROM PUBLIC;

/* GENERATE the INDEPENDENT CONFORMANCE PACKAGE (the conformance steward, independent assurance, the tenant's auditor; DOMAIN): for UX-70-006
   (B92's experience-quality workflow: telemetry governance, journeys, findings and their actions) or UX-66-006 (B94's onboarding and
   migration: acceptances, the go-live decision, admission records, value reviews) — the EXACT design tuple (a design acceptance record's,
   or the attested baseline's), the evidence by reference with its AGE, and the FINDINGS (open lint findings, expired evidence, unattested
   obligations, withheld acceptance, open and expired design exceptions, orphans and contradictions, MET-034 unsupported). Digested and kept;
   LEFT UNSIGNED — the signed acceptance by named independent authorities is R2's, outside the product. */
CREATE OR REPLACE FUNCTION governance.dg_generate_package(p_package uuid, p_tenant uuid, p_domain uuid, p_target text, p_acceptance uuid, p_actor uuid, p_corr uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = governance, analytics, onboarding, implementation, service, observation, public, pg_catalog, pg_temp AS $$
DECLARE r governance.design_acceptances%ROWTYPE; b governance.design_baselines%ROWTYPE; v_tuple jsonb; v_evidence jsonb := '[]'::jsonb; v_findings jsonb := '[]'::jsonb; v_content jsonb; v_digest text;
        v_tel jsonb; e governance.design_evaluations%ROWTYPE; o jsonb; x jsonb;
BEGIN
  PERFORM observation.assert_authority(ARRAY['governance.design.package.generate']);
  PERFORM observation.assert_scope(p_tenant, p_domain);
  IF p_actor IS NULL OR p_actor IS DISTINCT FROM public.eye_principal() THEN RAISE EXCEPTION 'conformance package rejected (actor): the act is recorded under the acting principal' USING ERRCODE = '42501'; END IF;
  IF coalesce(p_target, '') NOT IN ('UX-70-006', 'UX-66-006') THEN RAISE EXCEPTION 'conformance package rejected (target): the package is for UX-70-006 or UX-66-006' USING ERRCODE = '22023'; END IF;
  IF p_acceptance IS NOT NULL THEN
    SELECT * INTO r FROM governance.design_acceptances a WHERE a.acceptance_id = p_acceptance AND a.tenant_id = p_tenant AND a.domain_id = p_domain ORDER BY a.version DESC LIMIT 1;
    IF NOT FOUND THEN RAISE EXCEPTION 'conformance package rejected (unknown_acceptance): % is not a design acceptance record of this domain', p_acceptance USING ERRCODE = '23503'; END IF;
    SELECT * INTO b FROM governance.design_baselines x WHERE x.baseline_id = r.baseline_id AND x.version = r.baseline_version;
  ELSE
    SELECT * INTO b FROM governance.design_baselines x WHERE x.state = 'attested' ORDER BY x.decided_at DESC LIMIT 1;
  END IF;
  v_tuple := jsonb_build_object('tenant_id', p_tenant, 'domain_id', p_domain,
    'design_system', CASE WHEN b.baseline_id IS NULL THEN NULL ELSE jsonb_build_object('baseline_id', b.baseline_id, 'version', b.version, 'digest', b.digest, 'state', b.state,
                                                                                        'design_system_version', b.design_system_version, 'conformance_scope', b.conformance_scope) END,
    'components', CASE WHEN r.acceptance_id IS NOT NULL THEN r.components ELSE coalesce(b.members, '[]'::jsonb) END,
    'scope', CASE WHEN r.acceptance_id IS NOT NULL THEN r.tuple ELSE NULL END,
    'acceptance', CASE WHEN r.acceptance_id IS NULL THEN NULL ELSE jsonb_build_object('acceptance_id', r.acceptance_id, 'version', r.version, 'state', r.state, 'digest', r.digest,
                                                                                        'obligations', to_jsonb(r.obligations), 'attestations', r.attestations, 'valid_until', r.valid_until, 'claim', r.claim) END);
  IF b.baseline_id IS NULL THEN v_findings := v_findings || jsonb_build_object('class', 'no_baseline', 'finding', 'no attested design baseline — the design tuple is incomplete'); END IF;
  -- the record's own evidence, with ages
  IF r.acceptance_id IS NOT NULL THEN
    FOR x IN SELECT y FROM jsonb_array_elements(r.evidence) y LOOP
      v_evidence := v_evidence || governance.dg_aged(x ->> 'kind', NULL, x ->> 'digest', (x ->> 'capturedAt')::timestamptz,
                                                     jsonb_build_object('ref', x ->> 'ref', 'valid_until', x ->> 'validUntil', 'expired', (x ->> 'validUntil')::timestamptz <= clock_timestamp(), 'source', 'design acceptance'));
      IF (x ->> 'validUntil')::timestamptz <= clock_timestamp() THEN v_findings := v_findings || jsonb_build_object('class', 'evidence_expired', 'finding', format('%s expired at %s', x ->> 'ref', x ->> 'validUntil')); END IF;
    END LOOP;
    IF r.state <> 'accepted' THEN
      v_findings := v_findings || jsonb_build_object('class', 'acceptance_' || r.state, 'finding', format('the design acceptance v%s is %s%s', r.version, r.state, coalesce(' — ' || r.withheld_reason, '')));
    END IF;
    FOR x IN SELECT to_jsonb(u.ob) FROM unnest(r.obligations) u(ob) WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(r.attestations) a WHERE a ->> 'obligation' = u.ob) LOOP
      v_findings := v_findings || jsonb_build_object('class', 'obligation_unattested', 'finding', format('the %s obligation is not attested', x #>> '{}'));
    END LOOP;
  ELSE
    v_findings := v_findings || jsonb_build_object('class', 'no_acceptance', 'finding', 'no design acceptance record is bound — the package carries the attested baseline only');
  END IF;
  IF p_target = 'UX-70-006' THEN
    v_tel := governance.dg_telemetry_evidence(p_tenant, p_domain);
    FOR x IN SELECT y FROM jsonb_array_elements(v_tel -> 'purposes') y LOOP
      v_evidence := v_evidence || governance.dg_aged('telemetry_purpose', (x ->> 'id')::uuid, x ->> 'digest', (x ->> 'captured_at')::timestamptz, jsonb_build_object('key', x ->> 'key', 'state', x ->> 'state', 'source', 'B92'));
    END LOOP;
    FOR x IN SELECT y FROM jsonb_array_elements(v_tel -> 'lineage') y LOOP
      v_evidence := v_evidence || governance.dg_aged('telemetry_definition', (x ->> 'id')::uuid, x ->> 'digest', (x ->> 'captured_at')::timestamptz, jsonb_build_object('event_key', x ->> 'event_key', 'journey_key', x ->> 'journey_key', 'source', 'B92'));
    END LOOP;
    FOR x IN SELECT y FROM jsonb_array_elements(v_tel -> 'experience' -> 'actions') y LOOP
      v_evidence := v_evidence || governance.dg_aged('experience_action', (x ->> 'id')::uuid, x ->> 'digest', (x ->> 'captured_at')::timestamptz, jsonb_build_object('action_kind', x ->> 'action_kind', 'source', 'B92'));
    END LOOP;
    IF jsonb_array_length(v_tel -> 'purposes') = 0 THEN v_findings := v_findings || jsonb_build_object('class', 'telemetry_ungoverned', 'finding', 'no approved telemetry purpose in this domain'); END IF;
  ELSE
    FOR x IN SELECT governance.dg_aged('migration_acceptance', a.acceptance_id, a.digest, a.decided_at, jsonb_build_object('decision', a.decision, 'claim', a.claim, 'signature_id', a.signature_id, 'source', 'B94 §MG'))
               FROM onboarding.migration_acceptances a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain ORDER BY a.decided_at LOOP
      v_evidence := v_evidence || x;
    END LOOP;
    FOR x IN SELECT governance.dg_aged('golive_decision', g.decision_id, g.digest, g.decided_at, jsonb_build_object('decision', g.decision, 'role', g.decided_role, 'claim', g.claim, 'signature_id', g.signature_id, 'source', 'B94 §IM'))
               FROM implementation.golive_decisions g WHERE g.tenant_id = p_tenant AND g.domain_id = p_domain ORDER BY g.decided_at LOOP
      v_evidence := v_evidence || x;
    END LOOP;
    FOR x IN SELECT governance.dg_aged('admission_record', s.admission_id, s.digest, coalesce(s.decided_at, s.proposed_at), jsonb_build_object('version', s.version, 'state', s.state, 'production_admission', s.production_admission, 'source', 'B94 §SA'))
               FROM service.admission_records s WHERE s.tenant_id = p_tenant AND s.domain_id = p_domain ORDER BY s.proposed_at LOOP
      v_evidence := v_evidence || x;
    END LOOP;
    FOR x IN SELECT governance.dg_aged('value_review', v.review_id, v.digest, coalesce(v.decided_at, v.recorded_at), jsonb_build_object('state', v.state, 'value_status', v.value_status, 'claim', v.claim, 'source', 'B94 §SV'))
               FROM service.value_reviews v WHERE v.tenant_id = p_tenant AND v.domain_id = p_domain ORDER BY v.recorded_at LOOP
      v_evidence := v_evidence || x;
    END LOOP;
    IF NOT EXISTS (SELECT 1 FROM onboarding.migration_acceptances a WHERE a.tenant_id = p_tenant AND a.domain_id = p_domain AND a.decision = 'accepted') THEN
      v_findings := v_findings || jsonb_build_object('class', 'onboarding_unaccepted', 'finding', 'no accepted migration wave in this domain');
    END IF;
  END IF;
  SELECT * INTO e FROM governance.design_evaluations x1 WHERE x1.source = 'lint' ORDER BY x1.evaluated_at DESC LIMIT 1;
  IF e.evaluation_id IS NULL THEN v_findings := v_findings || jsonb_build_object('class', 'unevaluated', 'finding', 'the web source was not evaluated against the principles');
  ELSE
    v_evidence := v_evidence || governance.dg_aged('design_evaluation', e.evaluation_id, e.digest, e.evaluated_at, jsonb_build_object('verdict', e.verdict, 'counts', e.counts, 'source', 'B107 §DG'));
    FOR x IN SELECT y FROM jsonb_array_elements(e.findings) y WHERE y ->> 'status' = 'open' LIMIT 50 LOOP
      v_findings := v_findings || jsonb_build_object('class', 'lint_open', 'finding', format('%s: %s:%s %s', x ->> 'principle', x ->> 'file', x ->> 'line', x ->> 'excerpt'));
    END LOOP;
  END IF;
  FOR x IN SELECT jsonb_build_object('class', CASE WHEN d.expires_at <= clock_timestamp() THEN 'exception_expired' ELSE 'exception_open' END,
                                     'finding', format('design exception on %s for %s %s %s', d.asset_id, d.principle_key, CASE WHEN d.expires_at <= clock_timestamp() THEN 'expired at' ELSE 'expires' END, d.expires_at))
             FROM governance.design_exceptions d WHERE d.state = 'approved' ORDER BY d.expires_at LOOP
    v_findings := v_findings || x;
  END LOOP;
  o := governance.dg_orphans();
  IF jsonb_array_length(o -> 'assets_without_requirement') + jsonb_array_length(o -> 'assets_without_owner') + jsonb_array_length(o -> 'requirements_without_design') + jsonb_array_length(o -> 'contradictions') > 0 THEN
    v_findings := v_findings || jsonb_build_object('class', 'trace', 'finding', format('%s asset(s) without a requirement, %s without an owner, %s design requirement(s) without a design artifact, %s contradiction(s)',
                    jsonb_array_length(o -> 'assets_without_requirement'), jsonb_array_length(o -> 'assets_without_owner'), jsonb_array_length(o -> 'requirements_without_design'), jsonb_array_length(o -> 'contradictions')));
  END IF;
  v_findings := v_findings || jsonb_build_object('class', 'accessibility_unsupported', 'finding', 'MET-034 is unsupported: no accessibility journey results exist (B108 is the source, H3 the verification) — the accessibility slots are empty');
  v_content := jsonb_build_object('target', p_target, 'tuple', v_tuple, 'evidence', v_evidence, 'findings', v_findings, 'accessibility', governance.dg_accessibility_slots(),
                                  'unsigned', true, 'signature_required', 'R2: the named independent authorities review and sign this package outside the product; nothing here signs it',
                                  'claims', jsonb_build_object('construction', 'the generator and its harness', 'demonstrated_operation', 'every record here is SYNTHETIC (claim = demonstration)',
                                                               'real_acceptance', 'not claimed — R2 / H3'),
                                  'generated_at', clock_timestamp());
  v_digest := governance.digest(v_content);
  INSERT INTO governance.design_conformance_packages (package_id, tenant_id, domain_id, target, acceptance_id, acceptance_version, content, digest, generated_by, generated_by_kind, correlation_id)
  VALUES (p_package, p_tenant, p_domain, p_target, r.acceptance_id, r.version, v_content, v_digest, p_actor, coalesce(governance.dg_kind(p_actor), 'system'), p_corr);
  PERFORM governance.dg_artifact(p_package, 'evidence', 'DCP:' || p_package, format('Independent conformance package for %s (UNSIGNED — R2)', p_target), p_tenant, p_domain, NULL, NULL, 'active',
                                 jsonb_build_object('class', 'conformance_package', 'target', p_target, 'unsigned', true), v_digest, p_actor, p_corr);
  IF r.acceptance_id IS NOT NULL THEN PERFORM governance.dg_link(p_package, r.acceptance_id, 'evidences', p_tenant, p_domain, jsonb_build_object('record_version', r.version), p_actor, p_corr); END IF;
  PERFORM governance.ledger(p_tenant, p_domain, 'conformance_package', p_package, NULL, 'design.package_generated', p_actor,
            jsonb_build_object('target', p_target, 'digest', v_digest, 'evidence', jsonb_array_length(v_evidence), 'findings', jsonb_array_length(v_findings), 'unsigned', true), p_corr);
  RETURN jsonb_build_object('package_id', p_package, 'target', p_target, 'digest', v_digest, 'signed', false, 'content', v_content);
END $$;
REVOKE ALL ON FUNCTION governance.dg_generate_package(uuid, uuid, uuid, text, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_generate_package(uuid, uuid, uuid, text, uuid, uuid, uuid) TO eye_commit;

-- §DG.13 THE SEED's artifacts (the V9 principles registered in the shared core; the zero id recorded them) ────────────────────────────────
INSERT INTO governance.artifacts (artifact_id, version, scope, kind, external_key, title, owner_role, authority_class, controlling_volume, lifecycle, attributes, source, digest, recorded_by, correlation_id)
SELECT p.principle_id, 1, 'PLATFORM', 'principle', 'DP:' || p.principle_key, left(p.statement, 300), 'design_system_authority', 'normative (V9)', 'V9', 'active',
       jsonb_build_object('kind', p.kind, 'unwaivable', p.unwaivable, 'lint_rule', p.lint_rule, 'principle_version', 1), jsonb_build_object('part', 'dg', 'migration', '0115 §DG', 'seeded', true),
       p.digest, '00000000-0000-0000-0000-000000000000'::uuid, p.correlation_id
  FROM governance.design_principles p WHERE p.version = 1;

-- §DG.14 THE READS' GRANTS: the blockers read PLATFORM rows only (the vendor's design system) — the workspace explains a hold before the act.
GRANT EXECUTE ON FUNCTION governance.dg_contribution_blockers(governance.design_contributions) TO eye_app, eye_commit;
GRANT EXECUTE ON FUNCTION governance.dg_baseline_blockers(uuid, int) TO eye_app, eye_commit;

/* A principal's display name for the design-governance pages: a vendor governance authority (PLATFORM, holding a B107 role) or a principal of
   the caller's own tenant — never another tenant's (a DOMAIN context cannot read a PLATFORM-homed principal under identity's RLS). */
CREATE OR REPLACE FUNCTION governance.dg_principal_name(p_principal uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = identity, public, pg_catalog, pg_temp AS $$
  SELECT p.display_name FROM identity.principals p
   WHERE p.id = p_principal
     AND ((p.scope = 'PLATFORM' AND EXISTS (SELECT 1 FROM identity.role_bindings b WHERE b.principal_id = p.id AND b.scope = 'PLATFORM' AND b.revoked_at IS NULL
                                              AND b.role_code IN ('product_authority', 'design_system_authority', 'independent_assurance', 'operations_authority', 'conformance_steward')))
          OR (p.tenant_id IS NOT NULL AND p.tenant_id = public.eye_tenant()) OR public.eye_scope() = 'PLATFORM')
$$;
REVOKE ALL ON FUNCTION governance.dg_principal_name(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION governance.dg_principal_name(uuid) TO eye_app, eye_commit;
